(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]=m["moe"]||{};d["theory"]=[{"id":"th-roofline-moe-decode","title":"MoE解码Roofline界","direction":"dir-moe-routing-capacity","prereq":[],"plain":"MoE解码每token只激活少数专家，算术强度被压到极低，性能几乎完全由权重字节数与HBM带宽之比决定，算力峰值反而闲置。","definition":"MoE解码每token只激活少数专家，算术强度被压到极低，性能几乎完全由权重字节数与HBM带宽之比决定，算力峰值反而闲置。","formula":"$$T_{\\text{tok}}=\\max\\!\\left(\\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}},\\ \\frac{2\\,N_{\\text{act}}\\,d}{F_{\\text{peak}}}\\right)\\approx\\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}},\\qquad B_{\\text{act}}=b_w\\!\\left(N_{\\text{shared}}+k\\,N_{e}\\right)$$","variables":[{"sym":"B_{\\text{act}}","meaning":"单token激活权重字节数（含共享专家与k个路由专家）"},{"sym":"\\mathrm{BW}_{\\text{HBM}}","meaning":"HBM有效带宽（B200约8 TB/s，扣除实测效率）"},{"sym":"b_w","meaning":"权重位宽对应的字节数（NVFP4为0.5，FP8为1）"},{"sym":"k","meaning":"每token路由专家数top-k"},{"sym":"F_{\\text{peak}}","meaning":"峰值算力（FP4/FP8 dense TFLOPS）"}],"derivation":"推导关键一步：把每token的浮点运算量除以峰值算力得到算力项$$2N_{\\text{act}}d/F_{\\text{peak}}$$，与带宽项取max；因激活参数少、d有限，带宽项通常远大于算力项，故近似取带宽项。","example":"用途：用于判断某MoE模型在给定HBM带宽下的解码TPOT下界，决定是否需要提高批大小摊薄权重读取、是否值得用NVFP4把$$b_w$$从1降到0.5以近似翻倍吞吐。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["批内token共享专家权重时，实际字节数按批摊薄，公式需改为 B_act/B 才成立","当批很大、算术强度越过拐点后，瓶颈转为tensor core算力与tcgen05利用率，带宽项不再主导"],"system_note":"误用：直接用峰值算力估算解码时延而忽略带宽项，会低估TPOT数倍；反之在小批下用摊薄后的$$B_{\\text{act}}/B$$估算，会高估吞吐并导致SLO违约。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：MoE解码每token只激活少数专家，算术强度被压到极低，单token耗时几乎完全由激活权重字节数与HBM带宽之比决定，算力峰值大量闲置。","公式中$$B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)$$表示单token激活权重字节数，含共享专家与k个路由专家；$$\\mathrm{BW}_{\\text{HBM}}$$为有效带宽，B200约8 TB/s但需扣除实测效率。","推导关键一步：把每token的浮点运算量除以峰值算力得到算力项$$2N_{\\text{act}}d/F_{\\text{peak}}$$，与带宽项取max；因激活参数少、d有限，带宽项通常远大于算力项，故近似取带宽项。","适用边界：批内token共享专家权重时，实际读取字节按批摊薄，公式须改为$$B_{\\text{act}}/B$$；批很大、算术强度越过拐点后瓶颈转为tensor core算力与tcgen05利用率，带宽项不再主导。","用途：用于判断某MoE模型在给定HBM带宽下的解码TPOT下界，决定是否需要提高批大小摊薄权重读取、是否值得用NVFP4把$$b_w$$从1降到0.5以近似翻倍吞吐。","误用：直接用峰值算力估算解码时延而忽略带宽项，会低估TPOT数倍；反之在小批下用摊薄后的$$B_{\\text{act}}/B$$估算，会高估吞吐并导致SLO违约。"],"anchors":["B200约8 TB/s","NVFP4为0.5","FP8为1"],"pitfalls":["把训练阶段的算力受限roofline直接套到解码，忽略权重读取主导，容量规划偏乐观。","跨节点专家并行时未把All-to-All时延计入，纯HBM带宽模型低估实际TPOT。","小批解码时误用摊薄字节数$$B_{\\text{act}}/B$$，高估吞吐导致SLO无法兑现。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-1\">一 · 一句话直觉：解码时算力是闲的，带宽是紧的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-2\">二 · 严格定义：界的形式与每一项的含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-3\">三 · 为什么需要这个界：三个决策都要它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-4\">四 · 常见误解：四个必须纠正的用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-5\">五 · 一个具体例子：把界算到数字上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-6\">六 · 界的边界条件与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-7\">七 · 边界在哪里：摊薄、拐点与跨节点时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-8\">八 · 带宽项的物理含义与 \\(B_{\\text{act}}\\) 的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-9\">九 · 算力项的推导：从FLOPs到 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\)</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-10\">十 · 离散化与近似发生在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-11\">十一 · 适用边界与误用方向的代价对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-12\">十二 · 公式作为决策工具：三个可执行的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-13\">十三 · 从公式到实现：字节记账如何落到kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-14\">十四 · 边界一：批内权重摊薄何时生效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-15\">十五 · 边界二：算术强度越过拐点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-16\">十六 · 边界三：跨节点专家并行的通信项缺席</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-17\">十七 · 边界四：权重位宽与有效带宽的实测折扣</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-18\">十八 · 规模上限：公式在什么规模上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-19\">十九 · 带宽项成立的前提与三个断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-20\">二十 · 从TPOT下界反解批大小B</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-21\">二十一 · 用拐点定并行度：TP与EP的分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-22\">二十二 · 定KV预算：批与上下文的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-23\">二十三 · 定SLO：把界写成预算表而非单点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-24\">二十四 · 算例：一次完整的容量决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-25\">二十五 · 把 roofline 变成容量决策：批大小、并行度、KV 预算与 SLO 的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-26\">二十六 · 误用一：用峰值算力当解码时延的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-27\">二十七 · 误用二：小批下套用摊薄字节数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-28\">二十八 · 误用三：跨节点专家并行漏算 All-to-All</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-29\">二十九 · 一个反例：从「算力富余」推到「加批无损」</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-30\">三十 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-31\">三十一 · 误用与反例：roofline 在什么条件下会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-moe-decode-sec-32\">三十二 · 带宽项被当成常数：三种把 roofline 用反的现场</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:550px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550.4 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：MoE解码每token只激活少数专家，算术强度被压到极低，性能几乎…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{tok}}=\\max\\!\\left(\\fra…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"468.4\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：批内token共享专家权重时，实际字节数按批摊薄，公式需改为 B_…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-roofline-moe-decode-sec-1\">一 · 一句话直觉：解码时算力是闲的，带宽是紧的</h3>\n<p>把 MoE 解码想象成一次“按需取书”：每个 token 只从书架（HBM）上抽出少数几本专家权重（共享专家加 top-k 路由专家），翻几页就算完了。计算量小到 tensor core 大量空转，真正花时间的是把这几本书从显存搬到 SM 的过程。于是单 token 耗时几乎完全由“这一 token 需要读多少权重字节”除以“HBM 每秒能搬多少字节”决定，算力峰值反而闲置。这就是 MoE 解码 roofline 界的一句话直觉：<strong>解码是权重读取受限，不是算力受限</strong>。</p>\n<p>这个直觉之所以成立，是因为 MoE 把“激活参数”压得极低。dense 模型每个 token 都要过全部权重，算术强度随批大小迅速爬升；MoE 每 token 只走 k 个专家，权重读取量随激活专家数线性缩小，而 FLOPs 缩得更快，算术强度被压到远低于 roofline 拐点的位置。在 roofline 图上，MoE 解码的点落在带宽斜线的左下角，离算力平台很远——这不是调优问题，是结构性的位置。</p>\n<p>工程上要立刻抓住的代价是：<strong>TPOT 的下界由带宽项给出，而不是由 FLOPS 给出</strong>。B200 的 HBM 有效带宽约 8 TB/s（需扣除实测效率），这个数字就是解码时延的分母。任何“用峰值算力估解码时延”的容量规划都会系统性偏乐观，因为分子根本不是算力。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-2\">二 · 严格定义：界的形式与每一项的含义</h3>\n<p>把单 token 时延写成两个候选瓶颈取大：</p>\n<div class=\"formula\">$$T_{\\text{tok}}=\\max\\!\\left(\\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}},\\ \\frac{2\\,N_{\\text{act}}\\,d}{F_{\\text{peak}}}\\right)\\approx\\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}},\\qquad B_{\\text{act}}=b_w\\!\\left(N_{\\text{shared}}+k\\,N_{e}\\right)$$</div>\n<p>逐项定义清楚，避免含混：</p>\n<ul>\n<li><span class=\"sym\">\\(B_{\\text{act}}\\)</span>：单 token 激活权重字节数，含共享专家与 k 个路由专家。它是“这一 token 必须从 HBM 读进来的全部权重”，不是模型总参数量，也不是单专家大小。</li>\n<li><span class=\"sym\">\\(\\mathrm{BW}_{\\text{HBM}}\\)</span>：HBM 有效带宽，B200 约 8 TB/s，但必须扣除实测效率——峰值带宽是理论值，实际可持续读取低于它，界里用的是有效值。</li>\n<li><span class=\"sym\">\\(b_w\\)</span>：权重位宽对应的字节数，NVFP4 为 0.5，FP8 为 1。它直接把精度选择翻译成字节数，是量化收益进入 roofline 的唯一入口。</li>\n<li><span class=\"sym\">\\(k\\)</span>：每 token 路由专家数 top-k；<span class=\"sym\">\\(N_e\\)</span> 为单专家参数量，<span class=\"sym\">\\(N_{\\text{shared}}\\)</span> 为共享专家参数量。</li>\n<li><span class=\"sym\">\\(F_{\\text{peak}}\\)</span>：峰值算力（FP4/FP8 dense TFLOPS），只出现在算力项里。</li>\n</ul>\n<p>推导的关键一步是把每 token 的浮点运算量除以峰值算力，得到算力项 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\)，再与带宽项取 max。因为激活参数少、d 有限，带宽项通常远大于算力项，所以近似取带宽项。注意 \\(B_{\\text{act}}\\) 里的 \\(N_{\\text{shared}}\\) 不能漏：共享专家对所有 token 生效，是每 token 必读的固定开销，在小 k 模型里它甚至可能占主导。</p>\n<p>这个定义给出的是<strong>下界</strong>，不是预测值。它假设权重读取完全流水、无冗余、无跨节点通信，因此真实 TPOT 只会更差。把它当“理论地板”用，才能判断优化空间还剩多少。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-3\">三 · 为什么需要这个界：三个决策都要它</h3>\n<p>第一个决策是<strong>批大小</strong>。界告诉我们单 token 的权重读取是固定成本，增大批大小可以让同一批 token 共享这次读取，把 \\(B_{\\text{act}}\\) 按批摊薄。于是“要不要提批”不是拍脑袋，而是看当前 TPOT 离带宽下界多远：若远，提批摊薄权重读取是首选；若已贴近下界，提批只会把瓶颈推向算力项，收益递减。</p>\n<p>第二个决策是<strong>精度</strong>。\\(b_w\\) 从 1（FP8）降到 0.5（NVFP4），\\(B_{\\text{act}}\\) 近似减半，带宽项近似减半，吞吐近似翻倍。这个收益是解析可算的，不需要先跑 benchmark 才知道方向；NVFP4 的误差代价则由量化误差界单独约束，两条界合起来才能判断“值不值得”。</p>\n<p>第三个决策是<strong>容量规划与 SLO</strong>。给定模型结构（\\(N_{\\text{shared}}\\)、\\(k\\)、\\(N_e\\)）、精度 \\(b_w\\) 和硬件带宽，可以直接算出 TPOT 下界，进而判断某 SLO 是否物理可达。如果下界已经高于 SLO 目标，任何调度技巧都救不回来，必须改精度、改并行切分或换硬件——这是容量规划里最有价值的一次否决。</p>\n<p>代价维度上，这个界同时约束显存与带宽：权重字节数决定显存占用下限，带宽决定时延下限，两者共同决定单卡能放多少专家、需要多少卡做专家并行。它不直接约束功耗，但吞吐翻倍意味着每 token 的能耗摊薄，这是 NVFP4 在解码场景的真实卖点。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-4\">四 · 常见误解：四个必须纠正的用法</h3>\n<p><strong>误解一：用峰值算力估解码时延。</strong>直接用 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 当 TPOT，会忽略带宽项，低估 TPOT 数倍。算力项在 MoE 解码里通常不是 max 的胜者，把它当答案等于假设权重免费。</p>\n<p><strong>误解二：小批下用摊薄字节数 \\(B_{\\text{act}}/B\\)。</strong>摊薄只在批内 token 共享专家权重时成立。小批解码时专家命中分散，摊薄假设不成立，用 \\(B_{\\text{act}}/B\\) 估算会高估吞吐，直接导致 SLO 违约。正确做法是小批用 \\(B_{\\text{act}}\\)，大批才切换到摊薄形式。</p>\n<p><strong>误解三：把训练阶段的算力受限 roofline 套到解码。</strong>训练是算力受限、批大、算术强度高；解码是权重读取受限、批小、算术强度低。两者在 roofline 图上位置相反，套错模型会让容量规划偏乐观，上线后 TPOT 打脸。</p>\n<p><strong>误解四：纯 HBM 带宽模型忽略跨节点 All-to-All。</strong>跨节点专家并行时，token 要经 All-to-All 送到持有目标专家的卡上，这段时延不在 \\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\) 里。只算 HBM 带宽会低估实际 TPOT，尤其在 NVLink 域外的专家分布上。All-to-All 的下界由通信界单独给出，这里只需记住：带宽项是地板，通信是地板上另加的一层。</p>\n<p>还有一个隐性误解：把 \\(B_{\\text{act}}\\) 当成“模型总权重”。总权重决定显存容量，\\(B_{\\text{act}}\\) 决定单 token 时延，两者是不同的量。混淆它们会让“模型太大所以慢”这种错误归因成立——真正慢的是每 token 要读的那一小撮权重相对于带宽太贵。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-5\">五 · 一个具体例子：把界算到数字上</h3>\n<p>设某 MoE 模型共享专家加 k 个路由专家的激活权重在 FP8 下为 \\(B_{\\text{act}}\\) 字节，硬件为 B200，有效带宽按 8 TB/s 量级扣除效率后使用。带宽项 \\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\) 给出单 token 时延地板；算力项 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 因 \\(N_{\\text{act}}\\) 小、d 有限，通常远小于带宽项，max 取带宽项。这就是该模型在该精度下的 TPOT 下界。</p>\n<p>现在把 \\(b_w\\) 从 1 换成 0.5（NVFP4）：\\(B_{\\text{act}}\\) 近似减半，带宽项近似减半，吞吐近似翻倍。这个结论不依赖任何实测数字，只依赖公式结构。反过来，如果把批从 1 提到很大，摊薄后的有效字节变成 \\(B_{\\text{act}}/B\\)，带宽项随之下降，直到算术强度越过拐点，瓶颈转为 tensor core 算力与 tcgen05 利用率，带宽项不再主导——此时继续提批不再线性降 TPOT，收益被算力项封顶。</p>\n<p>这个例子说明界的用法：它不告诉你“跑多快”，它告诉你“最多能多快”和“往哪个方向调”。在小批下贴近带宽地板，说明优化空间在摊薄与精度；在大批下撞到算力项，说明该看 tcgen05 的 MMA 利用率而不是继续堆批。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-6\">六 · 界的边界条件与工程判断</h3>\n<p>这个界有三个明确的失效条件，工程上必须逐条检查。其一，批内 token 共享专家权重时，实际读取字节按批摊薄，公式须改为 \\(B_{\\text{act}}/B\\) 才成立；不共享时不能摊薄。其二，批很大、算术强度越过拐点后，瓶颈转为 tensor core 算力与 tcgen05 利用率，带宽项不再主导，此时 roofline 的点移到算力平台。其三，跨节点专家并行未把 All-to-All 时延计入，纯 HBM 带宽模型会低估实际 TPOT。</p>\n<p>判断当前处于哪个区间，只需比较两个候选项：带宽项与算力项谁大。带宽项大，就在带宽受限区，优化方向是摊薄（提批）、降字节（NVFP4）、减激活（调 k 或专家结构）；算力项大，就在算力受限区，优化方向是 tcgen05 利用率与 MMA 形状，而不是继续压带宽。这个二分判断是整套 roofline 分析的第一道闸门。</p>\n<p>最后落到一个具体机制上：\\(B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)\\) 里的 \\(N_{\\text{shared}}\\) 是每 token 必读的固定项，它不随 k 缩小。当 k 很小、共享专家占比高时，降 k 对 \\(B_{\\text{act}}\\) 的削减有限，真正有效的是把 \\(b_w\\) 从 1 压到 0.5——这是 NVFP4 在 MoE 解码上比在 dense 模型上更直接的原因。工程判断因此变成：先看 \\(N_{\\text{shared}}\\) 占比，再决定是调结构还是调精度，而不是默认“减专家数就能提速”。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-7\">七 · 边界在哪里：摊薄、拐点与跨节点时延</h3>\n<p>这一节只讨论那条带宽主导公式在什么条件下成立、什么时候必须换掉。公式本身是 <span class=\"formula\">$$T_{\\text{tok}}\\approx B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span>，其中 <span class=\"formula\">$$B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)$$</span> 是单 token 激活权重字节数。它成立的前提是：批内每个 token 都要把这份权重从 HBM 完整读一遍，且读与算之间没有可重叠的复用。一旦批内 token 命中同一组路由专家，权重读取就在批维度上被摊薄，真实字节数变成 <span class=\"formula\">$$B_{\\text{act}}/B$$</span>，此时 <span class=\"formula\">$$T_{\\text{tok}}$$</span> 的下界改写为 <span class=\"formula\">$$\\max(B_{\\text{act}}/(B\\cdot\\mathrm{BW}_{\\text{HBM}}),\\ 2N_{\\text{act}}d/F_{\\text{peak}})$$</span>。注意这个改写只在小批到中批、且专家命中确实集中的区间里有效；路由是数据相关的，最坏情况下批内 token 各走各的专家，摊薄系数退化为 1，按 <span class=\"formula\">$$B_{\\text{act}}/B$$</span> 做容量规划就会系统性高估吞吐，直接表现为 SLO 兑现不了。工程上判断能否摊薄，看的是实测的专家命中分布而不是批大小本身。</p>\n<p>第二个边界是算术强度拐点。带宽项与算力项取 max，当批大到把 <span class=\"formula\">$$2N_{\\text{act}}d/F_{\\text{peak}}$$</span> 推到超过带宽项时，瓶颈从 HBM 转到 tensor core 与 tcgen05 的利用率，带宽项不再主导，此时再靠加批换吞吐的边际收益迅速衰减，反而要盯 MMA 的发射密度与 TMEM 占用。这条拐点的位置由 <span class=\"formula\">$$b_w$$</span> 与 <span class=\"formula\">$$F_{\\text{peak}}$$</span> 共同决定：把 <span class=\"formula\">$$b_w$$</span> 从 FP8 的 1 降到 NVFP4 的 0.5，带宽项近似减半，拐点随之后移，等于把“加批还有用”的区间拉长——这正是 NVFP4 在解码阶段的价值所在，它改的不是算力峰值，而是那条带宽下界的位置。反过来，如果模型 <span class=\"formula\">$$k$$</span> 很小、<span class=\"formula\">$$N_e$$</span> 也不大，<span class=\"formula\">$$B_{\\text{act}}$$</span> 本就低，拐点来得早，继续堆批只会把延迟预算耗在调度与同步上。</p>\n<p>第三个边界最容易被忽略：跨节点专家并行。纯 HBM 带宽模型假设专家权重就在本卡 HBM 里，但 GB200/GB300 NVL72 上的大 MoE 往往把专家切到多张卡甚至多个节点，每 token 的激活路径要经过 All-to-All 把 hidden state 送到持有专家的设备，再把结果送回来。这段通信时延不在 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span> 里，却实打实计入 TPOT，NVLink 5 域内与跨域 InfiniBand 的差距会直接体现在这里。把纯带宽模型套到这种部署上，低估 TPOT 的幅度取决于 All-to-All 的相对占比：专家切得越细、<span class=\"formula\">$$k$$</span> 相对 <span class=\"formula\">$$N_e$$</span> 越小，通信占比越高，模型越失真。此时正确的做法是把通信项显式并入 <span class=\"formula\">$$T_{\\text{tok}}$$</span> 的 max 里，或用 NIXL 之类的传输层实测出这条路径的有效带宽再回填。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>主导项</th><th>公式形态</th><th>误用后果</th></tr></thead><tbody><tr><td>小批、专家命中分散</td><td>HBM 带宽</td><td><span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span></td><td>用峰值算力估算，TPOT 低估数倍</td></tr><tr><td>中批、命中集中</td><td>摊薄后带宽</td><td><span class=\"formula\">$$B_{\\text{act}}/(B\\cdot\\mathrm{BW}_{\\text{HBM}})$$</span></td><td>小批误用摊薄式，吞吐高估、SLO 违约</td></tr><tr><td>大批、越过拐点</td><td>tensor core / tcgen05</td><td><span class=\"formula\">$$2N_{\\text{act}}d/F_{\\text{peak}}$$</span></td><td>继续加批，延迟预算耗在调度</td></tr><tr><td>跨节点 EP</td><td>All-to-All 时延</td><td>带宽项 + 通信项取 max</td><td>纯带宽模型低估 TPOT</td></tr></tbody></table>\n<p>把这三条边界合起来看，这条 roofline 的定位就很清楚：它是解码 TPOT 的下界估计器，不是吞吐预测器。它的用途是回答两个工程问题——当前批大小下权重读取是否仍是瓶颈，以及把 <span class=\"formula\">$$b_w$$</span> 降到 0.5 是否值得。回答第一个问题要拿实测的专家命中分布去校验摊薄系数，回答第二个问题要确认拐点尚未到来、算力项仍被带宽项压住。一旦任一前提破裂，就该切换到含通信项与算力项的完整形态，而不是继续外推那条简洁的带宽下界。</p>\n<h3 id=\"th-roofline-moe-decode-sec-8\">八 · 带宽项的物理含义与 \\(B_{\\text{act}}\\) 的逐项拆解</h3>\n<p>公式里的带宽项 \\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\) 不是“把权重读一遍”的粗略说法，而是把单token解码必须从HBM搬到SM的那部分字节精确记账。拆开 \\(B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)\\)：\\(N_{\\text{shared}}\\) 是所有token都要过的共享专家（或稠密前置层）参数量，这部分字节无法被路由稀疏性削减，是解码路径上的固定税；\\(kN_e\\) 是top-k路由命中的专家参数量，\\(k\\) 决定稀疏度，\\(N_e\\) 是单专家规模；\\(b_w\\) 是位宽折算的字节数，NVFP4取0.5、FP8取1，这一项直接决定同一模型在两种精度下的带宽项比例关系。注意 \\(B_{\\text{act}}\\) 是“单token视角”的字节数，它隐含了一个前提：这些字节在本token的计算中确实需要被读入。工程上容易忽略的是，共享专家的字节在每层都存在，层数越多，固定税占比越高，因此低 \\(k\\) 的大模型并不自动等于低带宽项。</p>\n<p>把 \\(B_{\\text{act}}\\) 代入带宽项，得到的是单token权重读取的理论下界：在有效带宽 \\(\\mathrm{BW}_{\\text{HBM}}\\) 下，读这么多字节所需的最短时间。B200的HBM带宽标称约8 TB/s，但有效带宽必须扣除实测效率——HBM的行激活、bank冲突、以及权重布局非连续导致的低效访问都会吃掉一部分，实际可用带宽低于标称值。这一点在容量规划中必须显式处理：用标称8 TB/s算出的TPOT是乐观下界，工程上应把有效带宽作为独立参数标定，而不是把8 TB/s当成可兑现值。</p>\n<p>一个具体例子：设某MoE模型共享专家与稠密部分合计参数量对应FP8下 \\(b_wN_{\\text{shared}}\\) 为若干GB量级，单专家 \\(N_e\\) 使 \\(kN_e\\) 与之同量级，则 \\(B_{\\text{act}}\\) 落在数GB每token。在8 TB/s量级带宽下，带宽项给出的单token时间在毫秒量级；若误用峰值算力估算，会得到低一个数量级的结果——这正是失效模式中“低估TPOT数倍”的来源。代价形态很清楚：这一项是延迟下界，不是吞吐指标，它随 \\(b_w\\) 线性缩放，NVFP4把 \\(b_w\\) 从1降到0.5，理论上把带宽项减半，这是精度选择在解码侧最直接的收益路径。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-9\">九 · 算力项的推导：从FLOPs到 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\)</h3>\n<p>算力项 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 的推导起点是“每token的浮点运算量除以峰值算力”。系数2来自矩阵乘的乘加各计一次浮点运算；\\(N_{\\text{act}}\\) 是单token激活参数量（与 \\(B_{\\text{act}}/b_w\\) 同源，但这里是参数个数而非字节数）；\\(d\\) 是隐藏维度，代表每个激活参数在token维度上参与的乘加规模。严格说，MoE解码的FLOPs应按“激活权重矩阵 × 单token向量”计，即每个被激活的权重元素贡献一次乘加，因此 \\(2N_{\\text{act}}d\\) 是把“参数数 × 每参数参与的维度运算”这一结构写成了闭式。这一步的关键不是精确计数，而是确认算力项与带宽项共享同一组激活参数——两者不是独立瓶颈，而是同一份工作量的两种资源视角。</p>\n<p>推导的关键步在于取max而非相加：解码时权重读取与计算在时间上部分重叠（预取、流水），但稳态下由较慢的一侧主导，因此 \\(T_{\\text{tok}}=\\max(\\text{带宽项},\\text{算力项})\\) 是合理的下界形式。随后近似取带宽项，依据是：MoE解码每token只激活少数专家，\\(N_{\\text{act}}\\) 相对总参数量很小，而 \\(d\\) 有限，使 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 远小于 \\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\)。这个不等式成立的物理原因是算术强度（FLOPs/byte）被压到极低——每读一个权重字节只做很少的乘加，而HBM带宽相对算力峰值而言是稀缺资源。近似不是数学恒等，而是有明确适用域的工程简化。</p>\n<p>代价层面：算力项本身在解码中通常不构成约束，但它决定了“拐点”位置。当批大小上升、算术强度越过拐点，算力项开始与带宽项可比，此时瓶颈转为tensor core算力与tcgen05利用率，公式的近似失效。这意味着算力项的真正用途不是估算单token时延，而是标定“多大 batch 之后带宽项不再主导”。一个具体判断：若某模型在FP8下算力项比带宽项小一个数量级以上，则在小批解码区间内可以安全地只用带宽项做容量规划；反之若两者接近，说明该模型激活参数偏多或 \\(d\\) 偏大，必须保留max形式并准备拐点后的算力受限分析。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-10\">十 · 离散化与近似发生在哪三处</h3>\n<p>第一处近似是“单token字节数”到“稳态字节数”的离散化。公式默认每token独立读取 \\(B_{\\text{act}}\\)，但真实解码是连续批处理下的token流，多个token可能命中同一专家。当批内token共享专家权重时，实际读取字节按批摊薄，公式须改为 \\(B_{\\text{act}}/B\\)（\\(B\\) 为批大小）。这不是连续近似，而是离散命中结构的直接后果：共享程度取决于路由分布，最坏情况（批内专家完全不重叠）下摊薄失效，最好情况（高度集中）下摊薄接近线性。工程上不能假设摊薄一定发生，必须按路由熵与批内专家覆盖率评估。</p>\n<p>第二处近似是取max后丢弃较小项。\\(T_{\\text{tok}}\\approx B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\) 把算力项整体略去，等价于假设两者完全重叠且带宽项严格占优。真实系统中预取与计算的重叠并不完美，尤其在层间切换、专家切换时存在流水气泡，因此该近似给出的是下界而非可达值。这一近似的误差方向是单向的：实际TPOT不低于公式值，容量规划若直接采用公式值作为SLO承诺，会把气泡与调度开销漏掉。</p>\n<p>第三处近似是有效带宽的标量化。\\(\\mathrm{BW}_{\\text{HBM}}\\) 被当成一个常数，但实际有效带宽随访问模式变化：连续大块读取接近标称值，专家权重的分散布局、非对齐访问、以及多SM并发争抢会降低有效带宽。把8 TB/s标称值直接代入而不扣除实测效率，是把一个分布压成了点估计。代价体现在显存带宽利用率上：若有效带宽只有标称的若干成，带宽项被同比例放大，TPOT下界相应上移。一个具体例子：同一模型在权重布局连续时与布局碎片化时，公式给出相同结果，但实测TPOT差异明显——这说明公式的输入参数必须来自标定而非规格书。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-11\">十一 · 适用边界与误用方向的代价对照</h3>\n<p>边界一：小批解码。此时 \\(B_{\\text{act}}/B\\) 的摊薄不成立，必须用未摊薄的 \\(B_{\\text{act}}\\)。误用小批摊薄字节数会高估吞吐并导致SLO违约——这是失效模式中明确列出的方向。判断依据是批内专家覆盖率：若批大小远小于专家总数且路由分散，摊薄系数接近1，公式应回到原始形式。</p>\n<p>边界二：大批解码。算术强度越过拐点后，带宽项不再主导，瓶颈转为tensor core算力与tcgen05利用率。此时继续用带宽项估算会低估时延，因为算力项已成为max中的较大者。拐点位置由 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 与 \\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\) 的交点决定，工程上应把批大小作为分段参数，而不是用单一公式覆盖全区间。</p>\n<p>边界三：跨节点专家并行。纯HBM带宽模型不含All-to-All时延，跨节点EP时实际TPOT被通信项抬高。这一项不在本公式的max之内，属于公式外的附加代价，必须单独计入（其下界形式见专家并行通信条目）。误用表现为：容量规划按单节点带宽项算出乐观TPOT，上线后跨节点部署无法兑现。</p>\n<p>误用方向的代价可以对照：直接用峰值算力估算解码时延而忽略带宽项，会低估TPOT数倍；反之在小批下用摊薄后的 \\(B_{\\text{act}}/B\\) 估算，会高估吞吐。两个方向的错误都源于把公式的适用域扩大到了它不覆盖的区间。工程判断应落在“先确认批大小与专家覆盖率落在哪个区间，再选择公式形式”这一顺序上。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-12\">十二 · 公式作为决策工具：三个可执行的判断</h3>\n<p>判断一：给定模型与HBM带宽，算出解码TPOT下界，判断是否需要提高批大小摊薄权重读取。若当前批大小下 \\(B_{\\text{act}}/B\\) 相对 \\(B_{\\text{act}}\\) 的降幅有限，说明摊薄收益未兑现，提高批大小是直接手段；但需同时检查拐点，避免批大小越过算力受限区后收益反转。</p>\n<p>判断二：判断是否值得用NVFP4把 \\(b_w\\) 从1降到0.5。带宽项与 \\(b_w\\) 成正比，精度减半理论上使带宽项减半，从而近似翻倍吞吐（在带宽主导区间内）。这一判断的前提是模型仍处于带宽受限区，且量化误差在可接受范围内（误差界见NVFP4量化误差界条目）。若模型已接近拐点，精度收益会被算力项稀释。</p>\n<p>判断三：用公式反推所需有效带宽。若SLO要求的TPOT对应某个带宽项上限，而标称带宽扣除实测效率后无法满足，则结论是硬件或布局需要调整，而不是公式需要放宽。这一步把公式从“估算工具”变成“验收标准”：公式值是不可逾越的下界，实测TPOT高于它是正常的，低于它则说明字节记账漏项（例如共享专家被误算作可摊薄）。</p>\n<p>三个判断共享同一个纪律：公式的每一项都必须来自可标定的量——\\(b_w\\) 来自精度选择，\\(k\\) 来自路由配置，\\(\\mathrm{BW}_{\\text{HBM}}\\) 来自实测，\\(B\\) 来自调度策略。任何一项用规格书默认值替代标定值，都会把下界变成不可兑现的承诺。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-13\">十三 · 从公式到实现：字节记账如何落到kernel</h3>\n<p>公式要落地，\\(B_{\\text{act}}\\) 必须对应到真实的HBM事务。共享专家权重在每层被所有token读取，其字节应计入固定税且不随批摊薄；路由专家的读取取决于top-k命中，kernel侧通常按专家粒度聚合token再发起读取，聚合程度决定摊薄系数。若实现按token逐个发起专家权重读取，摊薄不发生，公式应保持未摊薄形式；若实现按批聚合，摊薄系数由批内专家覆盖率决定。这一区别不是理论细节，而是决定TPOT下界能否兑现的实现选择。</p>\n<p>伪代码思路：对每层，先读共享专家字节 \\(b_wN_{\\text{shared}}\\)，再按路由结果聚合token、按专家读取 \\(b_wN_e\\) 的命中份额，总字节累加得 \\(B_{\\text{act}}\\) 的实际值；用标定的有效带宽除之得带宽项，用 \\(2N_{\\text{act}}d/F_{\\text{peak}}\\) 得算力项，取max作为该层时间下界，跨层求和得单token下界。这个流程的关键是“按实际命中记账”而非“按公式名义值记账”，两者在路由分散时会显著分叉。</p>\n<p>代价形态：按专家聚合读取提高摊薄但引入聚合延迟与调度开销，按token逐个读取降低调度复杂度但放弃摊薄。工程判断应落在“批大小与路由集中度是否足以支撑聚合”上——聚合的收益必须超过其调度代价，否则公式的摊薄项只是纸面收益。最终，公式给出的下界只有在字节记账与kernel行为一致时才具备规划价值；不一致时，公式值不是乐观估计，而是错误估计。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-14\">十四 · 边界一：批内权重摊薄何时生效</h3>\n<p>公式的带宽项写的是单token激活权重字节数除以HBM带宽，隐含前提是这批token各自独立地把专家权重从HBM搬进SM。真实解码里，连续批处理会把不同请求的token拼进同一个前向，只要它们路由到同一个专家，这次权重读取就只发生一次，被整批摊薄。于是带宽项的正确形式是 <span class=\"sym\">B_act</span>/B 除以带宽，而不是 <span class=\"sym\">B_act</span> 除以带宽。这个替换不是修辞上的修正，它直接决定容量规划的方向：小批时摊薄几乎不发生，用摊薄后的字节数去估吞吐，等于把TPOT下界算小了一个量级，SLO在真实负载下必然违约。</p>\n<p>摊薄生效的充分条件有两个，缺一不可。其一是批内token在专家维度上足够分散，使得每个被激活的专家都承载多个token；其二是这些token在时间上确实同批，即调度器把它们放进同一个microbatch，而不是被chunked prefill或优先级抢占拆开。前者取决于路由分布的集中度，后者取决于批调度策略。工程上判断摊薄是否已经发生，看的是每个专家在批内的平均token数 <span class=\"sym\">n_e</span>，而不是批大小B本身：B很大但路由极度集中时，热门专家被反复命中、冷门专家一次只服务一个token，实际字节数介于 <span class=\"sym\">B_act</span> 与 <span class=\"sym\">B_act</span>/B 之间。</p>\n<div class=\"formula\">$$B_{\\text{eff}}=\\sum_{e\\in\\mathcal{E}_{\\text{batch}}} b_w N_e \\cdot \\mathbb{1}\\left[n_e&gt;0\\right],\\qquad \\frac{B_{\\text{act}}}{B}\\le \\frac{B_{\\text{eff}}}{B}\\le B_{\\text{act}}$$</div>\n<p>这里 <span class=\"sym\">B_eff</span> 是这批token真正从HBM读到的权重字节数，<span class=\"sym\">N_e</span> 是单个专家的参数量。左端是完美摊薄的理想值，右端是每个token都独占一次读取的最坏值。一个具体例子：top-k=2、每层64个路由专家、批大小32，若路由均匀，每个专家平均承载1个token，摊薄系数接近1，公式退化为原始形式；若路由高度偏斜到8个热门专家，每个热门专家承载约8个token，实际字节数降到 <span class=\"sym\">B_act</span> 的约四分之一，此时若仍按原始公式估TPOT，会把下界高估四倍，反过来若按 <span class=\"sym\">B_act</span>/B 估又会低估。代价落在显存带宽利用率上：摊薄越好，单位token分摊的HBM流量越低，但SM侧的tensor core开始成为约束，这正是下一个边界。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-15\">十五 · 边界二：算术强度越过拐点</h3>\n<p>原始公式取max的两项，在批很小时带宽项压倒算力项，近似取带宽项成立。批增大后，算力项 <span class=\"sym\">2N_act d</span>/<span class=\"sym\">F_peak</span> 不变（它是单token的固定开销），但带宽项被摊薄成 <span class=\"sym\">B_act</span>/(B·BW)，于是两者之比随B线性移动，必然存在一个拐点批大小B*，越过之后算力项主导。求拐点只需令两项相等：</p>\n<div class=\"formula\">$$B^{*}=\\frac{B_{\\text{act}}\\cdot F_{\\text{peak}}}{2\\,N_{\\text{act}}\\,d\\cdot \\mathrm{BW}_{\\text{HBM}}}$$</div>\n<p>B*的物理含义是：当批内token数超过它，每token分摊的权重读取时间已经小于它自身的浮点运算时间，继续加批不再降低TPOT，瓶颈转到tensor core与tcgen05的MMA利用率上。此时公式的带宽项不再主导，用带宽项估时延会系统性低估，且低估幅度随B增大而扩大。工程判断上，B*给出了“加批摊薄”这一手段的天花板：批大小加到B*附近，TPOT下界已经贴近算力项，再往上加只增加排队时延而不改善单token计算时间，容量规划应在此处停止堆批，转而考虑提高F_peak的有效利用率（例如用NVFP4把 <span class=\"sym\">b_w</span> 从1降到0.5，同时抬高F_peak的FP4 dense吞吐）。</p>\n<p>一个具体例子：某MoE每token激活参数 <span class=\"sym\">N_act</span> 较小、d有限，B*落在几十到上百的量级；在B=8的小批解码下带宽项仍是算力项的数倍，公式的近似成立；当B推到128以上，算力项反超，此时若仍宣称“吞吐随批线性增长”，就会在真实部署中看到吞吐曲线走平甚至因tcgen05流水填不满而下降。代价体现在延迟上：越过拐点后TPOT不再随批下降，SLO里的TPOT预算必须按算力项重新核算，而不是按带宽项。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-16\">十六 · 边界三：跨节点专家并行的通信项缺席</h3>\n<p>公式只含HBM带宽与峰值算力，没有任何互连项。这在单节点、专家全部驻留本地HBM时成立；一旦专家并行跨节点，token的路由结果必须经过All-to-All才能到达持有该专家的设备，通信时延就叠加在带宽项之上。此时正确的下界应是三项取max再加通信：</p>\n<div class=\"formula\">$$T_{\\text{tok}}\\approx\\max\\!\\left(\\frac{B_{\\text{act}}}{B\\cdot \\mathrm{BW}_{\\text{HBM}}},\\ \\frac{2N_{\\text{act}}d}{F_{\\text{peak}}}\\right)+T_{\\text{A2A}}$$</div>\n<p><span class=\"sym\">T_A2A</span> 由NVLink 5域内带宽、跨域InfiniBand或NIXL传输路径、以及NCCL集合通信的启动开销共同决定，它与批大小弱相关但与专家分布强相关：专家越分散，单token要走的跳数越多，<span class=\"sym\">T_A2A</span> 越大。纯HBM带宽模型在此处低估实际TPOT，低估量在专家并行度跨节点时不可忽略。一个具体例子：GB200 NVL72内专家全部落在同一NVLink域，<span class=\"sym\">T_A2A</span> 相对带宽项是小量，公式近似可用；当模型规模迫使专家切到两个NVL72机架、经InfiniBand互联，<span class=\"sym\">T_A2A</span> 可能成为三项中的最大项，此时再用纯带宽公式做容量规划，会把所需副本数算少，上线后TPOT超预算。判断方法是先估 <span class=\"sym\">T_A2A</span> 与带宽项的量级比，比值超过一定阈值就必须把通信项写进模型，而不是当作噪声。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-17\">十七 · 边界四：权重位宽与有效带宽的实测折扣</h3>\n<p>公式里的 <span class=\"sym\">BW_HBM</span> 写的是“有效带宽”，B200约8 TB/s但需扣除实测效率。这个折扣不是常数：它随访问模式变化。MoE解码读的是专家权重，属于大块连续流式读取，效率较高；但路由分散时读的是大量小片段，TLB与L2命中率下降，有效带宽显著低于峰值。同理 <span class=\"sym\">b_w</span> 取0.5（NVFP4）或1（FP8）是位宽对应的字节数，但反量化、scale因子读取、以及tcgen05对NVFP4的布局要求会引入额外流量，使实际字节数略高于 <span class=\"sym\">b_w</span> 乘以参数量。这两处偏差方向相反、量级不定，公式的精度因此有一个下限：当预测的TPOT与SLO预算的差距小于这两项折扣带来的误差时，公式只能给出趋势判断，不能当作验收依据。</p>\n<p>一个具体例子：把 <span class=\"sym\">b_w</span> 从1降到0.5，理论上带宽项减半、吞吐近似翻倍，这是公式的直接推论，也是判断“是否值得上NVFP4”的依据。但若反量化与scale读取带来额外流量，实际收益小于二倍；若同时F_peak的FP4路径利用率不足，拐点B*左移，加批摊薄的窗口变窄。工程上应把这两项折扣当作公式的误差带，在容量规划里留出余量，而不是把0.5当成精确的字节数代入。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-18\">十八 · 规模上限：公式在什么规模上失效</h3>\n<p>公式的适用规模有一个上界和一个下界。下界是批大小为1的纯延迟场景：此时摊薄不发生，公式退化为 <span class=\"sym\">B_act</span>/BW，预测的是单请求TPOT下界，成立但极保守，因为真实系统还有kernel启动、路由gating、采样等固定开销，这些不在公式里，小批下它们占比高，公式低估总时延。上界是批大到算力项主导且通信项不可忽略的规模：此时三项max加通信的完整形式才成立，原始两项式失效。中间地带——批大小在摊薄生效之后、拐点之前——是公式最准的区间，也是连续批处理实际运行的典型区间。</p>\n<p>还有一个规模维度是专家总数 <span class=\"sym\">N_e</span> 与top-k的比值。当 <span class=\"sym\">N_e</span> 远大于k时，路由极度稀疏，批内token命中同一专家的概率低，摊薄系数接近1，公式的摊薄修正几乎不起作用，带宽项按原始形式估反而更准；当 <span class=\"sym\">N_e</span> 接近k、专家少而集中，摊薄效应强，必须用 <span class=\"sym\">B_eff</span> 修正。误用方向因此是双向的：稀疏大专家池下用摊薄公式会高估吞吐，集中小专家池下用原始公式会低估吞吐。判断依据是批内每个专家的平均token数 <span class=\"sym\">n_e</span>，而不是模型参数量本身。</p>\n<p>把这些边界合起来看，公式的适用域可以写成一组约束：批大小落在摊薄生效与拐点之间、专家全部驻留本地或 <span class=\"sym\">T_A2A</span> 相对带宽项可忽略、有效带宽与位宽折扣在误差带内、固定开销相对带宽项是小量。四条同时满足时，公式给出可信的TPOT下界；任一条被破坏，公式退化为趋势工具，容量规划必须换用含摊薄、算力、通信三项的完整形式，并按最坏路由分布取 <span class=\"sym\">B_eff</span> 的上界。工程判断落在具体机制上：先用 <span class=\"sym\">n_e</span> 估摊薄系数，再用B*判断加批是否还有收益，最后用 <span class=\"sym\">T_A2A</span> 与带宽项的量级比决定是否把通信写进模型——这三步的顺序不能颠倒，因为摊薄系数决定了带宽项的实际大小，而带宽项的大小又决定了通信项是否值得计入。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-19\">十九 · 带宽项成立的前提与三个断点</h3>\n<p>公式的可用性取决于一个隐含假设：每个 token 的激活权重字节必须真正从 HBM 搬运一遍，且批内 token 之间不共享这些字节。一旦共享发生，roofline 的自变量就从 \\(B_{\\text{act}}\\) 变成 \\(B_{\\text{act}}/B\\)，而 \\(B\\) 是批内 token 数。这个替换不是线性修正，而是把模型从带宽受限区推向算力受限区的开关。工程上必须区分两种批语义：连续批处理中同一轮迭代的 token 若路由到同一专家，权重只读一次；若路由分散，则读次数接近专家被命中的不同集合大小，而非 token 数。因此摊薄系数实际是 \\(B_{\\text{eff}}\\)——批内命中的不同专家权重集合所覆盖的字节数，而非简单批大小。用小批实测的 TPOT 反推 \\(B_{\\text{act}}\\) 再外推到大批，是把 \\(B_{\\text{eff}}\\) 误当成 \\(B\\) 的典型错误。</p>\n<p>第一个断点是算术强度拐点。把带宽项与算力项相等时的批大小记为临界批 \\(B^\\*\\)，由 \\(\\frac{B_{\\text{act}}}{B^\\*\\cdot \\mathrm{BW}_{\\text{HBM}}}=\\frac{2N_{\\text{act}}d}{F_{\\text{peak}}}\\) 解出，其量级由 \\(F_{\\text{peak}}/\\mathrm{BW}_{\\text{HBM}}\\) 与每 token 激活参数共同决定。B200 的 8 TB/s 有效带宽与 FP4 峰值算力之间差距极大，这意味着 \\(B^\\*\\) 通常落在相当可观的批大小上；一旦越过，tcgen05 的 MMA 利用率、TMEM 占用与 2-SM 配对效率成为主项，此时再增加批只会推高算力项，带宽项退居次要。容量规划若仍按带宽线性外推吞吐，会在高批区间系统性低估时延增长。</p>\n<div class=\"formula\">$$T_{\\text{tok}}\\approx\\max\\!\\left(\\frac{B_{\\text{act}}}{B_{\\text{eff}}\\cdot \\mathrm{BW}_{\\text{HBM}}},\\ \\frac{2N_{\\text{act}}d}{F_{\\text{peak}}\\cdot \\eta_{\\text{tc}}}\\right)$$</div>\n<p>第二个断点是跨节点专家并行。纯 HBM 模型只计本地权重读取，未计 All-to-All 的 dispatch/combine 时延；当专家分布跨 NVLink 域甚至跨节点，token 路由引入的通信跳数与 NIXL/NCCL 传输时间会叠加进 TPOT，此时带宽项须替换为 \\(\\max(\\text{HBM 项},\\ \\text{互连项})\\)。第三个断点是权重位宽假设：\\(b_w=0.5\\) 的 NVFP4 收益以量化误差可接受为前提，若某层对精度敏感而回退到 FP8，则该层 \\(b_w=1\\)，混合精度下 \\(B_{\\text{act}}\\) 不再是单一常数，roofline 须按层分段计算。这三个断点共同定义了公式的适用域：小批、单节点、统一低精度，缺一即需修正。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式形态</th><th>主导代价</th></tr></thead><tbody><tr><td>小批、专家不共享</td><td>\\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\)</td><td>HBM 带宽、TPOT 下界</td></tr><tr><td>大批、专家命中集中</td><td>\\(B_{\\text{act}}/(B_{\\text{eff}}\\mathrm{BW}_{\\text{HBM}})\\)</td><td>摊薄后带宽，逼近拐点</td></tr><tr><td>越过拐点</td><td>算力项主导</td><td>tcgen05 利用率、功耗</td></tr><tr><td>跨节点 EP</td><td>max(HBM, 互连)</td><td>All-to-All 时延</td></tr></tbody></table>\n<h3 id=\"th-roofline-moe-decode-sec-20\">二十 · 从TPOT下界反解批大小B</h3>\n<p>把roofline界当成一个不等式来用，而不是当成一个预测值来用，是容量决策的第一条纪律。对单token，带宽项给出 $T_{\\text{tok}}\\ge B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$；对批大小 $B$ 的解码步，若批内token命中同一组专家，权重只读一遍，则每步耗时的下界是 $T_{\\text{step}}\\ge B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$ 与算力项 $\\max$ 的结果，而摊到每token的TPOT下界变成 $T_{\\text{step}}/B$。于是给定SLO要求的TPOT上限 $T_{\\text{slo}}$，可直接解出所需的最小批：</p>\n<div class=\"formula\">$$B\\ \\ge\\ \\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}\\cdot T_{\\text{slo}}}\\quad\\text{（带宽主导区）}$$</div>\n<p>这个式子的工程含义很硬：它把SLO翻译成一个关于批的硬约束，而不是一个可以靠调参绕过去的软目标。举例，取 $b_w=1$（FP8）、$N_{\\text{shared}}=2$、$k=2$、$N_e$ 为每专家约两千万参数规模，则 $B_{\\text{act}}$ 落在数十MB量级；以8 TB/s扣除实测效率后的有效带宽计，若SLO要求TPOT不超过数十毫秒，解出的 $B$ 会落在十几到几十之间。这意味着在FP8下，想兑现该SLO就必须把连续批处理的实际并发撑到这个量级；撑不到，SLO在物理上不可达，与调度策略无关。反过来，若把 $b_w$ 降到0.5（NVFP4），$B_{\\text{act}}$ 减半，同一SLO所需的最小批也减半——这正是“是否值得上NVFP4”的定量判据：它不是在问精度够不够，而是在问你的可达并发是否落在带宽约束解出的区间之下。</p>\n<p>代价必须同时记账。增大 $B$ 摊薄权重读取，收益是TPOT下降，代价是KV cache显存线性增长与单步内tensor core工作量上升。当 $B$ 越过算术强度拐点，$T_{\\text{step}}$ 的算力项 $\\frac{2N_{\\text{act}}d}{F_{\\text{peak}}}$ 开始主导，此时继续加批不再降低TPOT，只增加显存与功耗，吞吐进入平台。因此批大小的可用区间是“带宽约束解出的下界”到“算力拐点对应的上界”之间的一段，容量规划要落在这段里，而不是落在任一端点之外。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-21\">二十一 · 用拐点定并行度：TP与EP的分界线</h3>\n<p>并行度决策的本质是问：这个模型的解码落在带宽主导区还是算力主导区。若落在带宽区，增加张量并行（TP）只会把同一份权重切到更多卡上，每卡读取字节减少、单步带宽项下降，但每层引入的集合通信（All-Reduce）延迟随TP规模上升，净收益在TP超过一定规模后转负；此时更该做的是提高批、摊薄读取，而不是加卡切权重。若落在算力区，TP才有明确收益，因为算力项按TP线性下降。</p>\n<p>判据可以写成比较两个量：带宽项给出的每步时间 $B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$，与算力项 $\\frac{2N_{\\text{act}}d}{F_{\\text{peak}}}$。二者相等处即拐点批 $B^\\*$，满足</p>\n<div class=\"formula\">$$B^{*}\\ \\approx\\ \\frac{B_{\\text{act}}\\cdot F_{\\text{peak}}}{\\mathrm{BW}_{\\text{HBM}}\\cdot 2N_{\\text{act}}d}$$</div>\n<p>当实际并发 $B&lt;B^\\*$，加TP是把带宽瓶颈切得更细但通信开销吃掉收益，属于负优化；当 $B&gt;B^\\*$，加TP直接压缩算力项，收益明确。对专家并行（EP），判据不同：EP把不同专家放到不同卡，单卡只读自己那部分专家权重，$B_{\\text{act}}$ 中属于本卡的份额下降，但每token的路由意味着跨节点All-to-All，其时延必须计入 $T_{\\text{step}}$，纯HBM模型会低估实际TPOT。工程判断是：在带宽主导区优先用EP扩容量（因为EP不切每卡带宽份额而是切专家集合），在算力主导区优先用TP压时延；跨节点EP必须把All-to-All时延作为独立加项写进SLO预算，而不是指望它被带宽项吸收。</p>\n<p>具体例子：一个 $k=2$、专家数较多的MoE，在单节点8卡内做EP，单卡只需驻留部分专家，$B_{\\text{act}}$ 的本卡份额小，带宽项低，TPOT下界好看；一旦扩到跨节点NVL72规模，All-to-All跨NVLink 5域，时延项从微秒级升到需要认真计入的量级，此时若仍按单节点带宽模型算容量，规划会系统性偏乐观。正确做法是把 $T_{\\text{step}}$ 写成 $\\max(\\text{带宽项},\\text{算力项})+\\text{通信项}$，通信项随EP规模与拓扑变化，单独标定。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-22\">二十二 · 定KV预算：批与上下文的联合约束</h3>\n<p>批大小不是独立变量，它与KV cache预算耦合。设每token每层KV字节为 $b_{kv}$、层数 $L$、上下文长度 $S$，则单请求KV占用为 $2\\cdot b_{kv}\\cdot L\\cdot S$（K与V各一份），批 $B$ 条请求的KV总量为 $B\\cdot 2 b_{kv} L S$。显存约束要求这部分加上权重驻留与激活缓冲不超过可用HBM。于是容量规划变成一个两变量问题：</p>\n<div class=\"formula\">$$\\text{s.t.}\\quad B\\cdot 2b_{kv}LS\\ \\le\\ M_{\\text{avail}}-M_{\\text{weight}}-M_{\\text{act}},\\qquad B\\ \\ge\\ \\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}T_{\\text{slo}}}$$</div>\n<p>第一个不等式给出 $B$ 的上界（显存），第二个给出下界（SLO）。可行域存在的条件是上界不小于下界，这直接翻译成一句工程判断：当上下文 $S$ 很长时，KV上界收缩，可能低于SLO所需的最小批，此时SLO不可达，除非降 $b_w$（NVFP4减半权重占用，腾出显存给KV）、降 $k$（减少激活权重）、或缩短 $S$（分块预填与KV驱逐）。这就是为什么长上下文场景下NVFP4的价值不只是吞吐翻倍，而是把显存预算从权重侧挪到KV侧，让可行域重新出现。</p>\n<p>代价侧要看清：$b_{kv}$ 随KV量化位宽下降，但KV量化引入的误差会反馈到可接受的 $S$ 与批；权重侧用NVFP4省下的显存若全部转给KV，批上界抬升，但单步算力项随批上升，可能把系统推过拐点，TPOT不再随批下降。因此KV预算的分配不是“能塞多少塞多少”，而是把批定在可行域内靠近下界的位置，留出显存余量吸收请求长度抖动，避免长请求突发把批挤爆导致驱逐与重算。</p>\n<p>例子：同一模型在FP8下权重驻留占用显存的一大块，KV上界只允许批在个位数；切到NVFP4后权重占用减半，KV上界抬到十几，恰好跨过SLO解出的最小批，SLO从不可达变为可达。这个跃迁不是渐进的，而是可行域从空集变为非空集，容量规划要盯的正是这个临界点。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-23\">二十三 · 定SLO：把界写成预算表而非单点</h3>\n<p>SLO不是单一TPOT数字，而是一组预算的加总：$T_{\\text{TPOT}}\\ge T_{\\text{weight-read}}+T_{\\text{compute}}+T_{\\text{comm}}+T_{\\text{sched}}$。roofline界只覆盖前两项的 $\\max$，后两项必须单独列账。工程上把界写成预算表：权重读取项由 $B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$ 给出且随批摊薄，算力项由 $\\frac{2N_{\\text{act}}d}{F_{\\text{peak}}}$ 给出且随批上升，通信项由EP拓扑标定，调度项由连续批处理的批组装延迟给出。四项相加才是可承诺的TPOT。</p>\n<p>误用模式在此处最致命：直接用峰值算力估算解码时延，忽略带宽项，会把TPOT低估数倍，因为带宽项在解码区通常远大于算力项；反之在小批下用摊薄后的 $B_{\\text{act}}/B$ 估算，会高估吞吐，承诺的SLO在真实小批下无法兑现。两种误用的方向相反，但都源于把界当成等式而非不等式，且没有区分批是否足够大以触发摊薄。</p>\n<p>正确的用法是：先用 $B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$ 给出单token的TPOT下界（不摊薄，最保守），确认这个下界本身是否已低于SLO；若已低于，说明带宽不是障碍，瓶颈在通信或调度，优化方向转向拓扑与批组装；若高于，则必须靠批摊薄或降 $b_w$ 把有效字节压下来，且摊薄倍数不能超过实际可达并发。这条判断把“该优化什么”从猜测变成可计算的排序：先看保守下界与SLO的差距，再看摊薄能补多少，最后看通信项是否吃掉摊薄收益。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-24\">二十四 · 算例：一次完整的容量决策链</h3>\n<p>设某MoE解码，$b_w=1$（FP8），$N_{\\text{shared}}$ 与 $k N_e$ 合计使 $B_{\\text{act}}$ 落在数十MB量级，$\\mathrm{BW}_{\\text{HBM}}$ 取8 TB/s扣除效率后的有效值。第一步，算保守TPOT下界 $B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$，得到一个毫秒量级的数；若SLO要求与之相当或更严，则单token不可达，必须摊薄。第二步，解最小批 $B\\ge B_{\\text{act}}/(\\mathrm{BW}_{\\text{HBM}}T_{\\text{slo}})$，得到十几到几十的批需求。第三步，查显存：按给定 $S$ 算KV上界，若上界小于最小批，可行域为空，进入降 $b_w$ 分支——NVFP4把 $b_w$ 从1降到0.5，$B_{\\text{act}}$ 减半，最小批减半，同时权重显存减半抬高KV上界，可行域重新出现。第四步，检查拐点：若此时批已越过 $B^\\*$，TPOT不再随批下降，说明带宽已不是瓶颈，应停止加批、转向压通信项与调度项，或改用TP压算力项。第五步，把通信项加入预算表，若跨节点EP的All-to-All时延使总TPOT超出SLO，则回退到单节点EP或缩小EP规模，用容量换时延。</p>\n<p>这条链的每一步都由一个不等式或等式驱动，没有一步依赖经验系数。它的代价是：降 $b_w$ 到NVFP4会引入量化误差，需在精度可接受的前提下才成立；加批会抬高单步功耗与显存；缩EP规模会降低可驻留专家数、抬高单卡权重占用。工程判断落在“可行域是否非空”与“批是否在拐点之下”这两个二元问题上，而不是落在某个最优批的精确值上——因为在带宽主导区，TPOT对批的敏感度是 $1/B$ 的粗粒度关系，精确值意义有限，可行域边界才是决策依据。</p>\n<p>最后一段落在机制上：容量规划的输出不应是一个批大小数字，而应是一张三元组——(最小批, 显存上界批, 拐点批)，以及这三个数在当前 $b_w$、EP拓扑、$S$ 下的相对次序。次序决定优化动作：若最小批 &gt; 显存上界批，降 $b_w$ 或缩 $S$；若最小批 &lt; 拐点批 &lt; 显存上界批，加批有效且安全；若拐点批 &lt; 最小批，带宽已非瓶颈，优化转向通信与调度。这张次序表就是把roofline界从纸面公式变成可执行决策的全部内容。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-25\">二十五 · 把 roofline 变成容量决策：批大小、并行度、KV 预算与 SLO 的联立</h3>\n<p>这条 roofline 在容量决策里的正确用法，是把它当成一条<b>约束方程</b>而不是一条预测曲线：给定模型与硬件，先算出单 token 激活权重字节数 $B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)$，再除以有效带宽得到 TPOT 的硬下界。批大小 $B$ 的作用是把权重读取摊薄成 $B_{\\text{act}}/B$，因此吞吐上界近似为 $\\mathrm{BW}_{\\text{HBM}}\\cdot B/B_{\\text{act}}$，但这条式子只在 $B$ 尚未把算术强度推过拐点时成立——拐点条件是 $2N_{\\text{act}}d/F_{\\text{peak}}$ 与 $B_{\\text{act}}/(B\\cdot\\mathrm{BW}_{\\text{HBM}})$ 相等，越过之后瓶颈交给 tensor core 与 tcgen05 利用率，继续加批只增加排队而不增加单卡吞吐。工程判断因此是：批大小应定在拐点附近而非越大越好，KV 预算则要在这个批上反算——每 token 的 KV 字节乘以 $B$ 乘以平均上下文长度，必须留在剩余 HBM 内，否则批被显存挤回去，摊薄失效。</p>\n<p>并行度的定法直接由公式的分子决定。张量并行切分的是 $N_e$ 与 $d$，能等比缩小 $B_{\\text{act}}$ 但引入每层 All-Reduce；专家并行切分的是 $N_e$，把 $B_{\\text{act}}$ 中的 $kN_e$ 项按卡数除，代价是每 token 的 All-to-All。跨节点做专家并行时，纯 HBM 带宽模型会系统性低估 TPOT，必须把 All-to-All 时延作为加项塞进 max 之外，写成 $T_{\\text{tok}}\\approx B_{\\text{act}}/(B\\cdot\\mathrm{BW}_{\\text{HBM}})+T_{\\text{a2a}}$；NVLink 5 域内的 A2A 可以忽略，跨 NVL72 机柜边界时它往往与带宽项同量级，此时提高并行度反而恶化 SLO。精度决策同理：NVFP4 把 $b_w$ 从 1 降到 0.5，理论上吞吐近翻倍，但只有在带宽项主导、且量化未把专家路由分布打散导致负载倾斜时才兑现。</p>\n<p>算例：某 MoE 每 token 激活权重在 FP8 下为 $B_{\\text{act}}$，B200 有效带宽按 8 TB/s 扣除实测效率后取一个保守值。小批 $B=1$ 时 TPOT 下界就是 $B_{\\text{act}}/\\mathrm{BW}$，若直接用摊薄后的 $B_{\\text{act}}/B$ 去估吞吐，会得出线性增长的乐观曲线，而实际在拐点后走平——这正是 SLO 违约的典型来源。反过来，用峰值算力估解码时延会低估 TPOT 数倍，因为算力项在分子里根本不是主导项。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>公式中的抓手</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>批大小</td><td>$B_{\\text{act}}/B$ 摊薄</td><td>越过算术强度拐点</td><td>KV 显存挤占、排队延迟</td></tr><tr><td>并行度</td><td>切 $N_e$、$d$</td><td>跨节点 A2A 未计入</td><td>All-Reduce/A2A 带宽与尾延迟</td></tr><tr><td>精度</td><td>$b_w$: 1→0.5</td><td>路由倾斜、量化误差</td><td>精度损失与校准开销</td></tr></tbody></table>\n<p>最隐蔽的误用发生在小批：把 $B_{\\text{act}}/B$ 当成实际读取字节去算吞吐，等于假设批内 token 已经共享了专家权重，而小批下路由分散、共享率低，实际字节仍是 $B_{\\text{act}}$，于是容量规划偏乐观、SLO 无法兑现。判定共享是否成立要看批内路由直方图，而不是看批大小本身；只有当一个专家被批内多个 token 命中时，摊薄才真实发生。这条边界决定了 roofline 是容量规划的下界工具，而非吞吐承诺。</p>\n<h3 id=\"th-roofline-moe-decode-sec-26\">二十六 · 误用一：用峰值算力当解码时延的分母</h3>\n<p>最常见的一种误用，是把训练阶段的算力受限 roofline 直接搬到解码侧：看到模型标称的 FP4/FP8 dense TFLOPS，就用「每 token 浮点运算量 ÷ 峰值算力」当作 TPOT 的估计。这个数在训练场景里往往是对的，因为训练的前向与反向都有大矩阵乘、算术强度高；但在 MoE 解码里，每 token 只激活 <span class=\"sym\">k</span> 个路由专家加共享专家，算术强度被压到极低，算力项 <span class=\"formula\">$$2N_{\\text{act}}d/F_{\\text{peak}}$$</span> 与带宽项 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span> 取 max 后，带宽项通常远大于算力项。忽略带宽项，等于把分母从「有效带宽」换成了「峰值算力」，量纲上就错了。</p>\n<p>机制上，解码每步要为每个 token 从 HBM 搬运 <span class=\"formula\">$$B_{\\text{act}}=b_w(N_{\\text{shared}}+kN_e)$$</span> 字节的权重，这一步是串行的、受带宽约束的；tensor core 只在拿到权重后才开始乘加，且激活向量维度 <span class=\"formula\">$$d$$</span> 有限，乘加时间远小于搬运时间。所以真实 TPOT 的下界由 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span> 决定，算力峰值在这条路径上基本闲置。用峰值算力估时延，会低估 TPOT 数倍，直接后果是容量规划偏乐观：按这个数去算单卡 QPS，上线后发现 SLO 兑现不了，只能临时加卡或降级。</p>\n<p>识别方法很直接：把两个候选时延都算出来，比较量级。若带宽项显著大于算力项（MoE 解码的常态），任何只含算力项的估算都应作废。一个具体例子：某 MoE 模型 <span class=\"formula\">$$b_w=1$$</span>（FP8）、共享专家加 <span class=\"formula\">$$k$$</span> 个路由专家的激活权重字节数为 <span class=\"formula\">$$B_{\\text{act}}$$</span>，在 B200 约 8 TB/s 的有效带宽下（还需扣除实测效率），单 token 权重读取时间就是 <span class=\"formula\">$$B_{\\text{act}}/8\\,\\text{TB/s}$$</span>；而同样这些权重的乘加在峰值算力下只需其中很小一部分时间。规划时若只报后者，等于把 TPOT 报低了一个数量级。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-27\">二十七 · 误用二：小批下套用摊薄字节数</h3>\n<p>第二种误用方向相反，但同样致命：把批内共享专家权重带来的摊薄效应无条件套用。公式在批大小为 <span class=\"formula\">$$B$$</span> 时确实要改成 <span class=\"formula\">$$B_{\\text{act}}/B$$</span>，因为同一批内多个 token 命中同一专家时，权重只需读一次、在寄存器或 SMEM 里复用。但这条修正只在「批内 token 真的共享专家权重」时成立。小批解码时，token 数少、路由分散，命中同一专家的概率低，摊薄系数接近 1，此时用 <span class=\"formula\">$$B_{\\text{act}}/B$$</span> 估算就是把吞吐放大 <span class=\"formula\">$$B$$</span> 倍。</p>\n<p>后果是吞吐被高估、SLO 无法兑现。工程上表现为：压测时按摊薄公式算出可支撑的并发数，实际跑起来 TPOT 随并发上升而非按预期下降，尾延迟先崩。识别办法是看批内专家命中的集中度——若 <span class=\"formula\">$$B$$</span> 很小而专家数 <span class=\"formula\">$$N_e$$</span> 很大，摊薄假设不成立；只有当批大到路由分布开始收敛、单专家被多个 token 复用时，<span class=\"formula\">$$B_{\\text{act}}/B$$</span> 才有意义。这与「批很大、算术强度越过拐点后瓶颈转为 tensor core 算力与 tcgen05 利用率」是同一枚硬币的两面：摊薄有效的区间，恰好也是带宽项逐步让位的区间，两个修正不能各取一半混用。</p>\n<p>具体例子：连续批处理把并发从个位数拉到数十，若仍按 <span class=\"formula\">$$B_{\\text{act}}/B$$</span> 线性外推吞吐，会得到一条过于陡峭的吞吐-并发曲线；实测曲线在低并发段接近平坦（摊薄未生效），到中高并发才抬升。容量决策若按外推曲线做，低并发段的 SLO 会首先违约。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-28\">二十八 · 误用三：跨节点专家并行漏算 All-to-All</h3>\n<p>第三种误用是把纯 HBM 带宽模型直接用于跨节点部署的 MoE。单节点内专家并行时，token 路由靠 NVLink 5 与共享内存完成，时延可被带宽项吸收；一旦专家分布跨节点，每层解码都要插入 All-to-All 通信，把 token 发往持有目标专家的节点、再把结果收回。这部分时延不在 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span> 里，纯带宽模型会系统性低估实际 TPOT。</p>\n<p>机制上，All-to-All 的代价由消息大小、链路带宽与 NCCL/NIXL 的调度开销共同决定，且与解码步同步——它落在关键路径上，不能与下一层的权重读取重叠（除非做了通信-计算流水）。识别信号是：实测 TPOT 与单节点模型预测的差值随专家并行度（EP）增大而增大，且差值对批大小不敏感（通信量随 token 数线性增长，但固定开销占比高）。这与「专家并行 All-to-All 下界」条目讲的通信下界是同一约束，此处只需记住：带宽模型必须叠加通信项，否则跨节点容量规划偏乐观。</p>\n<p>具体例子：GB200/GB300 NVL72 机架内 NVLink 5 域很大，EP 可放到机架级；但若把专家切到机架之外，All-to-All 跨了更慢的链路，TPOT 的通信占比会明显抬升。工程判断是：先确认 EP 是否落在单一 NVLink 域内，再决定是否把通信项计入 roofline；落在域内可近似忽略，跨域则必须显式建模。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-29\">二十九 · 一个反例：从「算力富余」推到「加批无损」</h3>\n<p>把三种误用串起来看一个反例。某团队观察到解码时算力峰值大量闲置，于是判断「算力富余，加批一定无损」，据此把并发从个位数直接推到高并发，并按摊薄公式 <span class=\"formula\">$$B_{\\text{act}}/B$$</span> 预估吞吐线性增长。上线后尾延迟超标，SLO 违约。</p>\n<p>拆解这个反例：第一步错在用算力闲置反推带宽有余——算力闲置恰恰是带宽受限的症状，不是加批的许可；第二步错在低并发段就套用摊薄字节数，而该段路由分散、摊薄未生效；第三步错在未检查 EP 是否跨节点，若跨节点则 All-to-All 时延随并发上升。三步叠加，预测吞吐与实际吞吐的偏差被放大，且偏差方向一致（全部偏乐观），所以不会互相抵消。</p>\n<p>正确的做法是分段建模：低并发段用未摊薄的 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span> 加通信项；中高并发段在确认批内专家复用后才引入 <span class=\"formula\">$$B_{\\text{act}}/B$$</span>，并同时监控算术强度是否越过拐点、瓶颈是否转向 tcgen05 利用率。每一段都要有对应的实测锚点（TPOT 随并发、随 EP 的变化曲线），而不是从单一公式外推。反例的价值在于：它暴露的不是公式错，而是公式的适用区间被跨段误用——roofline 界是分段函数，不是一条直线。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-30\">三十 · 识别清单与工程判断</h3>\n<p>把识别动作固化成几条可执行的检查，能挡住绝大多数误用。每条都对应一个具体机制和一个代价维度：</p>\n<ul>\n<li>量级比对：同时算带宽项与算力项，若带宽项主导而估算只含算力项，作废重算。代价维度是 TPOT 被低估、容量规划偏乐观。</li>\n<li>摊薄前提检查：确认批内专家命中集中度，低并发段禁用 <span class=\"formula\">$$B_{\\text{act}}/B$$</span>。代价维度是吞吐被高估、SLO 违约。</li>\n<li>通信项检查：确认 EP 是否跨 NVLink 域，跨域则把 All-to-All 时延计入关键路径。代价维度是跨节点 TPOT 被低估。</li>\n<li>拐点检查：批增大后监控算术强度是否越过拐点、瓶颈是否转向 tensor core 与 tcgen05 利用率，及时切换模型形式。代价维度是带宽项失效后仍按带宽外推。</li>\n<li>精度切换检查：用 NVFP4 把 <span class=\"formula\">$$b_w$$</span> 从 1 降到 0.5 时，确认收益是否真按带宽项近似翻倍——若此时瓶颈已转向算力或通信，收益会被稀释。代价维度是精度切换的预期吞吐落空。</li>\n</ul>\n<p>工程判断落在最后一条上：roofline 界的用法不是「算一个数」，而是「先判定当前落在哪一段，再用该段的公式」。带宽主导段用 <span class=\"formula\">$$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$$</span>，摊薄生效段用 <span class=\"formula\">$$B_{\\text{act}}/B$$</span>，拐点之后转向算力与 tcgen05 利用率，跨节点再叠加通信项。任何把这三段压成一条直线的估算，都会在某个并发区间上给出偏乐观的 TPOT，而 SLO 恰恰是在那个区间被击穿的。</p>\n\n\n<h3 id=\"th-roofline-moe-decode-sec-31\">三十一 · 误用与反例：roofline 在什么条件下会骗你</h3>\n\n<p>这套 roofline 最危险的误用，是把训练阶段的算力受限直觉原样搬到解码侧。训练时大批量、长序列、梯度累积把算术强度推到拐点右侧，用 <span class=\"formula-inline\">F_peak</span> 估时延是合理的；解码时每 token 只激活少数专家，算术强度被压到极低，算力项与带宽项相差一个数量级以上。若容量规划直接拿峰值算力反推 TPOT，会系统性低估数倍，把本该预留的 HBM 带宽预算挪给了并不紧张的算力预算。识别方法很直接：算一遍 <span class=\"formula-inline\">2N_act·d/F_peak</span> 与 <span class=\"formula-inline\">B_act/BW_HBM</span> 的比值，若后者大出一个量级，任何以算力为主项的估算都应作废。代价体现在部署侧——按算力估出的单卡并发数偏高，上线后 TPOT 抖动、SLO 违约，再回头加卡已是既成事实。</p>\n\n<p>第二个反例出在小批解码时误用摊薄字节数。批内 token 共享专家权重，实际读取字节按批摊薄，公式须改为 <span class=\"formula-inline\">B_act/B</span>；但这只在批内确实命中同一批专家、且权重能被复用读取时成立。小批（例如 B 很小、路由分散）下把 <span class=\"formula-inline\">B_act/B</span> 代进去，等于假设每个 token 的专家权重只读一次却被 B 个 token 分摊，吞吐被高估，SLO 无法兑现。工程上的判据是看路由分布的集中度：top-k 命中重叠低时，摊薄系数应打折而非取满。下表给出三种估算口径的适用性对照。</p>\n\n<table class=\"mini\">\n<thead><tr><th>估算口径</th><th>适用条件</th><th>失效后果</th></tr></thead>\n<tbody>\n<tr><td><span class=\"formula-inline\">B_act/BW_HBM</span></td><td>小批、路由分散、带宽主导</td><td>基本可信，作为 TPOT 下界</td></tr>\n<tr><td><span class=\"formula-inline\">B_act/(B·BW_HBM)</span></td><td>大批、专家命中高度重叠</td><td>小批误用则高估吞吐</td></tr>\n<tr><td><span class=\"formula-inline\">2N_act·d/F_peak</span></td><td>算术强度越过拐点</td><td>解码侧误用则低估 TPOT 数倍</td></tr>\n</tbody>\n</table>\n\n<p>第三个失效条件更隐蔽：跨节点专家并行。纯 HBM 带宽模型只算了本地权重读取，没把 All-to-All 的 dispatch/combine 时延计入。当专家被切到多张卡、token 需跨 NVLink 域甚至跨节点搬运时，实际 TPOT 由 <span class=\"formula-inline\">max(B_act/BW_HBM, T_all2all)</span> 决定，而后者在拓扑跨域时会成为主项。识别方式是做一次分层拆解：把单 token 时延按权重读取、路由通信、tcgen05 计算三段分别计时，若通信段占比超过带宽段，roofline 的带宽近似就不再是瓶颈描述。系统代价是显存与带宽的双重占用——专家并行省了单卡显存，却把压力转移到 fabric 上，容量规划必须按 fabric 有效带宽而非 HBM 带宽留余量。工程判断落在具体机制上：先测路由重叠度与 fabric 时延，再决定是加大批摊薄权重、还是收敛专家放置以减少跨域流量；roofline 只用来定位瓶颈在哪一段，不用来直接出容量数字。</p>\n\n<h3 id=\"th-roofline-moe-decode-sec-32\">三十二 · 带宽项被当成常数：三种把 roofline 用反的现场</h3>\n\n<p>最常见的误用是把训练阶段的算力受限 roofline 直接平移到解码容量规划：拿 <span class=\"sym\">F_peak</span> 除以每 token 的 FLOPs 得到 TPOT，忽略带宽项，结果把时延低估数倍。识别方法很直接——把两个候选值都算出来并列，若带宽项比算力项大一个量级以上，任何以算力为分母的估算都作废。另一种反向误用发生在小批：把 <span class=\"sym\">B_act</span> 除以批大小 B 得到摊薄字节数，再代入带宽项，等于假设批内所有 token 命中同一组专家。这一假设只在专家高度集中时近似成立；top-k 路由分散时，批内并集专家数随 B 增长，摊薄收益迅速饱和。判据是看批内激活专家的并集规模与 B 的比值，比值接近 1 才可用摊薄式，否则必须回到未摊薄形式。</p>\n\n<div class=\"formula\">$$\\text{误用判据：}\\ \\frac{B_{\\text{act}}}{B}\\ \\text{仅在}\\ \\left|E_{\\text{union}}(B)\\right|\\ll B\\cdot k\\ \\text{时可用；否则}\\ T_{\\text{tok}}\\approx\\frac{B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}}$$</div>\n\n<p>跨节点专家并行是第三个盲区：纯 HBM 带宽模型不含 All-to-All 时延，而 EP 组越大，dispatch/combine 的往返在 TPOT 中的占比越高。系统代价上，这条被漏掉的项直接表现为尾延迟抬升与 SLO 违约，而非平均吞吐下降——平均值被计算掩盖，p99 暴露真相。识别手段是在 TPOT 分解里显式列出通信项，若其与带宽项同量级，roofline 只能当下界用，不能当预测用。</p>\n\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>用峰值算力估解码时延</td><td>TPOT 低估数倍，容量规划偏乐观</td><td>带宽项 ≫ 算力项</td></tr><tr><td>小批套用 B_act/B</td><td>吞吐高估，SLO 无法兑现</td><td>批内专家并集 ≈ B·k</td></tr><tr><td>忽略 All-to-All</td><td>p99 尾延迟超标</td><td>通信项与带宽项同量级</td></tr></tbody></table>\n\n<p>一个具体反例：某 MoE 服务按摊薄式算出单卡可支撑的批大小并据此定容，上线后小批请求占多数，实际每 token 仍需读取接近完整的 <span class=\"sym\">B_act</span>，HBM 带宽被打满而 tensor core 空闲，TPOT 超出预算。修正路径不是加卡，而是先判断瓶颈归属：小批场景下提高批大小摊薄权重读取，或用 NVFP4 把 <span class=\"sym\">b_w</span> 从 1 降到 0.5 近似翻倍有效吞吐；只有当批大到算术强度越过拐点、瓶颈转入 tcgen05 利用率时，才轮到算力项主导，此时再谈算力优化才有意义。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>B_{\\text{act}}</td><td>单token激活权重字节数（含共享专家与k个路由专家）</td></tr><tr><td>\\mathrm{BW}_{\\text{HBM}}</td><td>HBM有效带宽（B200约8 TB/s，扣除实测效率）</td></tr><tr><td>b_w</td><td>权重位宽对应的字节数（NVFP4为0.5，FP8为1）</td></tr><tr><td>k</td><td>每token路由专家数top-k</td></tr><tr><td>F_{\\text{peak}}</td><td>峰值算力（FP4/FP8 dense TFLOPS）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-roofline-moe-decode · 共 5 个片段</p>\n"},{"id":"th-kv-cache-capacity","title":"KV cache显存容量式","direction":"dir-expert-parallel-alltoall","prereq":[],"plain":"KV cache占用等于层数×KV头数×头维×序列长×批大小×每元素字节，再乘分页碎片系数；它决定单卡能装多少并发序列，是容量规划的第一约束。","definition":"KV cache占用等于层数×KV头数×头维×序列长×批大小×每元素字节，再乘分页碎片系数；它决定单卡能装多少并发序列，是容量规划的第一约束。","formula":"$$M_{\\text{KV}}=2\\,L\\,H_{kv}\\,d_h\\,s\\,B\\,b_{kv}\\,\\alpha_{\\text{page}},\\qquad B_{\\max}=\\left\\lfloor\\frac{M_{\\text{free}}}{2\\,L\\,H_{kv}\\,d_h\\,s\\,b_{kv}\\,\\alpha_{\\text{page}}}\\right\\rfloor$$","variables":[{"sym":"L","meaning":"Transformer层数"},{"sym":"H_{kv}","meaning":"KV头数（GQA下远小于Q头数）"},{"sym":"d_h","meaning":"每头维度"},{"sym":"s","meaning":"序列长度（含历史与生成长度）"},{"sym":"b_{kv}","meaning":"KV每元素字节数（FP8为1，NVFP4为0.5）"},{"sym":"\\alpha_{\\text{page}}","meaning":"分页/对齐碎片放大系数（典型1.05–1.2）"}],"derivation":"推导关键一步：由$$B_{\\max}=\\lfloor M_{\\text{free}}/(2LH_{kv}d_hsb_{kv}\\alpha_{\\text{page}})\\rfloor$$把显存预算直接换算为最大并发序列数，分母即单序列KV字节，取整后即为可调度上限。","example":"用途：决定单卡最大并发batch、分页块大小选型与是否启用FP8/NVFP4 KV量化；也是分离式解码池按序列数扩容的直接依据。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["GQA/MLA等压缩结构改变H_kv与d_h定义，公式需按实际缓存布局重写（MLA缓存的是潜向量而非K/V）","序列长度异构时须用各请求长度之和而非 B×s，且分页碎片系数α随块大小与长度分布漂移"],"system_note":"误用：用平均序列长代替异构长度之和估算并发，会在长尾请求下OOM；忽略$$\\alpha_{\\text{page}}$$会把容量高估5%–20%，导致调度器接纳过多请求后被迫抢占。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：KV cache占用等于层数×KV头数×头维×序列长×批大小×每元素字节，再乘分页碎片系数，它决定单卡能装多少并发序列，是容量规划第一约束。","公式中$$2LH_{kv}d_hsb_{kv}\\alpha_{\\text{page}}$$的因子2对应K与V两份缓存；$$H_{kv}$$在GQA下远小于Q头数，$$b_{kv}$$为FP8时取1、NVFP4时取0.5，$$\\alpha_{\\text{page}}$$为分页对齐碎片放大系数，典型1.05–1.2。","推导关键一步：由$$B_{\\max}=\\lfloor M_{\\text{free}}/(2LH_{kv}d_hsb_{kv}\\alpha_{\\text{page}})\\rfloor$$把显存预算直接换算为最大并发序列数，分母即单序列KV字节，取整后即为可调度上限。","适用边界：GQA/MLA等压缩结构改变$$H_{kv}$$与$$d_h$$定义，公式须按实际缓存布局重写，MLA缓存的是潜向量而非K/V；序列长度异构时须用各请求长度之和而非$$B\\times s$$，且$$\\alpha_{\\text{page}}$$随块大小与长度分布漂移。","用途：决定单卡最大并发batch、分页块大小选型与是否启用FP8/NVFP4 KV量化；也是分离式解码池按序列数扩容的直接依据。","误用：用平均序列长代替异构长度之和估算并发，会在长尾请求下OOM；忽略$$\\alpha_{\\text{page}}$$会把容量高估5%–20%，导致调度器接纳过多请求后被迫抢占。"],"anchors":["FP8为1","NVFP4为0.5","典型1.05–1.2"],"pitfalls":["按平均序列长度而非长度之和估算并发容量，长尾请求触发OOM与抢占。","忽略分页碎片系数$$\\alpha_{\\text{page}}$$，容量高估5%–20%，调度器接纳过多请求。","对MLA等压缩缓存仍套用K/V双份公式，容量估算严重偏离实际布局。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-1\">一 · 一句话直觉：KV cache 是&quot;每个 token 的账本&quot;，容量式是账本页数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-2\">二 · 为什么需要这条式子：它是容量规划的第一约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-3\">三 · 分母的四个易错点：2、H_kv、b_kv、α_page</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-4\">四 · 常见误解：平均长度、B×s、以及&quot;公式万能&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-5\">五 · 从公式到工程动作：三个直接可用的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-6\">六 · 容量公式的三条边界：异构长度、分页碎片与压缩缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-7\">七 · 逐项拆解：每个因子在显存里对应哪一段物理地址</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-8\">八 · 推导关键步：从字节预算到可调度整数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-9\">九 · 异构长度：为什么 $$B\\times s$$ 必须换成求和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-10\">十 · 压缩布局：GQA、MLA与公式重写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-11\">十一 · 精度因子的边界：$$b_{kv}$$ 取0.5时公式还成立吗</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-12\">十二 · 从公式到工程判据：三个必须固化的检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-13\">十三 · 公式成立的三条隐含假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-14\">十四 · 压缩缓存布局：Hkv 与 dh 被重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-15\">十五 · 异构长度：B×s 必须换成求和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-16\">十六 · αpage 的漂移与块大小选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-17\">十七 · 规模上限：公式在什么量级上先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-18\">十八 · 失效判据的工程落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-19\">十九 · 容量式在压缩缓存、异构长度与分页漂移下的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-20\">二十 · 容量式在压缩缓存与异构长度下的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-21\">二十一 · 从显存余量到可调度上限：B_max 的取整语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-22\">二十二 · 定批大小：用长度之和而非 B×s</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-23\">二十三 · 定并行度：TP 与 DP 的容量换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-24\">二十四 · 定 KV 预算：b_kv 与 α_page 的联合选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-25\">二十五 · 定 SLO：把容量式反解为时延约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-26\">二十六 · 算例：一次完整的容量决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-27\">二十七 · 容量式落到调度器：从字节预算到接纳上限的换算边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-28\">二十八 · 误用一：用平均序列长冒充长度之和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-29\">二十九 · 误用二：把 α_page 当成常数 1</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-30\">三十 · 误用三：对 MLA 套用 K/V 双份公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-31\">三十一 · 反例：一次把三个误用叠在一起的容量估算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-32\">三十二 · 把误用检测做成常驻检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-33\">三十三 · 容量式失效的三种典型误用与识别信号</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:515px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 515.3 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：KV cache占用等于层数×KV头数×头维×序列长×批大小×每元…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$M_{\\text{KV}}=2\\,L\\,H_{kv}\\,d_h…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"433.3\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：GQA/MLA等压缩结构改变H_kv与d_h定义，公式需按实际缓存…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-kv-cache-capacity-sec-1\">一 · 一句话直觉：KV cache 是\"每个 token 的账本\"，容量式是账本页数</h3>\n<p>把一条请求的 KV cache 想成一本不断增厚的账本：每生成一个 token，就在每一层、每一个 KV 头上追加一行 K 和一行 V。账本厚度只取决于\"层数 × KV 头数 × 头维 × 已见 token 数\"，与 Q 头数、与注意力分数矩阵的瞬时大小无关。容量式回答的问题只有一个：给定一块空闲显存，这本账本能同时摊开多少本？因此它的输出不是一个字节数，而是一个可调度上限 <span class=\"inline-math\">B_max</span>——调度器真正消费的量。</p>\n<p>严格定义如下。设空闲显存为 <span class=\"inline-math\">M_free</span>（已扣除权重、激活峰值、通信缓冲与框架保留），单序列 KV 字节数为</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\,L\\,H_{kv}\\,d_h\\,s\\,B\\,b_{kv}\\,\\alpha_{\\text{page}},\\qquad B_{\\max}=\\left\\lfloor\\frac{M_{\\text{free}}}{2\\,L\\,H_{kv}\\,d_h\\,s\\,b_{kv}\\,\\alpha_{\\text{page}}}\\right\\rfloor$$</div>\n<p>其中因子 2 是 K 与 V 两份缓存；<span class=\"inline-math\">L</span> 为层数，<span class=\"inline-math\">H_kv</span> 为 KV 头数（GQA 下远小于 Q 头数），<span class=\"inline-math\">d_h</span> 为每头维度，<span class=\"inline-math\">s</span> 为序列长度（含历史与生成长度），<span class=\"inline-math\">B</span> 为批大小，<span class=\"inline-math\">b_kv</span> 为每元素字节（FP8 取 1，NVFP4 取 0.5），<span class=\"inline-math\">α_page</span> 为分页/对齐碎片放大系数，典型 1.05–1.2。取整这一步不是形式主义：<span class=\"inline-math\">B_max</span> 必须是整数，调度器按它接纳请求，多接纳一个就触发抢占或 OOM。</p>\n<p>系统代价直接体现在分母上。以 FP8 KV、<span class=\"inline-math\">b_kv=1</span> 为例，单序列每 token 的 KV 字节为 <span class=\"inline-math\">2·L·H_kv·d_h</span>；把 <span class=\"inline-math\">b_kv</span> 换成 0.5（NVFP4），单序列字节减半，<span class=\"inline-math\">B_max</span> 近似翻倍——这是 KV 量化最直接的容量收益，代价是解码精度与反量化开销，属于数值精度条目的话题，此处只把它当作分母上的一个乘数。反过来，序列长 <span class=\"inline-math\">s</span> 翻倍，<span class=\"inline-math\">B_max</span> 减半，这是长上下文服务里最硬的约束。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-2\">二 · 为什么需要这条式子：它是容量规划的第一约束</h3>\n<p>解码阶段的算术强度极低，权重读取与 KV 读取共同构成带宽瓶颈，而 KV 读取量正比于 <span class=\"inline-math\">B×s</span>。于是出现一个结构性矛盾：要提高吞吐就得加 <span class=\"inline-math\">B</span>，但 <span class=\"inline-math\">B</span> 的上限由 KV 显存给出，不由算力给出。容量式的作用就是把\"还能不能再塞一条请求\"从经验判断变成可计算的门槛。它同时是三个工程决策的直接依据：单卡最大并发 batch、分页块大小选型、是否启用 FP8/NVFP4 KV 量化；在分离式部署中，它还是解码池按序列数（而非按 GPU 数）扩容的依据。</p>\n<p>举个具体例子。某模型 <span class=\"inline-math\">L</span> 层、<span class=\"inline-math\">H_kv</span> 个 KV 头、头维 <span class=\"inline-math\">d_h</span>，FP8 KV，<span class=\"inline-math\">α_page</span> 取 1.1。若目标上下文 <span class=\"inline-math\">s</span> 为 32K，则单序列 KV 字节为 <span class=\"inline-math\">2·L·H_kv·d_h·32768·1·1.1</span>；把 <span class=\"inline-math\">M_free</span> 除以它并向下取整，得到的就是该卡在此上下文下的并发上限。工程上真正要盯的是这个商随 <span class=\"inline-math\">s</span> 的变化曲线：<span class=\"inline-math\">s</span> 从 4K 走到 32K，容量降为八分之一，调度器的接纳策略必须随请求长度分布动态调整，否则短请求与长请求混跑时，少数长请求就能吃掉大半容量。</p>\n<p>另一个代价维度是功耗与带宽的耦合：KV 读取量随 <span class=\"inline-math\">B×s</span> 线性增长，而 HBM 带宽是固定的，因此 <span class=\"inline-math\">B_max</span> 同时也是\"带宽不被打爆\"的实际上限。容量式给出的数字往往比带宽允许的数字更紧，这正是它被称为第一约束的原因。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-3\">三 · 分母的四个易错点：2、H_kv、b_kv、α_page</h3>\n<p>因子 2 对应 K 与 V 两份缓存，看似 trivial，却是误用的高发区：一旦缓存布局改变（例如 MLA 只缓存潜向量），这个 2 就不再成立，公式必须按实际布局重写，否则容量估算会严重偏离。同理，<span class=\"inline-math\">H_kv</span> 与 <span class=\"inline-math\">d_h</span> 的定义在 GQA/MLA 下被改写——GQA 让 <span class=\"inline-math\">H_kv</span> 远小于 Q 头数，这是容量式能成立的前提；MLA 缓存的不是 K/V 而是潜向量，套用双份 K/V 公式会得到系统性错误的数字。</p>\n<p><span class=\"inline-math\">b_kv</span> 是唯一可以\"调\"的因子：FP8 取 1，NVFP4 取 0.5，直接把分母减半。但量化不是免费的，它换来容量、付出精度与反量化算力，这笔账属于数值精度条目的范围，此处只强调一点：<span class=\"inline-math\">b_kv</span> 的取值必须与缓存实际存储格式一致，若缓存里仍以 BF16 存放再在读取时转换，分母应按 2 计算，否则容量被高估一倍。</p>\n<p><span class=\"inline-math\">α_page</span> 是最容易被忽略的因子。分页分配以块为单位，序列末尾的残块、块大小与长度分布的匹配程度都会产生内部碎片，典型放大 1.05–1.2。忽略它会把容量高估 5%–20%——这个量级足以让调度器接纳过多请求，随后被迫抢占，表现为解码延迟尖刺而非直接报错，排查成本很高。块越小碎片越小但元数据与寻址开销越大，块越大越省元数据但尾部浪费越多，这就是分页块大小选型的核心权衡，容量式里的 <span class=\"inline-math\">α_page</span> 正是这个权衡的量化入口。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-4\">四 · 常见误解：平均长度、B×s、以及\"公式万能\"</h3>\n<p>第一个误解是用平均序列长代替异构长度之和。真实负载里请求长度是重尾分布，容量式在异构场景下必须写成各请求长度之和 <span class=\"inline-math\">Σs_i</span>，而不是 <span class=\"inline-math\">B×s</span>。用平均长度估算并发，在长尾请求到来时会瞬间 OOM 或触发抢占：平均值掩盖了少数超长请求对容量的吞噬效应。正确做法是按长度分位数做容量规划，例如以 P99 长度作为准入上限，或对超长请求单独限流。</p>\n<p>第二个误解是把 <span class=\"inline-math\">B_max</span> 当成静态常量。它随 <span class=\"inline-math\">M_free</span>、<span class=\"inline-math\">s</span> 分布、<span class=\"inline-math\">α_page</span> 漂移而变：连续批处理下每个 step 都有请求进出，<span class=\"inline-math\">M_free</span> 是动态量，<span class=\"inline-math\">α_page</span> 随块大小与当前长度分布漂移。因此容量式在调度器里应以\"每 step 重算的准入检查\"形式存在，而不是启动时算一次。</p>\n<p>第三个误解是对压缩缓存套用 K/V 双份公式。MLA 类结构缓存的是潜向量，其每 token 字节数与 <span class=\"inline-math\">2·L·H_kv·d_h</span> 无对应关系，必须按实际布局重写分母。这类误用不会报错，只会让容量估算系统性偏离，且偏离方向随模型结构而异，属于最难通过日志发现的错误。</p>\n<p>第四个误解是把容量式与带宽式混为一谈。容量式回答\"装得下多少\"，带宽式回答\"跑得多快\"，两者约束不同：装得下但带宽打满时，增加 <span class=\"inline-math\">B</span> 不会提升吞吐，只会拉长单步延迟。容量规划必须同时过这两道闸，容量式只是第一道。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-5\">五 · 从公式到工程动作：三个直接可用的判断</h3>\n<p>判断一：先算单序列每 token 字节 <span class=\"inline-math\">2·L·H_kv·d_h·b_kv</span>，再乘以目标上下文长度与 <span class=\"inline-math\">α_page</span>，得到单序列占用；用它去除 <span class=\"inline-math\">M_free</span> 并向下取整，得到 <span class=\"inline-math\">B_max</span>。这个数如果显著小于带宽允许的并发数，说明容量是瓶颈，优先考虑 KV 量化或压缩结构；反之说明带宽是瓶颈，加容量无益。</p>\n<p>判断二：把 <span class=\"inline-math\">α_page</span> 当作可测量的量而非常数。用实际块大小与线上长度分布回算碎片率，若发现 <span class=\"inline-math\">α_page</span> 长期高于 1.15，说明块大小与长度分布不匹配，调整块大小比加卡更划算。这一步的收益是定性的：降低碎片直接抬高 <span class=\"inline-math\">B_max</span>，且不引入任何数值风险。</p>\n<p>判断三：在分离式部署中，用 <span class=\"inline-math\">B_max</span> 而非 GPU 数作为解码池扩容单位。预填与解码的容量约束不同，解码池的扩容依据是\"还能装多少条序列\"，这正是容量式的输出。扩容决策若按 GPU 数做，会在长上下文场景下过度配置。</p>\n<p>这三个判断的共同点是：容量式不是一条用来背的公式，而是一个每 step 重算的准入函数。它的分母里每一项都可测、可调、可误用，工程价值恰恰在于把\"还能不能再塞一条\"变成一次除法加一次取整——而取整之后那个整数，就是调度器当天真正的天花板。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-6\">六 · 容量公式的三条边界：异构长度、分页碎片与压缩缓存</h3>\n\n<p>公式本身只是一次除法，真正决定它是否可信的是分母的构造方式。分母 $$2LH_{kv}d_hsb_{kv}\\alpha_{\\text{page}}$$ 隐含了一个前提：批内所有序列共享同一个长度 $$s$$。这个前提在离线批推理里勉强成立，在在线服务里几乎从不成立。真实负载的请求长度服从重尾分布，少数长请求（长文档问答、多轮对话历史、代码仓库上下文）的 KV 占用可以是中位数的数十倍。此时正确的分母不是 $$B\\times s_{\\text{avg}}$$，而是各请求长度之和 $$\\sum_i s_i$$ 再乘以单 token 单层字节数。用平均长度估算并发，等价于假设方差为零；一旦长尾请求同时到达，调度器按估算接纳的请求数会在解码中途撞上显存上限，触发抢占、重算甚至 OOM。工程上的做法是把容量换算从\"平均并发数\"改为\"给定长度分布下的可接纳概率\"：对长度分布做分位数采样，用 $$\\sum_i s_i$$ 的尾部分位而非均值去反解 $$B_{\\max}$$，并给调度器留出与长尾分位匹配的余量。</p>\n\n<p>第二个边界是分页碎片系数 $$\\alpha_{\\text{page}}$$。分页 KV cache 以固定块（block）为单位分配，块大小从 16 到 128 token 不等，最后一个块几乎必然填不满，序列越短、块越大，浪费比例越高。$$\\alpha_{\\text{page}}$$ 不是常数，它随块大小与长度分布漂移：短请求密集时放大系数上升，长请求密集时趋近 1。忽略它会把容量高估 5%–20%，这个区间足以让调度器在稳态下多接纳一到两成请求，然后在显存水位逼近上限时被迫连续抢占，表现为解码吞吐抖动与尾延迟抬升。块大小的选型因此是一个双向权衡：小块降低 $$\\alpha_{\\text{page}}$$ 但增加块表管理与访存间接层开销，大块简化寻址却放大内部碎片。容量规划时应把 $$\\alpha_{\\text{page}}$$ 当作与长度分布耦合的实测参数，而不是写死在配置里的经验值。</p>\n\n<p>第三个边界最容易被忽视：压缩缓存结构会改变公式中 $$H_{kv}$$ 与 $$d_h$$ 的物理含义。GQA 把 KV 头数压到远小于 Q 头数，公式仍成立，只是 $$H_{kv}$$ 取实际 KV 头数而非注意力头数。MLA 则根本不同——它缓存的不是 K 与 V 两份张量，而是每个 token 的潜向量（latent），因子 2 不再对应\"K 与 V 两份\"，$$d_h$$ 也不再是每头维度而是潜向量维度。此时若照搬 $$2LH_{kv}d_hs$$ 会系统性高估或低估容量，偏差方向取决于潜维度与等效 K/V 维度的比值。正确做法是按实际缓存布局重写分母：先数清每层每 token 实际驻留的元素个数，再乘元素字节数。这一步没有通用公式可套，只能对着具体实现的 buffer 布局核对。</p>\n\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>公式需做的修正</th><th>系统代价</th></tr></thead><tbody><tr><td>序列长度异构</td><td>分母用 $$\\sum_i s_i$$ 替代 $$B\\times s$$</td><td>按均值估算导致长尾 OOM 与抢占重算</td></tr><tr><td>分页内部碎片</td><td>$$\\alpha_{\\text{page}}$$ 随块大小与长度分布实测</td><td>容量高估 5%–20%，稳态吞吐抖动</td></tr><tr><td>MLA 等压缩缓存</td><td>按潜向量布局重写 $$H_{kv}$$、$$d_h$$ 与因子 2</td><td>容量估算严重偏离，扩容决策失真</td></tr></tbody></table>\n\n<p>把这三条边界合起来看，$$B_{\\max}$$ 的意义应当从\"一个数\"降级为\"一个带条件的上界\"。它成立的场景是：批内长度近似同构、块大小与长度分布匹配、缓存布局是标准 K/V 双份。离开这三个条件，公式给出的是乐观上界而非可调度容量。分离式解码池按序列数扩容时尤其要注意这一点——扩容依据若取自乐观上界，池子在长尾流量下会持续处于高水位抢占状态，扩容本身反而掩盖了真实的容量缺口。</p>\n<h3 id=\"th-kv-cache-capacity-sec-7\">七 · 逐项拆解：每个因子在显存里对应哪一段物理地址</h3>\n<p>把公式拆成可寻址的物理段，是判断容量估算是否可信的第一步。$$M_{\\text{KV}}=2\\,L\\,H_{kv}\\,d_h\\,s\\,B\\,b_{kv}\\,\\alpha_{\\text{page}}$$ 中，前四个因子 $$L\\cdot H_{kv}\\cdot d_h$$ 构成单层单token的KV元素数，乘 $$s$$ 得到单序列单层的元素总量，乘 $$B$$ 得到批内全部序列的单层元素总量，乘 $$b_{kv}$$ 折算为字节，乘 2 补上K与V两份，最后乘 $$\\alpha_{\\text{page}}$$ 计入分页对齐带来的浪费。工程上应把它读成“每层一张形状为 $$[B,\\,H_{kv},\\,s,\\,d_h]$$ 的张量，K和V各一张”，这样在排查OOM时可以直接定位到是哪一维在膨胀。</p>\n<p>因子2不是常数意义上的“两份”，而是布局意义上的两份独立缓存：K与V在tcgen05 MMA的消费路径上被分别搬运进TMEM附近的共享内存暂存区，二者生命周期相同但地址不连续，因此显存分配器必须为它们各留一份连续池。若采用交错布局（interleaved KV），因子2会被吸收进 $$d_h$$ 的有效宽度里，此时公式形式不变但 $$d_h$$ 的含义从“每头维度”变成“每头K+V拼接维度”，这是重写公式时最容易被忽略的一处。</p>\n<p>$$b_{kv}$$ 是唯一直接受数值精度策略影响的因子。FP8下取1字节，NVFP4下取0.5字节——后者不是“每个元素半个字节”的抽象说法，而是两个4-bit元素打包进一个字节的物理排布，块缩放因子（block scale）另行占用少量额外字节，通常被并入 $$\\alpha_{\\text{page}}$$ 或单列一项。这意味着切到NVFP4时，理论容量翻倍，但实际收益会被缩放因子的元数据开销打折，折扣幅度取决于块大小：块越小，元数据占比越高。</p>\n<p>$$\\alpha_{\\text{page}}$$ 是唯一不对应任何“数据”的因子，它对应的是分配器行为。分页KV cache以固定块（如16或64 token）为单位分配，序列尾部不足一块时整块占用；块越大，尾部浪费越显著；块越小，页表项越多、间接寻址开销越大。因此 $$\\alpha_{\\text{page}}$$ 是块大小与长度分布的联合函数，而不是硬件常数。</p>\n<div class=\"formula\">$$\\text{单序列KV字节}=2\\,L\\,H_{kv}\\,d_h\\,s\\,b_{kv}\\,\\alpha_{\\text{page}},\\qquad \\alpha_{\\text{page}}=\\frac{\\text{实际分配块数}\\times\\text{块字节}}{\\text{理论字节}}$$</div>\n<p>代价侧的直接推论：以B200单卡可用的HBM容量为预算上限，分母每增加一个因子量级，$$B_{\\max}$$ 就同比缩小。举例来说，一个 $$L=80$$、$$H_{kv}=8$$、$$d_h=128$$ 的模型，单token单序列KV为 $$2\\times80\\times8\\times128=163{,}840$$ 元素；FP8下即160 KiB/token，一条8K序列约1.25 GiB，若单卡留给KV的预算为数十GiB量级，则并发上限被压在个位到十位数之间——这正是长上下文场景下容量而非算力成为第一约束的原因。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-8\">八 · 推导关键步：从字节预算到可调度整数</h3>\n<p>推导的起点不是公式本身，而是显存预算的切分。单卡HBM总量减去权重常驻、激活峰值、通信缓冲、框架预留后得到 $$M_{\\text{free}}$$，这个量在运行期是动态的：权重在FP8/NVFP4下压缩后释放出的空间可直接转为KV池，而激活峰值随批大小与序列长上升，会反向挤压KV池。因此 $$M_{\\text{free}}$$ 应写成批大小的函数而非固定值，容量规划时必须用“最坏激活峰值”对应的剩余量代入，否则会在高并发时出现KV池被激活挤占的连锁抢占。</p>\n<p>关键一步是把连续字节预算转成离散序列数：$$B_{\\max}=\\left\\lfloor M_{\\text{free}}/(2LH_{kv}d_hsb_{kv}\\alpha_{\\text{page}})\\right\\rfloor$$。取整不是形式上的修饰——调度器只能接纳整数条序列，而分页分配又要求每条序列至少占一个块，所以真实的接纳上限还要再受“块粒度”约束：当单序列所需块数乘以块字节超过剩余池时，即使字节层面还够，也无法分配。这一步的离散化误差在短序列、大块配置下最明显。</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{page}}=\\left\\lfloor \\frac{M_{\\text{free}}}{\\lceil s/s_{\\text{blk}}\\rceil\\cdot 2\\,L\\,H_{kv}\\,d_h\\,s_{\\text{blk}}\\,b_{kv}}\\right\\rfloor$$</div>\n<p>上式把 $$\\alpha_{\\text{page}}$$ 显式化为块数上取整：$$\\lceil s/s_{\\text{blk}}\\rceil$$ 是单序列占用的块数，乘以每块字节即为真实占用。它与连续形式的差别正是碎片：当 $$s$$ 恰为块大小整数倍时两者相等，否则离散形式更小。工程含义是，块大小选型应与典型序列长度的分布对齐——若绝大多数请求落在8K附近而块为64 token，尾部浪费约为一个块的量级，折算到 $$\\alpha_{\\text{page}}$$ 上落在给定区间的低端；若长度分布弥散，则向高端漂移。</p>\n<p>推导中还有一处近似：把K与V视为等长。实际生成阶段K与V同步增长，这一近似成立；但在分块预填（chunked prefill）与投机解码并存的场景里，草稿token的KV需要额外暂存并在验证后被丢弃或接纳，瞬时占用会短暂超过稳态公式值。容量规划若按稳态值卡满，投机解码的暂存区就会触发瞬时OOM，因此 $$M_{\\text{free}}$$ 中必须预留这部分峰值。</p>\n<p>代价侧：取整与块粒度共同决定了“名义容量”与“可调度容量”之间的差距。以块大小64、序列长8K为例，块数恰为整数倍，离散与连续形式一致；若序列长为8K+1，则多占一块，单序列字节上升约0.8%，在数十并发下累积为可观的比例。这类误差不体现在公式的连续形式里，只能通过离散形式暴露。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-9\">九 · 异构长度：为什么 $$B\\times s$$ 必须换成求和</h3>\n<p>连续批处理下批内序列长度天然异构：有的请求处于预填末尾，有的已生成数千token，有的刚被接纳。此时 $$B\\times s$$ 中的 $$s$$ 若取平均长度，等价于假设所有序列共享同一长度，这在数学上低估了长尾请求的占用。正确形式是把批内各请求的实际缓存长度求和：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\,L\\,H_{kv}\\,d_h\\,b_{kv}\\,\\alpha_{\\text{page}}\\sum_{i=1}^{B}s_i$$</div>\n<p>求和形式与乘积形式的差异完全来自 $$s_i$$ 的离散度。若长度分布方差大，平均值附近的序列占用被高估、长尾序列被低估，净效应取决于分布形状：右偏长尾（少量超长请求）下，平均值低估总占用，因为长尾的字节贡献按长度线性叠加而平均值把它摊平了。工程上这直接对应调度器的接纳判据——必须用“当前所有活跃请求长度之和 + 新请求长度”与剩余池比较，而不是用“并发数 × 平均长度”。</p>\n<p>分页机制在这里提供了缓冲：异构长度不必连续排布，块可以散落在池中，因此求和形式的占用是精确的字节和，碎片只来自每条序列尾部的块内浪费。$$\\alpha_{\\text{page}}$$ 在异构场景下不再是单一系数，而是各序列尾部浪费之和与理论字节之比，随长度分布漂移。给定区间1.05–1.2对应的是典型分布下的经验范围，长度分布越碎，越靠上限。</p>\n<p>具体例子：批内三条序列长度分别为512、4096、16384，平均约6997，若按平均长度乘3估算，得到约20,992 token的占用；按求和则为20,992——两者在此例中恰好接近，因为中位数被长尾拉高。但若分布为512、512、16384，平均5803、乘3得17,409，求和为17,408，差异微小；真正拉开差距的是“平均”被用作接纳阈值时，调度器会误以为还能再塞进一条中等长度请求，而实际剩余池只够短请求。误用发生在判据而非估算本身。</p>\n<p>代价侧：求和形式要求调度器在每次接纳决策时维护活跃序列长度累加值，这是一个O(1)维护、O(B)校验的操作，相对KV搬运的带宽开销可忽略，但它是防止长尾OOM的唯一低成本手段。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-10\">十 · 压缩布局：GQA、MLA与公式重写</h3>\n<p>GQA把 $$H_{kv}$$ 从等于Q头数降到其几分之一，公式形式不变但 $$H_{kv}$$ 的取值必须取实际KV头数而非注意力头数。这一步在工程上常被写错：配置里同时存在num_attention_heads与num_key_value_heads，误用前者会把容量低估数倍，导致调度器过早拒绝请求、吞吐白白损失。GQA的收益正比于Q头数与KV头数之比，这个比值直接进入分母，是容量规划中收益最确定的一项。</p>\n<p>MLA则根本改变了缓存内容：它缓存的是压缩后的潜向量（latent）加位置相关的解耦分量，而非逐头的K与V。此时因子2不再对应K/V两份，$$d_h$$ 也不再是每头维度，公式须按实际布局重写为“每token潜向量维度 × 层数 × 字节数”的形式，且部分实现会额外缓存解耦的RoPE分量，形成两项之和。对MLA套用K/V双份公式，会把容量估算偏离到与实际布局无关的量级——这是给定失效条件中最严重的一条。</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{MLA}}=L\\left(d_c+d_r\\right)s\\,B\\,b_{kv}\\,\\alpha_{\\text{page}}$$</div>\n<p>其中 $$d_c$$ 为潜向量维度、$$d_r$$ 为解耦RoPE分量维度，因子2消失。工程判断是：看到模型配置里出现kv_lora_rank一类字段时，必须切换到潜向量公式，并核对实现是否把RoPE分量单独存放；两者混算会让分母错一个可观的百分比。</p>\n<p>代价侧：压缩布局的直接收益是分母缩小，$$B_{\\max}$$ 上升；但代价转移到计算侧——MLA的解压与吸收需要在MMA前做额外变换，GQA的KV广播在2-SM MMA下要求两个SM读到同一份KV，对共享内存带宽提出更高要求。容量公式只回答“装得下多少”，不回答“装下后跑得多快”，后者属于算子与带宽条目。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-11\">十一 · 精度因子的边界：$$b_{kv}$$ 取0.5时公式还成立吗</h3>\n<p>NVFP4下 $$b_{kv}=0.5$$，公式在字节层面依然成立，但“每元素字节”这一抽象开始失真：4-bit元素以打包形式存放，块缩放因子按固定块大小附带，寻址粒度不再是单元素而是打包字。容量估算若只把 $$b_{kv}$$ 从1改成0.5，会高估收益，因为缩放元数据未被计入。正确做法是把元数据开销并入 $$\\alpha_{\\text{page}}$$ 或单列一项，并在块大小选型时把“每块附带多少缩放因子”算进每块字节。</p>\n<p>精度因子的另一个边界是K与V可以不同精度：部分实现只量化K或只量化V，此时因子2应拆成 $$b_K+b_V$$ 两项而非 $$2b_{kv}$$。这在容量上等价于一个介于FP8与NVFP4之间的有效字节数，公式需相应改写。工程上这种非对称量化常见于对V精度更敏感的场景，容量规划必须按实际配置读取，不能假设对称。</p>\n<p>代价侧：精度下降换来的容量翻倍，其代价体现在注意力输出的数值误差上，误差界属于量化条目，此处只强调容量侧的一个事实——NVFP4的容量收益不是线性的2倍，而是 $$2/(1+\\text{元数据占比})$$，块越小折扣越大。选块大小时要在“缩放精度”与“容量收益”之间取平衡，这是容量规划与数值精度两个条目的交界处。</p>\n<p>具体例子：同一模型在FP8下 $$B_{\\max}$$ 为某值，切NVFP4后理论翻倍；若块缩放因子每32元素附带一个FP8缩放值，则每32个4-bit元素（16字节）附带1字节，元数据占比约6%，实际容量收益约1.88倍而非2倍。这个差额在卡满容量的部署里足以决定是否要多扩一张卡。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-12\">十二 · 从公式到工程判据：三个必须固化的检查</h3>\n<p>第一，分母必须按实际缓存布局构造，而不是按模型名义结构。检查项是：$$H_{kv}$$ 取KV头数、$$d_h$$ 取实际存储维度、因子2是否存在、是否走潜向量布局。任何一项与实现不符，容量估算就失去意义。第二，$$M_{\\text{free}}$$ 必须用最坏激活峰值下的剩余量，且为投机解码暂存与通信缓冲预留。第三，接纳判据必须用长度求和而非并发数乘平均长度，并把 $$\\alpha_{\\text{page}}$$ 按当前长度分布动态估计而非取固定中值。</p>\n<p>这三项固化后，公式的用途才完整：它同时决定分页块大小选型（块大省页表但增碎片，块小反之）、是否启用FP8/NVFP4 KV量化（收益需扣除元数据）、以及分离式解码池按序列数扩容的直接依据——解码池的扩容单位是“能多接纳多少条序列”，而该数正是 $$B_{\\max}$$ 的增量，不是字节增量。</p>\n<p>最后落在机制上：容量公式的每一次误用，最终都表现为调度器接纳了超出物理池的请求，触发抢占与重算，把本可避免的延迟加到用户侧。因此 $$B_{\\max}$$ 不应作为静态配置写入，而应作为运行期由分配器实际剩余块数反推的量，与接纳判据同源。公式给出的是上界与结构，运行期给出的是真实可用量，二者对齐的那一刻，容量规划才从纸面走进调度器。</p>\n<h3 id=\"th-kv-cache-capacity-sec-13\">十三 · 公式成立的三条隐含假设</h3>\n<p>容量式之所以能写成闭式，靠的是三个未被写进符号表的假设，任何一条松动，分母就不再是“单序列 KV 字节”的可靠度量。第一条是<strong>缓存布局同构</strong>：所有层、所有 KV 头、所有 token 的每元素字节数一致，因此可以把 2·L·H<sub>kv</sub>·d<sub>h</sub> 折叠成一个常数系数。第二条是<strong>长度可加性</strong>：批内 B 条序列共享同一个 s，于是总占用等于 B 乘以单序列占用；这在同构批里成立，在异构批里必须换成求和。第三条是<strong>分页系数稳定</strong>：α<sub>page</sub> 只由块大小与对齐粒度决定，与负载无关。工程上真正要盯的是第三条——α<sub>page</sub> 是唯一随运行时状态漂移的因子，而它恰好是容量高估的主要来源。</p>\n<p>把三条假设写成可检验的形式：设第 i 条请求的长度为 s<sub>i</sub>，块大小为 P（token 数），则实际占用为</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{real}}=\\sum_{i=1}^{B}2\\,L\\,H_{kv}\\,d_h\\,b_{kv}\\cdot P\\left\\lceil \\frac{s_i}{P}\\right\\rceil$$</div>\n<p>与闭式相比，差值就是每个请求尾部未填满块的浪费。当 s<sub>i</sub> ≫ P 时该项趋近于 1，公式可用；当大量请求长度落在 P 的量级（短对话、分类头、embedding 短序列），浪费比例迅速抬升，α<sub>page</sub> 从 1.05 滑向 1.2 甚至更高。这就是为什么同一张卡、同一模型，跑长文生成时容量估算很准，切到短请求高并发场景就频频触发抢占。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-14\">十四 · 压缩缓存布局：H<sub>kv</sub> 与 d<sub>h</sub> 被重新定义</h3>\n<p>GQA 把 KV 头数压到 Q 头数的几分之一，公式形式上仍然成立，因为 H<sub>kv</sub> 只是变小了；真正让公式失效的是 MLA 一类<strong>潜向量缓存</strong>。MLA 不缓存逐头的 K 与 V，而是缓存一个低秩潜向量加一个解耦的 RoPE 分量，缓存布局既不是“2 份”也不对应 H<sub>kv</sub>·d<sub>h</sub> 的乘积结构。此时因子 2 失去物理含义，必须按实际张量形状重写分母：</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{MLA}}=L\\,s\\,B\\,b_{kv}\\,\\alpha_{\\text{page}}\\left(d_c+d_r\\right)$$</div>\n<p>其中 d<sub>c</sub> 为潜向量维度、d<sub>r</sub> 为解耦 RoPE 维度，两者之和通常远小于 2·H<sub>kv</sub>·d<sub>h</sub>。误用双份 K/V 公式的后果是<strong>系统性低估容量</strong>——分母被高估，B<sub>max</sub> 被算小，调度器保守接纳，吞吐白白损失；反过来，若把 MLA 的潜向量当成“一份 K”去套 2 倍因子，又会高估。这类偏差不是几个百分点，而是与压缩比同量级，属于必须按框架实际缓存布局重算的情形。工程判断很简单：打开框架的 KV cache 配置，看它声明的每 token 字节数，而不是从模型超参反推。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-15\">十五 · 异构长度：B×s 必须换成求和</h3>\n<p>连续批处理下批内序列长度天然异构，预填请求与解码请求混跑，长尾请求与短请求共存。此时闭式的 B×s 是一个<strong>上界而非估计</strong>：用平均长度代替长度之和，等价于假设所有请求都等于均值，方差被抹平。真实占用由长度分布的二阶矩决定，用平均长度估算的误差量级正比于长度方差。</p>\n<p>设长度分布均值 μ、方差 σ²，则真实占用与均值估算之比约为 1 + σ²/μ²（按块对齐后略有修正）。对话类负载里长尾请求可以比均值长一个数量级，这个比值轻松超过 1.5。后果不是估算偏差，而是<strong>接纳即 OOM</strong>：调度器按均值算出还能塞 40 条，实际第 12 条长请求就把显存吃穿，触发抢占与重算，解码延迟出现尖刺。正确做法是把 B<sub>max</sub> 改成对长度和的预算约束：</p>\n<div class=\"formula\">$$\\sum_{i\\in \\text{batch}} s_i \\le \\frac{M_{\\text{free}}}{2\\,L\\,H_{kv}\\,d_h\\,b_{kv}\\,\\alpha_{\\text{page}}}$$</div>\n<p>即容量式给出的是“token 预算”而非“序列数预算”，序列数只是 token 预算除以典型长度后的派生量。把这条写进调度器的准入判据，长尾请求只会推迟接纳，不会击穿显存。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-16\">十六 · α<sub>page</sub> 的漂移与块大小选型</h3>\n<p>α<sub>page</sub> 不是常数，它是块大小 P 与长度分布的函数。块越大，尾部浪费的绝对 token 越多，但元数据开销越小；块越小，碎片少但页表项多、访存局部性差。容量式把 α<sub>page</sub> 当作 1.05–1.2 的标量，实际选型时必须把它当成可调参数去测：给定负载的长度直方图，扫 P 得到 α<sub>page</sub>(P)，再代回 B<sub>max</sub>。</p>\n<p>代价是双向的。P 偏小（如 16）时 α<sub>page</sub> 接近 1.05，容量好看，但页表项数量随并发线性膨胀，KV 访存的地址翻译与 gather 开销上升，解码 step 的有效带宽下降；P 偏大（如 128）时元数据省了，短请求的尾部浪费把 α<sub>page</sub> 推到 1.2，等效显存减少近两成。这是一个<strong>显存容量与访存效率的兑换</strong>，没有普适最优，只有按负载长度分布定的最优点。容量规划时应把 α<sub>page</sub> 的实测值写进预算表，而不是沿用默认常数。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-17\">十七 · 规模上限：公式在什么量级上先崩</h3>\n<p>公式的第二个失效维度是规模。当 s 进入十万 token 量级、B 进入数百，单序列 KV 字节已经与模型权重同量级，此时三个效应依次出现。其一是<strong>预算口径变化</strong>：M<sub>free</sub> 不再是“总显存减权重”，还要扣掉通信缓冲、激活峰值、框架预留，这些项随 B 与 s 增长，闭式里没有它们的位置。其二是<strong>带宽约束接管</strong>：容量够不代表跑得动，解码每步要把整个 KV 读一遍，带宽成为新瓶颈，容量式给出的 B<sub>max</sub> 只是必要不充分条件。其三是<strong>分页层级</strong>：超长序列下两级分页、前缀共享、KV 卸载到主机内存等机制介入，占用不再由单卡显存独占描述。</p>\n<p>因此容量式的适用上限可以这样界定：它给出的是<strong>显存准入的硬边界</strong>，在中等长度、同构批、单一缓存布局下精度足够；一旦跨入超长序列或异构混跑，它退化为上界估计，必须与带宽模型、卸载策略联合使用。工程上判断是否越界，看两个比值：单序列 KV 字节 / 可用显存，以及 KV 读取字节 / 单步可用带宽。前者逼近 1 说明容量式是主约束，后者逼近 1 说明带宽已经接管，此时再优化 α<sub>page</sub> 收益有限，该转向 KV 量化（FP8 取 1、NVFP4 取 0.5 直接减半分母）或前缀共享。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-18\">十八 · 失效判据的工程落地</h3>\n<p>把上述边界转成运行时可判的几条规则，比记住公式更有用。第一，准入判据用 token 预算而非序列数预算，长度和超预算即排队，避免均值估算的 OOM。第二，α<sub>page</sub> 按当前块大小与近期长度分布定期重估，容量表随负载滚动更新，而不是开机算一次。第三，缓存布局变更（切 GQA/MLA、开 KV 量化、改块大小）必须触发分母重算，禁止跨布局复用旧容量数。第四，当单序列 KV 字节超过可用显存的固定比例时，容量式让位于带宽与卸载模型，调度目标从“塞满”转为“稳住解码 step 时间”。</p>\n<p>最容易被忽略的是第三条：量化把 b<sub>kv</sub> 从 1 降到 0.5，分母减半，B<sub>max</sub> 翻倍，但若框架仍按 FP8 布局分配页、按旧块大小对齐，α<sub>page</sub> 会因半字节对齐而变差，实际增益小于名义值。容量式的每一次参数变更都要连带重测 α<sub>page</sub>，否则公式给的是纸面上限，不是可调度上限。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-19\">十九 · 容量式在压缩缓存、异构长度与分页漂移下的失效边界</h3>\n<p>容量式成立的前提是“每层缓存两份形状为 <em>H<sub>kv</sub></em>×<em>d<sub>h</sub></em> 的 K/V 张量”，一旦模型改用 MLA 一类压缩结构，这个前提直接崩掉。MLA 在推理期缓存的是每层的潜向量（latent）加一个解耦的 RoPE 分量，其每 token 字节数由潜维 <em>d<sub>c</sub></em>、RoPE 维 <em>d<sub>r</sub></em> 与层数共同决定，而不是 <em>2LH<sub>kv</sub>d<sub>h</sub></em>。此时若仍套用双份 K/V 公式，分母与实际缓存布局偏离，<em>B</em><sub>max</sub> 的估算会系统性失真——按 K/V 双份算出的单序列字节往往远大于潜向量布局，容量被低估；反之若潜维配置较高又可能低估占用。工程上的正确做法是把公式重写为按“每 token 每层实际写入的字节数”求和：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=\\sum_{l=1}^{L}\\big(s\\cdot b_{\\text{layer},l}\\big)\\cdot B\\cdot\\alpha_{\\text{page}},\\qquad b_{\\text{layer},l}=\\begin{cases}2H_{kv}d_h b_{kv} &amp; \\text{GQA/MHA}\\\\ (d_c+d_r)\\,b_{kv} &amp; \\text{MLA}\\end{cases}$$</div>\n<p>这条重写版的代价在于：它不再是闭式可解析的单一乘积，容量规划工具必须从模型的缓存布局描述（每层 dtype、每层潜维、是否共享 RoPE 缓存）里逐层累加，规划脚本与运行时 allocator 的字节口径必须严格一致，否则调度器按估算接纳的请求数与实际可分配块数对不上，表现为接纳后立即抢占。以 GB200 NVL72 单卡承载长上下文解码池为例，MLA 模型若沿用 K/V 双份口径做扩容决策，解码池按序列数扩容的斜率会整体偏移，扩容收益被高估或低估，属于典型的“公式对了但布局错了”的失效。</p>\n<p>第二个失效条件是序列长度异构。容量式的 <em>B</em>×<em>s</em> 隐含“所有并发序列等长”的假设，而真实服务里预填与解码混跑、请求长度呈长尾分布，正确口径是各请求长度之和 <em>Σs<sub>i</sub></em> 而非 <em>B</em>×<em>s̄</em>。用平均长度估算的后果不是精度损失而是硬失效：当长尾请求进入，实际占用超过 <em>M</em><sub>free</sub>，allocator 分配失败触发 OOM 或强制抢占，正在解码的序列被换出再换入，尾延迟被放大。可调度上限应改为按长度和的约束：</p>\n<div class=\"formula\">$$\\sum_{i=1}^{B}s_i\\;\\le\\;\\frac{M_{\\text{free}}}{2LH_{kv}d_hb_{kv}\\alpha_{\\text{page}}}$$</div>\n<p>这条约束把“最大并发数”从一个标量变成了一个随请求长度分布漂移的可行域，调度器必须在接纳时做在线求和校验，而不是查一张静态的 <em>B</em><sub>max</sub> 表。代价体现在调度路径上：每次接纳多一次累加与比较，换来的是长尾场景下不 OOM；若省掉这一步，抢占带来的重算预填开销远高于校验成本。</p>\n<p>第三个失效条件是 <em>α</em><sub>page</sub> 不是常数。分页块越大、序列长度分布越碎，块内尾部浪费与对齐填充越显著，<em>α</em><sub>page</sub> 随块大小与长度分布漂移，典型区间 1.05–1.2。容量式把 <em>α</em><sub>page</sub> 当固定系数代入，等于假设碎片率不随负载变化；当块大小选型偏大或短请求占比升高，实际碎片率上移，容量被高估 5%–20%，调度器接纳过多请求后被迫抢占。反过来，为压低 <em>α</em><sub>page</sub> 而选极小分页块，会抬高块表管理与寻址开销，解码步的访存效率下降。因此块大小选型本质是在碎片放大与元数据开销之间取平衡，容量式只能给出该平衡点附近的估算，不能替代基于实测长度分布的 <em>α</em><sub>page</sub> 标定。三者叠加时的判断很直接：只要模型缓存布局非 K/V 双份、或长度分布长尾显著、或块大小偏离标定工况，容量式就从“规划依据”退化为“量级参考”，真正的接纳决策必须回到运行时按实际块占用做校验。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-20\">二十 · 容量式在压缩缓存与异构长度下的失效边界</h3>\n<p>公式的成立前提是缓存布局为“每层两组K/V张量、头数与头维在层间恒定”。一旦模型改用MLA一类压缩结构，这个前提直接崩塌：缓存中驻留的是每层一份低秩潜向量（外加解耦的RoPE分量），既没有K与V两份之分，也不存在按H_kv×d_h展开的头维语义。此时因子2必须删除，H_kv与d_h要被潜向量维度与层数上的实际字节布局替代，B_max的分母需按真实缓存张量形状重新推导，而不是把MLA的等效头数硬塞进旧式。工程后果是双向的：沿用K/V双份公式会高估容量、调度器超发请求；反过来若按潜向量维度粗略折算又常低估，白白牺牲并发。判断标准只有一条——分母必须逐字节对应分配器实际申请的缓存块。</p>\n<p>第二个失效条件是序列长度异构。B×s只在所有请求等长时成立，真实负载下应替换为各请求长度之和：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2LH_{kv}d_hb_{kv}\\alpha_{\\text{page}}\\sum_{i=1}^{B}s_i,\\qquad B_{\\max}\\ \\text{由}\\ \\sum_i s_i\\le M_{\\text{free}}/(2LH_{kv}d_hb_{kv}\\alpha_{\\text{page}})\\ \\text{隐式给出}$$</div>\n<p>用平均长度代入相当于把长尾请求的峰值需求摊平，一旦出现远超均值的长序列，已接纳的batch会同时越过显存红线，触发抢占与重算，解码延迟出现尖刺。容量规划应取长度分布的高分位而非均值来定B_max，把均值留给吞吐估算。</p>\n<p>第三个漂移项是α_page。它并非常数，而随分页块大小与长度分布变化：块越大、序列尾部浪费越多，短请求密集时放大更明显。典型区间1.05–1.2意味着忽略它会把容量高估5%–20%，恰好是调度器“看起来还能再塞几个请求”的那段危险余量。块大小选型因此是容量与碎片之间的显式权衡，而非实现细节。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式需做的改写</th><th>系统代价</th></tr></thead><tbody><tr><td>MLA等压缩缓存</td><td>去掉因子2，按潜向量布局重写分母</td><td>容量估算偏离实际，超发或保守</td></tr><tr><td>长度异构</td><td>B×s换成Σs_i</td><td>长尾触发OOM与抢占，解码抖动</td></tr><tr><td>α_page漂移</td><td>按块大小与长度分布实测取值</td><td>高估5%–20%，被迫抢占</td></tr></tbody></table>\n<p>规模上限还受另一层约束：当单序列KV字节已接近单卡可用显存时，B_max退化为1，此时容量式不再回答“能装多少并发”，而转为回答“单条最长序列能否放下”，规划重心从批调度转向序列切分与分离式解码池扩容。</p>\n<h3 id=\"th-kv-cache-capacity-sec-21\">二十一 · 从显存余量到可调度上限：B_max 的取整语义</h3>\n<p>容量决策的第一步不是算总量，而是算<strong>可被调度器兑现的并发数</strong>。$$B_{\\max}$$ 的取整不是数学修饰，而是工程契约：向下取整意味着分母中任何一个因子被低估，都会让接纳的请求数超过物理可容纳量，抢占（preemption）与重算随之发生。工程上应把 $$M_{\\text{free}}$$ 定义为权重、激活峰值、通信缓冲、CUDA 上下文与框架预留之后的<em>净余量</em>，而不是标称 HBM 容量减去权重。激活峰值在长序列预填阶段会显著抬升，因此同一张卡在“预填为主”和“解码为主”两种负载下的 $$M_{\\text{free}}$$ 并不相同，容量表必须按负载形态分别标定。</p>\n<p>取整还带来一个常被忽略的副作用：当单序列 KV 字节接近 $$M_{\\text{free}}$$ 时，$$B_{\\max}$$ 从 2 掉到 1，吞吐断崖式下跌而非线性下降。因此调度器不应把 $$B_{\\max}$$ 当作硬上限直接填满，而应保留一个安全水位（例如按 $$B_{\\max}-1$$ 或乘以 0.9 的接纳阈值），把余量留给突发长请求与分页块对齐。伪代码思路：</p>\n<div class=\"formula\">$$\\text{accept}(r)=\\big(\\text{used}+\\text{kvbytes}(r)\\cdot\\alpha_{\\text{page}}\\big)\\le \\gamma\\,M_{\\text{free}},\\quad \\gamma\\in(0,1]$$</div>\n<p>其中 $$\\text{kvbytes}(r)=2LH_{kv}d_hs_rb_{kv}$$ 按该请求的<em>实际长度</em>计算，而非全局平均长度。这条接纳判据把公式从“静态容量表”变成“在线准入控制”，是连续批处理与分页分配器之间的接口。代价体现在延迟上：$$\\gamma$$ 越小，抢占越少但并发越低，解码吞吐下降；$$\\gamma$$ 越接近 1，OOM 风险与抢占重算的尾延迟上升。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-22\">二十二 · 定批大小：用长度之和而非 B×s</h3>\n<p>异构长度是容量估算失真的主因。公式中的 $$B\\times s$$ 只在所有序列等长时成立；真实负载下必须用 $$\\sum_i s_i$$ 替换。举例：单卡净余量按某模型布局可容纳的 KV 字节记为 $$M_{\\text{free}}$$，若 8 条请求平均长度 4K，但其中 2 条为 32K 长尾，则按平均值估算的占用与实际占用相差数倍，调度器会在接纳第 7、8 条时触发 OOM。正确做法是把批大小决策拆成两层：<em>字节预算层</em>用长度之和约束，<em>序列数层</em>用 $$B_{\\max}$$ 约束，两者同时满足才接纳。</p>\n<p>由此得到批大小的工程判据：设当前已用 KV 字节为 $$U$$，候选请求集 $$\\mathcal{R}$$，则</p>\n<div class=\"formula\">$$B^{*}=\\max\\Big\\{|\\mathcal{S}|:\\ \\sum_{r\\in\\mathcal{S}}\\text{kvbytes}(r)\\le \\gamma M_{\\text{free}}-U\\Big\\}$$</div>\n<p>这是一个带权背包的贪心近似：按长度升序接纳可最大化序列数（利于解码吞吐），按长度降序接纳可最大化单请求完成率（利于尾延迟 SLO）。选择哪种排序，取决于该副本承载的是吞吐型流量还是延迟敏感型流量。代价明确：升序接纳会让长请求排队更久，P99 首 token 时间恶化；降序接纳则让短请求被长请求“堵门”，平均吞吐下降。工程判断是——解码池用升序，预填池用降序或按 SLO 分级。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-23\">二十三 · 定并行度：TP 与 DP 的容量换算</h3>\n<p>张量并行（TP）把每层权重切分到多卡，KV 头也随之切分，因此单卡 KV 字节的分母中 $$H_{kv}$$ 变为 $$H_{kv}/N_{\\text{TP}}$$（在 KV 头可整除的前提下）。这意味着 TP 增大时单卡可容纳的序列数近似按 TP 倍数增长，但每 token 的解码要跨越 TP 组做 all-reduce，通信开销随 TP 上升。容量换算因此不是“TP 越大越好”，而是：</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{TP}}=\\left\\lfloor\\frac{M_{\\text{free}}}{2L\\,(H_{kv}/N_{\\text{TP}})\\,d_h\\,s\\,b_{kv}\\,\\alpha_{\\text{page}}}\\right\\rfloor$$</div>\n<p>数据并行（DP）则相反：每卡持有完整权重与完整 KV 头，$$B_{\\max}$$ 不随 DP 变化，但副本数线性放大总吞吐与总容量。工程上定并行度的顺序是：先用 TP 把单副本装进显存并满足单请求延迟，再用 DP 复制副本来满足总并发与冗余。一个具体例子：某模型在 FP8 KV 下单卡只能容纳个位数长序列，TP=4 后单卡 KV 分母缩小 4 倍，可容纳序列数上升，但每步解码多出三次跨卡归约；若该副本的瓶颈在解码延迟而非容量，则 TP=4 是净损失。判断依据是 roofline：当解码已进入带宽受限区，TP 带来的容量收益需与 all-reduce 的固定延迟做对比。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-24\">二十四 · 定 KV 预算：b_kv 与 α_page 的联合选型</h3>\n<p>KV 量化是容量杠杆中最直接的一档：$$b_{kv}$$ 从 FP8 的 1 降到 NVFP4 的 0.5，分母减半，$$B_{\\max}$$ 近似翻倍。但这条杠杆与数值精度耦合——KV 量化误差会沿序列累积，长上下文下注意力分数的扰动被放大，因此不能只看容量收益。工程做法是把 KV 预算拆成“容量预算”和“精度预算”两条线：容量线用 $$b_{kv}$$ 换算 $$B_{\\max}$$，精度线用任务侧的接受准则（长文检索、多轮一致性）做准入，二者冲突时优先保精度、用 DP 扩容而非降精度。</p>\n<p>$$\\alpha_{\\text{page}}$$ 是另一条被低估的杠杆。分页块越大，碎片越少但内部浪费越多；块越小，对齐浪费下降但元数据与分配开销上升。典型 1.05–1.2 的放大系数意味着：忽略它会把容量高估 5%–20%，在 $$B_{\\max}$$ 只有个位数的场景下，这直接等于多接纳一到两条请求后被迫抢占。选型判据是让块大小与长度分布匹配——长度集中在块大小整数倍附近时 $$\\alpha_{\\text{page}}$$ 接近下界，长度高度离散时向上漂移。KV 预算的最终形式应写成：</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{budget}}=\\sum_{r}\\text{kvbytes}(r)\\cdot\\alpha_{\\text{page}}(r)\\le \\gamma M_{\\text{free}}$$</div>\n<p>其中 $$\\alpha_{\\text{page}}(r)$$ 按请求长度与块大小的对齐关系逐请求估计，而非全局常数。代价是分配器需要维护按长度分桶的碎片统计，增加少量 CPU 开销，换来的是接纳决策不再系统性高估。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-25\">二十五 · 定 SLO：把容量式反解为时延约束</h3>\n<p>SLO 与容量的连接点是“每序列每 token 的 KV 读取字节”。解码一步需读取全部历史 KV，故单序列每步字节为 $$2LH_{kv}d_hs b_{kv}$$，批内总读取为各序列之和。当该总量超过 HBM 带宽乘以步长时间，解码即进入带宽受限，步时间随批大小线性上升，TPOT 恶化。因此给定 TPOT SLO，可反解出批大小的上界：</p>\n<div class=\"formula\">$$B_{\\text{slo}}=\\left\\lfloor\\frac{\\text{BW}\\cdot t_{\\text{TPOT}}}{\\sum_{r}\\text{kvbytes}(r)}\\right\\rfloor$$</div>\n<p>这个上界与 $$B_{\\max}$$ 取小者，才是真正可承诺的并发。举例：某副本 $$B_{\\max}$$ 允许较多并发，但按 TPOT SLO 反解出的 $$B_{\\text{slo}}$$ 更小，则瓶颈在带宽而非容量，扩容应走 DP 而非继续加批。反之若 $$B_{\\max}$$ 更小，瓶颈在容量，应优先考虑 KV 量化或 TP。这条判据把“定 SLO”从经验调参变成两界比较：容量界与带宽界，谁小谁决定副本形态。分离式部署中，解码池按序列数扩容的直接依据正是 $$B_{\\max}$$，而预填池的扩容依据是算力与激活峰值，两者不可混用同一张容量表。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-26\">二十六 · 算例：一次完整的容量决策链</h3>\n<p>设某副本权重与激活预留后净余量记为 $$M_{\\text{free}}$$，模型层数 $$L$$、KV 头数 $$H_{kv}$$、头维 $$d_h$$ 给定，KV 采用 FP8（$$b_{kv}=1$$），分页块按长度分布估得 $$\\alpha_{\\text{page}}=1.15$$。取一批请求：4 条 8K、2 条 16K、1 条 32K，长度之和为 96K token。先算单序列每 token KV 字节 $$2LH_{kv}d_h$$，再乘长度之和与 $$\\alpha_{\\text{page}}$$，得到该批的 KV 占用估计；与 $$\\gamma M_{\\text{free}}$$ 比较，若超出则按长度升序裁剪，先移除 32K 长请求，重算后接纳。随后用 $$B_{\\max}$$ 校验序列数上限，用 $$B_{\\text{slo}}$$ 校验 TPOT 约束，三者取小得到最终接纳集。</p>\n<p>若该批在 FP8 下超出预算，切换到 NVFP4（$$b_{kv}=0.5$$）可使占用减半，但需通过长上下文精度准入；若不接受精度损失，则改用 TP=2 使单卡 $$H_{kv}$$ 减半，代价是每步解码多一次跨卡归约。若 $$\\alpha_{\\text{page}}$$ 被误设为 1.0，估算占用偏低约 13%，调度器会多接纳约一条 8K 请求，在下一个长请求到达时触发抢占与重算——这正是容量式在工程中最常见的失效路径。决策链的落点是：容量式给出的是<em>上界</em>，SLO 与带宽给出的是<em>可达上界</em>，实际接纳必须同时满足两者，并为 $$\\alpha_{\\text{page}}$$ 的漂移留出固定余量。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-27\">二十七 · 容量式落到调度器：从字节预算到接纳上限的换算边界</h3>\n<p>把 \\(B_{\\max}\\) 直接当作调度器的并发上限是危险的，因为分母里的 \\(s\\) 不是一个常数，而是一个随请求集合变化的随机变量。工程上正确的做法是把容量式改写成“字节账本”形式：对当前在跑的请求集合 \\(\\mathcal{R}\\)，实际占用是 \\(\\sum_{r\\in\\mathcal{R}} 2LH_{kv}d_h s_r b_{kv}\\) 再乘分页放大，而不是 \\(B\\times s\\) 再乘放大。这意味着接纳决策不能只查一个预先算好的 \\(B_{\\max}\\)，而要维护一个剩余字节计数器，每接纳一个请求就按它声明的最大长度（而非当前长度）预扣额度，解码过程中按块增长逐次追加。预扣制的好处是把长尾风险前移：一个声明 32K 上下文的请求在进入时就把最坏占用记入账本，避免它在解码中途把池子撑爆。代价是接纳阶段的有效并发下降——短请求被迫等待长请求释放预扣额度，调度器需要在“预扣全额”与“按需增长”之间选一种策略，前者安全但吞吐受损，后者吞吐高但需要抢占机制兜底。</p>\n<p>分页碎片系数 \\(\\alpha_{\\text{page}}\\) 不是标定一次就能固定使用的常数，它随块大小与长度分布漂移，这是容量式在长期运行中最容易失效的地方。块越大，尾部浪费越严重，\\(\\alpha\\) 越接近上界；长度分布越集中于块边界附近，浪费越小。设块大小为 \\(p\\) 个 token，单序列尾部期望浪费约为 \\(p/2\\) 个 token 的 KV 字节，则有效放大可写成 \\(\\alpha\\approx 1+\\frac{p}{2\\bar{s}}\\)，其中 \\(\\bar{s}\\) 是该时刻活跃序列的平均长度。这个式子说明：在长上下文场景（\\(\\bar{s}\\) 大）放大系数趋近 1，块大小选型可以放宽；在短请求密集的对话场景，\\(\\alpha\\) 显著抬升，此时若仍按 1.05 估算，容量高估可达 5%–20%，调度器接纳过多请求后只能靠抢占回收，表现为解码被中断、TTFT 抖动。因此块大小选型本身就是容量决策：小块降低 \\(\\alpha\\) 但增加页表开销与访存碎片，大块反之。</p>\n<p>量化位宽 \\(b_{kv}\\) 进入分母的方式是线性的，这让 FP8 与 NVFP4 的收益看起来直白——\\(b_{kv}\\) 从 1 降到 0.5，理论并发翻倍。但这条路径有两个边界。其一，量化只压缩 KV 的存储字节，不改变 MMA 读取 KV 时的有效带宽需求，若解码阶段受限于 KV 带宽而非容量，降位宽换来的并发无法转化为吞吐，反而因反量化引入额外算力开销。其二，容量式假设 K 与 V 同精度同布局，混合精度（如 K 用 FP8、V 用 NVFP4）会破坏因子 2 的对称性，必须拆成两项分别计算。工程判断是：当瓶颈是“装不下更多并发”时降位宽；当瓶颈是“单序列解码太慢”时，降位宽对延迟几乎无益，应转向并行度与批调度。</p>\n<p>并行度决策与容量式耦合在张量并行上：TP 把 \\(L\\) 与 \\(H_{kv}\\) 按卡切分，单卡分母缩小，但每卡 \\(M_{\\text{free}}\\) 也被权重与激活挤占，且 TP 通信使解码步延迟上升。设 TP 度为 \\(t\\)，单卡 KV 分母近似变为原分母的 \\(1/t\\)（层或头被切分），单卡并发上限随之上升，但端到端吞吐受限于最慢的通信环节。分离式部署中，这个换算直接决定解码池按序列数扩容的规模：预填池按 token 吞吐定容量，解码池按 \\(B_{\\max}\\) 定卡数，两池之间的 KV 传输量正比于序列长度与层数，成为 NIXL 通道上的带宽成本。容量式在此的角色不是给出一个漂亮数字，而是把“每卡能挂多少序列”翻译成“解码池要几张卡、通道要多宽”，任何对 \\(\\alpha\\) 或 \\(b_{kv}\\) 的乐观假设都会在这条链路上被放大成实打实的卡数与带宽账单。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>容量式中的敏感变量</th><th>误判后果</th></tr></thead><tbody><tr><td>批大小上限</td><td>长度之和替代 \\(B\\times s\\)</td><td>长尾请求 OOM、抢占</td></tr><tr><td>分页块大小</td><td>\\(\\alpha_{\\text{page}}\\) 随 \\(p/\\bar{s}\\) 漂移</td><td>容量高估 5%–20%</td></tr><tr><td>KV 量化开关</td><td>\\(b_{kv}\\) 线性缩放</td><td>带宽瓶颈下收益落空</td></tr><tr><td>解码池卡数</td><td>分母按 TP 切分</td><td>通道带宽与卡数错配</td></tr></tbody></table>\n<h3 id=\"th-kv-cache-capacity-sec-28\">二十八 · 误用一：用平均序列长冒充长度之和</h3>\n<p>容量式里那个 <code>s</code> 是单序列长度，乘上批大小 <code>B</code> 才得到总占用的近似。工程上最常见的偷懒做法，是把线上请求的长度分布压成一个均值 <code>s̄</code>，然后直接算 <code>B_max = M_free / (2LH_kv d_h s̄ b_kv α)</code>。这一步在数学上就把「各请求长度之和」替换成了「批大小 × 平均长度」，而两者只有在所有请求长度完全相等时才相等。真实负载的长度分布是重尾的：少数请求带几万 token 的历史，多数请求只有几百 token。均值被长尾拉高，但真正决定显存峰值的是<strong>当前驻留批里最长那几条之和</strong>，不是均值乘以条数。</p>\n<p>识别这类误用的方法很直接：把调度器某一时刻的驻留请求逐条列出，算 <code>Σ s_i</code>，再和 <code>B × s̄</code> 对比。若比值明显大于 1，说明均值模型在低估峰值。更隐蔽的一种是把均值算在「已完成请求」上而非「驻留请求」上——已完成集合天然偏向短请求，均值被系统性压低，容量被高估得更厉害。</p>\n<p>后果是 OOM 与抢占的连锁反应。调度器按均值接纳了 <code>B</code> 条请求，长尾请求一进来，分页分配器找不到空闲块，触发抢占（preemption）：要么换出到主机内存再换回，要么直接重算（recompute）。换出换回吃掉 PCIe 带宽并拉长首 token 之外的每 token 延迟；重算则把已经算过的 prefill 白扔一遍，直接抬高算力开销。两者都让 goodput 塌陷——吞吐数字看着还在，有效产出却掉了。正确做法是在接纳决策时用<strong>当前驻留集合的实际长度之和</strong>做约束，并把新请求的长度作为增量项判断，而不是拿一个全局均值去乘。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-29\">二十九 · 误用二：把 α_page 当成常数 1</h3>\n<p>分页碎片系数 <code>α_page</code> 典型落在 1.05–1.2，它的来源是块粒度对齐：每个序列的 KV 按固定块大小（例如 16 或 32 token）分配，最后一块几乎必然填不满，浪费的部分就是内部碎片；块大小越大、序列越短，浪费比例越高。忽略它等于把容量高估 5%–20%，而且这个偏差不是均匀的——短序列密集的负载偏差更大。</p>\n<p>识别方式是做一次账实核对：用分配器的实际占用块数乘以块字节数，得到真实占用，再和公式算出的理论占用比。若比值稳定高于 1 且随块大小增大而上升，说明 α 被漏掉了。另一个信号是「理论剩余显存够、实际分配失败」反复出现，且失败点集中在短请求批量涌入时。</p>\n<p>后果不是单次 OOM，而是调度器的接纳策略持续偏乐观：它以为还能再塞几条，实际每塞一条都在透支碎片余量。等到余量耗尽，抢占集中爆发，表现为延迟毛刺而非平滑退化——这对 SLO 是最坏的一种失效形态，因为容量规划阶段看不出来，上线后才在长尾延迟上暴露。工程上的修法是把 α 显式建模进接纳判断，并让块大小选型与长度分布匹配：短序列为主时用小块降碎片，长序列为主时用大块降元数据开销，这个权衡本身就要用 α 来量化。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-30\">三十 · 误用三：对 MLA 套用 K/V 双份公式</h3>\n<p>公式里的因子 2 对应 K 与 V 两份缓存，这个前提在 MHA/GQA 下成立。但 MLA（Multi-head Latent Attention）缓存的是<strong>压缩后的潜向量</strong>，不是每头独立的 K 和 V。此时 <code>H_kv</code> 与 <code>d_h</code> 的物理含义已经变了：缓存布局里是一条（或少数几条）低秩潜向量，每 token 的字节数由潜维度决定，而不是「头数 × 头维 × 2」。继续套用 <code>2LH_kv d_h</code> 会得到与真实布局严重偏离的数字——偏离方向取决于你把潜维度错当成什么，可能高估也可能低估，但一定不可信。</p>\n<p>识别方法：直接读推理框架里该模型的 KV 缓存张量形状与 dtype，算出每 token 字节数，再和公式预测值比。凡是对不上，就说明公式的变量定义需要按实际缓存布局重写，而不是调参凑数。这一步在容量规划里必须做，因为 MLA 类模型的单序列 KV 字节往往比同规模 GQA 模型小一个量级，套错公式会让「单卡能装多少并发」的判断整体失准。</p>\n<p>后果在分离式部署里最严重：解码池按序列数扩容的直接依据就是单序列 KV 字节，估错方向会导致池子开得过大（浪费卡）或过小（频繁拒绝与排队）。前者是成本问题，后者是 SLO 问题，而两者都源于同一个没被验证的假设。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-31\">三十一 · 反例：一次把三个误用叠在一起的容量估算</h3>\n<p>设某解码池要决定单卡并发上限。工程师拿到线上统计：平均序列长 <code>s̄</code>、平均每请求字节数，直接代入 <code>B_max = ⌊M_free / (2LH_kv d_h s̄ b_kv)⌋</code>，α 取 1，且模型是 MLA 结构却沿用了 K/V 双份形式。三个误用叠加：均值代替长度之和（低估峰值）、α=1（高估 5%–20%）、MLA 套错布局（方向不定）。</p>\n<p>上线后的现象是教科书式的：平时吞吐平稳，一旦有一批带长历史的请求同时驻留，分页分配器瞬间打满，抢占集中触发，换出换回把解码延迟拉出长毛刺，重算又把 prefill 算力重复消耗一遍。监控上看到的是「显存利用率长期偏低但周期性 OOM」——这个组合本身就是误用的指纹：利用率偏低说明均值模型在多数时间过度保守地留了余量，周期性 OOM 说明峰值模型严重低估。</p>\n<p>正确的复核流程是三步：第一，用驻留集合的 <code>Σ s_i</code> 替代 <code>B × s̄</code> 做峰值判断；第二，用分配器实际块数反推 α 并纳入接纳决策；第三，对 MLA 类模型直接从缓存张量形状读出每 token 字节数，重写容量式的分母。三步都做完，容量式才从「纸面公式」变成「可调度的上限」。容量规划的第一约束是显存，而显存估算的可靠性取决于分母是否真的对应缓存布局——分母错一项，取整后的 <code>B_max</code> 就不是保守或激进的问题，而是没有物理意义。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-32\">三十二 · 把误用检测做成常驻检查</h3>\n<p>误用不会因为被写进文档就消失，它会在模型换代、负载漂移、块大小调整时重新出现。可行的工程判断是把三个检查做成常驻项：其一，每类模型上线前用缓存张量形状核对每 token 字节数，与公式预测值对齐后才允许进入容量表；其二，调度器在接纳路径上实时维护驻留长度之和与已分配块数，用账实比监控 α 的漂移，比值越界即告警；其三，把「显存利用率低但 OOM 频发」设为独立告警规则，因为它几乎总指向均值模型与峰值模型的错配。这三项都不增加推理热路径开销，却能把容量式从一次性推导变成持续可信的约束。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-33\">三十三 · 容量式失效的三种典型误用与识别信号</h3>\n<p>容量式最容易被误用的地方，不是公式本身写错，而是把<strong>稳态平均</strong>当成<strong>瞬时上界</strong>。工程上常见做法是拿离线评测的平均序列长度 s̄ 代入分母，得到 B_max 后直接配给调度器的 max_num_seqs。问题在于连续批处理下每个在飞请求的长度是异步增长的，分母里的 s 应当替换为当前驻留请求长度之和 Σs_i，而不是 B×s̄。当长度分布呈长尾（少量请求携带超长上下文或长生成），Σs_i 会显著高于 B×s̄，此时按平均长度算出的并发上限在执行中被击穿，表现为：调度器已接纳 B 个请求，但分页分配器在某个 step 找不到空闲块，触发抢占（preemption）与重算，吞吐骤降而延迟毛刺抬升。识别信号很直接——监控 <em>实际占用块数 / 预算块数</em> 的比值随时间单调爬升并逼近 1，同时 preemption 计数非零，就说明容量式被当成了平均值公式在用。</p>\n<p>第二个误用是丢掉 α_page。分页分配以块为粒度，块内尾部空隙、块大小与长度分布不匹配、对齐填充都会放大实际占用。α_page 典型落在 1.05–1.2，直接忽略它等于把可用并发高估 5%–20%。这个误差不会在短序列、均匀长度下暴露，却会在块较大而请求偏短时集中体现：大量请求各占一块、块内大半空置，物理块消耗远超按字节算出的理论值。识别方式是拿分配器统计的<em>已分配块数×块字节</em>与<em>按 Σs_i 算出的理论字节</em>做比值，该比值就是实测 α_page；若它稳定高于配置里假设的值，说明块大小选型与长度分布不匹配，应缩小块或改用更细粒度分页，而不是继续调大 max_num_seqs。容量式在这里的作用不是给出一个数，而是给出一个必须被实测校准的系数。</p>\n<p>第三个、也是最隐蔽的误用，是对压缩缓存结构照搬 K/V 双份公式。GQA 下 H_kv 远小于 Q 头数，公式尚可沿用但必须用真实的 KV 头数；而 MLA 缓存的是潜向量（latent），既不是 K 也不是 V，因子 2 与 d_h 的定义都不再成立，缓存布局变成每层一份低秩潜表示加解耦的 RoPE 分量。此时若仍按 2·L·H_kv·d_h 估算，容量偏差不是几个百分点而是成倍偏离，且方向不确定——可能高估导致 OOM，也可能低估导致显存闲置、并发上不去。识别信号是：按公式预算分配的块数与分配器实际能容纳的序列数长期对不上，且换用不同模型（GQA 与 MLA 混部）时偏差方向翻转。正确做法是按实际缓存布局重写分母，把每 token 每层的真实字节数作为唯一可信量，公式只保留“预算除以单序列字节”这一层结构。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>以平均长度代 Σs_i</td><td>长尾下 OOM、抢占重算</td><td>占用/预算比逼近 1 且 preemption 非零</td></tr><tr><td>忽略 α_page</td><td>并发高估 5%–20%</td><td>实测块字节/理论字节持续高于假设值</td></tr><tr><td>对 MLA 套 K/V 双份式</td><td>容量成倍偏离、方向不定</td><td>混部模型时偏差翻转、预算与实际长期不符</td></tr></tbody></table>\n<p>一个具体反例：某解码池按平均长度 2K 配了 max_num_seqs，分母用 B×s̄ 估算，未计 α_page，且模型为 MLA。上线后短请求阶段一切正常，一旦长上下文请求进入，Σs_i 迅速抬升，分页分配器在若干 step 后无块可分配，调度器被迫抢占最早请求并重算其全部历史 KV，单步延迟出现数量级毛刺；与此同时显存监控显示预算已被打满，但有效吞吐反而下降。把分母改为 Σs_i、把 α_page 换成实测值、并按 MLA 潜向量布局重算单 token 字节后，同样的显存预算下可稳定驻留的序列数下降，但抢占归零、尾延迟收敛。这说明容量式的价值不在于给出乐观上限，而在于迫使每一项都对应一个可观测的物理量。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>L</td><td>Transformer层数</td></tr><tr><td>H_{kv}</td><td>KV头数（GQA下远小于Q头数）</td></tr><tr><td>d_h</td><td>每头维度</td></tr><tr><td>s</td><td>序列长度（含历史与生成长度）</td></tr><tr><td>b_{kv}</td><td>KV每元素字节数（FP8为1，NVFP4为0.5）</td></tr><tr><td>\\alpha_{\\text{page}}</td><td>分页/对齐碎片放大系数（典型1.05–1.2）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-kv-cache-capacity · 共 5 个片段</p>\n"},{"id":"th-batch-latency-slo","title":"批调度时延-吞吐模型","direction":"dir-grouped-gemm-tcgen05","prereq":[],"plain":"连续批处理下，单token迭代时延由权重读取、KV读取与kernel启动开销叠加，吞吐随批增大而升但TTFT与TPOT随之恶化，SLO可行域由这两个不等式共同圈定。","definition":"连续批处理下，单token迭代时延由权重读取、KV读取与kernel启动开销叠加，吞吐随批增大而升但TTFT与TPOT随之恶化，SLO可行域由这两个不等式共同圈定。","formula":"$$\\mathrm{TPOT}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}},\\qquad \\mathrm{TTFT}=\\frac{P_{\\text{prefill}}(s_p)}{F_{\\text{eff}}}+\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$$","variables":[{"sym":"B","meaning":"并发解码批大小"},{"sym":"\\tau_{\\text{launch}}","meaning":"每层/每kernel启动与同步固定开销"},{"sym":"P_{\\text{prefill}}(s_p)","meaning":"预填阶段浮点运算量（随提示长度s_p增长）"},{"sym":"F_{\\text{eff}}","meaning":"预填实测有效算力"},{"sym":"\\ell_{\\text{queue}}","meaning":"请求在队列中等待的迭代数"}],"derivation":"推导关键一步：把解码迭代拆为权重流与KV流两段HBM读取并相加，再叠加与批无关的启动开销；TTFT则由预填浮点量除以$$F_{\\text{eff}}$$再加排队迭代数$$\\ell_{\\text{queue}}$$乘TPOT构成。","example":"用途：给定TPOT与TTFT的SLO上限，反解可行批大小B与预填块大小，决定是否启用chunked prefill、是否把长请求路由到独立解码池。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["专家并行跨节点时，All-to-All时延与链路带宽成为独立加项，纯HBM带宽模型低估TPOT","批内长度差异大时，decode迭代被最长序列拖尾，需用分块预填与chunked prefill修正"],"system_note":"误用：只按吞吐最大化调大批而不校验TPOT上限，会违反交互式SLO；忽略$$\\tau_{\\text{launch}}$$在小批时高估吞吐，层数多的模型误差可达数十微秒每token。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：连续批处理下单token迭代时延由权重读取、KV读取与kernel启动开销叠加，吞吐随批增大而升但TTFT与TPOT随之恶化，SLO可行域由这两个不等式共同圈定。","公式中$$\\mathrm{TPOT}(B)$$的分子含$$B_{\\text{act}}$$（权重读取，与批无关）与$$Bsb_{kv}2LH_{kv}d_h$$（KV读取，随批线性增长），除以$$\\mathrm{BW}_{\\text{HBM}}$$后加$$\\tau_{\\text{launch}}$$为每层kernel启动与同步固定开销。","推导关键一步：把解码迭代拆为权重流与KV流两段HBM读取并相加，再叠加与批无关的启动开销；TTFT则由预填浮点量除以$$F_{\\text{eff}}$$再加排队迭代数$$\\ell_{\\text{queue}}$$乘TPOT构成。","适用边界：专家并行跨节点时All-to-All时延与链路带宽成为独立加项，纯HBM带宽模型低估TPOT；批内长度差异大时decode迭代被最长序列拖尾，需用分块预填与chunked prefill修正。","用途：给定TPOT与TTFT的SLO上限，反解可行批大小B与预填块大小，决定是否启用chunked prefill、是否把长请求路由到独立解码池。","误用：只按吞吐最大化调大批而不校验TPOT上限，会违反交互式SLO；忽略$$\\tau_{\\text{launch}}$$在小批时高估吞吐，层数多的模型误差可达数十微秒每token。"],"anchors":["未给出"],"pitfalls":["只优化吞吐不断增大批，TPOT越过SLO上限导致交互式请求超时。","跨节点专家并行未把All-to-All时延计入TPOT，SLO预算被系统性低估。","批内长度差异大时未用chunked prefill，decode被最长序列拖尾，尾延迟恶化。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉：一条被两段HBM流夹住的迭代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-2\">二 · 严格定义：把TPOT与TTFT写成可反解的式子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-3\">三 · 为什么需要这个模型：三条工程决策都靠它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-4\">四 · 常见误解之一：把“吞吐最大”当成“批最大”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-5\">五 · 常见误解之二：忽略启动开销与跨节点加项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-6\">六 · 适用边界的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-7\">七 · 带宽模型之外：这个直觉式时延模型在哪些地方会骗人</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-8\">八 · 分子两项的物理来源与量纲对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-9\">九 · 从“逐层串行”到“整批相加”的推导关键步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-10\">十 · TTFT 式的两项结构与 \\(\\ell_{\\text{queue}}\\) 的含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-11\">十一 · 离散化与近似：公式在哪儿“骗”了你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-12\">十二 · 反解可行域：把公式当约束求解器用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-13\">十三 · 带宽模型的三处塌陷：All-to-All、拖尾与启动开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-14\">十四 · 公式成立的三条隐含前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-15\">十五 · 跨节点专家并行：被漏掉的独立加项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-16\">十六 · 批内异构：从算术和到最大值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-17\">十七 · 规模上限：公式在哪个批大小上先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-18\">十八 · 何时必须换模型而不是修系数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-19\">十九 · 带宽模型的三处断点：All-to-All、拖尾与启动开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-20\">二十 · 用TPOT不等式反解批大小上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-21\">二十一 · 用TTFT不等式定预填块大小与chunked prefill开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-22\">二十二 · 用两个不等式联立圈定SLO可行域与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-23\">二十三 · 用公式定KV预算与长请求路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-24\">二十四 · 算例：一次完整的容量反解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-25\">二十五 · 把不等式当设计约束用：反解批大小、并行度与 KV 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-26\">二十六 · 误用一：把吞吐最大化当成批大小选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-27\">二十七 · 误用二：忽略 $$\\tau_{\\text{launch}}$$ 在小批下的主导地位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-28\">二十八 · 误用三：跨节点专家并行不把 All-to-All 计入 TPOT</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-29\">二十九 · 误用四：批内长度差异大却不用 chunked prefill</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-30\">三十 · 一个反例：从“吞吐翻倍”到“SLO 全面失守”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-31\">三十一 · 误用的共同根源与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-32\">三十二 · 三种误用如何把 SLO 预算悄悄吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-33\">三十三 · 三类误用：把模型当成调参旋钮的代价</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:539px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 538.7 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"456.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"456.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：连续批处理下，单token迭代时延由权重读取、KV读取与kerne…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"456.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathrm{TPOT}(B)\\approx\\frac{B_…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"456.7\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：专家并行跨节点时，All-to-All时延与链路带宽成为独立加项，…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉：一条被两段HBM流夹住的迭代</h3>\n<p>连续批处理（continuous batching）把解码阶段从“一次一个请求”变成“每步一个批”，于是单token迭代的时延不再是某个请求的私事，而是整个批共同承担的一笔账。这笔账只有三项：把当前层权重从HBM读进SM的字节流、把批内每个序列的KV cache读进来的字节流、以及每层每个kernel启动与同步的固定开销。前两项除以HBM带宽得到传输时间，第三项与批大小无关，直接相加。吞吐随批增大而上升，因为权重流被摊薄；但KV流随批线性增长，且TTFT被排队迭代数放大。SLO可行域就是“TPOT不超过上限”与“TTFT不超过上限”两条不等式在(B, 预填块大小)平面上的交集。</p>\n<p>这个直觉的工程价值在于它把“调批大小”从经验试错变成了带约束的反解问题：给定两个SLO上限，可行批大小B不是越大越好，而是被KV流那一项顶住的一个上界；同时TTFT那一侧又要求预填块不能太大、排队不能太长。两侧一夹，可行域往往是一个窄带，而不是单调的“越大越优”。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-2\">二 · 严格定义：把TPOT与TTFT写成可反解的式子</h3>\n<p>本系列统一采用如下两个定义式，它们是后续所有推导的锚点：</p>\n<div class=\"formula\">$$\\mathrm{TPOT}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}},\\qquad \\mathrm{TTFT}=\\frac{P_{\\text{prefill}}(s_p)}{F_{\\text{eff}}}+\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$$</div>\n<p>逐项定义：B为并发解码批大小；\\(B_{\\text{act}}\\)是权重读取字节数，与批无关，只随模型与精度变化；\\(s\\)为序列当前长度，\\(b_{kv}\\)为KV每元素字节数，\\(L\\)为层数，\\(H_{kv}\\)为KV头数，\\(d_h\\)为头维，故\\(B\\,s\\,b_{kv}\\,2L H_{kv} d_h\\)是批内KV读取总字节（因子2来自K与V两份）；\\(\\mathrm{BW}_{\\text{HBM}}\\)为HBM有效带宽；\\(\\tau_{\\text{launch}}\\)为每层kernel启动与同步的固定开销。TTFT一侧，\\(P_{\\text{prefill}}(s_p)\\)是随提示长度\\(s_p\\)增长的预填浮点运算量，\\(F_{\\text{eff}}\\)是预填实测有效算力，\\(\\ell_{\\text{queue}}\\)是请求在队列中等待的迭代数。</p>\n<p>严格性体现在三个“可测”上：分子两项都是字节数，可用profiler直接量出；\\(\\mathrm{BW}_{\\text{HBM}}\\)用带宽微基准测得；\\(\\tau_{\\text{launch}}\\)用空批或极小批的迭代时延减去传输项反推。也就是说，这个式子不是拟合出来的经验曲线，而是每一项都能独立标定的结构式——这正是它能被用来反解SLO可行域的前提。</p>\n<p>推导的关键一步是把解码迭代拆成权重流与KV流两段HBM读取再相加，而不是笼统地写“访存量除以带宽”。拆开之后，权重流是常数项、KV流是B的线性项，于是TPOT(B)对B是仿射函数：斜率由\\(s\\,b_{kv}\\,2L H_{kv} d_h/\\mathrm{BW}_{\\text{HBM}}\\)决定，截距由\\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}+\\tau_{\\text{launch}}\\)决定。仿射性使得“给定TPOT上限反解B”成为一次除法，而不是搜索。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-3\">三 · 为什么需要这个模型：三条工程决策都靠它</h3>\n<p>第一条决策是批大小的定档。吞吐最大化会一路推高B，直到KV流项把TPOT顶过SLO上限；此时正确的动作不是继续加批，而是把B钉在反解出的上界，并把多出来的请求挡在队列里或路由到别处。没有这个式子，工程师只能靠压测曲线目测拐点，而拐点位置随序列长度\\(s\\)漂移——长上下文请求一进来，KV流项立刻变大，昨天合适的B今天就违约。</p>\n<p>第二条决策是预填块大小的选择与chunked prefill的开关。TTFT式里\\(P_{\\text{prefill}}(s_p)/F_{\\text{eff}}\\)随提示长度线性增长，而\\(\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}\\)把解码侧的时延折算进首token等待。把长预填切成块，等于把一个大\\(P_{\\text{prefill}}\\)摊到多个迭代上，代价是这些迭代与解码迭代共享同一个批，抬高了该批的TPOT。是否值得切、切多大，取决于两条SLO不等式的松紧程度，而不是“切了总比不切好”。</p>\n<p>第三条决策是长请求是否路由到独立解码池。若某类请求的\\(s\\)远大于均值，它进入共享批会把整批的KV流项抬高，等效于对同批所有请求征收时延税。用模型算一下：把长请求移出后共享批的B可以回升多少、独立池的利用率要多少才不亏——这是容量规划问题，而输入正是这两个式子。</p>\n<p>代价面同样清楚：模型直接给出的是每token时延与首token时延，而吞吐是B除以TPOT(B)的倒数关系，显存侧则受KV容量式约束（见KV cache显存容量式条目，此处不展开）。也就是说，延迟、吞吐、显存三者在这一个式子里被同时参数化，调一个必然动另外两个。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-4\">四 · 常见误解之一：把“吞吐最大”当成“批最大”</h3>\n<p>最典型的误用是只按吞吐最大化调大批而不校验TPOT上限。在仿射模型下，吞吐\\(B/\\mathrm{TPOT}(B)\\)在B增大时先升后趋于平台，因为分母里的线性项吃掉了收益；但TTFT里的\\(\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}\\)是乘法关系，批一大、队列一长，首token等待被双重放大。交互式SLO通常卡在TTFT而非TPOT，于是“吞吐最优批”往往已经违反SLO。工程判断应当是：先由TPOT上限反解\\(B_{\\max}\\)，再由TTFT上限反解允许的\\(\\ell_{\\text{queue}}\\)，两者共同决定准入与排队策略，而不是让调度器无限攒批。</p>\n<p>具体例子：一个层数较多的模型，权重读取项\\(B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}\\)在批很小时占主导，此时加批几乎免费，吞吐线性上升；但当KV流项追平权重项后，每加一个序列就按固定斜率抬升TPOT。拐点位置由\\(B_{\\text{act}}/(s\\,b_{kv}\\,2L H_{kv} d_h)\\)给出——序列越长，拐点越靠左。忽略这一点，会把“短请求压测出来的最优批”直接套到长上下文流量上，SLO当场破裂。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-5\">五 · 常见误解之二：忽略启动开销与跨节点加项</h3>\n<p>第二个误解是忽略\\(\\tau_{\\text{launch}}\\)。在小批区间，传输项很小，迭代时延被每层kernel启动与同步开销支配；此时若用纯带宽模型预测吞吐，会系统性高估。层数多的模型上，这个误差按每token数十微秒的量级累积，足以让“理论吞吐”与实测脱节。反过来，这也解释了一个反直觉现象：小批时加批几乎不增加时延，因为新增的KV流字节被淹没在启动开销里；这正是连续批处理在低负载下几乎免费的物理原因。</p>\n<p>第三个误解是把纯HBM带宽模型外推到专家并行跨节点的场景。此时All-to-All时延与链路带宽成为独立加项，TPOT的真实构成是HBM项加上一段与批内token路由分布相关的通信项，纯带宽模型会低估TPOT，SLO预算被系统性低估。判断方法很简单：若实测TPOT在批增大时呈现出比仿射斜率更陡的走势，且陡度随跨节点EP规模变化，就说明通信项已经不可忽略，必须把它作为独立加项写进预算，而不是塞进\\(\\mathrm{BW}_{\\text{HBM}}\\)里假装带宽变差了。</p>\n<p>第四个误解与批内长度差异有关：decode迭代被最长序列拖尾。批内序列长度参差时，每步迭代的有效工作量由最长者决定，短序列白等；此时TPOT式里的\\(s\\)应当理解为批内最大长度而非平均长度，否则模型偏乐观。修正手段是分块预填与chunked prefill，把长序列的预填切碎、把decode步的拖尾摊平——但如前所述，这本身要消耗TPOT预算，是一个需要反解而非默认开启的动作。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-6\">六 · 适用边界的工程读法</h3>\n<p>把这个模型当成“预算账本”而非“性能预测器”，是正确用法。它的每一项都可独立标定，因此当实测与模型偏离时，偏离的方向本身就指示了漏项：TPOT实测偏高且随批变陡，查通信项；小批时实测偏高，查\\(\\tau_{\\text{launch}}\\)标定是否漏了同步；TTFT实测偏高而TPOT吻合，查\\(\\ell_{\\text{queue}}\\)的统计口径是否把预填块排队算漏了。反解得到的B与预填块大小是决策变量，而模型的仿射结构保证了这个反解是闭式的、可审计的——给定SLO上限，可行域边界可以被画出来并被容量规划直接引用。</p>\n<p>需要强调的是，本部分只确立直觉、定义与边界；可行域的具体求解、chunked prefill的切分策略、以及长请求路由的收益判据，属于同一模块后续部分的内容，此处仅以一句话指路：所有后续推导都建立在这两个不等式之上，而这两个不等式的每一项都必须先被标定，否则反解出来的B只是一个好看的数。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-7\">七 · 带宽模型之外：这个直觉式时延模型在哪些地方会骗人</h3>\n\n<p>这套模型的成立前提是：解码迭代的时延可以被拆成两段彼此独立的 HBM 读取——权重流（$$B_{\\text{act}}$$，与批大小无关）与 KV 流（$$B\\,s\\,b_{kv}\\,2L H_{kv} d_h$$，随批线性增长）——再叠加一个与批无关的 kernel 启动与同步开销 $$\\tau_{\\text{launch}}$$。它的边界恰好就藏在这个“可加性”假设里。一旦某一段读取不再由 HBM 带宽主导，而是被链路带宽、同步等待或最长序列的拖尾接管，公式给出的 TPOT 就只是一个下界，而不是可交付的预测值。工程上判断模型是否还可用，看的不是拟合误差，而是这三类加项有没有被显式写进不等式。</p>\n\n<p>第一类失效来自专家并行跨节点。此时每层除了权重与 KV 的 HBM 读取，还要插入一次 All-to-All 的 dispatch 与 combine，其代价由链路带宽与同步延迟决定，与 $$\\mathrm{BW}_{\\text{HBM}}$$ 无关，因此是独立加项。把它漏掉，模型会系统性低估 TPOT，且低估幅度随 EP 规模与跨节点比例上升——这正是 SLO 预算被悄悄吃掉的典型路径。第二类失效来自批内长度差异：decode 迭代的完成时刻由批内最长序列决定，短请求被迫陪着长请求走完这一轮，公式里那个“平均 $$s$$”掩盖了拖尾。修正手段是分块预填与 chunked prefill，把长提示切块插入迭代间隙，同时把长请求路由到独立解码池，使主池的批内长度分布收敛。第三类失效在小批侧：$$\\tau_{\\text{launch}}$$ 在批很小时占比不可忽略，层数多的模型每 token 的固定开销可达数十微秒量级，只按吞吐最大化调大批会掩盖它，而一旦为了压 TPOT 把批调小，它立刻回来。</p>\n\n<div class=\"formula\">$$\\mathrm{TPOT}_{\\text{real}}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}}+\\underbrace{\\frac{V_{\\text{comm}}}{\\mathrm{BW}_{\\text{link}}}+\\tau_{\\text{sync}}}_{\\text{跨节点 EP 加项}}+\\underbrace{(s_{\\max}-\\bar{s})\\,\\delta_{\\text{tail}}}_{\\text{长度拖尾}}$$</div>\n\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被漏掉的加项</th><th>系统代价</th><th>修正动作</th></tr></thead><tbody><tr><td>专家并行跨节点</td><td>All-to-All 时延与链路带宽</td><td>TPOT 被系统性低估，SLO 预算透支</td><td>把通信项显式计入不等式，按 EP 拓扑重解 B</td></tr><tr><td>批内长度差异大</td><td>最长序列拖尾</td><td>尾延迟恶化，短请求陪跑</td><td>chunked prefill + 长请求独立解码池</td></tr><tr><td>小批、深层模型</td><td>$$\\tau_{\\text{launch}}$$ 固定开销</td><td>吞吐被高估，压批后时延反弹</td><td>合并 kernel、减少每层同步点</td></tr></tbody></table>\n\n<p>用途上，这个模型的价值不在于预测绝对数值，而在于反解：给定 TPOT 与 TTFT 的 SLO 上限，解出可行批大小 B 与预填块大小，据此决定是否启用 chunked prefill、是否把长请求分流。反解时必须把上表的加项一并代入，否则解出的 B 是“带宽可行”而非“SLO 可行”。一个具体判断：当跨节点 EP 的通信项已经与 KV 流读取同量级时，继续增大 B 换吞吐的边际收益会被通信与拖尾吃掉，此时正确动作是缩批、拆池、改路由，而不是继续调大批。TTFT 一侧同理，$$\\mathrm{TTFT}=P_{\\text{prefill}}(s_p)/F_{\\text{eff}}+\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$$ 中的排队迭代数 $$\\ell_{\\text{queue}}$$ 会随 B 增大而放大 TPOT 的乘性影响，预填块切得越细，$$\\ell_{\\text{queue}}$$ 越可控但预填有效算力 $$F_{\\text{eff}}$$ 越难打满——这是 chunked prefill 的真正代价所在，也是容量规划里必须先钉住的那条边界。</p>\n<h3 id=\"th-batch-latency-slo-sec-8\">八 · 分子两项的物理来源与量纲对齐</h3>\n<p>公式的分子不是随手拼出来的，它对应一次解码迭代里 HBM 必须搬动的两类字节。第一项 \\(B_{\\text{act}}\\) 是“权重流”：每生成一个 token，全部参与激活的权重都要从 HBM 过一遍，与批大小无关——批里放 1 条还是 64 条请求，权重都得读同样多。第二项 \\(B\\,s\\,b_{kv}\\,2L H_{kv} d_h\\) 是“KV 流”：\\(B\\) 条序列、每条 \\(s\\) 个历史 token、每 token 每层存 \\(b_{kv}\\) 字节的 K 与 V、共 \\(2L\\) 个张量（K 一份、V 一份）、\\(H_{kv}\\) 个 KV 头、每头 \\(d_h\\) 维。乘起来就是这一轮要读的 KV 字节总量，随批线性增长。</p>\n<p>量纲校验是推导的第一道关：分子单位是字节，除以 \\(\\mathrm{BW}_{\\text{HBM}}\\)（字节/秒）得到秒，再与 \\(\\tau_{\\text{launch}}\\)（秒）相加，整条式子才自洽。工程上这一步经常被写错——把 \\(b_{kv}\\) 写成“每元素比特数”而忘了除 8，或者把 \\(2L\\) 写成 \\(L\\)（漏掉 V），结果 TPOT 预算被系统性低估一半。写代码实现这个模型时，建议把每一项单独打日志，让 \\(B_{\\text{act}}/\\mathrm{BW}\\) 与 \\(B s b_{kv}2LH_{kv}d_h/\\mathrm{BW}\\) 分别可见，才能看出当前 batch 是权重主导还是 KV 主导。</p>\n<p>这个分解直接给出一个可操作的判据：令两项相等，解出临界批大小 \\(B^\\*=B_{\\text{act}}/(s\\,b_{kv}\\,2L H_{kv} d_h)\\)。当 \\(B&lt;B^\\*\\) 时 TPOT 几乎被权重读取钉死，加大批几乎不涨时延，是“免费吞吐”；当 \\(B&gt;B^\\*\\) 后 KV 流开始主导，TPOT 随批线性爬升。以长上下文场景为例，\\(s\\) 很大使 \\(B^\\*\\) 很小，可能十几条并发就跨过临界点，此时再往上堆批，每加一条都在吃 SLO 预算。反过来短提示、短输出的场景 \\(B^\\*\\) 可以很大，批调度的空间就宽。这个临界点是把公式变成调度策略的第一块砖。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-9\">九 · 从“逐层串行”到“整批相加”的推导关键步</h3>\n<p>推导的起点是单层解码：读该层权重、读该层所有序列的 KV、做一次 MMA、写回新 KV。单层耗时近似为（该层权重字节 + 该层 KV 字节）/\\(\\mathrm{BW}_{\\text{HBM}}\\) 再加一次 kernel 启动与同步开销。关键一步在于：把 \\(L\\) 层串起来时，权重与 KV 的读取量对层求和，得到分子里的 \\(B_{\\text{act}}\\) 与 \\(B s b_{kv}2LH_{kv}d_h\\)；而启动开销对层求和，得到 \\(L\\cdot\\tau_{\\text{layer}}\\)，公式里把它压缩成一个聚合的 \\(\\tau_{\\text{launch}}\\)。</p>\n<p>这一步隐含两个近似，必须说清楚。其一，假设 HBM 带宽被完全打满、权重流与 KV 流可以无缝接力，实际中两者交替发起、中间有流水线气泡，真实 TPOT 会比公式略高；其二，把逐层的启动开销线性相加，忽略了相邻层之间可能的 kernel 融合与异步重叠——在 Blackwell 上用 tcgen05 与 TMEM 把注意力和 FFN 的若干步骤融合后，\\(\\tau_{\\text{launch}}\\) 的有效值会低于“层数 × 单次启动”的朴素估计。因此 \\(\\tau_{\\text{launch}}\\) 应当作为实测标定参数，而不是从 kernel 数量直接推算。</p>\n<p>代价层面，这个推导把“每 token 一次全权重扫描”这件事摆到台面上：权重流项 \\(B_{\\text{act}}/\\mathrm{BW}\\) 是 TPOT 的下界，任何批调度都无法把它压到零，只能靠提高 \\(\\mathrm{BW}\\) 利用率或减少激活权重（如 MoE 只读被路由的专家）来摊薄。举例来说，一个层数多、权重大的稠密模型，其 \\(B_{\\text{act}}/\\mathrm{BW}\\) 本身就占掉 TPOT 预算的可观份额，此时即便 \\(B=1\\)，TPOT 也已接近 SLO 上限，说明瓶颈不在批调度而在权重读取——这类模型该走的是张量并行切分权重，而不是继续调 batch。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-10\">十 · TTFT 式的两项结构与 \\(\\ell_{\\text{queue}}\\) 的含义</h3>\n<p>TTFT 由两段构成：预填段 \\(P_{\\text{prefill}}(s_p)/F_{\\text{eff}}\\) 与排队段 \\(\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}\\)。第一段是纯算力项，\\(P_{\\text{prefill}}(s_p)\\) 随提示长度 \\(s_p\\) 增长（注意力部分对 \\(s_p\\) 是超线性，FFN 部分是线性），\\(F_{\\text{eff}}\\) 是实测有效算力，已经把 MMA 利用率、访存等待、并行切分损失都折进去了。第二段容易被忽略：请求不是预填完就立刻出 token，它要等在队列里排到自己的解码迭代，\\(\\ell_{\\text{queue}}\\) 就是它前面还有多少轮迭代。</p>\n<p>\\(\\ell_{\\text{queue}}\\) 与 \\(B\\) 的关系是这套模型最反直觉的地方。批越大，单轮 TPOT 越长（分子随 \\(B\\) 涨），同时队列里能塞的请求越多、\\(\\ell_{\\text{queue}}\\) 也可能越大，两个因子相乘，TTFT 的排队段被二次放大。这就是“吞吐升、TTFT 恶化”的数学来源：不是线性 trade-off，而是乘积关系。工程含义是，交互式 SLO 对 TTFT 的约束往往比 TPOT 更早被触发，尤其在预填与解码共享同一批 GPU 的部署里。</p>\n<p>一个具体判断：若某请求的 \\(s_p\\) 很大，\\(P_{\\text{prefill}}/F_{\\text{eff}}\\) 一项就可能吃掉整个 TTFT 预算，此时排队段再小也无济于事，正确做法是把长预填切块（chunked prefill）插入解码迭代之间，让预填不再独占一个时间片，从而压低单请求的 TTFT 峰值，代价是解码迭代被预填块挤占、TPOT 略微上抬。这正是公式里两个不等式互相牵制的体现：压低 TTFT 的手段会推高 TPOT，反之亦然。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-11\">十一 · 离散化与近似：公式在哪儿“骗”了你</h3>\n<p>第一个近似是“连续流”假设。真实解码是离散的 kernel 序列，权重读取与 KV 读取不是同时发生的，公式把它们加在一起除以带宽，等价于假设两者完美流水。实际中权重流结束后才开始 KV 流（或反之），中间存在带宽空窗，所以公式给出的是乐观下界。第二个近似是把 \\(\\tau_{\\text{launch}}\\) 当作与批无关的常数，但小批时启动开销占比高、大批时被摊薄，公式里它却是固定加项——这导致小批时高估吞吐、大批时相对准确。</p>\n<p>第三个近似最隐蔽：\\(s\\) 被当成批内所有序列的同一个历史长度。真实批里序列长短不一，decode 迭代的节奏被最长序列拖住——短序列早已该出下一个 token，却要等长序列的 KV 读完、MMA 做完。公式用单一 \\(s\\) 等于把拖尾效应抹平了，尾延迟被系统性低估。修正方式是分块预填加 chunked prefill，把长序列的 KV 读取切成块、与短序列的迭代交错，使单轮迭代的实际时长向平均值靠拢而不是向最大值靠拢。</p>\n<p>第四个近似在跨节点专家并行时暴露：公式只算 HBM 带宽，但 MoE 的 All-to-All 走的是 NVLink 5 与节点间链路，其时延与链路带宽是独立加项，不与 HBM 流共享同一个分母。此时 TPOT 应写成 HBM 项 + All-to-All 项 + \\(\\tau_{\\text{launch}}\\)，纯 HBM 模型会低估 TPOT，SLO 预算被系统性高估（以为还有余量，实际已越界）。工程上判断是否落入这个失效区，看专家是否跨节点、每 token 触发的 All-to-All 字节量是否与 KV 流同量级即可。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-12\">十二 · 反解可行域：把公式当约束求解器用</h3>\n<p>公式的用途不是算一个数，而是反解。给定 TPOT 上限 \\(T_{\\max}\\) 与 TTFT 上限 \\(F_{\\max}\\)，先由 TPOT 不等式解出批大小上界：\\((T_{\\max}-\\tau_{\\text{launch}})\\cdot\\mathrm{BW}_{\\text{HBM}}\\ge B_{\\text{act}}+B s b_{kv}2LH_{kv}d_h\\)，解出 \\(B\\le[(T_{\\max}-\\tau_{\\text{launch}})\\mathrm{BW}-B_{\\text{act}}]/(s b_{kv}2LH_{kv}d_h)\\)。这个上界随 \\(s\\) 增大而迅速收紧，说明长上下文场景的可行批天然更小。再把解出的 \\(B\\) 代入 TTFT 式，检查 \\(P_{\\text{prefill}}/F_{\\text{eff}}+\\mathrm{TPOT}(B)\\ell_{\\text{queue}}\\le F_{\\max}\\) 是否成立，若不成立则需下调预填块大小或把长请求路由到独立解码池。</p>\n<p>这个反解流程给出三类工程决策。其一，是否启用 chunked prefill：当预填项单独就逼近 \\(F_{\\max}\\) 时必须启用。其二，是否做预填/解码分离部署：当 \\(\\ell_{\\text{queue}}\\) 在共享部署下无法压到满足 TTFT 时，把预填搬到独立池可让解码池的 \\(\\ell_{\\text{queue}}\\) 归零，代价是多一套 KV 传输。其三，批大小上限该定在哪：直接取 TPOT 不等式解出的 \\(B\\) 上界，而不是取吞吐曲线的拐点——后者往往已经越过 SLO。</p>\n<p>误用模式很典型：只按吞吐最大化调大批，不校验 TPOT 上限，交互式请求成片超时。公式在这里的作用是提供一个硬约束，把“吞吐还能再涨”的诱惑挡在 SLO 之外。另一个误用是忽略 \\(\\tau_{\\text{launch}}\\)：层数多的模型在小批时，每 token 的启动开销累计可达数十微秒量级，若公式里漏掉这一项，会高估小批吞吐、误判“小批也够快”，从而做出错误的容量规划。把 \\(\\tau_{\\text{launch}}\\) 实测标定进模型，是让这套公式从纸面走向可用的必要一步。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-13\">十三 · 带宽模型的三处塌陷：All-to-All、拖尾与启动开销</h3>\n<p>该公式把一次解码迭代的HBM流量拆成两股：权重流$$B_{\\text{act}}$$与KV流$$B\\,s\\,b_{kv}\\,2L H_{kv} d_h$$，相加后除以$$\\mathrm{BW}_{\\text{HBM}}$$，再叠加$$\\tau_{\\text{launch}}$$。这个结构隐含一个强假设——迭代时间由单一HBM带宽资源独占。一旦模型跨节点做专家并行，MoE层的token要经All-to-All换手，dispatch与combine的时延由链路带宽和跳数决定，与HBM带宽完全解耦，成为TPOT里的独立加项。此时真实TPOT近似为$$\\mathrm{TPOT}(B)\\approx \\frac{B_{\\text{act}}+B s b_{kv}2LH_{kv}d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}}+T_{\\text{a2a}}(B)$$，其中$$T_{\\text{a2a}}$$随批增大而升，因为每token都要参与交换。工程后果是：按纯HBM模型反解出的可行批大小会被系统性高估，SLO预算在跨机柜部署上被低估，表现为线上TPOT长尾整体右移而非均值漂移。判断方法很直接——在目标并行拓扑上实测一次空载All-to-All往返，把该值代入不等式重解B，而不是沿用单机标定。</p>\n<p>第二个塌陷来自批内长度差异。公式把KV读取写成$$B\\,s\\,b_{kv}\\cdots$$，默认批内所有序列共享同一$$s$$，即等长。连续批处理的实际批是拼凑出来的：新请求不断插入，序列长度呈重尾分布，一个decode迭代的完成时刻由批内最长序列决定，短序列的算力与带宽被白白占用。此时有效批大小应替换为$$B_{\\text{eff}}=\\frac{\\sum_i s_i}{\\max_i s_i}$$，它恒小于等于名义B，且随长度方差增大而迅速衰减。这正是chunked prefill要修正的对象：把长提示切块，让预填块与decode步交错排入同一迭代，压平单步工作量，代价是预填被拉长、TTFT上升。于是可行域不再是二维的(B, 块大小)，而是三维——块太小则预填碎片化、$$\\tau_{\\text{launch}}$$被反复触发；块太大则单步被预填撑爆，decode尾延迟恶化。分块预填的调参本质是在TTFT上限与TPOT上限之间找一条折线。</p>\n<p>第三个塌陷在$$\\tau_{\\text{launch}}$$。它是每层每kernel的启动与同步固定开销，与批无关，因此在小批区间里占比极高：当$$B$$很小时，分子中的KV项趋近于零，TPOT几乎等于权重读取时间加$$\\tau_{\\text{launch}}$$，此时若忽略该项去反解吞吐，会得出“批越小越划算”的错误结论。层数多的模型上，这项按层累加，单token误差可达数十微秒量级，足以吃掉整个交互式SLO余量。工程上的判别信号是：实测TPOT对B的曲线在低批区出现平台而非线性下降，平台高度即$$\\tau_{\\text{launch}}$$的层累加值。此时正确动作不是继续减小批，而是合并kernel、减少每层同步点，或改用更大批把固定开销摊薄。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>被破坏的假设</th><th>系统代价</th><th>修正手段</th></tr></thead><tbody><tr><td>跨节点专家并行</td><td>单一HBM带宽独占</td><td>TPOT均值与长尾同时抬升，SLO预算低估</td><td>TPOT加$$T_{\\text{a2a}}$$项，按目标拓扑重解B</td></tr><tr><td>批内长度重尾</td><td>批内等长$$s$$</td><td>算力与带宽被短序列空耗，尾延迟恶化</td><td>以$$B_{\\text{eff}}$$替代B，启用chunked prefill</td></tr><tr><td>小批区间</td><td>忽略固定启动开销</td><td>每token数十微秒层累加误差，吞吐被高估</td><td>合并kernel、减少同步点、增大批摊薄</td></tr></tbody></table>\n<p>把这三项放回TTFT不等式会更清楚代价归属：$$\\mathrm{TTFT}=\\frac{P_{\\text{prefill}}(s_p)}{F_{\\text{eff}}}+\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$$，排队迭代数$$\\ell_{\\text{queue}}$$把TPOT的恶化直接放大到首token时延上——TPOT每增加一点，排队中的请求就要多等$$\\ell_{\\text{queue}}$$倍。这意味着只按吞吐最大化调大批，会在两个方向上同时违约：TPOT越过上限，且TTFT因排队被二次惩罚。反解可行域时应把$$\\ell_{\\text{queue}}$$当作负载的函数而非常数，在高并发段它随B上升而增，使TTFT约束比线性更陡。真正稳的做法是把长请求路由到独立解码池、短请求留在低$$\\ell_{\\text{queue}}$$的快池，用拓扑隔离替代单一池内的批大小折中。</p>\n<h3 id=\"th-batch-latency-slo-sec-14\">十四 · 公式成立的三条隐含前提</h3>\n<p>把 <span class=\"formula\">$$\\mathrm{TPOT}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}}$$</span> 当作可反解 SLO 的工具之前，必须先承认它是一张“单卡、单流、同构批”的账单。它成立依赖三条未被写进公式的前提：其一，解码迭代的全部数据搬运确实串行地压在同一条 HBM 总线上，权重流与 KV 流可以简单相加；其二，批内每个序列每步只贡献一个 token，迭代步长由最慢的那个 kernel 决定而与序列内容无关；其三，<span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 是与批大小无关的常数，可被提到括号外。三条前提任何一条破裂，公式给出的 TPOT 就不再是上界而是乐观估计。</p>\n<p>第一条前提的物理含义是：模型并行度没有超出单卡 HBM 带宽所能覆盖的范围。一旦张量并行跨卡，权重读取被切成多份、每卡只读 <span class=\"formula\">$$B_{\\text{act}}/N_{\\text{tp}}$$</span>，但每层之后要插入一次 All-Reduce，其代价由 NVLink 域带宽与环状通信的跳数决定，不再随 <span class=\"formula\">$$\\mathrm{BW}_{\\text{HBM}}$$</span> 缩放。此时分母应换成“HBM 带宽与互联带宽的调和量”，而公式里根本没有这一项。工程判断很直接：单机 NVLink 域内 TP=8 时误差尚可吸收，跨节点 TP 或 EP 时公式必须加项。</p>\n<p>第二条前提在真实流量里最先崩。连续批处理把不同提示长度的请求塞进同一批，decode 阶段每步只推进一个 token，但注意力的 KV 读取量取决于各序列已生成长度，迭代的实际耗时由批内最长上下文那条序列决定——短序列在等它。这就是拖尾：批的<b>有效</b> KV 读取量不是 <span class=\"formula\">$$B\\,s\\,b_{kv}\\,2L H_{kv} d_h$$</span> 的算术和，而是被最长序列放大的值。修正手段是分块预填（chunked prefill）把长提示切块、与 decode 交错调度，使单步计算量被块大小钳住，代价是长请求的 TTFT 被拉长。</p>\n<p>第三条前提在小批区间最致命。层数多的模型每 token 要经历 <span class=\"formula\">$$L$$</span> 次 kernel 启动与同步，<span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 累加后可达数十微秒量级；当 <span class=\"formula\">$$B$$</span> 很小、HBM 项只有几微秒时，启动开销反而占主导。此时按公式反解出的“吞吐随批线性上升”是假的——真实曲线在小批段是平的。误用者若只按吞吐最大化调大批，会先撞上 TPOT 上限而不是先看到收益拐点。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-15\">十五 · 跨节点专家并行：被漏掉的独立加项</h3>\n<p>MoE 解码的 roofline 界在另一条目里已给出，这里只取它对 TPOT 模型的破坏方式。专家并行把每层的 FFN 拆到不同 rank，token 需要经 All-to-All 被路由到持有对应专家的设备，算完再 All-to-All 回来。这两次集合通信的时延由链路带宽、消息大小与路由不均衡度共同决定，与 <span class=\"formula\">$$\\mathrm{BW}_{\\text{HBM}}$$</span> 无关，是纯粹的外加项：</p>\n<div class=\"formula\">$$\\mathrm{TPOT}_{\\text{EP}}(B)\\approx \\mathrm{TPOT}_{\\text{HBM}}(B)+2\\,T_{\\text{A2A}}(B)+\\tau_{\\text{sync}}$$</div>\n<p>其中 <span class=\"formula\">$$T_{\\text{A2A}}$$</span> 随批增大而增大（消息更大）、随专家负载不均衡而恶化（最热专家所在链路成为瓶颈）。这意味着 EP 场景下 TPOT 对 <span class=\"formula\">$$B$$</span> 的斜率比纯 HBM 模型陡得多，可行批大小被系统性高估。工程上的判别信号：若实测 TPOT 随批增长的斜率明显超过 <span class=\"formula\">$$s\\,b_{kv}\\,2L H_{kv} d_h/\\mathrm{BW}_{\\text{HBM}}$$</span> 的预测，就说明通信项已经接管。对策不是调公式系数，而是把 EP 组限制在单机 NVLink 域内、或对热专家做冗余复制以削平链路峰值。</p>\n<p>代价核算要落到预算上：交互式 SLO 常给 TPOT 上限在几十毫秒量级，一次跨节点 All-to-All 往返若占去其中可观比例，剩下的 HBM 预算就被压缩，可承载的批大小随之下降。忽略这一项的直接后果是容量规划阶段算出“能撑 N 并发”，上线后尾延迟超时——这是失败模式里“SLO 预算被系统性低估”的机制来源。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-16\">十六 · 批内异构：从算术和到最大值</h3>\n<p>公式把批当作同构单元，但生产流量里提示长度呈长尾分布。设批内序列的已生成长度为 <span class=\"formula\">$$s_1\\le s_2\\le\\cdots\\le s_B$$</span>，则单步 KV 读取量应写成 <span class=\"formula\">$$b_{kv}\\,2L H_{kv} d_h\\cdot \\max_i s_i\\cdot B$$</span> 的保守形式——因为 GPU 在一步内要等最长那条序列的注意力算完。等价地，有效批大小被“长度方差”打折：</p>\n<div class=\"formula\">$$B_{\\text{eff}}\\approx B\\cdot\\frac{\\bar{s}}{\\max_i s_i},\\qquad \\bar{s}=\\frac{1}{B}\\sum_i s_i$$</div>\n<p>当批内长度差异达到数倍时，<span class=\"formula\">$$B_{\\text{eff}}$$</span> 可能只有 <span class=\"formula\">$$B$$</span> 的一半甚至更低，公式预测的吞吐被高估、TPOT 被低估。修正路径有两条：其一是 chunked prefill，把预填切成固定大小的块并与 decode 步交错，使单步工作量有界，代价是长提示的 TTFT 增加（排队迭代数 <span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 变大）；其二是路由分层，把长上下文请求赶到独立解码池，让主池的批保持长度同构。后者对 TPOT 更友好，但需要入口处的长度预判与两套 KV 显存预算。</p>\n<p>具体例子：一个批里 7 条序列已生成 200 token、1 条已生成 4000 token，算术和模型认为 KV 读取量与 8 条均匀 675 token 相当，实际单步被 4000 token 那条拖住，短序列的算力槽位空转。此时把长序列迁出、或对其单独成批（批大小为 1 但长度可控），总吞吐反而上升——这是“最大批不等于最大吞吐”的典型反例。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-17\">十七 · 规模上限：公式在哪个批大小上先失效</h3>\n<p>公式对 <span class=\"formula\">$$B$$</span> 是线性的，但真实系统在三个方向上有硬顶。第一是 KV 显存：<span class=\"formula\">$$B\\,s\\,b_{kv}\\,2L H_{kv} d_h$$</span> 同时是显存占用式的主体，批越大留给权重的余量越小，超过某个 <span class=\"formula\">$$B$$</span> 后要么换页、要么抢占（preemption），TPOT 出现阶跃而非平滑上升。第二是 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 的摊销边界：只有当 HBM 项显著大于启动开销时，增大批才有正收益；在 <span class=\"formula\">$$B$$</span> 很小时公式的线性段并不存在。第三是 SLO 不等式本身：<span class=\"formula\">$$\\mathrm{TPOT}(B)\\le \\mathrm{TPOT}_{\\max}$$</span> 给出可行域上界 <span class=\"formula\">$$B^\\*$$</span>，而 <span class=\"formula\">$$\\mathrm{TTFT}$$</span> 不等式通过 <span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 给出下界约束——批越大排队越久，TTFT 越难满足。两条不等式夹出的区间可能为空，此时不是调参问题而是容量不足。</p>\n<table class=\"mini\"><thead><tr><th>失效方向</th><th>触发条件</th><th>公式表现</th><th>工程处置</th></tr></thead><tbody><tr><td>显存墙</td><td>KV 占用逼近容量</td><td>TPOT 阶跃、抢占抖动</td><td>限批、分页、分层路由</td></tr><tr><td>启动开销主导</td><td>小批、深层模型</td><td>吞吐曲线变平</td><td>合并 kernel、CUDA Graph</td></tr><tr><td>SLO 空集</td><td>TPOT 上限紧、流量长尾</td><td>无可行 <span class=\"formula\">$$B$$</span></td><td>扩容或降级服务等级</td></tr></tbody></table>\n<p>判别规模上限的实用做法：固定 <span class=\"formula\">$$s$$</span> 扫 <span class=\"formula\">$$B$$</span>，画实测 TPOT 曲线，与公式预测线对比。偏离点即失效点——若偏离发生在低 <span class=\"formula\">$$B$$</span>，是启动开销；若发生在高 <span class=\"formula\">$$B$$</span>，是显存或通信；若曲线在中段出现平台，是批内异构拖尾。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-18\">十八 · 何时必须换模型而不是修系数</h3>\n<p>有些失效不是加一项能救的，需要换建模层次。分离式部署（prefill/decode 解耦）下，TTFT 与 TPOT 由两套资源池分别决定，<span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 的含义变成跨池传输与排队，单池公式不再适用，应改用 goodput 模型（见对应条目）。投机解码改变了每步推进的 token 数，TPOT 的定义从“每 token”变成“每接受 token”，期望加速比界已单独讨论，此处只需记住：把投机塞进原公式会把 <span class=\"formula\">$$s$$</span> 与 <span class=\"formula\">$$B$$</span> 的语义同时污染。NVFP4 量化改变了 <span class=\"formula\">$$B_{\\text{act}}$$</span> 与 <span class=\"formula\">$$b_{kv}$$</span> 的字节数，公式形式不变但系数需按精度重标定，误差界另见量化条目。</p>\n<p>工程判断的落点：这张公式是<b>容量规划的第一遍粗算工具</b>，用于快速圈定可行批大小与是否启用 chunked prefill；一旦进入跨节点 EP、异构长尾或解耦部署，就必须在公式上显式加项或换模型，而不是靠调一个“经验系数”把偏差吸收掉——系数吸收会把系统性低估藏进配置里，上线后以尾延迟超时的形式暴露。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-19\">十九 · 带宽模型的三处断点：All-to-All、拖尾与启动开销</h3>\n<p>这套时延-吞吐模型的骨架是一条极简假设：解码迭代的耗时等于“权重流 + KV 流”两段 HBM 读取之和除以 HBM 带宽，再叠加与批无关的固定开销。它成立的前提是——迭代内所有字节都从本地 HBM 流出，且批内每条序列在同一迭代里推进同样的步数。一旦这两条前提被打破，公式不再是“略有偏差”，而是结构性低估。最典型的断点是跨节点专家并行：MoE 解码时，token 经路由分发到不同节点上的专家，每层都要一次 All-to-All 往返。这段时延由链路带宽与集合通信的固定同步成本共同决定，与 HBM 带宽无关，因此必须作为独立加项写入 TPOT：</p>\n<div class=\"formula\">$$\\mathrm{TPOT}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}}+\\sum_{l=1}^{L_{\\text{moE}}}\\Big(\\frac{2\\,B\\,s\\,d_{\\text{route}}}{\\mathrm{BW}_{\\text{link}}}+t_{\\text{sync}}\\Big)$$</div>\n<p>其中求和项按 MoE 层数累加，分子是每层被路由的激活字节量，分母是节点间实际可用的链路带宽。工程后果很直接：当专家并行度跨出单节点 NVLink 域，TPOT 的斜率不再由 HBM 决定，而由链路带宽与同步开销决定，此时继续按纯带宽模型反解批大小会系统性低估 SLO 预算——扩容批的收益被通信吃掉，而公式仍显示“还有余量”。判断方法不是猜，而是实测一次 All-to-All 的微基准，把每层往返时延作为常数项代入，再看它与 HBM 项的相对量级；若通信项已与 KV 项同阶，说明该部署形态下批大小不再是主要杠杆，应优先压缩路由的 token 数（如降低激活专家数）或改为节点内专家并行。</p>\n<p>第二个断点来自批内长度差异。公式隐含“批内所有序列每迭代只前进一个 token”，但真实请求的上下文长度分布极偏，decode 迭代的完成时刻由批内最长的那条序列决定，短序列被迫陪跑。若不做干预，尾延迟被拖尾放大，而平均 TPOT 看起来仍然漂亮——这是一种典型的指标欺骗。修正手段是分块预填与 chunked prefill：把长提示切成固定大小的块，与 decode 迭代交错调度，使每轮迭代的计算量有上界，拖尾被摊平到多个迭代上。代价是预填被切碎后单块的算力利用率下降、kernel 启动次数增加，且长请求的 TTFT 被拉长——这正是公式中 $$P_{\\text{prefill}}(s_p)/F_{\\text{eff}}$$ 一项需要按块重算的原因：块越小，$$F_{\\text{eff}}$$ 越低，TTFT 的算术部分反而变差。因此块大小是一个双向权衡：块太大则拖尾回归，块太小则预填效率与启动开销恶化。可行做法是以 TPOT 上限反解允许的最大单迭代工作量，再据此定块。</p>\n<p>第三个断点是 $$\\tau_{\\text{launch}}$$ 在小批时的支配地位。该常数项与批无关，意味着批越小，它在 TPOT 中的占比越高；层数多、kernel 切分细的模型，每 token 的启动与同步开销可以累积到数十微秒量级，此时“减小批以降低 TPOT”这条直觉会失效——批降到很小，TPOT 也降不下去，因为地板由启动开销钉死。这直接限制了模型的下界适用区间：当 $$B$$ 小到 KV 项远小于 $$\\tau_{\\text{launch}}$$ 时，公式对批的敏感度趋近于零，调批不再有意义，应转向减少 kernel 数量（算子融合）或提高单 kernel 工作量。反过来，只按吞吐最大化调大批而不校验 TPOT 上限，则是另一种误用：吞吐曲线单调上升，但 TPOT 随 $$B$$ 线性爬升，越过 SLO 上限后交互式请求开始超时，系统在“高吞吐”的表象下失去可用性。边界判断可归纳为一张判据表：</p>\n<table class=\"mini\"><thead><tr><th>断点</th><th>失效表现</th><th>修正项</th><th>系统代价</th></tr></thead><tbody><tr><td>跨节点专家并行</td><td>TPOT 被低估，扩容批无收益</td><td>All-to-All 时延与链路带宽加项</td><td>链路带宽占用、同步等待</td></tr><tr><td>批内长度差异大</td><td>尾延迟被最长序列拖尾</td><td>chunked prefill 与分块预填</td><td>预填算力利用率下降、TTFT 拉长</td></tr><tr><td>小批区间</td><td>TPOT 触底不降，调批无效</td><td>算子融合、减少 kernel 数</td><td>编译复杂度、寄存器压力</td></tr></tbody></table>\n<p>规模上限还有一层含义：公式把预填与解码视为可分离的两段，但当预填块与 decode 迭代共享同一批 SM 与同一份 HBM 带宽时，二者互相挤占，$$F_{\\text{eff}}$$ 与 $$\\mathrm{BW}_{\\text{HBM}}$$ 都不再是常数，而是随调度比例漂移的量。此时反解出的批大小只是名义值，真实可行域要按“预填占比 × 带宽占用”重算。工程判断落在具体机制上：把长请求路由到独立解码池、把预填池与解码池的 SM 配额显式隔离，比在单一池内调批更可靠——因为一旦两段共享资源，公式中的每一个“常数”都变成了调度变量的函数，边界条件也就从批大小转移到了资源配额上。</p>\n<h3 id=\"th-batch-latency-slo-sec-20\">二十 · 用TPOT不等式反解批大小上界</h3>\n<p>把TPOT公式当成约束而不是预测器，是容量决策的第一个动作。给定SLO里写死的每token时延上限$\\mathrm{TPOT}_{\\text{slo}}$，把公式移项，得到可行批大小的解析上界：</p>\n<div class=\"formula\">$$B \\le \\frac{(\\mathrm{TPOT}_{\\text{slo}}-\\tau_{\\text{launch}})\\,\\mathrm{BW}_{\\text{HBM}}-B_{\\text{act}}}{s\\,b_{kv}\\,2L H_{kv} d_h}$$</div>\n<p>分子里减掉$\\tau_{\\text{launch}}$这一步不能省。$\\tau_{\\text{launch}}$与批无关，但在小批区间它占TPOT的比例最高，层数多的模型每token累计可达数十微秒量级；若把它当作噪声忽略，反解出的$B$会系统性偏大，部署后才发现TPOT贴着上限抖动。分母是每token每序列的KV读取字节数，$s$为已生成token数、$b_{kv}$为KV元素字节宽、$2L H_{kv} d_h$为每层K与V的元素总数。这个式子的工程含义是：$B$的上界随已生成长度$s$反比收缩——同一个SLO，在首token附近允许的批远大于生成到数千token时允许的批。因此“定批大小”不是定一个常数，而是定一条随$s$衰减的曲线，调度器必须按批内最长$s$来取上界，否则长序列会把整批拖过线。</p>\n<p>具体机制上，这意味着连续批处理需要一个按$s_{\\max}$查表的准入控制：新请求进批前，用当前批的$s_{\\max}$代入上式算剩余容量，容量不足则排队而非硬塞。代价体现在吞吐侧——批被$s_{\\max}$压小，HBM带宽利用率下降，单位时间token数减少；收益是TPOT的尾部分布被钉在SLO内。举例：一个交互式编程助手场景，SLO写TPOT≤50 ms、TTFT≤800 ms，模型层数深、$B_{\\text{act}}$占HBM读取的主要部分，则上式给出的$B$上界在小$s$时由$B_{\\text{act}}$项主导而显得宽松，在$s$增大后由KV项主导迅速收紧，调度器若不分段处理就会在长对话上违约。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-21\">二十一 · 用TTFT不等式定预填块大小与chunked prefill开关</h3>\n<p>TTFT由两段构成：预填浮点量除以有效算力，加上排队迭代数乘以TPOT。第二段是很多人漏算的——预填不是瞬时的，它在队列里等待的每一个decode迭代都按当前TPOT计价。把TTFT约束写成对预填块大小$s_p$的不等式：</p>\n<div class=\"formula\">$$\\frac{P_{\\text{prefill}}(s_p)}{F_{\\text{eff}}}+\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}\\le \\mathrm{TTFT}_{\\text{slo}}$$</div>\n<p>$P_{\\text{prefill}}(s_p)$随提示长度增长，$F_{\\text{eff}}$是实测有效算力（不是峰值，要含利用率折损）。当提示很长时，左侧第一项单独就可能吃掉整个TTFT预算，此时唯一出路是把$s_p$切小、分多个迭代灌入，即启用chunked prefill：每块预填与当前批的decode迭代混跑，$\\ell_{\\text{queue}}$被人为拉长但单次预填的算力占用被摊薄，TTFT的方差下降。判断是否启用chunked prefill的工程判据很直接：若按整块预填算出的第一项已经逼近$\\mathrm{TTFT}_{\\text{slo}}$，而队列里还有decode请求在等，则必须切块；反之若提示短、第一项远小于预算，整块预填反而减少迭代数、降低$\\tau_{\\text{launch}}$的累计开销。</p>\n<p>代价在这里是双向的：切块降低了TTFT尾延迟，但每个chunk都带来一次额外的kernel启动与同步，$\\tau_{\\text{launch}}$乘以chunk数直接加到总时延上；同时预填与decode混跑会争抢HBM带宽，把TPOT推高，反过来又抬高第二项。所以块大小$s_p$是一个在“启动开销”和“带宽争抢”之间的折中量，典型做法是按$\\mathrm{TTFT}_{\\text{slo}}$反解出允许的最大chunk数，再取整到与tile对齐的尺寸。举例：长文档摘要请求提示极长，若不切块，预填算力项独占TTFT预算，同批的短问答请求全部超时；切块后长请求的TTFT略升但仍在SLO内，短请求的TPOT因带宽争抢上升有限，整体可行域反而扩大。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-22\">二十二 · 用两个不等式联立圈定SLO可行域与并行度</h3>\n<p>TPOT与TTFT不是两条独立的线，它们通过$B$耦合：增大$B$提升吞吐，但TPOT上升，同时TTFT的第二项$\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$也上升。把两式联立，可行域是$(B, s_p, \\ell_{\\text{queue}})$空间里的一个多面体，容量规划的任务就是找到这个多面体里吞吐最大的顶点。并行度的选择改变的是公式里的系数而非结构：张量并行把$B_{\\text{act}}$和KV读取按卡数分摊到多个HBM上，等效提高了可用$\\mathrm{BW}_{\\text{HBM}}$，从而放宽$B$的上界；但每层多一次集合通信，等效于给$\\tau_{\\text{launch}}$加了一项与卡数相关的固定开销。所以并行度不是越大越好——当$\\tau_{\\text{launch}}$的增量超过了带宽分摊带来的$B$上界扩张时，TPOT反而恶化。</p>\n<p>决策顺序应当是：先按单卡公式算出TPOT约束下的$B$上界与对应吞吐，再按张量并行度$N$重算——带宽项除以$N$、$\\tau_{\\text{launch}}$加上通信项——比较两种配置在SLO内的最大吞吐，取优者。这里必须显式标注一个失效条件：一旦专家并行跨节点，All-to-All时延与链路带宽成为TPOT里独立的加项，纯HBM带宽模型会低估TPOT，此时第三节的联立求解必须把这一项单独加进公式，否则可行域被高估、SLO预算被系统性低估。工程上的表现是：单机内验证通过的批大小，跨节点部署后TPOT尾延迟集体越线，而按公式算却“应该合规”。</p>\n<p>代价维度上，可行域顶点处的配置通常意味着HBM带宽接近饱和、功耗接近上限、$\\tau_{\\text{launch}}$占比被压到很低——这是吞吐最优但弹性最差的点。容量规划要留出余量，因为请求长度分布会漂移，$s_{\\max}$一旦变大，可行域立即收缩。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-23\">二十三 · 用公式定KV预算与长请求路由</h3>\n<p>KV预算的定法与前文KV容量式不同：这里不是问“能装多少”，而是问“在SLO内允许多长的序列留在解码批里”。由TPOT不等式解出$s$的上界：</p>\n<div class=\"formula\">$$s \\le \\frac{(\\mathrm{TPOT}_{\\text{slo}}-\\tau_{\\text{launch}})\\,\\mathrm{BW}_{\\text{HBM}}-B_{\\text{act}}}{B\\,b_{kv}\\,2L H_{kv} d_h}$$</div>\n<p>这个$s$上界就是KV预算的时延侧约束，它与显存容量侧约束取小者，才是真正可用的序列长度上限。工程含义明确：批越大，单序列允许的长度越短；想让长序列留在批里，就得把$B$压小，用吞吐换长度。当$s$上界低于业务的实际长尾长度时，正确动作不是继续压$B$（那会牺牲全部短请求的吞吐），而是把长请求路由到独立解码池——一个专门跑小批、长序列、低并发的池子，其$B$小、$s$上界大，TPOT可控；主池保持大批、短序列、高吞吐。这就是分离式部署在批调度层面的动机，路由判据直接由上式给出：请求预估长度超过主池$s$上界即分流。</p>\n<p>代价是资源碎片化：两个池各自的$B$都达不到全局最优，总算力利用率下降，且长请求池的HBM占用高、并发低，单位token成本上升。另一个必须处理的失效条件是批内长度差异大时的拖尾——decode迭代被最长序列拖慢，公式里的$s$应按批内$s_{\\max}$取值，若不做chunked prefill修正，短请求的TPOT被长请求绑架，尾延迟恶化而平均值看起来正常。因此KV预算的最终形态是三元组：主池$B$、主池$s$上界、分流阈值，三者由同一组不等式联立解出。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-24\">二十四 · 算例：一次完整的容量反解</h3>\n<p>设某交互式服务SLO为$\\mathrm{TPOT}_{\\text{slo}}=50$ ms、$\\mathrm{TTFT}_{\\text{slo}}=800$ ms，模型与硬件的具体数值按现场实测填入（此处不虚构数字），流程如下。第一步，实测$\\tau_{\\text{launch}}$：用$B=1$的空载decode迭代测每token时延，减去$B_{\\text{act}}/\\mathrm{BW}_{\\text{HBM}}$，残差即$\\tau_{\\text{launch}}$，层数多的模型此项不可忽略。第二步，代入TPOT不等式解$B$上界，分别在$s$取短、中、长三档计算，得到一条衰减曲线；取业务长度分布的中位数对应点作为主池批大小，取长尾分位点对应点作为分流阈值。第三步，对最长提示用TTFT不等式算$P_{\\text{prefill}}(s_p)/F_{\\text{eff}}$，若逼近800 ms则启用chunked prefill，按允许的chunk数反解$s_p$，并核对chunk带来的$\\tau_{\\text{launch}}$增量没有把TPOT推过线。第四步，若采用张量并行，把带宽项除以卡数、$\\tau_{\\text{launch}}$加通信项重算$B$上界，比较吞吐取优；若跨节点专家并行，把All-to-All时延作为独立加项写入TPOT，重解可行域。第五步，用解出的$(B, s_p, \\text{分流阈值})$跑一轮压测，重点看TPOT的尾部分位而非均值——均值合规而尾部越线，说明$s_{\\max}$取值偏乐观或$\\tau_{\\text{launch}}$被低估。</p>\n<p>这个算例的产出不是一组静态参数，而是一张随$s$变化的准入表加一个分流阈值。真正的工程判断落在最后一步：当压测显示尾部TPOT越线而均值合规时，优先怀疑批内长度拖尾而非公式本身，修正手段是chunked prefill与按$s_{\\max}$收紧准入，而不是简单调小$B$——后者会把吞吐一起赔进去，且掩盖了拖尾这个真实病因。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-25\">二十五 · 把不等式当设计约束用：反解批大小、并行度与 KV 预算</h3>\n<p>这套时延-吞吐模型在工程上的正确用法不是“预测一个数”，而是把 TPOT 与 TTFT 两条不等式当作可行域的边界，做反向求解。给定交互式 SLO（例如 TPOT 上限 <span>t_max</span>、TTFT 上限 <span>f_max</span>），先由 TPOT 不等式解出批大小的上界：<span>B ≤ (t_max − τ_launch)·BW_HBM / (s·b_kv·2L·H_kv·d_h) − B_act/(s·b_kv·2L·H_kv·d_h)</span>。注意分子里减掉的是启动开销，分母是每 token 每序列的 KV 字节数——这意味着 KV 预算不是独立参数，而是被 SLO 直接钉死的：<span>B·s·b_kv·2L·H_kv·d_h</span> 就是该 SLO 下允许驻留的 KV 总量上限。反过来，若显存先耗尽，则说明 SLO 与 KV 容量二者必有一个要放宽，此时应优先压缩 KV（量化、分页、前缀复用）而不是牺牲 TPOT。并行度的确定同理：TP 增大使每卡权重读取 <span>B_act</span> 变小，但引入跨卡通信加项；当 <span>B_act/BW_HBM</span> 已小于通信时延，继续加 TP 只降吞吐不降 TPOT，这是并行度选择的拐点判据。</p>\n<p>TTFT 不等式则用来定预填块大小与路由策略。把 <span>TTFT = P_prefill(s_p)/F_eff + TPOT(B)·ℓ_queue</span> 展开可见，长提示的代价有两段：算力段与排队段。若 <span>P_prefill/F_eff</span> 已接近 <span>f_max</span>，则任何排队都必然违约，此时唯一解是把长请求路由到独立解码池或启用 chunked prefill 把预填切成小块、让 decode 迭代插入其间，用 <span>ℓ_queue</span> 的上升换取单块预填不阻塞其他请求。算例：设某模型每序列每 token KV 读取使 TPOT 随 B 线性上升，SLO 要求 TPOT ≤ 某阈值；若把 B 从可行上界再调大一档，TPOT 立即越界，交互式请求开始超时——这正是“只按吞吐最大化调大批”的典型失效。小批时则相反：<span>τ_launch</span> 在分子中占比高，层数多的模型每 token 固定开销可达数十微秒量级，此时按纯带宽模型估出的吞吐会被系统性高估，容量规划会偏乐观。</p>\n<p>模型的边界必须写进决策流程，否则 SLO 预算会被系统性低估。第一类失效是跨节点专家并行：All-to-All 时延与链路带宽是独立加项，纯 HBM 带宽模型不含它，TPOT 被低估，此时应在公式中显式加一项通信时延，并据此判断 EP 规模是否值得。第二类失效是批内长度差异：decode 迭代被最长序列拖尾，实际 TPOT 高于按平均序列长度算出的值，必须用分块预填与 chunked prefill 修正，或按长度分桶路由。第三类是忽略 <span>τ_launch</span> 的小批误判。工程判断可以归纳为一张校验表：</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>模型给出的量</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>定批大小 B</td><td>TPOT 上界反解</td><td>只追吞吐不校验 TPOT</td><td>交互式请求超时</td></tr><tr><td>定并行度 TP/EP</td><td>权重读取项 vs 通信加项</td><td>跨节点 EP 未计 All-to-All</td><td>TPOT 被低估、SLO 违约</td></tr><tr><td>定 KV 预算</td><td>B·s·b_kv·2L·H_kv·d_h</td><td>批内长度差异大</td><td>尾延迟恶化、显存碎片</td></tr><tr><td>定预填块</td><td>P_prefill/F_eff 与 ℓ_queue</td><td>小批忽略 τ_launch</td><td>吞吐高估、容量规划偏松</td></tr></tbody></table>\n<p>因此这套公式的定位是“约束求解器”而非“性能预言机”：它给出的是可行域的边界形状，真正的数值必须用实测的 <span>F_eff</span>、<span>τ_launch</span> 与通信加项去校准。凡是模型里没有显式出现的项——All-to-All、拖尾、启动开销——都会以 SLO 违约的形式在线上暴露，而不是在纸面上暴露。</p>\n<h3 id=\"th-batch-latency-slo-sec-26\">二十六 · 误用一：把吞吐最大化当成批大小选择</h3>\n<p>最常见的误用是把连续批处理的批大小当成一个“越大越好”的旋钮：看到吞吐曲线单调上升，就把 <code>max_num_seqs</code> 或调度器的并发上限推到显存能容纳的极限，然后宣称优化完成。后果不是吞吐不够，而是交互式请求的 TPOT 越过 SLO 上限。识别方法很直接：把 <span class=\"formula\">$$\\mathrm{TPOT}(B)$$</span> 的实测值与 SLO 上限画在同一张图上，看两条线的交点落在哪个批大小；如果调度器实际运行的批大小在该交点右侧，就是误用。工程上更可靠的判据是“SLO 可行域”而非吞吐峰值——吞吐在可行域边界之外的增长，对交互式负载是负收益，因为超时请求会被重试或放弃，等效吞吐反而下降。具体例子：一个在线对话服务把 TPOT 上限设为 50 ms 量级，运维只监控 tokens/s，把批从 32 拉到 128，吞吐翻倍但 TPOT 从 30 ms 级升到 70 ms 级，前端超时率上升，重试流量又把有效批推得更高，形成正反馈。正确做法是在调度器里把 TPOT 上限作为硬约束反解 <span class=\"formula\">$$B$$</span>，而不是让吞吐曲线决定 <span class=\"formula\">$$B$$</span>。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-27\">二十七 · 误用二：忽略 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 在小批下的主导地位</h3>\n<p>第二个高频误用是把 <span class=\"formula\">$$\\mathrm{TPOT}(B)\\approx\\frac{B_{\\text{act}}+B\\,s\\,b_{kv}\\,2L H_{kv} d_h}{\\mathrm{BW}_{\\text{HBM}}}+\\tau_{\\text{launch}}$$</span> 当成纯带宽模型，只优化分子里的 HBM 读取量，忽略与批无关的 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span>。在小批（低并发、低延迟场景）下，分子里的 KV 项很小，<span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 反而是 TPOT 的主要构成：每层每 kernel 的启动与同步开销随层数线性累加，层数多的模型误差可达数十微秒每 token。后果是容量规划时高估小批下的吞吐、低估单请求延迟，导致低并发场景的 SLO 被系统性违反。识别方法：在批大小为 1 到 4 的区间测 TPOT，若实测值明显高于“分子除以带宽”的估算，差额就是 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 的贡献；再对照层数与 kernel 数，若差额与层数近似成正比，即可确认。工程判断：小批场景下减少 kernel 启动次数（算子融合、减少每层同步点）比提升带宽利用率更有效；把 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 当成常数从公式里删掉，等于把低延迟场景的预算全部算错。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-28\">二十八 · 误用三：跨节点专家并行不把 All-to-All 计入 TPOT</h3>\n<p>第三个误用是拿纯 HBM 带宽模型去套跨节点专家并行（EP）的部署。适用边界写得很清楚：专家并行跨节点时，All-to-All 时延与链路带宽成为独立加项，纯 HBM 带宽模型低估 TPOT。后果是 SLO 预算被系统性低估——调度器按公式算出的 <span class=\"formula\">$$B$$</span> 看起来安全，实际运行中每个 decode 迭代都要等一次跨节点交换，尾延迟被链路带宽和拥塞放大。识别方法：把 TPOT 拆成“HBM 段 + 通信段”两段实测，若通信段随 EP 规模（跨节点组大小）增长而增长，且与批大小弱相关，就说明模型漏了一项；再看 NVLink 域内与跨域两种拓扑下的 TPOT 差值，差值即为被漏掉的加项量级。具体例子：同一模型在单节点内 EP 与跨两节点 EP 下，公式给出的 TPOT 相同，但实测跨节点版本的 TPOT 明显更高，且在高并发时抖动更大——此时正确的动作是把通信段作为独立加项写进容量模型，并据此下调可行批大小或改用域内 EP 加分层路由。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-29\">二十九 · 误用四：批内长度差异大却不用 chunked prefill</h3>\n<p>第四个误用是忽视批内长度差异对 decode 迭代的拖尾效应。当批内混有长序列时，decode 迭代被最长序列拖尾，短请求的 TPOT 被长请求绑架；若不启用分块预填与 chunked prefill 修正，尾延迟恶化会直接体现在 P99 上，而均值看起来仍然健康。识别方法：按请求长度分桶统计 TPOT，若短请求桶的 TPOT 与批内最长序列长度正相关，即为拖尾证据；同时观察预填块是否整块插入 decode 批，若是，则一次长预填会把整个批的迭代拉长。工程判断：把长请求路由到独立解码池、对预填做分块并限制每迭代的预填 token 预算，是把“均值达标”变成“尾延迟达标”的关键动作。代价是预填被切碎后 <span class=\"formula\">$$F_{\\text{eff}}$$</span> 略降、TTFT 略升，但换来控制住的 P99 TPOT——这正是 TTFT 与 TPOT 两个不等式共同圈定可行域的意义：不能只守住其中一个。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-30\">三十 · 一个反例：从“吞吐翻倍”到“SLO 全面失守”</h3>\n<p>设一个交互式服务，SLO 为 TTFT 上限与 TPOT 上限各一档，调度器初始批大小为 <span class=\"formula\">$$B_0$$</span>，实测 TPOT 在 SLO 以内、吞吐未饱和。运维为提升吞吐，把批上限提高到 <span class=\"formula\">$$4B_0$$</span>，并关闭 chunked prefill 以减少预填切分开销。按公式，TPOT 的 KV 项随 <span class=\"formula\">$$B$$</span> 线性增长，<span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 不变，于是 TPOT 越过上限；同时整块预填插入 decode 批，长提示把迭代拉长，短请求的 TPOT 被拖尾，P99 进一步恶化。TTFT 一侧，预填浮点量除以 <span class=\"formula\">$$F_{\\text{eff}}$$</span> 的项未变，但排队迭代数 <span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 乘以更高的 TPOT，使 TTFT 也越过上限——两个不等式同时被破坏。系统层面表现为：前端超时、重试增加、有效到达率上升，调度器看到更多待处理请求又把批推得更大，TPOT 继续恶化，形成发散。识别这个反例的信号有三个：吞吐上升但成功请求率下降；TPOT 的 P99 与批大小同向增长；TTFT 的恶化幅度大于预填量变化所能解释的幅度（说明是 <span class=\"formula\">$$\\ell_{\\text{queue}}\\cdot\\mathrm{TPOT}$$</span> 项在放大）。修复不是简单调回 <span class=\"formula\">$$B_0$$</span>，而是按 SLO 反解可行批大小、恢复 chunked prefill 并给预填设每迭代预算，再把长请求分流到独立解码池；随后用实测 TPOT 与 TTFT 两条曲线验证交点位置，确认调度器运行点落在可行域内侧而非边界外侧。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-31\">三十一 · 误用的共同根源与工程判据</h3>\n<p>上述四种误用共享一个根源：把模型当成单向的吞吐预测器，而不是一对不等式组成的可行域约束。公式的两项——TPOT 的批线性项与 TTFT 的排队放大项——分别对应两个方向相反的力：增大 <span class=\"formula\">$$B$$</span> 提升吞吐、恶化 TPOT；增大 <span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 或整块预填恶化 TTFT。任何只优化其中一项的调参都会在另一项上失守。工程判据可以固化为三条监控规则：其一，调度器每次调整批上限前，用当前实测的 <span class=\"formula\">$$\\mathrm{BW}_{\\text{HBM}}$$</span>、<span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 与 KV 项系数反解 <span class=\"formula\">$$B_{\\max}$$</span>，运行点不得超过它；其二，按请求长度分桶看 TPOT 的 P99，出现拖尾即触发 chunked prefill 与长请求分流；其三，跨节点 EP 部署必须把通信段作为独立加项实测并写入容量模型，禁止直接用 HBM 带宽模型外推。代价方面，守住可行域意味着放弃吞吐峰值附近的边际收益，并付出预填切碎带来的 <span class=\"formula\">$$F_{\\text{eff}}$$</span> 损失；但对交互式负载，成功请求率与尾延迟才是真实产出，吞吐峰值只是不可兑现的账面数字。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-32\">三十二 · 三种误用如何把 SLO 预算悄悄吃掉</h3>\n<p>这套模型最容易被误用的地方，是把 TPOT 当成一个只随批大小单调变化的标量，然后拿吞吐曲线的拐点直接当部署批大小。后果是交互式 SLO 被系统性击穿：TPOT 的分子里 <span class=\"formula\">$$B_{\\text{act}}$$</span> 是权重读取项，与批无关；<span class=\"formula\">$$B\\,s\\,b_{kv}\\,2L H_{kv} d_h$$</span> 是 KV 读取项，随批线性增长；两者相加除以 HBM 带宽后再叠加 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span>。真正决定可行域的是两条不等式——TPOT 上限与 TTFT 上限——而不是吞吐。识别方法很直接：在压测里固定输入输出长度分布，把批从 8 扫到 256，记录每档的 TPOT 实测值与模型预测值，若实测曲线在某个批之后开始上翘而吞吐仍在涨，说明已经越过 TPOT 上限；此时继续加大批，等于用交互请求的超时换吞吐报表上的数字。代价体现在尾延迟上：一个被拖到 SLO 边界之外的 decode 迭代，会让该批内所有请求的 TPOT 一起恶化，而调度器往往只看到平均 TPOT 尚可。</p>\n<p>第二个高频误用是忽略 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span>。小批场景下权重读取项占主导，KV 项很小，此时每层 kernel 启动与同步的固定开销在 TPOT 中占比显著上升。若模型里把 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 置零去反解批大小，会得到偏乐观的吞吐估计，进而把批开得过大或把 TPOT 预算定得过紧。层数多的模型上这一项按层累加，误差在每 token 上可达数十微秒量级——对 TPOT 上限只有几十毫秒的交互式服务，这是必须计入的常数项。识别信号是：实测 TPOT 在小批区间明显高于纯带宽模型预测，且随层数增加而放大，而增大批后两者逐渐收敛。工程判断上，应当把 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span> 作为标定参数从实测中拟合，而不是当作可忽略的噪声。</p>\n<p>第三个误用出现在并行与长度分布两个维度上。跨节点专家并行时，All-to-All 时延与链路带宽是独立加项，纯 HBM 带宽模型会低估 TPOT，SLO 预算被系统性低估；识别方式是比对单节点与跨节点配置下同一批大小的 TPOT 实测差值，若差值不随批变化而近似恒定，即为通信加项而非带宽项。批内长度差异大时，decode 迭代被最长序列拖尾，尾延迟恶化；此时需用分块预填与 chunked prefill 修正，把长请求的预填切块插入 decode 迭代之间，避免单个长序列独占一次迭代。反例：一个混合长短请求的在线服务，调度器按总 token 数贪心组批，把一条 8K 提示与数十条短请求放进同一批，结果该批的 decode 迭代被长序列的 KV 读取拖慢，短请求的 TPOT 从达标区间被推到上限之外；正确做法是把长请求路由到独立解码池，或在预填阶段用 chunked prefill 切块，使每轮迭代的 KV 读取量可控。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>只按吞吐调大批</td><td>吞吐仍升而 TPOT 实测上翘</td><td>批内全体请求尾延迟恶化、交互超时</td></tr><tr><td>忽略 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span></td><td>小批 TPOT 高于带宽模型、随层数放大</td><td>TPOT 预算被低估，批开得过大</td></tr><tr><td>跨节点 EP 不计 All-to-All</td><td>跨节点与单节点 TPOT 差值近似恒定</td><td>SLO 预算系统性低估</td></tr><tr><td>长短混批不做 chunked prefill</td><td>尾延迟随批内最大长度上升</td><td>decode 被最长序列拖尾</td></tr></tbody></table>\n<p>把这三类误用收束成一条工程规则：反解批大小与预填块大小时，必须同时代入 TPOT 与 TTFT 两条不等式，并把 <span class=\"formula\">$$\\tau_{\\text{launch}}$$</span>、All-to-All 加项、批内最大长度作为显式参数而非事后修正。TTFT 一侧的 <span class=\"formula\">$$\\ell_{\\text{queue}}$$</span> 同样受批大小影响——批越大，排队迭代数越多，TTFT 随 <span class=\"formula\">$$\\mathrm{TPOT}(B)\\cdot\\ell_{\\text{queue}}$$</span> 增长；只盯 TPOT 而放任队列深度，等于把超时从 decode 阶段挪到预填阶段。可行的做法是给每个请求打上长度分位标签，按分位路由到不同解码池，池内再按 TPOT 上限反解批大小，使每条不等式的松弛量都可观测。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-33\">三十三 · 三类误用：把模型当成调参旋钮的代价</h3>\n<p>第一类误用是把吞吐最大化当作唯一目标，只调大批而不校验 TPOT 上限。后果是交互式 SLO 被静默击穿：批越大，KV 读取项 <span class=\"inline-math\">\\(B\\,s\\,b_{kv}\\,2L H_{kv} d_h\\)</span> 线性膨胀，TPOT 单调上升，而吞吐曲线在饱和区已趋平——多出来的批只换来排队更久。识别方法是做一次反解：把 SLO 的 TPOT 上限代入 <span class=\"inline-math\">\\(\\mathrm{TPOT}(B)\\)</span> 解出 <span class=\"inline-math\">\\(B_{\\max}\\)</span>，再与调度器实际运行的批大小对比；若实际批长期大于 <span class=\"inline-math\">\\(B_{\\max}\\)</span>，说明调度器在拿尾延迟换账面吞吐。工程上应把 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 作为准入约束写进连续批处理的分批逻辑，而不是留给运维事后发现。</p>\n<p>第二类误用是忽略 <span class=\"inline-math\">\\(\\tau_{\\text{launch}}\\)</span>，在小批场景高估吞吐。层数多的模型每 token 要叠加几十次 kernel 启动与同步，固定开销与批无关，却在小批时占比极高——此时公式里 KV 项很小，<span class=\"inline-math\">\\(\\tau_{\\text{launch}}\\)</span> 反而主导 TPOT。误判的后果是容量规划偏乐观：按纯带宽模型算出的小批 TPOT 明显低于实测，SLO 预算被系统性低估。识别方式是做批大小扫描，观察 TPOT 随 B 下降是否趋于一个非零平台；若平台明显高于带宽项预测，就是启动开销在起作用，此时应转向减少 kernel 数或合并算子，而非继续缩批。</p>\n<p>第三类误用出现在专家并行跨节点部署：只算 HBM 带宽项，不把 All-to-All 时延与链路带宽作为独立加项计入 TPOT。此时 <span class=\"inline-math\">\\(\\mathrm{TPOT}(B)\\)</span> 的 HBM 部分只是下限，真实迭代时延由跨节点交换主导，纯带宽模型会稳定低估，且低估幅度随 EP 规模扩大。识别信号是 TPOT 对批大小不敏感、却对 EP 度数与拓扑敏感——这正是通信项而非读取项在支配。对策是把 All-to-All 时延写成 TPOT 的加项重新反解 <span class=\"inline-math\">\\(B_{\\max}\\)</span>，并考虑把解码池限制在单节点 NVLink 域内。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>只追吞吐调大批</td><td>KV 读取项随 B 线性增长</td><td>TPOT 越过 SLO，交互请求超时</td><td>实际批 &gt; 反解出的 <span class=\"inline-math\">\\(B_{\\max}\\)</span></td></tr><tr><td>忽略 <span class=\"inline-math\">\\(\\tau_{\\text{launch}}\\)</span></td><td>固定开销在小批时主导</td><td>容量规划偏乐观，SLO 预算低估</td><td>TPOT 随 B 下降出现非零平台</td></tr><tr><td>跨节点 EP 不计 All-to-All</td><td>通信成为独立加项</td><td>TPOT 被系统性低估</td><td>TPOT 对 B 不敏感、对 EP 拓扑敏感</td></tr></tbody></table>\n<p>一个具体反例：某交互式服务把批大小从数十推到数百以拉高吞吐，账面上 tokens/s 上升，但 <span class=\"inline-math\">\\(\\mathrm{TPOT}(B)\\)</span> 的 KV 项随之线性抬高，叠加每层 <span class=\"inline-math\">\\(\\tau_{\\text{launch}}\\)</span> 后单 token 时延越过 SLO 上限；同时批内混入长提示请求，decode 迭代被最长序列拖尾，尾延迟进一步恶化。正确做法不是回调批大小了事，而是用分块预填与 chunked prefill 把长请求切块，并把长请求路由到独立解码池，让主池的 <span class=\"inline-math\">\\(B_{\\max}\\)</span> 由短请求的 TPOT 不等式单独圈定——边界条件变了，可行域才重新成立。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>B</td><td>并发解码批大小</td></tr><tr><td>\\tau_{\\text{launch}}</td><td>每层/每kernel启动与同步固定开销</td></tr><tr><td>P_{\\text{prefill}}(s_p)</td><td>预填阶段浮点运算量（随提示长度s_p增长）</td></tr><tr><td>F_{\\text{eff}}</td><td>预填实测有效算力</td></tr><tr><td>\\ell_{\\text{queue}}</td><td>请求在队列中等待的迭代数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-batch-latency-slo · 共 5 个片段</p>\n"},{"id":"th-quant-error-bound","title":"NVFP4量化误差界","direction":"dir-nvfp4-fp8-quant","prereq":[],"plain":"分块微缩放量化把权重量化误差上界写成块内动态范围除以2的位宽次方，NVFP4的E2M1加两级缩放（FP8 per-block、FP32 per-tensor）把相对误差压到约百分之几，但激活离群值会突破该界。","definition":"分块微缩放量化把权重量化误差上界写成块内动态范围除以2的位宽次方，NVFP4的E2M1加两级缩放（FP8 per-block、FP32 per-tensor）把相对误差压到约百分之几，但激活离群值会突破该界。","formula":"$$\\left|\\hat{w}-w\\right|\\le\\frac{\\Delta_{\\text{blk}}}{2}=\\frac{\\max_{i\\in\\text{blk}}|w_i|}{2^{b-1}},\\qquad \\varepsilon_{\\text{rel}}\\approx\\frac{\\mathbb{E}[|w-\\hat{w}|]}{\\mathbb{E}[|w|]}\\le\\frac{1}{2^{b}}\\cdot\\frac{\\mathrm{range}}{\\mathrm{rms}}$$","variables":[{"sym":"\\Delta_{\\text{blk}}","meaning":"量化块（如16或32元素）内的量化步长"},{"sym":"b","meaning":"尾数有效位宽（NVFP4的E2M1为2位尾数，等效b≈3）"},{"sym":"\\mathrm{range}","meaning":"块内动态范围max|w|"},{"sym":"\\mathrm{rms}","meaning":"块内权重均方根"}],"derivation":"推导关键一步：以块内最大绝对值定标得到步长，舍入误差不超过半步长$$\\Delta_{\\text{blk}}/2$$；再把绝对误差除以权重均值得到相对误差界，动态范围与rms之比成为放大因子。","example":"用途：用于判断某层权重能否安全降到NVFP4、块大小选16还是32、以及是否需要对特定通道保留FP8；也是量化后精度回归测试的触发阈值依据。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["激活存在>6σ离群通道时，per-tensor缩放被拉大，小块内有效位宽骤降，误差界失效（需SmoothQuant式通道均衡或MXFP8回退）","误差界只约束单次GEMM输出，多层累积与路由softmax放大后，端到端困惑度退化需实测而非由该界推出"],"system_note":"误用：把单次GEMM的误差界当作端到端精度保证，忽略多层累积与softmax放大，上线后困惑度明显退化；对含离群激活的层强行per-tensor缩放，等效位宽骤降导致输出崩坏。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：分块微缩放量化把权重量化误差上界写成块内动态范围除以2的位宽次方，NVFP4的E2M1加两级缩放（FP8 per-block、FP32 per-tensor）把相对误差压到约百分之几，但激活离群值会突破该界。","公式中$$\\Delta_{\\text{blk}}=\\max_{i\\in\\text{blk}}|w_i|/2^{b-1}$$为块内量化步长，$$b$$为尾数有效位宽（NVFP4的E2M1为2位尾数，等效$$b\\approx3$$）；$$\\varepsilon_{\\text{rel}}\\le(1/2^b)(\\mathrm{range}/\\mathrm{rms})$$说明块内动态范围与rms之比越大误差越大。","推导关键一步：以块内最大绝对值定标得到步长，舍入误差不超过半步长$$\\Delta_{\\text{blk}}/2$$；再把绝对误差除以权重均值得到相对误差界，动态范围与rms之比成为放大因子。","适用边界：激活存在>6σ离群通道时per-tensor缩放被拉大，小块内有效位宽骤降，误差界失效，需SmoothQuant式通道均衡或MXFP8回退；该界只约束单次GEMM输出，多层累积与路由softmax放大后端到端困惑度退化需实测而非由该界推出。","用途：用于判断某层权重能否安全降到NVFP4、块大小选16还是32、以及是否需要对特定通道保留FP8；也是量化后精度回归测试的触发阈值依据。","误用：把单次GEMM的误差界当作端到端精度保证，忽略多层累积与softmax放大，上线后困惑度明显退化；对含离群激活的层强行per-tensor缩放，等效位宽骤降导致输出崩坏。"],"anchors":["NVFP4的E2M1为2位尾数","等效b≈3","块大小16或32",">6σ离群通道"],"pitfalls":["把单次GEMM误差界当作端到端精度保证，忽略多层累积与路由softmax放大。","对含>6σ离群激活的层强行per-tensor缩放，块内有效位宽骤降导致输出崩坏。","未按块内动态范围与rms之比评估，块大小选得过小反而放大缩放开销与误差。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-1\">一 · 一句话直觉：误差上界就是块内动态范围除以位宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-2\">二 · 严格定义：从半步长到相对误差放大因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-3\">三 · 为什么需要这个界：三个工程决策的触发阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-4\">四 · 常见误解之一：把单次 GEMM 的界当成端到端精度保证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-5\">五 · 常见误解之二：对含离群激活的层强行 per-tensor 缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-6\">六 · 误差界的适用半径：从块内半步长到端到端退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-7\">七 · 步长公式的逐项解剖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-8\">八 · 从绝对界到相对界：除以均值那一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-9\">九 · 失效条件的机制链条</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-10\">十 · 界的适用域：单次 GEMM 与端到端之间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-11\">十一 · 误差界的适用边界与系统代价：从单次 GEMM 到端到端失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-12\">十二 · 边界的第一层：误差界只对“单次 GEMM、块内定标”成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-13\">十三 · 失效条件一：&gt;6σ 离群通道把 per-tensor 缩放拉爆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-14\">十四 · 失效条件二：多层累积与 softmax 放大，界不再可加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-15\">十五 · 规模上限：块大小、序列长度与批维度的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-16\">十六 · 误用清单与工程判别流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-17\">十七 · 误差界的三道断点：离群通道、块内动态范围与端到端放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-18\">十八 · 把误差界换算成&quot;可接受块内动态范围&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-19\">十九 · 用误差界定批大小：精度预算与显存预算的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-20\">二十 · 用误差界定并行度：张量并行切分与误差累积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-21\">二十一 · 用误差界定 KV 预算：量化 KV 的误差放大与容量折中</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-22\">二十二 · 用误差界定 SLO：延迟预算下的精度-吞吐前沿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-23\">二十三 · 算例：一个解码层的批大小、并行度与 KV 预算联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-24\">二十四 · 误差界进容量模型：批大小、并行度与 KV 预算的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-25\">二十五 · 把单次 GEMM 的界当成端到端承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-26\">二十六 · 对含离群激活的层强行 per-tensor 缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-27\">二十七 · 忽略 range/rms 而把块选小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-28\">二十八 · 一个反例：路由 softmax 放大单 GEMM 的“合格”误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-29\">二十九 · 误用的共同结构：把界的定义域当成结论域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-30\">三十 · 误用与反例：把误差界当成上线许可证</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:591px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 591.3 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：分块微缩放量化把权重量化误差上界写成块内动态范围除以2的位宽次方，…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\left|\\hat{w}-w\\right|\\le\\frac{…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"509.3\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：激活存在&gt;6σ离群通道时，per-tensor缩放被拉大，小块内有…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-quant-error-bound-sec-1\">一 · 一句话直觉：误差上界就是块内动态范围除以位宽</h3>\n<p>把一块权重（典型 16 或 32 个元素）压成低精度时，最自然的做法是拿块内绝对值最大的那个元素定标：它必须落在可表示的最大码点上，其余元素按比例落进去。于是块内量化步长被这个最大值唯一确定，任何元素的舍入误差都不会超过半个步长。这就是 NVFP4 误差界全部直觉的来源——误差不是由权重“平均有多大”决定，而是由块内“最大有多大”决定。块内越不均匀，最大值离大多数元素越远，步长越粗，误差越大。</p>\n<p>形式化地，设块内权重为 $w_i$，尾数有效位宽为 $b$，则步长与绝对误差界为：</p>\n<div class=\"formula\">$$\\Delta_{\\text{blk}}=\\frac{\\max_{i\\in\\text{blk}}|w_i|}{2^{b-1}},\\qquad |\\hat{w}-w|\\le\\frac{\\Delta_{\\text{blk}}}{2}=\\frac{\\max_{i\\in\\text{blk}}|w_i|}{2^{b}}$$</div>\n<p>NVFP4 的 E2M1 只有 2 位尾数，等效 $b\\approx3$，因此单元素绝对误差上界约为块内最大绝对值的 $1/8$。这个数字看起来粗糙，但两级缩放（FP8 per-block、FP32 per-tensor）把“块内最大绝对值”本身也压到了一个受控范围内，于是相对误差落到百分之几的量级。关键在于：界是逐块的，不是逐张量的；一个张量里只要有一块动态范围大，那一块就独自承担粗误差，不会污染其他块。</p>\n\n<h3 id=\"th-quant-error-bound-sec-2\">二 · 严格定义：从半步长到相对误差放大因子</h3>\n<p>严格地说，NVFP4 的误差界是一个关于“块内动态范围与 rms 之比”的不等式。推导分两步。第一步，以块内最大绝对值定标，量化格点间距为 $\\Delta_{\\text{blk}}$，最近邻舍入的误差绝对值不超过 $\\Delta_{\\text{blk}}/2$，这一步只用到舍入的几何性质，与数据分布无关。第二步，把绝对误差除以块内权重的平均绝对值，得到相对误差：</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{rel}}\\approx\\frac{\\mathbb{E}[|w-\\hat{w}|]}{\\mathbb{E}[|w|]}\\le\\frac{1}{2^{b}}\\cdot\\frac{\\mathrm{range}}{\\mathrm{rms}}$$</div>\n<p>这里 $\\mathrm{range}=\\max_{i\\in\\text{blk}}|w_i|$，$\\mathrm{rms}$ 是块内权重均方根。放大因子 $\\mathrm{range}/\\mathrm{rms}$ 是全部工程含义所在：块内元素越接近等幅，这个比值越接近 1，相对误差就越接近 $1/2^{b}$ 的下限；块内若有一个元素远大于其余（重尾分布），比值抬升，有效位宽被这个离群元素“吃掉”。换句话说，NVFP4 的精度不是由位宽单独决定，而是由位宽与块内均匀性的乘积决定。</p>\n<p>这个定义还隐含一个块大小的取舍。块越小，块内越容易均匀，$\\mathrm{range}/\\mathrm{rms}$ 越接近 1，误差界越紧；但块越小，每块要存一个 FP8 缩放因子，缩放因子的存储与读取开销占比上升，且定标、反定标的指令数随块数线性增长。块选 16 还是 32，本质是在“界更紧”与“缩放开销更低”之间取平衡，而不是精度越高越好。</p>\n<p>需要强调界的适用范围：它约束的是单次 GEMM 的输出误差，即一次矩阵乘中权重侧引入的扰动。它不约束多层串联后的激活误差，也不约束经过路由 softmax 或注意力 softmax 归一化后的概率扰动——那些环节会把局部误差非线性放大，端到端困惑度退化必须实测，不能由这个界推出。</p>\n\n<h3 id=\"th-quant-error-bound-sec-3\">三 · 为什么需要这个界：三个工程决策的触发阈值</h3>\n<p>这个界不是学术装饰，它在推理系统里有三个直接用途。第一，判断某层权重能否安全降到 NVFP4。做法是抽样若干块，算 $\\mathrm{range}/\\mathrm{rms}$，若该比值落在使 $\\varepsilon_{\\text{rel}}$ 超过容忍阈值的区间，则该层应保留 FP8 或改用更小塊。第二，决定块大小。同一层在块 16 与块 32 下的界不同，若块 32 的界已经满足阈值，就没必要付块 16 的缩放开销。第三，决定是否需要通道级干预。若某层激活存在 >6σ 的离群通道，per-tensor 缩放会被这个通道拉大，导致小块内有效位宽骤降，此时要么上 SmoothQuant 式通道均衡把离群度摊平，要么对该层回退 MXFP8。</p>\n<p>系统代价上，这个界直接影响三件事。显存：权重从 FP8 降到 NVFP4 使权重占用减半，但每 16 元素一个 FP8 缩放因子意味着额外约 6% 的缩放存储，块 32 则约 3%，块越小收益越被侵蚀。带宽：解码阶段权重读取是 roofline 的分子，权重位宽减半直接把解码 token 间延迟的权重带宽项减半，这是 NVFP4 在低批解码下最实在的收益。算力：tcgen05 的 NVFP4 MMA 吞吐高于 FP8，但若为了守住误差界而对部分通道保留 FP8，混合精度会打断整块 MMA 的流水，反而损失吞吐。因此界的用途不是“能不能压”，而是“压了之后要不要混精度、混到什么粒度”。</p>\n<p>具体例子：某线性层权重呈重尾，多数块 $\\mathrm{range}/\\mathrm{rms}$ 接近 1，但少数块因个别大权重使比值抬升数倍，这些块的 $\\varepsilon_{\\text{rel}}$ 逼近 $1/2^{b}$ 的数倍。工程处理不是整层回退，而是把这些块单独标记、以块 16 重量化或对这些块保留 FP8，其余块维持 NVFP4——界提供了“按块分级”的依据，而不是“按层一刀切”。</p>\n\n<h3 id=\"th-quant-error-bound-sec-4\">四 · 常见误解之一：把单次 GEMM 的界当成端到端精度保证</h3>\n<p>最常见的误用是把 $\\varepsilon_{\\text{rel}}\\le(1/2^{b})(\\mathrm{range}/\\mathrm{rms})$ 读成“整网精度不会掉超过这个数”。这个界只描述一次 GEMM 中权重扰动对输出的相对影响，而端到端退化要经过多层复合。层间误差不是简单相加：若每层引入相对扰动 $\\varepsilon$，经过 $L$ 层后激活的相对偏差大致按 $(1+\\varepsilon)^{L}$ 累积，深度越大放大越明显；更关键的是 softmax 与路由的归一化会把小的 logits 扰动放大成概率分布的显著偏移，尤其是路由 softmax 在专家分数接近时对扰动极敏感。因此上线前必须做量化后精度回归测试，以实测困惑度或任务指标为触发阈值，而不是拿这个界当验收标准。</p>\n<p>工程判断上，这个界适合做“筛查”而非“担保”：用它快速定位高风险层，把实测算力集中在这些层上。若某层界很紧却仍在端到端测试中出问题，说明问题不在权重侧量化，而在激活离群或归一化环节，应转向通道均衡或激活侧方案。</p>\n\n<h3 id=\"th-quant-error-bound-sec-5\">五 · 常见误解之二：对含离群激活的层强行 per-tensor 缩放</h3>\n<p>第二个高频错误发生在激活侧。NVFP4 的 per-tensor FP32 缩放本意是把整张量的动态范围纳入可表示区间，但若激活存在 >6σ 的离群通道，这个通道会把 per-tensor 缩放因子拉大，使得其余通道在小块内的有效位宽骤降——它们被压到很少的几个码点上，量化噪声相对其幅度急剧上升，输出直接崩坏。此时误差界的形式仍然成立，但界里的 $\\mathrm{range}/\\mathrm{rms}$ 已经被离群通道污染，界变得极松，等于失效。</p>\n<p>正确做法是通道均衡：用 SmoothQuant 式变换把激活的离群度迁移到权重侧（权重更容易被分块微缩放吸收），或对该层回退 MXFP8 让激活获得更宽的指数范围。判断是否需要干预的信号就是离群通道的 σ 倍数与 per-tensor 缩放被拉大的幅度；一旦确认，就不要在该层继续用 per-tensor 缩放的 NVFP4。</p>\n<p>第三个相关误解是块大小选得过小。直觉上块越小界越紧，但块小到一定程度后，缩放因子的读写与定标指令开销开始主导，且每块元素太少使 $\\mathrm{rms}$ 估计本身噪声变大，$\\mathrm{range}/\\mathrm{rms}$ 的估计不再稳定，界反而失去指导意义。块 16 与块 32 的选择应结合该层实测的 $\\mathrm{range}/\\mathrm{rms}$ 分布与缩放开销占比一起定，而不是默认取最小。</p>\n<p>把这三条放在一起，NVFP4 误差界的正确用法是：以块为单位算 $\\mathrm{range}/\\mathrm{rms}$ 得到相对误差估计，用它筛查高风险层与高风险块，对离群激活层做通道均衡或精度回退，最后以端到端实测作为上线门槛。界给的是方向与分级依据，不是保证书。</p>\n\n<h3 id=\"th-quant-error-bound-sec-6\">六 · 误差界的适用半径：从块内半步长到端到端退化</h3>\n<p>NVFP4的误差界不是一条对全模型无条件成立的保证，而是一份写明适用半径的契约。它的推导起点很朴素：在一个量化块（16 或 32 个元素）内取最大绝对值定标，步长 <span class=\"formula-inline\">Δ_blk = max|w_i| / 2^(b-1)</span>，舍入误差天然不超过半步长，于是得到绝对界 <span class=\"formula-inline\">|ŵ − w| ≤ Δ_blk/2</span>。把绝对误差除以权重均值，就得到相对形式 <span class=\"formula-inline\">ε_rel ≤ (1/2^b)·(range/rms)</span>。这里 b 是尾数有效位宽，E2M1 只有 2 位尾数，等效 b≈3，因此相对误差落在百分之几的量级——这正是 NVFP4 敢用于权重的原因。但请注意公式右侧那个放大因子：range/rms。块内动态范围与均方根之比越大，半步长相对权重均值就越粗，误差界越松。换句话说，这个界约束的是“块内足够均匀”的权重分布，而不是任意分布。</p>\n<p>失效条件的第一类来自激活而非权重。当某层激活存在 >6σ 的离群通道时，per-tensor 的 FP32 缩放会被这些极值拉大，导致整个张量的缩放因子偏大，落到每个小块上的有效位宽骤降——块内原本可分辨的权重被压进更少的量化格点，误差界所依赖的“半步长”假设在数值上被架空。此时误差界形式上仍写着，实际上已不构成约束。工程上的处置是明确的：要么用 SmoothQuant 式通道均衡把离群能量从激活迁移到权重，要么对该层回退到 MXFP8，不要指望调块大小能救回来。第二类失效更隐蔽：该界只约束单次 GEMM 的输出误差，多层串联后误差沿残差路径累积，路由 softmax 又会把小的 logits 扰动放大成专家选择的跳变，端到端困惑度的退化必须实测，不能由单层界推出。</p>\n<p>把这两类失效折算成系统代价，才能判断界是否“够用”。块大小选 16 时，缩放因子数量是权重的 1/16，FP8 per-block 缩放元数据带来的额外显存与带宽开销约为权重的 6%；选 32 则降到约 3%，但块内 range/rms 更大、界更松。这是一条显存带宽与精度之间的直接兑换：更小的块换来更紧的界，代价是解码阶段每个权重元素要多读一份缩放元数据，在 memory-bound 的 decode 步骤上直接体现为有效带宽下降。反过来，若为了省元数据把块放大，误差界放宽后可能需要更多层保留 FP8，反而增加混合精度的调度复杂度与 kernel 分支。至于离群激活导致的回退，代价不止是那一层的算力翻倍，还破坏了整网统一的 NVFP4 kernel 路径，迫使运行时在层间切换精度，增加流水线气泡。</p>\n<p>因此这份界的正确用法是三个具体判断，而非一句“精度没问题”。其一，逐层检查 range/rms 与是否存在 >6σ 通道，决定该层权重能否安全降到 NVFP4；其二，据此选块大小 16 还是 32，并把缩放开销计入 decode 带宽预算；其三，把界换算成量化后精度回归测试的触发阈值——单次 GEMM 输出偏差超过界所给比例时报警，但上线判定仍以实测困惑度为准。常见误用恰恰跳过第三步：拿单层界当端到端承诺，或对含离群激活的层强行 per-tensor 缩放，结果块内有效位宽骤降、输出崩坏。界是筛选器，不是保单。</p>\n<h3 id=\"th-quant-error-bound-sec-7\">七 · 步长公式的逐项解剖</h3>\n<p>公式的第一行是纯舍入几何：<span class=\"formula\">$$\\left|\\hat{w}-w\\right|\\le\\frac{\\Delta_{\\text{blk}}}{2}=\\frac{\\max_{i\\in\\text{blk}}|w_i|}{2^{b-1}}$$</span>。这里没有概率，没有统计假设，只有一条硬约束——块内任何一个权重被映射到最近的可表示格点后，它与原值的距离不超过相邻格点间距的一半。理解这条式子的关键在于认清三个量的来源各不相同：<span class=\"formula\">$$\\max_{i\\in\\text{blk}}|w_i|$$</span> 是数据决定的，随权重分布逐块浮动；<span class=\"formula\">$$2^{b-1}$$</span> 是格式决定的，对 NVFP4 的 E2M1 而言尾数只有 2 位，等效 <span class=\"formula\">$$b\\approx3$$</span>，于是分母落在 <span class=\"formula\">$$2^{2}=4$$</span> 这一档；<span class=\"formula\">$$\\Delta_{\\text{blk}}$$</span> 则是两者相除的商，是量化器实际写进缩放因子里的那个数。三者中只有 <span class=\"formula\">$$\\Delta_{\\text{blk}}$$</span> 是被存储的——per-block 的 FP8 缩放因子承载的就是它，per-tensor 的 FP32 缩放再把它整体平移一次。换句话说，两级缩放不是两次独立量化，而是把同一个步长拆成“粗粒度全局档位 + 细粒度块内档位”的乘积结构，块内格点间距由两级缩放因子的乘积唯一确定。</p>\n<p>工程上必须盯住的是分母的指数位置：<span class=\"formula\">$$2^{b-1}$$</span> 而非 <span class=\"formula\">$$2^{b}$$</span>。这个 <span class=\"formula\">$$-1$$</span> 来自对称量化的符号位占位——块内最大值必须能映射到格点的一端，剩下 <span class=\"formula\">$$b-1$$</span> 位才用于分辨幅度。对 E2M1，可表示幅度的档位极其稀疏，块内只要有元素贴近 <span class=\"formula\">$$\\max|w_i|$$</span>，其余元素就落进粗格点；这正是“块内动态范围”成为误差主导变量的格式根源。代价侧的直接推论：块越小，<span class=\"formula\">$$\\max_{i\\in\\text{blk}}|w_i|$$</span> 越接近块内 rms，步长越细，但每块要额外存一个 FP8 缩放因子，块大小从 32 降到 16 意味着缩放因子数量翻倍，权重侧的元数据带宽与解码时的缩放加载次数同步上升。这就是块大小 16 与 32 之间真正的取舍点——不是精度单调变好，而是精度收益与缩放开销、缩放访存延迟之间的对冲。</p>\n\n<h3 id=\"th-quant-error-bound-sec-8\">八 · 从绝对界到相对界：除以均值那一步</h3>\n<p>第二行 <span class=\"formula\">$$\\varepsilon_{\\text{rel}}\\approx\\frac{\\mathbb{E}[|w-\\hat{w}|]}{\\mathbb{E}[|w|]}\\le\\frac{1}{2^{b}}\\cdot\\frac{\\mathrm{range}}{\\mathrm{rms}}$$</span> 不是第一行的代数变形，而是一次统计化的近似。推导的关键步在于：绝对误差界 <span class=\"formula\">$$\\Delta_{\\text{blk}}/2$$</span> 是逐元素成立的，但要得到可跨层比较的相对误差，必须把分子分母都取期望。分子取 <span class=\"formula\">$$\\mathbb{E}[|w-\\hat{w}|]$$</span> 时隐含了一个均匀舍入假设——误差在 <span class=\"formula\">$$[-\\Delta_{\\text{blk}}/2,\\Delta_{\\text{blk}}/2]$$</span> 内近似均匀分布，于是期望绝对值约为 <span class=\"formula\">$$\\Delta_{\\text{blk}}/4$$</span>；分母取 <span class=\"formula\">$$\\mathbb{E}[|w|]$$</span> 则用块内 rms 作代理。两步近似叠加后，<span class=\"formula\">$$\\Delta_{\\text{blk}}$$</span> 里的 <span class=\"formula\">$$\\max|w_i|$$</span> 与分母的 rms 之比浮出水面，成为唯一的放大因子 <span class=\"formula\">$$\\mathrm{range}/\\mathrm{rms}$$</span>。</p>\n<p>这个放大因子是整条界的“良心”：当块内权重幅度均匀时，range 与 rms 同量级，比值接近常数，相对误差被 <span class=\"formula\">$$1/2^{b}$$</span> 压住；一旦块内出现一个远离主体的权重，range 被单点抬高而 rms 几乎不动，比值线性膨胀，误差界随之松脱。离散化与近似具体落在三处：其一，均匀舍入假设把最坏情况界换成了平均行为，对含极端值的块会低估误差；其二，用 rms 代理 <span class=\"formula\">$$\\mathbb{E}[|w|]$$</span> 在重尾分布下偏低，使比值被高估；其三，两级缩放的乘积结构被折叠进单一 <span class=\"formula\">$$\\Delta_{\\text{blk}}$$</span>，忽略了 FP8 块缩放因子自身的量化误差——这一项在块缩放因子动态范围跨度过大时会二次放大块内步长。系统代价上，这个比值直接决定某层能否安全降到 NVFP4：比值大的层，即便 b 固定，有效分辨率也被吃掉，表现为该层 GEMM 输出信噪比下降，进而在后续层被放大。</p>\n\n<h3 id=\"th-quant-error-bound-sec-9\">九 · 失效条件的机制链条</h3>\n<p>激活侧存在大于 6σ 的离群通道时，失效不是“精度略降”，而是界本身失去约束力。链条是这样的：per-tensor 的 FP32 缩放必须以全张量最大幅度定标，一个 6σ 通道把全局档位拉大，块内 FP8 缩放因子的可用动态范围被压缩，等效于块内有效位宽骤降——<span class=\"formula\">$$\\Delta_{\\text{blk}}$$</span> 不再由块内 <span class=\"formula\">$$\\max|w_i|$$</span> 决定，而由被全局档位挤压后的残余分辨能力决定。此时第一行的等式右端形式上仍成立，但 <span class=\"formula\">$$b$$</span> 已不是格式标称的等效 3，而是被离群值侵蚀后的实际值，界的数值意义被掏空。工程判断因此要分两路：对权重侧，按 <span class=\"formula\">$$\\mathrm{range}/\\mathrm{rms}$$</span> 逐块筛查，比值超阈的块保留 FP8 或改块大小；对激活侧，走 SmoothQuant 式通道均衡把离群幅度摊到相邻通道，或对含离群通道的层回退 MXFP8，用更宽的尾数换回被吃掉的位宽。</p>\n<p>代价必须算清楚：通道均衡是在推理图里插入一次逐通道缩放，前向多一次元素级乘，延迟增量随 hidden 维度线性走；MXFP8 回退则把该层权重带宽翻倍，在解码阶段的权重流带宽受限场景下直接压低 token 吞吐。这两条路的共同点是都在 GEMM 之外加了一次数据变换或格式切换，属于“用带宽/延迟换误差界有效性”的典型对冲。反例是强行对含离群激活的层保持 per-tensor 缩放，块内有效位宽骤降导致输出崩坏——这种崩坏在单层 GEMM 的数值检查里可能看不出来，因为界的形式仍满足，问题要到多层累积后才显形。</p>\n\n<h3 id=\"th-quant-error-bound-sec-10\">十 · 界的适用域：单次 GEMM 与端到端之间</h3>\n<p>这条界只约束单次 GEMM 的输出误差，它的推导里没有任何跨层传播项。多层累积的机制是：每层引入的相对误差经权重矩阵与激活非线性放大，路由 softmax 再把专家选择的微小分数扰动转成离散的路由翻转，误差从连续量变成结构性跳变。因此端到端困惑度退化不能由该界推出，只能实测。工程上的正确用法是把界当触发阈值而非保证：对每层算出 <span class=\"formula\">$$\\varepsilon_{\\text{rel}}$$</span> 的上界，超过预设阈值的层进入精度回归测试清单，用真实校准集跑端到端困惑度与任务指标，而不是拿单层界去背书上线。</p>\n<p>伪代码思路可以写成：逐块计算 <span class=\"formula\">$$\\max|w_i|$$</span> 与 rms，得到比值；比值低于阈值则标 NVFP4，高于阈值则标 FP8 候选；再对激活侧统计逐通道幅度，标记 >6σ 通道，命中则对该层插入均衡或回退。这条流程的代价是离线标定的一次性开销，换来的线上收益是避免“界满足但精度崩”的误判。块大小选择也在这里落地：块 16 让比值更贴近 1、界更紧，但缩放因子翻倍抬高解码期元数据带宽；块 32 省带宽但比值方差更大，需要更保守的回退策略。判断依据是层内权重分布的均匀度，而非格式标称精度。</p>\n<table class=\"mini\"><thead><tr><th>量</th><th>来源</th><th>对界的影响</th><th>系统代价落点</th></tr></thead><tbody><tr><td><span class=\"formula\">$$\\max_{i\\in\\text{blk}}|w_i|$$</span></td><td>数据，逐块浮动</td><td>直接定步长</td><td>块越小越贴近 rms，缩放因子翻倍</td></tr><tr><td><span class=\"formula\">$$b\\approx3$$</span></td><td>E2M1 格式，2 位尾数</td><td>分母 <span class=\"formula\">$$2^{b-1}$$</span></td><td>固定，无调节余地</td></tr><tr><td><span class=\"formula\">$$\\mathrm{range}/\\mathrm{rms}$$</span></td><td>块内分布形状</td><td>相对误差放大因子</td><td>决定该层是否回退 FP8/MXFP8</td></tr><tr><td>per-tensor 缩放</td><td>全张量最大幅度</td><td>离群时侵蚀有效位宽</td><td>均衡插入元素级乘或格式切换</td></tr></tbody></table>\n<p>最后落在机制上：这条界的价值不在于给出一个可上线背书的数字，而在于把“块内动态范围与 rms 之比”变成可计算的层筛选信号——比值是权重分布的函数，可在量化前离线批量算出，直接决定块大小、FP8 保留位与均衡插入点，把精度风险从上线后的困惑度回归前移到编译期的格式分配决策。</p>\n\n<h3 id=\"th-quant-error-bound-sec-11\">十一 · 误差界的适用边界与系统代价：从单次 GEMM 到端到端失真</h3>\n\n<p>上一节给出的界只回答一个问题：在给定块内动态范围与尾数位宽时，单次乘加的绝对误差不超过半步长。把它当成可交付的精度承诺之前，必须先看清这个界的三个隐含前提。第一，它假设块内元素服从近似均匀的幅度分布，因此以 max|w| 定标是紧的；一旦块内出现少数远大于其余元素的权重，定标被少数元素绑架，其余元素的舍入相对误差被成倍放大——这正是 <span class=\"formula\">$$\\varepsilon_{\\text{rel}}\\le(1/2^b)(\\mathrm{range}/\\mathrm{rms})$$</span> 中 range/rms 放大因子的物理含义。第二，它假设缩放因子本身可被精确表示；NVFP4 的两级缩放（FP8 per-block、FP32 per-tensor）中，per-block 缩放被压到 FP8 的有限动态范围里，块间缩放差异过大时，FP8 缩放自身的舍入会叠加到权重误差上，此时界不再只由 b 决定。第三，它只约束一次 GEMM 的输出，不约束该输出进入后续非线性、残差与路由后的传播。</p>\n\n<p>失效条件里最需要工程警觉的是激活侧。当某层输入存在大于 6σ 的离群通道时，per-tensor 缩放被这些通道拉大，导致正常通道落入更粗的量化格点，小块内的有效位宽骤降；此时权重侧的界仍然成立，但激活量化误差主导了 GEMM 输出偏差，界失去解释力。工程上的处置不是调块大小，而是通道均衡（SmoothQuant 式把激活尺度迁移到权重）或对该层回退到 MXFP8——后者以更宽的尾数换取对离群值的容忍，代价是权重带宽翻倍，直接抬高解码阶段的显存读取时间。判断是否需要回退，可用一个廉价探针：统计各通道激活的 max/rms 比，超过阈值的层标记为高风险，先在小校准集上比对 FP8 与 NVFP4 的输出余弦相似度，再决定是否整层回退。</p>\n\n<p>块大小的选择同样受这个界约束，但方向与直觉相反。缩小块（16 而非 32）确实降低块内 range/rms，使界更紧，代价是缩放因子数量翻倍：每 16 个元素附带一个 FP8 缩放，元数据开销在权重带宽中占比上升，且反量化时每个块都要做一次缩放乘加，SM 上的指令开销与 TMEM 读写次数同步增加。对权重静态、解码受显存带宽约束的场景，块 16 的额外元数据可能吃掉量化带来的带宽收益；对预填阶段计算密集的 GEMM，缩放开销可被 MMA 流水掩盖，块 16 更划算。因此块大小的决策应绑定阶段：预填偏小、解码偏大，而不是全局统一。</p>\n\n<table class=\"mini\"><thead><tr><th>场景</th><th>界是否可信</th><th>主导代价</th><th>处置</th></tr></thead><tbody><tr><td>权重幅度均匀、无离群激活</td><td>可信，range/rms 接近 1</td><td>缩放元数据带宽</td><td>块 16，直接上线</td></tr><tr><td>存在 &gt;6σ 激活通道</td><td>失效，激活误差主导</td><td>回退 FP8 的权重带宽翻倍</td><td>通道均衡或整层 MXFP8</td></tr><tr><td>块内少数大权重</td><td>界变松，range/rms 放大</td><td>有效位宽下降</td><td>该通道保留 FP8 或拆块</td></tr></tbody></table>\n\n<p>最危险的误用是把单次 GEMM 的界外推为端到端保证。多层串联后误差并非线性叠加：残差路径会稀释偏差，而路由 softmax 与归一化会把小的 logits 偏差放大为专家选择翻转，一次翻转即改变整条计算路径，困惑度退化呈现阶跃而非渐进。这意味着界只能用作“某层能否安全降到 NVFP4”的准入判据与回归测试的触发阈值，不能替代实测。工程判断应落在：以界筛选候选层，以校准集上的逐层输出偏差与端到端困惑度做两级验收，并把离群通道探针纳入量化流水线的固定步骤，而不是在部署后被动回滚。</p>\n<h3 id=\"th-quant-error-bound-sec-12\">十二 · 边界的第一层：误差界只对“单次 GEMM、块内定标”成立</h3>\n<p>前两部分给出的界，成立的前提是三条硬性假设，缺一条就换公式。第一条：量化步长由块内最大绝对值定标，即 <span class=\"formula-inline\">Δ_blk = max|w_i| / 2^{b-1}</span>，舍入误差被夹在 ±Δ_blk/2 内。这要求块内元素确实被同一个步长覆盖，块大小 16 或 32 时，块内分布近似同尺度。第二条：误差度量是单次 GEMM 的输出误差，即 <span class=\"formula-inline\">|ŷ − y| ≤ ‖x‖·|ŵ − w|</span> 这一层线性传播，不涉及非线性、残差叠加与跨层放大。第三条：两级缩放中 per-block 的 FP8 scale 与 per-tensor 的 FP32 scale 都是静态或按校准集确定的，推理时不再随输入漂移。</p>\n<p>这三条假设在工程上对应一个明确的适用范围：权重侧、线性层、校准分布内的输入。一旦输入分布偏离校准集，或者该层后面紧跟 softmax、路由、LayerNorm 这类放大算子，界就从“保证”退化为“单算子局部参考”。判断某层能否安全降到 NVFP4，第一步不是算界，而是确认这三条是否同时成立；只要有一条不成立，就该把该层列入 FP8 保留名单，而不是继续用界去论证它安全。</p>\n<div class=\"formula\">$$\\left|\\hat{w}-w\\right|\\le\\frac{\\Delta_{\\text{blk}}}{2}=\\frac{\\max_{i\\in\\text{blk}}|w_i|}{2^{b-1}},\\qquad \\varepsilon_{\\text{rel}}\\approx\\frac{\\mathbb{E}[|w-\\hat{w}|]}{\\mathbb{E}[|w|]}\\le\\frac{1}{2^{b}}\\cdot\\frac{\\mathrm{range}}{\\mathrm{rms}}$$</div>\n<p>代价侧要看清：这个界约束的是权重张量的表示误差，不是 kernel 的实际吞吐。NVFP4 的 E2M1 只有 2 位尾数，等效 <span class=\"formula-inline\">b≈3</span>，理论相对误差量级在百分之几；但 tcgen05 的 MMA 吞吐提升来自位宽减半带来的 TMEM 带宽与 2-SM 配对收益，与误差界的大小没有函数关系。也就是说，界收紧了不代表吞吐变好，界失效了也不代表吞吐变差——两者必须分开评估。一个具体例子：某线性层块内 range/rms 比为 4，按 <span class=\"formula-inline\">1/2^3 × 4 = 0.5</span> 得到的相对误差界已经宽到没有工程意义，此时该层即使 kernel 跑得再快，也应回退 FP8，因为界的数值本身就在提示块内分布不适合 2 位尾数。</p>\n\n<h3 id=\"th-quant-error-bound-sec-13\">十三 · 失效条件一：>6σ 离群通道把 per-tensor 缩放拉爆</h3>\n<p>最典型的失效来自激活侧的离群通道。当某几层激活存在大于 6σ 的通道时，per-tensor 的 FP32 scale 会被这几个通道的最大值顶上去，导致其余通道分到的有效动态范围被压缩。对权重侧的分块界而言，这不会直接改写 <span class=\"formula-inline\">Δ_blk</span>，但它改变了“等效位宽”的实际含义：per-tensor 缩放拉大后，块内可表示的相对精度骤降，原本按 <span class=\"formula-inline\">b≈3</span> 算出的界不再描述真实舍入行为，界失效。</p>\n<p>机制上，这是两级缩放的结构性弱点：per-block scale 负责块内动态范围，per-tensor scale 负责全局动态范围，两者串联时，全局那一级被离群值绑架，块内那一级的有效位数就被吃掉。工程上的判别方法是逐通道统计激活的 max/rms 比，凡是超过 6σ 的通道单独标记；对这些层，per-tensor 缩放不再可信，必须走 SmoothQuant 式通道均衡（把激活的尺度搬到权重上，使两侧动态范围对齐），或者直接对该层回退 MXFP8——MXFP8 的块级指数更细，对离群通道的容忍度高于 NVFP4 的单级 per-tensor 结构。</p>\n<p>代价要算清楚：通道均衡本身是一次离线重参数化，推理时零额外开销，但它改变了权重分布，需要重新校准 per-block scale，校准成本按层数线性增长；MXFP8 回退则直接把该层的权重带宽翻倍，在 NVL72 这种带宽敏感的部署里，单层回退对整体 token 吞吐的影响取决于该层占的总 GEMM 时间比例。一个具体例子：MoE 模型的 router 前线性层，激活经 softmax 前存在尖锐峰值，>6σ 通道几乎必然出现，这一层应默认保留 FP8 或做通道均衡，而不是用 NVFP4 界的数值去论证它“误差在百分之几以内”。</p>\n\n<h3 id=\"th-quant-error-bound-sec-14\">十四 · 失效条件二：多层累积与 softmax 放大，界不再可加</h3>\n<p>第二个失效条件是界的可加性假设。单次 GEMM 的误差界是 <span class=\"formula-inline\">L∞</span> 意义上的局部界，多层串联时误差不会简单相加，而是被每层的 Jacobian 谱范数放大。对残差结构，放大因子近似为 <span class=\"formula-inline\">∏(1 + ‖J_l‖)</span>；对注意力里的 softmax，放大更剧烈：softmax 的输入扰动 δ 会引起输出扰动约 <span class=\"formula-inline\">‖∂softmax/∂z‖·δ</span>，当 logits 分布尖锐时该雅可比范数接近 1，误差被原样传递；当分布平坦时反而被压缩。这意味着同一套 NVFP4 权重，在不同输入上端到端退化程度不同，单次 GEMM 的界无法给出端到端保证。</p>\n<p>工程判断因此必须换指标：不看单层界的数值，而看端到端困惑度或任务指标的实测退化。触发阈值应设为“量化后精度回归测试的通过线”，而不是“单层界小于某值”。具体做法是分层灰度：先只量化对 softmax 不敏感的 MLP 中间层，测端到端；再逐层加入注意力投影，每加一层跑一次回归。任何一层加入后指标越线，就回退该层，而不是回头去修界的公式——界在这里的作用只是解释“为什么这层敏感”，不是预测“端到端会掉多少”。</p>\n<p>代价侧：分层灰度意味着校准与回归测试的迭代次数随层数增长，工程上通常按块粒度（每 8–16 层一组）做批量灰度以控制测试成本；而一旦上线后发现退化，回退单层带来的显存与带宽开销是离散的，不能靠调块大小 16 还是 32 来平滑。一个具体例子：路由 softmax 前的 logits 若因量化误差偏移，top-k 选择可能翻转，这种离散错误不是连续误差界能描述的，只能靠实测捕获；这也正是“界只约束单次 GEMM 输出”这句话的工程含义。</p>\n\n<h3 id=\"th-quant-error-bound-sec-15\">十五 · 规模上限：块大小、序列长度与批维度的三重约束</h3>\n<p>界还隐含一个规模上限，来自块大小与统计量的关系。块越小，块内 range/rms 比越接近 1，界越紧；但块越小，per-block scale 的数量越多，scale 本身的存储与读取开销占比上升，且块内元素太少时 max|w_i| 的估计方差变大，界的紧致性反而被统计噪声吃掉。块大小 16 与 32 的取舍就在这里：16 给出更紧的界但更多 scale 流量，32 反之。工程上应按层实测 range/rms 比来决定，而不是全局统一。</p>\n<p>序列长度维度上，界的适用性随上下文增长而下降。长上下文下 KV cache 的读取占主导，权重侧量化误差被摊薄，界对端到端的影响变小；但长上下文也意味着激活分布更宽，离群通道更容易出现，失效条件一被触发的概率上升。批维度上，大批量使单次 GEMM 的算术强度上升，量化误差在输出上的相对影响被平均化，界的局部性更明显；小批量解码阶段则相反，单 token 的误差直接暴露在输出上，界的约束力更强。这三重约束共同决定：NVFP4 的界在“短序列、大批量、MLP 层”上最可信，在“长序列、小批量、注意力与路由层”上最不可信。</p>\n<p>代价上，块大小从 32 降到 16 会使 scale 元数据翻倍，在 TMEM 与共享内存之间搬运 scale 的带宽开销上升；序列变长使 KV cache 显存占用按 <span class=\"formula-inline\">O(L)</span> 增长，权重侧省下的显存被 KV 侧吃掉，量化的收益被稀释。一个具体例子：在 GB200 NVL72 上做长上下文解码，权重 NVFP4 省下的显存若不足以抵消 KV cache 的增长，就该优先把显存预算给 KV 而不是给权重精度；此时界的数值再紧，也不构成把更多层降到 NVFP4 的理由。</p>\n\n<h3 id=\"th-quant-error-bound-sec-16\">十六 · 误用清单与工程判别流程</h3>\n<p>两类误用最致命。第一类：把单次 GEMM 的界当作端到端精度保证，忽略多层累积与 softmax 放大，上线后困惑度明显退化——这是把局部 <span class=\"formula-inline\">L∞</span> 界错当成全局界。第二类：对含 >6σ 离群激活的层强行 per-tensor 缩放，块内有效位宽骤降导致输出崩坏——这是把权重侧的界套用到激活侧，而界从未约束激活。两类误用的共同点是：用界的数值替代了实测，把“理论上界”读成“工程保证”。</p>\n<p>判别流程可以固化为四步：其一，逐层统计权重块内 range/rms 比，比值大的层界本身就宽，优先保留 FP8；其二，逐通道统计激活 max/rms，标记 >6σ 通道，这些层禁用 per-tensor 缩放或做通道均衡；其三，按块粒度做端到端灰度回归，以任务指标通过线为触发阈值；其四，对通过灰度的层再评估块大小 16 与 32 的 scale 开销与界紧致度的权衡。四步的顺序不能颠倒——先算界再实测，会把界的宽窄误读为风险的宽窄。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>界是否成立</th><th>工程动作</th><th>主要代价</th></tr></thead><tbody><tr><td>权重线性层、校准分布内输入</td><td>成立</td><td>可按界判断是否降 NVFP4</td><td>scale 元数据带宽</td></tr><tr><td>激活含 >6σ 离群通道</td><td>失效</td><td>SmoothQuant 均衡或 MXFP8 回退</td><td>该层权重带宽翻倍</td></tr><tr><td>后接 softmax / 路由</td><td>失效（不可加）</td><td>端到端灰度回归，不看单层界</td><td>校准与回归迭代成本</td></tr><tr><td>长序列、小批量解码</td><td>约束力强但收益被 KV 稀释</td><td>显存预算优先给 KV</td><td>KV cache 显存 O(L)</td></tr></tbody></table>\n<p>最后落在机制上：这个界的真正用途不是“证明某层安全”，而是“给出一个可计算的触发阈值”——当块内 range/rms 比与等效位宽 <span class=\"formula-inline\">b≈3</span> 算出的相对误差超过回归测试的容差时，该层就不该进 NVFP4；当激活侧出现 >6σ 通道时，界的推导前提已被破坏，任何数值都不再是保证。把这两条作为量化流水线的门禁，比事后用端到端退化去反推原因要省得多。</p>\n\n<h3 id=\"th-quant-error-bound-sec-17\">十七 · 误差界的三道断点：离群通道、块内动态范围与端到端放大</h3>\n<p>公式成立的前提是“块内最大绝对值定标、舍入不超过半步长”，而这一步在激活侧首先被打破。当某层输入存在超过 6σ 的离群通道时，per-tensor 的 FP32 缩放因子会被这些通道拉大，同一块内正常权重的有效位宽随之骤降——绝对误差界仍写着 Δ_blk/2，但 Δ_blk 已由离群值而非权重分布决定，等效 b 从 ≈3 掉到不足 2 位，输出直接崩坏。工程上的处置不是调块大小，而是先做 SmoothQuant 式通道均衡把离群能量迁移到权重侧，或对该层整体回退 MXFP8；判断触发条件应写进量化回归测试的门槛，而不是上线后靠困惑度报警。</p>\n<p>第二道断点在块内动态范围本身。相对误差界 ε_rel ≤ (1/2^b)·(range/rms) 表明放大因子是块内 max|w| 与 rms 之比：块越小，range/rms 越接近 1、界越紧，但缩放因子与元数据的开销随块数线性上升，NVFP4 每 16 或 32 元素一个 FP8 块缩放，块取 16 时缩放字节占比与反量化指令数都翻倍，SM100 上 tcgen05 的 TMEM 带宽和缩放加载会成为新的瓶颈。因此块大小选择是精度界与显存/带宽代价的折中，而非越小越准。</p>\n<p>第三道断点最容易被误用：该界只约束单次 GEMM 的输出误差，多层串联后误差按层间雅可比累积，路由 softmax 与注意力归一化又会把小的 logit 扰动放大成概率分布的偏移。端到端困惑度退化必须实测，不能由单层界推出；把 GEMM 界当作上线精度保证，正是量化后精度回归失败的主要来源。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>激活 >6σ 离群通道</td><td>per-tensor 缩放被拉大，块内有效位宽骤降</td><td>输出崩坏，需整层重算</td><td>SmoothQuant 均衡或 MXFP8 回退</td></tr><tr><td>块内 range/rms 过大</td><td>相对误差界放大因子失控</td><td>块取 16 时缩放开销与反量化指令翻倍</td><td>块 32 折中，或该层保留 FP8</td></tr><tr><td>多层累积与 softmax 放大</td><td>单 GEMM 界不覆盖端到端</td><td>困惑度退化，需实测回归</td><td>以实测退化设触发阈值</td></tr></tbody></table>\n<h3 id=\"th-quant-error-bound-sec-18\">十八 · 把误差界换算成\"可接受块内动态范围\"</h3>\n<p>推理侧做量化决策时，第一个要回答的不是\"这层能不能上 NVFP4\"，而是\"这层的块内动态范围与 rms 之比是否落在界允许的区间内\"。把前文的相对误差界$$\\varepsilon_{\\text{rel}}\\le\\frac{1}{2^{b}}\\cdot\\frac{\\mathrm{range}}{\\mathrm{rms}}$$反解，得到一条工程判据：给定可容忍的相对误差预算$$\\varepsilon_{\\text{budget}}$$，该层权重可安全量化的条件是$$\\frac{\\mathrm{range}}{\\mathrm{rms}}\\le 2^{b}\\cdot\\varepsilon_{\\text{budget}}$$。NVFP4 的 E2M1 等效$$b\\approx3$$，即$$2^{b}\\approx8$$；若把端到端精度回归允许的单层误差预算定在百分之几量级，则要求块内 range/rms 不超过数十倍。这个比值是一个纯统计量，可在离线标定时对每层每块直接算出，无需跑推理。</p>\n<p>关键在于它把\"精度风险\"变成了\"容量决策的输入\"。range/rms 大的块意味着块内存在尖峰权重，微缩放的 FP8 per-block 缩放因子被尖峰拉大，块内其余元素的量化步长随之变粗，等效位宽下降。工程上因此把每层划分为三类：range/rms 远低于阈值的块直接 NVFP4；接近阈值的块保留块大小 32 而非 16（更大块摊薄缩放开销，但会牺牲对尖峰的隔离，需实测权衡）；显著超阈值的块对该通道回退 FP8。这条分类规则直接决定权重显存占用——回退比例越高，NVFP4 相对 FP8 的 2 倍权重压缩收益越被侵蚀，容量规划必须按回退比例打折，而不是按理想 4 位密度计算。</p>\n<div class=\"formula\">$$\\text{可量化判据：}\\quad \\frac{\\max_{i\\in\\text{blk}}|w_i|}{\\mathrm{rms}_{\\text{blk}}}\\le 2^{b}\\,\\varepsilon_{\\text{budget}},\\qquad b\\approx3$$</div>\n<p>具体机制上，标定流程对每个线性层的权重按 16 或 32 元素切块，逐块计算 range/rms 并统计超阈值块占比。举例：某解码层权重整体接近高斯，绝大多数块 range/rms 在 3–4 之间（高斯分布极值比 rms 约 3–4 倍），远低于阈值，可整层 NVFP4；而个别含大尖峰的块比值可达数十倍，触发通道级 FP8 回退。代价是标定阶段的一次性扫描开销与回退通道带来的显存增量，收益是避免上线后困惑度退化。</p>\n\n<h3 id=\"th-quant-error-bound-sec-19\">十九 · 用误差界定批大小：精度预算与显存预算的联立</h3>\n<p>批大小在 NVFP4 推理里不是单纯的吞吐旋钮，它与精度预算耦合。连续批处理下，批内序列共享同一套权重，权重精度是批级共享的，因此权重侧的误差界不随批大小变化；但激活侧的误差界随批内 token 数变化——批越大，激活张量的统计越接近总体分布，离群通道被更多 token 命中，per-tensor 缩放被拉大的概率上升。这意味着批大小增大时，激活量化误差界的失效风险单调上升，而权重侧不变。</p>\n<p>于是定批大小变成一个双边约束：显存侧，权重按 NVFP4 密度、KV cache 按序列长度与并发数占用，剩余显存决定激活与中间缓冲的上限；精度侧，激活量化误差界要求批内激活的通道离群度不超过阈值，超过则需 SmoothQuant 式通道均衡或对激活回退 MXFP8。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{batch}^\\*=\\max\\{B:\\ \\text{mem}_{\\text{weight}}(B)+\\text{KV}(B,L)+\\text{act}(B)\\le \\text{HBM},\\ \\ \\text{outlier}(B)\\le\\theta\\}$$</div>\n<p>其中 outlier(B) 是批内激活通道的最大偏离度指标，θ 由误差界反解得到。工程判断是：当批大小受显存约束而非精度约束时，直接取显存上限；当精度约束先到，则批大小被钉在较小值，此时应改用激活回退或通道均衡把 θ 抬高，而不是硬压批大小牺牲吞吐。举例：一个 70B 级模型在单卡 NVFP4 权重下，权重显存按 4 位密度估算约 35 GB 量级，KV cache 随并发线性增长，激活缓冲随批线性增长；若激活离群在批超过某阈值后触发失效，则批大小应停在精度拐点，剩余吞吐靠增加数据并行副本补回，而非加大单副本批。</p>\n\n<h3 id=\"th-quant-error-bound-sec-20\">二十 · 用误差界定并行度：张量并行切分与误差累积</h3>\n<p>并行度决策里，误差界的作用是判断\"切分是否改变每层的量化误差结构\"。张量并行把单个 GEMM 的 K 维或 N 维切开，每张卡只持有部分权重块。由于 NVFP4 的微缩放是块内局部的，只要块边界与切分边界对齐（块大小 16 或 32 整除切分粒度），每张卡上的块内 range/rms 与原层一致，误差界不变。若切分粒度与块大小不对齐，跨卡拼接的块被拆散，块内动态范围被人为割裂，等效位宽在边界块上下降——这是并行度选择时必须避开的陷阱。</p>\n<p>因此并行度选取的第一条规则是：张量并行度应使每卡分到的权重维度是块大小的整数倍。第二条规则涉及误差累积：张量并行把一层拆成多卡的部分和再 all-reduce 求和，各卡的量化误差独立，求和后误差按方差叠加而非线性叠加，端到端误差增长慢于层数增长。这给并行度一个宽松的上界——增加张量并行度不会显著放大单层量化误差，但会引入 all-reduce 通信延迟，属于通信代价而非精度代价。</p>\n<div class=\"formula\">$$\\sigma_{\\text{sum}}^2=\\sum_{k=1}^{P}\\sigma_k^2,\\qquad \\sigma_k\\le\\frac{\\Delta_{\\text{blk},k}}{2}$$</div>\n<p>举例：把某层 N 维按 8 卡切分，若 N 是 32 的整数倍，则每卡块对齐、误差界逐卡成立，all-reduce 后误差方差为 8 份独立误差之和，标准差约为单卡的√8 倍但相对误差因分母同步增大而基本持平。代价是每层一次 all-reduce 的延迟，在 NVLink 5 域内可接受，跨节点则需权衡。工程判断：优先保证块对齐，其次才谈并行度大小；块不对齐时宁可减小并行度或改块大小。</p>\n\n<h3 id=\"th-quant-error-bound-sec-21\">二十一 · 用误差界定 KV 预算：量化 KV 的误差放大与容量折中</h3>\n<p>KV cache 量化是容量规划的核心杠杆，而误差界在此处的用法与权重侧不同：KV 的量化误差不经过权重矩阵的再缩放，而是直接进入注意力 softmax 的 logits。误差界只约束单次 GEMM 输出，KV 量化误差经 softmax 指数放大后，端到端影响需实测，不能由界直接推出。因此 KV 预算决策必须把\"界成立\"与\"端到端可接受\"分开处理：先用界判断 KV 量化在数值上是否可控，再用回归测试确认 softmax 放大后是否可接受。</p>\n<p>容量侧，KV cache 按每 token 每层 2×头数×头维×字节数计。NVFP4 量化 KV 把每元素字节数从 FP8 的 1 字节压到约 0.5 字节，KV 容量翻倍，直接转化为可并发序列数翻倍或上下文长度翻倍。但 KV 的块内动态范围通常比权重更宽——不同 token 的 key 幅值差异大，range/rms 比值高，误差界更易被突破。工程折中是：对 key 采用 per-channel 缩放以吸收通道间幅值差异，对 value 采用 per-token 或分块缩放；当某层的 KV range/rms 超阈值时，该层 KV 保留 FP8，其余层 NVFP4。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{bytes}}=2\\cdot n_{\\text{layer}}\\cdot n_{\\text{head}}\\cdot d_{\\text{head}}\\cdot L\\cdot B\\cdot c_{\\text{byte}},\\qquad c_{\\text{byte}}\\in\\{1,\\,0.5\\}$$</div>\n<p>举例：一个长上下文服务，KV 从 FP8 降到 NVFP4 使单卡可容纳序列数翻倍，但若部分层 KV 回退 FP8，实际增益按回退层比例打折。代价是 KV 量化引入的 softmax logits 扰动，需在回归集上测困惑度与长文检索准确率；收益是并发数或上下文长度的直接扩容。工程判断：KV 量化收益最大的是长上下文、高并发场景，短上下文场景下 KV 占比低，量化收益不足以抵消精度风险，应优先保 FP8。</p>\n\n<h3 id=\"th-quant-error-bound-sec-22\">二十二 · 用误差界定 SLO：延迟预算下的精度-吞吐前沿</h3>\n<p>SLO 决策把误差界与延迟预算绑在一起。推理服务的 SLO 通常由首 token 延迟与每 token 延迟（TPOT）刻画，而 NVFP4 的收益在于 GEMM 吞吐提升与权重带宽下降——权重从 FP8 降到 NVFP4，每 token 解码需读取的权重字节减半，解码阶段是带宽受限的，因此 TPOT 随权重位宽下降而改善。误差界在此的角色是：它决定了为达到该 TPOT 所需的量化激进程度是否越过精度红线。</p>\n<p>具体做法是把 SLO 反解为\"允许的最大量化激进度\"：给定 TPOT 目标，权重位宽越低越容易达标；但位宽越低，range/rms 阈值越紧，回退比例越高，实际有效位宽回升，TPOT 改善被侵蚀。这是一个自洽方程：位宽选择影响回退比例，回退比例影响有效位宽，有效位宽影响 TPOT。求解时以误差界为约束、以 TPOT 为目标，找到满足 SLO 的最小激进位宽配置。</p>\n<div class=\"formula\">$$\\text{TPOT}\\approx\\frac{\\text{bytes}_{\\text{weight}}^{\\text{eff}}+\\text{bytes}_{\\text{KV}}}{BW_{\\text{HBM}}},\\qquad \\text{bytes}_{\\text{weight}}^{\\text{eff}}=c_{\\text{byte}}\\cdot(1-r_{\\text{fallback}})+1\\cdot r_{\\text{fallback}}$$</div>\n<p>举例：某服务 TPOT 目标要求权重带宽占用减半，理想 NVFP4 可满足；但若回退比例使有效字节数只降到 0.7 倍，则 TPOT 目标落空，此时应回头放宽误差预算（接受略高的困惑度）或改进通道均衡以降低回退比例，而不是盲目加大并行度。代价是精度预算与延迟预算的联合调参成本；收益是 SLO 可达且不牺牲精度底线。工程判断：SLO 紧张时优先降 KV 位宽与权重位宽，但每次位宽下调都必须重跑 range/rms 标定与端到端回归，因为误差界的失效条件随位宽收紧而更容易触发。</p>\n\n<h3 id=\"th-quant-error-bound-sec-23\">二十三 · 算例：一个解码层的批大小、并行度与 KV 预算联立</h3>\n<p>设一个解码层，权重矩阵 N×K，块大小取 32，NVFP4 等效 b≈3。标定得到该层块内 range/rms 的中位数为 4，少数块达 40。按第一节判据，阈值约为$$2^{3}\\times\\varepsilon_{\\text{budget}}$$；若误差预算取百分之几量级对应的比值上限为数十，则中位块安全、尖峰块需回退。设尖峰块占比 5%，则该层有效权重字节数为$$0.95\\times0.5+0.05\\times1=0.525$$字节/元素，相对 FP8 的压缩比约 1.9 倍而非理想 2 倍——容量规划按 1.9 倍算。</p>\n<p>批大小侧：权重显存按有效密度算定，KV 按 FP8 与 NVFP4 两套预算分别算，激活缓冲随批线性增长。若激活离群在批超过某值时触发失效，则批大小停在精度拐点，剩余吞吐靠数据并行副本补。并行度侧：N 维按 8 卡切分需保证每卡维度是 32 的整数倍，块对齐后各卡误差界独立成立，all-reduce 后方差叠加但相对误差持平。KV 预算侧：该层 KV 的 range/rms 若超阈值则保留 FP8，否则 NVFP4，按回退层比例折算总 KV 容量。</p>\n<div class=\"formula\">$$\\text{有效压缩比}=\\frac{1}{c_{\\text{byte}}(1-r_{\\text{fallback}})+r_{\\text{fallback}}},\\qquad \\text{批上限}=\\min\\{B_{\\text{mem}},\\,B_{\\text{precision}}\\}$$</div>\n<p>联立结论：该层的容量收益由回退比例决定，批大小由精度拐点与显存上限的较小者决定，并行度由块对齐约束决定，KV 预算由逐层回退比例折算。四者不是独立旋钮，而是被同一个 range/rms 统计量串起来的联合决策。工程上应把 range/rms 标定作为容量规划的前置步骤，把回退比例作为显存、批、并行、KV 四类预算的共同输入，而不是先定批再补精度测试。最后落在具体机制上：每当块大小从 32 改到 16，缩放开销翻倍但尖峰隔离变好，回退比例下降，有效压缩比上升——这个权衡必须用标定数据算，不能凭经验拍。</p>\n\n<h3 id=\"th-quant-error-bound-sec-24\">二十四 · 误差界进容量模型：批大小、并行度与 KV 预算的联动</h3>\n<p>把误差界当容量约束用，关键是把 $$\\varepsilon_{\\text{rel}}$$ 折算成“每层可容忍的额外误差预算”，再反推批大小。做法是：对每层采样块内 range/rms 比，若某层该比值超过阈值（例如 8），则该层不进 NVFP4，保留 FP8，并在容量表里给它记一份额外权重带宽。批大小 B 的可行域由显存约束给出：$$B\\le\\frac{M_{\\text{free}}-W_{\\text{fp8}}\\cdot s_{\\text{fp8}}-W_{\\text{nvfp4}}\\cdot s_{\\text{nvfp4}}}{L\\cdot H\\cdot 2\\cdot d_{\\text{kv}}}$$，其中分子是扣掉混合精度权重后的剩余显存，分母是每 token 每层的 KV 字节数。range/rms 大的层越多，$$W_{\\text{fp8}}$$ 越大，B 上限越低——这就是误差界对批大小的直接传导路径。</p>\n<p>并行度决策同理：TP 度越大，每卡分到的权重块越小，块内 range/rms 比反而更容易被少数大权重拉高，$$\\varepsilon_{\\text{rel}}$$ 随 TP 上升而恶化。工程判断是：先按单卡测出的 range/rms 分布定 TP，再定是否对离群通道做通道均衡；若不做均衡而强行 per-tensor 缩放，>6σ 激活会把 per-tensor 缩放因子拉大，块内有效位宽骤降，此时误差界不再成立，只能回退 MXFP8。KV 预算则与误差界解耦但共享显存池：NVFP4 权重省下的字节应优先换成 KV 容量而非更大批，因为批增大带来的收益会被多层累积误差抵消。</p>\n<p>算例：某 70B 级模型单层权重 1.2 GB（FP8），KV 每 token 每层 2 KB，共 80 层。若 30% 的层因 range/rms 超阈值保留 FP8，其余走 NVFP4（约省一半字节），则权重总占用从 96 GB 降到约 82 GB，省出的 14 GB 可多容纳约 14 GB/(80×2 KB)≈9 万 token 的 KV——这比把批从 32 提到 48 更稳，因为后者会让 softmax 路由层的误差放大。表格化记录每层 range/rms、所选精度、折算字节，是量化回归测试的触发阈值依据。</p>\n<table class=\"mini\"><thead><tr><th>层类型</th><th>range/rms</th><th>精度选择</th><th>容量影响</th></tr></thead><tbody><tr><td>注意力投影</td><td>低</td><td>NVFP4</td><td>权重减半</td></tr><tr><td>FFN 首层</td><td>中</td><td>NVFP4（块 32）</td><td>缩放开销可控</td></tr><tr><td>含 >6σ 通道层</td><td>高</td><td>FP8 或 MXFP8</td><td>占满预算</td></tr></tbody></table>\n<h3 id=\"th-quant-error-bound-sec-25\">二十五 · 把单次 GEMM 的界当成端到端承诺</h3>\n<p>最常见的误用，是把 <span class=\"mono\">ε_rel ≤ (1/2^b)(range/rms)</span> 这条单次 GEMM 输出误差界，直接当成整网精度保证来签字。这条界的推导前提是“一层、一次矩阵乘、输入固定”，它约束的是 <span class=\"mono\">ŷ = Ŵx</span> 与 <span class=\"mono\">y = Wx</span> 的单步偏差；而推理链路是几十层串联，每层输出既是下一层的输入，又经过 LayerNorm、残差、激活函数与注意力 softmax 的非线性整形。误差不会线性相加，而是被逐层重新标定：LayerNorm 会把绝对误差按当前激活的 rms 归一化，残差把量化噪声与信号直接叠加，softmax 则把 logits 上的小幅扰动指数放大成概率分布上的大幅偏移。</p>\n<p>识别这类误用的方法很直接：看精度回归报告里有没有“逐层单 GEMM 余弦相似度”与“端到端困惑度/任务指标”两套数。只有前者、没有后者，就是把界当承诺。工程上应把该界定位为<strong>准入筛选器</strong>而非<strong>验收标准</strong>——它回答“这一层权重能不能安全降到 NVFP4”，不回答“这个模型上线后掉几个点”。真正的验收必须跑长序列、跑分布外样本、跑路由分支被激活的稀疏路径，因为 softmax 与 MoE 路由的放大效应只在真实数据分布上才显形。</p>\n<p>代价体现在验证预算上：单 GEMM 误差界可以在离线用合成权重几秒算完，端到端退化测试却要占用真实 GPU 跑完整推理栈，通常是小时级、多卡级的开销。跳过它的后果不是“精度略降”，而是上线后困惑度明显退化、长尾任务崩坏，且因为缺少逐层埋点而无法定位是哪一层越界。</p>\n\n<h3 id=\"th-quant-error-bound-sec-26\">二十六 · 对含离群激活的层强行 per-tensor 缩放</h3>\n<p>第二种误用更隐蔽：权重侧的分块微缩放做得规规矩矩，却在激活侧沿用 per-tensor 的 FP32 缩放，且该层存在 >6σ 的离群通道。机制上，per-tensor 缩放因子由整个张量的最大绝对值决定，一个 6σ 以上的离群通道会把缩放因子拉大到远超主体分布的量级，于是主体通道在 FP4 的 E2M1 网格上被压进极少数码点，块内有效位宽骤降——名义上仍是 2 位尾数（等效 b≈3），实际可用分辨率远低于此，误差界中的 range/rms 放大因子被离群值单方面抬高，界本身不再成立。</p>\n<p>识别信号有三条：其一，逐通道统计激活的最大绝对值与 rms 之比，若某几个通道的比值显著高于其余通道，即为离群通道；其二，量化前后该层输出的逐通道相对误差分布出现“少数通道爆炸、多数通道正常”的双峰；其三，端到端指标在特定输入类型上崩坏而在平均集上尚可，这正是离群通道被特定 token 触发的特征。</p>\n<p>处置路径是通道均衡或回退：SmoothQuant 式做法把激活的离群幅度按通道迁移一部分到权重上，使两侧动态范围都收敛；或者对该层直接回退 MXFP8，用更高的尾数位宽吸收离群。代价是明确的——通道均衡需要在推理前做一次校准统计并固化缩放向量，增加一次离线开销和一份 per-channel 元数据；MXFP8 回退则让该层的权重带宽翻倍，在解码阶段直接抬高每 token 的显存读取量，是吞吐与精度的硬交换。</p>\n\n<h3 id=\"th-quant-error-bound-sec-27\">二十七 · 忽略 range/rms 而把块选小</h3>\n<p>块大小 16 还是 32 的选择，常被误当成“越小越精确”的单调关系。看界就知道不是：<span class=\"mono\">ε_rel ≤ (1/2^b)(range/rms)</span> 里，块越小，块内 max|w| 越可能由单个大权重主导，range/rms 之比反而上升；同时每块要带一个 FP8 缩放因子，块数翻倍意味着缩放元数据的存储与读取翻倍。也就是说，块缩小带来的是“界内放大因子变大 + 缩放开销变大”的双重代价，只有在权重分布本身高度局部平稳时，缩小块才真正降低误差。</p>\n<p>正确做法是先按块内动态范围与 rms 之比做分层评估：对 range/rms 接近 1 的平稳层，块 32 足够且缩放开销低；对 range/rms 明显偏高的层，缩块未必救得回来，更该考虑的是通道级处理或提高位宽。识别误用的办法是在量化配置里同时记录块大小与逐块 range/rms 分布，若发现大量块的比值超过阈值却仍强行用小块，就是在用缩放开销换一个并未改善的界。</p>\n<p>系统代价落在解码带宽上：NVFP4 的权重读取本就以块为单位，缩放因子与数据打包在同一缓存行里，块从 32 降到 16 会让单位权重的元数据占比上升，等效于每 token 需要搬运更多字节，直接压低解码吞吐。这类损失在预填阶段不明显，在低并发解码时才暴露，因此必须用解码态的实测带宽而非预填态的算力指标来判断。</p>\n\n<h3 id=\"th-quant-error-bound-sec-28\">二十八 · 一个反例：路由 softmax 放大单 GEMM 的“合格”误差</h3>\n<p>设某 MoE 层，专家权重量化后逐块 range/rms 均在正常范围，单 GEMM 的相对误差落在界内，逐层余弦相似度看起来合格。但该层的路由打分经过 softmax 后，top-k 专家之间的分数差很小，logits 上的微小扰动足以改变 top-k 的选择——被选中的专家集合发生切换，输出不再是“同一组专家的略微偏差”，而是“不同专家输出的拼接”。此时单 GEMM 误差界完全无法描述端到端偏差：界约束的是固定权重下的乘法结果，而路由切换改变了参与计算的权重子集。</p>\n<p>这个反例的工程含义是：对 MoE 层，量化误差评估必须在<strong>路由决策稳定性</strong>这一层做，而不是在 GEMM 输出上做。可操作的伪代码思路是，对校准集逐 token 记录量化前后的 top-k 专家索引，统计索引翻转率；翻转率超过阈值即判定该层不能仅凭单 GEMM 界放行，需对路由打分保留更高精度（如路由器权重留 FP8 甚至 BF16），或对专家权重回退。代价是路由部分的精度保留会增加一小块常驻显存与一次额外的矩阵乘，但相比专家权重整体回退，这是更便宜的保险。</p>\n<p>同一反例也解释了为什么“逐层余弦相似度合格”会骗人：余弦相似度对输出向量的整体方向敏感，却对“换了哪个专家”这种离散切换不敏感，尤其在专家输出彼此接近时。识别这类问题的唯一可靠手段是任务级指标加路由翻转率联合观测，二者缺一不可。</p>\n\n<h3 id=\"th-quant-error-bound-sec-29\">二十九 · 误用的共同结构：把界的定义域当成结论域</h3>\n<p>上述三种误用共享一个结构：误差界的定义域是“单次 GEMM、固定权重、给定输入分布”，而工程结论的定义域是“整网、动态路由、真实流量”。跨定义域引用，就是把条件结论当无条件结论。判断一份量化方案是否踩坑，只需问三个问题：界的放大因子 range/rms 是否在目标层被逐块核过；激活侧是否存在被 per-tensor 缩放掩盖的离群通道；端到端退化是否在真实分布上实测过而非由界推出。三问有一问答不上，该方案就还停留在“界内合格、界外未知”的状态。</p>\n<p>把这三问固化成上线前的门禁，比事后调参便宜得多：逐块 range/rms 统计与离群通道扫描是离线一次性的，路由翻转率与端到端指标是每次模型变更必跑的回归项。NVFP4 的两级缩放（FP8 per-block、FP32 per-tensor）给了权重侧足够的表达力，但激活侧的离群与路由的离散性不在它的保护范围内——这正是误差界必须被当作筛选器、而验收必须落在实测上的根本原因。</p>\n\n<h3 id=\"th-quant-error-bound-sec-30\">三十 · 误用与反例：把误差界当成上线许可证</h3>\n<p>最常见的误用不是算错公式，而是把 <span class=\"inline-math\">$\\varepsilon_{\\text{rel}}\\le(1/2^b)(\\mathrm{range}/\\mathrm{rms})$</span> 这个<strong>单次 GEMM 输出</strong>的界，直接当成端到端精度保证。这个界只约束一次矩阵乘的舍入偏差，它不穿过残差流、不穿过 LayerNorm、更不穿过路由 softmax。多层累积会把每层的相对误差按权重敏感度加权叠加，而 MoE 路由里 softmax 对 logit 差异的指数放大，会让某个专家被错误选中——一次错误路由就把整条 token 的计算路径换掉，误差不再是“几个百分点”而是分布级别的偏移。工程后果是：离线单层 cosine 相似度看着漂亮，上线后困惑度退化明显，长上下文尤其严重，因为累积层数与注意力稀释同时起作用。识别方法很直接：量化回归测试必须跑<strong>端到端</strong>困惑度与任务指标，而不是只跑逐层 GEMM 误差；把单层界当作触发阈值的唯一依据，等于用局部线性近似去担保一个非线性系统的输出。</p>\n<p>第二类误用是对含离群激活的层强行套 per-tensor 缩放。NVFP4 的两级缩放里，FP32 per-tensor 因子由全局最大幅值定标，一旦某条通道出现 &gt;6σ 的激活离群值，这个因子被拉大，per-block 的 FP8 缩放能表达的相对动态范围随之被压缩，块内有效位宽骤降——形式上仍满足 <span class=\"inline-math\">$\\Delta_{\\text{blk}}=\\max_{i\\in\\text{blk}}|w_i|/2^{b-1}$</span>，但此时 <span class=\"inline-math\">$\\mathrm{range}/\\mathrm{rms}$</span> 被离群通道主导，界本身已经失去约束力。反例：某 Transformer 的 down_proj 层权重分布良好，单层量化误差在百分之几量级，但同一层的输入激活存在少数幅值远超 6σ 的通道；直接 per-tensor 定标后，这些通道所在的块等效位宽掉到接近 1 位尾数的表达能力，输出出现成片饱和与符号翻转，注意力输出崩坏。正确做法是 SmoothQuant 式通道均衡把激活难度迁移到权重侧，或对该层回退 MXFP8；判断依据是逐通道的幅值分布，而不是全局一个 max。</p>\n<p>第三类误用是块大小选择脱离 <span class=\"inline-math\">$\\mathrm{range}/\\mathrm{rms}$</span> 的实际分布。块越小，块内动态范围越窄、界越紧，但缩放因子的元数据开销与反量化指令随之上升；块越大，元数据摊薄，可块内一旦混入离群元素，整块的步长被抬高，其余元素的有效位宽被牺牲。块大小 16 与 32 的选择应由逐块的 range/rms 直方图决定：若分布长尾明显，缩小块反而放大误差与缩放开销的双重代价。系统代价上，这直接体现为 TMEM 中缩放因子的搬运带宽与 tcgen05 MMA 前的反量化流水占用，块元数据越密，每拍有效 MMA 占比越低。识别信号是：量化后逐块误差的方差随块大小单调恶化，说明块内动态范围失配，此时应改块尺寸或对高 range/rms 块保留 FP8，而不是继续压位宽。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>单层界当端到端保证</td><td>多层累积 + 路由 softmax 放大</td><td>上线困惑度退化，长上下文更重</td><td>逐层 cosine 好、端到端指标差</td></tr><tr><td>离群层强行 per-tensor</td><td>&gt;6σ 通道拉大因子，块内有效位宽骤降</td><td>输出饱和/崩坏，需回退重算</td><td>逐通道幅值长尾、块误差方差突增</td></tr><tr><td>块大小脱离 range/rms</td><td>大块混入离群元素抬高步长</td><td>缩放元数据带宽与反量化流水占用上升</td><td>块误差随块尺寸单调恶化</td></tr></tbody></table>\n<p>把这三类误用收束成一条工程判断：误差界是<strong>准入筛选器</strong>，不是<strong>放行许可证</strong>。它的正确用法是判断某层权重能否安全降到 NVFP4、块大小取 16 还是 32、以及哪些通道需要保留 FP8——也就是把它当作量化后精度回归测试的触发阈值，而不是替代回归测试。真正的放行条件必须包含端到端实测：困惑度、路由命中分布、长上下文退化斜率，以及回退路径（MXFP8 或通道均衡）的切换成本。当某层的逐块 range/rms 直方图出现长尾、且该层位于残差累加的关键路径上时，即便单次 GEMM 的界仍然成立，也应默认保留更高精度——因为界约束的是算术，而系统失效发生在算术之外。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\Delta_{\\text{blk}}</td><td>量化块（如16或32元素）内的量化步长</td></tr><tr><td>b</td><td>尾数有效位宽（NVFP4的E2M1为2位尾数，等效b≈3）</td></tr><tr><td>\\mathrm{range}</td><td>块内动态范围max|w|</td></tr><tr><td>\\mathrm{rms}</td><td>块内权重均方根</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-quant-error-bound · 共 5 个片段</p>\n"},{"id":"th-alltoall-lower-bound","title":"专家并行通信下界","direction":"dir-kv-cache-compression","prereq":[],"plain":"每个token要被送往k个专家所在设备，All-to-All的通信量下界是token数×隐藏维×字节数×路由扇出，跨节点时被链路带宽与NVLink域边界切成两段，通信时间不可能低于该字节数除以最慢链路带宽。","definition":"每个token要被送往k个专家所在设备，All-to-All的通信量下界是token数×隐藏维×字节数×路由扇出，跨节点时被链路带宽与NVLink域边界切成两段，通信时间不可能低于该字节数除以最慢链路带宽。","formula":"$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}],\\qquad T_{\\text{comm}}\\ge\\frac{V_{\\text{a2a}}}{\\mathrm{BW}_{\\text{link}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$","variables":[{"sym":"T","meaning":"批内token总数"},{"sym":"d","meaning":"隐藏维（dispatch与combine各一次故乘2）"},{"sym":"b_{a}","meaning":"激活字节数（FP8为1，NVFP4为0.5）"},{"sym":"\\bar{k}","meaning":"平均每token跨设备专家数"},{"sym":"\\mathrm{BW}_{\\text{link}}","meaning":"最慢链路有效带宽（跨节点IB/RoCE）"},{"sym":"\\eta_{\\text{hop}}","meaning":"每跳固定时延"}],"derivation":"推导的关键一步是先算全部激活字节 2·T_act·d·b_act，再乘以非本地专家的比例 (1-1/E) 得到跨设备通信量下界，随后除以 B_NVLink·E 得到时延下界；E 同时出现在分子比例与分母带宽中。","example":"在部署容量决策中，该式用于判断 EP 度增大能否摊薄通信、估算每层 All-to-All 时延是否成为解码瓶颈，并指导 EP 拓扑选择（NVLink 域内 vs 跨节点 IB）。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["单节点内NVLink全互联时扇出不增加跨链路字节，公式中cross-node指示项为0，下界退化为零","专家放置均衡且token路由局部性好时，实际通信可被融合dispatch与计算重叠掩盖，下界不再是端到端瓶颈"],"system_note":"常见误用是直接用均匀路由下界做容量规划而忽略专家倾斜，实际最慢链路时延远超估计；另一误用是跨节点 EP 仍沿用 NVLink 带宽，低估通信时延与拓扑跳数代价。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉上，MoE 每层需把 token 按路由发往各专家所在设备，All-to-All 通信量下界由激活 token 数与隐藏维度决定，与专家数无关但随 EP 度线性分摊。","公式中 T_act 为每层激活 token 数（batch×seq），d 为隐藏维度，b_act 为激活字节数（FP8=1），E 为专家并行度；系数 2 对应发送与接收，因子 (1-1/E) 表示发往本设备的份额被扣除。","推导的关键一步是先算全部激活字节 2·T_act·d·b_act，再乘以非本地专家的比例 (1-1/E) 得到跨设备通信量下界，随后除以 B_NVLink·E 得到时延下界；E 同时出现在分子比例与分母带宽中。","适用边界是路由均匀、拓扑为单层 NVLink；失效条件为路由高度倾斜时实际通信量低于上界但最慢链路成为瓶颈，下界不再代表实际时延；跨节点 EP 走 InfiniBand 时带宽远低于 NVLink，需替换 B_NVLink 并计入拓扑跳数。","在部署容量决策中，该式用于判断 EP 度增大能否摊薄通信、估算每层 All-to-All 时延是否成为解码瓶颈，并指导 EP 拓扑选择（NVLink 域内 vs 跨节点 IB）。","常见误用是直接用均匀路由下界做容量规划而忽略专家倾斜，实际最慢链路时延远超估计；另一误用是跨节点 EP 仍沿用 NVLink 带宽，低估通信时延与拓扑跳数代价。"],"anchors":["FP8=1","2"],"pitfalls":["按均匀路由下界规划容量，忽略专家倾斜使最慢链路成为瓶颈，实际 All-to-All 时延远超估计。","跨节点 EP 仍用 NVLink 带宽代入公式，未替换为 InfiniBand 带宽并计入拓扑跳数，通信时延被严重低估。","误以为增大 E 总能摊薄通信，忽略 (1-1/E) 比例与分母带宽的耦合及跨节点拓扑代价。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-1\">一 · 一句话直觉与它的物理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-2\">二 · 严格定义：下界到底界定的是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-3\">三 · 为什么需要这个下界：三个工程决策场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-4\">四 · 常见误解之一：把均匀路由下界当成容量规划依据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-5\">五 · 常见误解之二：跨节点仍沿用 NVLink 带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-6\">六 · 常见误解之三：以为增大 E 总能摊薄通信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-7\">七 · 下界成立的那块窄地：单层 NVLink、均匀路由与可重叠窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-8\">八 · 逐项拆解：为什么是 2·T·d·b·k̄ 而不是别的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-9\">九 · 推导关键步：先算全量字节，再乘非本地比例，最后除带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-10\">十 · 离散化与近似发生在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-11\">十一 · 代入数字：FP8 与 NVFP4 的字节账，以及 E 的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-12\">十二 · 失效条件的公式读法：指示项归零与重叠掩盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-13\">十三 · 下界公式的适用边界：从单层 NVLink 到跨节点 IB 的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-14\">十四 · 均匀路由假设：从“平均份额”到“最慢链路”的断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-15\">十五 · 单层 NVLink 拓扑：指示项归零与“下界消失”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-16\">十六 · 规模上限：E 增大时分子与分母的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-17\">十七 · 失效条件清单：什么时候公式不再成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-18\">十八 · 边界内的正确用法：从下界到决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-19\">十九 · 边界在哪里：均匀路由、单层 NVLink 与 (1−1/E) 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-20\">二十 · 下界公式的三处“地基”与它们各自的塌陷方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-21\">二十一 · 把下界写成可求解的容量方程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-22\">二十二 · 定 KV 预算：通信批与显存批的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-23\">二十三 · 定 SLO：把下界翻译成尾时延约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-24\">二十四 · 定并行度：EP 与 TP 的联合取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-25\">二十五 · 误用清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-26\">二十六 · 把下界嵌进容量决策：四个可调旋钮与两处塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-27\">二十七 · 把下界嵌进容量决策：批大小、EP 度与 KV 预算的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-28\">二十八 · 误用一：把均匀路由下界当容量规划的真值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-29\">二十九 · 误用二：跨节点 EP 仍代入 NVLink 带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-30\">三十 · 误用三：以为增大 E 总能摊薄通信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-31\">三十一 · 反例：一个被下界误导的部署决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-32\">三十二 · 识别清单与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-alltoall-lower-bound-sec-33\">三十三 · 当“下界”被当成“预算”：三类误用与一个反例</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:533px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 532.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：每个token要被送往k个专家所在设备，All-to-All的通信…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：单节点内NVLink全互联时扇出不增加跨链路字节，公式中cross…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-alltoall-lower-bound-sec-1\">一 · 一句话直觉与它的物理含义</h3>\n<p>把 MoE 的一层想象成一次“按目的地分拣的快递”：每个 token 在门控网络里被指派给 k 个专家，而专家分散在 EP 组的不同设备上，于是这一层的输入必须先离开本卡、穿过链路、落到目标卡，算完再回来。All-to-All 通信下界说的就是这件事的物理下限——<strong>你必须搬运的字节数，除以你能用的最慢那条链路的带宽</strong>，再叠加每一跳的固定开销。它不关心你用哪套集合通信库、开了几个 SM、用了多深的流水，只要字节数和链路带宽定了，时间就不可能更低。一句话：<span class=\"formula\">$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}],\\qquad T_{\\text{comm}}\\ge\\frac{V_{\\text{a2a}}}{\\mathrm{BW}_{\\text{link}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span>其中系数 2 是 dispatch 与 combine 各一次，<em>T</em> 是批内 token 总数，<em>d</em> 是隐藏维，<em>b<sub>a</sub></em> 是激活字节数（FP8 记 1，NVFP4 记 0.5），<em>k̄</em> 是平均每 token 跨设备的专家数。这个式子的“直觉价值”在于它把通信成本从“感觉上很贵”变成了“可以拿笔算的量”：<em>T</em>·<em>d</em>·<em>b<sub>a</sub></em> 是这一层激活张量的总字节，乘以扇出 <em>k̄</em> 就是需要过链路的字节总量。</p>\n<p>注意这个直觉里藏着一个反常识的结论：<strong>下界与专家总数无关，只与扇出和链路有关</strong>。把 EP 从 8 扩到 64，单卡要发的 token 数按 1/E 摊薄，但每 token 的扇出 <em>k̄</em> 不变，于是总字节量不变、单卡字节量下降——这正是“EP 度线性分摊”的来源，也是后面几部分要拆开算的耦合点。工程上这意味着：扩容 EP 买到的是“每卡少发一点”，而不是“总量变少”。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-2\">二 · 严格定义：下界到底界定的是什么</h3>\n<p>严格地说，这个下界界定的是<strong>单层 All-to-All 阶段在给定拓扑与路由下的最小传输时间</strong>，而不是端到端解码时延。定义需要三个前提写清楚：其一，路由已定（门控输出已知），因此字节数是确定量而非随机量；其二，拓扑已知，最慢链路带宽 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 取该拓扑下参与本次 All-to-All 的所有链路中的最小值——跨节点时它是 IB/RoCE 的有效带宽，域内时是 NVLink 5 的单向有效带宽；其三，跳数 <em>#hops</em> 与每跳固定时延 <em>η<sub>hop</sub></em> 计入，因为跨节点流量在 fabric 上要过交换机，这部分不随字节数缩放。</p>\n<p>用伪代码表述这个下界的计算过程，比公式更能暴露工程细节：</p>\n<ul>\n<li>输入：本层 token 集合 <em>T</em>、隐藏维 <em>d</em>、激活字节 <em>b<sub>a</sub></em>、EP 度 <em>E</em>、每 token 目标专家集合；</li>\n<li>第一步：算全部激活字节 <em>B</em> = 2·<em>T</em>·<em>d</em>·<em>b<sub>a</sub></em>（收发各一份）；</li>\n<li>第二步：乘以非本地份额 (1−1/<em>E</em>) 得跨设备字节 <em>V</em>；</li>\n<li>第三步：若跨节点，<em>V</em> 除以 <span class=\"formula\">$$\\mathrm{BW}_{\\text{IB}}$$</span>，否则除以 <span class=\"formula\">$$\\mathrm{BW}_{\\text{NVLink}}$$</span>，再加 <em>η<sub>hop</sub></em>·<em>#hops</em>；</li>\n<li>输出：<em>T<sub>comm</sub></em> 的下界，作为该层通信预算的硬底。</li>\n</ul>\n<p>这里 (1−1/<em>E</em>) 是“发往本设备的份额被扣除”的严格表达：均匀路由下，1/<em>E</em> 的 token 留在本地，不产生链路字节。这个因子与分母里的带宽分摊 <em>B<sub>NVLink</sub></em>·<em>E</em> 是耦合的——<em>E</em> 同时出现在分子比例与分母带宽中，所以“增大 E 摊薄通信”不是单调结论，这一点是本卷后续部分的核心争议点，此处只标记不展开。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-3\">三 · 为什么需要这个下界：三个工程决策场景</h3>\n<p><strong>场景一：容量规划。</strong>部署容量决策中，这个式子用来判断 EP 度增大能否摊薄通信。给定一个目标 SLO（比如解码每 token 时延上限），你可以反推：在 <em>T</em>（批内 token 数）、<em>d</em>、<em>b<sub>a</sub></em> 固定时，<em>T<sub>comm</sub></em> 的下界是否已经吃掉预算的大头。如果下界本身就接近 SLO 上限，那么无论怎么优化 kernel 都救不回来，必须改拓扑或改并行策略。这是“先算下界再调优”的典型用法——下界告诉你优化空间的天花板在哪。</p>\n<p><strong>场景二：判断解码瓶颈。</strong>解码阶段每层都要做一次 All-to-All，batch 小、<em>T</em> 小，但层数多，于是通信时延按层累加。用下界估算每层 All-to-All 时延是否成为解码瓶颈：若单层下界乘以层数已超过目标 TPOT 的可接受份额，说明 EP 拓扑选错了，需要把专家收进 NVLink 域内。这里的代价指标是<strong>时延</strong>，不是吞吐——解码是时延敏感型负载，下界给的是“最快能多快”。</p>\n<p><strong>场景三：EP 拓扑选择（NVLink 域内 vs 跨节点 IB）。</strong>这是最直接的用法：同一 <em>V</em> 分别除以 NVLink 带宽与 IB 带宽，得到两个数量级不同的下界，差值就是跨节点部署的“拓扑税”。工程判断很干脆——若跨节点下界已经超过层计算时间，就不该把专家撒到节点外；若跨节点下界仍可被计算重叠掩盖，则跨节点扩容是划算的。注意这里的代价指标是<strong>带宽</strong>与<strong>跳数</strong>，两者在跨节点时同时恶化。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-4\">四 · 常见误解之一：把均匀路由下界当成容量规划依据</h3>\n<p>最普遍也最贵的误用，是直接用均匀路由下界做容量规划而忽略专家倾斜。均匀路由假设每个专家收到的 token 数相等，于是 (1−1/<em>E</em>) 这个比例是精确的；但真实门控输出是倾斜的——少数热门专家吃掉大量 token，冷门专家几乎闲置。倾斜的后果不是“总量变少”，而是<strong>最慢链路成为瓶颈</strong>：热门专家所在设备的入向链路被打满，而其他链路空闲，此时实际 All-to-All 时延由那条最慢链路决定，远超按平均字节数算出的估计。</p>\n<p>用公式语言说，均匀下界给的是 <em>V</em>/<span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 的<strong>平均值</strong>，而实际时延是 <span class=\"formula\">$$\\max_{i} V_{i}/\\mathrm{BW}_{i}$$</span> 的<strong>最大值</strong>——当 <em>V<sub>i</sub></em> 的分布有重尾时，最大值可以远高于均值。这就是为什么按均匀下界规划容量会在生产环境里“翻车”：估算说通信只占 20% 预算，实测却占了 60%。正确做法是把下界当作<strong>乐观底</strong>而非<strong>规划值</strong>，并在倾斜场景下引入最慢链路的修正项。注意此处的失效条件写得很明确：路由高度倾斜时实际通信量低于上界但最慢链路成为瓶颈，下界不再代表实际时延。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-5\">五 · 常见误解之二：跨节点仍沿用 NVLink 带宽</h3>\n<p>第二个高频错误是把 NVLink 带宽代入跨节点场景。NVLink 5 只在单节点域内全互联，一旦 EP 度超过单节点 GPU 数，流量必须出域走 InfiniBand 或 RoCE，带宽远低于 NVLink，且要计入拓扑跳数。此时公式里的 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 必须替换为 IB 有效带宽，<em>η<sub>hop</sub></em>·<em>#hops</em> 项从可忽略变成主导项之一。用 NVLink 带宽代入跨节点场景，会把通信时延低估一个量级，进而让容量规划得出“跨节点扩容很便宜”的错误结论。</p>\n<p>这个误解的根源是把“链路”当成抽象常量，而忽略了拓扑的层级性。严格定义要求 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 取<strong>参与本次 All-to-All 的所有链路中的最小值</strong>——跨节点时最小值就是 IB 带宽，不是 NVLink。同理，<em>#hops</em> 不是 1，而是 fabric 上的实际跳数。工程判断：只要 EP 组跨越节点边界，就必须在公式里同时替换带宽与增加跳数项，两者缺一都会系统性低估。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-6\">六 · 常见误解之三：以为增大 E 总能摊薄通信</h3>\n<p>第三个误解是线性外推“EP 度翻倍，通信减半”。这个直觉只在单层 NVLink 全互联、路由均匀时近似成立，因为此时 <em>E</em> 只出现在分母带宽分摊里。但一旦跨节点，<em>E</em> 的增大同时带来两件事：分子里的 (1−1/<em>E</em>) 趋近于 1（本地份额变小，几乎全部要走链路），分母里的带宽从 NVLink 换成 IB（带宽骤降），并且跳数项随 fabric 规模上升。三者叠加，<em>E</em> 增大到某个点后通信下界反而<strong>上升</strong>。这就是“E 同时出现在分子比例与分母带宽中”的耦合含义。</p>\n<p>还有一个边界条件必须记住：单节点内 NVLink 全互联时，扇出不增加跨链路字节，公式中 cross-node 指示项为 0，下界退化为零。这不是说通信真的为零，而是说在单节点全互联拓扑下，All-to-All 的字节不经过任何“慢链路”，下界不再由带宽项主导，而由 SM 内的搬运与同步开销主导——那属于另一套模型，本式不覆盖。同理，专家放置均衡且 token 路由局部性好时，实际通信可被融合 dispatch 与计算重叠掩盖，下界不再是端到端瓶颈。工程上判断“下界是否 relevant”的标准很直接：看 cross-node 指示项是否为 1，以及重叠窗口是否足以吞掉 <em>T<sub>comm</sub></em>。</p>\n<p>把这三个误解放在一起看，会发现它们共享同一个病根：把下界当成预测值。下界是<strong>乐观底</strong>，它的正确用法是排除“不可能更快”的方案，而不是承诺“一定能这么快”。在 Blackwell 上做 EP 容量规划时，真正决定成败的是那条最慢链路——它由专家倾斜与拓扑层级共同决定，而这两者都不在均匀下界的假设里。</p>\n\n\n<h3 id=\"th-alltoall-lower-bound-sec-7\">七 · 下界成立的那块窄地：单层 NVLink、均匀路由与可重叠窗口</h3>\n<p>把公式拆开看，它的每一项都在限定自己的适用域。$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]$$ 里那个指示项不是装饰：当 EP 组完全落在一个 NVLink 全互联域内，token 发往同域另一台设备与发往本机的字节都走同一条 NVLink 通路，扇出并不额外增加跨链路字节数，指示项取 0，下界退化为零——此时真正的约束是 NVLink 域内聚合带宽与 SM 侧 tcgen05 的发射节奏，而非 All-to-All 字节量。一旦 EP 度超出单机 8 卡（GB200 NVL72 内以 NVLink 5 域为界），跨域那一段被 InfiniBand/RoCE 切开，指示项取 1，公式才重新有约束力。因此这个下界的第一条边界是拓扑边界：它只对“跨节点 EP”这一半流量给出非平凡结论，对域内那一半必须换成另一套带宽口径，否则会得出“通信为零”的荒谬容量规划。</p>\n<p>第二条边界是路由分布。推导中先算全部激活字节 $2Td b_a$，再乘非本地专家比例 $(1-1/E)$，这一步隐含了均匀路由假设：每个 token 的 k 个专家在 E 台设备上均匀散开，$\\bar{k}$ 才等于期望的跨设备专家数。真实路由是倾斜的，热门专家集中时，全局字节量确实低于均匀上界，但最慢那条链路（承载最热专家所在设备）的字节量反而高于均值，端到端时延由这条链路决定，公式给出的“平均下界”不再代表实际时延。工程含义很直接：用均匀下界做容量规划会系统性低估，因为瓶颈从“总量除以带宽”变成了“最大分片除以单链路带宽”。判断倾斜程度要看路由熵与专家负载方差，而不是看平均扇出。</p>\n<p>第三条边界是重叠窗口。dispatch 与 combine 各一次，中间夹着专家 FFN 计算；当专家放置均衡、token 路由局部性好时，dispatch 的字节可以被上一层计算与 combine 的流水掩盖，此时下界不再是端到端瓶颈，解码阶段真正卡住的是每层 All-to-All 的固定跳数时延 $\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$ 而非字节项。反过来说，在小 batch 解码场景，$T$ 很小、字节项趋近于零，公式退化成纯时延项，此时增大 EP 度只会增加跳数与同步点，摊薄效应消失——这正是“增大 E 总能摊薄通信”这一误解的失效点：$E$ 同时出现在分子比例 $(1-1/E)$ 与分母带宽 $B_{\\text{NVLink}}\\cdot E$ 中，两者耦合，只有在字节项主导且拓扑单层时增大 E 才有净收益。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>公式行为</th><th>系统代价落点</th></tr></thead><tbody><tr><td>单层 NVLink 域内</td><td>指示项为 0，下界退化</td><td>域内聚合带宽、SM 发射节奏</td></tr><tr><td>跨节点 IB/RoCE</td><td>需替换 $\\mathrm{BW}_{\\text{link}}$ 并计入跳数</td><td>最慢链路带宽、每跳固定时延</td></tr><tr><td>路由高度倾斜</td><td>均值下界失效</td><td>最热专家所在单链路成为瓶颈</td></tr><tr><td>小 batch 解码</td><td>字节项趋零，时延项主导</td><td>跳数与同步点，EP 摊薄失效</td></tr></tbody></table>\n<p>把这些边界合起来看，这个下界的工程价值不在数值本身，而在它标出的三个失效开关：拓扑是否跨域、路由是否均匀、重叠窗口是否存在。任一开关翻转，公式要么退化为零、要么被最慢链路接管、要么被固定时延接管。跨节点 EP 仍沿用 NVLink 带宽代入，等于同时关掉了带宽替换与跳数计入两个开关，低估幅度随 hop 数线性放大；而按均匀下界排容量、忽略专家倾斜，则是把瓶颈从聚合带宽错配到单链路带宽。真正可用的做法是把下界当作“字节项主导区”的判据：先用 $T$ 与 $\\bar{k}$ 判断字节项是否显著大于 $\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$，再决定 EP 拓扑是压在 NVLink 域内还是放开到跨节点 IB。</p>\n<h3 id=\"th-alltoall-lower-bound-sec-8\">八 · 逐项拆解：为什么是 2·T·d·b·k̄ 而不是别的</h3>\n<p>公式 <span class=\"formula\">$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]$$</span> 的每一项都对应一个物理动作，不是拟合出来的系数。T 是批内 token 总数，注意它是<b>批内</b>而非序列内：连续批处理下不同请求的 token 被拼进同一个 dispatch 张量，T 随并发请求数增长，因此这一项是调度决策的直接函数。d 是隐藏维，dispatch 阶段要把整条激活向量发给目标专家，专家做完 FFN 再原样宽度 combine 回来，所以 d 出现两次——公式里那个 2 正是“发一次、收一次”，不是冗余的对称美化。b_a 是激活字节数，FP8 取 1、NVFP4 取 0.5，这一项把精度选择直接折算成字节预算：把 dispatch 从 BF16 降到 FP8，V 减半，这是 NVFP4/FP8 在 MoE 上最直接的通信收益来源，与量化误差界是两回事，后者管数值，这里管字节。</p>\n<p>k̄ 是平均每 token 跨设备专家数。它是唯一一个由路由分布决定的量，也是公式里最容易被误读的项：它不等于 top-k 的 k。若某 token 的 k 个专家里有若干落在他自己所在设备上，这部分根本不进链路。真正进链路的份额是 k 乘以“非本地比例”。在 EP 度为 E、专家均匀铺开的拓扑下，单个专家落在本设备的概率是 1/E，于是跨设备份额为 (1−1/E)，这就是另一版写法里 (1−1/E) 因子的来历——它和 k̄ 是同一件事的两种记账方式，不能同时乘两遍。指示项 𝟙[cross-node] 是全式最锋利的一刀：单节点内 NVLink 全互联时，扇出不增加跨链路字节，该项归零，下界退化为零，公式不再提供任何有意义的约束。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-9\">九 · 推导关键步：先算全量字节，再乘非本地比例，最后除带宽</h3>\n<p>推导顺序不能颠倒，颠倒就会把 E 放错位置。第一步算全部激活字节：每层 2·T·d·b_a，这是“假如所有专家都在本地、一次都不用发”的字节总量，它不含任何并行度信息。第二步乘非本地份额 (1−1/E)，得到真正跨设备的字节下界——这一步的物理依据是：本地专家的那份激活由片上或同卡完成，不消耗链路。第三步除以有效带宽得到时延下界。关键在于 E 同时出现在分子的比例因子和分母的带宽里：分子是 (1−1/E)，分母若写成 B_NVLink·E（把聚合带宽按 EP 度分摊到每个参与者的份额），两者耦合后 E 增大并不单调改善时延。E→∞ 时 (1−1/E)→1，分子趋于饱和，分母却继续线性增长，于是时延下界反而被带宽分摊拖住。这就是“增大 E 总能摊薄通信”这一直觉的数学死穴：摊薄只发生在分子，分母在同步放大。</p>\n<p>把 hop 项加进来才构成完整下界：<span class=\"formula\">$$T_{\\text{comm}}\\ge\\frac{V_{\\text{a2a}}}{\\mathrm{BW}_{\\text{link}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span>。前一项是字节传输时间，后一项是每跳固定时延乘以跳数。这一项在小消息、高扇出时主宰时延：当 T·d·b_a 很小而 k̄ 很大，字节项趋近于零，剩下的全是 hop 开销。跨节点 EP 走 IB/RoCE 时，BW_link 必须替换为最慢链路的有效带宽，且 #hops 不再是 1。NVLink 域边界把一次逻辑 All-to-All 切成两段：域内段用 NVLink 带宽，域间段用 IB 带宽，两段串行叠加，最慢的那段决定下界。这就是为什么“跨节点时被链路带宽与 NVLink 域边界切成两段”不是修辞，而是公式里两个独立加项的来源。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-10\">十 · 离散化与近似发生在哪三处</h3>\n<p>第一处是 k̄ 的连续化。真实路由是离散的 top-k 选择，每个 token 的跨设备专家数是一个整数随机变量，k̄ 只是它的样本均值。用均值替代分布，等于假设路由均匀，这正是公式的适用边界。一旦路由倾斜——少数专家吸走大部分 token——均值不变而最慢链路的实际字节数远超 V/E 的平均分摊，下界不再代表实际时延。这是本式最危险的近似：它给出的是<b>平均意义</b>的下界，而端到端时延由<b>最慢链路</b>决定，两者在倾斜分布下可以差出一个量级。工程上必须用分位数而非均值做容量规划。</p>\n<p>第二处是带宽的标量近似。BW_link 被当作一个常数，但 NVLink 与 IB 的有效带宽随消息大小、并发流数、拥塞状态变化；小消息打不满带宽，大消息受限于协议开销。把 BW_link 当常数意味着忽略了“带宽-消息尺寸”曲线，在小 T 的解码场景下会系统性低估时延。第三处是 hop 时延的线性化：η_hop·#hops 假设每跳固定开销可加，实际交换机的排队时延随负载非线性上升，拥塞时 hop 项会被放大而非保持常数。这三处近似共同决定了公式的定位——它是<b>容量规划与拓扑选型的下界工具</b>，不是逐层时延的精确预测器。</p>\n<p>离散化还体现在 combine 阶段：dispatch 的字节数与 combine 对称，但 combine 发生在专家计算之后，其时延可与下一层的计算重叠。公式把 2 一次性计入，等于假设 dispatch 与 combine 都不可重叠，这是保守下界；实际系统中 combine 常被流水掩盖，因此公式对 combine 的计入是“上界式的保守”，而非精确刻画。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-11\">十一 · 代入数字：FP8 与 NVFP4 的字节账，以及 E 的耦合代价</h3>\n<p>取 FP8，b_a=1。设某解码步 T=1024 个 token、d=7168、k̄=8、EP 跨节点，则 2·T·d·b_a·k̄ = 2×1024×7168×1×8 ≈ 1.17×10⁸ 字节，约 117 MB 的跨链路流量。若把 dispatch 换成 NVFP4，b_a=0.5，同一配置降到约 58 MB——精度选择在这里是纯粹的字节折扣，与数值稳定性无关。再看不含 k̄ 的 (1−1/E) 写法：E=8 时非本地份额 7/8，全量字节 2×1024×7168×1 ≈ 1.47×10⁷，乘 7/8 得约 1.28×10⁷ 字节，这是“每 token 只发一份”的口径；两种写法差在 k̄ 是否已含扇出，混用会重复计数。</p>\n<p>E 的耦合代价可以定性看清：E 从 8 增到 16，分子 (1−1/E) 从 0.875 升到 0.9375，只涨 7%；若分母带宽按 E 分摊，可用带宽减半，时延下界净增约一倍。这就是“增大 E 摊薄通信”失效的算术根源——分子趋饱和，分母线性恶化。跨节点时更糟：BW_link 从 NVLink 换成 IB，量级下降，且 #hops 从域内的近零跳到域间多跳，hop 项从可忽略变成主导。此时公式的价值不在于给出精确数字，而在于立刻暴露“跨节点 EP 的时延下界已被 IB 带宽和跳数锁死”这一结构性事实，从而把拓扑选型推向 NVLink 域内。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-12\">十二 · 失效条件的公式读法：指示项归零与重叠掩盖</h3>\n<p>指示项归零不是公式的缺陷，而是它的定义域边界。单节点 NVLink 全互联时，任意设备到任意设备的字节都走同一张 fabric，扇出不增加跨链路字节，V_a2a 的物理含义消失，下界退化为零——此时真正的瓶颈回到计算与显存，应由 MoE 解码 roofline 界接管，本式不再发言。另一类失效是重叠掩盖：专家放置均衡且 token 路由局部性好时，dispatch 可与专家 FFN 计算流水重叠，combine 可与下一层预填重叠，此时端到端时延由计算而非通信决定，字节下界虽仍成立却不再是瓶颈。判断是否落入这一类，要看 T_comm 下界与单层专家计算时间的大小关系：前者小于后者时，通信被掩盖，公式让位于计算界。</p>\n<p>工程判断落在最后一步：拿到本式后先问三个问题——拓扑是否跨 NVLink 域（决定指示项与 BW_link 替换）、路由分布的分位数是否远离均值（决定 k̄ 是否可信）、E 的增大是否真的带来分子收益而分母未同步恶化。三个问题任一为否，公式给出的就不是容量规划依据，而是误导。跨节点 EP 仍沿用 NVLink 带宽代入，是本式最常见的误用，其后果是把时延低估到与实际相差一个拓扑层级；而按均匀路由下界规划容量、忽略专家倾斜，则会让最慢链路在实际负载下成为真正的瓶颈，此时唯一可靠的修正是用倾斜分布的最慢链路字节数替换 V_a2a/E 的平均分摊。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-13\">十三 · 下界公式的适用边界：从单层 NVLink 到跨节点 IB 的失效面</h3>\n\n<p>本节的公式在两种拓扑下含义完全不同，必须把 cross-node 指示项当作开关而非修饰符。单节点内 NVLink 全互联时，任意两卡之间都有直连链路，token 发往本节点其他专家的字节并不会因为扇出增大而额外占用跨链路带宽——此时 <span>𝟙[cross-node]=0</span>，下界退化为零，通信不再是端到端瓶颈，真正的代价转移到 SM 占用与 dispatch/combine 的 kernel 启动开销上。一旦 EP 度越过 NVLink 域边界，指示项取 1，公式立刻从“零”跳到“按最慢链路计”的硬下界，这个跳变不是渐变的：GB200 NVL72 的 NVLink 域是 72 卡，EP=72 时下界为零，EP=73 时哪怕只多一个专家落在域外，整层 All-to-All 的字节都要按 IB/RoCE 的有效带宽重新计价。工程判断因此很直接：EP 度应当尽量取 NVLink 域大小的整数分之一或整数倍，让跨域份额要么为零、要么被均匀摊到尽可能少的链路上，避免出现“只溢出一点点却按最慢链路付费”的悬崖。</p>\n\n<p>失效条件的第一类是路由倾斜。公式里的 <span>\\(\\bar{k}\\)</span> 是平均跨设备专家数，下界对平均量成立，但实际时延由最慢链路决定：当少数热门专家集中在一张卡上，该卡的入向链路承载的字节远超平均值，而其余链路空闲。此时总通信量低于均匀假设下的上界，可端到端时延反而更高——下界不再代表实际时延，它变成了一个过于乐观的估计。容量规划若直接代入均匀下界，会系统性低估每层 All-to-All 的耗时，解码阶段每 token 都要过一次 All-to-All，这个低估会按层数累乘。对策不是修正公式，而是在路由侧引入容量因子（capacity factor）限制单专家接收 token 数，把倾斜压回可控范围，再用修正后的 <span>\\(\\bar{k}_{\\max}\\)</span> 而非 <span>\\(\\bar{k}\\)</span> 代入估算。</p>\n\n<p>第二类失效是带宽替换不彻底。跨节点 EP 走 InfiniBand 时，<span>\\(\\mathrm{BW}_{\\text{link}}\\)</span> 必须换成 IB/RoCE 的有效带宽，且 <span>\\(\\eta_{\\text{hop}}\\cdot\\#\\text{hops}\\)</span> 这一项不能再忽略：多级 fabric 下每跳的固定时延在小消息场景会主导总时延，而 MoE 的 dispatch 恰恰是大量小消息。仍沿用 NVLink 带宽代入公式，会把跨节点通信时延低估一个量级以上，直接导致 EP 拓扑选型错误。下表给出同一公式在两种拓扑下的代入差异，可见分母与附加项同时变化，量级不可互换。</p>\n\n<table class=\"mini\"><thead><tr><th>代入项</th><th>NVLink 域内</th><th>跨节点 IB</th></tr></thead><tbody><tr><td>𝟙[cross-node]</td><td>0</td><td>1</td></tr><tr><td>BW_link</td><td>NVLink 有效带宽</td><td>IB/RoCE 有效带宽（远低）</td></tr><tr><td>η_hop·#hops</td><td>不计</td><td>必须计入，小消息下主导</td></tr><tr><td>下界性质</td><td>退化为零，非瓶颈</td><td>硬下界，常为解码瓶颈</td></tr></tbody></table>\n\n<p>第三类误用是误以为增大 E 总能摊薄通信。公式中 E 同时出现在分子比例 <span>(1-1/E)</span> 与分母带宽 <span>\\(B_{\\text{NVLink}}\\cdot E\\)</span> 中：域内时比例趋近 1 而分母线性增长，摊薄成立；跨域时分子被 cross-node 指示项整体放大，分母却换成远低的 IB 带宽，E 增大反而把更多字节推过域边界。判断增大 E 是否划算，应看 <span>\\((1-1/E)\\cdot b_a\\cdot\\bar{k}\\)</span> 与 <span>\\(\\mathrm{BW}_{\\text{link}}\\)</span> 的乘积是否随 E 改善，而不是只看比例项。这条判据直接决定 EP 拓扑选择：域内扩 EP 摊薄通信，跨域扩 EP 要先算清 fabric 跳数与最慢链路余量。</p>\n<h3 id=\"th-alltoall-lower-bound-sec-14\">十四 · 均匀路由假设：从“平均份额”到“最慢链路”的断裂</h3>\n<p>前两部分把下界写成 <span class=\"formula\">$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]$$</span> 的形式，其中 <span class=\"formula\">$$\\bar{k}$$</span> 是平均每 token 跨设备专家数。这个平均值的合法性完全依赖一个隐含前提：路由分布均匀，且专家放置均衡。推导里用 <span class=\"formula\">$$(1-1/E)$$</span> 扣除非本地份额，本质是把“每个 token 有 <span class=\"formula\">$$1/E$$</span> 概率留在本设备”当作确定性比例来用。一旦路由倾斜，这个比例对多数 token 失效，对少数 token 又严重低估。</p>\n<p>具体机制在于：All-to-All 的完成时间由最慢的那条链路决定，而不是由总字节数除以总带宽决定。均匀假设下总字节被均匀摊到 <span class=\"formula\">$$E$$</span> 条链路上，最慢链路恰好等于平均值；倾斜时总字节可能下降，但某几条链路承载的字节数反而上升。设第 <span class=\"formula\">$$i$$</span> 条链路承载字节为 <span class=\"formula\">$$V_{i}$$</span>，则真实时延满足 <span class=\"formula\">$$T_{\\text{comm}}\\ge \\max_{i} V_{i}/\\mathrm{BW}_{\\text{link}}$$</span>，而均匀下界给的是 <span class=\"formula\">$$\\sum_{i}V_{i}/(E\\cdot \\mathrm{BW}_{\\text{link}})$$</span>。两者之间的差距就是路由倾斜度。工程代价很直接：按均匀下界做容量规划，会把每层 All-to-All 时延估低，解码阶段每 token 都要过一遍这个瓶颈，端到端 TPOT 被最慢链路拖住，而总带宽利用率看起来还很“健康”。</p>\n<p>一个具体例子：某层 8 个专家分布在 8 个 GPU 上，某 batch 的 token 因领域集中而大量涌向专家 0 与专家 1，其余专家几乎空闲。此时总跨设备字节可能低于均匀估计，但 GPU0 的接收链路被打满，其余链路空转，实际时延由 GPU0 决定。这种情况下公式的数值不再代表端到端瓶颈，必须换成 max-over-links 的形式，或者引入路由倾斜度作为修正因子。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-15\">十五 · 单层 NVLink 拓扑：指示项归零与“下界消失”</h3>\n<p>公式里的 <span class=\"formula\">$$\\mathbb{1}[\\text{cross-node}]$$</span> 是一个硬开关。当 EP 度完全落在单个 NVLink 域内、且域内为全互联拓扑时，任意两设备之间都是一跳直达，扇出 <span class=\"formula\">$$\\bar{k}$$</span> 不增加“跨链路字节”——因为所有专家本来就在同一高带宽域里，token 发往哪个设备走的都是同一类链路。此时指示项为 0，下界退化为零，公式不再给出任何有意义的时延约束。</p>\n<p>这不是说通信不存在，而是说通信不再是“跨域”意义上的瓶颈：NVLink 域内带宽远高于跨节点链路，All-to-All 的字节可以被 dispatch 与专家计算重叠掩盖。失效的判据是重叠窗口：若单层专家计算时间 <span class=\"formula\">$$T_{\\text{expert}}$$</span> 大于域内 All-to-All 的实际传输时间，则通信完全藏在计算后面，端到端瓶颈转移到计算或显存。工程上这意味着：在小规模 EP（例如单机 8 卡）上套用跨节点下界公式，会得出一个虚假的“通信瓶颈”结论，误导人去优化一条根本不紧张的链路。</p>\n<p>反过来，当 EP 度跨出 NVLink 域，指示项变为 1，公式才重新生效，但此时 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 必须换成最慢的那条跨节点链路带宽（IB/RoCE），并加上 <span class=\"formula\">$$\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span> 的每跳固定时延。代价量级的变化是结构性的：跨节点链路的有效带宽比 NVLink 低一个量级以上，跳数又把固定时延乘上去，原本可被计算掩盖的通信突然变成显性瓶颈。判断边界的方法很朴素——先看 EP 拓扑是否越过 NVLink 域边界，越过了才谈下界，没越过就谈重叠。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-16\">十六 · 规模上限：E 增大时分子与分母的耦合</h3>\n<p>公式中 <span class=\"formula\">$$E$$</span> 同时出现在两个位置：分子里的非本地比例 <span class=\"formula\">$$(1-1/E)$$</span> 随 <span class=\"formula\">$$E$$</span> 增大趋近于 1，分母里的聚合带宽 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}\\cdot E$$</span> 随 <span class=\"formula\">$$E$$</span> 线性增长。单看这个结构，时延下界随 <span class=\"formula\">$$E$$</span> 增大而下降，似乎“EP 度越大通信越便宜”。但这个结论只在单层 NVLink 全互联、且带宽随 <span class=\"formula\">$$E$$</span> 线性可扩展的前提下成立。</p>\n<p>规模上限出现在两处。第一处是拓扑：NVLink 域的大小有物理上限，<span class=\"formula\">$$E$$</span> 超过域内可互联的设备数后，新增的 EP 度只能落在跨节点链路上，分母里的带宽不再是 <span class=\"formula\">$$\\mathrm{BW}_{\\text{NVLink}}\\cdot E$$</span>，而是被最慢跨节点链路钳制，<span class=\"formula\">$$E$$</span> 的线性摊薄效应中断。第二处是路由扇出：<span class=\"formula\">$$\\bar{k}$$</span> 随专家总数增长而增长（top-k 路由在更大专家池里更可能跨设备），分子不再是一个与 <span class=\"formula\">$$E$$</span> 无关的常数，而是随规模上升。两者叠加，时延下界在某个 <span class=\"formula\">$$E$$</span> 之后不再下降，甚至回升。</p>\n<p>工程判断因此不能只看“增大 E 能否摊薄通信”，而要看 <span class=\"formula\">$$(1-1/E)$$</span> 的比例收益是否还被分母带宽的拓扑代价吃掉。一个具体场景：单机 8 卡 NVLink 域内把 EP 从 4 提到 8，分母翻倍、分子比例从 0.75 提到 0.875，净收益明显；继续把 EP 提到 16 而必须跨节点时，分母带宽骤降、跳数时延加入，净收益转负。容量规划里这个拐点就是 EP 拓扑选择的依据：域内加密度优先，跨域扩展要先算清链路带宽与跳数。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-17\">十七 · 失效条件清单：什么时候公式不再成立</h3>\n<p>把适用边界收敛成可操作的判据，至少有以下几类失效：</p>\n<ul>\n<li><b>路由高度倾斜</b>：均匀比例 <span class=\"formula\">$$(1-1/E)$$</span> 不再代表实际跨设备份额，最慢链路成为瓶颈，下界低于实际时延。修正方向是 max-over-links 或引入倾斜度因子。</li>\n<li><b>单层 NVLink 全互联</b>：指示项为 0，下界退化为零，通信被计算重叠掩盖，公式不再给出端到端约束。</li>\n<li><b>跨节点仍用 NVLink 带宽</b>：<span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 未替换为 IB/RoCE 有效带宽，且未计入 <span class=\"formula\">$$\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span>，时延被系统性低估。</li>\n<li><b>专家放置不均衡</b>：即使路由均匀，若专家在设备上分布不均，某些设备承载的专家被更多 token 命中，链路负载偏离平均值，同样触发最慢链路瓶颈。</li>\n<li><b>重叠窗口不足</b>：dispatch 与 combine 无法与专家计算重叠时（例如小 batch 解码、专家计算极短），通信从“可掩盖”变为“显性”，下界重新成为瓶颈，但此时实际时延还受启动开销与同步代价影响，纯字节除以带宽的模型偏乐观。</li>\n</ul>\n<p>这些失效条件的共同结构是：公式假设“总字节均匀分摊到所有链路”和“通信是端到端唯一显性成本”。任一假设破裂，下界的数值就不再是工程上可用的估计。代价表现各异——倾斜表现为 TPOT 抖动与链路利用率不均，拓扑误用表现为跨节点吞吐骤降，重叠不足表现为小 batch 下延迟不降反升。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-18\">十八 · 边界内的正确用法：从下界到决策</h3>\n<p>公式在边界内仍然有价值，但用法要精确。它回答的是“在均匀路由、单层 NVLink、跨节点指示项为 1 的条件下，每层 All-to-All 时延不可能低于多少”，因此适合做两件事：判断通信是否可能成为解码瓶颈的下限筛查，以及比较不同 EP 拓扑下通信代价的量级差异。</p>\n<p>具体做法是先做拓扑分类：若 EP 全在 NVLink 域内，直接判定通信可被重叠，把优化预算投向计算与显存；若跨节点，则代入最慢链路带宽与跳数，得到每层时延下界，再与每 token 的专家计算时间比较。若下界已接近或超过计算时间，通信就是显性瓶颈，需要减少跨节点扇出（路由局部性、专家亲和放置）或缩小 EP 度。若下界远低于计算时间，则不必在通信上投入，除非路由倾斜使最慢链路偏离平均值。</p>\n<p>这里的关键工程判断是：下界只用于“排除不可能”和“量级比较”，不用于精确容量规划。精确规划必须补上倾斜度与重叠窗口两个修正，否则就会落入按均匀下界估容量的失败模式——账面带宽充裕，实际最慢链路先饱和，端到端时延远超估计。公式的边界本身就是它的使用说明书：越过 NVLink 域边界才谈字节下界，域内谈重叠；路由均匀才谈平均份额，倾斜谈最慢链路。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-19\">十九 · 边界在哪里：均匀路由、单层 NVLink 与 (1−1/E) 的耦合</h3>\n<p>本卷前文给出的跨设备通信下界，其成立依赖三个隐含前提同时为真：路由分布近似均匀、专家放置均衡、拓扑是单层 NVLink 全互联。三者中任一被破坏，公式就从“下界”退化为“一个与实际时延无关的乐观估计”。最容易被忽略的是 (1−1/E) 这个因子——它同时出现在分子（非本地专家比例）与分母（按 EP 度分摊的有效带宽 B_NVLink·E）中，这意味着增大 E 并不单调地摊薄通信：分子趋近 1 而分母线性增长，表面上时延按 1/E 下降，但这一结论只在“每个 token 恰好命中 k 个均匀分布的专家、且所有跨设备流量都走同一层 NVLink 交换机”时成立。一旦 EP 度跨出单机 NVLink 域，分母必须换成跨节点 IB/RoCE 的有效带宽，量级落差远大于 E 带来的分摊收益，此时继续代入 B_NVLink 会把时延低估一个数量级以上，这是容量规划中最常见的误用。</p>\n<p>失效条件的判定可以写成一个指示项的形式，用来提醒实现者公式何时归零：</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ge\\frac{2\\,T_{\\text{act}}\\,d\\,b_{a}\\,(1-1/E)}{\\mathrm{BW}_{\\text{link}}\\cdot E}\\cdot\\mathbb{1}[\\text{cross-node}]+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</div>\n<p>当 EP 全部落在单节点内、NVLink 全互联时，扇出不增加跨链路字节，指示项为 0，下界退化为零——此时真正的瓶颈是 SM 内的 dispatch/combine 融合与计算重叠，而非链路带宽，公式不再有诊断价值。反之，跨节点 EP 时指示项为 1，必须把 BW_link 替换为 IB 有效带宽并计入 η_hop 与跳数；在 GB200 NVL72 这类机柜级域内，NVLink 域边界把一次 All-to-All 切成“域内高带宽段 + 域间低带宽段”两截，端到端时延由最慢那段决定，而不是由平均带宽决定。</p>\n<p>第二个失效条件是路由倾斜。均匀路由下实际通信量接近上界，但真实 MoE 推理中 token 路由高度集中，少数热门专家所在设备成为热点，此时全网平均字节数低于公式给出的量，而最慢链路的瞬时排队却远超估计——下界不再代表实际时延，反而给出一个偏小的数字诱导工程师低估容量。工程判断应落在“最慢链路”而非“平均带宽”上：按均匀下界做容量规划，会在专家倾斜的真实负载下出现尾延迟塌陷。第三个边界是规模上限：E 增大到跨节点后，η_hop·#hops 项随拓扑层数增长，而 (1−1/E) 已趋饱和，分摊收益被跳数时延吃掉；此时提升 EP 度的正确做法是缩小 NVLink 域内的专家组、把跨域流量压到少数聚合节点，而不是继续线性放大 E。判断公式是否仍适用的操作性准则很简单：先确认路由熵与专家负载分布的偏斜度，再确认 EP 拓扑是否单层，两者任一不满足就应切换到“最慢链路 + 跳数”的实测模型，而不是继续解析求导。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-20\">二十 · 下界公式的三处“地基”与它们各自的塌陷方式</h3>\n<p>这个下界不是一条无条件成立的不等式，它站在三块地基上：路由均匀、拓扑单层、带宽取最慢链路。任何一块塌陷，公式给出的数字就从“不可能更快”退化为“某种理想排布下可能更快”，失去约束力。第一块地基是路由均匀假设。公式里用 (1−1/E) 表示发往非本地专家的份额，前提是每个 token 的 k 个目标专家在 E 个设备上均匀散开。一旦路由倾斜——少数专家吸走大部分 token——跨设备字节总量确实下降，但流量集中到少数链路上，此时瓶颈不再是总字节除以总带宽，而是最忙那条链路的排队。均匀下界此时偏乐观，用它做容量规划会系统性低估尾延迟。工程上应把公式改为按最热专家所在链路的字节数取 max，而不是按全局平均。</p>\n<p>第二块地基是拓扑单层。公式隐含所有跨设备流量走同一层 NVLink 全互联，一跳直达。跨节点 EP 时这条不成立：NVLink 域边界把流量切成域内与域间两段，域间走 InfiniBand/RoCE，有效带宽远低于 NVLink，且每经过一级交换就多一次固定时延。此时必须把 BW_link 替换为 IB 有效带宽，并叠加 η_hop·#hops 项。常见误用正是沿用 NVLink 带宽代入，把跨节点 All-to-All 时延估低一个量级，进而误判解码阶段通信可被计算掩盖。</p>\n<div class=\"formula\">$$T_{\\text{comm}}\\ge\\frac{2\\,T\\,d\\,b_a\\,\\bar{k}}{\\mathrm{BW}_{\\text{slowest}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops},\\qquad \\bar{k}=\\frac{E-1}{E}\\cdot k$$</div>\n<p>第三块地基是“增大 E 总能摊薄通信”。注意 E 同时出现在分子的 (1−1/E) 与分母的带宽项里：域内时两者近似抵消，收益趋平；跨节点时分母换成 IB 带宽，E 增大反而拉长跳数与最慢链路占比。规模上限由此显现——当 EP 度超出单个 NVLink 域容量，公式中的 cross-node 指示项被迫置 1，下界抬升而非下降。判断准则很直接：若 (1−1/E) 的下降被 BW_slowest 的下降抵消，扩容 EP 只增加拓扑代价。表里给出三种边界情形的定性对照。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>公式状态</th><th>系统代价落点</th></tr></thead><tbody><tr><td>单节点 NVLink 全互联</td><td>cross-node 项为 0，下界退化</td><td>扇出不增加跨链路字节，瓶颈回到计算或显存</td></tr><tr><td>路由局部性好且 dispatch 融合</td><td>下界被重叠掩盖，不再是端到端瓶颈</td><td>实际时延由最慢链路与融合效率决定</td></tr><tr><td>跨节点 EP 走 IB</td><td>需替换带宽并计跳数</td><td>每跳固定时延与低带宽共同抬高下界</td></tr></tbody></table>\n<p>还有一处容易被忽略的边界：b_a 取 FP8=1、NVFP4=0.5 时，公式假设 dispatch 与 combine 使用同一精度。若 dispatch 用 FP8 而 combine 回传用更高精度，系数 2 就不再对称，下界需按两段分别计算再取和。这不是精度细节，而是直接改变分子量级的建模错误。真正决定这个下界能否用于容量决策的，是它是否与实际最慢链路对齐；对齐时它是硬约束，错位时它只是乐观估计。</p>\n<h3 id=\"th-alltoall-lower-bound-sec-21\">二十一 · 把下界写成可求解的容量方程</h3>\n<p>容量决策的第一件事，是把通信下界从“不等式”改写成“约束”。给定目标 SLO 中的单 token 解码时延预算 <span class=\"inline-math\">τ</span>，以及每层可分摊给 All-to-All 的份额 <span class=\"inline-math\">γ</span>（其余留给 MMA、attention、KV 读取与调度开销），则每层允许的通信时延为 <span class=\"inline-math\">γτ</span>。把下界代入并取等号，得到关于批内 token 数 <span class=\"inline-math\">T</span> 的容量方程：</p>\n<div class=\"formula\">$$T_{\\max}=\\frac{\\left(\\gamma\\tau-\\eta_{\\text{hop}}\\cdot\\#\\text{hops}\\right)\\cdot \\mathrm{BW}_{\\text{link}}}{2\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]}$$</div>\n<p>这个式子的工程含义很直接：<strong>时延预算减去跳数固定开销后，剩余的时间乘以最慢链路带宽，就是这一层允许搬运的字节数；再除以每 token 的跨设备字节数，就是批大小上限。</strong>注意分子里的减法是硬约束——当 <span class=\"inline-math\">η·#hops</span> 接近 <span class=\"inline-math\">γτ</span> 时，<span class=\"inline-math\">T<sub>max</sub></span> 迅速塌缩到零，说明拓扑跳数本身就是不可忽略的容量税，而不是可以靠增大批来摊薄的成本项。这一点与单节点 NVLink 全互联情形（指示项为 0、下界退化为零）形成鲜明对照：域内 EP 的批大小由算力与 KV 决定，域间 EP 的批大小首先由链路决定。</p>\n<p>反过来解并行度。设单卡可承载的专家数与显存预算已定，EP 度 <span class=\"inline-math\">E</span> 同时出现在跨设备比例与聚合带宽中，把 <span class=\"inline-math\">T<sub>max</sub>(E)</span> 对 <span class=\"inline-math\">E</span> 求值即可判断“加卡是否摊薄通信”。在单层 NVLink 拓扑下，聚合带宽随 <span class=\"inline-math\">E</span> 增长而跨设备比例按 <span class=\"inline-math\">(1-1/E)</span> 收敛到 1，两者相抵后时延下界近似与 <span class=\"inline-math\">E</span> 无关——这解释了为什么域内扩 EP 对通信时延的边际收益很快耗尽，真正的收益来自显存与算力分摊，而非通信。跨节点时带宽不随 <span class=\"inline-math\">E</span> 线性增长（IB 端口数与交换机层级受限），此时增大 <span class=\"inline-math\">E</span> 反而使 <span class=\"inline-math\">T<sub>max</sub></span> 下降，这是容量规划中最容易踩空的一步。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-22\">二十二 · 定 KV 预算：通信批与显存批的耦合</h3>\n<p>KV cache 容量式给出的是“显存允许的批”，通信下界给出的是“时延允许的批”，两者取小才是可部署批大小。设每 token 每层 KV 字节为 <span class=\"inline-math\">b_{kv}</span>、层数 <span class=\"inline-math\">L</span>、每卡可用显存 <span class=\"inline-math\">M</span>，则显存侧上限为 <span class=\"inline-math\">T<sub>kv</sub>=M/(L·b_{kv})</span>（忽略权重与激活，权重由 EP 分摊另行扣除）。实际批大小 <span class=\"inline-math\">T<sub>eff</sub>=min(T<sub>max</sub>, T<sub>kv</sub>)</span>。这个 min 的取法决定了优化方向：若 <span class=\"inline-math\">T<sub>max</sub> &lt; T<sub>kv</sub></span>，瓶颈在链路，扩容应优先加带宽或减少跨节点扇出（改专家放置、加局部性路由），而不是加显存；若 <span class=\"inline-math\">T<sub>kv</sub> &lt; T<sub>max</sub></span>，瓶颈在显存，扩容应优先加卡分摊 KV 或降低 KV 精度。</p>\n<p>更细一层，KV 预算还要为通信留出“在途缓冲”。All-to-All 的 dispatch 与 combine 各一次，若采用分块流水（chunked dispatch）与计算重叠，则在途缓冲的峰值约正比于 <span class=\"inline-math\">T·d·b<sub>a</sub>·k̄</span> 的一个分块份额，而不是整批。工程上把批切成若干 chunk，使每 chunk 的通信字节落在“能被 MMA 时间掩盖”的窗口内，等价于把 <span class=\"inline-math\">T<sub>max</sub></span> 从整批约束降为 chunk 约束，从而允许更大的总批。代价是 chunk 数增加带来更多 kernel 启动与同步开销，以及 combine 端需要按 chunk 重组 token 顺序，这部分开销应计入 <span class=\"inline-math\">γ</span> 的扣减项而非通信下界本身。</p>\n<p>算例：设 <span class=\"inline-math\">d=7168</span>、<span class=\"inline-math\">b<sub>a</sub>=1</span>（FP8）、<span class=\"inline-math\">k̄=4</span>、跨节点 IB 有效带宽取相对量 <span class=\"inline-math\">BW<sub>link</sub></span>、跳数 2、每跳固定时延 <span class=\"inline-math\">η</span>。若 <span class=\"inline-math\">γτ=200</span> 个相对时间单位、<span class=\"inline-math\">η·#hops=20</span>，则分子为 <span class=\"inline-math\">180·BW<sub>link</sub></span>，分母为 <span class=\"inline-math\">2·7168·1·4=57344</span>。把 <span class=\"inline-math\">BW<sub>link</sub></span> 按 IB 相对 NVLink 的低带宽代入，得到的 <span class=\"inline-math\">T<sub>max</sub></span> 会显著小于显存侧 <span class=\"inline-math\">T<sub>kv</sub></span>，结论是：该配置下批大小由链路而非显存决定，扩容优先级应给网络。若把同一模型放回单节点 NVLink 域内，指示项归零、下界消失，<span class=\"inline-math\">T<sub>eff</sub></span> 立即由 <span class=\"inline-math\">T<sub>kv</sub></span> 接管——这就是拓扑选择对容量的量级影响。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-23\">二十三 · 定 SLO：把下界翻译成尾时延约束</h3>\n<p>SLO 通常写成 P99 时延或 goodput 下限。通信下界本身是均值意义上的，但容量决策必须面对倾斜路由下的最慢链路。均匀路由下界给出的是“平均每 token 字节数除以聚合带宽”，而实际瓶颈是“最热专家所在链路的字节数除以该链路带宽”。设路由倾斜度为 <span class=\"inline-math\">ρ</span>（最热专家接收的 token 份额相对均匀份额的倍数），则最慢链路时延约放大 <span class=\"inline-math\">ρ</span> 倍。工程上不应直接把 <span class=\"inline-math\">ρ</span> 乘进下界当作新下界（它不是下界，只是估计），而应把它作为 SLO 校验项：用均匀下界算出 <span class=\"inline-math\">T<sub>max</sub></span> 后，再检查 <span class=\"inline-math\">ρ·T<sub>comm</sub>(T<sub>max</sub>)</span> 是否仍落在 <span class=\"inline-math\">γτ</span> 内；若不落在，则实际可部署批要按 <span class=\"inline-math\">T<sub>max</sub>/ρ</span> 收缩，或引入容量因子（capacity factor）限制每专家接收上限，把 <span class=\"inline-math\">ρ</span> 压回可控范围。容量因子会丢弃部分 token 的路由（回退到次优专家或本地计算），代价是模型质量与额外计算，需与 SLO 违约风险一起权衡。</p>\n<p>对分离式部署，预填与解码的 SLO 形态不同：预填是吞吐导向、批大、单次长；解码是时延导向、批小、每步都要走一遍 All-to-All。因此同一公式在两段的用法不同——预填段用 <span class=\"inline-math\">T<sub>max</sub></span> 约束的是“单批预填能否在 SLA 内完成”，解码段约束的是“每步 decode 的通信份额是否小于 <span class=\"inline-math\">γτ</span>”。解码段 <span class=\"inline-math\">T</span> 小、<span class=\"inline-math\">η·#hops</span> 占比高，跳数税在解码段远比预填段致命，这也是解码实例倾向放在 NVLink 域内、预填实例可跨域的原因。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-24\">二十四 · 定并行度：EP 与 TP 的联合取舍</h3>\n<p>并行度决策不是单独定 EP，而是 EP 与 TP 的联合分配。TP 的通信是每层两次 all-reduce，字节量正比于 <span class=\"inline-math\">T·d·b<sub>a</sub></span> 且不随专家扇出放大；EP 的通信是 all-to-all，字节量再乘 <span class=\"inline-math\">k̄</span> 与跨节点指示项。在同一 NVLink 域内，TP 的 all-reduce 通常可被计算掩盖且带宽充裕；EP 的 all-to-all 因扇出与不均衡更难掩盖。因此域内优先用 TP 摊薄权重、用较小 EP 控制扇出；跨域时才考虑大 EP，并必须把 <span class=\"inline-math\">BW<sub>link</sub></span> 换成 IB 有效带宽、把 <span class=\"inline-math\">η·#hops</span> 计入。判断准则可写成：若 <span class=\"inline-math\">T<sub>comm,EP</sub>(E) &gt; T<sub>comm,TP</sub>(TP)</span> 且前者已逼近 <span class=\"inline-math\">γτ</span>，则继续加 EP 不划算，应改为在域内加 TP 或增加副本（数据并行）来提升吞吐。</p>\n<p>另一个常被忽略的耦合是专家放置。公式里的 <span class=\"inline-math\">k̄</span> 是“平均每 token 跨设备专家数”，它由路由分布与放置共同决定。把高频共现的专家放在同一设备或同一 NVLink 域，可降低 <span class=\"inline-math\">k̄</span> 的跨域部分，等效于把指示项从 1 压向 0。这是放置优化而非公式修改，但对 <span class=\"inline-math\">T<sub>max</sub></span> 的影响是乘性的：跨域扇出减半，<span class=\"inline-math\">T<sub>max</sub></span> 翻倍。容量规划应把放置作为一等决策变量，而不是事后调优。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-25\">二十五 · 误用清单与工程判断</h3>\n<p>三类误用直接对应三条失效路径。其一，用均匀路由下界做容量规划而忽略倾斜：算出的 <span class=\"inline-math\">T<sub>max</sub></span> 看似宽裕，实际最慢链路时延远超估计，SLO 在尾部长尾处违约。其二，跨节点 EP 仍代入 NVLink 带宽：分子被高估，<span class=\"inline-math\">T<sub>max</sub></span> 被高估数倍，且漏掉 <span class=\"inline-math\">η·#hops</span> 固定项，解码段尤其失真。其三，误以为增大 <span class=\"inline-math\">E</span> 总能摊薄通信：忽略了 <span class=\"inline-math\">(1-1/E)</span> 比例与分母带宽的耦合，域内收益饱和、域外可能反向恶化。</p>\n<p>正确的用法是把公式当作“约束生成器”而非“性能预测器”：它给出的是任何实现都无法突破的时延地板，因此适合做容量下界、批大小上界与拓扑筛选；它不适合预测实际时延，因为融合 dispatch、计算重叠、路由局部性都会把实际值抬离地板。工程判断的落点是：先用公式筛掉不可行的拓扑与批大小组合，再用实测的 <span class=\"inline-math\">ρ</span> 与重叠效率修正，最后把 <span class=\"inline-math\">γ</span> 的分配写进 SLO 契约——通信份额一旦被链路锁死，就只能靠减少跨域扇出或改拓扑来解锁，加算力无效。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-26\">二十六 · 把下界嵌进容量决策：四个可调旋钮与两处塌陷</h3>\n\n<p>把 <span class=\"formula\">$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]$$</span> 当作容量决策的输入，而不是事后核算的账单，关键在于认清它同时被四个旋钮牵动：批内 token 数 <em>T</em>、隐藏维 <em>d</em>、激活字节 <em>b<sub>a</sub></em>、平均跨设备专家数 <em>k̄</em>，而 <em>k̄</em> 本身又是 EP 度 <em>E</em> 与路由分布的函数。定批大小时不能只看显存与算力，要把 <em>T</em> 与 <em>T<sub>comm</sub></em> 一起解：解码阶段每步的 All-to-All 时延若已接近单步计算时延，增大批只会线性抬高 <em>V<sub>a2a</sub></em> 而不改善每 token 摊销，此时应转向提高 EP 度或改拓扑。定并行度时，<em>E</em> 同时出现在分子比例与分母带宽里，均匀路由下跨设备份额约为 <em>(1−1/E)</em>，而可用链路带宽被 <em>E</em> 分摊，两者相抵后下界对 <em>E</em> 的敏感度远低于直觉——这正是“增大 E 总能摊薄通信”这一误判的根源。定 KV 预算时，<em>V<sub>a2a</sub></em> 与 KV 争抢的是同一块 HBM 带宽与同一组链路：dispatch/combine 的激活搬运与 KV 的读写叠加后，有效带宽 <span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 需按峰值并发折算，否则下界算出的时延只是空载值。定 SLO 时把 <em>T<sub>comm</sub></em> 写成 <span class=\"formula\">$$T_{\\text{comm}}\\ge\\frac{V_{\\text{a2a}}}{\\mathrm{BW}_{\\text{link}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span>，第二项在跨节点时不可忽略，它把“带宽够”与“时延达标”拆成两个独立约束。</p>\n\n<p>算例只做量纲推演，不引入实验数字。设某解码步批内 <em>T</em> 个 token、隐藏维 <em>d</em>、FP8 激活（<em>b<sub>a</sub></em>=1）、均匀路由下 <em>k̄</em> 取跨节点份额，先算 <em>2·T·d·1</em> 得到全部激活字节，再乘非本地比例得到 <em>V<sub>a2a</sub></em>；若拓扑为单层 NVLink 域内，指示项为 0，下界退化为零，此时通信可被融合 dispatch 与计算重叠掩盖，瓶颈回到算力与 HBM。一旦 EP 跨节点走 IB/RoCE，<em>BW<sub>link</sub></em> 必须换成 IB 有效带宽，且 <em>η<sub>hop</sub>·#hops</em> 项按跳数线性叠加；把 NVLink 带宽代入跨节点场景，会把时延低估一个量级以上，这是容量规划中最常见的塌陷。表格给出四个旋钮的调节方向与代价归属：</p>\n\n<table class=\"mini\"><thead><tr><th>旋钮</th><th>对下界的作用</th><th>系统代价归属</th></tr></thead><tbody><tr><td><em>T</em>（批大小）</td><td>线性抬高 <em>V<sub>a2a</sub></em></td><td>显存与链路带宽同增，摊销未必改善</td></tr><tr><td><em>E</em>（EP 度）</td><td>分子 <em>(1−1/E)</em> 与分母带宽耦合</td><td>跨节点时拓扑跳数与 IB 带宽成主约束</td></tr><tr><td><em>b<sub>a</sub></em>（精度）</td><td>FP8=1、NVFP4=0.5，直接减半</td><td>量化误差与反量化开销转移到算力侧</td></tr><tr><td>拓扑（域内/跨节点）</td><td>指示项 0 与非 0 的开关</td><td>NVLink 域边界决定 <em>BW<sub>link</sub></em> 取值</td></tr></tbody></table>\n\n<p>该方案的边界必须写进决策流程而非脚注。第一处塌陷是专家倾斜：均匀路由下界给出的是“平均链路”的乐观值，而实际最慢链路承担了远超均值的 token 份额，端到端时延由最慢链路决定，此时下界不再代表实际时延，按它规划容量会系统性低估。第二处塌陷是拓扑误代：跨节点 EP 仍沿用 NVLink 带宽，忽略 IB 有效带宽与跳数项，等于把 <em>T<sub>comm</sub></em> 的下界当成上界用。第三处是 <em>E</em> 的边际收益递减——分子比例趋近 1 而分母带宽被 <em>E</em> 分摊，继续增大 <em>E</em> 只增加跨节点跳数与调度复杂度。工程判断因此落在：域内 EP 用该式确认通信已被重叠掩盖即可，不必细算；跨节点 EP 则必须把 <em>BW<sub>link</sub></em> 换成 IB 实测有效带宽、把 <em>η<sub>hop</sub>·#hops</em> 计入 SLO 余量，并以专家倾斜后的最慢链路而非均匀下界作为容量上限的约束条件。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-27\">二十七 · 把下界嵌进容量决策：批大小、EP 度与 KV 预算的联立</h3>\n<p>这个下界在容量决策里的正确用法不是“算出一个数然后照抄”，而是把它当成一条约束去反解批大小。解码阶段每层 All-to-All 的时间下界除以层数，就是单 token 的通信摊薄成本；把它与单 token 的权重读取、KV 读取成本相加，得到每 token 的服务时间，再用 SLO 的 TPOT 上限去除，得到可承载的并发 token 数 <span class=\"formula\">$$T_{\\max}\\approx\\frac{\\text{TPOT}_{\\text{SLO}}-t_{\\text{compute}}}{2\\,d\\,b_a\\bar{k}\\,\\mathbb{1}[\\text{cross-node}]/(\\mathrm{BW}_{\\text{link}})+\\eta_{\\text{hop}}\\#\\text{hops}}$$</span> 注意分母里没有 E：均匀路由下 EP 度增大时 (1−1/E) 趋近 1、分母带宽按 B_NVLink·E 摊薄，两者在单层时延上大致抵消，所以“加大 E 就能摊薄通信”只在 NVLink 域内、且专家放置真正均衡时成立。KV 预算同理受牵连——批越大，每层 dispatch 的 T 越大，通信字节线性上涨，而 KV cache 的显存占用也线性上涨，两者共同把可用的 batch 上限压到显存与带宽两条约束的交点。</p>\n<p>算例：FP8 激活（b_a=1），d 取一个中等隐藏维，单节点 8 卡 NVLink 域内 EP=8，路由均匀，cross-node 指示项为 0，公式退化为零，此时通信不构成瓶颈，批大小由 KV 显存与权重带宽决定。一旦 EP 扩到跨节点、扇出 \\bar{k} 覆盖到远端专家，指示项置 1，分子变成 2·T·d·\\bar{k} 字节，分母换成 IB 有效带宽并叠加 \\eta_{\\text{hop}}·#hops；此时每增加一档批大小，时延按字节线性增长，而 IB 带宽比 NVLink 低一个量级，TPOT 预算很快被通信吃满。工程判断是：跨节点 EP 的批大小应按时延约束而非显存约束来定，且要把 \\bar{k} 按最慢链路而非平均值代入。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>代入方式</th><th>失效时的表现</th></tr></thead><tbody><tr><td>批大小</td><td>由 TPOT 反解 T，用最慢链路带宽</td><td>按均匀下界放大批，实际 TPOT 超标</td></tr><tr><td>EP 度</td><td>域内可增大，跨节点需重算分母</td><td>误以为 E 越大越省，忽略跳数代价</td></tr><tr><td>KV 预算</td><td>与通信字节共享 T，取两者交点</td><td>显存够但带宽先饱和</td></tr></tbody></table>\n<p>边界条件必须写进决策流程：专家倾斜时实际通信量低于均匀上界，但最慢链路成为瓶颈，下界不再代表实际时延，此时应按最大专家负载重算 \\bar{k} 的有效值；融合 dispatch 与计算重叠能掩盖部分时延，重叠率取决于 dispatch 与本地专家计算的相对时长，重叠不充分时下界重新变成端到端瓶颈。跨节点 EP 若仍沿用 NVLink 带宽代入，会系统性低估时延与拓扑跳数代价，这是容量规划中最常见的错误来源。</p>\n<h3 id=\"th-alltoall-lower-bound-sec-28\">二十八 · 误用一：把均匀路由下界当容量规划的真值</h3>\n<p>本卷前四部分给出的下界，前提是路由分布均匀、专家负载均衡。工程上最常见的误用，是把这条理想化下界直接代入容量规划，用它估算每层 All-to-All 的时延预算，再据此决定 EP 度、节点数与 SLO 余量。后果是系统上线后最慢链路成为瓶颈：路由倾斜时，少数热门专家所在设备的入向链路被打满，而其余链路空闲。此时全局平均通信量确实低于均匀假设下的上界，但端到端时延由最慢那条链路决定，而不是由平均字节数决定。下界不再代表实际时延，规划出来的吞吐与延迟指标系统性偏乐观。</p>\n<p>识别方法很直接：在真实路由分布下采样每层 dispatch 的按目的设备字节直方图，计算其最大值与均值的比值，即倾斜因子。若该比值显著大于 1，则均匀下界失效。工程判断上，容量规划应改用最慢链路字节数除以该链路有效带宽，而不是用总字节数除以聚合带宽。具体例子：一个 EP=8 的单节点部署，均匀假设下每设备承担 (1-1/8) 的跨设备份额；若某层路由使两个专家吸收了大半 token，则这两个专家所在设备的入向链路承载的字节数远超均值，All-to-All 时延被这条链路钉住，增大 EP 度也无法摊薄，因为瓶颈不在总量而在分布。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-29\">二十九 · 误用二：跨节点 EP 仍代入 NVLink 带宽</h3>\n<p>公式中的 <span>BW_link</span> 定义为最慢链路有效带宽。单层 NVLink 全互联拓扑下，这一项是 NVLink 带宽；一旦 EP 域跨出 NVLink 域边界，dispatch 与 combine 被切成两段，跨节点段走 InfiniBand 或 RoCE，其有效带宽远低于 NVLink。误用在于沿用单节点推导时的带宽数值，把 cross-node 指示项当作 1 却仍填 NVLink 带宽，同时忽略每跳固定时延 <span>η_hop</span> 与跳数。后果是通信时延被严重低估，容量规划给出的 EP 度上限过高，实际部署时跨节点 All-to-All 成为解码主瓶颈，尾延迟远超 SLO。</p>\n<p>识别信号：拓扑中是否存在跨节点链路、路由是否真的落在远端专家。若存在，则必须把 <span>BW_link</span> 替换为跨节点链路的有效带宽，并在时延项中显式加上 <span>η_hop·#hops</span>。工程上可用一个简单判据：当跨节点字节数占总 dispatch 字节数的比例不可忽略时，NVLink 域内的带宽优势不再适用于全局下界，必须按两段分别估算再取和。具体例子：一个跨两节点的 EP 部署，域内段用 NVLink 传输本地份额，域间段用 IB 传输远端份额；若仍用 NVLink 带宽代入整段公式，估算出的每层时延会比按 IB 带宽加跳数计算的时延低一个量级，容量决策随之失真。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-30\">三十 · 误用三：以为增大 E 总能摊薄通信</h3>\n<p>公式中 E 同时出现在分子比例 (1-1/E) 与分母带宽 <span>BW_link·E</span> 中，二者耦合。均匀路由、单层 NVLink 拓扑下，增大 E 使非本地份额上升但聚合带宽同步上升，净效应是每设备承担的字节数被摊薄；然而一旦跨节点，分母中的带宽不再是随 E 线性增长的 NVLink 聚合带宽，而是被域边界切开的慢链路带宽，增大 E 反而增加跨节点跳数与远端份额。误用在于把“E 增大摊薄通信”当作无条件结论，忽略拓扑代价。后果是盲目提高 EP 度，跨节点流量与跳数同步上升，All-to-All 时延不降反升。</p>\n<p>识别方法：检查 E 的增长是否跨越了 NVLink 域边界。域内增大 E 摊薄有效；跨域增大 E 需重新代入跨节点带宽与跳数项。工程判断上，EP 度应优先在 NVLink 域内提升，跨域扩展前先确认远端份额与跳数带来的时延增量是否被计算重叠掩盖。具体例子：EP 从域内 8 扩到跨节点 16，域内份额从 7/8 降到 15/16，看似摊薄，但远端份额从 0 跳到接近一半，且这部分走 IB 并多一跳，每层 All-to-All 时延由 IB 带宽与跳数决定，摊薄效应被拓扑代价抵消。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-31\">三十一 · 反例：一个被下界误导的部署决策</h3>\n<p>设一个 MoE 解码服务，隐藏维 d、激活字节数 <span>b_a</span> 取 FP8 即 1，批内 token 数 T，路由扇出均值 <span>k̄</span>。规划者用均匀路由下界估算每层 All-to-All 时延，认为 EP=16 跨两节点仍可满足解码 SLO，理由是 E 增大使每设备份额 (1-1/16) 下降、聚合带宽上升。实际部署后出现两个问题叠加：其一，路由倾斜使少数专家所在设备的入向链路饱和，最慢链路字节数远超均值；其二，跨节点段走 IB，带宽远低于 NVLink，且每跳固定时延不可忽略。两者共同作用，使实际每层 All-to-All 时延远高于按均匀下界加 NVLink 带宽算出的估计，解码吞吐被通信钉住，SLO 违约。</p>\n<p>这个反例的教训不是“下界错了”，而是“下界的前提没有被检查”。正确的做法是：先用按目的设备的字节直方图确认倾斜因子，若显著大于 1 则改用最慢链路字节数；再确认 EP 域是否跨节点，若是则把 <span>BW_link</span> 换成 IB 有效带宽并加上 <span>η_hop·#hops</span>；最后判断该时延是否被 dispatch 与计算的重叠掩盖。三者任一不满足，均匀下界就不能作为容量规划的依据。工程上更稳妥的判据是：把下界当作乐观极限而非预测值，容量决策取最慢链路估算与重叠掩盖后的有效时延两者中的较大者。</p>\n\n<h3 id=\"th-alltoall-lower-bound-sec-32\">三十二 · 识别清单与工程落点</h3>\n<p>把上述误用收敛成可执行的检查项，能在部署前拦住大部分失真。检查项应覆盖路由分布、拓扑边界与重叠能力三个维度，每一项都对应公式中的一个假设或变量。</p>\n<ul>\n<li>路由倾斜：采样每层 dispatch 的按目的设备字节直方图，比较最大值与均值；倾斜因子显著大于 1 时，下界失效，改用最慢链路字节数除以该链路带宽。</li>\n<li>拓扑边界：确认 EP 域是否跨出 NVLink 域；跨域时 cross-node 指示项为 1，<span>BW_link</span> 必须替换为 IB/RoCE 有效带宽，并显式计入 <span>η_hop·#hops</span>。</li>\n<li>重叠能力：确认 dispatch 是否与专家计算融合重叠；若重叠充分，通信可被掩盖，下界不再是端到端瓶颈，此时容量规划应以计算或显存为约束，而非通信。</li>\n<li>E 的耦合：增大 E 前先判断是否跨域；域内增大 E 摊薄有效，跨域增大 E 需重算远端份额与跳数代价。</li>\n</ul>\n<p>工程落点上，最容易被忽视的是“下界的适用边界”与“实际瓶颈”之间的错位：均匀路由下界描述的是聚合字节数的乐观极限，而真实系统由最慢链路、跨域带宽与跳数共同决定。把这三者写进容量规划的输入，而不是把下界当作预测值，才能避免反例中的系统性偏乐观。具体到部署动作，EP 拓扑选择应优先在 NVLink 域内提升并行度，跨域扩展必须以最慢链路时延与跳数代价为约束重新核算，而不是沿用域内推导出的摊薄结论。</p>\n\n\n<h3 id=\"th-alltoall-lower-bound-sec-33\">三十三 · 当“下界”被当成“预算”：三类误用与一个反例</h3>\n<p>最常见的误用是把均匀路由下界直接当成容量规划的输入。公式里的 <span class=\"formula\">$$V_{\\text{a2a}}=2\\,T\\,d\\,b_{a}\\,\\bar{k}\\cdot\\mathbb{1}[\\text{cross-node}]$$</span> 中，<span class=\"formula\">$$\\bar{k}$$</span> 取的是平均每 token 跨设备专家数，它隐含了路由均匀的前提；一旦门控网络在训练或微调后出现专家倾斜（少数专家吸走大部分 token），实际字节量并不高于下界，但流量在时间与链路上高度集中，最慢那条链路的瞬时负载远超均值。此时端到端时延由 <span class=\"formula\">$$T_{\\text{comm}}\\ge\\frac{V_{\\text{a2a}}}{\\mathrm{BW}_{\\text{link}}}+\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span> 中的 BW_link 项决定，而这一项的分母是“最慢链路有效带宽”，不是平均带宽。用平均值代入做 EP 度选型，得到的每层时延估计会系统性偏乐观，解码阶段每 token 都要付一次这个误差，累积到 TPOT 上就是 SLO 违约。识别方法很直接：在真实路由分布下采样每张卡、每条 NVLink/IB 链路的发送字节直方图，若 P99 与均值的比值明显偏离 1，就说明下界已不代表实际时延，容量规划必须改用倾斜路由下的最慢链路模型。</p>\n<p>第二类误用是跨节点 EP 仍沿用 NVLink 带宽。公式中 cross-node 指示项一旦为 1，BW_link 必须替换为 InfiniBand/RoCE 的有效带宽，并补上 <span class=\"formula\">$$\\eta_{\\text{hop}}\\cdot\\#\\text{hops}$$</span> 的固定跳数代价。工程上常见的错误是把 NVLink 域内的实测带宽直接填进跨节点场景，忽略了两点：一是 IB 带宽远低于 NVLink，二是多跳拓扑（leaf-spine 层级）带来的每跳固定时延在 decode 的小 batch 下不可忽略——此时单次 All-to-All 的字节量不大，η_hop×hops 反而成为主导项。后果是通信时延被严重低估，分离式预填/解码部署中解码池的 EP 度被开得过大，跨节点流量上升而单 token 时延不降反升。识别信号是：把 EP 度从 NVLink 域内推到跨节点后，实测 All-to-All 时间不随 E 增大而下降，或下降斜率明显低于 1/E 预期，说明带宽项已被拓扑项接管。</p>\n<p>第三类误用是认为增大 E 总能摊薄通信。在单层 NVLink 全互联、路由均匀的边界内，分子中的非本地比例 (1−1/E) 与分母带宽中的 E 同时变化，通信量随时延一起被摊薄；但跨节点时 E 的增大同时扩大了 hops 与最慢链路数量，两个因子反向耦合，最优点往往落在 NVLink 域边界上而非最大 E。一个具体反例：某 MoE 解码服务在单节点 8 卡 NVLink 域内把 EP 从 8 推到 16（跨两节点），路由分布本身已倾斜，最热专家所在链路的发送字节约为均值的数倍；规划时按均匀下界估算认为时延减半，实测却因跨节点 IB 带宽替换与跳数叠加，单层 All-to-All 时延上升，decode 吞吐下降。这个反例的教训不是“不要跨节点”，而是：下界只在“路由均匀 + 单层 NVLink + 指示项为 0”的边界内可作规划依据；一旦越界，必须同时替换带宽、计入跳数、并用倾斜路由的最慢链路重算，否则公式给的是乐观幻觉而非预算。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>被忽略的项</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>均匀下界做容量规划</td><td>专家倾斜下的最慢链路</td><td>TPOT 超 SLO，解码吞吐低于预期</td><td>链路发送字节 P99/均值显著偏离 1</td></tr><tr><td>跨节点沿用 NVLink 带宽</td><td>IB 带宽替换与 η_hop×hops</td><td>通信时延低估，EP 度选型过大</td><td>E 增大后 All-to-All 时间不降</td></tr><tr><td>认为 E 总能摊薄</td><td>(1−1/E) 与分母带宽、拓扑的耦合</td><td>跨域后时延反升，NVLink 域边界被越过</td><td>跨节点后斜率低于 1/E 预期</td></tr></tbody></table>\n<p>把这三类误用收敛成一条工程判断：下界公式的每一项都对应一个可观测的系统量——T 与 d 由批形状决定，b_a 由精度决定（FP8 为 1，NVFP4 为 0.5），k̄ 必须用实测路由分布而非配置均值，BW_link 必须取当前拓扑下最慢链路的有效带宽，η_hop 与 hops 必须按实际 fabric 层级填写。任何一项用了“设计值”而非“实测值”，下界就会从约束变成幻觉；而识别幻觉的最可靠手段，是在真实路由与真实拓扑下测量最慢链路的单层 All-to-All 时间，与公式预测值做比值——比值显著大于 1 时，先修路由均衡或收敛 EP 拓扑，再谈扩容。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>批内token总数</td></tr><tr><td>d</td><td>隐藏维（dispatch与combine各一次故乘2）</td></tr><tr><td>b_{a}</td><td>激活字节数（FP8为1，NVFP4为0.5）</td></tr><tr><td>\\bar{k}</td><td>平均每token跨设备专家数</td></tr><tr><td>\\mathrm{BW}_{\\text{link}}</td><td>最慢链路有效带宽（跨节点IB/RoCE）</td></tr><tr><td>\\eta_{\\text{hop}}</td><td>每跳固定时延</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-alltoall-lower-bound · 共 5 个片段</p>\n"},{"id":"th-spec-decode-speedup","title":"投机解码加速比界","direction":"dir-disaggregated-pd","prereq":[],"plain":"投机解码的加速比等于每轮被接受token数的期望除以验证与草稿的总代价比；MoE上因验证批可摊薄权重读取，实际加速常高于按稠密模型估计的预测值。","definition":"投机解码的加速比等于每轮被接受token数的期望除以验证与草稿的总代价比；MoE上因验证批可摊薄权重读取，实际加速常高于按稠密模型估计的预测值。","formula":"$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)},\\qquad \\mathbb{E}[\\text{accepted}]=\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$$","variables":[{"sym":"\\alpha","meaning":"单token接受率（草稿与目标分布一致性度量）"},{"sym":"\\gamma","meaning":"每轮草稿token数"},{"sym":"c","meaning":"草稿+验证相对单次解码迭代的代价比"}],"derivation":"分母 $(1-\\alpha)(\\gamma c_d+c_v)$ 的物理含义：$(1-\\alpha)$ 是拒绝概率归一化项，$\\gamma c_d$ 是草稿阶段 $\\gamma$ 次串行前向的相对成本，$c_v$ 是目标模型一次并行验证的相对成本；$c_d,c_v$ 均以目标模型单 token 成本为基准归一化。","example":"适用边界：$\\alpha$ 较高且 $c_d\\ll c_v$ 时 $S$ 随 $\\gamma$ 单调上升；失效条件是 $\\alpha$ 偏低（如 MoE 路由分歧使草稿与目标激活不同专家）时，$\\gamma$ 增大只增加草稿成本而接受数不增，$S$ 反而下降。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["草稿模型与目标模型分布差异大（α低）时，期望接受长度趋近1，加速比趋近1/(1+c)甚至为负","验证阶段批增大后若转为算力受限或KV带宽受限，摊薄收益消失，c不再是常数"],"system_note":"用途：在容量决策中，用实测 $\\alpha$、$c_d$、$c_v$ 反解最优草稿长度 $\\gamma^\\ast$，并据此估算单卡可承载的并发请求数与 SLO 余量；$\\alpha$ 随 MoE 专家路由分布漂移时需按模型/负载分桶标定。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：投机解码每轮先由草稿模型连续生成 $\\gamma$ 个候选 token，再由目标模型一次前向并行验证，加速比取决于这 $\\gamma+1$ 个位置中被接受多少，以及验证相对草稿的算力开销。","公式分子 $1-(1-\\alpha)^{\\gamma+1}$ 是长度为 $\\gamma+1$ 的候选序列中至少接受一个 token 的概率，等价于每轮被接受 token 的期望数；$\\alpha$ 为单 token 接受率，$\\gamma$ 为草稿步数，二者共同决定收益上限。","分母 $(1-\\alpha)(\\gamma c_d+c_v)$ 的物理含义：$(1-\\alpha)$ 是拒绝概率归一化项，$\\gamma c_d$ 是草稿阶段 $\\gamma$ 次串行前向的相对成本，$c_v$ 是目标模型一次并行验证的相对成本；$c_d,c_v$ 均以目标模型单 token 成本为基准归一化。","推导关键一步：把每轮视为几何分布式的接受过程，接受 token 数的期望为 $\\sum_{k=1}^{\\gamma+1}P(\\text{接受}\\ge k)=\\frac{1-(1-\\alpha)^{\\gamma+1}}{1-(1-\\alpha)}$，再除以每轮归一化时间 $\\gamma c_d+c_v$ 得到加速比 $S$。","适用边界：$\\alpha$ 较高且 $c_d\\ll c_v$ 时 $S$ 随 $\\gamma$ 单调上升；失效条件是 $\\alpha$ 偏低（如 MoE 路由分歧使草稿与目标激活不同专家）时，$\\gamma$ 增大只增加草稿成本而接受数不增，$S$ 反而下降。","用途：在容量决策中，用实测 $\\alpha$、$c_d$、$c_v$ 反解最优草稿长度 $\\gamma^\\ast$，并据此估算单卡可承载的并发请求数与 SLO 余量；$\\alpha$ 随 MoE 专家路由分布漂移时需按模型/负载分桶标定。","常见误用：把 $c_v$ 当作固定常数。验证阶段若批内序列长度差异大，目标模型前向被最长序列拖长，$c_v$ 随批膨胀，公式会系统性低估验证成本、高估加速比。"],"anchors":[],"pitfalls":["在 MoE 模型上直接用稠密模型的 $\\alpha$ 标定值，忽略路由分歧导致的接受率下降，按公式选出的 $\\gamma$ 偏大，实际吞吐不升反降。","把 $c_v$ 固定为单序列验证成本，忽略变长批导致的验证膨胀，容量规划按公式上限配置并发，线上出现 SLO 违约。","只优化 $\\alpha$ 而不约束草稿模型与目标模型的专家亲和性，草稿命中率虚高但验证阶段频繁拒绝，浪费草稿算力。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-1\">一 · 一句话直觉与它为什么成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-2\">二 · 严格定义：把“加速比”钉在哪个基准上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-3\">三 · 为什么需要这个界：它挡住的是“凭感觉调参”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-4\">四 · 常见误解：四个必须拆掉的直觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-5\">五 · 界的形状：从 $\\alpha$ 与 $c$ 读出可决策结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-6\">六 · 边界不在 α 高低，而在 c 是否还是常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-7\">七 · 分子：期望接受长度如何从几何过程长出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-8\">八 · 分母：$c_d$、$c_v$ 的归一化基准与串并行结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-9\">九 · 最优 $\\gamma^\\ast$：对离散变量求极值的实操</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-10\">十 · 失效边界的定量刻画：$\\alpha\\to$ 低时加速比趋近 $1/(1+c)$</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-11\">十一 · 公式在容量决策中的用法与不可让渡的实测项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-12\">十二 · 分母不是常数：验证膨胀与路由漂移如何吃掉加速比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-13\">十三 · α 的分布依赖：为什么标定值会漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-14\">十四 · c 不是常数：验证批膨胀与资源受限切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-15\">十五 · 分布差异导致的负加速区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-16\">十六 · 规模上限：γ 与并发的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-17\">十七 · 变长批与验证膨胀的耦合失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-18\">十八 · 边界在哪里：α、γ、c 三变量的失效地形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-19\">十九 · 边界不在公式里，在批的形状里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-20\">二十 · 把加速比公式变成容量约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-21\">二十一 · 定批大小：解 \\(\\gamma^\\ast\\) 与 \\(B^\\ast\\) 的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-22\">二十二 · 定并行度：把 \\(\\mathrm{SU}\\) 折进 TP/EP 的收益账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-23\">二十三 · 定 KV 预算：\\(\\gamma\\) 与 \\(B\\) 共同决定驻留量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-24\">二十四 · 定 SLO：尾延迟而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-25\">二十五 · 把加速比公式放进容量账本：γ*、并发与 SLO 余量的反解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-26\">二十六 · 把 α 当成模型常量：MoE 路由分歧下的系统性高估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-27\">二十七 · 把 $c_v$ 钉死为单序列成本：变长批下的验证膨胀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-28\">二十八 · 只优化 α 不管专家亲和性：虚高的命中率与真实的拒绝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-29\">二十九 · 一个反例：按公式上限配置并发的 MoE 服务</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-30\">三十 · 误用的共同结构：把负载相关量当模型常量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-31\">三十一 · 误用与反例：把公式当承诺而不是当仪表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-spec-decode-speedup-sec-32\">三十二 · 误用与反例：把 c_v 当常数、把稠密 α 搬到 MoE 上</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:585px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 585.4 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"503.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"503.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：投机解码的加速比等于每轮被接受token数的期望除以验证与草稿的总…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"503.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\t…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"503.4\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：草稿模型与目标模型分布差异大（α低）时，期望接受长度趋近1，加速比…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-spec-decode-speedup-sec-1\">一 · 一句话直觉与它为什么成立</h3>\n<p>投机解码的加速比，一句话：<strong>每轮被接受 token 数的期望，除以验证与草稿相对单次解码迭代的总代价比</strong>。这句话把两件事钉在一起——分子是“这一轮赚到多少”，分母是“这一轮花了多少”。赚的部分来自草稿模型连续吐出 $\\gamma$ 个候选、目标模型一次前向并行验证；花的部​​分来自草稿的 $\\gamma$ 次串行前向加上目标模型的一次并行验证。两者相除，才是可落地的加速比，而不是“草稿命中率”这种单边指标。</p>\n<p>为什么分子必须是期望而不是命中率？因为一轮里被接受的 token 数不是 0/1 变量：可能接受 1 个、2 个，直到 $\\gamma+1$ 个全部通过。把每轮看作一个几何式的接受过程，接受数 $K$ 满足 $P(K\\ge k)=(1-\\alpha)^{k-1}$（$\\alpha$ 为单 token 接受率），于是</p>\n<div class=\"formula\">$$\\mathbb{E}[K]=\\sum_{k=1}^{\\gamma+1}P(K\\ge k)=\\frac{1-(1-\\alpha)^{\\gamma+1}}{\\alpha}$$</div>\n<p>这正是给定事实里分子 $1-(1-\\alpha)^{\\gamma+1}$ 除以 $\\alpha$ 的来源；写成 $\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$ 是同一式子的等价变形。注意一个容易读错的点：$1-(1-\\alpha)^{\\gamma+1}$ 本身是“$\\gamma+1$ 个位置中至少接受一个”的概率，它<em>不是</em>期望接受数；期望接受数还要再除以 $\\alpha$。工程上标定 $\\alpha$ 时若把这两个量混用，会把 $\\gamma^\\ast$ 系统性选小。</p>\n<p>代价侧同理不能只看草稿。分母的物理含义是：$(1-\\alpha)$ 是拒绝概率的归一化项，$\\gamma c_d$ 是草稿阶段 $\\gamma$ 次串行前向的相对成本，$c_v$ 是目标模型一次并行验证的相对成本，$c_d,c_v$ 都以目标模型单 token 成本为基准归一化。于是完整形式为</p>\n<div class=\"formula\">$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)},\\qquad \\mathbb{E}[\\text{accepted}]=\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$$</div>\n<p>其中 $c$ 是草稿+验证相对单次解码迭代的代价比。这个式子的价值不在算出一个漂亮数字，而在它把三个可测变量 $\\alpha,\\gamma,c$ 与一个可决策量（是否开投机、开多长）连成一条可反解的链：容量规划时用实测 $\\alpha,c_d,c_v$ 反解 $\\gamma^\\ast$，再折算单卡可承载的并发请求数与 SLO 余量。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-2\">二 · 严格定义：把“加速比”钉在哪个基准上</h3>\n<p>严格定义的第一件事是选基准。投机解码的加速比必须以“同一目标模型、同一批调度策略、不开投机时的解码迭代”为分母基准，否则数字不可比。设单次解码迭代（一个 token、一个 batch）的归一化时间为 1，则一轮投机的时间为 $\\gamma c_d+c_v$，产出 $\\mathbb{E}[K]+1$ 个被目标模型确认的 token（$+1$ 来自验证后被接受的那一个额外位置，具体计数口径随实现而定，但必须与分子口径一致）。加速比即</p>\n<div class=\"formula\">$$S=\\frac{\\mathbb{E}[K]+1}{\\gamma c_d+c_v}=\\frac{1-(1-\\alpha)^{\\gamma+1}}{\\alpha\\,(\\gamma c_d+c_v)}$$</div>\n<p>这个定义暴露了三处工程上必须固定的口径。其一，$\\alpha$ 是<strong>单 token 接受率</strong>，是草稿分布与目标分布一致性的度量，不是“整轮通过率”；整轮全接受概率是 $\\alpha^{\\gamma+1}$，两者差一个量级。其二，$c_d$ 与 $c_v$ 是<strong>相对成本</strong>，不是绝对毫秒数——草稿模型若比目标模型小一个数量级，$c_d$ 可以远小于 1，但它在 MoE 上未必小，因为草稿也要读专家权重。其三，分母里的 $\\gamma c_d$ 是串行的：草稿每步都要等上一步输出，这 $\\gamma$ 步无法并行摊薄，这是投机解码在延迟上的固有税。</p>\n<p>定义的第二层是适用域。给定事实给出的边界很硬：$\\alpha$ 较高且 $c_d\\ll c_v$ 时 $S$ 随 $\\gamma$ 单调上升；一旦 $\\alpha$ 偏低，$\\gamma$ 增大只增加草稿成本而接受数不增，$S$ 反而下降。把 $\\gamma$ 当成“越大越好”的旋钮是定义层面的错误——$\\gamma$ 是分子分母同时出现的变量，最优点由 $\\partial S/\\partial\\gamma=0$ 决定，而这个驻点是否存在，取决于 $\\alpha$ 与 $c_d/c_v$ 的组合。</p>\n<p>代价上要盯住一个具体量：草稿阶段的串行前向是<strong>延迟项</strong>，验证阶段的一次前向是<strong>吞吐项</strong>。以 B200 单卡跑一个中等规模 MoE 目标模型为例，验证一次前向要把 $\\gamma+1$ 个位置的激活一起送进专家层，权重读取被这批位置摊薄，所以 $c_v$ 并不随 $\\gamma$ 线性增长；但草稿的 $\\gamma$ 次前向每次都完整读一遍草稿权重，显存带宽开销按 $\\gamma$ 线性累加。这就是为什么 $c_d$ 在 MoE 上不能按稠密模型的参数量比例去估。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-3\">三 · 为什么需要这个界：它挡住的是“凭感觉调参”</h3>\n<p>需要这个界，是因为投机解码的三个参数（开不开、草稿多长、草稿模型选谁）在线上是耦合的，而工程团队最常用的替代品是“先开 4 步试试”。这个界的作用是把试错变成反解：给定实测 $\\alpha$ 与 $c_d,c_v$，$\\gamma^\\ast$ 是可算的；给定 SLO 余量，能承载的并发数是可算的。没有这个界，容量规划只能按“命中率高的配置”拍脑袋配并发，而命中率高不等于加速比高——分子涨、分母也涨的配置比比皆是。</p>\n<p>第二个必要性来自失效条件的可识别性。给定事实点明：$\\alpha$ 低时期望接受长度趋近 1，加速比趋近 $1/(1+c)$ 甚至为负。这句话的工程含义是，投机解码在低 $\\alpha$ 下不是“收益小”，而是<strong>可能净亏</strong>：草稿算力白烧，验证还要多付一次前向。界的存在让团队能在上线前用一小批真实流量标定 $\\alpha$，而不是等线上吞吐掉下去再回滚。</p>\n<p>第三个必要性在 MoE 上尤其尖锐。给定事实明确：MoE 上因验证批可摊薄权重读取，实际加速常高于按稠密模型估计的预测值；但反过来的失败模式是，直接用稠密模型的 $\\alpha$ 标定值，忽略路由分歧导致的接受率下降，按公式选出的 $\\gamma$ 偏大，实际吞吐不升反降。也就是说，这个界在 MoE 上是<strong>双向</strong>的：摊薄效应让 $c_v$ 比稠密估计更小、加速比更高；路由分歧让 $\\alpha$ 比稠密估计更低、加速比更小。两个偏差方向相反，谁也不能靠“经验系数”糊过去，必须按模型/负载分桶标定 $\\alpha$。</p>\n<p>代价侧的具体例子：一个 MoE 目标模型在 decode 阶段是权重带宽受限的，单 token 解码的瓶颈在读专家权重；验证 $\\gamma+1$ 个位置时，同一批专家权重被多次复用，$c_v$ 的相对成本被摊薄。若草稿模型与目标模型共享专家亲和性（草稿命中的专家与目标将要激活的专家高度重叠），$\\alpha$ 保持高位，$S$ 上升；若路由分歧大，草稿命中的专家在验证时被大量拒绝，$\\gamma$ 越大浪费的草稿带宽越多，此时增大 $\\gamma$ 是在给显存带宽交税。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-4\">四 · 常见误解：四个必须拆掉的直觉</h3>\n<p><strong>误解一：把 $c_v$ 当固定常数。</strong>给定事实直接点名这是常见误用：验证阶段若批内序列长度差异大，目标模型前向被最长序列拖长，$c_v$ 随批膨胀，公式会系统性低估验证成本、高估加速比。机制上，连续批处理下验证批里混着长短不一的序列，kernel 的尾效应由最长序列决定，$\\gamma+1$ 个位置的验证不再是“一次干净的前向”。工程后果是容量规划按公式上限配并发，线上出现 SLO 违约。</p>\n<p><strong>误解二：把 $\\alpha$ 当模型固有属性。</strong>$\\alpha$ 是草稿与目标<em>分布</em>的一致性度量，随负载漂移。给定事实要求：$\\alpha$ 随 MoE 专家路由分布漂移时需按模型/负载分桶标定。同一个草稿模型，在短 prompt、长 prompt、代码、多语言上的 $\\alpha$ 不同；用一个全局 $\\alpha$ 反解出的 $\\gamma^\\ast$ 只对那个桶成立。</p>\n<p><strong>误解三：只优化 $\\alpha$ 不管专家亲和性。</strong>给定事实列为失败模式：草稿命中率虚高但验证阶段频繁拒绝，浪费草稿算力。这里的陷阱在于“命中率”口径——草稿自己觉得自信的 token，在目标模型验证时被拒，说明 $\\alpha$ 的测量若只看草稿侧置信度就会虚高。必须用目标模型的实际接受结果标定。</p>\n<p><strong>误解四：以为 $\\gamma$ 越大加速越多。</strong>由 $S$ 的表达式，$\\gamma$ 在分子里以 $1-(1-\\alpha)^{\\gamma+1}$ 饱和增长，在分母里以 $\\gamma c_d$ 线性增长。$\\alpha$ 高时分子先饱和得慢、分母增长被 $c_d\\ll c_v$ 压住，$S$ 单调升；$\\alpha$ 低时分子几乎不动、分母照涨，$S$ 掉头向下。这不是“调参技巧”，是定义决定的形状。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>机制根源</th><th>系统代价</th></tr></thead><tbody><tr><td>$c_v$ 视为常数</td><td>变长批尾效应拖长验证前向</td><td>低估验证成本，高估加速比，SLO 违约</td></tr><tr><td>$\\alpha$ 视为模型固有</td><td>MoE 路由分布随负载漂移</td><td>$\\gamma^\\ast$ 选错，吞吐不升反降</td></tr><tr><td>只看草稿置信度</td><td>草稿自信≠目标接受</td><td>草稿算力与显存带宽白烧</td></tr><tr><td>$\\gamma$ 越大越好</td><td>分子饱和、分母线性</td><td>低 $\\alpha$ 下加速比为负</td></tr></tbody></table>\n\n<h3 id=\"th-spec-decode-speedup-sec-5\">五 · 界的形状：从 $\\alpha$ 与 $c$ 读出可决策结论</h3>\n<p>把 $S(\\gamma)$ 的形状讲清楚，比记公式有用。分子 $1-(1-\\alpha)^{\\gamma+1}$ 随 $\\gamma$ 的增量是 $(1-\\alpha)^{\\gamma+1}\\alpha$，按几何衰减；分母的增量是常数 $c_d$。于是最优 $\\gamma^\\ast$ 的驻点条件近似为“边际接受概率等于边际草稿成本”，即 $(1-\\alpha)^{\\gamma^\\ast}\\alpha\\approx c_d$ 量级上的平衡。$\\alpha$ 越接近 1，$(1-\\alpha)^{\\gamma}$ 衰减越慢，$\\gamma^\\ast$ 越大；$\\alpha$ 越低，驻点越早出现，甚至不存在（$S$ 从 $\\gamma=1$ 就单调降）。这给出一条无需精算的工程判断：先测 $\\alpha$，若 $\\alpha$ 明显偏低，不要急着加 $\\gamma$，先换草稿模型或改草稿策略。</p>\n<p>另一个可决策结论在 $c$ 上。给定事实的失效条件写明：验证阶段批增大后若转为算力受限或 KV 带宽受限，摊薄收益消失，$c$ 不再是常数。这意味着 $c$ 是<strong>批规模的函数</strong>，不是配置常量。容量规划时若按小批实测的 $c$ 去推大批的加速比，会在高并发区间高估收益——因为大批下验证从带宽受限翻到算力受限，$c_v$ 的相对成本抬升，$S$ 被压回去。工程上应把 $c$ 标定成“批规模 × 序列长度分布”的二维表，而不是一个标量。</p>\n<p>具体例子：一个在线服务在低并发时测得 $\\alpha$ 较高、$c_d$ 很小，按公式选出较大的 $\\gamma^\\ast$，单请求延迟明显下降；当并发爬升、验证批变大后，目标模型前向转为算力受限，$c_v$ 抬升，同一 $\\gamma^\\ast$ 下 $S$ 回落，尾延迟恶化。此时正确动作不是调 $\\gamma$，而是按批规模分桶重标 $c$，并在高并发桶里收缩 $\\gamma$、把省下的算力让给验证批的摊薄。这个判断只能从“$c$ 不是常数”这条定义推出来，靠“加速比看起来还行”是推不出来的。</p>\n<p>最后落在机制上：这个界的可用性取决于三个量的标定质量——$\\alpha$ 要按负载分桶、$c_d$ 要按草稿模型在目标硬件上的实际带宽开销测、$c_v$ 要按批规模与序列长度分布测。三者任一被当成常数，界就从“可反解的决策工具”退化成“事后解释数字的装饰”。下一部分要处理的，正是这三者在真实硬件与真实批形态下如何被测出来。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-6\">六 · 边界不在 α 高低，而在 c 是否还是常数</h3>\n<p>把加速比写成 $\\mathrm{SU}=\\mathbb{E}[\\text{accepted}+1]/\\bigl(1+c(1-\\alpha^{\\gamma+1})/(1-\\alpha)\\bigr)$ 之后，最常见的误读是把它当成“α 越高越好、γ 越大越好”的单调调参表。真正的失效面在分母：$c$ 被定义为一个常数，即草稿加验证相对单次解码迭代的代价比；一旦验证批被拉长到目标模型转为算力受限或 KV 带宽受限，$c$ 就随批规模漂移，公式从“预测器”退化为“上界估计器”。此时即便 α 不低，摊薄权重读取的收益也会被验证前向的膨胀吃掉——MoE 上尤其如此，验证批能摊薄专家权重读取，使实测加速常高于按稠密模型外推的预测值，但这份红利只在 $c$ 稳定时兑现。</p>\n<p>第二个失效条件是分布分歧本身。当草稿与目标在 MoE 路由上落到不同专家，α 下降，$\\mathbb{E}[\\text{accepted}]=\\alpha(1-\\alpha^{\\gamma})/(1-\\alpha)$ 迅速趋近 0，期望接受长度塌到 1，加速比趋近 $1/(1+c)$，草稿算力纯属浪费；若草稿成本 $c_d$ 不小，甚至为负。工程上更隐蔽的一种是“α 虚高”：只优化单 token 命中率而不约束草稿与目标的专家亲和性，离线标定的 α 好看，线上验证阶段频繁拒绝，草稿阶段 $\\gamma c_d$ 照付。</p>\n<p>因此容量决策不能拿公式上限配并发。正确做法是按模型与负载分桶实测 α、$c_d$、$c_v$，反解 $\\gamma^\\ast$，并对 $c_v$ 做变长批敏感性检查：批内序列长度差异大时，目标前向被最长序列拖长，$c_v$ 随批膨胀，公式系统性低估验证成本、高估加速比，按此配置的并发会在线上直接表现为 SLO 违约。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>α</th><th>c 行为</th><th>加速比走向</th></tr></thead><tbody><tr><td>稠密、分布一致</td><td>高</td><td>近似常数</td><td>随 γ 单调上升</td></tr><tr><td>MoE 路由分歧</td><td>低</td><td>草稿成本照付</td><td>趋近 1/(1+c)，可为负</td></tr><tr><td>变长批验证</td><td>中高</td><td>随批膨胀</td><td>实测低于公式预测</td></tr></tbody></table>\n<h3 id=\"th-spec-decode-speedup-sec-7\">七 · 分子：期望接受长度如何从几何过程长出来</h3>\n<p>分子 $\\mathbb{E}[\\text{accepted}+1]$ 不是“平均接受率乘 $\\gamma$”这种线性直觉的产物，而是对一条长度 $\\gamma+1$ 的候选链做几何求和的结果。把每个位置看成一次独立的伯努利试验，接受概率 $\\alpha$，则“至少接受 $k$ 个”这一事件等价于前 $k$ 个位置全部命中，概率为 $\\alpha^{k}$。于是期望接受数可以写成尾和形式：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{accepted}]=\\sum_{k=1}^{\\gamma+1}P(\\text{接受}\\ge k)=\\sum_{k=1}^{\\gamma+1}\\alpha^{k}=\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$$</div>\n<p>这里的关键推导步是“尾和换序”：不去逐项算“恰好接受 $k$ 个”的概率（那需要二项分布加截断，形式复杂），而是把期望拆成“至少 $k$ 个”的概率之和。这一步之所以成立，是因为接受过程在拒绝处截断——一旦某个位置被拒，后续草稿 token 全部作废，链就终止。因此“接受数 ≥ k”与“前 k 个全中”严格等价，不需要考虑第 $k+1$ 位之后的状态。分子里的 $+1$ 来自目标模型在验证时额外产出的那一个 token（被接受序列之后的修正位），它恒计入每轮产出，与 $\\alpha$ 无关。</p>\n<p>离散化与近似发生在两处。第一处是把连续的自回归生成离散成 $\\gamma+1$ 个位置的独立判定，这要求草稿模型每一步的采样与目标模型的验证判定在统计上可分离——工程上通过固定采样温度、禁用动态 top-p 漂移来维持。第二处是 $\\alpha$ 被当作单值常数，而真实系统里 $\\alpha$ 随位置衰减：靠前的草稿 token 因为上下文更确定而更易被接受，靠后的 token 因为草稿模型自身误差累积而接受率下降。用单一 $\\alpha$ 代入上式，等价于用几何分布去拟合一条实际衰减更快的曲线，会在 $\\gamma$ 较大时高估分子。工程判断是：$\\gamma$ 超过 4–6 后必须按位置分桶标定 $\\alpha_i$，用 $\\prod_{i\\le k}\\alpha_i$ 替代 $\\alpha^k$，否则分子虚高会直接传导到 $\\gamma^\\ast$ 的选择上。</p>\n<p>代价侧要盯住的是：分子每增加一个被接受 token，就省下一次目标模型前向的权重读取。以 B200 单卡跑稠密 70B 级模型为例，解码阶段每 token 的权重读取量是显存带宽的函数，接受长度从 1 提到 3 意味着同样的权重读取摊到三倍 token 上，这是加速比的物理来源。但分子只描述“省了多少次前向”，不描述“验证那一次前向有多贵”，后者全部压在分母里。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-8\">八 · 分母：$c_d$、$c_v$ 的归一化基准与串并行结构</h3>\n<p>分母 $1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)$ 是给定事实里公式的紧凑写法，展开后是 $(1-\\alpha)(\\gamma c_d+c_v)$ 再归一化。逐项看：$\\gamma c_d$ 是草稿阶段 $\\gamma$ 次<strong>串行</strong>前向的相对成本——串行意味着这 $\\gamma$ 步无法并行，每一步都要等上一步采样出 token 才能喂进下一步，延迟是线性叠加的；$c_v$ 是目标模型一次<strong>并行</strong>验证的相对成本，$\\gamma+1$ 个位置在同一次前向里算完，算力开销接近一次普通解码迭代但略高（序列变长、注意力模式变化）。两者都以“目标模型单 token 解码成本”为基准归一化，所以 $c_d&lt;1$ 是草稿模型更小的自然结果，$c_v\\approx 1$ 是验证与解码同量级的自然结果。</p>\n<p>$(1-\\alpha)$ 出现在分母里是归一化项而非物理成本，它的作用是让“每轮期望产出”与“每轮期望成本”在同一概率测度下相除。推导上，每轮以概率 $\\alpha$ 继续、以概率 $1-\\alpha$ 终止，终止轮次服从几何分布，期望轮内产出要除以终止概率才能得到无偏的每 token 成本。这一步是把“每轮”换算成“每 token”的关键，漏掉它会把加速比算成每轮口径而非每 token 口径，量纲直接错掉。</p>\n<p>离散化近似在分母侧更隐蔽：$c_v$ 被当成与批无关的常数，但验证阶段一旦批内序列长度参差，目标模型前向被最长序列拖长，$c_v$ 随批膨胀。这是公式系统性高估加速比的主要通道——容量规划若按 $c_v$ 为常数的公式上限配并发，线上会出现验证阶段实际耗时超过预算、SLO 违约。工程上应把 $c_v$ 写成 $c_v(\\text{batch},\\text{seqlen spread})$ 的实测曲面，而不是一个标量。另一个近似是 $c_d$ 与 $\\gamma$ 解耦：草稿模型连续生成 $\\gamma$ 步时 KV cache 逐 step 增长，第 $\\gamma$ 步的注意力读取比第 1 步贵，$\\gamma c_d$ 线性叠加低估了后段成本，$\\gamma$ 大时需按步分段计费。</p>\n<p>具体例子：MoE 目标模型上，验证批增大后权重读取被摊薄，$c_v$ 的有效值反而下降——这正是给定事实里“MoE 上实际加速常高于稠密估计”的机制来源。但同一现象的反面是：若验证批大到转为算力受限或 KV 带宽受限，摊薄收益消失，$c_v$ 重新抬升，$c$ 不再是常数。分母的这一非线性拐点，是公式在容量决策中最容易踩空的地方。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-9\">九 · 最优 $\\gamma^\\ast$：对离散变量求极值的实操</h3>\n<p>$\\gamma$ 是整数，不能直接求导置零，实操是对 $\\gamma=1,2,\\dots$ 逐点算 $S(\\gamma)$ 取最大。但可以先用连续松弛看趋势：$\\alpha$ 高、$c_d\\ll c_v$ 时 $S$ 随 $\\gamma$ 单调上升，因为分子按 $1-\\alpha^{\\gamma+1}$ 快速饱和而分母的 $\\gamma c_d$ 增长慢；$\\alpha$ 偏低时分子饱和极快（$\\alpha^{\\gamma+1}$ 几乎不降），分母却随 $\\gamma$ 线性涨，$S$ 在很小的 $\\gamma$ 处就掉头向下。极值点的判据是边际收益等于边际成本：</p>\n<div class=\"formula\">$$\\Delta S&gt;0\\iff \\alpha^{\\gamma+1}\\cdot\\frac{1}{1-\\alpha}&gt;\\frac{c_d}{c_v}\\cdot\\frac{1}{1-\\alpha^{\\gamma+1}}\\ \\text{（近似口径）}$$</div>\n<p>定性读法：左边是“再多一个草稿位还能带来多少额外接受概率”，随 $\\gamma$ 指数衰减；右边是“多一步草稿的相对成本占比”，随 $\\gamma$ 缓慢变化。交点即 $\\gamma^\\ast$。这个判据的工程价值在于它把 $\\gamma^\\ast$ 的选择拆成两个可测量：$\\alpha$ 决定左边衰减速度，$c_d/c_v$ 决定右边水位。草稿模型越小，$c_d/c_v$ 越低，$\\gamma^\\ast$ 越靠后；$\\alpha$ 越低，左边塌得越快，$\\gamma^\\ast$ 越靠前。</p>\n<p>代价侧：$\\gamma^\\ast$ 偏大是 MoE 上最典型的失败模式。给定事实明确指出，直接用稠密模型的 $\\alpha$ 标定值、忽略路由分歧导致的接受率下降，按公式选出的 $\\gamma$ 偏大，实际吞吐不升反降。机制是草稿模型与目标模型的专家激活不一致——草稿命中的 token 在目标模型验证时落到不同专家，判定被拒，草稿算力白烧。因此 $\\gamma^\\ast$ 必须按模型/负载分桶标定，$\\alpha$ 随专家路由分布漂移时重新解一次。容量决策里，用实测 $\\alpha$、$c_d$、$c_v$ 反解 $\\gamma^\\ast$ 后，再据此估算单卡可承载并发与 SLO 余量，而不是拿公式上限直接配。</p>\n<p>另一个离散化陷阱：$\\gamma$ 增大时验证序列变长，$c_v$ 本身随 $\\gamma$ 微增（注意力长度、KV 读取），连续松弛里把 $c_v$ 当常数会让 $\\gamma^\\ast$ 系统性偏大。工程做法是把 $c_v(\\gamma)$ 实测成表，逐点代入求 $\\gamma^\\ast$，而不是解析求解。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-10\">十 · 失效边界的定量刻画：$\\alpha\\to$ 低时加速比趋近 $1/(1+c)$</h3>\n<p>给定事实给出失效条件：$\\alpha$ 低时期望接受长度趋近 1，加速比趋近 $1/(1+c)$ 甚至为负。把 $\\alpha\\to 0$ 代入分子，$\\mathbb{E}[\\text{accepted}+1]\\to 1$；分母的 $(1-\\alpha^{\\gamma+1})/(1-\\alpha)\\to 1$，于是 $S\\to 1/(1+c)$。$c$ 是草稿加验证相对单次解码的代价比，$c&gt;0$ 时 $S&lt;1$——投机解码不但不加速，反而因为多跑了草稿和验证两次前向而变慢。这就是“负加速”的定量来源，不是定性吓唬。</p>\n<p>更细的边界在 $\\alpha$ 中等区间：分子饱和于 $1/(1-\\alpha)$ 量级，分母的 $\\gamma c_d$ 项开始主导，$S$ 对 $\\gamma$ 的偏导转负。此时增大 $\\gamma$ 只增加草稿成本而接受数不增，是给定事实点名的失效形态。工程判断是设一个 $\\alpha$ 下限闸门：实测 $\\alpha$ 低于阈值时强制 $\\gamma=1$ 或直接关闭投机，把算力还给正常解码。阈值由 $c_d/c_v$ 反解，不是拍脑袋定。</p>\n<p>第二类失效是 $c_v$ 随批膨胀导致的摊薄收益消失。验证阶段批增大后若转为算力受限或 KV 带宽受限，$c$ 不再是常数，公式的线性分母假设破裂。此时公式会系统性低估验证成本、高估加速比，容量规划按公式上限配置并发会在线上出现 SLO 违约。机制上，变长批让目标模型前向被最长序列拖长，$c_v$ 的有效值随批内长度方差上升，而公式里 $c_v$ 是标量。工程上要么按批内长度方差分桶标定 $c_v$，要么在调度层做长度分桶，把方差压下去再套公式。</p>\n<p>具体例子：MoE 路由分歧使草稿与目标激活不同专家，$\\alpha$ 掉到低位，此时 $\\gamma$ 增大只增加草稿成本，$S$ 反而下降——这与稠密模型上“$\\gamma$ 越大越好”的直觉相反。同一模型上，草稿命中率虚高但验证阶段频繁拒绝，是“只优化 $\\alpha$ 而不约束草稿与目标的专家亲和性”的直接后果，浪费的是草稿算力与验证带宽两笔账。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-11\">十一 · 公式在容量决策中的用法与不可让渡的实测项</h3>\n<p>公式的用途不是预测一个漂亮的加速比数字，而是把 $\\alpha$、$c_d$、$c_v$ 三个实测量的误差传导路径看清楚。分子对 $\\alpha$ 的敏感度是 $\\partial S/\\partial\\alpha$ 在 $\\gamma$ 大时被 $\\alpha^{\\gamma}$ 放大，意味着 $\\alpha$ 标定偏差 0.05 在 $\\gamma=6$ 时能让 $\\gamma^\\ast$ 偏移两档；分母对 $c_v$ 的敏感度在批膨胀时被批内长度方差放大。容量规划的正确姿势是：先用小批实测 $\\alpha$ 与 $c_d$，再用目标并发下的实测 $c_v$ 曲面回代，解出 $\\gamma^\\ast$ 与单卡并发上限，最后留 SLO 余量给 $\\alpha$ 漂移。</p>\n<p>不可让渡的实测项有三个：$\\alpha$ 必须按模型/负载分桶（MoE 上还要按专家路由分布分桶），$c_v$ 必须是批与长度方差的函数而非标量，$c_d$ 必须按草稿步分段计费而非线性叠加。三项里任何一项用常数替代，公式的输出就只能当上界看，不能当配置依据。给定事实里的常见误用正是把 $c_v$ 当固定常数——验证阶段批内序列长度差异大时目标模型前向被最长序列拖长，$c_v$ 随批膨胀，公式系统性低估验证成本、高估加速比。</p>\n<p>最后落在工程判断上：这套公式的推导关键步是尾和换序与几何归一化，离散化近似集中在“$\\alpha$ 单值化”“$c_v$ 常数化”“$c_d$ 线性化”三处。三处近似的修正成本远低于它们造成的容量误配成本——一次 SLO 违约的代价通常超过把 $\\gamma^\\ast$ 标定表重做一遍的工程投入。因此在 Blackwell 上做投机解码的容量决策，公式是骨架，实测曲面是血肉，骨架不能替代血肉。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-12\">十二 · 分母不是常数：验证膨胀与路由漂移如何吃掉加速比</h3>\n<p>把公式写成 $\\mathrm{SU}=\\mathbb{E}[\\text{accepted}+1]/\\bigl(1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)\\bigr)$ 之后，工程上真正要盯的不是分子而是 $c$。$c$ 定义为草稿加验证相对单次解码迭代的代价比，它隐含一个前提：验证一次前向的成本与单 token 解码同阶。这个前提在连续批处理下立刻破裂——验证批里各序列的草稿长度 $\\gamma_i$ 不同、已接受前缀不同，目标模型前向被最长序列拖长，$c_v$ 随批宽单调膨胀。此时公式仍按常数 $c$ 计算，会系统性低估验证开销、高估加速比，容量规划据此配置并发就会在线上撞 SLO。</p>\n<p>第二个失效点藏在 $\\alpha$ 的标定口径里。$\\alpha$ 是单 token 接受率，度量草稿与目标分布的一致性；在 MoE 上它不是一个全局常数，而是随专家路由分布漂移的量。草稿模型与目标模型对同一 token 激活不同专家时，接受率骤降，$\\mathbb{E}[\\text{accepted}]=\\alpha(1-\\alpha^{\\gamma})/(1-\\alpha)$ 迅速塌向 1，加速比趋近 $1/(1+c)$，甚至因草稿串行开销为负。若直接沿用稠密模型上标定的 $\\alpha$ 反解 $\\gamma^\\ast$，选出的草稿长度偏大，草稿阶段 $\\gamma c_d$ 线性增长而接受数不增，吞吐不升反降——这是 MoE 投机解码最常见的翻车方式。</p>\n<p>推导中还有一处离散化近似值得点明：把每轮接受过程当作几何分布，用 $\\sum_{k=1}^{\\gamma+1}P(\\text{接受}\\ge k)$ 求期望，等价于假设各位置接受事件独立同分布、且拒绝即整段作废。真实验证是并行逐位置比对，一旦某位置拒绝，其后候选全部丢弃，这个“前缀截断”语义与几何模型吻合；但独立同分布假设在长草稿上偏乐观——后段 token 依赖前段已接受内容，$\\alpha$ 实际随位置衰减。工程上的对策是把 $\\gamma$ 分段标定，按 $\\alpha$ 分桶而非取全局均值。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式表现</th><th>系统代价</th></tr></thead><tbody><tr><td>$\\alpha$ 低（路由分歧）</td><td>分子趋 1，SU→1/(1+c)</td><td>草稿算力白烧，吞吐下降</td></tr><tr><td>变长批验证膨胀</td><td>$c_v$ 被低估</td><td>并发超配，SLO 违约</td></tr><tr><td>$\\gamma$ 过大</td><td>$\\gamma c_d$ 线性涨</td><td>显存与 KV 带宽挤占解码</td></tr></tbody></table>\n<p>因此容量决策的正确姿势是：用实测 $\\alpha$、$c_d$、$c_v$ 反解 $\\gamma^\\ast$，且 $c_v$ 必须按目标批宽实测而非单序列取值；$\\alpha$ 按模型与负载分桶标定，MoE 上还要约束草稿与目标的专家亲和性，避免“命中率虚高、验证频繁拒绝”的假收益。</p>\n<h3 id=\"th-spec-decode-speedup-sec-13\">十三 · α 的分布依赖：为什么标定值会漂移</h3>\n<p>公式里 α 被写成标量，但工程上它从来不是标量。α 是草稿分布与目标分布在具体输入上下文上的重叠度，它随 prompt 领域、语言、生成长度位置、采样温度而变。把 α 当作模型固有常数去反解 γ*，等于假设接受率在整条序列上平稳，而这个假设在真实负载下最先崩。</p>\n<p>机制上，接受判定是逐位置进行的拒绝采样：草稿给出 q(x)，目标给出 p(x)，以 min(1, p/q) 的概率接受。因此 α 的局部值由该位置上 p 与 q 的逐 token 概率质量差决定。序列开头（系统提示、格式模板）往往 α 高，因为模板化文本的下一 token 分布极其尖锐；进入开放式推理或长尾实体名时 α 骤降。于是每轮的期望接受数不是几何分布的平稳采样，而是分段异质的。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{accepted}]=\\sum_{k=1}^{\\gamma+1}\\prod_{j=1}^{k}\\alpha_j,\\qquad \\alpha_j=\\mathbb{E}_{x\\sim p}\\left[\\min\\!\\left(1,\\frac{p(x)}{q(x)}\\right)\\right]$$</div>\n<p>当 α_j 随位置单调下降时，连乘衰减远快于单个 α^γ，公式给出的 γ* 会系统性偏大。系统代价直接体现为草稿算力浪费：草稿阶段 γ 次串行前向是纯延迟开销，若后段位置的接受概率已跌到很低，这部分串行时间无法被验证阶段的并行摊薄回收，端到端 TPOT 反而上升。</p>\n<p>具体例子：同一套目标模型服务代码补全与自由问答两类请求。代码补全的 α 在整段上接近高位，γ 取较大值仍单调增益；自由问答在生成 200 token 后 α 明显下滑，此时若沿用代码负载标定的 γ，草稿阶段每轮多出的串行前向直接吃掉收益。工程判断是按负载分桶标定 α，而不是全局一个数——这与容量规划中按请求类型分桶估并发是同一件事。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-14\">十四 · c 不是常数：验证批膨胀与资源受限切换</h3>\n<p>分母里的 c 被定义为草稿加验证相对单次解码迭代的代价比，但 c 的可加性只在验证阶段仍处于带宽受限区时成立。投机解码的验证是一次前向并行打分 γ+1 个位置，批维度从 1 涨到 γ+1，权重读取被摊薄——这正是它在低批、带宽受限的解码场景里有效的原因。一旦验证批把 kernel 推过 roofline 拐点进入算力受限区，摊薄收益消失，c_v 随批非线性上升。</p>\n<p>机制上，验证前向的算术强度随批增大而上升，但注意力部分的 KV 读取量也随批线性增长。当并发请求叠加投机验证时，实际批是「并发数 × (γ+1)」量级，KV 带宽需求同步放大。此时 c_v 不再是单序列验证成本，而是批内最长序列与批大小的函数。</p>\n<div class=\"formula\">$$c_v^{\\text{eff}}=\\max\\!\\left(c_v^{\\text{bw}},\\;c_v^{\\text{comp}}\\cdot\\frac{B(\\gamma+1)}{B_{\\text{knee}}}\\right)$$</div>\n<p>这个分段式表达的含义是：批小于拐点 B_knee 时验证成本由权重带宽决定、可摊薄；超过拐点后由算力或 KV 带宽决定、随批线性膨胀。系统代价是双重的——既损失了投机带来的延迟收益，又因为验证批占用了本可服务更多并发的算力，吞吐上限被压低。容量规划若按固定 c_v 反解并发数，线上会在高并发段出现 SLO 违约。</p>\n<p>具体例子：在 NVL72 单节点上服务长上下文请求，KV 读取本就吃紧。加入投机后验证批把 KV 带宽需求推高一个量级，c_v 有效值远超标定值，公式预测的加速比与实际观测背离。判断准则很直接：先测验证前向在不同批下的实际耗时曲线，找到拐点，再决定 γ 与并发上限的联合取值，而不是先定 γ 再算并发。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-15\">十五 · 分布差异导致的负加速区</h3>\n<p>失效条件里最硬的一条是 α 低到使期望接受长度趋近 1。此时分子趋近 1，分母趋近 1+c，加速比趋近 1/(1+c) 且小于 1。这不是「收益变小」，而是净亏损：每轮多花了草稿的串行前向与验证的并行前向，却只换来与朴素解码相同的 token 产出。</p>\n<p>机制上，α 低的根因是草稿与目标的分布结构性错位，而非随机噪声。典型来源是 MoE 路由分歧：草稿模型在某层选中不同专家，激活路径分叉，后续层分布随之偏离，逐位置接受概率被系统性压低。此时增大 γ 只增加草稿成本，接受数不增，S 随 γ 单调下降——与「α 高时 S 随 γ 单调上升」正好相反，最优 γ 退化为 0，即关闭投机。</p>\n<ul>\n<li>判据一：实测每轮平均接受长度是否显著大于 1；若接近 1，投机在该负载上不成立。</li>\n<li>判据二：草稿与目标在关键层的路由一致性；不一致率高时，先修亲和性再谈 γ。</li>\n<li>判据三：把 γ 从 1 扫到较大值，观察 S 是否出现下降段；出现即说明已越过该负载的收益上限。</li>\n</ul>\n<p>系统代价是显存与算力的双重占用：草稿模型常驻显存挤占 KV cache 容量，草稿前向占用本可用于验证或并发的 SM 周期。在显存紧张的部署里，一个 α 偏低的投机配置会让可承载并发数下降，吞吐与延迟同时受损。具体例子：MoE 目标模型配稠密草稿模型，路由分歧使 α 偏低，按稠密模型标定的 γ 偏大，实际吞吐不升反降——这正是把 α 从稠密场景直接迁移到 MoE 场景的典型失败。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-16\">十六 · 规模上限：γ 与并发的联合约束</h3>\n<p>公式隐含一个假设：γ 可以独立于并发选择。实际不成立。单卡可承载的并发请求数与 γ 通过验证批耦合：总验证批 ≈ 并发数 × (γ+1)，而 KV cache 容量与验证算力都是硬约束。因此存在一个规模上限，超过它之后增大 γ 或增大并发都会把系统推入算力受限区，公式的线性摊薄假设失效。</p>\n<div class=\"formula\">$$\\text{s.t.}\\quad N_{\\text{req}}\\,(\\gamma+1)\\le B_{\\text{knee}},\\qquad N_{\\text{req}}\\cdot L\\cdot \\text{KV}_{\\text{per-token}}\\le M_{\\text{KV}}$$</div>\n<p>两个约束分别对应算力拐点与显存容量。前者限制验证批的摊薄有效性，后者限制并发上限。γ 增大时第一个约束先被触发，于是最优 γ 随并发上升而下降——这是一个反直觉但可测的结论：高并发段应缩短草稿长度甚至关闭投机，把算力留给批处理吞吐。</p>\n<p>系统代价体现在 SLO 余量上：容量决策若用「单请求最优 γ」乘以「最大并发」估算承载能力，会同时高估加速比与并发上限。正确做法是在 (γ, N_req) 平面上找满足两条约束的可行域，再在可行域内按 SLO 选点。具体例子：分离式部署中预填节点与解码节点资源配比固定，解码节点的 KV 容量决定了 N_req 上限，此时 γ 的自由度被压缩，投机收益主要来自 α 而非 γ。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-17\">十七 · 变长批与验证膨胀的耦合失效</h3>\n<p>连续批处理下批内序列长度差异大，验证前向被最长序列拖长，c_v 随批膨胀。这是公式最常见的误用点：把 c_v 固定为单序列验证成本，忽略变长批的拖尾效应。机制上，验证 kernel 的完成时间由批内最长序列的注意力计算决定，短序列的算力被浪费在等待上，有效 c_v 高于按平均长度估算的值。</p>\n<p>耦合失效的后果是公式系统性低估验证成本、高估加速比。在混合负载（长短请求同批）中，这个偏差被放大：长请求的验证拖尾让整批的验证阶段变慢，而投机又要求每轮都做验证，于是拖尾成本被每轮重复支付。系统代价是 TPOT 的方差上升，P99 延迟恶化，而平均吞吐看起来尚可——这正是容量规划按均值配置、线上按尾延迟违约的根源。</p>\n<p>工程判断是三条：其一，按批内长度分布而非均值标定 c_v；其二，对长请求单独分桶，避免与短请求同批做投机验证；其三，在调度层对 γ 做长度自适应——长序列位置 α 通常更低且验证更贵，应缩短 γ。具体例子：同一解码节点同时服务短问答与长文档摘要，若统一 γ，长文档请求的验证拖尾会拉长整批每轮时间，短请求的 TPOT 被无辜拖累；按长度分桶后，两类请求各自的 γ 与批组成独立优化，尾延迟回到 SLO 之内。</p>\n<p>最终落在一条可执行的判断上：投机解码的加速比界不是一条曲线，而是一个受 α 分布、c 的资源区段、γ 与并发的联合约束、批内长度分布四重条件裁剪的可行域；任何把其中任一变量当常数的标定，都会在负载漂移时把可行域算错。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-18\">十八 · 边界在哪里：α、γ、c 三变量的失效地形</h3>\n<p>公式的分子分母各自携带一个隐含假设，边界就藏在这两个假设里。分子假设每轮接受的 token 数只由 α 与 γ 决定，与批内其他序列无关；分母假设 γc_d+c_v 是每轮归一化时间的常数。前者在草稿与目标分布一致时成立，后者在验证前向始终处于权重带宽受限区间时成立。一旦任一假设破裂，公式给出的就不是加速比，而是一个乐观上界。工程上更该问的是：当前负载落在哪个区间，以及该区间的 α、c 是否还是标定时的那个值。</p>\n<div class=\"formula\">$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)},\\qquad \\mathbb{E}[\\text{accepted}]=\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$$</div>\n<p>第一个失效条件是 α 偏低。当草稿与目标分布差异拉大，期望接受长度趋近 1，加速比趋近 1/(1+c)，c 稍大即为负收益。MoE 上这一点尤其隐蔽：草稿模型与目标模型对同一 token 激活不同专家，路由分歧直接压低 α，而按稠密模型标定的 α 看不出这个损失。此时增大 γ 只增加草稿的串行前向成本，接受数不增，S 随 γ 单调下降——公式在 α 低区的偏导符号已经翻转，最优 γ* 退化到 1 甚至 0。第二个失效条件是 c 不再为常数。验证阶段批增大后，若目标前向从权重带宽受限转为算力受限或 KV 带宽受限，摊薄收益消失；批内序列长度差异大时，验证被最长序列拖长，c_v 随批膨胀。公式把 c_v 当定值，会系统性低估验证成本、高估加速比，容量规划按此上限配并发，线上直接出现 SLO 违约。</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导变量</th><th>公式行为</th><th>系统代价</th></tr></thead><tbody><tr><td>α 高、c_d≪c_v</td><td>γ</td><td>S 随 γ 单调升</td><td>草稿算力线性增，验证摊薄有效</td></tr><tr><td>α 低（路由分歧）</td><td>α</td><td>S→1/(1+c)，γ* 退化</td><td>草稿算力纯浪费，吞吐不升反降</td></tr><tr><td>验证转算力/KV 受限</td><td>c_v</td><td>c 非常数，S 被高估</td><td>批膨胀、尾延迟抬升、SLO 余量被吃掉</td></tr></tbody></table>\n<p>规模上限由此显形：γ 的可取范围被 α 与 c_d/c_v 的比值夹住，并发上限被 c_v 的批膨胀夹住。容量决策要用实测 α、c_d、c_v 反解 γ*，并按模型与负载分桶标定——MoE 专家路由分布漂移时，同一 α 标定值跨负载不可迁移。约束草稿与目标的专家亲和性，比单独优化 α 更能守住验证阶段的拒绝率。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-19\">十九 · 边界不在公式里，在批的形状里</h3>\n<p>本节的公式把每轮代价写成 $\\gamma c_d+c_v$，其中 $c_v$ 被当成目标模型一次并行验证的相对成本。这个假设在单序列、定长、小批时成立；一旦进入连续批处理，验证前向的实际耗时由批内最长序列决定，短序列的验证槽位被空转填充。此时 $c_v$ 不再是常数，而是批内长度分布的泛函：$c_v^{\\text{eff}}=\\max_{i\\in\\text{batch}}L_i\\big/\\bar{L}$ 量级的膨胀因子乘上原 $c_v$。公式分子仍是 $\\mathbb{E}[\\text{accepted}+1]$，分母却被系统性低估，容量规划若按公式上限配置并发，线上就会出现验证阶段拖尾导致的 SLO 违约——这不是 $\\alpha$ 的问题，是批调度的问题。</p>\n<p>第二个失效面在 $\\alpha$ 的标定口径。MoE 模型上草稿与目标的路由分歧会让同一 prompt 在不同负载下落到不同专家，$\\alpha$ 随专家分布漂移，用稠密模型或单一负载桶标出的 $\\alpha$ 去反解 $\\gamma^\\ast$，选出的草稿长度偏大：$\\gamma$ 增大只增加 $\\gamma c_d$ 的串行草稿成本，接受数不增，$S$ 反而下降。工程上必须按模型与负载分桶标定 $\\alpha$，并把专家亲和性作为草稿模型的约束条件，而不是只优化接受率指标。</p>\n<table class=\"mini\"><thead><tr><th>失效源</th><th>被破坏的假设</th><th>系统代价</th></tr></thead><tbody><tr><td>变长批验证</td><td>$c_v$ 为常数</td><td>验证膨胀，吞吐低于预测，SLO 违约</td></tr><tr><td>MoE 路由漂移</td><td>$\\alpha$ 与负载无关</td><td>草稿算力浪费，$\\gamma^\\ast$ 偏大</td></tr><tr><td>批增大转算力受限</td><td>验证可摊薄权重读取</td><td>摊薄收益消失，$c$ 不再稳定</td></tr></tbody></table>\n<p>第三类是规模上限本身：验证批增大后若从权重带宽受限转为算力受限或 KV 带宽受限，MoE 上“验证批摊薄权重读取”的收益消失，$c$ 随批规模漂移，公式的线性代价模型失效。判断方法是在目标并发区间实测 $c_v$ 随批的变化曲线，若斜率明显偏离常数，就应把 $\\gamma^\\ast$ 的求解改为分段查表而非解析反解，并把 SLO 余量按最坏批形状预留。</p>\n<h3 id=\"th-spec-decode-speedup-sec-20\">二十 · 把加速比公式变成容量约束</h3>\n<p>前两部分已经把 \\(\\mathrm{SU}\\) 的分子分母拆开，本部分只回答一个问题：拿到实测的 \\(\\alpha\\)、\\(c_d\\)、\\(c_v\\) 之后，怎么把它变成部署决策里的四个旋钮——批大小、并行度、KV 预算、SLO。关键认识是：\\(\\mathrm{SU}\\) 不是一条性能曲线，而是一条<strong>约束方程</strong>。它把「每轮产出多少 token」与「每轮花多少代价」绑定，而代价项里的 \\(c_v\\) 恰恰是批大小的函数。工程上正确的用法不是先定批大小再算加速比，而是把 \\(\\mathrm{SU}\\) 写成批大小的函数，再与显存、带宽、SLO 三条边界联立求解。</p>\n<p>先明确归一化基准。设目标模型单次解码迭代（单序列、批为 1）的墙钟时间为 \\(T_0\\)，则草稿阶段 \\(\\gamma\\) 次串行前向耗时 \\(\\gamma c_d T_0\\)，验证阶段一次并行前向耗时 \\(c_v(B) T_0\\)，其中 \\(B\\) 是验证批内序列数。每轮产出 \\(\\mathbb{E}[\\text{accepted}+1]\\) 个 token，于是单序列的有效 token 产出率为</p>\n<div class=\"formula\">$$\\mathrm{TPP}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{(\\gamma c_d+c_v(B))\\,T_0}$$</div>\n<p>注意 \\(c_v(B)\\) 不是常数：验证前向把 \\(B\\) 条序列的 \\(\\gamma+1\\) 个位置拼成一个批，目标模型的权重读取被摊薄，但 KV 读取与注意力计算随 \\(B\\) 线性增长。当 \\(B\\) 小、权重带宽占主导时 \\(c_v(B)\\) 随 \\(B\\) 上升缓慢（摊薄收益显著）；当 \\(B\\) 越过拐点转为 KV 带宽或算力受限时，\\(c_v(B)\\) 近似线性上升，摊薄收益消失。这正是前文「失效条件」里那句「\\(c\\) 不再是常数」在容量层面的具体形态。</p>\n<p>举例：一个稠密 70B 级模型在单卡上，实测 \\(\\alpha=0.7\\)、\\(\\gamma=4\\)、\\(c_d=0.08\\)、\\(c_v(1)=1.0\\)。此时 \\(\\mathbb{E}[\\text{accepted}+1]=1+0.7(1-0.7^4)/(1-0.7)\\approx 1+0.7\\times 0.7599/0.3\\approx 2.77\\)，分母为 \\(4\\times0.08+1.0=1.32\\)，\\(\\mathrm{SU}\\approx 2.1\\)。若把 \\(B\\) 提到 32 后实测 \\(c_v(32)=1.6\\)（KV 带宽开始主导），分母变成 \\(0.32+1.6=1.92\\)，\\(\\mathrm{SU}\\) 掉到 \\(1.44\\)。同一套 \\(\\alpha\\)、\\(\\gamma\\)，仅仅因为批变大，加速比缩水三成——这就是为什么容量规划必须把 \\(c_v\\) 写成 \\(B\\) 的函数而不是抄一个标量。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-21\">二十一 · 定批大小：解 \\(\\gamma^\\ast\\) 与 \\(B^\\ast\\) 的联立</h3>\n<p>批大小决策的本质是两条相反曲线的交点。一条是摊薄收益：\\(B\\) 增大使 \\(c_v(B)\\) 的单位 token 成本下降；另一条是 KV 带宽与算力膨胀：\\(B\\) 增大使 \\(c_v(B)\\) 绝对值和显存占用上升。把 \\(\\mathrm{TPP}(B)\\) 对 \\(B\\) 求极值，得到的是「吞吐最优批」，但它通常不是「SLO 可行批」——后者还要叠加尾延迟约束。工程做法是分两步：先解吞吐最优，再用 SLO 收缩。</p>\n<p>吞吐最优的求解不需要闭式解，用离散扫描即可。伪代码思路：</p>\n<ul>\n<li>对 \\(B\\in\\{1,2,4,\\dots,B_{\\max}\\}\\) 与 \\(\\gamma\\in\\{1,\\dots,\\gamma_{\\max}\\}\\) 做二维网格；</li>\n<li>每个格点用实测标定的 \\(c_v(B)\\) 插值表（不是常数）计算 \\(\\mathrm{TPP}\\)；</li>\n<li>过滤掉显存超限（KV + 权重 + 草稿模型）与尾延迟超 SLO 的格点；</li>\n<li>在剩余格点中取 \\(\\mathrm{TPP}\\) 最大者，得到 \\((\\gamma^\\ast,B^\\ast)\\)。</li>\n</ul>\n<p>为什么必须二维联立而不是先定 \\(\\gamma\\) 再定 \\(B\\)？因为 \\(\\gamma\\) 增大同时抬高草稿成本 \\(\\gamma c_d\\) 与验证批的序列长度 \\(\\gamma+1\\)，后者直接推高 \\(c_v(B)\\) 中的注意力项。\\(\\gamma\\) 与 \\(B\\) 在验证成本上是耦合的：\\(\\gamma\\) 越大，同一 \\(B\\) 下验证批的有效 token 数越多，KV 读取量越大，\\(c_v\\) 越早进入线性区。忽略这个耦合，按稠密模型经验选出的 \\(\\gamma\\) 往往偏大，实际吞吐不升反降——这正是前文列出的失败模式之一。</p>\n<p>代价视角：批大小每翻一倍，KV cache 显存近似翻倍，这是硬约束；而 \\(\\mathrm{TPP}\\) 的边际收益在拐点后迅速衰减。因此 \\(B^\\ast\\) 通常落在「\\(c_v(B)\\) 刚开始偏离平坦段」的位置，而不是显存能塞下的最大值。对 MoE 模型还要额外一层：验证批增大时被激活的专家数增多，权重读取的摊薄收益比稠密模型更显著，实测 \\(\\mathrm{SU}\\) 常高于按稠密 \\(\\alpha\\) 估计的预测值；但若草稿与目标的路由分歧大，\\(\\alpha\\) 本身会随负载漂移，\\(\\gamma^\\ast\\) 必须按模型/负载分桶标定，不能全局一个值。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-22\">二十二 · 定并行度：把 \\(\\mathrm{SU}\\) 折进 TP/EP 的收益账</h3>\n<p>并行度决策常被误当成纯通信问题，但在投机解码下它多了一层：并行度改变的是 \\(c_v\\) 的构成。张量并行（TP）把目标模型单次前向的权重读取与算力分摊到多卡，\\(c_v\\) 的分母变大、单卡份额变小，但每轮验证要插入 all-reduce，通信延迟进入 \\(c_v\\) 的固定项。当 \\(B\\) 小、验证前向本就受权重带宽限制时，TP 能显著压低 \\(c_v\\)，\\(\\mathrm{SU}\\) 上升；当 \\(B\\) 已大到 KV 带宽主导时，TP 对 \\(c_v\\) 的改善有限，反而因通信固定开销拖累小批场景。</p>\n<p>判据可以写成：设 \\(c_v^{(P)}(B)\\) 为并行度 \\(P\\) 下的验证相对成本，则选择 \\(P\\) 的条件是</p>\n<div class=\"formula\">$$\\frac{\\mathbb{E}[\\text{accepted}+1]}{\\gamma c_d+c_v^{(P)}(B)}&gt;\\frac{\\mathbb{E}[\\text{accepted}+1]}{\\gamma c_d+c_v^{(P')}(B)}\\ \\Longleftrightarrow\\ c_v^{(P)}(B)&lt;c_v^{(P')}(B)$$</div>\n<p>分子在并行度变化下不变（\\(\\alpha\\) 由模型决定，与并行度无关，除非并行改变了数值精度路径），所以并行度选择退化为「谁的 \\(c_v\\) 更小」。这给出一个干净的工程判断：在投机解码场景下，并行度的收益必须通过压低 \\(c_v\\) 来兑现，任何不改变 \\(c_v\\) 的并行调整（例如只改 EP 分组但不改验证批的权重读取路径）对 \\(\\mathrm{SU}\\) 无贡献。</p>\n<p>具体例子：MoE 模型在 EP 下，草稿模型若与目标模型共享专家分组，草稿前向的 all-to-all 与验证前向的 all-to-all 可以合并或流水，\\(c_d\\) 与 \\(c_v\\) 同时受益；若草稿模型独立部署在不同卡组，两段通信无法重叠，\\(\\gamma c_d+c_v\\) 中的通信项叠加，\\(\\mathrm{SU}\\) 被通信吃掉。这就是「只优化 \\(\\alpha\\) 而不约束草稿与目标的专家亲和性」在并行度层面的代价：草稿命中率虚高，但每轮两段 all-to-all 串行，验证阶段频繁拒绝，草稿算力白花。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-23\">二十三 · 定 KV 预算：\\(\\gamma\\) 与 \\(B\\) 共同决定驻留量</h3>\n<p>投机解码对 KV 预算的影响是双重的，且方向相反。一方面，草稿模型需要自己的 KV（若草稿是独立小模型），验证阶段目标模型要为 \\(\\gamma+1\\) 个候选位置一次性写入 KV，峰值 KV 占用比常规解码高；另一方面，\\(\\mathrm{SU}&gt;1\\) 意味着同样 token 产出下驻留的序列数可以更少，长期 KV 压力下降。容量决策要区分<strong>峰值</strong>与<strong>稳态</strong>两个口径。</p>\n<p>峰值口径：每轮验证时，批内 \\(B\\) 条序列各扩展 \\(\\gamma+1\\) 个位置，目标模型 KV 的瞬时写入量为 \\(B(\\gamma+1)\\) 个位置的 KV，若显存按稳态 \\(B\\) 条序列的当前长度分配，则必须预留 \\(\\gamma+1\\) 个位置的余量，否则验证前向会触发重分配或 OOM。稳态口径：由于每轮产出 \\(\\mathbb{E}[\\text{accepted}+1]\\) 个 token 而只消耗一轮时间，达到同一 token 吞吐所需的并发序列数约为常规解码的 \\(1/\\mathrm{SU}\\)，KV 稳态占用同比例下降。</p>\n<p>把两者写成约束：设单序列每 token 的 KV 字节数为 \\(k\\)，序列平均长度为 \\(L\\)，则峰值 KV 需求近似为</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}}^{\\mathrm{peak}}\\approx B\\,(L+\\gamma+1)\\,k+M_{\\mathrm{draft}}$$</div>\n<p>其中 \\(M_{\\mathrm{draft}}\\) 是草稿模型的 KV 与权重占用。工程上常见的错误是按稳态 \\(BLk\\) 配置显存，把 \\(\\gamma+1\\) 的余量忽略掉，结果在 \\(\\gamma\\) 调大后线上出现间歇性 OOM——这与「把 \\(c_v\\) 当常数」是同一类错误的两个面：都忽略了 \\(\\gamma\\) 对验证阶段资源需求的放大。</p>\n<p>算例延续第一节：\\(B=32\\)、\\(L=2048\\)、\\(\\gamma=4\\)、\\(k\\) 取每 token 每层固定字节（定性量级），峰值比稳态多出 \\(32\\times5\\) 个位置的 KV。若把 \\(\\gamma\\) 从 4 提到 8 以图更高 \\(\\mathrm{SU}\\)，峰值余量翻倍，而 \\(\\alpha=0.7\\) 下 \\(\\mathbb{E}[\\text{accepted}+1]\\) 从 2.77 只升到约 3.1，\\(\\mathrm{SU}\\) 的边际增益远小于 KV 峰值的边际成本。这就是 \\(\\gamma^\\ast\\) 存在上限的显存侧原因：不是公式不给收益，而是峰值 KV 预算先把 \\(\\gamma\\) 卡死。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-24\">二十四 · 定 SLO：尾延迟而非均值</h3>\n<p>SLO 决策不能直接用 \\(\\mathrm{SU}\\) 的均值。\\(\\mathrm{SU}\\) 是期望加速比，而 SLO 约束的是尾延迟（如 P99 TTFT 或 TPOT）。投机解码的每轮接受数是几何分布式的随机变量：有的轮接受 \\(\\gamma+1\\) 个，有的轮只接受 1 个就拒绝。单请求的 token 产出时间因此是随机游走，尾延迟由「连续多轮低接受」的坏运气决定，而不是由 \\(\\alpha\\) 的均值决定。</p>\n<p>把每轮视为独立试验，连续 \\(m\\) 轮接受数不超过某阈值的概率随 \\(m\\) 指数衰减，但单轮被拒绝的概率 \\(1-\\alpha\\) 直接决定尾部形状。工程判据：SLO 余量应按「最坏可接受轮次」估算，即</p>\n<div class=\"formula\">$$T_{\\mathrm{tail}}\\approx n_{\\mathrm{round}}\\cdot(\\gamma c_d+c_v(B))\\,T_0,\\qquad n_{\\mathrm{round}}\\approx\\frac{N_{\\mathrm{out}}}{\\mathbb{E}[\\text{accepted}+1]-\\delta}$$</div>\n<p>其中 \\(N_{\\mathrm{out}}\\) 是请求需产出的 token 数，\\(\\delta\\) 是给尾部分布留的折减量（由实测 P99 与均值的比值标定，不是常数）。\\(\\delta\\) 的存在意味着：按均值 \\(\\mathrm{SU}\\) 配置并发，线上必然出现 SLO 违约——这正是前文失败模式里「容量规划按公式上限配置并发」的机制解释。</p>\n<p>具体做法：用实测的接受率分布（不只是均值 \\(\\alpha\\)）跑离线模拟，得到给定 \\(B\\)、\\(\\gamma\\) 下的 TPOT 分布，取 P99 反解可承载并发数。若 P99 超标，优先降 \\(B\\) 而不是降 \\(\\gamma\\)：降 \\(B\\) 直接压低 \\(c_v(B)\\) 与 KV 峰值，而降 \\(\\gamma\\) 只减少草稿成本却同时降低每轮产出，对尾延迟的改善不确定。MoE 场景下还要按专家路由分布分桶做这个模拟，因为 \\(\\alpha\\) 随负载漂移，单一 \\(\\alpha\\) 标定出的 SLO 余量在路由偏移的负载上不成立。</p>\n<p>最后落到一个可执行的工程判断：把 \\(\\mathrm{SU}\\) 公式当作<strong>四个约束的联立求解器</strong>——\\(c_v(B)\\) 的实测插值表是输入，\\(\\gamma^\\ast\\)、\\(B^\\ast\\)、KV 峰值余量、P99 余量是四个输出，任何一项用标量近似替代函数关系，都会在容量决策里系统性高估加速比。真正决定线上稳定的是 \\(c_v(B)\\) 这张表和接受率分布，而不是 \\(\\alpha\\) 的单点值。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-25\">二十五 · 把加速比公式放进容量账本：γ*、并发与 SLO 余量的反解</h3>\n<p>这个公式在容量决策里不是用来“预测能快多少”，而是用来反解三个可调量：草稿长度 γ、单卡并发数、以及为 SLO 预留的时延余量。做法是把实测的 α、c_d、c_v 代入 SU(γ)，先求使 SU 最大的 γ*：对 γ 求导并令其为零，等价于比较“多走一步草稿带来的边际接受概率”与“多一步草稿的边际成本”。工程上不必解析求解，直接在候选 γ∈{1,2,3,4,5,8} 上做表扫描即可，因为 α 与 c_v 都是分桶标定量。得到 γ* 后，单请求每 token 的有效时延为 t_dec/SU(γ*)，其中 t_dec 是目标模型单次解码迭代的实测时延；再用 SLO 的 TPOT 上限去除，得到单请求可容忍的时延预算，进而换算出在该预算下能并置多少请求。关键在于：并发数上升会改变 c_v，所以这一步必须迭代——先按小批测得的 c_v 估一个并发，再在该并发下复测 c_v 并修正，通常两轮即收敛。</p>\n<p>下表给出一个算例的骨架（数值为实测填入位，此处只示范结构）：α 分三桶（高一致性、路由轻度分歧、路由重度分歧），c_d 取 0.05～0.1 量级，c_v 取 1 附近但在变长批下膨胀。可以看到，α 从高桶掉到重度分歧桶时，γ* 迅速收缩到 1～2，此时 SU 已接近 1/(1+c)，投机解码只剩“省一点算力”的意义，不再值得为它付出草稿模型的显存与调度复杂度。</p>\n<table class=\"mini\"><thead><tr><th>α 桶</th><th>γ*</th><th>SU 量级</th><th>容量决策</th></tr></thead><tbody><tr><td>高一致性</td><td>4～5</td><td>明显大于 1</td><td>按 SU 折算并发，保留 SLO 余量</td></tr><tr><td>轻度分歧</td><td>2～3</td><td>略大于 1</td><td>并发按保守值配置，γ 下调</td></tr><tr><td>重度分歧</td><td>1</td><td>趋近 1/(1+c)</td><td>关闭投机路径，回归常规解码</td></tr></tbody></table>\n<p>边界与失效条件必须写进配置而不是写在文档里。第一，c_v 不是常数：验证阶段批内序列长度差异大时，目标模型前向被最长序列拖长，c_v 随批膨胀，公式会系统性低估验证成本、高估加速比；容量规划若按公式上限配并发，线上必然出现 SLO 违约。第二，MoE 上直接用稠密模型标定的 α 是典型误用——路由分歧使草稿与目标激活不同专家，α 虚高、γ* 偏大，实际吞吐不升反降。第三，只优化 α 而不约束草稿与目标的专家亲和性，会让草稿算力白烧。因此容量账本里应把 α 按模型与负载分桶标定，并在路由分布漂移时触发重标定；同时给 c_v 设一个随批长度增长的上界修正项，把“验证膨胀”显式计入分母。</p>\n<p>系统代价落在三处：草稿模型的常驻显存挤占 KV 预算（γ 越大，草稿侧要保留的状态越多）；验证批增大后若转为算力受限或 KV 带宽受限，摊薄收益消失，c 不再是常数，此时提高并发只会同时抬高 TTFT 与 TPOT；以及为维持高 α 而做的专家亲和性约束，会限制草稿模型的选型自由度。工程判断是：把 γ* 与并发上限做成随 α 桶联动的查表配置，并让调度器在检测到 c_v 膨胀超过阈值时自动降 γ、降并发，而不是让公式的乐观上限直接进入 SLO 承诺。</p>\n<h3 id=\"th-spec-decode-speedup-sec-26\">二十六 · 把 α 当成模型常量：MoE 路由分歧下的系统性高估</h3>\n<p>最普遍的一种误用，是把单 token 接受率 α 当作某个模型固有的、与负载无关的标定值，一次测完就写进容量表。在稠密模型上这个近似尚可容忍，因为草稿与目标的输出分布差异主要由采样温度与提示分布决定；但在 MoE 上，α 的物理来源多了一层——草稿模型与目标模型的激活走的是不同的专家子集。草稿模型若是一个独立的小模型，它没有目标模型的专家路由表；即便是同源蒸馏的草稿头，路由 logits 的微小偏移也会把 token 送进不同专家，进而让两个分布在同一位置上分叉。这种分叉不是采样噪声，而是结构性的：它随提示的领域、语言、以及批内其他序列的组成而漂移。</p>\n<p>后果直接落在公式的分子上。期望接受数 $\\mathbb{E}[\\text{accepted}]=\\alpha(1-\\alpha^{\\gamma})/(1-\\alpha)$ 对 α 的敏感度是非线性的：α 从高位滑落到中位时，分子近似按 $\\gamma\\alpha$ 缩减，而分母中的草稿成本 $\\gamma c_d$ 一分不少。也就是说，α 的标定偏差不会被 γ 的调整吸收，反而被 γ 放大。工程上表现为：按稠密模型标定的 α 选出的 $\\gamma^\\ast$ 偏大，草稿阶段串行前向次数增加，验证阶段却频繁在第一个位置就拒绝，草稿算力全部沉没。</p>\n<p>识别方法不是看平均接受率，而是看<em>接受长度的分布形状</em>。健康的投机解码，每轮接受数分布应当偏向 γ 一侧，即大量轮次能吃到接近上限的接受数；一旦分布退化为在 1 附近堆积、长尾极薄，说明 α 的有效值已经塌陷，此时任何 γ 增大都只是在给拒绝概率做乘法。运维上应当按模型×负载分桶记录该分布，而不是只记一个标量 α。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-27\">二十七 · 把 $c_v$ 钉死为单序列成本：变长批下的验证膨胀</h3>\n<p>第二个误用针对分母里的 $c_v$。公式把 $c_v$ 定义为目标模型一次并行验证的相对成本，以单 token 解码成本为基准归一化。很多实现把它当成一个与批无关的常数，理由是“验证是一次前向，批内并行不额外花钱”。这个理由只在验证批处于带宽受限区时成立。一旦批内序列长度差异拉大，目标模型前向的完成时间由最长序列决定，短序列的验证位置被空转填充拖住，$c_v$ 随批膨胀而不再是常数。</p>\n<p>膨胀的机制有两层。其一是注意力与 KV 读取：验证阶段每个候选位置都要对前缀 KV 做读取，批内最长序列的 KV 长度决定了这一轮的实际带宽占用，短序列无法提前退出。其二是算力受限的切换：当验证批大到一定程度，MMA 流水从带宽受限转为算力受限，摊薄收益消失，此时 $c_v$ 的增长近似线性于批内总 token 数而非批内序列数。公式若仍用单序列 $c_v$，会系统性低估验证成本、高估加速比，容量规划据此配置的并发数在线上直接表现为 SLO 违约——不是缓慢劣化，而是跨过某个批规模后延迟台阶式抬升。</p>\n<div class=\"formula\">$$c_v^{\\text{eff}} \\approx c_v^{0}\\cdot\\frac{L_{\\max}}{\\bar L}\\quad(\\text{带宽受限区}),\\qquad c_v^{\\text{eff}} \\propto N_{\\text{tok}}\\quad(\\text{算力受限区})$$</div>\n<p>识别信号是验证阶段的分位延迟与批内长度极差的相关性：若 P99 验证延迟随批内最长序列长度单调上升，而吞吐不随之上升，说明已经进入膨胀区。工程判断是：把 $c_v$ 标定成批内长度极差与总 token 数的函数，而不是标量；在连续批处理下，宁可对验证批做长度分桶，也不要把长短序列混进同一验证轮。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-28\">二十八 · 只优化 α 不管专家亲和性：虚高的命中率与真实的拒绝</h3>\n<p>第三种误用是把 α 当作唯一可调目标，通过蒸馏、温度对齐、甚至放宽草稿采样策略把 α 刷高，却不约束草稿模型与目标模型在专家路由上的亲和性。这类优化在离线评测里数字漂亮，上线后却出现“草稿命中率虚高、验证阶段频繁拒绝”的割裂。原因是 α 的度量口径本身可能被污染：如果 α 是在草稿模型自己的采样分布上统计的，它度量的是草稿的自一致性，而不是草稿与目标的一致性。真正的接受判定发生在目标模型的验证前向里，路由分歧会在那里一次性暴露。</p>\n<p>代价是双份的：草稿阶段 γ 次串行前向的算力已经付出，验证阶段又因为拒绝而无法回收，等于用草稿成本买了一个不被接受的 token。在 MoE 上这尤其昂贵，因为验证前向要读取的专家权重远多于稠密模型同等参数量的读取量，拒绝意味着这次权重读取完全浪费。识别方法是做<em>分层接受率</em>：按目标模型实际激活的专家组合对样本分桶，看 α 在桶间的方差。方差大说明亲和性问题存在，此时提高全局 α 只是在平均意义上掩盖了某些桶的塌陷。</p>\n<p>工程上的正解不是继续调 α，而是让草稿模型继承目标模型的路由先验——同源蒸馏、共享路由 logits、或在草稿侧做轻量的专家预测头——把 α 的提升建立在亲和性之上，而不是建立在采样技巧之上。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-29\">二十九 · 一个反例：按公式上限配置并发的 MoE 服务</h3>\n<p>设一个 MoE 目标模型的服务，团队用稠密模型时代的标定流程得到 α 的中位估计与 $c_d\\ll c_v$ 的关系，代入公式反解出 $\\gamma^\\ast$，再按加速比上限 S 推算单卡可承载并发数，配置为容量上限。上线后观测到：低并发时加速比接近预测，吞吐随并发上升；跨过某个并发阈值后，验证阶段 P99 延迟台阶式抬升，加速比跌到 1 附近，SLO 违约。</p>\n<p>复盘时三个误用同时在场。其一，α 是在单一领域提示上标定的，线上流量混入多语言与代码后，MoE 路由分歧使有效 α 下滑，分子缩水。其二，$c_v$ 被钉死为单序列验证成本，而连续批处理把长短序列混进同一验证轮，$c_v$ 随批内长度极差膨胀，分母被低估。其三，草稿模型是独立小模型，与目标模型的专家亲和性未约束，分层接受率方差大，部分桶的接受长度趋近 1。三者叠加的方向一致：公式高估 S，容量规划把并发配到了膨胀区之上。</p>\n<p>正确的做法是把这三个量都变成负载的函数再反解：α 按领域与专家组合分桶，$c_v$ 按批内长度极差与总 token 数标定，γ 的选择受草稿串行成本 $\\gamma c_d$ 与验证膨胀的联合约束。容量决策不应取公式的加速比上限，而应取“加速比开始随并发下降”的拐点作为并发上限——这个拐点正是 $c_v$ 从常数变为变量的位置。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-30\">三十 · 误用的共同结构：把负载相关量当模型常量</h3>\n<p>三种误用共享同一个结构：公式里的 α、$c_v$、以及草稿与目标的亲和性，全都是负载相关量，却被当作模型常量写进容量表。投机解码的加速比界是一个<em>条件界</em>，它的成立依赖 α 在批内稳定、$c_v$ 不随批膨胀、草稿与目标在路由上同分布。任何一个条件被负载打破，界就不再是界，而是一个乐观的估计。</p>\n<p>识别这类误用不需要复杂的实验，只需要在容量表里为每个量标注它的标定条件：α 的标定领域、$c_v$ 的标定批形态、亲和性的标定专家组合。任何一项在线上流量中越界，就应当触发重新标定而不是继续按公式扩容。工程判断落在具体机制上：把验证批按长度分桶、把 α 按专家组合分桶、把 γ 的选择绑定在草稿串行成本与验证膨胀的联合约束上——这三件事做完，公式才重新变成一个可用的界，而不是一个会被负载悄悄推翻的假设。</p>\n\n<h3 id=\"th-spec-decode-speedup-sec-31\">三十一 · 误用与反例：把公式当承诺而不是当仪表</h3>\n<p>最常见的误用是把 <span class=\"sym\">c</span> 当成常数。公式 <span class=\"formula\">$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)}$$</span> 里，<span class=\"sym\">c</span> 的物理含义是草稿与验证相对单次解码迭代的代价比，它只在验证批的算力与 KV 带宽占用随批线性增长时近似稳定。一旦验证阶段转入算力受限或 KV 带宽受限，摊薄收益消失，<span class=\"sym\">c</span> 随批膨胀，公式会系统性低估验证成本、高估加速比。识别方法很直接：在容量规划前，用同一组 <span class=\"sym\">\\(\\alpha\\)</span>、<span class=\"sym\">\\(\\gamma\\)</span> 分别在低并发与目标并发下实测端到端每 token 时延，若实测加速比低于公式预测且差距随并发扩大，说明 <span class=\"sym\">c</span> 已不是常数，此时应把 <span class=\"sym\">c</span> 改写为批规模的函数再反解 <span class=\"sym\">\\(\\gamma^\\ast\\)</span>，而不是继续按公式上限配置并发。</p>\n<p>第二个误用出现在 MoE 上：直接沿用稠密模型标定出的 <span class=\"sym\">\\(\\alpha\\)</span>。MoE 的路由分歧会让草稿与目标激活不同专家，单 token 接受率显著低于稠密场景，而按公式选出的 <span class=\"sym\">\\(\\gamma\\)</span> 偏大，草稿阶段 <span class=\"sym\">\\(\\gamma c_d\\)</span> 的串行成本照付，接受数却不增，实际吞吐不升反降。注意这里有一个容易被忽略的反向效应：MoE 验证批可摊薄权重读取，实际加速常高于按稠密模型估计的预测值——于是同一套参数既可能高估 <span class=\"sym\">\\(\\alpha\\)</span> 又低估摊薄，两个误差方向相反，靠公式本身无法分辨。工程判断是分桶标定：按模型与负载把 <span class=\"sym\">\\(\\alpha\\)</span> 分桶实测，并在路由分布漂移时重新标定，而不是取一个全局均值。</p>\n<p>反例可以这样构造：某 MoE 服务按稠密模型标定得 <span class=\"sym\">\\(\\alpha\\)</span> 较高，据此把 <span class=\"sym\">\\(\\gamma\\)</span> 取到较大值并上线。线上真实 <span class=\"sym\">\\(\\alpha\\)</span> 因路由分歧而偏低，期望接受长度趋近 1，加速比趋近 <span class=\"sym\">1/(1+c)</span> 甚至为负；同时变长批把验证前向拖长，<span class=\"sym\">c_v</span> 随批膨胀。两个失效叠加，草稿算力被白白消耗，容量按公式上限配置的并发出现 SLO 违约。识别信号是：草稿命中率看起来不低，但验证阶段拒绝频繁，且每 token 时延随批长上升而非持平。此时应先收缩 <span class=\"sym\">\\(\\gamma\\)</span>、约束草稿与目标模型的专家亲和性，再谈扩容。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td><span class=\"sym\">c_v</span> 固定为单序列成本</td><td>高估加速比，并发超配</td><td>实测加速比随并发下降</td></tr><tr><td>MoE 沿用稠密 <span class=\"sym\">\\(\\alpha\\)</span></td><td><span class=\"sym\">\\(\\gamma\\)</span> 偏大，吞吐反降</td><td>命中率虚高、验证频繁拒绝</td></tr><tr><td>只优化 <span class=\"sym\">\\(\\alpha\\)</span> 不顾专家亲和性</td><td>浪费草稿算力</td><td>草稿成本占比升而接受数不增</td></tr></tbody></table>\n\n<h3 id=\"th-spec-decode-speedup-sec-32\">三十二 · 误用与反例：把 c_v 当常数、把稠密 α 搬到 MoE 上</h3>\n<p>最常见的误用不是公式写错，而是把 <span class=\"sym\">c_v</span> 当成与批无关的常数。验证阶段的目标模型前向被批内最长序列拖长，<span class=\"sym\">c_v</span> 随批膨胀，公式便系统性低估验证成本、高估加速比。识别信号很直接：固定 <span class=\"sym\">γ</span> 扫并发，实测加速比在某个并发点后掉头向下，而按公式预测仍单调上升——这就是 <span class=\"sym\">c_v</span> 已从常数变为批规模的函数。此时容量规划若仍按公式上限配并发，线上必然出现 SLO 违约，因为分母里被漏掉的那部分验证时间正是尾延迟的来源。</p>\n<div class=\"formula\">$$\\mathrm{SU}=\\frac{\\mathbb{E}[\\text{accepted}+1]}{1+c\\,(1-\\alpha^{\\gamma+1})/(1-\\alpha)},\\qquad \\mathbb{E}[\\text{accepted}]=\\frac{\\alpha(1-\\alpha^{\\gamma})}{1-\\alpha}$$</div>\n<p>第二个失效模式发生在 MoE：直接用稠密模型上标定的 <span class=\"sym\">α</span> 选 <span class=\"sym\">γ</span>。路由分歧使草稿与目标激活不同专家，真实 <span class=\"sym\">α</span> 远低于标定值，期望接受长度趋近 1，加速比趋近 <span class=\"sym\">1/(1+c)</span> 甚至为负；而按虚高的 <span class=\"sym\">α</span> 反解出的 <span class=\"sym\">γ*</span> 偏大，草稿阶段 <span class=\"sym\">γ c_d</span> 次串行前向白烧，实际吞吐不升反降。反例：某 MoE 服务沿用稠密标定的 <span class=\"sym\">α</span> 把 <span class=\"sym\">γ</span> 设为较大值，草稿命中率看似可观，但验证阶段频繁拒绝，草稿算力全部沉没，单卡承载的并发请求数反而低于不启用投机的基线。识别办法是按模型与负载分桶实测 <span class=\"sym\">α</span>，并约束草稿与目标的专家亲和性，而不是只优化 <span class=\"sym\">α</span> 这一个标量。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>c_v 视为常数</td><td>加速比随并发先升后降</td><td>尾延迟膨胀、SLO 违约</td></tr><tr><td>稠密 α 搬到 MoE</td><td>草稿命中高但验证拒绝多</td><td>草稿算力沉没、吞吐低于基线</td></tr></tbody></table>\n<p>工程判断落在分母的可测性上：<span class=\"sym\">c_d</span>、<span class=\"sym\">c_v</span> 必须以目标模型单 token 成本为基准、在真实批形态下归一化实测，且 <span class=\"sym\">α</span> 随专家路由分布漂移时按桶重标定；一旦验证阶段转为算力受限或 KV 带宽受限，摊薄收益消失，<span class=\"sym\">c</span> 不再是常数，公式只能作上界参考，不能作容量承诺。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\alpha</td><td>单token接受率（草稿与目标分布一致性度量）</td></tr><tr><td>\\gamma</td><td>每轮草稿token数</td></tr><tr><td>c</td><td>草稿+验证相对单次解码迭代的代价比</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-spec-decode-speedup · 共 5 个片段</p>\n"},{"id":"th-disagg-goodput","title":"分离式部署Goodput模型","direction":"dir-moe-routing-capacity","prereq":[],"plain":"预填与解码分离后，系统goodput由两类资源池的瓶颈阶段决定：预填池受算力与TTFT约束，解码池受KV带宽与TPOT约束，整体吞吐是两池吞吐的调和式折中，任一池饱和即拖垮全局。","definition":"预填与解码分离后，系统goodput由两类资源池的瓶颈阶段决定：预填池受算力与TTFT约束，解码池受KV带宽与TPOT约束，整体吞吐是两池吞吐的调和式折中，任一池饱和即拖垮全局。","formula":"$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p\\,F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d\\,\\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h}\\right)\\cdot\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$","variables":[{"sym":"N_p","meaning":"预填池GPU数"},{"sym":"N_d","meaning":"解码池GPU数"},{"sym":"P_{\\text{prefill}}","meaning":"单请求预填FLOPs"},{"sym":"S_{\\text{ttft}}","meaning":"TTFT SLO阈值"},{"sym":"S_{\\text{tpot}}","meaning":"TPOT SLO阈值"}],"derivation":"推导关键一步：分别对预填池写“GPU 数 × 有效算力 / 单请求预填量”、对解码池写“GPU 数 × HBM 带宽 / 每 token KV 字节”，取两者较小值，再用 TTFT 与 TPOT 两个 SLO 指示函数做硬截断。","example":"用途：容量规划中用于确定 N_p:N_d 配比——按目标负载的 P_prefill 与 KV 字节量代入两式，找出先饱和的一侧并调整 GPU 分配，使两池吞吐尽量相等以避免单侧闲置。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["KV cache需跨池传输时，互连带宽成为第三瓶颈，min式需加入KV迁移项","请求长度分布重尾时，预填池被长提示占满，静态配比N_p:N_d失效，需弹性重配比"],"system_note":"误用后果：忽略 KV 跨池迁移带宽，只按两池算力配比，实际部署中 KV 传输成为隐藏瓶颈；或在重尾请求下沿用静态配比，长提示占满预填池使 TTFT 超 SLO，指示函数归零、goodput 崩塌。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：预填与解码分离后，全局 goodput 由两池中先饱和的那个决定；预填池受算力与 TTFT 约束，解码池受 KV 带宽与 TPOT 约束，任一池饱和即拖垮整体。","公式含义：$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p\\,F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d\\,\\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h}\\right)\\cdot\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$ 中 N_p、N_d 为两池 GPU 数，P_prefill 为单请求预填 FLOPs，分母第二项为每 token 的 KV 读取字节量。","推导关键一步：分别对预填池写“GPU 数 × 有效算力 / 单请求预填量”、对解码池写“GPU 数 × HBM 带宽 / 每 token KV 字节”，取两者较小值，再用 TTFT 与 TPOT 两个 SLO 指示函数做硬截断。","适用边界：KV cache 需跨池传输时互连带宽成为第三瓶颈，min 式需加入 KV 迁移项；请求长度分布重尾时预填池被长提示占满，静态配比 N_p:N_d 失效，需弹性重配比。","用途：容量规划中用于确定 N_p:N_d 配比——按目标负载的 P_prefill 与 KV 字节量代入两式，找出先饱和的一侧并调整 GPU 分配，使两池吞吐尽量相等以避免单侧闲置。","误用后果：忽略 KV 跨池迁移带宽，只按两池算力配比，实际部署中 KV 传输成为隐藏瓶颈；或在重尾请求下沿用静态配比，长提示占满预填池使 TTFT 超 SLO，指示函数归零、goodput 崩塌。"],"anchors":["$$\\mathrm{TTFT}\\le S_{\\text{ttft}}$$","$$\\mathrm{TPOT}\\le S_{\\text{tpot}}$$"],"pitfalls":["只按两池算力做静态配比而不监测先饱和的一侧，导致预填池闲置或解码池排队，整体 goodput 被短板锁死。","忽略 KV cache 跨池传输的互连带宽项，分离式部署后 KV 迁移成为实际瓶颈，min 式预测的吞吐无法达到。","在请求长度重尾分布下沿用固定 N_p:N_d，长提示占满预填池使 TTFT 越过 SLO，指示函数归零导致 goodput 骤降。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-1\">一 · 一句话直觉：短板在哪，全局就在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-2\">二 · 严格定义：min 式与两个硬截断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-3\">三 · 为什么需要这个模型：静态配比靠猜，min 式靠算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-4\">四 · 常见误解之一：把 min 当成和，把分离当成叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-5\">五 · 常见误解之二：忽略第三瓶颈与重尾分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-6\">六 · 两池木桶：分离式 goodput 的边界、失效与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-7\">七 · 两个分式的量纲对齐：为什么可以直接取 min</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-8\">八 · 解码分母的逐项拆解与离散化位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-9\">九 · 指示函数的硬截断与 SLO 的耦合结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-10\">十 · 重尾分布下 min 式的失效与弹性重配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-11\">十一 · KV 迁移项的加入与三瓶颈 min 式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-12\">十二 · 从公式到配比求解：等吞吐点的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-13\">十三 · 公式的失效面：第三瓶颈、重尾与指示函数归零</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-14\">十四 · 指示函数不是软约束：SLO 越界即归零的硬截断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-15\">十五 · 第三瓶颈：KV 跨池迁移项的缺席与补入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-16\">十六 · 重尾长度分布：静态配比 N_p:N_d 的失效机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-17\">十七 · 规模上限：两池独立假设在小规模与大集群两端的破裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-18\">十八 · 何时该弃用公式：从解析模型退回测量驱动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-19\">十九 · 边界之外：当 min 式不再成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-20\">二十 · 把 min 式读成两条“产能曲线”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-21\">二十一 · 用指示函数反推批大小与 KV 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-22\">二十二 · 定并行度：TP 与 EP 如何进入两条直线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-23\">二十三 · 算例：从 SLO 反推 N_p:N_d 与批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-24\">二十四 · 重尾负载下的弹性重配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-25\">二十五 · 误用清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-26\">二十六 · 配比求解的反问题：从 SLO 倒推 N_p:N_d 与 KV 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-27\">二十七 · 误用一：把 min 式当成“算力配比公式”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-28\">二十八 · 误用二：漏掉 KV 迁移项，把互连当免费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-29\">二十九 · 误用三：重尾分布下沿用静态配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-30\">三十 · 反例：一次“加机器反而更慢”的扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-31\">三十一 · 误用与反例：当 min 式被当成静态配比表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-disagg-goodput-sec-32\">三十二 · 当 min 式漏掉第三项：分离式 goodput 的三个反例边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：预填与解码分离后，系统goodput由两类资源池的瓶颈阶段决定：预…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathrm{Goodput}=\\min\\!\\left(\\f…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：KV cache需跨池传输时，互连带宽成为第三瓶颈，min式需加入…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-disagg-goodput-sec-1\">一 · 一句话直觉：短板在哪，全局就在哪</h3>\n<p>把预填（prefill）与解码（decode）拆到两个资源池之后，系统不再是一条流水线，而是两条各自会饱和的生产线，中间用 KV cache 做交接。全局 goodput 的直觉只有一句：<strong>两池中先饱和的那一个决定整体吞吐</strong>。预填池吃的是算力，它的产出速率是「GPU 数 × 有效算力 ÷ 单请求预填 FLOPs」；解码池吃的是 HBM 带宽，它的产出速率是「GPU 数 × HBM 带宽 ÷ 每 token 需读取的 KV 字节」。谁先到顶，谁就把另一边锁死——预填池再快，解码池吐不出 token，整机吞吐就停在解码侧；解码池再空，预填池排满长提示，TTFT 照样越线。这就是「min 式」而非「和式」的根本原因：分离式部署不产生新的总算力，只把两种性质完全不同的负载从互相踩踏变成各自独立，代价是必须显式管理配比。</p>\n<p>用一个具体场景固定直觉：N_p 张卡做预填、N_d 张卡做解码，若把 N_p 加倍而 N_d 不动，预填侧吞吐翻倍，全局 goodput 纹丝不动——多出来的预填能力全部转化为 KV cache 的堆积与排队。反过来把 N_d 加倍，解码侧每 token 的 KV 读取吞吐翻倍，但如果预填池已经在 TTFT SLO 边缘，全局同样不涨。工程上判断一次扩容是否有效，只需问一句：加的那一侧，是不是当前的短板？</p>\n\n<h3 id=\"th-disagg-goodput-sec-2\">二 · 严格定义：min 式与两个硬截断</h3>\n<p>把直觉写成可代入的式子，就是本卷反复使用的 goodput 定义：</p>\n<div class=\"formula\">$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p\\,F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d\\,\\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h}\\right)\\cdot\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$</div>\n<p>逐项拆开：N_p、N_d 是两池 GPU 数；P_prefill 是单请求预填 FLOPs，随提示长度线性增长；F_eff 是预填池在目标精度（NVFP4/FP8 走 tcgen05 路径）下的有效算力，已经把 MMA 利用率与访存开销折算进去。解码侧分母是每 token 的 KV 读取字节量：B_act 为单 token 激活读取量，B 为批大小，s 为序列长度，b_kv 为每元素字节数，2 来自 K/V 两份，L 为层数，H_kv 为 KV 头数，d_h 为头维。分母随批大小与序列长度线性增长，这正是解码池「带宽受限」的数学形态——算力几乎不进入这一项。</p>\n<p>关键在于两个指示函数。它们不是软惩罚，而是硬截断：TTFT 一旦越过 S_ttft，或者 TPOT 一旦越过 S_tpot，该项归零，goodput 直接崩塌，而不是平滑下降。这与传统吞吐指标有本质区别——离线批处理里慢一点只是均值变差，在线服务里慢过 SLO 就是违约，违约的请求不计入有效产出。因此 goodput 是「在 SLO 约束下的有效 token 速率」，量纲是 token/s，但语义是「可交付的 token/s」。</p>\n<p>推导的关键一步没有玄机：分别对两池写产出速率，取较小值，再乘指示函数。它之所以成立，前提是两池之间除 KV 交接外没有其他耦合——一旦 KV 需要跨池搬运，这个前提就被打破，min 式必须扩项，这一点在适用边界里处理。</p>\n\n<h3 id=\"th-disagg-goodput-sec-3\">三 · 为什么需要这个模型：静态配比靠猜，min 式靠算</h3>\n<p>分离式部署的工程诱惑在于「各干各的」：预填是算力密集、解码是带宽密集，混在一起时预填的长矩阵乘会打断解码的细粒度 token 循环，解码的 KV 读取又会稀释预填的 MMA 占用。拆开之后两类负载各自跑到自己的 roofline 附近，这是分离式部署收益的来源。但拆开也把一个问题摆到台面上：N_p:N_d 到底怎么定？</p>\n<p>没有模型时，配比只能靠试跑或经验比例，代价是双向的浪费。预填池配多了，解码池排队，GPU 闲置在预填侧；解码池配多了，预填侧成为长提示的瓶颈，TTFT 越线，指示函数归零，整机有效吞吐骤降。min 式的用途正是把这件事变成算术：按目标负载的 P_prefill 与每 token KV 字节量代入两式，算出两侧各自的产出速率，找出先饱和的一侧，然后把 GPU 从富余侧挪向短板侧，直到两池吞吐尽量相等。相等点是配比的最优点——此时任何一侧的额外 GPU 都无法提升全局 goodput，扩容必须两侧同步。</p>\n<p>系统代价在这里体现得非常直接。以解码侧为例，分母中的 B·s·b_kv·2L·H_kv·d_h 随序列长度增长，长上下文场景下每 token 的 KV 读取字节量可以远超 B_act，解码池的吞吐随平均序列长度近似反比下降；这意味着同一套 N_p:N_d 在短请求负载下健康，在长上下文负载下解码池立刻成为短板。容量规划若不把序列长度分布纳入 P_prefill 与 KV 字节量的计算，配比就是对着错误的工作点调的。显存侧的代价同样真实：解码池每张卡能容纳的并发批大小受 KV cache 容量限制，批大小 B 上不去，分母里的固定项 B_act 占比上升，带宽利用率下降——这是解码池「显存换吞吐」的经典取舍，与 KV cache 容量式是同一枚硬币的两面。</p>\n\n<h3 id=\"th-disagg-goodput-sec-4\">四 · 常见误解之一：把 min 当成和，把分离当成叠加</h3>\n<p>最常见的误读是把两池吞吐相加当作系统吞吐：「预填池能做 X token/s，解码池能做 Y token/s，所以系统能做 X+Y」。这在分离式架构下是错的，因为两池串行服务于同一批请求——一个请求必须先过预填再进解码，两池的产出不是并列的独立流，而是同一条请求流上的两个阶段。全局速率由较慢阶段决定，这正是 min 的来历。相加只在两池服务完全不相交的请求集合时才成立，而那不是分离式部署的常态。</p>\n<p>由此衍生出第二个误解：认为分离式部署本身能提升吞吐。分离式部署提升的是<em>效率</em>——让两类负载各自贴近自己的 roofline，减少互相干扰带来的利用率损失；它不创造算力，也不创造带宽。如果原系统本来就没有互相干扰（例如负载极轻、两阶段都不饱和），分离反而引入 KV 交接开销与配比管理成本。判断是否该分离，要看混部时的利用率损失是否大于交接开销，而不是看分离式架构在图谱上更好看。</p>\n\n<h3 id=\"th-disagg-goodput-sec-5\">五 · 常见误解之二：忽略第三瓶颈与重尾分布</h3>\n<p>公式的适用边界写得很清楚，但工程上最常踩的两个坑恰好都在边界上。第一，KV cache 需要跨池传输时，互连带宽成为第三瓶颈，min 式必须加入 KV 迁移项。此时即使两池算力配比完美，KV 从预填池搬到解码池的链路也可能先饱和——NVLink 5 域内的搬运与跨节点走 NIXL/互连的搬运代价完全不同，后者会把 min 式预测的吞吐打成实际达不到的上限。只按两池算力配比而不监测迁移链路，是分离式部署最隐蔽的失效模式：账面配比平衡，实测吞吐上不去，瓶颈在公式之外。</p>\n<p>第二，请求长度分布重尾时，静态配比 N_p:N_d 失效。少量超长提示会占满预填池，把 TTFT 推过 S_ttft，指示函数归零，goodput 不是缓慢下滑而是断崖。重尾分布下预填池的「平均」产出速率没有意义，必须看分位数：长提示的 P_prefill 可能是中位数的若干倍，按均值配比必然在尾部违约。对策是弹性重配比——在负载构成变化时动态调整两池的 GPU 分配或准入策略，而不是把 N_p:N_d 写死在部署配置里。这也是为什么本卷把 goodput 模型与批调度、连续批处理放在同一框架下讨论：配比是静态决策，准入与调度是动态补偿，两者缺一，min 式就只是纸面数字。</p>\n<p>还有一个更细的误解：把指示函数当成可以「稍微超一点」的软约束。工程上 SLO 是契约，TTFT 超阈值意味着请求在用户侧已经不可用，其产出的 token 不计入有效吞吐。因此优化目标不是「平均 TTFT 尽量低」，而是「让尽可能多的请求落在阈值内」，这两者在重尾分布下会给出完全不同的配比决策——前者奖励均值优化，后者要求对尾部做保护。goodput 的硬截断形式正是把后者写进目标函数的方式。</p>\n\n<h3 id=\"th-disagg-goodput-sec-6\">六 · 两池木桶：分离式 goodput 的边界、失效与代价</h3>\n<p>把预填池与解码池看成两只并联的水桶，全局 goodput 不是两池吞吐之和，而是先见底的那只桶的出水速率——这就是 min 式的物理含义。严格地说，goodput 指单位时间内满足 TTFT 与 TPOT 两条 SLO 的“有效完成 token 数”，而非 GPU 跑满时的原始 token 吞吐。公式 $$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p\\,F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d\\,\\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h}\\right)\\cdot\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$ 的左项是预填池每秒能“吃进”多少请求，右项是解码池每秒能“吐出”多少 token，指示函数则把任何越界 SLO 的解直接截断为零。注意右项分母是每 token 的 KV 读取字节量：$B_{\\text{act}}$ 为激活读取，$B s b_{kv}2L H_{kv}d_h$ 随批大小 $B$、序列长度 $s$ 与层数线性增长，这意味着解码池的吞吐随上下文变长而单调下滑，而预填池的 $P_{\\text{prefill}}$ 亦随提示长度上升。两条曲线一升一降，交点即最优配比。</p>\n<p>这个模型的适用边界必须写清楚，否则它会被当成万能容量公式。第一，它默认 KV cache 留在解码池本地；一旦预填与解码分处不同 GPU 甚至不同节点，KV 必须跨池搬运，互连带宽就成为第三只桶，min 式需追加一项 KV 迁移吞吐（正比于互连有效带宽除以每请求 KV 字节数）。在 NVLink 5 域内这一项通常不显形，但跨 NVL72 机柜或跨节点走 RDMA 时，它会迅速压过前两项——工程上表现为预填池明明有空闲、解码池却在等 KV 到达。第二，它假设请求长度分布可用单一均值刻画；重尾分布下长提示会成批占满预填池，$N_p:N_d$ 的静态配比失效，TTFT 越过 $S_{\\text{ttft}}$ 使指示函数归零，goodput 不是缓慢下降而是断崖式崩塌。第三，min 式是稳态流模型，不描述突发到达下的排队行为，P99 尾延迟需另用排队论或实测校正。</p>\n<p>系统代价体现在三处。其一是显存：分离后 KV cache 只落在解码池，预填池可把 HBM 几乎全部让给权重与激活，单卡可承载更长上下文，但代价是解码池单位 GPU 需容纳更多并发序列的 KV，$B s b_{kv}2L H_{kv}d_h$ 直接决定解码池的并发上限。其二是带宽：解码阶段每 token 都要把全部 KV 读一遍，HBM 带宽是硬约束，批大小 $B$ 增大虽摊薄权重读取，却线性推高 KV 字节，右项因此存在一个使吞吐最大的最优点而非越大越好。其三是功耗与配比僵化：静态 $N_p:N_d$ 在负载漂移时必然造成一侧闲置，弹性重配比需要请求路由层支持池间 GPU 重新划分，这本身带来调度延迟与冷启动开销。典型例子是长文档问答服务：提示动辄数万 token，预填池被长提示占满而解码池大量空转，此时若仍按 1:1 配比，TTFT 率先破线，goodput 归零；正确做法是把配比向预填池倾斜并引入分块预填，让长提示切片进入，避免单请求垄断整池。</p>\n<p>因此该模型的正确用法不是“算出一个数就照做”，而是把它当作配比搜索的判据：按目标负载代入 $P_{\\text{prefill}}$ 与每 token KV 字节，找出先饱和的一侧，再调整 $N_p:N_d$ 使两池吞吐尽量相等；同时必须监测实际先饱和的是哪一池，因为重尾与跨池迁移会让解析解偏离。工程判断落在一句话上：分离式部署的收益来自两池各自用最合适的并行策略与精度，而它的风险全部集中在“短板识别”——不监测先饱和侧、不把 KV 迁移项写进容量模型，min 式给出的乐观数字在真实集群里无法兑现。</p>\n<h3 id=\"th-disagg-goodput-sec-7\">七 · 两个分式的量纲对齐：为什么可以直接取 min</h3>\n<p>公式里两个分式看起来一个是“请求每秒”、一个是“token 每秒”，直接取 min 在量纲上并不显然成立。推导的第一步必须把它们统一到同一个计量单位上：全局 goodput 定义为“满足 SLO 的每秒钟完成的 token 数”。预填池的分式 <span class=\"inline-math\">N_p F_eff / P_prefill</span> 天然给出的是“每秒可预填的请求数”，要转成 token 速率，需要乘以该请求的 token 数 <span class=\"inline-math\">s</span>（输入长度）。于是预填池的 token 吞吐为 <span class=\"inline-math\">N_p F_eff s / P_prefill</span>，其中 <span class=\"inline-math\">P_prefill</span> 本身随 <span class=\"inline-math\">s</span> 线性增长，<span class=\"inline-math\">s</span> 被约掉，剩下的正是 <span class=\"inline-math\">N_p F_eff / (P_prefill/s)</span>——即“每 token 的预填 FLOPs”作分母。这就是公式中 <span class=\"inline-math\">P_prefill</span> 被写成“单请求预填 FLOPs”而非“单 token”的原因：它与 <span class=\"inline-math\">N_p</span> 组合后，隐含的约分让两个分式都落在 token 速率这一量纲上。工程含义是：预填池的产能与输入长度无关（在算力受限区），只与“每 token 摊到的算力”有关；这也是为什么长提示不会线性拖慢预填池的总 token 产能，却会线性拉长单请求的 TTFT。</p>\n<p>解码池的分式量纲更直接：<span class=\"inline-math\">BW_HBM</span> 是字节每秒，分母 <span class=\"inline-math\">B_act + B s b_kv 2 L H_kv d_h</span> 是每生成一个 token 需要从 HBM 读出的字节数，两者相除即 token 每秒。注意分母里 <span class=\"inline-math\">B</span> 是批内并发序列数、<span class=\"inline-math\">s</span> 是当前上下文长度：<span class=\"inline-math\">B_act</span> 是权重与激活的固定读取量（与批大小弱相关），第二项是 KV 读取量，随 <span class=\"inline-math\">B</span>、<span class=\"inline-math\">s</span> 线性增长。这一步是推导的关键：解码池的 token 速率不是常数，而是随上下文长度衰减的函数，这正是分离式部署中解码池“越跑越慢”的数学根源。</p>\n\n<h3 id=\"th-disagg-goodput-sec-8\">八 · 解码分母的逐项拆解与离散化位置</h3>\n<p>把 <span class=\"inline-math\">B s b_kv 2 L H_kv d_h</span> 拆开看：<span class=\"inline-math\">B</span> 条序列、每条 <span class=\"inline-math\">s</span> 个 token、每 token 每层存 K 和 V 两份（因子 2）、<span class=\"inline-math\">L</span> 层、<span class=\"inline-math\">H_kv</span> 个 KV 头、每头 <span class=\"inline-math\">d_h</span> 维、每元素 <span class=\"inline-math\">b_kv</span> 字节。这是连续形式的字节量。离散化发生在两处：其一，<span class=\"inline-math\">s</span> 在真实推理中是整数且按 block 对齐（paged KV 的 block size 通常是 16 或 32 token），所以实际读取量是 <span class=\"inline-math\">\\(ceil(s/block) \\cdot block\\)</span> 而非精确的 <span class=\"inline-math\">s</span>，短上下文时这一取整会带来可观的相对误差；其二，<span class=\"inline-math\">B</span> 在连续批处理下是随时间波动的随机过程，公式取的是稳态均值，瞬时值可能远高于或低于它。工程判断：容量规划时若按均值 <span class=\"inline-math\">B</span> 配 <span class=\"inline-math\">N_d</span>，在批到达的泊松波动下解码池会周期性越过 TPOT SLO，指示函数频繁归零，实测 goodput 低于公式预测——这不是公式错，而是把离散随机过程近似成了连续均值。</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{inst}} \\approx \\frac{B_{\\text{inst}}\\, s_{\\text{inst}}\\, b_{kv}\\, 2 L H_{kv} d_h + B_{\\text{act}}}{\\mathrm{BW}_{\\text{HBM}}\\cdot \\eta_{\\text{eff}}}$$</div>\n<p>这里引入 <span class=\"inline-math\">\\(\\eta_eff\\)</span> 是推导中被省略但工程上必须补的一步：HBM 带宽不会 100% 转化为有效 KV 读取，实际有效带宽受 bank 冲突、非合并访问、与权重读取争抢影响。公式用 <span class=\"inline-math\">BW_HBM</span> 的标称值，等价于假设 <span class=\"inline-math\">\\(\\eta_eff = 1\\)</span>，这是乐观上界。举例：一个 <span class=\"inline-math\">L</span> 层、<span class=\"inline-math\">H_kv</span> 头、<span class=\"inline-math\">d_h</span> 维的模型，在 <span class=\"inline-math\">B=64</span>、<span class=\"inline-math\">s</span> 增长到数千 token 时，KV 项远超 <span class=\"inline-math\">B_act</span>，解码池彻底进入带宽受限区，此时 <span class=\"inline-math\">\\(\\eta_eff\\)</span> 的 10% 偏差直接等价于 10% 的 goodput 偏差。</p>\n\n<h3 id=\"th-disagg-goodput-sec-9\">九 · 指示函数的硬截断与 SLO 的耦合结构</h3>\n<p>指示函数 <span class=\"inline-math\">\\(\\mathbb{1}[TTFT \\le S_ttft, TPOT \\le S_tpot]\\)</span> 不是装饰，它把“吞吐”与“时延”两个正交目标强行耦合：只要任一 SLO 被突破，整个 goodput 归零，而不是打折。这个设计的推导依据是：在 SLO 约束下，超时的请求对业务而言等同于未完成，其 token 不计入有效产出。因此 goodput 是“带约束的吞吐”，约束是硬的。关键推导步在于两个 SLO 分别绑定到两个池：TTFT 由预填池的排队与执行时间决定，TPOT 由解码池的单 token 迭代时间决定。这意味着 <span class=\"inline-math\">N_p</span> 的调整只影响 TTFT 项，<span class=\"inline-math\">N_d</span> 的调整只影响 TPOT 项——两池的容量决策在约束层面是解耦的，但在吞吐层面通过 min 耦合。</p>\n<p>代价体现在：为了让指示函数恒为 1，两池都必须留出时延余量，而余量直接吃掉吞吐。预填池若按“刚好满足 TTFT”配 <span class=\"inline-math\">N_p</span>，则无排队余量，突发到达即超时；解码池若按“刚好满足 TPOT”配 <span class=\"inline-math\">N_d</span>，则 <span class=\"inline-math\">B</span> 的瞬时峰值即超时。工程上的做法是把 SLO 阈值当作约束边界反解 <span class=\"inline-math\">N_p</span>、<span class=\"inline-math\">N_d</span> 的下界，再在 min 式上取等号附近工作，而不是把 min 式当无约束优化。举例：<span class=\"inline-math\">S_tpot</span> 给定后，解码池的可行 <span class=\"inline-math\">B</span> 上界由 <span class=\"inline-math\">\\(B \\le (S_tpot \\cdot BW_HBM - B_act)/(s b_kv 2 L H_kv d_h)\\)</span> 给出，这个上界随 <span class=\"inline-math\">s</span> 反比收缩，长上下文下解码池的批容量被 SLO 而非显存卡死——这是分离式部署中一个常被忽略的约束来源。</p>\n\n<h3 id=\"th-disagg-goodput-sec-10\">十 · 重尾分布下 min 式的失效与弹性重配比</h3>\n<p>公式隐含假设请求长度 <span class=\"inline-math\">s</span> 是同质的，或至少用均值代入即可。重尾分布打破这一假设：少数超长提示的 <span class=\"inline-math\">P_prefill</span> 极大，会独占预填池的算力槽位，使短请求的 TTFT 被排队拉长。此时预填池的“有效产能”不再是 <span class=\"inline-math\">\\(N_p F_eff / \\bar{P}_prefill\\)</span>，而是被最长请求的尾部分割后的碎片化产能。推导上的修正是在预填分式里引入尾部分位：用 <span class=\"inline-math\">P_prefill^{(q)}</span>（第 q 分位的预填量）替代均值，得到保守下界 <span class=\"inline-math\">N_p F_eff / P_prefill^{(q)}</span>。代价是：按分位配 <span class=\"inline-math\">N_p</span> 会让预填池在多数时间闲置，利用率下降，但换来指示函数不归零。</p>\n<p>静态配比 <span class=\"inline-math\">N_p:N_d</span> 在重尾下失效的机制是：配比按均值负载算出，长提示到达时预填池瞬间饱和，TTFT 越过 <span class=\"inline-math\">S_ttft</span>，指示函数归零，全局 goodput 崩塌——即使解码池此时大量空闲。工程判断是引入弹性重配比：监测两池的实时饱和度（预填池的排队深度、解码池的 KV 带宽占用率），在重尾到达时把 GPU 从解码池临时划给预填池。这一步的代价是重配本身有开销（重新加载权重、重建 KV 布局、迁移在途请求），重配频率与重配开销之间存在权衡；公式的静态形式无法表达这一动态，只能作为容量规划的下界参考。</p>\n\n<h3 id=\"th-disagg-goodput-sec-11\">十一 · KV 迁移项的加入与三瓶颈 min 式</h3>\n<p>当 KV cache 需要跨池传输时，公式的 min 式必须加入第三项。推导：设互连带宽为 <span class=\"inline-math\">BW_inter</span>，每 token 的 KV 字节量为 <span class=\"inline-math\">b_kv 2 L H_kv d_h</span>（与解码分母同源），则迁移侧的 token 速率为 <span class=\"inline-math\">BW_inter / (b_kv 2 L H_kv d_h)</span>。注意这一项不含 <span class=\"inline-math\">s</span> 与 <span class=\"inline-math\">B</span>：迁移是按 token 流式进行的，与上下文长度无关，只与总 token 流量有关。三瓶颈 min 式为：</p>\n<div class=\"formula\">$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d \\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h},\\ \\frac{\\mathrm{BW}_{\\text{inter}}}{b_{kv}2L H_{kv}d_h}\\right)\\cdot\\mathbb{1}[\\cdot]$$</div>\n<p>关键工程含义：迁移项的瓶颈位置取决于部署拓扑。若预填与解码同节点、走 NVLink，<span class=\"inline-math\">BW_inter</span> 高，迁移项通常不成为短板；若跨节点走 RDMA/NIXL，<span class=\"inline-math\">BW_inter</span> 低一个量级，迁移项极易成为实际瓶颈，而公式前两项仍显示“两池均衡”，造成规划幻觉。代价是：KV 迁移不仅占带宽，还占两池的 HBM 暂存与拷贝引擎，迁移期间解码池的 KV 读取带宽被挤占，<span class=\"inline-math\">\\(\\eta_eff\\)</span> 进一步下降。举例：长上下文、高并发的分离式部署中，KV 迁移流量与解码 KV 读取流量在同一 HBM 上竞争，实测 TPOT 高于仅按解码分式预测的值，差值正是迁移项未计入的部分。</p>\n\n<h3 id=\"th-disagg-goodput-sec-12\">十二 · 从公式到配比求解：等吞吐点的工程判据</h3>\n<p>容量规划的推导终点是求 <span class=\"inline-math\">N_p:N_d</span> 使两池吞吐相等，即令两个分式相等：<span class=\"inline-math\">N_p F_eff / P_prefill = N_d BW_HBM / (B_act + B s b_kv 2 L H_kv d_h)</span>。解出 <span class=\"inline-math\">\\(N_p/N_d = (P_prefill / F_eff) \\cdot (B_act + B s b_kv 2 L H_kv d_h) / BW_HBM\\)</span>。这个比值的物理意义是“预填每 token 的算力代价”与“解码每 token 的带宽代价”之比。工程判据：该比值随 <span class=\"inline-math\">s</span> 线性漂移，长上下文负载下解码侧代价上升，配比应向解码池倾斜；短提示高并发负载下预填侧代价主导，配比应向预填池倾斜。这意味着固定配比只对特定 <span class=\"inline-math\">s</span> 分布成立，任何跨负载复用的配比都需要按 <span class=\"inline-math\">s</span> 的分布重新求解。</p>\n<p>求解时的近似点在于：<span class=\"inline-math\">F_eff</span> 与 <span class=\"inline-math\">\\(\\eta_eff\\)</span> 都是负载相关的，前者受 MMA 利用率与批形状影响，后者受访问模式影响，公式把它们当常数处理。实际配比求解应把它们当作待标定的系数，用少量在线探测（例如在目标负载下测单池的实际 token 速率）反推有效值，再代入求解，而不是直接用标称峰值。这一步的代价是标定本身消耗产能，但相比配比失当导致的单侧闲置或 SLO 归零，标定开销可以忽略。最终落在具体机制上：配比不是一次性算出的静态数，而是随 <span class=\"inline-math\">s</span> 分布与两池饱和度持续重解的动态量，公式提供的是求解框架而非答案。</p>\n\n<h3 id=\"th-disagg-goodput-sec-13\">十三 · 公式的失效面：第三瓶颈、重尾与指示函数归零</h3>\n<p>该 min 式在工程上真正危险的地方，是它把系统描述成两个可独立饱和的资源池，而实际部署中两池之间往往存在一条被公式省略的通道。当 KV cache 不能留在解码池本地、必须从预填池跨池搬运时，互连带宽成为第三个约束项，min 式应扩展为 <span class=\"formula-inline\">min(预填吞吐, 解码吞吐, KV 迁移吞吐)</span>，其中迁移项形如 <span class=\"formula-inline\">BW_interconnect / (B·s·b_kv·2L·H_kv·d_h)</span>——分子是可用互连带宽，分母与解码池每 token KV 读取字节同构，只是乘上了跨池传输的放大系数。这一项的代价是双重的：它既占用 NVLink 或 RDMA 带宽，又与解码池的 HBM 读取争抢时间窗口，使得原本按算力配平的 N_p:N_d 在实际运行中偏向解码侧排队。判断是否落入该失效面的工程信号很直接——若解码池 TPOT 达标而端到端吞吐低于 min 式预测值，且互连利用率随并发上升，则第三瓶颈已经生效，此时继续加解码 GPU 只会加剧迁移压力。</p>\n<p>第二个失效面来自请求长度分布的重尾。公式中 P_prefill 与 KV 字节量都被当作目标负载下的代表值代入，但真实流量里少数超长提示会独占预填池的算力与显存窗口：一个长提示的预填 FLOPs 可达短提示的数十倍，它在预填池内停留的时间足以让后续请求的 TTFT 越过 S_ttft。指示函数是硬截断而非软惩罚，一旦越界，整项归零，goodput 不是缓慢下滑而是断崖式崩塌。这意味着静态配比 N_p:N_d 只在长度分布足够窄、方差可控时成立；重尾场景下必须引入弹性重配比——按滑动窗口内的提示长度分位数动态调整两池 GPU 数，或把长提示路由到专用预填实例，避免其污染主池的 TTFT 统计。代价是重配比本身有冷启动与显存重分配开销，频繁抖动会吃掉弹性带来的收益，因此重配周期应显著长于单请求生命周期。</p>\n<p>第三个易被忽视的边界是指示函数的耦合性。TTFT 与 TPOT 两个 SLO 并非独立：预填池的排队延迟会通过 KV 就绪时间传导到解码池的首 token 时刻，而解码池的批调度若为追求 TPOT 而缩小批，又会反过来降低 KV 生产速率、拉长预填池的驻留队列。公式用两个独立的 0/1 指示函数相乘，隐含假设两池的 SLO 违约互不相关，这在低负载下近似成立，在高负载下失效——此时应把指示函数替换为对联合分布的约束，或至少对两池分别保留安全裕量。工程判断上，容量规划应按目标负载的 P_prefill 与 KV 字节量代入两式找出先饱和的一侧，但配比调整必须留出应对重尾与迁移项的余量，而不是把两池吞吐配到严格相等——相等意味着任何扰动都会立刻把短板推向另一侧。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式缺口</th><th>系统代价</th></tr></thead><tbody><tr><td>KV 跨池传输</td><td>缺 KV 迁移项</td><td>互连带宽争抢，吞吐低于预测</td></tr><tr><td>长度重尾</td><td>P_prefill 视为定值</td><td>TTFT 越界，指示函数归零</td></tr><tr><td>两池 SLO 耦合</td><td>指示函数独立相乘</td><td>高负载下违约相关性被低估</td></tr></tbody></table>\n<h3 id=\"th-disagg-goodput-sec-14\">十四 · 指示函数不是软约束：SLO 越界即归零的硬截断</h3>\n<p>公式末尾那个 <span class=\"formula\">$$\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$</span> 常被误读成“性能打折系数”，实际是硬门控：任一条件不满足，整条 goodput 归零，而不是按比例衰减。这意味着模型的适用边界首先由 SLO 的可达性决定，而非由两个 min 项的数值大小决定。工程上必须把 SLO 判定放在容量规划的第一步：先验证在目标负载下两池各自的尾延迟能否压进阈值，再谈配比优化。若 TTFT 的 P99 已经贴着 <span class=\"formula\">$$S_{\\text{ttft}}$$</span>，那么任何提高预填池利用率的动作（更大批、更长排队）都会把指示函数打成 0，此时 min 式算出的“理论吞吐”毫无意义。</p>\n<p>机制上，TTFT 由预填池的排队时延加单请求预填执行时延构成，前者随批内 token 总数增长而非线性上升；TPOT 则由解码池每步的 KV 读取与集合通信主导。两者对批大小的敏感方向相反：预填池增大批提升算力利用率却推高排队，解码池增大批摊薄权重读取却拉长单步。因此指示函数的可行域是一个由两个 SLO 围出的窄带，模型只在这个窄带内成立。代价上，为守住 SLO 而人为压低预填批，会让预填池的 <span class=\"formula\">$$N_p F_{\\text{eff}}/P_{\\text{prefill}}$$</span> 项显著低于解码池项，min 取小后整体 goodput 被预填侧锁死——这是“SLO 达标但吞吐平庸”的典型形态。例子：长上下文对话场景中，单请求预填 FLOPs 随提示长度线性增长，若为压 TTFT 而限制并发预填数，预填池实际吞吐远低于其算力上限，此时正确判断是增加 <span class=\"formula\">$$N_p$$</span> 而非放宽 SLO。</p>\n\n<h3 id=\"th-disagg-goodput-sec-15\">十五 · 第三瓶颈：KV 跨池迁移项的缺席与补入</h3>\n<p>原式的两个分母各自只描述池内瓶颈，隐含假设是 KV cache 在解码池本地生成、本地消费。一旦预填与解码物理分离且不共享 HBM，预填产出的 KV 必须经互连搬到解码池，迁移带宽就成为 min 式之外的第三项。补入后的形式应为三项取小：池内预填吞吐、池内解码吞吐、以及 <span class=\"formula\">$$\\frac{\\mathrm{BW}_{\\text{link}}}{B_{\\text{kv}}}$$</span> 形式的迁移吞吐（<span class=\"formula\">$$B_{\\text{kv}}$$</span> 为单请求 KV 字节量，<span class=\"formula\">$$\\mathrm{BW}_{\\text{link}}$$</span> 为可用互连带宽）。NVLink 5 与 NIXL 这类传输层决定了这一项的实际上限；当 KV 字节量与请求到达率之积逼近链路带宽，迁移项会先于两个池内项饱和。</p>\n<p>关键在于量纲对齐：迁移是突发性的，预填完成一个请求就触发一次整块 KV 搬运，其瞬时带宽需求等于 KV 字节量除以预填完成间隔。若预填池以高并发运行，多个请求的 KV 搬运会在时间上叠加，链路出现排队，反过来拖慢预填池的槽位释放，形成正反馈式的拥塞。代价表现为 TTFT 尾部抬升（等待迁移完成才算预填结束）与解码池首 token 前的空转。例子：在 NVL72 机架内预填与解码分置不同 GPU 组时，若 KV 经机架内 NVLink 交换，链路带宽充裕但交换结构存在竞争；跨机架则必须走更窄的链路，迁移项极易成为实际短板。判断准则：当 <span class=\"formula\">$$B_{\\text{kv}}\\times \\text{请求率}$$</span> 超过链路可用带宽的一半，就必须把迁移项写进模型，否则预测吞吐系统性偏高。</p>\n\n<h3 id=\"th-disagg-goodput-sec-16\">十六 · 重尾长度分布：静态配比 N_p:N_d 的失效机制</h3>\n<p>min 式里的 <span class=\"formula\">$$P_{\\text{prefill}}$$</span> 与 <span class=\"formula\">$$B_{\\text{kv}}$$</span> 都是单请求量，模型默认负载由某个代表值刻画——这在长度分布集中时成立，在重尾分布下失效。重尾意味着少数超长提示贡献了大部分预填 FLOPs 与 KV 字节，而它们的到达是随机的。静态配比 <span class=\"formula\">$$N_p:N_d$$</span> 按平均负载设定，遇到长提示簇发时预填池被瞬间占满，排队时延把 TTFT 推过 <span class=\"formula\">$$S_{\\text{ttft}}$$</span>，指示函数归零，goodput 骤降；而长提示稀疏时预填池又大量闲置，解码池成为唯一瓶颈。</p>\n<p>机制上，预填池的服务时间对提示长度是超线性的（注意力部分随长度平方增长），因此重尾分布下的排队系统不是简单的 M/G/1，长请求会“锁住”槽位并放大后续请求的等待。这使静态配比在两种状态间振荡：要么预填侧 SLO 破裂，要么预填资源浪费。工程对策是弹性重配比——按滑动窗口内的长度分布实时调整两池 GPU 划分，或引入预填池的抢占式调度，把长提示拆块分片以缩短单槽占用。代价是重配比本身需要迁移模型状态或重新划分实例，带来秒级的容量抖动；分片预填则增加 KV 拼接与跨片通信开销。例子：代码补全与长文档问答混跑的负载中，长文档请求占比虽低但单请求预填量极高，固定配比下这些请求会周期性击穿 TTFT SLO，正确做法是为长提示保留专用预填槽位并对其单独计量。</p>\n\n<h3 id=\"th-disagg-goodput-sec-17\">十七 · 规模上限：两池独立假设在小规模与大集群两端的破裂</h3>\n<p>模型假设两池的吞吐可独立计算再取小，这要求池内资源充分并行、池间耦合可忽略。规模过小时，单池 GPU 数不足以隐藏单请求的执行时延：预填池若只有个位数 GPU，一个长请求的预填充就能占满全部算力，此时“池吞吐”退化为“单请求时延的倒数”，min 式的连续近似失效，必须改用离散的排队仿真。规模过大时，池内集合通信（张量并行、专家并行的 All-to-All）开始主导，<span class=\"formula\">$$F_{\\text{eff}}$$</span> 不再是常数而是随并行度下降的函数，解码池的 <span class=\"formula\">$$\\mathrm{BW}_{\\text{HBM}}$$</span> 有效值也被通信挤占。</p>\n<p>具体机制：解码池的每 token KV 读取在张量并行下被切分到多卡，单卡读取量下降但需 All-Reduce 汇总，通信时延随卡数对数增长；当 TPOT 的通信分量超过 KV 读取分量，继续加卡不再提升解码吞吐，min 式的解码项饱和。预填池同理，专家并行下 token 路由的 All-to-All 在批内 token 数大时成为瓶颈，<span class=\"formula\">$$F_{\\text{eff}}$$</span> 随专家并行度衰减。代价上，大集群的功耗与散热约束还会反过来限制可持续的 GPU 密度，使名义 <span class=\"formula\">$$N_p$$</span>、<span class=\"formula\">$$N_d$$</span> 无法全部满载运行。例子：在 NVL72 级别的机架内做大规模分离式部署，解码池跨节点张量并行时 TPOT 的通信占比显著上升，此时模型预测的线性扩容不再成立，应改用“通信受限”的修正项替代常数带宽。</p>\n\n<h3 id=\"th-disagg-goodput-sec-18\">十八 · 何时该弃用公式：从解析模型退回测量驱动</h3>\n<p>公式的价值在于给出配比的一阶估计与短板定位，但其成立需要三个前提同时满足：SLO 可达、KV 本地消费或迁移带宽充裕、长度分布可用单值代表。任一前提破裂，解析式就从预测工具退化为误导来源。工程判断应遵循一条分界线：当负载的变异系数低、互连带宽余量充足、两池并行度足以隐藏单请求时延时，用公式做容量规划；否则以测量驱动的小规模仿真替代，把公式仅作为仿真初值的设定依据。</p>\n<p>具体做法是把公式的每一项变成可观测指标而非假设常数：持续监测预填池的实际 <span class=\"formula\">$$F_{\\text{eff}}$$</span>、解码池的实际 KV 读取带宽占比、以及 KV 迁移链路的利用率，三者中任一项逼近饱和即触发配比重估。误用后果已在失效条件中写明——忽略迁移项导致预测吞吐无法达到，静态配比在重尾下使 goodput 崩塌。更隐蔽的一种误用是把指示函数当作惩罚项去做梯度式优化，实际上它不可微且是二值的，优化目标应是先扩大可行域（加 GPU、放宽 SLO 或分片预填），再在可行域内做 min 项的均衡。最终落点：goodput 模型的适用边界本质上是“两个池内瓶颈与一个池间瓶颈同时可控”的边界，容量规划的第一动作永远是识别当前负载下这三个瓶颈中哪一个最先饱和，而不是套用公式算出配比。</p>\n\n\n<h3 id=\"th-disagg-goodput-sec-19\">十九 · 边界之外：当 min 式不再成立</h3>\n<p>把 goodput 写成两池吞吐取小，前提是两池之间不存在第三个共享资源。一旦预填与解码不在同一 NVLink 域内、KV cache 必须跨池搬运，这个前提就破了：每生成一个 token，解码侧要么回读远端 KV，要么预填侧持续把新块推过去，互连带宽成为独立于 HBM 带宽与算力的约束。此时 min 式应扩展为三项取小，第三项形如 <span class=\"formula\">$$ \\frac{\\mathrm{BW}_{\\text{link}}}{\\beta\\, b_{kv}\\,2L H_{kv} d_h} $$</span>，其中 β 是每 token 需要跨池搬运的 KV 比例（取决于块放置策略与复用命中率）。工程上判断是否越界的方法很直接：比较 KV 迁移所需带宽与解码池 HBM 读取带宽的量级，若前者不可忽略，则容量规划中只按两池算力配比就会系统性高估吞吐——这正是“忽略 KV 跨池迁移带宽”这一类误用的根源，预测值在纸面上漂亮，实测却被一条隐藏链路锁死。</p>\n<p>第二个失效条件是请求长度分布的重尾性。静态配比 N_p:N_d 的隐含假设是预填负载与解码负载按固定比例随时间到达，两池各自被平稳占满。重尾分布下，少量超长提示会集中占据预填池的算力与显存，使预填队列排空时间被单个长请求拉长，TTFT 越过 S_ttft，指示函数整体归零——注意这不是吞吐下降，而是 goodput 直接塌到零，因为 SLO 是硬截断而非软惩罚。此时正确做法不是加大 N_p，而是让配比随队列状态弹性重配：把空闲解码卡临时划入预填、或对长提示做分块预填以打断其对池的独占。代价是重配本身引入调度抖动与 KV 块迁移，需要以块为粒度而非以请求为粒度做迁移，否则重配开销会吃掉收益。</p>\n<p>第三个边界是规模上限。两池吞吐取小的模型假设每池内部可以线性扩展——N_p 与 N_d 增加，吞吐同比增加。但预填池的有效算力 F_eff 会随并行度上升而衰减：TP 扩大带来更细的切分与更多集合通信，EP 扩大带来更重的路由与负载不均，2-SM MMA 与 TMEM 的占用也限制了可并发的请求数。解码池同理，HBM 带宽在 TP 组内被分摊，TPOT 随 TP 增大而改善的曲线会饱和。因此 min 式中的 N_p、N_d 只在中等规模区间近似线性，超出后应把 F_eff 与有效带宽写成并行度的函数再代入，否则配比会偏向“多加卡就能救”的错误直觉。规模上限的另一个表现是单池内部的排队效应：当请求数接近池的并发上限，尾延迟抬升使 SLO 指示函数在平均吞吐尚未饱和时就翻零。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>公式修正</th><th>系统代价</th></tr></thead><tbody><tr><td>KV 跨池传输</td><td>min 式加互连带宽项</td><td>链路带宽占用、迁移延迟抬升 TPOT</td></tr><tr><td>重尾请求分布</td><td>N_p:N_d 变为时变量</td><td>重配抖动、块迁移开销</td></tr><tr><td>超中等规模</td><td>F_eff、有效带宽随并行度衰减</td><td>集合通信与路由开销、尾延迟</td></tr></tbody></table>\n<p>把这些边界统一起来看，min 式的适用域可以概括为：单一 NVLink 域、长度分布可控、并行度处于线性区。三者任一不满足，容量规划就必须从“解一个取小方程”退化为“监测先饱和的一侧并动态重配”。工程判断的落点是监控项而非公式项：持续采集两池的队列深度、TTFT 与 TPOT 的分位值、以及跨池 KV 流量占链路带宽的比例，用实测的先饱和侧去校正 N_p:N_d，而不是让静态配比在重尾流量下把 goodput 锁死在短板。</p>\n<h3 id=\"th-disagg-goodput-sec-20\">二十 · 把 min 式读成两条“产能曲线”</h3>\n<p>在容量决策里，这个公式不该被当成一个求值的标量，而应被读成两条关于配比 <em>r</em>=N_p/N_d 的产能曲线：预填侧 <em>G_p(r)</em>=N_p·F_eff/P_prefill 随 r 线性上升，解码侧 <em>G_d(r)</em>=N_d·BW_HBM/(B_act+B·s·b_kv·2L·H_kv·d_h) 随 r 线性下降。两条直线的交点就是“两池同时饱和”的理想配比，而 goodput 永远落在较低的那条线上。工程含义很直接：**配比不是拍脑袋定的，而是解一个交点方程**。当负载画像（P_prefill、每 token KV 字节）变化时，交点平移，静态配比立刻变成短板。因此定配比的第一步不是算 GPU 数，而是先测出本负载下两条直线的斜率——预填侧斜率由 F_eff/P_prefill 决定，解码侧斜率由 BW_HBM/每 token KV 字节决定。斜率之比即两池的“产能密度比”，它才是配比的物理依据。</p>\n<p>伪代码思路：给定负载画像与总卡数 N_total，先算两条直线的斜率 k_p、k_d，再解 N_p·k_p = (N_total−N_p)·k_d，得到 N_p* = N_total·k_d/(k_p+k_d)。这一步只用到除法与一次线性求解，可以在容量规划脚本里对每个候选负载画像批量跑。代价面：交点算错一个方向，就意味着另一侧池子的 GPU 在空转——预填池闲置浪费的是算力预算，解码池排队浪费的是 SLO 余量，两者都直接压低 goodput，且后者会通过指示函数把 goodput 直接归零。</p>\n\n<h3 id=\"th-disagg-goodput-sec-21\">二十一 · 用指示函数反推批大小与 KV 预算</h3>\n<p>指示函数 𝟙[TTFT≤S_ttft, TPOT≤S_tpot] 不是装饰，它是把“产能”翻译成“可用产能”的开关。定批大小时的正确顺序是：先由 TPOT SLO 反推解码池每卡可承载的并发序列数，再由此反推 KV 预算，最后才由预填池的 TTFT SLO 决定预填批大小。解码侧每 token 的 KV 读取字节为 B_act+B·s·b_kv·2L·H_kv·d_h，其中 B 为批内序列数、s 为序列长度；TPOT 近似正比于该字节量除以 BW_HBM，于是 TPOT≤S_tpot 给出 B 的上界：B ≤ (BW_HBM·S_tpot − B_act)/(s·b_kv·2L·H_kv·d_h)。这个上界随序列长度 s 反比收缩，说明**批大小不是常数，而是序列长度的函数**——长上下文请求天然只能配小批，这正是连续批处理需要按长度分桶的原因。</p>\n<p>KV 预算则由同一不等式反解：在给定 B 与 S_tpot 下，允许的最大 s 就是 KV 预算的边界，超出即 TPOT 越界、指示函数归零。工程上把它写成“每卡 KV 预算 = B·s_max·每 token KV 字节”，并与显存容量式（见 KV cache 显存占用式条目）对齐，两者取小。具体例子：一个解码池若 TPOT SLO 收紧，B 的上界随之下降，KV 预算被动收缩，此时若仍按旧批大小跑，解码池会先饱和，goodput 被 min 式锁死在解码侧——这正是“调 SLO 等于调容量”的机制来源。</p>\n\n<h3 id=\"th-disagg-goodput-sec-22\">二十二 · 定并行度：TP 与 EP 如何进入两条直线</h3>\n<p>并行度决策的本质是改变两条直线的斜率。张量并行 TP 增大时，单卡承担的权重与激活字节下降，B_act 项被摊薄，解码侧斜率上升；但同时每层需要 all-reduce，通信开销进入 TPOT 的有效带宽项，等效 BW_HBM 被折减。于是解码侧斜率并非随 TP 单调上升，而是存在一个由“字节摊薄收益”与“集合通信代价”相抵的拐点。预填侧同理：TP 提高使单卡 F_eff 的有效算力上升，但 P_prefill 的切分带来额外同步，斜率增益递减。定并行度的判据因此是：**选择使两池斜率之比最接近当前 N_p:N_d 的那个 TP 配置**，而不是孤立地追求单池最快。</p>\n<p>专家并行 EP 在解码侧的作用更微妙：它把 MoE 层的权重读取分散到多卡，降低单卡 B_act 中的权重项，但引入 All-to-All 通信（其下界见专家并行 All-to-All 下界条目）。在分离式部署中，EP 度提高会同时抬高解码侧斜率与通信延迟，前者利、后者害，净效应取决于 batch 大小——大批时字节摊薄收益占优，小批时通信延迟占优。这就是为什么解码池的 EP 配置必须与批大小联动决策，而不能独立定。代价面：并行度配错的直接表现是解码池 TPOT 越界或预填池 TTFT 越界，指示函数归零，goodput 从“受 min 约束”退化为“零”。</p>\n\n<h3 id=\"th-disagg-goodput-sec-23\">二十三 · 算例：从 SLO 反推 N_p:N_d 与批大小</h3>\n<p>设总卡数 N_total 固定，负载画像给出预填侧斜率 k_p 与解码侧斜率 k_d（由 F_eff/P_prefill 与 BW_HBM/每 token KV 字节算出，均为定性量级，此处只走流程不填实验数）。第一步解交点得 N_p*、N_d*；第二步用 TPOT SLO 反解解码池批上界 B_max；第三步用 TTFT SLO 反解预填池批上界——预填池的 TTFT 近似正比于 P_prefill/(N_p·F_eff) 加上排队项，故 TTFT≤S_ttft 给出单请求预填时延上界，进而给出预填批的并发上限。第四步校验：把 B_max 与预填批上限代回 min 式，若两池吞吐接近相等，配比成立；若预填侧明显偏低，说明 N_p 不足或 P_prefill 画像偏重，需上调 N_p 或对长提示做分桶限流。</p>\n<p>算例的工程价值在于暴露隐藏瓶颈：若 KV cache 需跨池传输，min 式必须加入 KV 迁移项——迁移字节量为每请求 KV 总量，迁移带宽由互连决定（NVLink 5 域内与跨域差异极大，见并行与通信条目）。此时即便两池算力配比完美，KV 迁移仍可能成为第三瓶颈，实际 goodput 低于 min 式预测。校验步骤因此必须包含“迁移项是否小于两池吞吐”的判断，否则配比只是纸面最优。代价面：迁移项一旦成为短板，表现为解码池等 KV、预填池已释放，两池都“看起来没满”但全局吞吐上不去，这是分离式部署最典型的隐性损失。</p>\n\n<h3 id=\"th-disagg-goodput-sec-24\">二十四 · 重尾负载下的弹性重配比</h3>\n<p>静态配比在重尾请求分布下失效的机制是：长提示把预填池的 P_prefill 总量瞬间抬高，预填侧直线整体下移，交点向解码侧偏移，而 N_p:N_d 未变，于是预填池先饱和、TTFT 越 SLO、指示函数归零。对策不是简单加大 N_p，而是**按请求长度分桶做弹性重配比**：短提示桶走低 P_prefill 配比，长提示桶走高 N_p 配比，两桶共享同一批 GPU 但按时间片切换。实现上需要一个监测先饱和侧的反馈环——持续采样两池的实际利用率与 SLO 余量，当预填侧利用率逼近 1 且 TTFT 余量收窄时，把 N_d 的卡临时划给预填池。代价面：重配比本身有冷启动与 KV 迁移成本，切换频率过高会引入抖动，因此反馈环需要滞回区间，避免在交点附近来回震荡。</p>\n<p>监测的判据应落在公式的两个分子上，而不是落在 GPU 利用率这种间接指标：预填侧看 N_p·F_eff/P_prefill 的实际达成率，解码侧看 N_d·BW_HBM/每 token KV 字节的实际达成率，两者之比偏离 1 超过阈值即触发重配比。这样做的原因是利用率可以被排队掩盖——预填池利用率 100% 可能只是队列长，而非产能真被吃满。把监测锚定在公式项上，才能让弹性重配比与容量模型同源，避免“模型算一套、运维看另一套”的割裂。</p>\n\n<h3 id=\"th-disagg-goodput-sec-25\">二十五 · 误用清单与工程判断</h3>\n<p>三类误用都可追溯到公式的某一项被忽略。其一，只按两池算力做静态配比而不监测先饱和侧，等于假设交点永远不动，实际负载画像一变就单侧闲置或排队，goodput 被短板锁死。其二，忽略 KV 跨池迁移带宽，min 式少了一项，预测吞吐达不到，且故障表现为“两池都不满却上不去”，排查成本高。其三，重尾分布下沿用固定 N_p:N_d，长提示占满预填池使 TTFT 越 SLO，指示函数归零导致 goodput 骤降——注意这里是**归零而非下降**，因为指示函数是硬截断，SLO 一破，产能再高也不计入 goodput。这三条的共性是把公式当成一次性计算，而不是当成需要在线校准的决策环。</p>\n<p>工程判断落在一句话上：**goodput 模型的输出不是配比数字，而是“当前先饱和的是哪一侧”这个诊断**。定批大小、定并行度、定 KV 预算、定 SLO 四件事，本质上都是在移动两条直线的斜率或交点，而每一次移动都必须回读 min 式确认短板没有换边。把公式嵌进容量规划脚本、把两项达成率嵌进在线监测、把重配比嵌进调度器，三者同源，才是分离式部署下 goodput 可控的前提。</p>\n\n<h3 id=\"th-disagg-goodput-sec-26\">二十六 · 配比求解的反问题：从 SLO 倒推 N_p:N_d 与 KV 预算</h3>\n<p>把公式当正问题用只能算出一个 goodput 数，真正在容量决策里要做的是反问题：给定 SLO 阈值 S_ttft、S_tpot 与目标负载画像，解出让两池同时逼近饱和的 N_p:N_d。做法是把 min 的两项写成等式——<span class=\"formula\">$$N_p F_{\\text{eff}}/P_{\\text{prefill}} = N_d \\mathrm{BW}_{\\text{HBM}}/(B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h)$$</span>——再叠加总卡数约束 N_p+N_d=N_total，得到闭式配比。注意分母第二项随批大小 B 线性增长，因此配比不是常数：B 越大，解码池每 token 的 KV 读取字节越重，需要更多 N_d 才能与预填池对齐。这意味着定批大小与定并行度是同一个方程的两个未知量，必须联立求解，而不是先拍一个 batch size 再分配 GPU。工程上更稳的做法是固定 B 的上界（由 TPOT SLO 反推），再解 N_p:N_d，因为 B 一旦越过 TPOT 约束，指示函数直接归零，配比再优也无意义。</p>\n<p>KV 预算同样从这条式子倒推。解码池可容纳的并发序列数受 HBM 容量约束，而每序列 KV 字节为 <span class=\"formula\">$$2L H_{kv} d_h s b_{kv}$$</span>（s 为序列长度），把它乘以目标并发数即为 KV 预算下限；预算不足时只能降 B 或降并发，两者都会推高 TPOT。这里存在一个容易被忽略的耦合：降 B 会减小每 token 的 KV 读取量、改善 TPOT，但同时降低解码池吞吐，使 min 式的解码侧变小，配比需要重新向 N_d 倾斜。所以 KV 预算、批大小、并行度三者构成一个闭环，任何一项调整都要回到 min 式重算，静态一次性规划在负载漂移下必然失准。</p>\n<p>算例：设预填池单卡有效算力记为 F_eff、单请求预填量 P_prefill 为某定值，解码侧每 token KV 字节记为 K_tok。若初始按 1:1 分配 N_p=N_d，代入后发现预填侧吞吐明显低于解码侧，说明预填池先饱和，goodput 被预填锁死，此时应把部分解码卡划给预填，直到两侧吞吐相等；反之若 K_tok 因长上下文或大 B 而膨胀，解码侧先饱和，则需反向调整。判断依据不是瞬时利用率，而是两式比值是否偏离 1——偏离方向就是该补卡的方向。这个比值应作为在线监控指标持续采样，而不是部署时算一次。</p>\n<p>边界与代价必须写清楚。第一，一旦 KV cache 跨池传输，min 式要加第三项 KV 迁移吞吐，互连带宽成为新的短板；此时即便两池算力配比完美，实际 goodput 仍被迁移项压住，且迁移带来的额外延迟会侵蚀 TTFT 余量。第二，请求长度重尾时预填池被长提示占满，静态 N_p:N_d 失效，必须做弹性重配比——代价是重配比期间存在迁移与冷启动开销，频繁重配本身会吃掉一部分 goodput，因此重配比要有滞回与最小驻留时间。第三，指示函数的硬截断意味着 SLO 附近是悬崖而非斜坡：TTFT 或 TPOT 略微越界即整体归零，容量规划必须留出余量而不是贴着阈值配比。最后，只按算力配比而不监测先饱和侧，会造成一侧闲置、一侧排队，短板锁死全局——这正是该模型在工程上最典型的失效方式。</p>\n<h3 id=\"th-disagg-goodput-sec-27\">二十七 · 误用一：把 min 式当成“算力配比公式”</h3>\n<p>最常见的误用，是把 goodput 公式里的两项当成“两池各自能跑多快”，然后按 <span class=\"sym\">N_p</span>:<span class=\"sym\">N_d</span> 正比于两项数值去分配 GPU。这忽略了 min 的语义：它取的是短板，不是加和，也不是平均。若预填池算出 1200 tok/s、解码池算出 800 tok/s，把 GPU 按 3:2 分完之后，预填池仍会空出一截算力，而解码池持续排队——全局 goodput 锁死在 800 tok/s，多出来的预填容量对吞吐毫无贡献，只贡献了功耗与闲置。</p>\n<p>识别方法很直接：在压测中同时采样两池的 GPU 利用率与队列深度。若一侧 SM 占用长期低于目标水位而另一侧队列单调增长，说明配比偏离了等吞吐点。正确的调整方向是把 GPU 从利用率低的一侧挪向排队的一侧，直到两池的“边际吞吐/GPU”相等。工程上可用一个简单判据：设两池实测吞吐为 <span class=\"sym\">T_p</span>、<span class=\"sym\">T_d</span>，若 <span class=\"sym\">T_p</span>/<span class=\"sym\">N_p</span> &gt; <span class=\"sym\">T_d</span>/<span class=\"sym\">N_d</span>，则预填池相对富余，应减 <span class=\"sym\">N_p</span> 增 <span class=\"sym\">N_d</span>。代价是每次重配比都涉及实例重建与 KV 路由表更新，不能按秒级做，只能按分钟级或按负载形态切换。</p>\n<p>具体例子：一个以短提示、长输出为主的对话负载，解码池每 token 要读的 KV 字节量随上下文线性增长，解码侧先饱和；此时若仍按“预填 FLOPs 大所以多给预填 GPU”的直觉配比，等于把预算投在了非瓶颈侧。反过来，长文档摘要类负载预填 FLOPs 占主导，多给解码池同样是浪费。</p>\n\n<h3 id=\"th-disagg-goodput-sec-28\">二十八 · 误用二：漏掉 KV 迁移项，把互连当免费</h3>\n<p>公式在适用边界里明确写了：KV cache 需跨池传输时，互连带宽成为第三瓶颈，min 式要加入 KV 迁移项。误用者往往只按两池的 HBM 带宽与算力配比，默认 KV 从预填池到解码池的搬运不花时间。实际部署中，每个请求的 KV 字节量为 <span class=\"sym\">B s b_kv 2 L H_kv d_h</span>，预填完成后必须整块送到解码池所在 GPU，这笔流量走的是池间互连而非 HBM，带宽量级与 HBM 不同，且与解码池的 KV 读取争用同一条链路时会更糟。</p>\n<div class=\"formula\">$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d \\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2LH_{kv}d_h},\\ \\frac{\\mathrm{BW}_{\\text{link}}\\,N_{\\text{link}}}{B s b_{kv}2LH_{kv}d_h}\\right)$$</div>\n<p>第三项的分母与解码池每 token 的 KV 字节同形，但分子换成互连带宽与链路数——含义是“KV 搬运能支撑多少请求的预填-解码交接”。当上下文很长时，这一项常常比前两项更早触底。识别信号：预填池 TTFT 达标、解码池 TPOT 达标，但端到端吞吐上不去，且池间链路利用率接近饱和；或者增大 <span class=\"sym\">N_d</span> 后吞吐不升反降，因为更多解码实例意味着更多跨池拉取。</p>\n<p>具体例子：长上下文 RAG 场景，单请求 KV 体量随上下文线性膨胀，预填池算力充足、解码池 HBM 带宽也够，但每交接一个请求就要搬一次整块 KV，链路成为实际瓶颈。此时正确的动作不是加 GPU，而是减少跨池交接次数——例如让同一会话的后续请求尽量落在同一解码实例、或对超长上下文采用预填与解码同池的混合部署。代价是调度复杂度上升，收益是避免把预算投在非瓶颈资源上。</p>\n\n<h3 id=\"th-disagg-goodput-sec-29\">二十九 · 误用三：重尾分布下沿用静态配比</h3>\n<p>公式的指示函数是硬截断：TTFT 一旦越过 <span class=\"sym\">S_ttft</span>，整项归零。静态配比在长度分布集中时表现良好，但真实流量是重尾的——少量超长提示会占满预填池的批次槽位，把排在后面的短请求 TTFT 一起拖过 SLO。此时不是“吞吐下降一点”，而是指示函数归零、goodput 崩塌，因为 SLO 是硬约束而非软惩罚。</p>\n<p>机制上，预填池的批处理按 token 预算装箱，一个超长提示可能独占数个迭代周期，短请求被迫等待。识别方法：按请求长度分桶统计 TTFT 的 P99，若长桶的 TTFT 显著越线而短桶正常，且预填池队列中长请求占比与流量占比不符（长请求滞留更久），即为重尾挤压。应对不是简单加 <span class=\"sym\">N_p</span>，而是弹性重配比加准入控制：给长提示单独划出预填容量或限流，短请求走快速通道；或在检测到长请求占比上升时按分钟级扩容预填池、压缩解码池。</p>\n<p>具体例子：一个混合了代码补全（短提示、短输出）与长文档问答（超长提示）的负载，静态 1:1 配比下，少量长文档请求周期性占满预填池，代码补全的 TTFT 被推过 SLO，整体 goodput 归零的时间段与长文档到达的突发对齐。把长文档请求隔离到独立预填队列并限制并发后，短请求的 TTFT 回到 SLO 内，全局 goodput 恢复——尽管总 GPU 数没变。</p>\n\n<h3 id=\"th-disagg-goodput-sec-30\">三十 · 反例：一次“加机器反而更慢”的扩容</h3>\n<p>设一个分离式部署，预填池与解码池各若干 GPU，负载以中等长度提示、中等长度输出为主，当前两池吞吐接近相等，goodput 稳定在 SLO 内。运维看到解码侧队列偶有堆积，决定扩容：把新增 GPU 全部投入解码池，<span class=\"sym\">N_d</span> 增大而 <span class=\"sym\">N_p</span> 不变。</p>\n<p>结果与预期相反：解码池单实例的 KV 读取被更多实例分摊后，每实例的批规模下降，HBM 带宽利用率反而走低；同时更多解码实例意味着更多跨池 KV 拉取请求，池间链路流量上升，KV 迁移项开始触底。更关键的是，预填池没扩容，预填吞吐不变，解码池再多也只能消费预填池产出的请求——min 式里第一项成了新的短板。整体 goodput 不升，端到端延迟因链路争用而变差，功耗因新增 GPU 空转上升。</p>\n<p>这个反例的诊断路径是标准的：先看两池实测吞吐与利用率，确认预填池已满负荷而解码池未饱和；再看池间链路利用率，确认 KV 迁移项是否已接近 min；最后核对请求长度分布，确认没有重尾挤压。三步都指向同一结论——扩容投在了非瓶颈侧，且引入了第三瓶颈。正确动作是把新增 GPU 按等吞吐点分配，或先解决 KV 交接的链路瓶颈再谈扩容。</p>\n<p>反例的工程含义：goodput 模型的 min 结构决定了扩容必须针对当前短板，而短板会随配比与负载形态漂移。把模型当成一次性规划工具、配比定死不再监测，等于放弃了它最有价值的部分——持续识别“此刻谁在拖后腿”。监测项至少包括两池吞吐/GPU、两池队列深度、池间链路利用率、按长度分桶的 TTFT P99；任一项偏离等吞吐点，就是重配比的信号。</p>\n\n<h3 id=\"th-disagg-goodput-sec-31\">三十一 · 误用与反例：当 min 式被当成静态配比表</h3>\n<p>最常见的误用不是公式写错，而是把 min 式当成一次性容量规划表：上线前按平均负载解出 N_p:N_d，之后不再监测哪一池先饱和。后果是短板锁死全局——预填池闲置而解码池排队，或反过来预填池被长提示占满。识别信号很直接：两池 GPU 利用率长期不对称，且低利用一侧的排队延迟仍在上升，说明瓶颈不在算力而在另一池的 KV 带宽或互连。工程上必须把 min 式当作在线观测量而非离线常量：分别采样预填池的每请求预填 FLOPs 与解码池的每 token KV 读取字节量，代入两分支得到瞬时吞吐上界，再与实际 token 产出比对，偏差持续存在即说明有未建模的第三瓶颈。</p>\n<p>第二个误用是忽略 KV 跨池迁移项。分离式部署中，预填产生的 KV cache 必须搬到解码池，互连带宽因此成为独立瓶颈。此时 min 式需扩展为三路取小：</p>\n<div class=\"formula\">$$\\mathrm{Goodput}=\\min\\!\\left(\\frac{N_p F_{\\text{eff}}}{P_{\\text{prefill}}},\\ \\frac{N_d \\mathrm{BW}_{\\text{HBM}}}{B_{\\text{act}}+B s b_{kv}2L H_{kv}d_h},\\ \\frac{\\mathrm{BW}_{\\text{link}}\\,N_{\\text{link}}}{B_{kv}^{\\text{req}}}\\right)\\cdot\\mathbb{1}[\\mathrm{TTFT}\\le S_{\\text{ttft}},\\ \\mathrm{TPOT}\\le S_{\\text{tpot}}]$$</div>\n<p>第三项中 B_kv^req 为单请求 KV 字节量，BW_link·N_link 为可用互连带宽。只按两池算力配比时，这一项被完全遗漏，实际部署中 KV 迁移悄悄吃掉带宽，min 式预测的吞吐无法达到。识别方法是把 KV 迁移耗时与预填耗时并列打点：若迁移耗时占端到端预填阶段的比例持续偏高，说明互连已是实际瓶颈，此时增加解码池 GPU 数不会提升 goodput，只会加深迁移队列。</p>\n<p>反例：某服务请求长度重尾，短提示占多数但长提示贡献大量 token。团队按平均长度解出静态 N_p:N_d 并固定运行。突发长提示到来时，预填池被少数长请求占满，TTFT 越过 S_ttft，指示函数归零，goodput 骤降——尽管解码池此时大量空闲。正确做法是弹性重配比：监测预填池队列长度与 TTFT 余量，在重尾窗口临时上调 N_p，或对长提示做分块预填以平滑占用。代价是重配比本身有切换开销，频繁抖动会引入额外延迟，因此需设滞回阈值。下表给出三类误用的识别信号与后果：</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>后果</th></tr></thead><tbody><tr><td>静态配比不监测先饱和侧</td><td>两池利用率长期不对称，低利用侧排队仍上升</td><td>短板锁死全局 goodput</td></tr><tr><td>忽略 KV 跨池迁移带宽</td><td>迁移耗时占预填阶段比例偏高，加解码 GPU 无效</td><td>min 式预测吞吐无法达到</td></tr><tr><td>重尾下沿用固定 N_p:N_d</td><td>TTFT 逼近 S_ttft，预填池队列被长提示占满</td><td>指示函数归零，goodput 崩塌</td></tr></tbody></table>\n<p>这三类误用共享同一根源：把 SLO 指示函数当成事后校验而非设计约束。指示函数是硬截断，一旦 TTFT 或 TPOT 越界，再高的算力利用率也归零。因此容量规划应先把 S_ttft 与 S_tpot 反解为两池的最小资源下界，再在满足下界的前提下用 min 式找平衡点，而不是先配 GPU 再看 SLO 是否达标。落在具体机制上：预填池的分块大小与解码池的批大小必须联动调参，分块过大抬高单请求预填占用、压缩预填池并发，分块过小则增加跨池迁移次数、放大互连项权重；批大小过大抬高 TPOT、触发指示函数截断。两者的联合搜索空间才是分离式部署真正的调优对象，静态配比表只是其中一条切片。</p>\n\n<h3 id=\"th-disagg-goodput-sec-32\">三十二 · 当 min 式漏掉第三项：分离式 goodput 的三个反例边界</h3>\n<p>最典型的误用是把容量规划简化成“按两池算力配比 GPU”。工程上常见的做法是：先测单请求预填 FLOPs 与每 token KV 字节，代入 min 式解出使两池吞吐相等的 N_p:N_d，然后固定下来。问题在于这个配比只在负载平稳、KV 不跨池、请求长度分布窄的条件下成立。一旦把 P/D 分离部署到真实网关后面，最先饱和的往往不是算力池，而是被 min 式省略的互连项。KV cache 从预填池迁到解码池时，每 token 的迁移字节量与解码侧每步读取量同阶，互连带宽却远低于 HBM 带宽，于是 min 式应改写为三项取小：预填算力项、解码 KV 带宽项、KV 迁移带宽项。只按前两项配比，实际部署中迁移项先触顶，预测吞吐达不到，表现为解码池 GPU 利用率不高但 TPOT 抖动，而预填池已经空闲——短板不在任何一池内部，而在池间的链路上。</p>\n<p>第二个反例来自重尾请求分布。静态 N_p:N_d 的推导隐含“预填池的平均占用率可控”，但长提示会把预填池的排队深度推高，TTFT 越过 S_{ttft} 后指示函数归零，goodput 不是缓慢下降而是硬截断。识别信号很直接：监控预填池的排队长度分布而非均值，若 P99 排队时间接近 S_{ttft}，说明静态配比已失效，需要弹性重配比——把解码池的空闲 GPU 临时划给预填，或对长提示做分块预填以削峰。代价是重配比本身有切换开销，频繁抖动会把收益吃掉，因此弹性策略要带滞回区间。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>忽略 KV 迁移带宽</td><td>解码池利用率低但 TPOT 抖动，预填池空闲</td><td>互连成为隐藏瓶颈，min 式高估吞吐</td></tr><tr><td>重尾下沿用静态配比</td><td>预填池 P99 排队逼近 S_{ttft}</td><td>TTFT 超 SLO，指示函数归零，goodput 崩塌</td></tr><tr><td>只监测均值不监测先饱和侧</td><td>两池均值都“健康”，全局吞吐被短板锁死</td><td>单侧闲置或排队，容量浪费</td></tr></tbody></table>\n<p>第三个反例是监测口径错误：只看两池的平均利用率，不看哪一池先饱和。分离式部署的健康指标应是两池吞吐的比值趋近 1，而不是各自利用率高。若预填池利用率 60%、解码池 95%，说明解码侧先饱和，N_d 应增；反之亦然。把均值当健康信号，会让运维在短板已经锁死全局时仍认为系统有余量。工程判断落在一点：min 式的价值不在算出某个配比数字，而在迫使你把三个瓶颈项都写进监控——算力、KV 带宽、迁移带宽，并对每一项设先饱和告警，任何一项触顶就触发重配比，而不是等 goodput 已经掉下去再回头找原因。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N_p</td><td>预填池GPU数</td></tr><tr><td>N_d</td><td>解码池GPU数</td></tr><tr><td>P_{\\text{prefill}}</td><td>单请求预填FLOPs</td></tr><tr><td>S_{\\text{ttft}}</td><td>TTFT SLO阈值</td></tr><tr><td>S_{\\text{tpot}}</td><td>TPOT SLO阈值</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-disagg-goodput · 共 5 个片段</p>\n"},{"id":"th-moe-roofline","title":"MoE 解码 roofline 界","direction":"dir-expert-parallel-alltoall","prereq":[],"plain":"MoE 解码每 token 只激活少数专家，算术强度被压到极低，性能几乎完全由权重字节数与 HBM 带宽之比决定，算力峰值基本用不上。","definition":"MoE 解码每 token 只激活少数专家，算术强度被压到极低，性能几乎完全由权重字节数与 HBM 带宽之比决定，算力峰值基本用不上。","formula":"$$T_{\\text{token}} \\ge \\max\\left(\\frac{\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w}{B_{\\text{HBM}}},\\ \\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}\\right)$$","variables":[{"sym":"\\mathcal{A}(x)","meaning":"token x 路由命中的专家集合（top-k）"},{"sym":"|W_e|","meaning":"单个专家的参数量"},{"sym":"b_w","meaning":"权重每参数字节数（FP8=1，NVFP4≈0.5）"},{"sym":"B_{\\text{HBM}}","meaning":"Blackwell HBM3e 有效带宽"},{"sym":"N_{\\text{act}}","meaning":"激活参数量"},{"sym":"F_{\\text{peak}}","meaning":"tcgen05 峰值算力"}],"derivation":"推导关键一步：把每 token 的权重读取量写成“命中专家参数量 × 每参数字节”，除以 HBM3e 有效带宽得带宽项；再写“2 × 激活参数量 × 每参数运算量 / 峰值算力”得算力项，取两者较大值即为下界。","example":"用途：在部署决策中用于判断该用 FP8 还是 NVFP4——把 b_w 从 1 降到 0.5 可近似减半带宽项，从而在相同 HBM 带宽下提升单 token 吞吐；也用于估算单卡可承载的并发 batch 上限。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["当 batch 足够大、同一专家被多 token 复用使权重读取摊薄时，瓶颈转向算力项，roofline 需按有效 batch 重算","若专家权重常驻 SMEM/L2 或被 NVFP4 压缩到可缓存规模，HBM 带宽项失效，需改用片上带宽模型"],"system_note":"误用后果：在小 batch 下用峰值算力估算吞吐会严重高估性能；反之在大 batch 专家复用充分时仍按带宽项扩容，忽视算力项成为新瓶颈，增加 GPU 也无法线性提升吞吐。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：MoE 解码每 token 只激活少数专家，算术强度被压到极低，单 token 时间几乎完全由激活专家的权重字节数除以 HBM 带宽决定，tcgen05 峰值算力基本用不上。","公式含义：$$T_{\\text{token}} \\ge \\max\\left(\\frac{\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w}{B_{\\text{HBM}}},\\ \\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}\\right)$$ 中 \\mathcal{A}(x) 为 token 命中的 top-k 专家集合，|W_e| 为单专家参数量，b_w 为权重每参数字节数（FP8=1、NVFP4≈0.5），N_act 为激活参数量。","推导关键一步：把每 token 的权重读取量写成“命中专家参数量 × 每参数字节”，除以 HBM3e 有效带宽得带宽项；再写“2 × 激活参数量 × 每参数运算量 / 峰值算力”得算力项，取两者较大值即为下界。","适用边界：batch 足够大、同一专家被多 token 复用使权重读取摊薄时，瓶颈转向算力项，roofline 需按有效 batch 重算；若专家权重常驻 SMEM/L2 或被 NVFP4 压缩到可缓存规模，HBM 带宽项失效，需改用片上带宽模型。","用途：在部署决策中用于判断该用 FP8 还是 NVFP4——把 b_w 从 1 降到 0.5 可近似减半带宽项，从而在相同 HBM 带宽下提升单 token 吞吐；也用于估算单卡可承载的并发 batch 上限。","误用后果：在小 batch 下用峰值算力估算吞吐会严重高估性能；反之在大 batch 专家复用充分时仍按带宽项扩容，忽视算力项成为新瓶颈，增加 GPU 也无法线性提升吞吐。"],"anchors":["FP8=1","NVFP4≈0.5","$$\\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}$$"],"pitfalls":["在小 batch 解码时用 tcgen05 峰值算力估算吞吐，忽视权重读取的带宽项，实际性能被 HBM 带宽锁死而远低于预期。","在大 batch 专家复用充分、瓶颈已转向算力项时仍按带宽项扩容，新增 GPU 无法线性提升吞吐，容量规划失真。","假设专家权重可常驻 L2 或 SMEM 而不校验容量，实际权重规模超出片上缓存，roofline 退化为 HBM 带宽模型，预测偏差显著。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-1\">一 · 一句话直觉：解码时算力在睡觉，带宽在扛活</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-2\">二 · 严格定义：变量、推导与“有效 batch”的重算规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-3\">三 · 为什么需要这个界：三个部署决策离不开它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-4\">四 · 常见误解：三种典型误用及其后果</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-5\">五 · 一个具体例子：把数字代进去看瓶颈翻转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-6\">六 · roofline 界的适用域：什么时候这条下界说了算，什么时候它失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-7\">七 · 边界：这个下界什么时候不再成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-8\">八 · 带宽项的逐项拆解：为什么分子是&quot;命中专家参数量 × 字节数&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-9\">九 · 算力项的来源：2·N_act·P 是怎么长出来的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-10\">十 · 取 max 的推导关键步：两个下界为何不能相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-11\">十一 · 有效 batch 的重算：摊薄如何改写公式结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-12\">十二 · 片上缓存使带宽项失效：模型切换的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-13\">十三 · 公式作为决策工具的三个代入点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-14\">十四 · 带宽项成立的前提：激活权重必须真的从 HBM 读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-15\">十五 · 有效 batch：权重读取被摊薄后算力项接管</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-16\">十六 · 小 batch 分支：峰值算力估算为何系统性高估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-17\">十七 · 规模上限：专家并行与路由倾斜如何压缩适用区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-18\">十八 · 精度与数值假设：b_w 的取值边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-19\">十九 · 带宽下界在什么条件下让位于算力项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-20\">二十 · 把下界变成批大小决策：有效 batch 与专家复用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-21\">二十一 · 定并行度：TP 与 EP 的取舍由哪一项主导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-22\">二十二 · 定 KV 预算：权重占位之后的剩余显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-23\">二十三 · 定 SLO：把下界翻译成延迟与吞吐目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-24\">二十四 · 算例：一次完整的容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-25\">二十五 · 决策时的三个校验点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-26\">二十六 · 把 roofline 当决策器：有效 batch、并行度与 KV 预算的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-27\">二十七 · 把下界变成容量决策：有效 batch、KV 预算与 SLO 的三条约束线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-28\">二十八 · 误用一：拿峰值算力当吞吐上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-29\">二十九 · 误用二：大 batch 下仍按带宽项扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-30\">三十 · 误用三：假设权重常驻片上而不校验容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-31\">三十一 · 一个反例：三处误用叠加的容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-32\">三十二 · 工程判断：把 roofline 当诊断工具而非预测器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-roofline-sec-33\">三十三 · 误用与反例：把 roofline 当恒等式用</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:533px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 532.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：MoE 解码每 token 只激活少数专家，算术强度被压到极低，性…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{token}} \\ge \\max\\left(…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：当 batch 足够大、同一专家被多 token 复用使权重读取摊…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-moe-roofline-sec-1\">一 · 一句话直觉：解码时算力在睡觉，带宽在扛活</h3>\n<p>MoE 解码的 roofline 界，用一句话说：**每生成一个 token，真正要读的只是被路由命中的那几个专家的权重，而这份字节数除以 HBM 带宽，就是单 token 时间的硬底。** 密集模型解码时每个 token 都要过全部权重，算术强度已经很低；MoE 把激活参数压到总参数的一小部分，算术强度被进一步压到接近“每读一字节只做一两次乘加”的水平。于是 tcgen05 的峰值算力在解码阶段基本闲置，HBM3e 的有效带宽成为唯一有意义的资源。这个直觉不是“MoE 比密集模型快”的笼统说法，而是一个可代入数字的定量判断：单 token 的下界由激活专家的权重字节数决定，而不是由芯片的算力峰值决定。</p>\n<p>把它写成可操作的形式，就是本系列反复使用的那个式子：</p>\n<div class=\"formula\">$$T_{\\text{token}} \\ge \\max\\left(\\frac{\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w}{B_{\\text{HBM}}},\\ \\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}\\right)$$</div>\n<p>左边一项是带宽项，右边一项是算力项，取大者。解码小 batch 时带宽项压倒算力项；这正是“算力在睡觉”的数学表达。注意它是**下界**而非预测值：真实 kernel 还要加上路由、All-to-All、KV cache 读取、kernel launch 与同步的开销，roofline 只告诉你“不可能比这更快”，以及“瓶颈在哪一侧”。</p>\n\n<h3 id=\"th-moe-roofline-sec-2\">二 · 严格定义：变量、推导与“有效 batch”的重算规则</h3>\n<p>先把符号钉死。<span>\\(\\mathcal{A}(x)\\)</span> 是 token x 经门控网络后命中的 top-k 专家集合；<span>|W_e|</span> 是单个专家的参数量；<span>b_w</span> 是权重每参数字节数，FP8 为 1，NVFP4 约为 0.5；<span>\\(B_{\\text{HBM}}\\)</span> 是 Blackwell HBM3e 的有效带宽（注意是有效值，不是标称峰值，要扣掉访问模式带来的效率损失）；<span>\\(N_{\\text{act}}\\)</span> 是激活参数量；<span>\\(F_{\\text{peak}}\\)</span> 是 tcgen05 峰值算力；P 是参与计算的 token 数（在批处理语境下即有效 batch）。</p>\n<p>推导只有两步。第一步，把每 token 的权重读取量写成“命中专家参数量 × 每参数字节”，即 <span>\\(\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w\\)</span>，除以 HBM3e 有效带宽，得到带宽项——这是“必须把这么多字节从 HBM 搬到 SM”的时间。第二步，把计算量写成“2 × 激活参数量 × 每参数运算量”，除以峰值算力，得到算力项——系数 2 来自每个权重参与一次乘加（MAC）的两次浮点运算。两者取 max，就是单 token 时间的下界。之所以取 max 而不是相加，是因为在理想流水下带宽搬运与张量核计算可以重叠，谁更慢谁定调。</p>\n<p>严格定义的关键在于**它不是固定常数，而是 batch 的函数**。当 batch 足够大、同一专家被多个 token 复用时，一次权重读取可以摊薄到多个 token 上，带宽项按有效 batch 摊薄，瓶颈随之转向算力项。此时必须按“有效 batch”（真正共享同一专家的 token 数，而非名义 batch）重算 roofline，否则会得出错误的扩容结论。另一个使定义失效的条件是：若专家权重常驻 SMEM/L2，或被 NVFP4 压缩到可缓存规模，HBM 带宽项就不再成立，模型要换成片上带宽模型。这两条边界是本定义不可分割的一部分，而不是补充说明。</p>\n\n<h3 id=\"th-moe-roofline-sec-3\">三 · 为什么需要这个界：三个部署决策离不开它</h3>\n<p>第一个用途是**精度选型**。把 <span>b_w</span> 从 1（FP8）降到约 0.5（NVFP4），带宽项近似减半，在相同 HBM 带宽下单 token 吞吐获得接近翻倍的提升空间。这个判断不需要跑 benchmark，代进式子就能看出量级；它决定了“这块卡上该用 FP8 还是 NVFP4”的第一层取舍，而量化误差是否可接受则由另一条误差界来把关。</p>\n<p>第二个用途是**并发 batch 上限估算**。单卡能承载多少并发，取决于每 token 的权重读取时间与 KV cache 读取、专家并行通信之间的平衡。带宽项给出了“每 token 至少花多久”的基线，乘以目标 token 速率就得到单卡可持续的 token 预算，再结合 KV cache 容量式反推并发数。这是容量规划里最先要算的一笔账。</p>\n<p>第三个用途是**判断扩容是否有效**。如果当前处于带宽项主导的小 batch 区间，增加 GPU 只会增加可并行的专家分片与带宽总量，吞吐大致线性；一旦专家复用充分、算力项成为新瓶颈，继续按带宽逻辑堆卡就无法线性提升吞吐。roofline 界的作用就是在扩容前告诉你“现在哪一侧在定调”，避免把预算投到不产生收益的方向上。</p>\n<p>代价层面要讲清楚：这个界本身不消耗资源，但它约束的资源是 HBM 带宽——在 Blackwell 上这是最稀缺、最难通过软件腾挪的资源。带宽项每减少一字节，等于直接买回时间；而算力项富余得几乎可以忽略。正因为资源分布如此不对称，才需要一个专门以带宽为纲的界，而不是沿用密集模型的算术强度直觉。</p>\n\n<h3 id=\"th-moe-roofline-sec-4\">四 · 常见误解：三种典型误用及其后果</h3>\n<p>**误解一：用峰值算力估算解码吞吐。** 在小 batch 解码时，把 <span>\\(F_{\\text{peak}}\\)</span> 当作吞吐上限，会得出远高于实际的数字。实际性能被 HBM 带宽锁死：权重读取的字节数是硬性的，算力再富余也无法让这些字节到得更快。这是最典型的失效模式，后果是容量规划整体偏高、SLO 承诺无法兑现。</p>\n<p>**误解二：在大 batch 下仍按带宽项扩容。** 当专家复用充分、瓶颈已转向算力项时，继续按“带宽不够就加卡”的逻辑扩容，新增 GPU 无法线性提升吞吐。此时正确的动作是重算有效 batch 下的算力项，判断是否已进入算力受限区间，再决定是加卡、调 top-k、还是改专家并行切分。</p>\n<p>**误解三：假设专家权重可常驻 L2 或 SMEM 而不校验容量。** 片上缓存容量有限，一旦权重规模超出，roofline 就退化为 HBM 带宽模型，此前基于“权重已在片上”的预测会出现显著偏差。这个误解的危险在于它不会报错，只会让预测悄悄失准——所以任何“权重常驻”的假设都必须先做容量校验，再决定是否切换模型。</p>\n<p>还有一个隐蔽的误解是把下界当预测值。roofline 界不含路由开销、All-to-All 通信、KV cache 读取与 kernel 启动开销，真实延迟总是高于它。把它当作“应该达到的性能”去追，会误判框架与 kernel 的优化空间；正确用法是把它当作“不可逾越的地板”和“瓶颈定位器”。</p>\n\n<h3 id=\"th-moe-roofline-sec-5\">五 · 一个具体例子：把数字代进去看瓶颈翻转</h3>\n<p>设某 MoE 层有若干专家，单专家参数量为 <span>|W_e|</span>，top-k 命中 <span>\\(|\\mathcal{A}(x)|\\)</span> 个专家。用 FP8（<span>b_w=1</span>）时，每 token 需读取 <span>\\(\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\)</span> 字节；换成 NVFP4（<span>\\(b_w\\approx0.5\\)</span>），同一集合的字节数近似减半，带宽项随之减半。这就是精度选型的定量依据：不需要实测，先看带宽项缩小了多少倍。</p>\n<p>再看瓶颈翻转。batch=1 时，每个 token 独占一组专家，权重读取无法摊薄，带宽项主导，算力项（<span>\\(2\\cdot N_{\\text{act}}\\cdot P/F_{\\text{peak}}\\)</span>）相对可忽略。当 batch 增大到同一专家被多个 token 命中，权重读取量按有效 batch 摊薄，带宽项下降，而算力项随 P 线性上升，两者在某一点交叉——交叉点之后，扩容逻辑必须从“加带宽”切换为“加算力或改切分”。这个交叉点的位置由 <span>\\(|\\mathcal{A}(x)|\\)</span>、<span>|W_e|</span>、<span>b_w</span> 与 <span>\\(F_{\\text{peak}}\\)</span> 共同决定，是部署时必须算出的一个数，而不是靠经验拍脑袋。</p>\n<p>工程判断落在这里：先算带宽项，确认它是否主导；若主导，优先动 <span>b_w</span>（量化）和专家放置（减少跨卡读取）；若不主导，说明已进入算力受限区间，此时再谈 tensor core 利用率、top-k 调整与专家并行切分才有意义。这个顺序不能颠倒，否则优化投入会打在非瓶颈上。</p>\n\n<h3 id=\"th-moe-roofline-sec-6\">六 · roofline 界的适用域：什么时候这条下界说了算，什么时候它失效</h3>\n<p>这条下界不是无条件成立的定律，而是一张“在什么条件下谁做主”的判据表。它的成立前提是：激活专家的权重必须从 HBM 现取现用，且同一份权重在同一解码步内没有被多个 token 摊薄。一旦这两个前提之一被打破，公式给出的数值就从“下界”退化为“无关量”。工程上真正要判断的是当前负载落在哪个区间：设有效 batch 为 $B_{\\text{eff}}$，即同一专家在一步内被复用的平均 token 数，则权重读取量从 $\\sum_{e\\in\\mathcal{A}(x)}|W_e|\\cdot b_w$ 摊薄为 $\\frac{1}{B_{\\text{eff}}}\\sum_{e}|W_e|\\cdot b_w$，带宽项随 $B_{\\text{eff}}$ 线性下降，而算力项 $\\frac{2N_{\\text{act}}P}{F_{\\text{peak}}}$ 随 batch 线性上升。两条曲线的交点就是 roofline 拐点，越过它之后继续按带宽项做容量规划必然失真。</p>\n<p>第一个失效条件是片上缓存容量。若专家权重常驻 SMEM 或被 NVFP4 压到可缓存规模，HBM 带宽项整项作废，必须换成片上带宽模型——此时决定单 token 时间的是 SMEM/L2 的读写带宽与 tcgen05 的 MMA 发射节奏，而非 HBM3e。判断这一步不能靠假设，要实算：单专家参数量 × 命中专家数 × $b_w$ 与单卡 SMEM 加 L2 的实际可用容量对比，超出即退回 HBM 模型。第二个失效条件是专家复用度。小 batch 解码时 $B_{\\text{eff}}\\approx 1$，带宽项主导，此时用 tcgen05 峰值算力估算吞吐会把性能高估到与实际相差一个数量级；反之在大 batch、专家复用充分时仍按带宽项扩容，新增 GPU 无法线性提升吞吐，容量规划直接失真。</p>\n<p>第三个容易被忽略的边界是精度换算的近似性。把 $b_w$ 从 FP8 的 1 降到 NVFP4 的约 0.5，确实近似减半带宽项，但这条近似只在权重读取完全主导时成立；一旦算力项接管，降低 $b_w$ 带来的收益会被反量化开销与 MMA 吞吐差异吃掉。因此部署决策中“该用 FP8 还是 NVFP4”不能只看公式里的系数，而要先确认当前 $B_{\\text{eff}}$ 与缓存命中情况，再判断减半的是不是真正的那一项。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>主导项</th><th>模型切换</th><th>误用后果</th></tr></thead><tbody><tr><td>小 batch，$B_{\\text{eff}}\\approx 1$，权重不驻留</td><td>HBM 带宽项</td><td>保持原式</td><td>用峰值算力估算，严重高估吞吐</td></tr><tr><td>大 batch，专家复用充分</td><td>算力项</td><td>按 $B_{\\text{eff}}$ 重算拐点</td><td>按带宽项扩容，GPU 增加不线性</td></tr><tr><td>权重常驻 SMEM/L2 或 NVFP4 可缓存</td><td>片上带宽</td><td>换片上带宽模型</td><td>容量未校验，预测偏差显著</td></tr></tbody></table>\n<p>把这张表落到具体机制上：一次解码步内，路由器先给出每个 token 的 top-k 专家集合，调度器据此统计每个专家的命中计数，命中计数即为 $B_{\\text{eff}}$ 的实测来源。若某专家的命中计数为 1 且其权重不在片上，该 token 的时间由该专家权重的 HBM 读取决定；若命中计数升高到使带宽项低于算力项，则调度器应转为按算力预算分配 SM 与 TMEM，而不是继续按权重字节数排队。这条判据直接决定连续批处理时 batch 上限的估算方式：上限不是由显存容量单独决定，而是由“带宽项与算力项相等”的那个 $B_{\\text{eff}}$ 决定。</p>\n\n<h3 id=\"th-moe-roofline-sec-7\">七 · 边界：这个下界什么时候不再成立</h3>\n<p>roofline 下界不是一条永远贴合的曲线，它有两处明确的失效面。第一处是有效 batch 变大之后：同一专家被多个 token 复用，权重读取量被摊薄，每 token 摊到的 HBM 字节数下降，带宽项随之收缩，而算力项 <span class=\"formula-inline\">2·N_act·P/F_peak</span> 不随 batch 缩小。此时瓶颈迁移到算力项，必须按有效 batch（而非名义 batch）重算下界；若仍按带宽项做容量规划，增加 GPU 不会带来线性吞吐提升，扩容决策直接失真。第二处是权重被搬进片上存储：当专家权重常驻 SMEM/L2，或被 NVFP4 压到可缓存规模，HBM 带宽项整体失效，模型要换成片上带宽与容量约束，而不是继续套用 HBM3e 有效带宽。</p>\n<p>因此使用这个下界前必须先校验两个量：一是每个专家权重的字节规模是否真的超出 L2 可容纳范围，二是路由分布是否已形成足够的专家复用。任一条件不满足，公式给出的就不是性能上限而是错误预期。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主导项</th><th>误用代价</th></tr></thead><tbody><tr><td>小 batch 解码</td><td>HBM 带宽项</td><td>用 tcgen05 峰值算力估吞吐，严重高估</td></tr><tr><td>大 batch、专家复用充分</td><td>算力项</td><td>仍按带宽项扩容，吞吐不线性增长</td></tr><tr><td>权重常驻 L2/SMEM</td><td>片上带宽</td><td>HBM 模型预测偏差显著</td></tr></tbody></table>\n<p>系统代价体现在三个方向：延迟上，带宽项锁死单 token 时间，任何算力侧优化都无法突破；显存上，专家权重总量决定单卡可承载的专家数与并发 batch 上限；带宽上，b_w 从 FP8 的 1 降到 NVFP4 的约 0.5，带宽项近似减半，这是部署中选择精度的直接依据。具体例子：一个 top-k 路由、激活参数量远小于总参数量的解码请求，若按峰值算力估算单卡吞吐，实际会被权重读取字节数除以 HBM 带宽的商所限制，预测值与实测值出现数量级偏差——这正是把下界当成上界使用的典型后果。</p>\n<h3 id=\"th-moe-roofline-sec-8\">八 · 带宽项的逐项拆解：为什么分子是\"命中专家参数量 × 字节数\"</h3>\n<p>公式的带宽项写作 <span class=\"formula-inline\">$$\\frac{\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w}{B_{\\text{HBM}}}$$</span>，分子不是\"全部专家参数量\"，而是\"token x 路由命中的 top-k 专家集合 <span class=\"formula-inline\">$$\\mathcal{A}(x)$$</span> 的参数量之和乘以每参数字节数\"。这一步是整条推导的分水岭：MoE 解码的稀疏性首先体现在<strong>每 token 只触碰少数专家</strong>，因此权重读取量的正确计数单位是\"本次激活的专家权重字节\"，而非模型总权重。若把分母写成全模型权重，得到的是稠密模型的带宽时间，会把 MoE 的解码代价高估一个数量级。</p>\n<p>第二个细节在 <span class=\"formula-inline\">$$b_w$$</span>。它是<strong>权重每参数字节数</strong>，FP8 取 1，NVFP4 取约 0.5。注意这里只对权重计字节，不把激活、KV cache、路由表、归一化参数混进分子——它们走的是另一条路径（激活读写在片上完成，KV cache 由显存容量式单独约束）。把 <span class=\"formula-inline\">$$b_w$$</span> 单独拎出来，是为了让\"换精度\"成为公式里唯一可解析操作的杠杆：<span class=\"formula-inline\">$$b_w$$</span> 从 1 降到 0.5，带宽项近似减半，在 <span class=\"formula-inline\">$$B_{\\text{HBM}}$$</span> 不变的前提下单 token 时间下界随之下降。这也是部署决策里\"该用 FP8 还是 NVFP4\"能被公式直接回答的原因。</p>\n<p>第三个细节是分母 <span class=\"formula-inline\">$$B_{\\text{HBM}}$$</span> 必须是<strong>有效带宽</strong>而非纸面峰值。Blackwell 的 HBM3e 在真实解码负载下受限于访问粒度、专家权重的非连续布局与并发流竞争，有效带宽低于标称值；公式用有效带宽，等于承认\"带宽项是一个可达下界，不是理论极限\"。工程含义：分子侧优化（减少命中专家字节）与分母侧优化（提高有效带宽利用率、改善权重布局连续性）是两条独立的降本路径，不能互相替代。</p>\n<p>具体例子：某 MoE 模型单专家参数量 <span class=\"formula-inline\">$$|W_e|$$</span> 固定、top-k 命中 <span class=\"formula-inline\">$$k$$</span> 个专家，FP8 下分子为 <span class=\"formula-inline\">$$k\\cdot|W_e|\\cdot 1$$</span>；切到 NVFP4 后分子变为 <span class=\"formula-inline\">$$k\\cdot|W_e|\\cdot 0.5$$</span>。若该 token 的算力项仍远小于带宽项，则 <span class=\"formula-inline\">$$T_{\\text{token}}$$</span> 的下界近似减半——这正是公式把精度选择放进分子而不是散落在文字描述里的价值。</p>\n\n<h3 id=\"th-moe-roofline-sec-9\">九 · 算力项的来源：2·N_act·P 是怎么长出来的</h3>\n<p>算力项 <span class=\"formula-inline\">$$\\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}$$</span> 中，<span class=\"formula-inline\">$$N_{\\text{act}}$$</span> 是激活参数量，<span class=\"formula-inline\">$$P$$</span> 是每 token 的 token 数（解码时通常为 1，预填或投机解码的验证阶段会大于 1），<span class=\"formula-inline\">$$F_{\\text{peak}}$$</span> 是 tcgen05 峰值算力。系数 2 来自矩阵乘的乘加计数：每个激活参数参与一次乘与一次加，按 FLOP 计为 2 次运算。这一步的关键是把\"每 token 的计算量\"写成<strong>激活参数量 × 每参数运算量 × token 数</strong>，而不是用模型总参数量——与带宽项同构，稀疏性在两项里都被一致地施加在\"激活\"而非\"全量\"上。</p>\n<p>推导上容易出错的地方是把 <span class=\"formula-inline\">$$N_{\\text{act}}$$</span> 与 <span class=\"formula-inline\">$$\\sum_{e\\in\\mathcal{A}(x)}|W_e|$$</span> 当成同一个量。二者在数值上相关但不相等：前者是参与运算的激活参数总量，后者是命中专家的权重参数量；当专家内部存在不参与本次计算的参数（如未被路由到的子结构）或存在共享参数时，两者会分叉。公式刻意保留两个符号，就是为了让读者在代入具体模型时分别核对，而不是拿一个数套两处。</p>\n<p>算力项在解码阶段的现实地位：单 token、小 batch 时它通常远小于带宽项，因此 <span class=\"formula-inline\">$$\\max$$</span> 取到的是带宽项；但它是<strong>下界的一部分而非可忽略项</strong>——一旦 batch 增大、同一专家被多 token 复用，权重读取被摊薄，带宽项的相对份额下降，算力项就会顶上来成为新的 <span class=\"formula-inline\">$$\\max$$</span> 取值。这正是公式用 <span class=\"formula-inline\">$$\\max$$</span> 而非求和的原因：两项描述的是两种不同的资源约束，任一时刻只有一项是紧的。</p>\n<p>具体例子：在投机解码的验证阶段，一次前向要处理 <span class=\"formula-inline\">$$P&gt;1$$</span> 个候选 token，算力项随 <span class=\"formula-inline\">$$P$$</span> 线性增长，而带宽项因专家复用被摊薄而增长更慢；此时若仍按 <span class=\"formula-inline\">$$P=1$$</span> 的带宽主导直觉做容量规划，会低估算力侧的占用。代价体现在延迟上：验证阶段的单步时间不再由 HBM 带宽锁死，而开始受 tcgen05 的吞吐约束。</p>\n\n<h3 id=\"th-moe-roofline-sec-10\">十 · 取 max 的推导关键步：两个下界为何不能相加</h3>\n<p>从\"每 token 权重读取量 ÷ 带宽\"和\"每 token 运算量 ÷ 峰值算力\"分别得到两个时间量，然后取 <span class=\"formula-inline\">$$\\max$$</span>。这一步的合法性来自<strong>资源并行性</strong>：权重读取与矩阵运算在时间上可以重叠（HBM 传输与 tcgen05 计算流水并行），因此单 token 的耗时不可能小于两者中较大的那个，但也不必是两者之和。写成求和会得到一个过于悲观的上界式估计，写成取小则会违反物理约束。取 <span class=\"formula-inline\">$$\\max$$</span> 是\"重叠执行假设下的紧下界\"这一语义的精确表达。</p>\n<p>推导中还有一个隐含假设需要点明：<strong>带宽项与算力项使用同一份激活专家集合</strong>。也就是说，公式假定被读取的权重恰好就是被用于计算的权重，没有预取浪费、没有因路由抖动导致的重复读取。真实系统里，若专家权重布局离散、每次命中触发多次小粒度传输，实际带宽项会高于公式值；若采用权重预取或专家缓存，实际带宽项会低于公式值。公式给出的是\"理想布局 + 无缓存命中\"下的基准，工程上把它当作<strong>可对比的标尺</strong>而非绝对预测。</p>\n<p>离散化与近似出现在两处。第一处是 <span class=\"formula-inline\">$$b_w$$</span> 的取值：NVFP4 的\"约 0.5\"是块缩放格式下的平均字节数，实际每参数字节随块大小与元数据开销浮动，公式用常数近似掉了这部分结构性开销。第二处是 <span class=\"formula-inline\">$$F_{\\text{peak}}$$</span>：峰值算力是理想工况下的标称值，真实 kernel 的 tcgen05 利用率受 tile 形状、TMEM 占用与 2-SM MMA 配对效率影响，公式用峰值意味着算力项是\"最乐观的算力下界\"，真实算力项只会更大。两处近似方向相反：<span class=\"formula-inline\">$$b_w$$</span> 偏乐观（低估字节），<span class=\"formula-inline\">$$F_{\\text{peak}}$$</span> 也偏乐观（高估算力），因此公式整体是<strong>偏乐观的下界</strong>，实际 <span class=\"formula-inline\">$$T_{\\text{token}}$$</span> 高于它。</p>\n<p>具体例子：把 <span class=\"formula-inline\">$$F_{\\text{peak}}$$</span> 代入算力项时，若某层因 tile 尺寸不匹配导致 tcgen05 利用率只有标称的一部分，算力项的真实值按比例放大，但公式仍按峰值计算——这解释了为什么在小 batch 下用峰值算力估吞吐会严重高估：公式的算力项本就不是紧的，而带宽项才是当时真正紧的那一项。</p>\n\n<h3 id=\"th-moe-roofline-sec-11\">十一 · 有效 batch 的重算：摊薄如何改写公式结构</h3>\n<p>原始公式按\"每 token\"计，隐含 batch=1。当 batch 增大到同一专家被多个 token 命中时，权重只需读取一次即可服务多个 token，带宽项的分子被摊薄。严格写法应把带宽项改为 <span class=\"formula-inline\">$$\\frac{\\sum_{e\\in\\mathcal{A}(B)} |W_e|\\cdot b_w}{B_{\\text{HBM}}}$$</span>，其中 <span class=\"formula-inline\">$$\\mathcal{A}(B)$$</span> 是 batch 内所有 token 命中专家的并集，而算力项的 <span class=\"formula-inline\">$$P$$</span> 换成 batch 内 token 总数。于是两项随 batch 的增长斜率不同：带宽项随专家并集规模增长（亚线性于 batch），算力项随 token 数线性增长。交点就是瓶颈切换点。</p>\n<p>这个重算不是可选的修正，而是公式适用边界的核心。失效条件明确写着：batch 足够大、专家复用充分时，瓶颈转向算力项，roofline 需按有效 batch 重算。所谓\"有效 batch\"，指的不是调度器里的请求数，而是<strong>在专家维度上真正产生复用的 token 数</strong>——若路由高度分散，batch 再大专家并集仍接近线性增长，摊薄效果有限；若路由集中（如领域内请求聚集），少量 token 就能覆盖大部分专家，摊薄迅速发生。因此有效 batch 是路由分布的泛函，不能只看请求队列长度。</p>\n<p>工程代价：在瓶颈切换点之前扩容 GPU，吞吐近似线性提升（带宽项主导，每卡独立承担权重读取）；越过切换点后继续按带宽项扩容，新增 GPU 无法线性提升吞吐，因为算力项已成为紧约束，容量规划失真。这正是误用后果里\"大 batch 下仍按带宽项扩容\"的机制根源。</p>\n<p>具体例子：连续批处理把多个请求拼进同一解码步，若这些请求命中同一组专家，带宽项分子近似不变而算力项随 token 数上升，单 token 平均时间下降；但一旦 token 数超过算力项对应的阈值，继续加 token 只会拉长单步时间，吞吐进入平台期。调度器需要在这个阈值附近做批大小决策，而不是无限增大 batch。</p>\n\n<h3 id=\"th-moe-roofline-sec-12\">十二 · 片上缓存使带宽项失效：模型切换的判据</h3>\n<p>公式的第二个失效条件是专家权重常驻 SMEM/L2，或被 NVFP4 压缩到可缓存规模。此时 HBM 带宽项不再是紧约束，因为权重读取发生在片上而非 HBM，公式应改用片上带宽模型：分子不变（命中专家字节），分母换成 SMEM/L2 的有效带宽。这一步的判据是<strong>容量校验</strong>：命中专家权重字节是否真的放得进目标缓存层级。若不校验就假设常驻，实际权重规模超出片上缓存，roofline 会退化为 HBM 带宽模型，预测偏差显著——这是失败模式里明确列出的第三条。</p>\n<p>NVFP4 在这里的作用是双重的：它既降低 <span class=\"formula-inline\">$$b_w$$</span> 从而缩小带宽项，也可能把权重规模压到可缓存阈值以下，使公式从 HBM 模型切换到片上模型。两个效果叠加时，单 token 时间的下界下降幅度超过单纯减半，因为分母也从 HBM 带宽换成了更高的片上带宽。但切换的前提是容量校验通过：压缩后的专家权重总量必须小于可用 SMEM/L2 容量，且要为激活、KV cache、路由元数据留出余量。</p>\n<p>代价维度：片上缓存模型下，瓶颈可能转为 SMEM 容量与 L2 命中率，而非 HBM 带宽；此时增加 HBM 带宽对延迟无益，优化方向转向提高缓存命中率与减少专家切换。功耗侧也随之变化——HBM 访问的能耗远高于片上访问，权重常驻片上会显著降低每 token 的访存能耗，这是公式切换带来的隐性收益。</p>\n<p>具体例子：某层专家权重经 NVFP4 压缩后总量落入 L2 可容纳范围，且路由在该层高度集中，则该层的 <span class=\"formula-inline\">$$T_{\\text{token}}$$</span> 下界由片上带宽决定；若另一层专家总量超出 L2，即使精度相同也仍走 HBM 模型。同一模型内不同层可能落在不同模型下，逐层判断而非整体套用一个公式，是容量规划的正确粒度。</p>\n\n<h3 id=\"th-moe-roofline-sec-13\">十三 · 公式作为决策工具的三个代入点</h3>\n<p>把公式当决策工具，要盯住三个代入点。第一是 <span class=\"formula-inline\">$$b_w$$</span>：精度选择直接改写带宽项分子，FP8 到 NVFP4 的切换在带宽主导区近似减半单 token 时间下界，这是最直接的吞吐杠杆。第二是 <span class=\"formula-inline\">$$B_{\\text{HBM}}$$</span> 的有效性：分母用有效带宽而非标称值，意味着改善权重布局连续性、减少小粒度传输，等价于抬高分母，与降低分子是两条独立路径。第三是有效 batch：它决定 <span class=\"formula-inline\">$$\\max$$</span> 取哪一项，也决定扩容是否还有线性收益。</p>\n<p>单卡并发 batch 上限的估算也落在这三个点上：给定 <span class=\"formula-inline\">$$B_{\\text{HBM}}$$</span> 与 <span class=\"formula-inline\">$$F_{\\text{peak}}$$</span>，找到带宽项与算力项相等时的有效 batch，即为该卡的瓶颈切换点；超过它，增加并发不再提升单卡吞吐。这个上限不是常数，随路由分布与精度变化而移动，因此容量规划必须按实际负载的路由统计重算，而不能套用固定值。</p>\n<p>误用公式的两种典型方向已在失效条件中给出：小 batch 下用峰值算力估吞吐会严重高估（算力项不紧却被当作紧约束），大 batch 下按带宽项扩容会低估算力约束（带宽项已松却被当作紧约束）。两者的共同根源是<strong>没有判断当前哪一项是紧的</strong>。公式的 <span class=\"formula-inline\">$$\\max$$</span> 结构本身就是判断工具：代入实际 <span class=\"formula-inline\">$$b_w$$</span>、有效带宽、有效 batch 与路由统计，算出两项数值，较大者即当前瓶颈，优化与扩容都应指向它。</p>\n<p>具体例子：部署决策中若测得某负载下带宽项显著大于算力项，则优先做精度压缩与权重布局优化；若两项接近，则需同时准备两条优化路径，并意识到任何单侧扩容的边际收益都在下降。公式不给出绝对时间，但给出<strong>瓶颈归属</strong>，这才是它在容量规划中被反复代入的原因。</p>\n<h3 id=\"th-moe-roofline-sec-14\">十四 · 带宽项成立的前提：激活权重必须真的从 HBM 读</h3>\n<p>公式的带宽项 \\(\\sum_{e\\in\\mathcal{A}(x)} |W_e|\\cdot b_w / B_{\\text{HBM}}\\) 隐含一个物理假设：本 token 命中的每个专家权重，在本次前向中确实需要跨越 HBM 接口搬运一次。这个假设在两种情况下被破坏，而破坏之后整条 roofline 的取值来源就变了。</p>\n<p>第一种是片上驻留。若某专家的权重在解码循环中被固定在 SMEM 或长期占据 L2，则它不再计入 HBM 流量，带宽项应替换为片上带宽模型：以 SMEM/L2 的有效读带宽与容量约束重写分母。此时单 token 时间不再由 HBM3e 带宽锁定，而是由 tcgen05 从片上取操作数的速率与 MMA 发射节奏决定。工程上判断是否落入这一分支，只需做一次容量校验：把常驻专家的字节数 \\(|\\mathcal{W}_{\\text{res}}|\\cdot b_w\\) 与可用的 L2 切片、SMEM 配额逐项比对，超出即退回 HBM 模型，不得沿用片上假设。</p>\n<p>第二种是压缩后进入可缓存规模。NVFP4 把 \\(b_w\\) 从 FP8 的 1 压到约 0.5，这不仅是把带宽项近似减半，还可能把原本放不进 L2 的专家集合压进缓存容量阈值。于是同一个模型在 FP8 下走 HBM 带宽分支、在 NVFP4 下走片上带宽分支，两条分支的斜率完全不同。误用后果很直接：假设权重可常驻 L2 而不校验容量，实际权重规模超出片上缓存，roofline 退化为 HBM 带宽模型，预测偏差显著。容量校验必须作为公式适用性的前置条件，而不是事后解释偏差的补丁。</p>\n<p>具体例子：一个专家权重按 FP8 计量已接近单卡 L2 可用切片的上限，此时把精度换到 NVFP4，字节数减半后该专家集合具备常驻条件，单 token 延迟的瓶颈项从 HBM 搬到片上；反过来，若路由分布使得每 token 命中的专家集合在多个切片间跳动，常驻失效，压缩带来的收益又回到纯带宽项上兑现。</p>\n\n<h3 id=\"th-moe-roofline-sec-15\">十五 · 有效 batch：权重读取被摊薄后算力项接管</h3>\n<p>带宽项的分母是每 token 的权重读取量，这个量在 batch 增大时并不线性增长——同一专家被多个 token 命中，一次权重搬运服务多个 token 的计算。于是需要引入有效 batch 的概念：不是调度器里的请求数，而是按专家命中分布折算出的、真正能摊薄权重读取的并发度。</p>\n<p>设 batch 内 token 集合为 \\(\\mathcal{B}\\)，专家 \\(e\\) 被命中的 token 数为 \\(n_e=\\sum_{x\\in\\mathcal{B}}\\mathbf{1}[e\\in\\mathcal{A}(x)]\\)，则每 token 摊到的权重字节为 \\(\\sum_{e} |W_e|\\cdot b_w / \\max(1,n_e)\\) 的加权形式。当所有 \\(n_e\\) 都远大于 1 时，带宽项被压到很低，下界由算力项 \\(2\\cdot N_{\\text{act}}\\cdot P / F_{\\text{peak}}\\) 接管。这就是失效条件的核心：roofline 必须按有效 batch 重算，而不是按名义 batch 套用同一条曲线。</p>\n<div class=\"formula\">$$T_{\\text{token}} \\ge \\max\\left(\\frac{1}{|\\mathcal{B}|}\\sum_{e}\\frac{|W_e|\\cdot b_w}{\\max(1,n_e)},\\ \\frac{2\\cdot N_{\\text{act}}\\cdot P}{F_{\\text{peak}}}\\right)$$</div>\n<p>这条改写暴露出容量规划中最常见的失真：在大 batch 专家复用充分、瓶颈已转向算力项时仍按带宽项扩容，新增 GPU 无法线性提升吞吐。因为算力项与设备数近似成反比的前提是每张卡都能吃满 tcgen05 峰值，而专家并行带来的 All-to-All 与负载倾斜会先吃掉这部分余量。工程判断应落在“当前 batch 下两项谁更大”的实测上：用一次 profile 读出实际 HBM 流量与 MMA 占用率，若流量远低于按名义 batch 估算的值而 MMA 占用率接近饱和，就说明已经越过边界，扩容策略要从加带宽转向加算力效率或改路由均衡。</p>\n<p>具体例子：连续批处理把解码 batch 推到较大规模后，热门专家被反复命中，权重读取摊薄，此时若仍以 FP8→NVFP4 的带宽减半作为主要提速手段，收益会明显低于预期，因为瓶颈已不在字节数上；真正有效的是提高 MMA 利用率、减少专家并行通信等待。</p>\n\n<h3 id=\"th-moe-roofline-sec-16\">十六 · 小 batch 分支：峰值算力估算为何系统性高估</h3>\n<p>公式取 max 而非求和，本身就说明两项不会同时成为瓶颈。在小 batch 解码区间，带宽项远大于算力项，此时用 \\(F_{\\text{peak}}\\) 反推吞吐会得到严重偏高的数字。失败模式很明确：在小 batch 解码时用 tcgen05 峰值算力估算吞吐，忽视权重读取的带宽项，实际性能被 HBM 带宽锁死而远低于预期。</p>\n<p>量化这个偏差只需看两项之比：带宽项与算力项之比近似为 \\(\\frac{\\sum|W_e| b_w}{B_{\\text{HBM}}}\\big/\\frac{2N_{\\text{act}}P}{F_{\\text{peak}}}\\)，在小 batch 下该比值远大于 1，意味着按算力估算的吞吐要除以这个比值才接近现实。这个比值同时给出一个有用的判据：它随 \\(b_w\\) 线性变化、随有效 batch 反向变化，因此可以作为“何时该换精度、何时该加 batch”的单一标尺。</p>\n<p>代价层面要区分清楚：小 batch 区间牺牲的是吞吐，换来的是单 token 延迟的下界；此时增加并发几乎不增加单 token 时间（因为权重读取被摊薄），但一旦越过算力项接管点，单 token 时间开始随 batch 上升，尾延迟恶化。容量规划若只按吞吐目标堆 batch，会在 SLO 的尾延迟上付出代价，而这条代价在纯带宽模型里是看不见的。</p>\n<p>具体例子：单请求解码时，每 token 只搬运少量专家权重，HBM 带宽被少量字节的搬运占满而 tcgen05 大量空转；此时把并发从 1 提到能覆盖同一专家集合的规模，单 token 时间基本不变而吞吐成倍上升——这正是带宽项主导区间的典型行为，也是判断是否仍在边界内的操作信号。</p>\n\n<h3 id=\"th-moe-roofline-sec-17\">十七 · 规模上限：专家并行与路由倾斜如何压缩适用区间</h3>\n<p>公式把 \\(\\mathcal{A}(x)\\) 当作给定集合，未计入取得这些权重的通信代价。当模型规模推到需要跨卡放置专家时，每 token 的激活权重不再来自本地 HBM，而要先经 All-to-All 汇聚 token 再读权重，或先读权重再算。此时 HBM 带宽项仍是下界的一部分，但已不是主导项，实际单 token 时间被互连带宽与跳数支配。roofline 的适用上限因此由“专家是否本地”划定：一旦激活专家跨节点，公式需补入通信项，否则预测偏低。</p>\n<p>路由倾斜从另一侧压缩区间。若命中分布高度集中，少数专家承担大部分 token，这些卡的算力项先饱和而其余卡仍在带宽项区间，全局吞吐由最慢的分片决定，max 的逐设备形式取代了全局形式。此时按全局平均激活参数量估算会低估热点分片的压力。规模上限的工程含义是：当专家并行度上升、每卡专家数下降时，单卡命中集合的方差变大，公式的确定性假设（每 token 命中量近似恒定）逐渐失效，需要用分片级的最坏命中量替代平均值。</p>\n<p>功耗与带宽在此处耦合：跨卡搬运增加互连功耗，而本地 HBM 流量下降并不等比例降低整卡功耗，能效比的分母变了，roofline 只描述时间不描述能耗，扩容决策需另设能效约束。具体例子：把专家数扩到需要多卡承载后，单 token 的 HBM 读取字节数下降，但 All-to-All 的等待使单 token 时间不降反升，此时按带宽项预测的“扩容即提速”完全落空。</p>\n\n<h3 id=\"th-moe-roofline-sec-18\">十八 · 精度与数值假设：b_w 的取值边界</h3>\n<p>公式把 \\(b_w\\) 当作常数，FP8 取 1、NVFP4 取约 0.5。这个取值成立的前提是权重确实以该精度存储并被 MMA 直接消费，中间不发生反量化回写到更高精度。若内核在加载后把 NVFP4 权重解压到 FP8 或 BF16 再进 tcgen05，则实际 HBM 流量仍按压缩后的字节计，但片上占用与算力项的有效 \\(P\\) 发生变化，公式两项需分别修正，不能只改 \\(b_w\\)。</p>\n<p>另一处边界是精度与路由的交互：量化误差会改变路由打分，进而改变 \\(\\mathcal{A}(x)\\) 的分布，使有效 batch 的摊薄效果偏移。公式本身不建模这一层，因此当量化误差界接近路由决策的间隔时，roofline 的输入集合不再稳定，预测的置信度下降。这不是公式错了，而是它的输入假设被上游数值行为扰动。</p>\n<p>工程判断落在校验顺序上：先确认权重格式与内核消费路径一致，再确认路由分布在量化后未发生系统性漂移，最后才用 \\(b_w\\) 的减半去推带宽项收益。跳过前两步直接套 0.5，会在片上占用或路由倾斜上遭遇未计入的代价。具体例子：同一模型在 FP8 与 NVFP4 下若路由命中集合显著不同，则两者的有效 batch 不可直接比较，带宽项的减半收益必须按各自的实际命中分布重算，而不是把 0.5 当作通用缩放因子。</p>\n\n<h3 id=\"th-moe-roofline-sec-19\">十九 · 带宽下界在什么条件下让位于算力项</h3>\n<p>公式取 max 的结构本身已经说明：这个下界不是一条曲线，而是两条曲线在某个 batch 点上的交点。带宽项的分母是固定的 HBM3e 有效带宽，分子是 Σ|W_e|·b_w，对单个 token 而言这是硬开销；但只要同一专家被多个 token 命中，这份权重字节就被摊薄成 Σ|W_e|·b_w / n_e，n_e 为落在专家 e 上的 token 数。于是有效单 token 时间应改写为带宽项除以复用度、再与算力项取大。真正的适用边界是复用度尚未把带宽项压到算力项之下的区间。一旦 batch 增长到专家负载均衡、n_e 接近 batch·k/专家总数，瓶颈翻转，此时继续按带宽项做容量规划会系统性高估可扩展性——增加 GPU 只增加总算力，而算力项才是新约束，吞吐不会线性增长。判断翻转点需要实测专家命中分布，而不是用均匀路由假设；长尾路由下少数热专家先饱和，翻转点比均匀假设来得更早。</p>\n<p>第二个失效条件是片上缓存假设。带宽项成立的前提是激活专家权重必须从 HBM 取。若专家权重常驻 SMEM 或驻留 L2，或被 NVFP4 压到可缓存规模，HBM 项就不再是约束，模型必须换成片上带宽与 L2 命中率模型。这里有一个容量校验不等式：k·|W_e|·b_w ≤ C_片上（SMEM 或可用 L2 份额），不满足就不能声称带宽项失效。工程上常见错误是只按 NVFP4 的 b_w≈0.5 折算就断言权重可缓存，却忽略 k 个专家同时驻留以及多 token 并发下同一 SMEM 分区被挤占的事实；一旦超出容量，实际行为回退到 HBM 带宽模型，预测偏差显著。下表给出三个判据的对应关系：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>主导项</th><th>模型替换</th><th>系统代价</th></tr></thead><tbody><tr><td>小 batch、专家不复用</td><td>HBM 带宽项</td><td>原式成立</td><td>算力闲置，延迟由权重字节决定</td></tr><tr><td>大 batch、n_e 高</td><td>算力项</td><td>按有效 batch 重算</td><td>扩容不线性，功耗随算力项上升</td></tr><tr><td>权重驻留 SMEM/L2</td><td>片上带宽</td><td>改用片上带宽模型</td><td>容量越界即退化，需校验 k·|W_e|·b_w</td></tr></tbody></table>\n<p>第三个边界是规模上限本身。公式对 N_act 与 Σ|W_e| 是线性的，但真实系统里专家并行会把 Σ|W_e| 拆到多卡，跨卡 all-to-all 的通信时间不进入这两项，却实打实叠加在 T_token 上；当专家分布跨节点、走 NVLink 5 之外的链路时，通信项可能超过带宽项，此时 roofline 只是下界而非预测值。同理，top-k 路由的负载不均衡会让最慢那张卡决定整体延迟，max 应理解为对卡取 max 再对项取 max。误用后果很直接：小 batch 下用 tcgen05 峰值算力估吞吐，实际被 HBM 带宽锁死；大 batch 下仍按带宽项扩容，容量规划失真。把 b_w 从 1 降到 0.5 只近似减半带宽项，对算力项主导的区间几乎无收益，这也是精度选择必须与 batch 区间绑定的原因。</p>\n<h3 id=\"th-moe-roofline-sec-20\">二十 · 把下界变成批大小决策：有效 batch 与专家复用率</h3>\n<p>roofline 下界本身是单 token 的，但容量决策问的是“一张卡能同时跑多少条序列”。关键是把 batch 拆成“命中同一专家的 token 数”。设全局 batch 为 <em>B</em>，top-k 为 <em>k</em>，专家总数为 <em>E</em>，路由近似均匀时，单个专家在一次前向中平均被 <em>B·k/E</em> 个 token 命中。记这个数为复用度 <em>r</em>，则每 token 摊到的权重读取字节从 <em>k·|W_e|·b_w</em> 降为 <em>k·|W_e|·b_w / r</em>（当 <em>r</em>&gt;1）。于是带宽项随 batch 增大而线性摊薄，直到算力项接管。工程上可直接解出“带宽项 = 算力项”的交叉 batch：</p>\n<div class=\"formula\">$$B^{*} \\approx \\frac{E}{k}\\cdot\\frac{2 N_{\\text{act}} P\\, B_{\\text{HBM}}}{k\\,|W_e|\\, b_w\\, F_{\\text{peak}}}$$</div>\n<p>这个式子的读法是：<em>B</em> 小于 <em>B*</em> 时扩 batch 几乎免费（吞吐线性涨、单 token 延迟不变），超过 <em>B*</em> 后每加一条序列都在抢算力，单 token 时间开始上升。因此批大小不应按显存上限定，而应按 <em>B*</em> 与 KV 预算两者取小。举例：一个 top-2、专家数较多的 MoE，FP8 权重下带宽项主导，把 batch 从 8 拉到 64 时吞吐近似线性；继续拉到 256，专家复用已充分，算力项成为约束，吞吐曲线明显变平——此时再加并发只增加排队延迟，不增加 goodput。</p>\n\n<h3 id=\"th-moe-roofline-sec-21\">二十一 · 定并行度：TP 与 EP 的取舍由哪一项主导</h3>\n<p>并行度决策的本质是问“我在切带宽还是在切算力”。张量并行（TP）把每个专家的权重矩阵按列/行切开，每卡只读 <em>1/TP</em> 的权重字节，直接缩小带宽项，代价是每层两次 All-Reduce；专家并行（EP）把不同专家放到不同卡，每卡只持有 <em>E/EP</em> 个专家，单卡权重总量下降，但每个 token 要把激活发到命中专家所在的卡，付出 All-to-All。判断依据是：当 <em>B</em> &lt; <em>B*</em>、带宽项主导时，TP 对单 token 延迟的收益是直接的（带宽项除以 TP），而 EP 只减小了单卡驻留权重、并不减小单 token 需读取的字节数（该 token 命中的专家仍在别的卡上，读取量不变，只是换了位置）。反过来，当 <em>B</em> &gt; <em>B*</em>、算力项主导时，TP 切算力有效，EP 则通过把专家分散降低单卡算力压力但引入通信。因此小 batch 低延迟场景优先 TP（或 TP×EP 混合且 TP 占主导），大 batch 高吞吐场景优先 EP 以省出单卡显存给 KV。代价量化：TP 的 All-Reduce 每层 2×(hidden×batch×bytes) 的通信量，在 NVLink 5 域内可接受；跨节点 EP 的 All-to-All 则要按专家并行通信下界那条结论校核，避免通信把 roofline 的收益吃掉。</p>\n\n<h3 id=\"th-moe-roofline-sec-22\">二十二 · 定 KV 预算：权重占位之后的剩余显存</h3>\n<p>MoE 的显存账要先扣权重再算 KV。单卡权重字节为 <em>(E/EP)·|W_e|·b_w</em>（非激活专家也要驻留），加上激活参数与框架开销。剩余显存除以每 token KV 字节，得到 KV 能支撑的并发 token 数：</p>\n<div class=\"formula\">$$\\text{Cap}_{\\text{KV}} = \\frac{M_{\\text{HBM}} - (E/EP)\\,|W_e|\\, b_w - M_{\\text{other}}}{\\text{kv\\_bytes\\_per\\_token}}$$</div>\n<p>这里出现一个常被忽略的耦合：roofline 说 batch 越大越好（直到 <em>B*</em>），但 KV 预算说 batch 受显存限制。两个约束的交点才是可部署的 batch。工程判断是：若 <em>Cap</em><sub>KV</sub> 对应的 batch 远小于 <em>B*</em>，说明瓶颈其实在显存而非带宽，此时应优先用 NVFP4 压权重（<em>b_w</em> 从 1 降到约 0.5，权重占位减半，直接释放 KV 空间），而不是加卡扩 EP；若 <em>Cap</em><sub>KV</sub> 对应的 batch 已超过 <em>B*</em>，则显存不是约束，应把预算花在提升算力利用率上。举例：一个权重占了大头的 MoE，FP8 下权重吃掉多数 HBM，KV 只剩很小一块，长上下文时并发被压到个位数——此时换 NVFP4 的收益不只是带宽项减半，更是把权重占位腾出来给 KV，一举把 batch 推过 <em>B*</em>。</p>\n\n<h3 id=\"th-moe-roofline-sec-23\">二十三 · 定 SLO：把下界翻译成延迟与吞吐目标</h3>\n<p>SLO 通常写成“P99 单 token 间隔 ≤ X ms”或“每卡吞吐 ≥ Y token/s”。roofline 给的是单 token 时间的下界，可直接作为延迟 SLO 的可行性判据：若 <em>T</em><sub>token</sub> 的下界已经超过 SLO 的 X，则无论怎么调度都达不到，必须改精度（降 <em>b_w</em>）、改并行（切带宽项）或改硬件。反过来，吞吐 SLO 的上界是 <em>1/T</em><sub>token</sub> 乘以 batch 再乘以利用率。实际部署中要区分两种 SLO 形态：延迟敏感（交互式）取小 batch、贴着带宽项走，此时 <em>T</em><sub>token</sub> ≈ 带宽项，SLO 达标与否几乎只取决于 <em>b_w</em> 和 <em>B</em><sub>HBM</sub>；吞吐敏感（离线批处理）取大 batch、逼近 <em>B*</em>，此时 SLO 由算力项和排队共同决定。一个具体判断：当 SLO 要求 P99 延迟很紧时，把 batch 定在 <em>B*</em> 以下并留出排队余量，因为超过 <em>B*</em> 后单 token 时间随 batch 上升，P99 会被尾部序列拖垮；当 SLO 只约束总吞吐时，把 batch 顶到 <em>B*</em> 附近最划算，再往上加并发只增延迟不增吞吐。</p>\n\n<h3 id=\"th-moe-roofline-sec-24\">二十四 · 算例：一次完整的容量决策</h3>\n<p>设一个 MoE 模型，top-k=2，专家数 <em>E</em> 较大，单专家参数量 <em>|W_e|</em> 中等，激活参数 <em>N_act</em> 远小于总参数；硬件为单台 Blackwell 节点，HBM3e 带宽 <em>B</em><sub>HBM</sub> 与 tcgen05 峰值 <em>F</em><sub>peak</sub> 取该平台标称值。决策步骤如下。</p>\n<ul>\n<li>第一步，算 FP8 下的带宽项：<em>k·|W_e|·1 / B</em><sub>HBM</sub>，得到单 token 时间下界的主项；再算算力项 <em>2·N_act·P / F</em><sub>peak</sub>，确认在小 batch 下带宽项远大于算力项——这验证了“峰值算力用不上”的直觉。</li>\n<li>第二步，解交叉 batch <em>B*</em>：按上面的式子代入 <em>E/k</em>、<em>|W_e|</em>、<em>N_act</em>，得到“带宽项与算力项相等”的 batch。若 <em>B*</em> 落在几十到上百量级，说明该模型在单卡上有可观的 batch 扩展空间。</li>\n<li>第三步，算 KV 预算：用 <em>M</em><sub>HBM</sub> 减去 <em>(E/EP)·|W_e|·1</em> 与框架开销，除以每 token KV 字节，得到 <em>Cap</em><sub>KV</sub>。若 <em>Cap</em><sub>KV</sub> &lt; <em>B*</em>，则显存是硬约束，batch 取 <em>Cap</em><sub>KV</sub>。</li>\n<li>第四步，换 NVFP4：<em>b_w</em> 从 1 降到约 0.5，带宽项近似减半，同时权重占位减半使 <em>Cap</em><sub>KV</sub> 上升。重算后若 <em>Cap</em><sub>KV</sub> 越过 <em>B*</em>，则 batch 由 <em>B*</em> 决定，吞吐提升来自带宽项减半与 batch 扩大两重叠加。</li>\n<li>第五步，定并行度：若最终 batch 仍小于 <em>B*</em>，优先 TP 切带宽项以压延迟；若 batch 已接近或超过 <em>B*</em>，改用 EP 省显存给 KV，并按 All-to-All 下界校核通信开销。</li>\n<li>第六步，定 SLO：延迟敏感则取 batch 略低于 <em>B*</em> 并留排队余量；吞吐敏感则顶到 <em>B*</em>，并用 <em>1/T</em><sub>token</sub>×batch×利用率 反推每卡吞吐上界，与 SLO 比对。</li>\n</ul>\n<p>这个算例的工程价值在于：它把“加不加卡、换不换精度、用 TP 还是 EP、batch 开多大”四个决策串成一条由同一个下界驱动的链条，而不是各自拍脑袋。任何一个环节的结论变化（比如 <em>Cap</em><sub>KV</sub> 突然变成约束），都会立刻反映到其他三个决策上。</p>\n\n<h3 id=\"th-moe-roofline-sec-25\">二十五 · 决策时的三个校验点</h3>\n<p>用 roofline 做容量规划，必须在使用前做三项校验，否则公式会给出误导性结论。其一，校验专家权重是否真的每次从 HBM 读：若权重规模小到可常驻 L2 或 SMEM，带宽项失效，应改用片上带宽模型，此时按 HBM 算出的 <em>T</em><sub>token</sub> 会高估延迟、低估吞吐。其二，校验 <em>r</em> 是否真的接近 <em>B·k/E</em>：路由若严重倾斜（少数专家吃掉大部分 token），复用度对热门专家远高于均值、对冷门专家接近 1，摊薄效应不均匀，按均匀假设算出的 <em>B*</em> 会偏乐观，实际更早撞上算力项。其三，校验 batch 是否已越过 <em>B*</em>：一旦越过，继续按带宽项扩容就是典型的容量规划失真——新增 GPU 无法线性提升吞吐，因为瓶颈已换成算力。这三个校验点对应的正是该下界的三个失效条件，做容量决策时逐条对照，比事后调参便宜得多。</p>\n\n<h3 id=\"th-moe-roofline-sec-26\">二十六 · 把 roofline 当决策器：有效 batch、并行度与 KV 预算的联立</h3>\n<p>公式本身只是下界，真正难的是把它变成可执行的容量决策。关键动作是把 \\(\\mathcal{A}(x)\\) 从“单 token 命中集合”升级为“一个 decode step 内被命中的专家集合”，记其并集为 \\(\\mathcal{A}_{\\text{step}}\\)，则带宽项应改写为 \\(\\sum_{e\\in\\mathcal{A}_{\\text{step}}}|W_e|\\cdot b_w / B_{\\text{HBM}}\\)，而不是 batch 内每个 token 各自求和再相加。这一步决定了批大小的收益曲线形状：当 \\(|\\mathcal{A}_{\\text{step}}|\\) 随 batch 增长而趋于饱和（路由分布集中、专家数有限），每 token 摊销的权重字节数按 \\(1/|\\mathcal{A}_{\\text{step}}|\\) 下降，吞吐近似线性上升；一旦并集接近全专家数，带宽项不再随 batch 摊薄，此时若算力项 \\(\\frac{2N_{\\text{act}}P}{F_{\\text{peak}}}\\) 尚未成为主导，扩 batch 仍有收益，反之则进入算力受限区。工程判断的落点是：先测出该模型在目标序列长度下的专家命中并集增长曲线，再据此定 batch，而不是拿峰值算力或单 token 带宽项任一单独外推。</p>\n<p>并行度决策同样受这条边界支配。张量并行把单专家权重切分到多卡，带宽项按卡数近似线性下降，但每层引入 all-reduce/all-gather 通信，解码阶段这些集合通信的延迟无法被计算掩盖，于是 \\(T_{\\text{token}}\\) 的下界要加上通信项；专家并行则让每卡只驻留部分专家，单卡权重字节数下降但 token 需跨卡分发（all-to-all），在小 batch 下 all-to-all 的固定开销占比极高。可用一个粗糙的判据：设单卡权重容量为 \\(C_{\\text{card}}\\)，专家并行度 \\(E_p\\) 必须满足 \\(\\sum_{e\\in\\mathcal{E}}|W_e| b_w / E_p \\le C_{\\text{card}}\\)，同时 KV 预算要留出余量；若算出的 \\(E_p\\) 使每卡仅分到极少专家、而 batch 又小，则 all-to-all 延迟会吞掉带宽收益，此时宁可降 \\(E_p\\)、提高单卡权重占比，用更大的 \\(b_w\\) 压缩（NVFP4）换容量。这正是“把 \\(b_w\\) 从 1 降到 0.5 近似减半带宽项”的用法边界：它省的是字节，不是通信。</p>\n<p>KV 预算与 SLO 必须和 roofline 联立，否则会出现“权重放得下、KV 放不下”或“KV 放得下、延迟不达标”的错配。设每 token 每层 KV 字节为 \\(s_{\\text{kv}}\\)、层数 \\(L\\)、并发序列数 \\(B\\)、平均上下文长度 \\(\\bar{n}\\)，则 KV 占用 \\(M_{\\text{kv}} = 2\\cdot B\\cdot \\bar{n}\\cdot L\\cdot s_{\\text{kv}}\\)（系数 2 对应 K/V 两份），它与权重占用共享 HBM 容量。容量约束写成 \\(M_{\\text{weight}} + M_{\\text{kv}} \\le \\eta\\cdot C_{\\text{HBM}}\\)（\\(\\eta\\) 为留给定影、激活与碎片的安全系数），而延迟约束写成 \\(T_{\\text{token}} \\le \\text{TPOT}_{\\text{SLO}}\\)。两条约束的交集才是可行域：先由延迟约束定出单卡可承载的 batch 上限（带宽项或算力项取大者），再由容量约束反推最大 \\(\\bar{n}\\)，二者取小即为该卡型的服务档位。若解出的 \\(\\bar{n}\\) 远低于业务上下文长度，说明需要更多卡做序列并行或改用 KV 量化，而不是继续加 batch。</p>\n<p>算例（定性量级，仅示范流程）：某 MoE 模型激活参数 \\(N_{\\text{act}}\\) 远小于总参数，专家权重以 FP8 存放（\\(b_w=1\\)），单卡 HBM 容量固定。第一步，按小 batch 估算带宽项，得到单 token 时间下限，换算单卡 TPOT；若该值已逼近 SLO 上限，说明单卡在小 batch 下被 HBM 带宽锁死，此时把权重换 NVFP4（\\(b_w\\approx0.5\\)）可近似减半带宽项，TPOT 下界随之下降，这是最直接的杠杆。第二步，增大 batch 观察专家并集增长：若并集很快饱和，带宽项不再摊薄，需检查算力项是否接管；若接管，则继续加 batch 只提升吞吐不改善 TPOT，容量规划应按算力受限区重算，新增 GPU 不再线性增益。第三步，把剩余 HBM 容量代入 \\(M_{\\text{kv}}\\) 公式反推 \\(\\bar{n}\\)，若结果小于业务上下文，则要么降并发、要么上 KV 量化、要么拆分为预填/解码分离部署。整条链路中，最易失效的假设是“专家权重可常驻 L2 或 SMEM”——一旦权重规模超出片上缓存容量，带宽项立刻退化为 HBM 模型，先前按片上带宽做的吞吐预测全部作废，因此任何缓存假设都必须先用容量校验兜底。</p>\n\n<h3 id=\"th-moe-roofline-sec-27\">二十七 · 把下界变成容量决策：有效 batch、KV 预算与 SLO 的三条约束线</h3>\n<p>公式本身只给出单 token 的下界，工程上要把它转成“每卡能挂多少并发”，必须引入有效 batch 的概念。设并发 batch 为 <span class=\"inline-math\">B</span>，同一专家被命中的平均复用度为 <span class=\"inline-math\">r(B)</span>，则带宽项被摊薄为 <span class=\"inline-math\">∑|W_e|·b_w / (B·r(B)·B_HBM)</span>；当 <span class=\"inline-math\">B·r(B)</span> 增长到使该项低于算力项 <span class=\"inline-math\">2·N_act·P/F_peak</span> 时，roofline 拐点出现，此后扩容 GPU 只增加算力供给而不减带宽压力。因此定批大小的正确做法是解一个双约束方程：先按带宽项估出“带宽饱和 batch” <span class=\"inline-math\">B_bw</span>，再按算力项估出“算力饱和 batch” <span class=\"inline-math\">B_flop</span>，取两者较小值作为单卡 batch 上限的初值。若 <span class=\"inline-math\">B_bw &lt; B_flop</span>，说明该部署仍处带宽锁定区，此时把 b_w 从 FP8 的 1 降到 NVFP4 的约 0.5，等价于把 <span class=\"inline-math\">B_bw</span> 近似翻倍，是比加卡更便宜的扩容手段；反之若 <span class=\"inline-math\">B_flop</span> 先到，继续压精度只减少带宽项而算力项不动，收益立刻归零。</p>\n<p>KV 预算与这条曲线耦合，不能独立拍板。解码期每 token 的 KV 字节数为 <span class=\"inline-math\">2·L·H_kv·d_head·b_kv</span>（层数、KV 头数、头维、KV 精度字节），它与权重常驻量共同瓜分 HBM：<span class=\"inline-math\">M_weights + B·S·KV_per_token ≤ M_HBM·η</span>，其中 <span class=\"inline-math\">S</span> 为平均上下文长度，<span class=\"inline-math\">η</span> 为可用显存占比。这条不等式给出的是 batch 的硬上限，往往比 roofline 的 <span class=\"inline-math\">B_bw</span> 更早生效——尤其在长上下文场景，KV 增长是线性的而权重是常数，批大小会被 KV 而非带宽锁死。此时 roofline 给出的吞吐预测会系统性偏高，因为公式里根本没有 KV 项；正确做法是把 KV 约束作为外层循环，先定 <span class=\"inline-math\">B_max = min(B_bw, B_flop, B_kv)</span>，再回代校验带宽项是否仍成立。</p>\n<p>SLO 决策则要区分 TTFT 与 TPOT 两条线。预填阶段算术强度高，受算力项支配，适合用大 chunk 摊薄；解码阶段受带宽项支配，TPOT 下界即 <span class=\"inline-math\">T_token</span>，任何调度技巧都无法突破。因此定 SLO 时应先算出目标 TPOT 对应的最大可容忍 <span class=\"inline-math\">T_token</span>，反推允许的专家权重读取量，再决定是否启用 NVFP4 或专家常驻策略。算例：某 MoE 模型单专家 FP8 权重 <span class=\"inline-math\">|W_e|·b_w</span> 记为 <span class=\"inline-math\">w</span> 字节，top-k 命中 <span class=\"inline-math\">k</span> 个专家，则带宽项为 <span class=\"inline-math\">k·w/B_HBM</span>；若 SLO 要求 TPOT 不超过该值的 1.5 倍，则留给调度与通信的余量仅 50%，此时任何跨节点 all-to-all 的抖动都会击穿 SLO，分离式部署必须把专家并行限制在单 NVLink 域内。反过来，若实测 TPOT 远高于 <span class=\"inline-math\">k·w/B_HBM</span>，说明瓶颈不在 HBM 而在路由或通信，继续按 roofline 扩容是方向性错误。</p>\n<p>三个失效条件必须写进容量评审清单。其一，假设专家权重可常驻 L2 或 SMEM 而不校验容量：单卡 SMEM 与 L2 容量有限，全部专家权重之和一旦超出，roofline 立即退化为 HBM 带宽模型，此前按片上带宽做的吞吐预测全部作废，预测偏差可达数倍。其二，在小 batch 下用 tcgen05 峰值算力估算吞吐，忽视带宽项，实际被 HBM 锁死。其三，在大 batch 专家复用充分、瓶颈已转向算力项时仍按带宽项扩容，新增 GPU 无法线性提升吞吐。工程判断的落点是：每次调整 batch、精度或并行度后，都要重算 <span class=\"inline-math\">B_bw</span>、<span class=\"inline-math\">B_flop</span>、<span class=\"inline-math\">B_kv</span> 三个数并取最小，roofline 只是其中一条约束线，不是容量规划的全部。</p>\n<h3 id=\"th-moe-roofline-sec-28\">二十八 · 误用一：拿峰值算力当吞吐上限</h3>\n<p>最常见的误用，是把 tcgen05 的峰值算力直接当成解码吞吐的分母。做法通常是这样：拿到 F_peak，除以 2·N_act 得到“每 token 需要的时间”，再取倒数乘以 batch，得到一个看起来很漂亮的 tokens/s，然后据此写容量规划。这个数在 prefill 阶段或许还沾边，在 MoE 解码阶段则系统性偏高，因为 roofline 的下界是两项取 max，而小 batch 下起决定作用的是带宽项，算力项根本不是约束。</p>\n<p>识别方法很直接：把两个候选值都算出来做比值。设命中专家集合的权重字节数为 <span class=\"inline-math\">Σ|W_e|·b_w</span>，带宽项为它除以 B_HBM；算力项为 2·N_act·P / F_peak。若带宽项显著大于算力项，任何以 F_peak 为主轴的吞吐估算都是错的。工程上更稳妥的做法是先算“每 token 权重读取字节数”这一个量——它只依赖路由结果和精度，与 batch 无关——再除以有效带宽，得到单 token 的带宽下界。这个量在 FP8 下是激活专家参数量的一倍字节，NVFP4 下约减半，两者相差近 2 倍，正好对应吞吐的近 2 倍差距，这也是精度选择在解码侧最直接的杠杆。</p>\n<p>后果不是“估算偏乐观”这么轻。按峰值算力做的容量规划会低估所需 GPU 数，上线后单卡并发一压就撞到 HBM 墙，尾延迟抬升，SLO 违约；更糟的是团队会误以为是调度或框架问题，去调 batch size、换 attention backend、加投机解码，全都无效，因为瓶颈根本不在那条路径上。一个具体例子：某部署按算力项估算单卡可支撑的并发 batch，实际运行时每 token 时间被权重读取锁死，增加并发只增加排队而不增加吞吐，表现为 GPU 利用率看着不低、tokens/s 却纹丝不动——这就是带宽项主导的典型指纹。</p>\n\n<h3 id=\"th-moe-roofline-sec-29\">二十九 · 误用二：大 batch 下仍按带宽项扩容</h3>\n<p>反向的误用同样常见，而且更隐蔽。当 batch 足够大、同一专家被多个 token 复用时，权重读取被摊薄，roofline 的瓶颈从带宽项转向算力项。此时若还按“权重字节数 / 带宽”做扩容决策，就会得出“加卡线性提升吞吐”的错误结论。实际加卡后，每张卡上的算力项成为新约束，吞吐增长远低于线性，容量规划失真。</p>\n<p>这里的关键机制是“有效 batch”这个概念：不是调度器里的 batch size，而是每个专家实际被复用的 token 数。只有当某专家的复用度足够高，其权重读取成本才被摊到多个 token 上，单 token 分摊的带宽项下降；一旦分摊后的带宽项低于算力项，max 就切换到算力侧。识别这一点的工程手段是监控两个量：每 token 实际读取的权重字节数（可由路由统计与精度推算），以及每 token 的实际 FLOPs 与 F_peak 的比值。前者随复用度上升而下降，后者随 batch 上升而逼近 1。当后者开始主导，扩容策略必须换成提升算力效率——更激进的量化、更好的 MMA 利用率、减少非矩阵开销——而不是简单堆 GPU。</p>\n<p>伪代码思路可以写成：对每个 batch 配置，计算 <span class=\"inline-math\">reuse_e = tokens_e / 1</span>（该专家被多少 token 命中），带宽项变为 <span class=\"inline-math\">Σ_e |W_e|·b_w / reuse_e / B_HBM</span>，再与算力项取 max，得到该配置下的单 token 时间下界。若这个下界随 batch 增大而趋平，说明已进入算力区，扩容收益递减。代价上，这直接决定 GPU 采购与集群规模：在算力区扩容，钱花在算力上却拿不到吞吐，是典型的资本效率损失。</p>\n\n<h3 id=\"th-moe-roofline-sec-30\">三十 · 误用三：假设权重常驻片上而不校验容量</h3>\n<p>第三种误用是把“专家权重常驻 SMEM/L2”当成前提写进模型，却不校验容量。roofline 的适用边界写得很清楚：若专家权重常驻 SMEM/L2，或被 NVFP4 压缩到可缓存规模，HBM 带宽项失效，需改用片上带宽模型。问题在于，MoE 的专家总数乘以单专家参数量，往往远超 L2 容量；SMEM 更是每 SM 百 KB 级别，装不下哪怕一个中等专家。把“常驻”当默认假设，等于把 HBM 带宽模型悄悄换成了一个不存在的片上模型，预测偏差会非常大。</p>\n<p>校验方法：先算专家权重总字节数 <span class=\"inline-math\">E · |W_e| · b_w</span>，与目标硬件的 L2 容量比较；再算单专家字节数与单 SM 可用 SMEM 比较。只有当前者能整体落入 L2、或路由局部性使得热专家集合能落入 L2 时，片上模型才成立。NVFP4 把 b_w 从 1 降到约 0.5，确实能把可缓存规模的门槛推高一倍，但这是“把不可能变成可能”的量级问题，不是“默认成立”的假设。若专家规模仍超出片上缓存，roofline 必须退回 HBM 带宽模型，否则预测会系统性偏低（以为很快，实际被 HBM 锁死）。</p>\n<p>后果体现在延迟预测与 SLO 上：按片上模型估算的单 token 时间远小于实际，导致超时阈值设得过紧、批调度参数配错，上线后大面积超时。一个具体例子：某团队看到 NVFP4 把权重压到一半，就推断“专家可常驻 L2”，据此把并发拉到很高；实际权重总量仍远超 L2，每次解码仍要走 HBM，吞吐没有提升反而因并发过高导致 cache 抖动，尾延迟恶化。识别信号是 L2 命中率与 HBM 流量的实测比值——若 HBM 流量仍与权重读取量同阶，片上假设就不成立。</p>\n\n<h3 id=\"th-moe-roofline-sec-31\">三十一 · 一个反例：三处误用叠加的容量规划</h3>\n<p>构造一个反例把三种误用串起来。某 MoE 模型部署在 Blackwell 单机上，团队做容量规划时：第一步用 F_peak 除以 2·N_act 估单 token 时间，得到乐观吞吐；第二步假设 NVFP4 后专家权重可常驻 L2，进一步下调单 token 时间；第三步按这个时间乘以目标并发，得出“单卡可承载的 batch 上限”，并据此决定不扩容。三处误用叠加，预测吞吐被高估了数倍。</p>\n<p>实际运行时的表现是：小 batch 下每 token 时间由 HBM 带宽项锁死，与算力项无关；权重总量超出 L2，片上假设不成立，NVFP4 只带来带宽项约减半的收益而非数量级收益；并发一拉高，专家复用虽使带宽项摊薄，但算力项随即成为新约束，吞吐趋平。结果是单卡实际吞吐远低于规划值，SLO 违约，而团队按“加卡不线性”的直觉又不敢扩容，陷入两难。正确的诊断顺序应是：先算带宽项与算力项的比值确定当前区间，再校验权重总量与 L2/SMEM 容量决定用哪个模型，最后按有效 batch 重算 max，得出扩容是否有线性收益。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>以 F_peak 估吞吐</td><td>带宽项 ≫ 算力项，tokens/s 不随并发增长</td><td>GPU 数低估，尾延迟与 SLO 违约</td></tr><tr><td>大 batch 仍按带宽扩容</td><td>单 token 下界随 batch 趋平</td><td>扩容非线性，资本效率损失</td></tr><tr><td>假设权重常驻片上</td><td>HBM 流量与权重读取量同阶，L2 命中率低</td><td>延迟预测偏低，超时与 cache 抖动</td></tr></tbody></table>\n\n<h3 id=\"th-moe-roofline-sec-32\">三十二 · 工程判断：把 roofline 当诊断工具而非预测器</h3>\n<p>上述误用的共同根源，是把 roofline 当成一个“算出数就能用”的预测器，而不是一个“判断当前被什么锁死”的诊断工具。正确的用法是每次决策前先做区间判定：算带宽项与算力项的比值，落在带宽区就用 b_w 做杠杆（FP8 到 NVFP4 近似减半带宽项），落在算力区就转向 MMA 利用率与非矩阵开销；同时校验权重总量与片上容量，决定 HBM 模型是否仍然有效。这三个判定各自只需几个已知量，却能把绝大多数误用挡在决策之外。</p>\n<p>落到具体机制上，最值得固化成检查项的是“每 token 权重读取字节数”这一个标量：它同时编码了路由命中数、单专家参数量与精度，是带宽项的唯一输入；把它与实测 HBM 流量对比，就能立刻发现片上假设是否成立、精度收益是否兑现。再把它除以有效复用度，就得到摊薄后的带宽项，与算力项取 max 即为当前配置的真实下界。工程判断的落点在这里：不是相信某一个公式给出的数字，而是持续用实测流量去校准公式里的每一项，让 roofline 始终描述机器正在发生的事。</p>\n\n<h3 id=\"th-moe-roofline-sec-33\">三十三 · 误用与反例：把 roofline 当恒等式用</h3>\n<p>最常见的误用是把 roofline 下界当成吞吐预测器：在小 batch 解码场景下直接拿 tcgen05 峰值算力乘利用率去估 token/s，完全不看权重读取项。后果是预测值与实测严重背离——每 token 只激活少数专家，算术强度被压到极低，单 token 时间几乎完全由激活专家的权重字节数除以 HBM 带宽决定，峰值算力基本用不上。识别方法很简单：先算带宽项 $\\sum_{e\\in\\mathcal{A}(x)}|W_e|\\cdot b_w / B_{\\text{HBM}}$，再算算力项 $2 N_{\\text{act}} P / F_{\\text{peak}}$，若前者比后者大一个数量级以上而报告里只出现后者，这份容量规划就是错的。工程代价直接体现在显存与带宽预算上：按算力估出的并发上限会诱使部署方削减卡数，实际运行时 HBM 带宽先饱和，SLO 的 TPOT 指标无法达成。</p>\n<p>第二个误用方向相反：在 batch 足够大、同一专家被多 token 复用使权重读取摊薄之后，仍按带宽项线性扩容。此时瓶颈已转向算力项，roofline 必须按有效 batch 重算——有效 batch 不是请求数，而是按专家命中分布折算后的复用度。若继续按“加卡即加吞吐”的带宽模型做容量规划，新增 GPU 无法线性提升吞吐，钱花在不会成为瓶颈的资源上。识别信号是监控里 HBM 带宽利用率不再随并发上升而饱和、而 SM 的 MMA 管道占用率持续走高。这一条对分离式预填/解码部署尤其致命：解码池按带宽项配卡，预填池却把专家权重反复换入换出，两边预算互相污染。</p>\n<p>第三个误用是假设专家权重可常驻 L2 或 SMEM 而不校验容量。Blackwell 的 L2 与每 SM 的 SMEM 都是有限资源，MoE 的专家权重总量通常远超片上缓存；一旦实际规模超出，roofline 就退化为 HBM 带宽模型，任何基于“片上命中”的预测都显著偏高。识别办法是做容量核算：把常驻专家的字节数与可用 L2/SMEM 容量对比，并观察 NVFP4 压缩后是否真的落进可缓存规模——$b_w$ 从 FP8 的 1 降到 NVFP4 的约 0.5 只是近似减半带宽项，并不自动意味着能常驻。若压缩后仍装不下，就必须回到 HBM 带宽模型重算，否则片上带宽模型的乐观预测会在真实负载下崩塌。</p>\n<p>反例：某部署把 8 卡解码池的吞吐按峰值算力折算，宣称单卡可承载远超实际的并发，实际压测时 TPOT 随并发线性恶化——因为每 token 的权重读取量固定，HBM 带宽被占满，加卡只是把同一份带宽预算切得更碎。正确做法是先按带宽项定单卡并发上限，再在专家复用度提升后用有效 batch 重算算力项，两套模型取较紧的一侧作为容量边界；同时把 $b_w$ 的选择（FP8 还是 NVFP4）作为独立决策变量，用带宽项的近似减半效果去换吞吐，而不是拿它去论证片上缓存可行性。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\mathcal{A}(x)</td><td>token x 路由命中的专家集合（top-k）</td></tr><tr><td>|W_e|</td><td>单个专家的参数量</td></tr><tr><td>b_w</td><td>权重每参数字节数（FP8=1，NVFP4≈0.5）</td></tr><tr><td>B_{\\text{HBM}}</td><td>Blackwell HBM3e 有效带宽</td></tr><tr><td>N_{\\text{act}}</td><td>激活参数量</td></tr><tr><td>F_{\\text{peak}}</td><td>tcgen05 峰值算力</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-moe-roofline · 共 5 个片段</p>\n"},{"id":"th-kv-cache-mem","title":"KV cache 显存占用式","direction":"dir-grouped-gemm-tcgen05","prereq":[],"plain":"KV cache 字节数随并发序列数、上下文长度和层数线性增长，是长上下文与高并发下决定单卡能放多少请求的硬约束。","definition":"KV cache 字节数随并发序列数、上下文长度和层数线性增长，是长上下文与高并发下决定单卡能放多少请求的硬约束。","formula":"$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$","variables":[{"sym":"L","meaning":"Transformer 层数"},{"sym":"H_{kv}","meaning":"KV 头数（GQA 下小于注意力头数）"},{"sym":"d_h","meaning":"每头维度"},{"sym":"b_{kv}","meaning":"KV 每元素字节数（FP8=1，NVFP4≈0.5）"},{"sym":"B_i","meaning":"第 i 条序列的 token 数"}],"derivation":"推导的关键一步是把单序列单层 KV 占用写成 2·H_kv·d_h·b_kv·B_i，再对 L 层与 N 条序列求和；系数 2 与 H_kv 的取值直接决定结果量级，GQA 下必须用实际 KV 头数而非注意力头数。","example":"在推理容量决策中，该式用于反解单卡可并发序列数上限、判断长上下文请求是否放得下，并作为批调度与 SLO 约束的硬输入；结合 b_kv 从 FP8 降到 NVFP4 可估算量化带来的容量增益。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["采用 GQA/MQA 时 H_kv 远小于 H，公式需按实际 KV 头数代入，否则高估数倍","分页/前缀共享（PagedAttention、Mooncake）下同一前缀被多请求复用，按 sum B_i 计会高估真实占用"],"system_note":"常见误用是直接用注意力头数 H 代替 H_kv 估算 GQA 模型，导致容量规划偏保守、批大小设得过小；另一误用是忽略前缀共享，把共享前缀重复计入每条序列，造成显存预算虚高。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉上，KV cache 是每条序列在每层、每个 KV 头上缓存的历史 key/value 张量，其字节数随并发序列数、上下文长度和层数线性增长，因此长上下文与高并发场景下，单卡能容纳多少请求首先被它卡住。","公式中系数 2 对应 key 与 value 两份张量；L 为层数，H_kv 为 KV 头数（GQA 下小于注意力头数），d_h 为每头维度，b_kv 为每元素字节数（FP8=1，NVFP4≈0.5），sum B_i 为批内各序列 token 数之和，乘积即总字节数。","推导的关键一步是把单序列单层 KV 占用写成 2·H_kv·d_h·b_kv·B_i，再对 L 层与 N 条序列求和；系数 2 与 H_kv 的取值直接决定结果量级，GQA 下必须用实际 KV 头数而非注意力头数。","适用边界是标准多头或 GQA 解码缓存；失效条件有二：采用 GQA/MQA 时若误用注意力头数 H 代入会高估数倍；分页/前缀共享（PagedAttention、Mooncake）下同一前缀被多请求复用，按 sum B_i 计会高估真实占用。","在推理容量决策中，该式用于反解单卡可并发序列数上限、判断长上下文请求是否放得下，并作为批调度与 SLO 约束的硬输入；结合 b_kv 从 FP8 降到 NVFP4 可估算量化带来的容量增益。","常见误用是直接用注意力头数 H 代替 H_kv 估算 GQA 模型，导致容量规划偏保守、批大小设得过小；另一误用是忽略前缀共享，把共享前缀重复计入每条序列，造成显存预算虚高。"],"anchors":["2","FP8=1","NVFP4≈0.5","16"],"pitfalls":["用注意力头数 H 而非 KV 头数 H_kv 代入公式，GQA 模型下高估数倍，批大小被压得过低、吞吐浪费。","忽略 PagedAttention/Mooncake 的前缀共享，把共享前缀按每条序列重复计入 sum B_i，显存预算虚高导致上线后 OOM。","只按平均上下文长度估算，未考虑长尾请求的 B_i 峰值，单条超长序列即可挤占整卡 KV 空间。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-1\">一 · 一句话直觉与严格定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-2\">二 · 为什么需要这条式子：它是容量决策的硬输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-3\">三 · 常见误解一：用注意力头数 H 代替 H_kv</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-4\">四 · 常见误解二：忽略前缀共享，把 sum B_i 当成真实占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-5\">五 · 常见误解三：按平均上下文长度估算，忽略长尾峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-6\">六 · 适用边界与失效条件的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-7\">七 · 边界在哪：公式的适用域、失效条件与容量代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-8\">八 · 逐项拆解：每个因子在显存里对应哪一块物理页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-9\">九 · 推导关键步：从单序列单层到批总和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-10\">十 · 离散化与近似：三个偏差源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-11\">十一 · 反解与敏感度：哪个因子真正决定容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-12\">十二 · 与调度和 SLO 的耦合：公式作为硬约束输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-13\">十三 · 精度切换时的重算边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-14\">十四 · 把公式放到边界上：什么时候它开始骗人</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-15\">十五 · 公式成立的前提：静态、独占、无共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-16\">十六 · 失效条件一：GQA/MQA 下头数代入错误</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-17\">十七 · 失效条件二：前缀共享打破 sum B_i 的可加性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-18\">十八 · 失效条件三：长尾 B_i 峰值与动态增长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-19\">十九 · 公式何时仍然可信：一个工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-20\">二十 · 公式成立的前提：从“逐序列独立缓存”到“共享前缀复用”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-21\">二十一 · 公式在什么条件下不再成立：头数口径、前缀复用与长尾峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-22\">二十二 · 从字节数到并发上限：反解 N</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-23\">二十三 · 定并行度：TP 与 KV 池的除法关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-24\">二十四 · 定 KV 预算：b_kv 与量化增益的定量换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-25\">二十五 · 定 SLO：把 TTFT 与 TPOT 翻译成 KV 约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-26\">二十六 · 算例：一个 GQA 模型的容量决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-27\">二十七 · 容量反解：把 KV 字节式变成批大小、并行度与 SLO 的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-28\">二十八 · 容量反解：从字节预算倒推批大小、并行度与 SLO 余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-29\">二十九 · 误用一：用注意力头数 H 顶替 H_kv</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-30\">三十 · 误用二：把共享前缀按每条序列重复计入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-31\">三十一 · 误用三：只按平均上下文长度估算，无视长尾峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-32\">三十二 · 反例：一次“算得很准”的上线事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-33\">三十三 · 精度位宽与误用的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-34\">三十四 · 误用与反例：从&quot;算多了&quot;到&quot;算漏了&quot;的两头翻车</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-mem-sec-35\">三十五 · 误用与反例：容量预算为何在真实流量下失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:544px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 544.5 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：KV cache 字节数随并发序列数、上下文长度和层数线性增长，是…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$M_{\\text{KV}} = 2\\cdot L\\cdot H…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：采用 GQA/MQA 时 H_kv 远小于 H，公式需按实际 KV…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-kv-cache-mem-sec-1\">一 · 一句话直觉与严格定义</h3>\n<p>KV cache 是解码阶段为了免去重复计算而驻留在显存里的历史 key/value 张量：每条序列在每一层、每一个 KV 头上都保留一份自己的 K 与 V，长度等于该序列已处理的 token 数。它的字节数随并发序列数、上下文长度和层数三者线性增长，因此在长上下文与高并发叠加时，单卡能装下多少请求首先被它卡住，而不是被权重或激活卡住。</p>\n<p>严格定义写成一条可代入的容量式：</p>\n<div class=\"formula\">$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$</div>\n<p>其中 L 为 Transformer 层数，H_kv 为 KV 头数（GQA 下严格小于注意力头数 H），d_h 为每头维度，b_kv 为 KV 每元素字节数（FP8=1，NVFP4≈0.5），B_i 为批内第 i 条序列的 token 数，N 为并发序列数。系数 2 对应 key 与 value 两份张量，这是最容易漏掉的一项——漏掉它，容量估算直接砍半，上线后必然 OOM。</p>\n<p>推导路径很短：先把单序列单层 KV 占用写成 2·H_kv·d_h·b_kv·B_i，再对 L 层求和、对 N 条序列求和。量级由系数 2 与 H_kv 共同决定，这也解释了为什么 GQA 模型的 KV 占用能比同规模 MHA 模型低一个可观的倍数：H_kv 缩小，整条式子等比缩小。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-2\">二 · 为什么需要这条式子：它是容量决策的硬输入</h3>\n<p>推理系统里，权重占用是静态的、可预先算死的；激活占用随批大小波动但峰值有限；只有 KV cache 是随运行时状态（并发数、每条序列长度）动态膨胀的那一项。因此“这张卡还能不能再接一个请求”这个问题，答案几乎总是由 KV cache 剩余空间决定。这条式子的工程价值在于它是可反解的：给定卡上剩余显存，反解出可并发序列数上限 N_max；给定一条长上下文请求的 B_i，判断它是否放得下；给定 b_kv 从 FP8 降到 NVFP4，估算量化带来的容量增益。</p>\n<p>它同时是批调度与 SLO 约束的硬输入。连续批处理在每一步决定接纳哪些请求、驱逐哪些请求，判据就是 KV 预算；分离式预填/解码部署里，预填节点把 KV 传给解码节点，传输量与这条式子成正比，直接决定 NVLink 5 上的搬运时间和 NIXL 传输路径的选型。换句话说，KV 容量式不是一张事后核算表，而是调度器的约束条件本身。</p>\n<p>一个具体例子：某 GQA 模型 L 层、H_kv 个 KV 头、d_h 维，以 FP8 缓存。若把 b_kv 换成 NVFP4 的约 0.5，同一张卡上可容纳的 token 总量翻倍——这不是“省一点显存”，而是并发上限的整数倍变化，直接改变批大小与吞吐曲线的形状。工程上判断是否值得为 NVFP4 KV 付出量化误差代价，第一步就是拿这条式子算出容量增益是否落在关键区间。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-3\">三 · 常见误解一：用注意力头数 H 代替 H_kv</h3>\n<p>最普遍的误用是拿模型配置里的注意力头数 H 直接代入 H_kv。GQA 模型里 H_kv 远小于 H，误代会让估算结果高估数倍，容量规划偏保守，批大小被压得过低，吞吐白白浪费。这种错误在工程上很隐蔽：算出来的数字“看起来合理”，只是偏大，于是团队把并发上限设得很低，GPU 利用率长期上不去，却找不到原因。</p>\n<p>正确的做法是从模型配置里读 KV 头数字段，而不是从注意力头数字段推断。伪代码思路很简单：<code>kv_bytes_per_token = 2 * L * H_kv * d_h * b_kv</code>，然后 <code>capacity_tokens = free_mem / kv_bytes_per_token</code>，再用 <code>sum B_i</code> 与并发数做约束求解。整个计算只有一次乘法链，出错点全在取哪个 H。MQA 是 GQA 的极端情形，H_kv=1，此时若误用 H，高估幅度最大。</p>\n<p>代价是双向的：估高了，批大小设小，解码阶段每步的矩阵乘规模不足，算力利用率低、单位 token 成本高；估低了，批大小设大，运行时 KV 分配失败触发抢占与重算，尾延迟飙升。前者浪费吞吐，后者破坏 SLO，两种都源于同一个变量取错。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-4\">四 · 常见误解二：忽略前缀共享，把 sum B_i 当成真实占用</h3>\n<p>第二个误用是把批内每条序列的 token 数简单相加，忽略分页与前缀共享。PagedAttention 把 KV 切成固定大小的块并按块分配，Mooncake 一类系统让多个请求复用同一段前缀的 KV 块。此时同一前缀在物理显存里只存一份，而按 <code>sum B_i</code> 计会把共享前缀按请求数重复计入，显存预算虚高，上线后要么过度保守、要么在真实峰值下 OOM。</p>\n<p>修正思路是把式子里的 <code>sum B_i</code> 换成“去重后的物理 token 块总数”：先按前缀树把请求分组，共享前缀只计一次，各请求只计自己独有的后缀。工程上这意味着容量式不再是纯静态公式，而要向调度器查询当前前缀命中率与块复用情况。前缀命中率越高，真实占用相对 <code>sum B_i</code> 的偏差越大，这条式子的预测力越弱——这不是公式错了，而是公式的适用边界被越过了。</p>\n<p>代价体现在显存带宽与调度复杂度上：前缀共享省下的是容量，付出的是块表管理与跨请求引用计数的开销；共享块被多个请求引用时，驱逐策略必须等最后一个引用释放才能回收，否则会出现悬空引用。容量收益与调度开销的权衡，正是分页系统设计的核心。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-5\">五 · 常见误解三：按平均上下文长度估算，忽略长尾峰值</h3>\n<p>第三个误用是用平均 B_i 做容量规划。KV 占用对 B_i 是线性的，但请求长度分布是重尾的：一条超长序列的 B_i 就可能挤占整卡 KV 空间，把同批其他请求全部挤出。按均值估算得到的并发上限，在长尾请求到达时立刻失效。</p>\n<p>正确的做法是按分位数而非均值做预算：用 P99 或更高的 B_i 峰值代入，或者显式保留一块“长请求预留区”，让超长序列走单独队列、限制其并发数。伪代码层面就是在调度器里加一条约束：<code>sum over admitted requests of kv_bytes(B_i) &lt;= kv_budget</code>，其中 kv_budget 已扣除长尾预留。这条约束在连续批处理的每一步都要重新求解，因为 B_i 随解码推进单调增长。</p>\n<p>代价是吞吐与尾延迟的取舍：为长尾预留显存，等于常态下牺牲一部分并发；不预留，则长请求到达时触发抢占、重算甚至拒绝服务。工程判断的依据是 SLO 里尾延迟的权重——如果 P99 时延是硬指标，预留就是必须的；如果吞吐优先，就要接受长请求被降级或排队。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-6\">六 · 适用边界与失效条件的工程读法</h3>\n<p>这条式子的适用边界是标准多头或 GQA 解码缓存：每层每 KV 头一份连续或分块的 K/V 张量，长度等于序列 token 数。越过边界，式子要么高估、要么需要改写。两类失效条件已经明确：误用 H 代替 H_kv 导致高估数倍；忽略前缀共享导致预算虚高。两者都不是数值精度问题，而是变量语义取错。</p>\n<p>工程上应把这条式子当作“上界估计器”而非“精确账本”：它给出的是无共享、无压缩、按注意力头数正确代入时的占用上界。真实占用只会因前缀共享、KV 量化、块对齐浪费等因素偏离，偏离方向可正可负——块对齐会造成内部碎片使真实占用略高于按 token 精确计算的值，前缀共享则使其显著低于 <code>sum B_i</code>。容量决策时先算上界，再用运行时监控的前缀命中率与块利用率做修正，比直接相信单一数字可靠。</p>\n<p>最后一个工程判断落在 b_kv 上：FP8 到 NVFP4 的容量翻倍是这条式子最直接的杠杆，但它把量化误差引入 KV，误差会沿解码步累积。是否采用，取决于这条式子算出的容量增益是否恰好把并发上限推过某个关键阈值——推不过，就不值得付误差代价；推得过，容量收益就是决定性的。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-7\">七 · 边界在哪：公式的适用域、失效条件与容量代价</h3>\n<p>公式本身只是一次乘法，真正决定它能不能用于容量决策的是三个前提：缓存结构是标准多头或 GQA 解码缓存、批内序列互不共享前缀、以及 B_i 取的是真实峰值而非均值。只要有一条不成立，算出来的就不是占用而是上限估计。最容易踩的是头数代入：GQA 下 KV 头数 H_kv 远小于注意力头数 H，若图省事直接拿 H 代入，结果按 H/H_kv 的倍数被放大，容量规划立刻偏保守，批大小被压到远低于硬件实际能承载的水平，吞吐白白浪费。工程上应把 H_kv 作为模型配置里的独立字段读取，而不是从注意力头数推导。</p>\n<p>第二个失效点是前缀共享。PagedAttention 的块表与 Mooncake 的跨请求前缀复用，都会让同一段系统提示或 few-shot 前缀在物理显存里只存一份，而公式里的 sum B_i 是按逻辑 token 数逐序列累加的。共享前缀越长、并发越高，高估越严重——预算虚高的直接后果是上线时按乐观数字配置并发，真实负载一上来就 OOM。正确做法是把 sum B_i 拆成“独占 token 之和 + 去重后的共享前缀 token 数”，共享部分只计一次。第三个失效点是长尾：按平均上下文长度估算会系统性低估，因为 KV 占用对 B_i 是线性的，单条超长序列就能吃掉整卡剩余空间，把同批其他请求挤出去。容量规划必须用 P99 甚至 max(B_i) 做压力测试，而不是均值。</p>\n<div class=\"formula\">$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$</div>\n<p>把公式反过来用，才是它在系统里的主要价值：给定单卡可用于 KV 的显存预算 M_budget（总显存减去权重、激活峰值、通信缓冲与框架开销），可并发序列数上限近似为 N_max ≈ M_budget / (2·L·H_kv·d_h·b_kv·B̄)，其中 B̄ 是规划用的上下文长度。这个反解直接喂给批调度器作为硬约束，也是 SLO 容量规划里“每卡能挂几个请求”的第一道闸。降低 b_kv 是最直接的杠杆：FP8 取 1 字节，NVFP4 约 0.5 字节，同一预算下容量近似翻倍，代价是量化误差进入注意力打分，需要与精度容忍度一起评估。注意这里的代价是显存带宽与延迟的联动——KV 越大，每步解码要读的张量越多，单 token 延迟随批内总 token 数上升，因此容量上限并不等于吞吐最优，批大小还要受 decode 阶段带宽约束二次裁剪。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>公式行为</th><th>系统后果</th></tr></thead><tbody><tr><td>GQA 模型误用 H 代入</td><td>结果放大 H/H_kv 倍</td><td>批大小过小，吞吐浪费</td></tr><tr><td>前缀共享未去重</td><td>sum B_i 重复计入共享段</td><td>预算虚高，上线 OOM</td></tr><tr><td>按均值估 B_i</td><td>忽略长尾峰值</td><td>单条超长序列挤占整卡</td></tr></tbody></table>\n<p>还有一个常被忽略的边界：该式描述的是稳态解码期的 KV 驻留量，不包含预填充阶段的瞬时峰值与块表、页元数据等管理开销。分页分配下块粒度带来的内部碎片、以及为投机解码额外保留的 draft 分支缓存，都会在公式结果之上叠加一层不可忽略的附加项。因此工程判断应落在“公式给出下界、实测给出上界”这一对括号里：用公式快速筛掉明显放不下的配置，用真实负载的峰值占用去校准那层附加开销，两者之间的差额就是调度器必须留出的安全余量。</p>\n<h3 id=\"th-kv-cache-mem-sec-8\">八 · 逐项拆解：每个因子在显存里对应哪一块物理页</h3>\n<p>把公式拆成可核对的物理量，是排查容量偏差的第一步。$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$ 中，<code>2·H_kv·d_h·b_kv</code> 是“单层单 token 的 KV 字节数”，它是一个与序列长度无关的常量，只由模型结构和数值精度决定；<code>∑B_i</code> 才是随负载变化的动态项。工程上应把前者算成一个标量常数 <code>c_layer</code>，再乘以 <code>L</code> 得到单 token 全层字节数 <code>c_tok</code>，这样容量估算就退化为“<code>c_tok</code> × 总 token 数”，与分页块大小对齐时尤其方便。</p>\n<p>系数 2 不是近似，而是 key 与 value 两份独立张量的精确计数；<code>L</code> 是精确整数；<code>d_h</code> 由 head_dim 决定，在 Blackwell 上常见的 128 或 64 会直接改变 <code>c_tok</code> 的量级；<code>b_kv</code> 是唯一带近似性质的因子——FP8 取 1 是精确的，NVFP4 取 0.5 则是“每元素 4 bit”的理想值，实际存储还要加缩放因子（每 16 或 32 个元素一组共享一个 FP8 scale），所以真实占用略高于 0.5 字节/token/头。这个偏差在小模型上可忽略，在 <code>L·H_kv·d_h</code> 很大时会累积成可观测的显存差，容量规划时应按“0.5 加上 scale 开销”而不是纯 0.5 来算。</p>\n<p>代价视角：<code>c_tok</code> 同时决定了三件事——单卡可容纳的总 token 数（显存）、每步解码需要读取的 KV 字节数（带宽）、以及分页块分配的最小粒度（碎片率）。以 <code>L=80</code>、<code>H_kv=8</code>、<code>d_h=128</code>、<code>b_kv=1</code> 为例，<code>c_tok = 2×80×8×128×1 = 163840</code> 字节，即单 token 约 160 KB；一条 8K 上下文序列就占约 1.25 GB，这个数字直接解释了为什么长上下文下并发数被压到个位数。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-9\">九 · 推导关键步：从单序列单层到批总和</h3>\n<p>推导只有三步，但每一步都埋着易错点。第一步，单序列单层：一个 token 在该层产生一个 key 向量和一个 value 向量，各自形状为 <code>H_kv × d_h</code>，所以字节数为 <code>2·H_kv·d_h·b_kv</code>；这里 <code>H_kv</code> 必须是 KV 头数，GQA 下它等于查询头数除以分组数，误用查询头数 <code>H</code> 会把结果放大数倍。第二步，对层求和：<code>L</code> 层结构相同（忽略少数异构层），乘以 <code>L</code> 即得单 token 全层占用。第三步，对序列与 token 求和：批内第 <code>i</code> 条序列有 <code>B_i</code> 个已缓存 token，求和得 <code>∑B_i</code>，再乘以前两步的常量。</p>\n<p>伪代码层面，容量检查应写成增量式而非一次性：</p>\n<div class=\"formula\">$$\\text{need} = c_{tok}\\cdot (B_{new} + \\text{prefix\\_shared\\_tokens}) \\quad\\text{与}\\quad \\text{free\\_blocks}\\times\\text{block\\_bytes}\\ \\text{比较}$$</div>\n<p>关键在于 <code>prefix_shared_tokens</code> 只计新增的、未被其他序列引用的部分，而不是整段前缀。这正是第三步求和的离散化偏差来源：公式假设每条序列的 token 互不共享，而 PagedAttention 的块表允许多条序列指向同一物理块，Mooncake 之类的前缀缓存进一步把共享前缀提到跨请求级别。此时 <code>∑B_i</code> 是“逻辑 token 数”，真实占用是“去重后的物理 token 数”，两者之差就是前缀共享带来的节省，长系统提示场景下这个差值可以占到大头。</p>\n<p>代价视角：推导的每一步都对应一次显存分配决策。若按逻辑 token 数预分配，调度器会过早拒绝新请求，吞吐被压低；若按物理块惰性分配，则需要在接纳请求时做块表引用计数，增加调度路径的 CPU 开销。工程判断是：短上下文、低共享场景用逻辑计数足够；长系统提示、多轮对话场景必须走物理块计数，否则预算虚高。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-10\">十 · 离散化与近似：三个偏差源</h3>\n<p>公式是连续的理想化模型，落到硬件上有三处离散化。第一处是分页块粒度：显存按固定大小的块分配（如每块容纳若干 token），序列末尾的未满块仍占整块空间，实际占用是 <code>ceil(B_i / block_tokens) × block_bytes</code> 之和，比 <code>c_tok·∑B_i</code> 多出至多 <code>N × (block_tokens-1) × c_tok</code> 的碎片。高并发短序列场景下，碎片率随 <code>N</code> 线性上升，是容量规划必须留的余量。</p>\n<p>第二处是数值精度的分组缩放：NVFP4 的 0.5 字节/token/头是理想值，实际每若干元素附带一个 scale，等效字节数略高；FP8 虽为 1 字节精确，但某些实现会把 scale 单独存放。第三处是层间异构与对齐：部分模型存在不同 <code>d_h</code> 或 <code>H_kv</code> 的层，统一按最大值估算会高估；张量按 128 字节对齐分配时，小 <code>d_h</code> 的头会产生填充浪费。</p>\n<p>代价视角：离散化直接体现为“预算 vs 实际”的差额。以块粒度 16 token 为例，100 条平均长度 100 token 的序列，逻辑占用 10000 token，物理占用约 <code>100×ceil(100/16)×16 = 11200</code> token，碎片率约 12%；若块粒度放大到 64，碎片率升到约 30%，但块表更短、调度开销更低。这是一个明确的吞吐-显存权衡点，而不是可以忽略的舍入误差。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-11\">十一 · 反解与敏感度：哪个因子真正决定容量</h3>\n<p>把公式反解，得到单卡可并发序列数上限的表达式：</p>\n<div class=\"formula\">$$N_{\\max} \\approx \\frac{M_{\\text{avail}}}{c_{tok}\\cdot \\bar{B}}$$</div>\n<p>其中 <code>M_avail</code> 是扣除权重、激活与临时缓冲后的可用显存，<code>\\bar{B}</code> 是平均序列长度。敏感度分析显示：<code>N_max</code> 对 <code>\\bar{B}</code> 是反比，对 <code>H_kv</code> 与 <code>b_kv</code> 也是反比，但 <code>b_kv</code> 从 1 降到 0.5 只带来约两倍增益，而 GQA 把 <code>H_kv</code> 从 <code>H</code> 降到 <code>H/8</code> 带来的是八倍量级的变化——这解释了为什么结构选择比精度选择对容量影响更大，也解释了为什么误用 <code>H</code> 代入会造成数倍高估。</p>\n<p>具体例子：某 GQA 模型 <code>H=64</code>、<code>H_kv=8</code>、<code>L=80</code>、<code>d_h=128</code>，若误用 <code>H=64</code> 估算，<code>c_tok</code> 被放大 8 倍，容量规划得出的并发数只有真实值的八分之一，批大小被压得过低，GPU 利用率与吞吐同步浪费。反过来，若忽略长尾请求的 <code>B_i</code> 峰值，按平均值反解出的 <code>N_max</code> 在遇到单条超长序列时会瞬间挤占整卡 KV 空间，触发抢占或 OOM。</p>\n<p>代价视角：敏感度分析的工程价值在于排序优化动作。先改结构（GQA/MQA）、再改精度（FP8→NVFP4）、最后才调块粒度与调度策略，这个顺序与各因子对 <code>c_tok</code> 的杠杆倍数一致；反过来先做精度量化，收益会被结构项掩盖。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-12\">十二 · 与调度和 SLO 的耦合：公式作为硬约束输入</h3>\n<p>容量式不是静态报表，而是批调度器的准入判据。连续批处理在每一步解码前要决定接纳哪些新请求，判据就是“新请求的 <code>B_new</code> 加上已有序列的增长量，是否仍落在 <code>M_avail</code> 之内”。由于解码每步每个序列只增 1 个 token，增长量是 <code>N·c_tok</code>，可预测；但预填请求一次带入 <code>B_new</code> 个 token，是容量曲线的阶跃点，也是 SLO 违约的高发处。</p>\n<p>把公式代入时延-吞吐约束，可以得到一个可操作的准入规则：当 <code>c_tok·(∑B_i + B_new) &gt; M_avail·(1-安全余量)</code> 时，要么拒绝、要么抢占低优先级序列、要么把长请求切块预填以摊平阶跃。安全余量必须覆盖第三节的碎片与缩放开销，否则规则在高压下失效。分离式部署中，这个判据还要跨节点传递——预填节点算出 KV 字节数，经 NIXL 传输到解码节点前需确认对端块表有空位，否则传输即浪费带宽。</p>\n<p>代价视角：准入判据的精度直接换算成 goodput。判据偏保守（按逻辑 token 计、余量过大），则并发上不去、TTFT 拉长；判据偏激进（忽略碎片与长尾），则触发抢占重算，已算好的 KV 被丢弃，等于白烧算力。工程判断是：把 <code>c_tok</code> 作为编译期常量固化进调度器，把碎片率作为运行期滑动统计量动态修正余量，二者分离，避免每次准入都做完整公式计算。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-13\">十三 · 精度切换时的重算边界</h3>\n<p>当 <code>b_kv</code> 从 FP8 切到 NVFP4，公式给出的容量增益是近似两倍，但工程上不能直接按两倍放大批大小。原因在于：已缓存的 FP8 KV 不能原地“压缩”成 NVFP4，切换精度意味着旧序列的 KV 需要重算或丢弃；而 NVFP4 的量化误差会改变注意力输出的数值分布，长上下文下误差累积对生成质量的影响需要单独评估（该误差界属另一条目主题，此处只指出它是切换的前置条件）。</p>\n<p>因此精度切换的正确做法是：新请求按新精度分配块，旧序列按原精度保留至自然结束，块表按精度分区管理，容量式对两个分区分别计算再相加。这样 <code>M_KV</code> 变成分段函数而非单一乘积，调度器需要维护两套 <code>c_tok</code>。代价是块管理的复杂度上升与短期内的显存双份占用，收益是切换过程不中断服务、不触发全量重算。</p>\n<p>工程判断落在具体机制上：把 <code>c_tok</code> 与块粒度、精度分区一起做成调度器的配置项，在容量式反解 <code>N_max</code> 时按分区加权求和，而不是用一个全局平均 <code>b_kv</code> 糊过去——后者在混合精度过渡期会系统性高估可用并发数，是上线后 OOM 的典型来源。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-14\">十四 · 把公式放到边界上：什么时候它开始骗人</h3>\n<p>公式本身只是一次乘法链，真正的工程价值在于知道它在哪一步失真。推导的关键动作是把“单序列、单层、单 KV 头”的占用写成 <span class=\"inline-math\">2·H_kv·d_h·b_kv·B_i</span>，再对 L 层求和、对 N 条序列求和，得到 <span class=\"inline-math\">M_KV = 2·L·H_kv·d_h·b_kv·ΣB_i</span>。这里没有任何近似——它精确描述“每条序列各自持有一份完整历史”的解码缓存。所有失效都发生在把它套到真实系统上时：真实系统里 KV 头数不等于注意力头数，真实系统里前缀被多请求共享，真实系统里 B_i 的分布有长尾。离散化不在公式内部，而在“把连续增长的 token 流切成按页分配的块”这一步，块粒度决定了 ΣB_i 与实际占用之间的向上取整误差。</p>\n<p>第一个失真点是 H_kv。GQA/MQA 下 KV 头数远小于注意力头数，若沿用 H 代入，结果按 H/H_kv 倍高估。以典型 GQA 配置为例，注意力头数取 16 量级而 KV 头数常为其四分之一到八分之一，误用 H 会让容量规划直接偏保守数倍，批大小被压到远低于硬件实际能容纳的水平，吞吐白白浪费。这不是精度问题，是量级问题：算出来的单卡并发上限比真实值低一个档位，调度器据此拒绝请求，SLO 达标率反而因为“太保守”而下降。判断方法很直接——查模型 config 里的 num_key_value_heads，而不是 num_attention_heads。</p>\n<p>第二个失真点是 ΣB_i 的语义。分页与前缀共享（PagedAttention、Mooncake 一类）把同一前缀的物理块在多个请求间复用，此时按每条序列的完整 token 数累加会重复计入共享段。共享前缀越长、并发越高，虚高越严重：一个被 N 条请求共享的长系统提示，在公式里被算了 N 次，在显存里只存一份。后果是预算虚高、上线后反而 OOM——因为规划时以为占用很大而压缩了并发，真实占用却因共享而变小，运维侧对余量的判断完全失准。正确做法是把 ΣB_i 拆成“独占段之和 + 共享段按引用计数折算”，共享段只在首次分配时计入。</p>\n<p>第三个失真点是长尾。公式对 B_i 是线性的，但请求的 B_i 分布重尾：平均上下文长度算出的占用是平滑的，单条超长序列的峰值却能在瞬间挤占整卡 KV 空间，把同批其他请求挤出可调度集合。离散化在这里放大问题——按页分配意味着一条超长序列占用的块数是阶梯式跳变的，块粒度越粗，峰值时的碎片浪费越大。系统代价体现在三处：显存上，峰值 B_i 决定的是最坏情况容量而非平均容量；延迟上，KV 逼近上限时调度器被迫抢占/重算，prefill 被反复触发；带宽上，块分配与回收的元数据操作随并发线性上升。工程判断是：容量规划用峰值 B_i 加共享折算，而不是平均值；b_kv 从 FP8 降到 NVFP4（≈0.5 字节/元素）带来的容量增益，只有在 H_kv 与共享语义都代对之后才可信。</p>\n<table class=\"mini\"><thead><tr><th>失真源</th><th>公式中的位置</th><th>系统代价</th></tr></thead><tbody><tr><td>误用注意力头数</td><td>H_kv 被 H 替代</td><td>并发上限低估数倍，吞吐浪费</td></tr><tr><td>前缀共享未折算</td><td>ΣB_i 重复计入共享段</td><td>预算虚高，上线 OOM</td></tr><tr><td>长尾 B_i 峰值</td><td>ΣB_i 取平均而非峰值</td><td>抢占重算，prefill 抖动</td></tr></tbody></table>\n<h3 id=\"th-kv-cache-mem-sec-15\">十五 · 公式成立的前提：静态、独占、无共享</h3>\n<p>$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$ 这条式子看起来是纯乘法，但它隐含了三个未被写出的假设，任何一条被打破，结果就不再是容量上界而只是一个偏高的估计值。第一个假设是<strong>静态性</strong>：$\\sum B_i$ 被视为一个在批生命周期内不变的量，即所有序列的 token 数在分配那一刻就确定且不再增长。第二个假设是<strong>独占性</strong>：第 $i$ 条序列占用的字节完全归它自己，不与任何其他序列重叠。第三个假设是<strong>无共享</strong>：不同序列即使内容相同，也各存一份。真实推理系统里这三条几乎同时被打破——解码是逐 token 追加的，分页分配器按块粒度而非按序列粒度管理，前缀共享让相同 prompt 的 KV 只存一次。</p>\n<p>从工程角度看，这条公式的正确定位是<strong>容量上界估计器</strong>，而不是运行时占用测量器。它的价值在于反解并发上限：给定单卡可用于 KV 的显存 $M_{\\text{avail}}$，可得 $N_{\\max} = M_{\\text{avail}} / (2 L H_{kv} d_h b_{kv} \\bar{B})$，其中 $\\bar{B}$ 是平均序列长度。这个反解在容量规划阶段是硬输入，但一旦进入调度器内部，就必须换成按块计数的动态模型。代价体现在两个方向：把公式当运行时真值用，会在长尾请求到来时低估峰值而 OOM；把公式当唯一规划依据用，会因忽略共享而高估预算、把批大小压得过低，浪费吞吐。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-16\">十六 · 失效条件一：GQA/MQA 下头数代入错误</h3>\n<p>公式中 $H_{kv}$ 是 KV 头数，不是注意力头数 $H$。在标准多头注意力下二者相等，公式无须区分；但在 GQA 下 $H_{kv}$ 可以是 $H$ 的几分之一，MQA 下甚至退化为 1。若误用 $H$ 代入，误差倍数为 $H/H_{kv}$，这是数倍量级的高估。举例：一个 $H=64$、$H_{kv}=8$ 的 GQA 模型，误用 64 代入会使估算的 KV 占用放大 8 倍，规划出的并发序列数被压到真实值的八分之一，解码吞吐随之塌陷——GPU 的 SM 大部分时间在等调度而不是在算。</p>\n<p>更隐蔽的错误发生在跨模型迁移场景：工程师把上一个 MHA 模型的容量脚本直接套到新 GQA 模型上，脚本里 $H_{kv}$ 一栏填的还是 $H$，结果新卡上线的第一批请求就出现显存预算虚高、批大小设得过小、GPU 利用率长期低位。这类错误的诊断特征是：显存实际占用远低于预算，但吞吐上不去。反过来，若把 MQA 的 $H_{kv}=1$ 误当成某个中间值，则会低估占用，直接触发 OOM。判断准则很简单——打开模型 config，读 `num_key_value_heads` 字段，而不是 `num_attention_heads`。</p>\n<p>这里还有一个与量化耦合的细节：$b_{kv}$ 从 FP8 的 1 降到 NVFP4 的约 0.5 时，容量增益是线性的，但前提是 $H_{kv}$ 已经取对。若 $H_{kv}$ 错了 8 倍，量化带来的 2 倍增益会被完全淹没在错误的基数里，工程师会误以为量化没起作用。所以量化收益评估必须在正确的 $H_{kv}$ 基线上做，否则结论不可信。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-17\">十七 · 失效条件二：前缀共享打破 sum B_i 的可加性</h3>\n<p>PagedAttention 与 Mooncake 这类系统把 KV 切成固定大小的块，按块分配、按块引用计数。当多条请求共享同一段 prompt 前缀时，这段前缀的 KV 块只存一份，被多个请求的块表指向。此时真实占用是<strong>去重后的块集合大小</strong>，而不是 $\\sum B_i$ 对应的字节数。按 $\\sum B_i$ 计会把共享前缀重复计入每条序列，显存预算虚高，上线后实际占用远低于预期——这本身不致命，但会误导容量决策，让运维误判还有多少余量可放新请求，一旦共享比例下降（比如用户开始发各不相同的长 prompt），真实占用会突然逼近预算上限。</p>\n<p>形式化地，设请求集合的前缀树共有 $U$ 个唯一 token 位置，则真实 KV 占用约为 $2 L H_{kv} d_h b_{kv} \\cdot U$，而公式给出的是 $2 L H_{kv} d_h b_{kv} \\cdot \\sum B_i$，二者之比等于平均共享度。系统前缀（system prompt）越长、越统一，这个比值越大，公式的保守程度越高。工程上的正确做法是：规划阶段用公式给出上界，运行阶段用块分配器的实际引用计数作为真值，并在调度器里维护“当前唯一块数 / 总块数”这一比值作为健康指标。当该比值从高位快速下滑，说明共享红利在消失，需要提前触发驱逐或拒绝策略，而不是等到 OOM。</p>\n<p>代价层面，前缀共享的收益直接体现在显存上，但它把容量模型从“按序列线性”变成了“按唯一内容计数”，这使得 SLO 容量规划不能再简单用 $\\bar{B}$ 乘以并发数。对长 system prompt 的对话类负载，共享度高，公式高估严重；对每个请求 prompt 都不同的批处理负载，共享度接近 1，公式反而准确。判断负载属于哪一类，是决定是否信任公式的第一步。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-18\">十八 · 失效条件三：长尾 B_i 峰值与动态增长</h3>\n<p>公式里的 $\\sum B_i$ 是一个求和，它对分布不敏感——只关心总量，不关心单条序列的极值。但显存分配是按块进行的，一条超长序列可能在某一时刻独占大量连续块，把其他请求挤出。只按平均上下文长度估算，会系统性低估峰值占用：即使总 token 数不变，只要有一条 $B_i$ 远超均值，分页分配器就可能因为找不到足够多的空闲块而触发抢占或重计算。这就是长尾请求的破坏性——它不需要改变总量，只需要改变分布。</p>\n<p>解码阶段的动态增长进一步加剧这一点。公式假设 $B_i$ 在分配时确定，但实际解码每步追加一个 token，序列长度单调增长直到达到 max_new_tokens 或 EOS。若调度器按初始长度分配并预留增长空间，预留量本身就是一笔隐性开销；若不预留，则增长到一定程度必须重新分配或迁移块。两种策略的代价不同：预留浪费显存、降低并发；不预留则引入迁移延迟和碎片。工程判断是——对输出长度方差大的负载（如开放式生成），按 P99 输出长度预留；对输出长度可控的负载（如结构化抽取），按 max_new_tokens 精确预留。</p>\n<p>规模上限由此显现：单卡可并发序列数不是由平均长度决定的，而是由“最长序列 + 其余序列的块需求”共同决定的最坏情况。当并发数上升到数百量级，块碎片和长尾峰值的叠加会让实际可用并发显著低于公式反解值。这也是为什么大规模部署倾向于把 KV 容量问题外推到分离式架构——把预填与解码拆到不同资源池，让解码池的 KV 增长曲线更可预测。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-19\">十九 · 公式何时仍然可信：一个工程判据</h3>\n<p>把三条失效条件合起来看，公式的可信度取决于负载的三个属性：头数配置是否已按 $H_{kv}$ 校正、前缀共享度是否接近 1、序列长度分布是否集中。三者都满足时，公式给出的就是接近真值的容量上界，可以直接用于反解并发上限和 SLO 容量规划。任一不满足时，公式退化为保守上界，只能用于“最坏情况放不放得下”的判断，不能用于“还能放多少”的判断。</p>\n<p>一个可操作的判据是：在调度器里同时维护公式估算值和块分配器实测值，计算二者比值 $r$。当 $r$ 稳定在 1 附近，说明负载无共享、长度集中，公式可信；当 $r$ 显著大于 1，说明共享或长尾在起作用，此时应以实测值为准，公式仅作上界保护。这个比值本身就是一个低成本、高信息量的运行指标，比事后 OOM 告警更早暴露容量模型的失配。最终落在具体机制上：容量决策的正确姿势不是选公式或选实测，而是让公式做上界、让块计数做真值、让比值做失配探测器。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-20\">二十 · 公式成立的前提：从“逐序列独立缓存”到“共享前缀复用”</h3>\n<p>该式的隐含假设是：批内每条序列各自持有一份互不重叠的 KV 张量，且这份张量按 token 数线性增长、按层数线性叠加。只有当解码缓存以“每序列一块连续逻辑区间”的方式分配时，这个假设才成立。一旦运行时把物理块与逻辑序列解耦——PagedAttention 的块表、Mooncake 的全局前缀池——<span class=\"inline-math\">$\\sum_i B_i$</span> 就不再等于真实驻留的 KV 字节数。此时正确口径是“去重后的物理块数 × 每块字节数”，而不是把每条序列的 token 数简单相加。工程上判断是否越界的方法很直接：看分配器统计的是逻辑页还是物理页；若框架报告的是物理页占用，而容量规划仍用 <span class=\"inline-math\">$\\sum_i B_i$</span> 反解并发上限，预算会系统性虚高，上线后在高并发长前缀场景（如共享系统提示、few-shot 模板、多轮对话历史）直接撞上 OOM。</p>\n<p>第二个失效点是头数代入错误。GQA/MQA 下 <span class=\"inline-math\">$H_{kv}$</span> 远小于注意力头数 <span class=\"inline-math\">$H$</span>，若沿用 <span class=\"inline-math\">$H$</span> 估算，结果按 <span class=\"inline-math\">$H/H_{kv}$</span> 倍高估。这个倍数不是小数：在 <span class=\"inline-math\">$H=32$</span>、<span class=\"inline-math\">$H_{kv}=8$</span> 的典型配置下就是 4 倍，容量规划因此把批大小压到真实上限的四分之一，SM 占用率与解码吞吐同步塌陷。更隐蔽的是 MLA 一类结构，KV 被压缩成潜向量后既不是“每头一对 K/V”，也不服从系数 2 的语义，公式只能作为量级下界使用，必须换成按潜维度与缓存深度重新推导的表达式。</p>\n<div class=\"formula\">$$N_{\\max}\\approx\\frac{M_{\\text{budget}}-M_{\\text{weights}}-M_{\\text{act}}}{\\left(2 L H_{kv} d_h b_{kv}\\right)\\bar{B}}\\quad\\text{仅当无前缀共享、}\\bar{B}\\text{ 代表真实峰值而非均值时成立}$$</div>\n<p>第三个边界是“平均值陷阱”。用平均上下文长度 <span class=\"inline-math\">$\\bar{B}$</span> 反解 <span class=\"inline-math\">$N_{\\max}$</span> 在数学上没错，在调度上却错：KV 分配是瞬时的、不可抢占的，一条超长请求的 <span class=\"inline-math\">$B_i$</span> 峰值可以在一个调度周期内吃掉整卡 KV 空间，把其余请求挤到等待队列。因此容量决策必须用分位数而非均值，把长尾 <span class=\"inline-math\">$B_i$</span> 的 P99 代入，并配合 chunked prefill 与请求准入控制，否则公式给出的并发上限只是一个在平稳流量下才兑现的乐观值。规模上限还受带宽约束：即便显存放得下，解码每步都要把全部活跃 KV 读一遍，<span class=\"inline-math\">$2 L H_{kv} d_h b_{kv}\\sum_i B_i$</span> 字节的读取量直接决定单步延迟下限，容量与带宽在这里是一枚硬币的两面。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>公式是否成立</th><th>应替换的口径</th></tr></thead><tbody><tr><td>标准 MHA/GQA 解码，无共享</td><td>成立</td><td>直接用 <span class=\"inline-math\">$H_{kv}$</span> 与 <span class=\"inline-math\">$\\sum_i B_i$</span></td></tr><tr><td>PagedAttention / Mooncake 前缀复用</td><td>高估</td><td>去重物理块数 × 每块字节数</td></tr><tr><td>误用 <span class=\"inline-math\">$H$</span> 代替 <span class=\"inline-math\">$H_{kv}$</span></td><td>高估 <span class=\"inline-math\">$H/H_{kv}$</span> 倍</td><td>按实际 KV 头数重算</td></tr><tr><td>长尾超长请求</td><td>均值口径失效</td><td>用 <span class=\"inline-math\">$B_i$</span> 的 P99 峰值反解</td></tr></tbody></table>\n\n<h3 id=\"th-kv-cache-mem-sec-21\">二十一 · 公式在什么条件下不再成立：头数口径、前缀复用与长尾峰值</h3>\n<p>该式的成立前提是“每条序列独占一份连续 KV 张量”。一旦这个前提被打破，公式就从容量估算退化为量级参考。第一个断点是头数口径：GQA/MQA 下 H_kv 远小于注意力头数 H，若误用 H 代入，结果会按 H/H_kv 的倍数高估，容量规划因此偏保守、批大小被压得过低，吞吐白白浪费。工程上应把 H_kv 与 b_kv 一起作为模型元数据固化进容量表，而不是在调度器里临时从 config 里猜。</p>\n<p>第二个断点是前缀共享。PagedAttention 的块表与 Mooncake 的跨请求前缀复用，使同一前缀的 KV 只存一份、被 N 条序列共同引用，此时按 ∑B_i 求和会把共享段重复计入，显存预算虚高，上线后反而因真实占用低于预期而放松了水位线，掩盖了长尾风险。更准确的写法是引入去重后的有效 token 总量：</p>\n<div class=\"formula\">$$M_{\\text{KV}} \\approx 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot\\left(\\sum_{i=1}^{N}B_i - \\sum_{p\\in\\text{shared}} (c_p-1)\\,|p|\\right)$$</div>\n<p>其中 c_p 为前缀 p 的引用计数，|p| 为其 token 数。该修正只对可精确识别的前缀成立；带随机前缀、动态系统提示或跨租户隔离策略时，共享率不可预测，公式只能给出上界。</p>\n<p>第三个断点是长尾。按平均上下文长度估算会系统性低估峰值：单条超长序列的 B_i 即可挤占整卡 KV 空间，使并发上限从数十骤降。容量决策应以 B_i 的 P99 而非均值代入反解，并配合抢占/换出策略兜底。此外 b_kv 从 FP8=1 降到 NVFP4≈0.5 虽带来约两倍容量增益，但需确认内核与量化校准支持，否则收益只停留在纸面。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>偏差方向</th><th>系统代价</th></tr></thead><tbody><tr><td>用 H 代替 H_kv</td><td>高估数倍</td><td>批过小、吞吐损失</td></tr><tr><td>忽略前缀共享</td><td>预算虚高</td><td>水位误判、长尾 OOM</td></tr><tr><td>按均值估 B_i</td><td>低估峰值</td><td>单请求挤占整卡</td></tr></tbody></table>\n<h3 id=\"th-kv-cache-mem-sec-22\">二十二 · 从字节数到并发上限：反解 N</h3>\n<p>容量决策的第一步不是问“这张卡能放多少 KV”，而是问“给定显存预算，我能同时容纳几条序列”。把公式中求和项拆开，设批内平均序列长度为 <span class=\"inline-math\">B̄</span>，则 <span class=\"inline-math\">ΣB_i ≈ N·B̄</span>，反解得到单卡并发上限：</p>\n<div class=\"formula\">$$N_{\\max} = \\left\\lfloor \\frac{M_{\\text{budget}}}{2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\bar B} \\right\\rfloor$$</div>\n<p>这里 <span class=\"inline-math\">M_budget</span> 不是整卡 HBM 容量，而是权重、激活峰值、通信缓冲、框架运行时开销扣完后的余量。工程上必须先把权重按 <span class=\"inline-math\">\\(P\\cdot b_w\\)</span>（参数量乘权重位宽字节）从总容量里减掉，再留出激活与 workspace 的固定份额，剩下的才是 KV 池。这一步做错，后面所有批大小都是空中楼阁。注意 <span class=\"inline-math\">N_max</span> 对 <span class=\"inline-math\">B̄</span> 是反比关系：平均上下文翻倍，并发上限直接腰斩，这就是长上下文服务容量曲线陡峭的根源。</p>\n<p>具体机制上，反解出的 <span class=\"inline-math\">N_max</span> 要作为连续批处理调度器的硬上限输入，而不是软提示。调度器每个 decode step 从等待队列取新请求时，必须先按该请求的 <span class=\"inline-math\">B_i</span> 试算增量占用，放得下才准入，放不下就阻塞——这把 KV 公式从“规划期估算”变成了“运行期准入判据”。代价体现在延迟侧：准入阻塞会让短请求排在长请求后面，尾延迟被拉长；因此高 SLO 场景通常配一个按 <span class=\"inline-math\">B_i</span> 分桶的准入策略，把超长请求隔离到独立副本。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-23\">二十三 · 定并行度：TP 与 KV 池的除法关系</h3>\n<p>张量并行（TP）对 KV 的影响是直接的除法：每层 KV 头按 TP 度切分到各卡，单卡承担的 KV 头数为 <span class=\"inline-math\">H_{kv}/t</span>（<span class=\"inline-math\">t</span> 为 TP 度），于是单卡 KV 占用变为</p>\n<div class=\"formula\">$$M_{\\text{KV, per-card}} = \\frac{2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_i B_i}{t}$$</div>\n<p>这给出一个明确的工程判断：当 <span class=\"inline-math\">N_max</span> 被 KV 卡住而非被算力卡住时，加 TP 度是提升并发的有效手段，因为它同时分摊了权重和 KV；但当 <span class=\"inline-math\">H_{kv}</span> 本身很小（MQA 或极端 GQA），<span class=\"inline-math\">H_{kv}/t</span> 可能除不尽甚至小于 1，此时 TP 对 KV 的收益饱和，继续加卡只增加通信开销而不增加容量。这就是为什么 MQA 模型在大 TP 下 KV 容量几乎不随卡数线性增长。</p>\n<p>并行度决策还要和序列并行/上下文并行区分：后者切的是 <span class=\"inline-math\">B_i</span> 维度而非头维度，单卡 KV 变为 <span class=\"inline-math\">ΣB_i/c</span>（<span class=\"inline-math\">c</span> 为切分度），适合单条超长序列放不下的场景。两者代价不同：TP 每层都要 All-Reduce，通信量与 <span class=\"inline-math\">t</span> 成正比且落在关键路径上；上下文并行只在注意力边界做点对点交换，但对短序列不划算。容量规划时应先算 <span class=\"inline-math\">N_max</span> 判断瓶颈在并发还是在单序列长度，再选切分维度。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-24\">二十四 · 定 KV 预算：b_kv 与量化增益的定量换算</h3>\n<p><span class=\"inline-math\">b_kv</span> 是公式里唯一可以“免费”改写的乘数。FP8 时 <span class=\"inline-math\">b_kv=1</span>，NVFP4 时约 <span class=\"inline-math\">0.5</span>，代入公式即得容量翻倍——这是纯算术结论，不依赖任何实测。但工程上必须把这条增益与精度代价一起放进预算表：KV 量化到 NVFP4 会引入 key/value 的表示误差，长上下文下误差随注意力分数累积，通常需要配合 per-channel 或 per-token 缩放，以及关键层保留 FP8 的混合策略。因此“容量翻倍”应写成“容量上限翻倍、有效容量按精度验收打折”。</p>\n<p>定 KV 预算的正确姿势是双向约束：一方面按目标并发 <span class=\"inline-math\">N_target</span> 和目标上下文 <span class=\"inline-math\">B_target</span> 正算所需字节，与可用余量比对；另一方面按可用余量反算 <span class=\"inline-math\">N_max</span>，看是否满足 SLO 要求的并发。两者不闭合时，调节杠杆按代价排序为：先降 <span class=\"inline-math\">b_kv</span>（量化，代价是精度验收），再提 <span class=\"inline-math\">t</span>（并行，代价是通信与卡数），最后才是砍 <span class=\"inline-math\">B_target</span>（拒绝长请求，代价是产品能力）。这个排序的理由是前两者不改变服务语义，后者改变。</p>\n<p>显存侧的具体代价：KV 池一旦按峰值 <span class=\"inline-math\">N_max·B̄</span> 预留，空闲时也占着 HBM，挤占权重加载和激活空间；反之按均值预留则会在长尾请求到来时触发抢占或 OOM。生产系统通常预留一个可增长的 KV 池并设高水位告警，把公式算出的 <span class=\"inline-math\">N_max</span> 作为高水位阈值，而不是一次性静态分配。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-25\">二十五 · 定 SLO：把 TTFT 与 TPOT 翻译成 KV 约束</h3>\n<p>SLO 对 KV 的约束是间接的，但可以写成显式不等式。解码阶段的每 token 时间（TPOT）在批大小 <span class=\"inline-math\">N</span> 下近似随批线性增长（受带宽与算力共同支配），而 <span class=\"inline-math\">N</span> 又受 <span class=\"inline-math\">N_max</span> 约束，于是：</p>\n<div class=\"formula\">$$\\text{TPOT}(N) \\le \\text{TPOT}_{\\text{SLO}} \\quad\\Rightarrow\\quad N \\le N_{\\text{slo}}, \\qquad N_{\\text{eff}} = \\min(N_{\\max}, N_{\\text{slo}})$$</div>\n<p>这个 <span class=\"inline-math\">min</span> 就是容量规划的核心结论：KV 公式给出显存上限 <span class=\"inline-math\">N_max</span>，时延模型给出 SLO 上限 <span class=\"inline-math\">N_slo</span>，实际可用并发取两者较小值。很多团队只算前者，结果批开得很大但 TPOT 超标，SLO 违约；也有团队只盯时延把批压得很小，KV 池大量闲置、吞吐浪费。把两个上限并列写进容量表，才能判断该扩容还是该量化。</p>\n<p>预填阶段则受 TTFT 约束：长 <span class=\"inline-math\">B_i</span> 的请求预填耗时长，若与解码请求混批会拖慢后者。分离式预填/解码部署的本质就是把 <span class=\"inline-math\">ΣB_i</span> 的预填压力从解码副本的 KV 池里剥离出去，让解码侧只承担稳定增长的 KV 占用。代价是 KV 需要在预填与解码节点间传输，带宽开销与 <span class=\"inline-math\">ΣB_i·b_kv</span> 成正比，NVLink 5 与 NIXL 的价值正在于此。容量规划时要把这部分传输时间计入 TTFT 预算。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-26\">二十六 · 算例：一个 GQA 模型的容量决策链</h3>\n<p>设某 GQA 解码模型 <span class=\"inline-math\">L=16</span> 层（数字锚点），<span class=\"inline-math\">H_{kv}</span> 取注意力头数的四分之一，<span class=\"inline-math\">d_h</span> 为常规头维，KV 以 FP8 存储（<span class=\"inline-math\">b_kv=1</span>）。单卡扣除权重与激活后 KV 余量记为 <span class=\"inline-math\">M_budget</span>。按公式，单序列每 token 的 KV 字节为 <span class=\"inline-math\">2·L·H_{kv}·d_h·1</span>，这是一个与 <span class=\"inline-math\">B_i</span> 无关的常数斜率；于是 <span class=\"inline-math\">N_max = M_budget / (斜率 · B̄)</span>。</p>\n<p>决策链按以下顺序走：第一步，用实际 <span class=\"inline-math\">H_{kv}</span> 而非注意力头数 <span class=\"inline-math\">H</span> 算斜率——若误用 <span class=\"inline-math\">H</span>，斜率放大四倍，<span class=\"inline-math\">N_max</span> 被低估四倍，批大小压得过小，吞吐白白浪费，这是最常见的失败模式。第二步，把 <span class=\"inline-math\">b_kv</span> 从 1 换到 <span class=\"inline-math\">0.5</span>（NVFP4），斜率减半，<span class=\"inline-math\">N_max</span> 翻倍，但需过精度验收。第三步，若启用 PagedAttention 前缀共享，共享前缀只计一次，<span class=\"inline-math\">ΣB_i</span> 应改为“唯一 token 数 + 各序列私有后缀之和”，否则预算虚高、上线 OOM。第四步，用 <span class=\"inline-math\">min(N_max, N_slo)</span> 定最终批上限，并把长尾 <span class=\"inline-math\">B_i</span> 峰值作为准入判据而非均值。</p>\n<p>这个算例的工程含义是：容量决策不是一次乘法，而是一条带三个校验点的链——头数校验、共享校验、长尾校验。任一校验点漏掉，公式给出的 <span class=\"inline-math\">N_max</span> 都不可信。真正可落地的做法是把这条链写成容量规划脚本，输入层数、KV 头数、头维、位宽、显存余量、目标上下文与 SLO，输出 <span class=\"inline-math\">N_max</span>、<span class=\"inline-math\">N_slo</span> 与建议的量化/并行杠杆，并随模型版本与硬件配置变更重跑，而不是把某个数字钉死在配置里。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-27\">二十七 · 容量反解：把 KV 字节式变成批大小、并行度与 SLO 的硬约束</h3>\n<p>把 $$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$ 用在容量决策上，正确姿势不是正算“这批请求要多少显存”，而是反解“还剩多少显存能换多少 token”。设单卡 HBM 为 $M_{\\text{gpu}}$，权重与激活、通信缓冲、框架开销合计占 $M_{\\text{fixed}}$，则可用于 KV 的预算为 $M_{\\text{budget}} = M_{\\text{gpu}} - M_{\\text{fixed}}$，于是单卡可容纳的 KV token 总量为 $$T_{\\max} = \\frac{M_{\\text{budget}}}{2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}}$$ 这个 $T_{\\max}$ 才是调度器的第一类硬资源：连续批处理里每接纳一条新序列，就从 $T_{\\max}$ 里扣掉它的 $B_i$；每释放一条，归还其占用。批大小不是拍脑袋定的常数，而是 $\\sum_i B_i \\le T_{\\max}$ 与算力/带宽上限两条约束同时成立时的较小者——长上下文场景下几乎总是 KV 这条先撞墙。并行度决策同理：TP 切分把 $L$、$H_{kv}$ 按头或按层分摊到各卡，每卡 $T_{\\max}$ 随 $H_{kv}$ 或 $L$ 的切分近似线性放大，但 TP 带来的 AllReduce 通信量随 TP 增大而上升，于是“加卡换 KV 容量”存在边际收益递减的拐点，拐点位置由 NVLink 5 域内带宽与单 token 解码的通信占比决定。工程上判断该不该扩 TP，看的是解码步时间里通信占比是否已逼近算力占比，而不是看显存数字本身。</p>\n<p>算例：一个 GQA 解码模型，$L=80$，注意力头数 64 而 KV 头数 $H_{kv}=8$，$d_h=128$，KV 以 FP8 存储即 $b_{kv}=1$。单 token 单卡 KV 字节为 $2\\times80\\times8\\times128\\times1 = 163{,}840$ 字节，约 160 KiB/token。若单卡 HBM 扣除固定开销后剩 60 GiB 可用作 KV，则 $T_{\\max}\\approx 60\\times1024^3/163840$，即约 39 万个 KV token 位。折算成并发：平均上下文 8K token 时可同时驻留约 48 条序列；平均 32K 时只剩约 12 条；若长尾里出现一条 128K 的请求，它单独就吃掉约三分之一张卡的 KV 预算，其余请求的批大小必须立刻收缩。把 $b_{kv}$ 换成 NVFP4 的约 0.5，$T_{\\max}$ 翻倍，同样的卡能把 32K 平均上下文的并发从 12 条抬到 24 条上下——这正是量化在长上下文服务里比在短请求服务里更值钱的原因：它直接乘在容量分母上。反过来，若误用注意力头数 64 代入，单 token 字节变成约 1.25 MiB，$T_{\\max}$ 被低估八倍，批大小会被压到实际能力的零头，吞吐白白浪费，这就是失效条件里“高估数倍”的具体代价形态。</p>\n<p>把 $T_{\\max}$ 接进 SLO 的方式是把它写成准入判据而非事后统计。对每条请求，调度器需要其输入长度与最大输出长度之和 $B_i^{\\max}$，准入条件为 $\\sum_{j\\in\\text{active}} B_j^{\\max} + B_i^{\\max} \\le T_{\\max}\\cdot(1-\\epsilon)$，其中 $\\epsilon$ 是留给前缀共享失效、碎片与临时峰值的余量。TTFT 与 TPOT 的 SLO 由此转成两条可测约束：预填阶段受算力约束，解码阶段受 HBM 带宽约束，而 KV 预算决定的是“同时在跑多少条”这一乘数——并发越高，单卡带宽被更多序列分摊，TPOT 越难守住。因此定 SLO 时应先由 TPOT 目标反推单卡可承载的活跃序列数上限，再与 $T_{\\max}$ 取小，两者中更紧的那个才是真实容量。这里必须警惕前缀共享带来的高估：PagedAttention 与 Mooncake 让同一系统提示或共享文档的 KV 块被多请求引用，物理占用远小于 $\\sum_i B_i$，若仍按每序列全额计入，预算虚高、准入过松，上线后在共享前缀失效（如请求分属不同前缀树分支）时瞬间 OOM。正确做法是按物理块计费、按引用计数回收，把 $\\sum_i B_i$ 换成去重后的物理 token 数再代入反解式。另一类失效是只按平均 $B_i$ 规划：长尾单条超长序列能独占整卡 KV，因此准入必须对 $B_i^{\\max}$ 设单请求上限，超过上限的请求走分离式预填/解码或排队降级，而不是让它挤掉整批。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>由 KV 式导出的量</th><th>失效时的系统代价</th></tr></thead><tbody><tr><td>批大小</td><td>$\\sum_i B_i \\le T_{\\max}$</td><td>误用 $H$ 代入 → 批过小，吞吐塌陷</td></tr><tr><td>并行度</td><td>$T_{\\max}$ 随 $H_{kv}$/L 切分放大</td><td>过度 TP → 解码步通信占比压过算力收益</td></tr><tr><td>KV 预算</td><td>$M_{\\text{budget}}=M_{\\text{gpu}}-M_{\\text{fixed}}$</td><td>忽略前缀共享 → 预算虚高，上线 OOM</td></tr><tr><td>SLO 准入</td><td>TPOT 反推并发上限与 $T_{\\max}$ 取小</td><td>只按均值规划 → 单条长尾挤占整卡</td></tr></tbody></table>\n\n<h3 id=\"th-kv-cache-mem-sec-28\">二十八 · 容量反解：从字节预算倒推批大小、并行度与 SLO 余量</h3>\n<p>把公式当作约束而非描述，用法是反解：给定单卡可用显存 <code>M_budget</code>（总 HBM 减去权重、激活峰值与框架保留），先算出每 token 的 KV 单价 <code>c = 2·L·H_kv·d_h·b_kv</code>，再得到可容纳的总 token 数 <code>T_max = M_budget / c</code>。批大小不是独立变量，而是 <code>N ≤ T_max / B_avg</code>；一旦 <code>B_avg</code> 抬到长上下文区间，N 立刻塌缩。工程上更稳的做法是保留 <code>1 - α</code> 的安全水位（α 取 0.1–0.2 量级，用于吸收碎片、临时前缀与解码期增长），把 <code>T_max</code> 乘上该系数后再反解。并行度同理：TP 把 <code>H_kv</code> 切分到各卡，单卡 KV 单价近似按 TP 缩小，但权重与通信缓冲不缩，故 TP 增大对 KV 容量的边际收益递减，容量规划必须按“每卡剩余显存”而非“总显存除以 TP”来算。</p>\n<p>算例：某 GQA 模型 L 层、KV 头数 <code>H_kv</code> 为注意力头数的几分之一、<code>d_h</code> 固定，FP8 下 <code>b_kv = 1</code>，单卡预算扣除权重后剩 <code>M_budget</code>。先算 <code>c</code>，再除以 <code>M_budget</code> 得 <code>T_max</code>；若 SLO 要求平均上下文 <code>B_avg</code> 与长尾峰值 <code>B_peak</code> 并存，则批大小须满足 <code>N·B_avg + (B_peak - B_avg) ≤ (1-α)·T_max</code>——长尾单条序列额外占用的差值必须显式预留，否则一条超长请求就能把整卡 KV 挤爆。把 <code>b_kv</code> 从 1 换成 NVFP4 的约 0.5，<code>c</code> 减半，<code>T_max</code> 翻倍，这是量化换容量的直接杠杆；但 NVFP4 的 scale 开销与精度损失要单独评估，不能只看字节数。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>反解式</th><th>失效点</th></tr></thead><tbody><tr><td>批大小 N</td><td>N ≤ (1-α)·T_max / B_avg</td><td>用平均 B 忽略长尾峰值</td></tr><tr><td>KV 预算</td><td>M_KV = c·ΣB_i</td><td>误用注意力头数 H 代 H_kv</td></tr><tr><td>前缀共享</td><td>ΣB_i 改为去重后 token 数</td><td>共享前缀被重复计入</td></tr></tbody></table>\n<p>边界与代价：该式只对标准多头或 GQA 解码缓存成立；MQA 下 <code>H_kv = 1</code>，容量极大但表达力受限，不能拿它套 GQA 的结论。分页与前缀共享（PagedAttention、Mooncake）使 <code>ΣB_i</code> 不再等于各序列长度之和，真实占用应按去重后的物理块计，按序列长度累加会系统性高估，导致批大小设得过小、吞吐白扔；反过来，若调度器未真正复用前缀而规划时按复用算，上线即 OOM。系统代价体现在三处：KV 单价 <code>c</code> 决定单请求显存税，直接压制并发；长尾 <code>B_peak</code> 决定必须留出的死区，压缩了有效批；前缀共享的块管理引入查表与引用计数开销，命中率低时反而增加调度延迟。因此容量决策的正确顺序是：先用实际 <code>H_kv</code> 与 <code>b_kv</code> 算准 <code>c</code>，再用去重后的 token 总量校准 <code>T_max</code>，最后按 SLO 的尾延迟而非平均延迟定 <code>α</code> 与 <code>N</code>。</p>\n<h3 id=\"th-kv-cache-mem-sec-29\">二十九 · 误用一：用注意力头数 H 顶替 H_kv</h3>\n<p>这是容量规划里最贵的一次笔误，也是最难自查的一次。公式里 <span class=\"sym\">H_kv</span> 是 KV 头数，GQA 下它严格小于注意力头数 <span class=\"sym\">H</span>；把 <span class=\"sym\">H</span> 代进去，等于把每层 KV 张量的宽度按查询头的规模去算，误差倍数就是分组比 <span class=\"sym\">H/H_kv</span>。这个倍数不是小数：分组比取 4 或 8 时，估算出的 KV 字节数直接放大 4 倍或 8 倍。机制上，GQA 让多组查询头共享同一份 K/V，缓存里只存 <span class=\"sym\">H_kv</span> 份，而不是 <span class=\"sym\">H</span> 份；误用者把共享结构当成独立结构，等于凭空给每条序列多分配了几份根本不存在的张量。</p>\n<div class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{wrong}}}{M_{\\text{KV}}^{\\text{right}}}=\\frac{H}{H_{kv}}$$</div>\n<p>后果是双向的，但工程上通常只暴露一个方向：容量规划偏保守，反解出的单卡并发序列数上限被压到真实值的 1/4 或 1/8，批大小设得过小，解码阶段 GPU 的算力与带宽都吃不满，吞吐白白浪费。更隐蔽的是它不会报错——系统跑得很稳，只是慢，而慢不会被当成 bug 上报，只会被当成“这个模型就这样”。识别方法很直接：拿引擎实际报告的 KV 占用（TensorRT-LLM 的 KV 统计、vLLM 的块表占用）与手算值对一次账，若手算值系统性高出整数倍，先查 <span class=\"sym\">H_kv</span> 的取值来源。具体例子：一个分组比为 8 的 GQA 模型，规划者按查询头数算出单卡只能放很少的并发序列，于是把批大小锁死；实际按 KV 头数重算后，同样的显存能容纳的序列数高出一个量级，之前被浪费的正是这部分吞吐。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-30\">三十 · 误用二：把共享前缀按每条序列重复计入</h3>\n<p>公式里的 <span class=\"sym\">∑B_i</span> 是“批内各序列 token 数之和”，这个求和隐含了每条序列的 token 都独占显存。分页与前缀共享（PagedAttention 的块复用、Mooncake 的跨请求前缀池）恰恰打破这个隐含前提：同一段系统提示、同一份长文档被多个请求共同引用时，物理块只有一份，逻辑上却被每条序列各算一遍。误用者按 <span class=\"sym\">∑B_i</span> 直接乘出总字节，显存预算虚高，规划阶段看着宽裕，上线后却出现 OOM——因为真实占用比预算低，规划者据此把批大小和并发上限调得比安全值更激进，一旦长尾请求涌入，物理块的增长曲线超出预期。</p>\n<p>识别这类误用的抓手是“逻辑 token 数”与“物理块数”的比值。引擎侧若报告的去重后块数显著低于按 <span class=\"sym\">∑B_i</span> 折算的块数，说明共享正在生效，此时任何按求和式做的预算都偏高。修正思路不是改公式，而是在求和之外引入一个共享折扣：把被复用的前缀 token 从 <span class=\"sym\">∑B_i</span> 中扣除，只对独占部分计数。代价体现在调度侧——前缀共享要求块表能跨请求引用同一物理块，引用计数、回收时机、跨请求的块生命周期管理都会增加调度器开销；收益则体现在显存上，共享前缀越长、并发请求越多，省下的物理块越可观。工程判断是：共享前缀占比高的负载（长系统提示、RAG 同一文档多问）必须按去重后的物理占用做容量决策，否则预算与现实的偏差会随并发数放大。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-31\">三十一 · 误用三：只按平均上下文长度估算，无视长尾峰值</h3>\n<p>公式对 <span class=\"sym\">B_i</span> 是求和，求和对分布的形状不敏感，但显存分配对形状极度敏感。按平均上下文长度乘并发数做预算，等于假设所有序列同时处于平均长度；真实负载里 <span class=\"sym\">B_i</span> 是重尾的，一条超长序列的 KV 占用可以顶掉几十条短序列。机制上，解码阶段的 KV 是逐步增长的，长序列在生成过程中持续追加块，而分页分配器在显存碎片化后未必能凑出连续的大块，一条超长序列就可能把整卡 KV 空间挤到无法再接纳新请求。后果不是平均吞吐下降，而是尾延迟骤升与请求被拒——SLO 上表现为长上下文请求的排队时间失控。</p>\n<p>识别方法：把批内 <span class=\"sym\">B_i</span> 的分布画出来，看 P99 与均值的比值；若比值达到数倍，平均值预算就是失效的。容量决策应改用分位数约束而非均值约束，即为长尾预留 headroom，或对超长请求单独设并发上限、走分离式预填路径。代价是短请求的批大小被长尾挤占，吞吐略降；收益是长上下文请求不再触发整卡级 OOM。具体例子：一个以短问答为主、混入少量长文档摘要的负载，均值预算算出的并发数在长文档到达时被单条序列吃掉大半 KV 空间，后续短请求全部排队——这不是公式算错，而是把分布压成了标量。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-32\">三十二 · 反例：一次“算得很准”的上线事故</h3>\n<p>构造一个反例把三类误用叠在一起。某 GQA 模型分组比为 8，服务长系统提示加多轮问答。规划者用查询头数代入 <span class=\"sym\">H_kv</span>，KV 预算被放大 8 倍，于是把单卡并发序列数上限设得极低；同时系统提示被所有请求共享，规划者又按 <span class=\"sym\">∑B_i</span> 把这段前缀在每条序列里重复计入，预算再虚高一层。两个方向的误差没有相互抵消，反而叠加成一个自洽但完全错误的数字：预算看起来“刚好够用”，实际物理占用远低于预算，而规划者据此认为显存是瓶颈、把批大小继续压低。上线后系统稳定但吞吐极差，运维以为是模型慢；直到有人把引擎报告的物理块数与手算值对账，才发现预算与真实占用差了一个量级，被浪费的显存本可以支撑高得多的并发。</p>\n<p>这个反例的教训不在算术，而在校验闭环：公式给出的是量级，不是真相，必须用引擎侧的物理占用做交叉验证。可操作的检查清单是三条——<span class=\"sym\">H_kv</span> 取自模型配置的 KV 头字段而非查询头字段；<span class=\"sym\">∑B_i</span> 在存在前缀共享时按去重后的独占 token 计；预算按 <span class=\"sym\">B_i</span> 的高分位数而非均值留 headroom。三条里任何一条缺失，公式的输出都只能当上界参考，不能当容量承诺。真正决定单卡能放多少请求的，是物理块数乘以块大小这条实测曲线，公式的价值在于给出它的形状与量级，误用的代价则全部落在批大小与 SLO 上。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-33\">三十三 · 精度位宽与误用的耦合</h3>\n<p>把 <span class=\"sym\">b_kv</span> 从 FP8 的 1 降到 NVFP4 的约 0.5，容量增益是线性的，但这条增益会被前述误用吞掉。若 <span class=\"sym\">H_kv</span> 仍按查询头数代入，位宽减半带来的 2 倍容量在 8 倍的头部误用面前毫无意义；若前缀共享仍被重复计入，位宽减半只是让虚高的预算从“离谱”变成“偏大”，规划者依旧看不到真实的容量边界。机制上，量化改变的是每元素字节数这一乘子，它无法修正求和项与头数项的结构性错误。工程判断：先修公式的代入项，再谈位宽收益；顺序颠倒时，量化带来的显存节省会被误用放大成错误的批大小决策，收益在账面上存在、在吞吐上不出现。识别办法仍是同一条对账——量化上线前后各测一次物理块占用，若下降幅度与 <span class=\"sym\">b_kv</span> 的比例不符，说明预算模型里还有未被修正的结构项。</p>\n\n<h3 id=\"th-kv-cache-mem-sec-34\">三十四 · 误用与反例：从\"算多了\"到\"算漏了\"的两头翻车</h3>\n<p>这套式子的危险不在于难，而在于它太容易算出一个\"看起来合理\"的数。最常见的误用是把注意力头数 H 直接塞进 H_kv 的位置。GQA 模型里 KV 头数往往只有注意力头数的几分之一，代入 H 会让 M_KV 成倍放大，容量规划随之偏保守：批大小被压得过低，卡上明明还有空间，调度器却不敢放请求，吞吐白白浪费。识别方法很直接——把模型 config 里的 <code>num_key_value_heads</code> 与 <code>num_attention_heads</code> 并排打出来，若两者不等而你的估算脚本只读了一个字段，这个脚本就是错的。代价是隐性的：它不报错、不 OOM，只表现为 GPU 利用率长期上不去、每卡 QPS 低于同硬件同模型的公开基线，排查时容易误判成调度或通信问题。</p>\n<p>反方向的误用更致命：忽略前缀共享。PagedAttention 与 Mooncake 这类系统让同一前缀（系统提示、few-shot 模板、多轮对话历史）在多个请求间复用同一批物理块，此时按 $\\sum_i B_i$ 逐条累加会把共享部分重复计入。设批内 N 条序列共享长度为 $S$ 的前缀，各自独有 $u_i$ 个 token，真实占用应按 $S+\\sum_i u_i$ 计，而误算按 $\\sum_i (S+u_i)=N\\cdot S+\\sum_i u_i$ 计，虚高部分为 $(N-1)\\cdot S$。系统提示越长、并发越高，这笔虚账越大：预算阶段以为放得下，上线后块池迅速耗尽，表现为 decode 阶段频繁抢占与重算、TTFT 抖动、极端情况下直接 OOM。识别信号是\"预算余量充足但实际块分配率接近 1\"——去比对块池水位与公式预测值，差值随并发线性扩大，就是前缀被重复计入了。</p>\n<p>第三个失效条件藏在长尾里：只按平均上下文长度估算。$\\sum_i B_i$ 是批内实际 token 数之和，而调度器面对的是分布，不是均值。一条远超均值的超长序列单独就能吃掉整卡 KV 空间，把同批其他请求挤出去。工程上应把容量判断改成对 B_i 分布的分位数约束，而非均值约束：</p>\n<div class=\"formula\">$$N_{\\max}=\\left\\lfloor \\frac{M_{\\text{budget}}}{2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\bar{B}_{p}} \\right\\rfloor,\\quad \\bar{B}_{p}=\\text{批内 }B_i\\text{ 的第 }p\\text{ 分位均值}$$</div>\n<p>取 $p$ 高于均值（例如按 P95 附近的批均值代入），得到的是偏保守但不会在长尾请求到来时崩掉的并发上限；再叠加一条硬规则——单条请求的 $B_i$ 超过预算的固定比例时拒绝入批或单独走隔离队列。具体例子：一个 GQA 模型、$L$ 层、$H_{kv}$ 远小于 $H$、KV 以 FP8 存储（$b_{kv}=1$），若把 $b_{kv}$ 换成 NVFP4（$\\approx 0.5$），同一预算下容量约翻倍，但这是在同一 $H_{kv}$、同一前缀共享假设下的增益；若前两项误用未纠正，量化带来的翻倍会被虚高的基数吞掉，容量决策依旧失真。判断顺序应是：先核对 $H_{kv}$ 与共享前缀，再谈精度换容量。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>方向</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>用 H 代 H_kv</td><td>高估</td><td>利用率低、QPS 低于基线</td><td>吞吐浪费、批过小</td></tr><tr><td>忽略前缀共享</td><td>高估</td><td>块池水位逼近 1、抢占频繁</td><td>TTFT 抖动、OOM</td></tr><tr><td>只按均值估 B_i</td><td>低估长尾</td><td>单请求触发整卡挤占</td><td>同批请求被驱逐重算</td></tr></tbody></table>\n\n<h3 id=\"th-kv-cache-mem-sec-35\">三十五 · 误用与反例：容量预算为何在真实流量下失效</h3>\n<p>最常见的误用是把注意力头数 H 直接代入 KV 占用式。以 GQA 模型为例，KV 头数 H_kv 往往远小于 H，若仍用 H 计算，结果会高估数倍——容量规划因此偏保守，批大小被压得过低，GPU 的算力与带宽被白白浪费。识别方法很直接：把模型 config 里的 <code>num_key_value_heads</code> 与 <code>num_attention_heads</code> 对比，若两者不等而预算表里没有区分，几乎可以断定这一项被算错了。修正只需把公式中的 H_kv 换成实际 KV 头数，容量数字立刻回落。</p>\n<p>第二个反例来自前缀共享。PagedAttention 与 Mooncake 让同一系统提示词或共享文档的 KV 块被多请求复用，此时按 <span class=\"formula\">$$M_{\\text{KV}} = 2\\cdot L\\cdot H_{kv}\\cdot d_h\\cdot b_{kv}\\cdot \\sum_{i=1}^{N}B_i$$</span> 里的 sum B_i 逐条累加，会把共享前缀重复计入每条序列，显存预算虚高；上线后真实流量一压，块表碎片与长尾请求叠加，反而触发 OOM。识别信号是预算值与实测 <code>nvidia-smi</code> 占用长期背离，且背离幅度随并发数增大而扩大。</p>\n<p>第三个失效条件是长尾。只按平均上下文长度估算，等于假设所有 B_i 都接近均值；但单条超长序列的 B_i 峰值即可挤占整卡 KV 空间，把同批其他请求挤到换出或抢占。工程上应把预算拆成“均值项 + 峰值项”，对 B_i 取分位数而非均值，并在批调度里为超长请求预留独立配额。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>用 H 代替 H_kv</td><td>高估数倍，批大小过小</td><td>config 中两值不等而预算未区分</td></tr><tr><td>忽略前缀共享</td><td>预算虚高，上线 OOM</td><td>预算与实测占用随并发扩大而背离</td></tr><tr><td>只按均值估 B_i</td><td>长尾请求挤占整卡</td><td>P99 上下文远超均值</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>L</td><td>Transformer 层数</td></tr><tr><td>H_{kv}</td><td>KV 头数（GQA 下小于注意力头数）</td></tr><tr><td>d_h</td><td>每头维度</td></tr><tr><td>b_{kv}</td><td>KV 每元素字节数（FP8=1，NVFP4≈0.5）</td></tr><tr><td>B_i</td><td>第 i 条序列的 token 数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-kv-cache-mem · 共 5 个片段</p>\n"},{"id":"th-batch-latency","title":"连续批处理时延模型","direction":"dir-nvfp4-fp8-quant","prereq":[],"plain":"解码阶段每步时延由固定开销加与批大小近似线性的计算项组成，批越大吞吐越高但单请求 TPOT 变差，SLO 约束下存在最优批上限。","definition":"解码阶段每步时延由固定开销加与批大小近似线性的计算项组成，批越大吞吐越高但单请求 TPOT 变差，SLO 约束下存在最优批上限。","formula":"$$\\text{TPOT}(B) \\approx \\frac{c_0 + c_1 B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta},\\quad B^{*}=\\arg\\max\\{B:\\text{TPOT}(B)\\le \\text{SLO}\\}$$","variables":[{"sym":"B","meaning":"当前批内序列数"},{"sym":"c_0","meaning":"每步固定 kernel 启动与调度开销"},{"sym":"c_1","meaning":"每序列每步计算/访存边际成本"},{"sym":"\\eta","meaning":"带宽利用率"},{"sym":"\\text{SLO}","meaning":"目标每 token 时延上限"}],"derivation":"推导的关键一步是把每步总时间写成 c_0+c_1·B，再除以 B 得到单请求 TPOT，从而显式暴露固定开销随 B 摊薄、边际成本随 B 上升的竞争关系；B* 由 TPOT(B)≤SLO 的边界解出。","example":"在推理性能决策中，该式用于在给定 SLO 下选取最大可行批大小、评估增大批的吞吐收益与 TPOT 代价，并指导连续批处理调度器设置批上限与准入控制。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["MoE 下专家负载不均导致 c_1 随 B 非线性上升，线性模型在专家倾斜时低估时延","chunked prefill 与解码混跑时，prefill 抢占会引入额外排队项，纯解码模型失效"],"system_note":"常见误用是把 c_1 当作常数外推到大批，忽略 MoE 专家倾斜与 prefill 混跑的排队项，导致 SLO 违约；另一误用是只追求吞吐把 B 推到远超 B*，单请求时延超标。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉上，解码每步时延由固定开销摊薄项与随批大小增长的边际项组成，批越大吞吐越高，但单请求 TPOT 变差，SLO 约束下存在最优批上限 B*。","公式中 c_0 为每步固定 kernel 启动与调度开销，c_1 为每序列每步计算/访存边际成本，B 为当前批内序列数；第二项 M_KV(B)/(B_HBM·η) 表示 KV 读取受 HBM 带宽与利用率 η 约束的时延分量。","推导的关键一步是把每步总时间写成 c_0+c_1·B，再除以 B 得到单请求 TPOT，从而显式暴露固定开销随 B 摊薄、边际成本随 B 上升的竞争关系；B* 由 TPOT(B)≤SLO 的边界解出。","适用边界是解码阶段批处理近似线性；失效条件包括：MoE 下专家负载不均使 c_1 随 B 非线性上升，线性模型在专家倾斜时低估时延；chunked prefill 与解码混跑时 prefill 抢占引入额外排队项，纯解码模型失效。","在推理性能决策中，该式用于在给定 SLO 下选取最大可行批大小、评估增大批的吞吐收益与 TPOT 代价，并指导连续批处理调度器设置批上限与准入控制。","常见误用是把 c_1 当作常数外推到大批，忽略 MoE 专家倾斜与 prefill 混跑的排队项，导致 SLO 违约；另一误用是只追求吞吐把 B 推到远超 B*，单请求时延超标。"],"anchors":["未给出"],"pitfalls":["把 c_1 视为常数外推到大批，MoE 专家负载倾斜时实际时延非线性上升，SLO 被击穿。","在 chunked prefill 与解码混跑时仍用纯解码模型估 TPOT，忽略 prefill 抢占的排队项，批上限设得过高。","只按吞吐最大化选 B 而不校验 TPOT(B)≤SLO，单请求时延超标导致线上体验劣化。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-1\">一 · 一句话直觉与严格定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-2\">二 · 为什么需要这个模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-3\">三 · 常见误解之一：把 c_1 当常数外推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-4\">四 · 常见误解之二：混跑场景沿用纯解码模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-5\">五 · 常见误解之三：只最大化吞吐不校验 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-6\">六 · 定义背后的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-7\">七 · 线性模型的适用边界：c₁ 何时不再可信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-8\">八 · 逐项拆解：TPOT 公式里每一项到底在数什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-9\">九 · 推导关键步：从“每步总时间”到“单请求时延”的那一次除法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-10\">十 · 离散化与近似：线性假设在哪一段成立、在哪一段崩掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-11\">十一 · 失效条件的数学形态：MoE 倾斜与 prefill 抢占如何改写公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-12\">十二 · 从公式到调度决策：B* 的求解与准入控制的落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-13\">十三 · 线性模型的边界：c₁ 何时不再是常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-14\">十四 · 线性假设的成立前提：解码稳态与批内同质</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-15\">十五 · MoE 专家倾斜：c_1 随 B 非线性上升的第一个失效源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-16\">十六 · chunked prefill 混跑：排队项缺失导致纯解码模型失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-17\">十七 · 规模上限：固定开销摊薄收益的耗尽点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-18\">十八 · 误用模式与边界校验清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-19\">十九 · 线性假设在何处开始失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-20\">二十 · 从 TPOT 曲线反解批上限：B* 的数值求法与工程取值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-21\">二十一 · 定并行度：把 B* 换算成 TP 与 EP 的切分粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-22\">二十二 · 定 KV 预算：把 M_KV(B) 反解成显存配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-23\">二十三 · 定 SLO 与准入控制：把不等式装进调度器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-24\">二十四 · 算例：一次完整的容量决策链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-25\">二十五 · 把 B* 变成调度器里的四个旋钮：批上限、并行度、KV 预算与准入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-26\">二十六 · 误用的共同结构：把边际项当常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-27\">二十七 · 反例：一次把批上限设高的完整推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-28\">二十八 · 后果的量级判断：为什么尾部先坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-29\">二十九 · 识别手法：三个可落地的检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-30\">三十 · 正确用法：把模型当边界探测器而非外推器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-31\">三十一 · 一个必须写进调度器注释的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-sec-32\">三十二 · 当线性批模型开始说谎：三类误用与一个可复现的反例</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：解码阶段每步时延由固定开销加与批大小近似线性的计算项组成，批越大吞…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\text{TPOT}(B) \\approx \\frac{c_…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：MoE 下专家负载不均导致 c_1 随 B 非线性上升，线性模型在…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-batch-latency-sec-1\">一 · 一句话直觉与严格定义</h3>\n<p>连续批处理时延模型要回答的只有一个问题：<strong>在当前批里塞进第 B 条序列，这一步解码会慢多少，慢到什么时候就踩过 SLO 线</strong>。一句话直觉是——解码每步的墙钟时间由两部分拼成：一部分是与批大小无关的固定开销，另一部分随批内序列数近似线性增长；把总时间除以 B，就得到单请求的每 token 时延（TPOT），于是固定开销被摊薄、边际成本被放大，两者相争处就是最优批上限。严格定义如下：设 B 为当前批内序列数，c_0 为每步固定 kernel 启动与调度开销（与 B 无关），c_1 为每序列每步的计算/访存边际成本，M_KV(B) 为该批需要从 HBM 读出的 KV 字节量，B_HBM 为 HBM 带宽，η 为带宽利用率，则</p>\n<div class=\"formula\">$$\\text{TPOT}(B) \\approx \\frac{c_0 + c_1 B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta},\\quad B^{*}=\\arg\\max\\{B:\\text{TPOT}(B)\\le \\text{SLO}\\}$$</div>\n<p>这里 TPOT 是目标每 token 时延上限 SLO 的被约束量，B* 是满足 SLO 的最大可行批大小。注意第二项写成 M_KV(B) 而非常数，是因为 KV 读取量本身随批内总上下文长度变化；在等长序列的简化情形下它近似与 B 成正比，除以 B 后回落为每序列的 KV 读取成本，这正是“批越大越吃带宽”的来源。定义的关键不在公式形式，而在<strong>把每步总时间写成 c_0 + c_1·B 再除以 B</strong> 这一步：它把“摊薄”与“边际”两种相反的力显式摆在同一根轴上，使 B* 成为一个可解的不等式边界，而不是靠试跑调参猜出来的经验值。</p>\n\n<h3 id=\"th-batch-latency-sec-2\">二 · 为什么需要这个模型</h3>\n<p>没有这个式子，连续批处理调度器只有两种粗糙策略：固定批上限（拍脑袋定一个 32 或 64），或贪心塞满（来一条塞一条直到显存或调度队列撑不住）。前者在低负载时浪费了摊薄固定开销的机会，后者在大批时把单请求 TPOT 推到 SLO 之外。模型的价值在于把“吞吐—时延”这对矛盾转成一个<strong>可计算的准入判据</strong>：给定 SLO，解出 B*，调度器据此设置批上限并对新请求做准入控制；给定硬件与模型，比较不同 B 下 TPOT(B) 的斜率，判断增大批的吞吐收益是否还值得那份 TPOT 代价。</p>\n<p>从系统代价看，这个模型的三个输出分别对应三类工程决策。其一，c_0 项决定<strong>低负载区的时延地板</strong>：B 很小时 TPOT≈c_0/B，固定开销主导，此时增大批几乎免费地提升吞吐，是连续批处理最该利用的区间。其二，c_1·B 项决定<strong>高负载区的时延斜率</strong>：每多一条序列，单步多出的计算/访存时间被摊到所有请求上，TPOT 随 B 上升，越过 SLO 即违约。其三，KV 带宽项决定<strong>长上下文场景的显存带宽压力</strong>：批内总上下文越长，M_KV(B) 越大，η 一旦因带宽争抢下降，该项非线性恶化。举例：一个在线客服推理服务，SLO 设为每 token 数十毫秒量级，低峰期 B 只有个位数，TPOT 被 c_0 抬高；调度器若死守固定批上限，就白白丢掉了摊薄固定开销的吞吐；反之高峰期若贪心塞到显存极限，c_1·B 与 KV 带宽项叠加，TPOT 冲破 SLO，前端表现为流式输出卡顿。</p>\n\n<h3 id=\"th-batch-latency-sec-3\">三 · 常见误解之一：把 c_1 当常数外推</h3>\n<p>最典型的误用是把 c_1 视为与 B 无关的常数，据此把 B* 一路外推到大批区间。这在稠密模型、等长序列、纯解码的干净场景下尚可，但一进入 MoE 就失效：专家负载不均使不同 token 路由到不同专家，批越大，被激活的专家集合越分散，单步内需要等待的最慢专家（或最热专家）决定墙钟时间，于是 c_1 随 B 非线性上升。线性模型在专家倾斜时<strong>系统性低估时延</strong>，解出的 B* 偏大，调度器按此设批上限，实际 TPOT 已越过 SLO。工程上的判别信号是：实测 TPOT 对 B 的曲线在高 B 段上翘，斜率超过线性拟合值，且上翘点与专家激活分布的倾斜程度相关。此时正确做法不是调大 c_1 重拟合了事，而是承认模型在 MoE 下只有局部线性有效，把 B* 的搜索区间限制在专家负载仍均匀的批大小以内，或引入按专家负载修正的惩罚项。</p>\n<p>代价是直接的：一次 SLO 违约在流式接口上表现为 token 间隔抖动，用户侧感知为“卡”；对容量规划而言，按错误 B* 配置的副本数会在高峰被击穿，被迫临时扩容。这类失效的根源不在公式，而在<strong>把适用边界当成了普适定律</strong>。</p>\n\n<h3 id=\"th-batch-latency-sec-4\">四 · 常见误解之二：混跑场景沿用纯解码模型</h3>\n<p>第二个高频误用出现在 chunked prefill 与解码混跑的调度器里：仍用纯解码的 TPOT(B) 估时延，忽略 prefill 抢占引入的额外排队项。机制上，当一个 prefill chunk 被插入解码步之间，它占用 SM 与带宽资源，解码步被推迟；被推迟的时长不只取决于 chunk 大小，还取决于当时批内有多少解码序列在等——这构成一个与 B 相关的排队项，纯解码模型里根本没有这一项。结果是批上限被设得过高：调度器以为 B 还在 SLO 内，实际因 prefill 抢占，解码请求的 TPOT 已经超标。判别方法是分别测量“纯解码步”与“含 prefill chunk 的步”的墙钟时间分布，若后者长尾显著厚于前者，说明排队项不可忽略。工程对策是把批上限的求解拆成两段：解码批上限按纯解码模型解 B*，再对混跑步额外预留一份时延预算给 prefill 抢占，或改用按步类型分别计费的调度策略。</p>\n<p>这里的系统代价是<strong>尾时延</strong>而非均值：排队项主要恶化 P99 而非平均 TPOT，均值监控看不出来，只有分位数监控才能捕获。容量规划若只按均值做，会在混跑高峰低估所需副本数。</p>\n\n<h3 id=\"th-batch-latency-sec-5\">五 · 常见误解之三：只最大化吞吐不校验 SLO</h3>\n<p>第三种误用是把 B* 当成吞吐最大化的批大小来用，而不是 SLO 约束下的边界解。公式里 B* 的定义是“满足 TPOT(B)≤SLO 的最大 B”，它<strong>不是</strong>吞吐曲线的极值点；吞吐随 B 单调上升（在显存与带宽允许范围内），而 TPOT 也随 B 上升，两者在 B* 处分离：B* 左侧是“还能再塞、时延仍合规”的区间，右侧是“吞吐更高、但单请求已违约”的区间。只按吞吐选 B，等于把 B 推到 B* 右侧，线上体验劣化是必然的。正确用法是把 B* 作为<strong>准入控制的上界</strong>：新请求到来时，若当前 B 已达 B*，则排队而非立即合批；同时用 TPOT(B) 的斜率评估“再增大批上限换取多少吞吐、付出多少 TPOT 余量”，把决策显式化。</p>\n<p>表格对比三种用法：</p>\n<table class=\"mini\"><thead><tr><th>用法</th><th>选取的 B</th><th>吞吐</th><th>单请求 TPOT</th><th>后果</th></tr></thead><tbody><tr><td>固定批上限</td><td>拍脑袋常数</td><td>低负载区浪费</td><td>低负载区偏高</td><td>摊薄机会丢失</td></tr><tr><td>吞吐最大化</td><td>显存/带宽极限</td><td>最高</td><td>越过 SLO</td><td>流式卡顿、违约</td></tr><tr><td>SLO 约束解 B*</td><td>TPOT(B)=SLO 边界</td><td>合规区间内最高</td><td>恰在 SLO 线上</td><td>吞吐与时延平衡</td></tr></tbody></table>\n<p>这张表的工程含义是：B* 是一个<strong>约束边界</strong>而非优化目标，调度器的职责是在边界内尽量填满，而不是越过边界去追吞吐。</p>\n\n<h3 id=\"th-batch-latency-sec-6\">六 · 定义背后的工程判断</h3>\n<p>把上述三条误解收拢，可以看出这个模型真正的适用范围是一条窄带：<strong>稠密模型、等长序列、纯解码、专家负载均匀</strong>。离开这条窄带，公式仍可作为一阶近似与决策语言，但 B* 的数值必须带修正项重新校验。工程上更稳妥的做法是把模型当作<strong>分层判据</strong>：先用它解出名义 B*，再用实测的 TPOT-B 曲线校验斜率是否线性、长尾是否被 prefill 抢占拉厚、专家激活是否倾斜；三项校验任一不通过，就把 B* 下调并记录修正因子，而不是修改 c_1 去硬拟合。这样模型保持可解释，调度器保持可审计，SLO 违约的根因也能追溯到具体是哪一项假设被打破——是 c_0 被低估、c_1 非线性、还是排队项缺失。定义的价值不在给出一个精确数字，而在把“批能开多大”这个模糊问题拆成三个可分别验证的物理量。</p>\n\n<h3 id=\"th-batch-latency-sec-7\">七 · 线性模型的适用边界：c₁ 何时不再可信</h3>\n<p>把每步总时间写成 c₀+c₁·B 再除以 B，这个推导之所以有用，是因为它把“固定开销被摊薄”和“边际成本线性累加”这两股相反的力摆在同一根轴上。但它的前提是解码阶段批内序列对计算与访存的占用近似可加：每条序列贡献一份权重读取、一份 KV 读取、一份 attention 计算，互不干扰，于是 c₁ 是一个与 B 无关的常数。一旦这个可加性被打破，公式给出的 B* 就不再是可行批上限，而是一个系统性偏乐观的估计。工程上真正要盯的不是公式本身，而是 c₁ 在目标负载下是否仍然稳定——这决定了这套时延模型能不能用于准入控制。</p>\n<p>最典型的破口是 MoE。稠密模型里每 token 激活的参数固定，c₁ 随 B 增长基本平直；MoE 则不同，路由结果随 batch 内容变化，专家负载倾斜时，被挤到同一专家的 token 会串行排队，等价的边际成本随 B 非线性上升。此时真实 TPOT 曲线在某个批大小之后陡然上翘，而线性模型仍按常数 c₁ 外推，低估时延、把 B* 设在真实拐点右侧。判断信号很直接：观察每步 kernel 时间随 B 的斜率是否单调增大，若斜率本身在涨，说明 c₁ 已不是常数，必须改用分段拟合或按专家负载加惩罚项，而不是继续解那个线性不等式。</p>\n<div class=\"formula\">$$\\text{TPOT}(B) \\approx \\frac{c_0 + c_1 B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta},\\quad B^{*}=\\arg\\max\\{B:\\text{TPOT}(B)\\le \\text{SLO}\\}$$</div>\n<p>第二个破口是 chunked prefill 与解码混跑。纯解码模型假设一个 step 里只有解码 token 在流动，而实际调度器会把 prefill 块塞进同一批次以填满算力。prefill 抢占带来的不是简单的 c₁ 增大，而是一个额外的排队项：解码请求要等 prefill 块的计算让出 SM 与带宽，等待时间取决于块大小与到达节奏，与 B 的关系是非线性的、且带突发性。用纯解码公式估 TPOT，会把批上限设得过高，线上表现为周期性长尾——平均 TPOT 达标，P99 击穿 SLO。正确做法是把 prefill 块视为独立占用项，在时延预算里先扣除其等效排队时延，再对剩余预算解 B*。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>c₁ 行为</th><th>模型结论</th><th>系统代价</th></tr></thead><tbody><tr><td>稠密解码</td><td>近似常数</td><td>B* 可信</td><td>固定开销摊薄，吞吐随 B 上升</td></tr><tr><td>MoE 专家倾斜</td><td>随 B 非线性上升</td><td>低估 TPOT，B* 偏大</td><td>专家串行，SM 空转，TPOT 长尾</td></tr><tr><td>prefill 混跑</td><td>叠加排队项</td><td>纯解码式失效</td><td>解码被抢占，P99 违约</td></tr></tbody></table>\n<p>还有一类误用不在公式内部，而在决策目标上：只按吞吐最大化选 B，不校验 TPOT(B)≤SLO。吞吐随 B 单调上升，若不设时延约束，最优解永远是硬件能塞下的最大批，代价是单请求 TPOT 线性恶化、交互体验崩坏。B* 的意义正在于它是“吞吐收益”与“时延代价”的边界解，而不是性能最优点。工程判断上，B* 应作为调度器的硬上限与准入阈值：新请求进入前先估算加入后的 TPOT 是否越界，越界则排队而非硬塞。同时保留一条降级路径——当检测到 c₁ 斜率上翘或 prefill 排队项增大时，主动下调批上限，用吞吐换 SLO 稳定，这比事后补救便宜得多。</p>\n<h3 id=\"th-batch-latency-sec-8\">八 · 逐项拆解：TPOT 公式里每一项到底在数什么</h3>\n<p>把公式摊开看：$$\\text{TPOT}(B) \\approx \\frac{c_0 + c_1 B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta}$$ 它其实不是一条“拟合曲线”，而是把解码一步的墙钟时间做了两段式记账。分子 <code>c_0 + c_1 B</code> 是“每步总时间”的线性近似，除以 B 才落到单请求头上，所以第一项天然是 <code>c_0/B + c_1</code> 的形状：固定项被批摊薄，边际项不随 B 变化。第二项则是另一条独立的物理通道——KV 读取。注意 <code>M_KV(B)</code> 是批内全部序列在该步需要从 HBM 拉取的 KV 字节总量，<code>B_HBM</code> 是 HBM 峰值带宽，<code>\\eta</code> 是实际可达的带宽利用率。除以 B 之后得到的是“平均每个请求分摊到的 KV 搬运时间”，它和第一项不是同一类开销：第一项是计算与调度的账，第二项是纯带宽的账。工程上必须把两者分开看，因为它们的缩放行为不同——<code>c_1</code> 随 B 恒定，而 <code>M_KV(B)/B</code> 在 KV 长度分布不均时会随 B 漂移（批内混入长上下文请求就抬高均值）。<code>\\eta</code> 是这条式子里最容易被忽略却最致命的参数：它把理论带宽打折成有效带宽，注意力 kernel 的 tile 形状、KV 布局的连续性、是否命中 L2 都体现在这个折扣里。把 <code>\\eta</code> 当成 1 去反推 B*，等于假设 HBM 永远满负荷，实际调度器会因此把批上限设得偏高。</p>\n<p>一个具体例子：某解码步批内 32 条序列，每条已生成 4K token，KV 以 FP8 存储、每 token 每层约若干 KB 量级，则 <code>M_KV(B)</code> 随 B 线性增长，第二项在 B 增大时基本持平；而 <code>c_0/B</code> 从 B=8 到 B=64 会掉到原来的八分之一。这就是为什么小批时 TPOT 被固定开销主导、大批时被边际项与带宽项主导——曲线的“拐点”正是这两股力量交接的位置。</p>\n\n<h3 id=\"th-batch-latency-sec-9\">九 · 推导关键步：从“每步总时间”到“单请求时延”的那一次除法</h3>\n<p>推导的核心只有一步，但这一步决定了整条式子的可用性：先把解码一步的总墙钟时间写成 <code>T_step(B) = c_0 + c_1 B</code>，再除以 B 得到单请求的每 token 时间。为什么可以这样写？因为解码一步里，所有序列共享同一次 kernel launch、同一次调度器决策、同一次采样后的同步，这部分与 B 无关，归入 <code>c_0</code>；而每条序列各自要做一遍 QKV 投影、注意力、MLP，其计算量与访存量随序列数线性叠加，归入 <code>c_1 B</code>。这个线性假设的物理依据是：解码阶段每序列每步只处理 1 个 token，矩阵乘的 M 维极小，GPU 处于“瘦矩阵”状态，SM 的占用由批内序列数拼出来的有效 M 维决定，因此在 SM 未饱和前，时间随 B 近似线性。</p>\n<p>关键推导链可以写成伪代码式的思路：</p>\n<ul>\n<li>设一步内 kernel 启动与调度开销为 <code>c_0</code>，与 B 无关；</li>\n<li>设每序列每步的计算/访存边际成本为 <code>c_1</code>，在 SM 未饱和区间内视为常数；</li>\n<li>则 <code>T_step(B) = c_0 + c_1 B</code>，单请求时延 <code>TPOT(B) = T_step(B)/B = c_0/B + c_1</code>；</li>\n<li>叠加 KV 带宽通道 <code>M_KV(B)/(B_HBM·\\eta)</code>，得到完整式；</li>\n<li>令 <code>TPOT(B) = SLO</code>，解出可行批的上界 <code>B*</code>。</li>\n</ul>\n<p>这次除法的价值在于它把“摊薄”与“上升”两种相反趋势放进同一个表达式：<code>c_0/B</code> 单调下降，<code>c_1</code> 与带宽项不降（带宽项在 KV 均值不变时持平，在长上下文混入时上升）。于是 TPOT 曲线先降后平再升，B* 就是它与 SLO 水平线的交点。代价侧要看清：B 增大提升的是吞吐（每步产出 B 个 token），牺牲的是单请求 TPOT；<code>c_0/B</code> 的下降在 B 超过某个量级后收益急剧衰减——B 从 8 到 16 省下的固定开销占比远大于从 128 到 256。这就是调度器设置批上限时不该盲目追大的数学理由。</p>\n\n<h3 id=\"th-batch-latency-sec-10\">十 · 离散化与近似：线性假设在哪一段成立、在哪一段崩掉</h3>\n<p>这条式子本质上是连续近似，而真实解码是离散的步进：每一步的 B 都在变（连续批处理不断有请求完成、不断有新请求准入），所以 <code>TPOT(B)</code> 严格说是“当前批快照”的瞬时估计，而不是一个请求全生命周期的平均。工程上正确的用法是对每个调度决策点用当时的 B 代入，而不是拿一个稳态 B 去估全程。离散化带来的第一个误差是批内序列长度异质：<code>M_KV(B)</code> 是批内 KV 总量，长短请求混批会让均值随 B 漂移，线性外推失效。第二个误差是 <code>c_0</code> 本身并非常数——kernel launch 次数随算子融合策略变化，调度器每次决策的 CPU 开销在极高 QPS 下会抬升 <code>c_0</code>，此时“固定开销”变成了随负载变化的量。</p>\n<p>更关键的是线性假设的适用区间。解码的瘦矩阵乘在 B 较小时 SM 占用不足，时间随 B 线性上升；但当 B 大到把 SM 打满、或注意力 kernel 的 KV 分块不再能整块驻留时，<code>c_1</code> 开始出现台阶式跳变（tile 边界效应），线性模型低估时延。这就是公式的适用边界：它描述的是“SM 未饱和、KV 带宽未打满”的中间区间，两端都要打折扣。用表格对照三种区间的行为更清楚：</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>主导项</th><th>TPOT 随 B 的行为</th><th>模型可信度</th></tr></thead><tbody><tr><td>小批（SM 占用不足）</td><td><code>c_0/B</code></td><td>快速下降</td><td>高，线性假设成立</td></tr><tr><td>中批（SM 渐满）</td><td><code>c_1</code> 与带宽项</td><td>趋平</td><td>高，B* 通常落在此区间</td></tr><tr><td>大批（SM 饱和/带宽打满）</td><td>带宽项、tile 跳变</td><td>上升且非线性</td><td>低，线性模型低估</td></tr></tbody></table>\n<p>代价上要意识到：把 B 推过中批区间，吞吐的边际收益已经很小，而 TPOT 的非线性上升会让 SLO 迅速被击穿；此时多出来的显存被 KV 占满，反而压缩了可准入的新请求空间。</p>\n\n<h3 id=\"th-batch-latency-sec-11\">十一 · 失效条件的数学形态：MoE 倾斜与 prefill 抢占如何改写公式</h3>\n<p>两个失效条件都不是“模型不准”这么含糊，而是有明确的数学形态。MoE 下专家负载不均时，<code>c_1</code> 不再是常数，而是 B 的函数：批内 token 路由到少数热门专家，这些专家的 GEMM 被撑大而其余专家空转，有效计算量随 B 超线性增长，于是 <code>c_1(B)</code> 单调上升，第一项变成 <code>c_0/B + c_1(B)</code>，TPOT 曲线在原本该趋平的位置继续爬升，B* 被高估。诊断方法是分专家统计每步的实际负载方差，方差随 B 增大而扩大就说明线性模型已失效。</p>\n<p>chunked prefill 与解码混跑时，公式需要多一项排队项：prefill chunk 抢占了解码步的 SM 与带宽，解码请求被迫等待，等效于在 TPOT 上叠加 <code>W_prefill(B)</code>，即每个解码步因 prefill 插入而增加的平均等待。此时纯解码模型 <code>(c_0+c_1B)/B</code> 系统性低估时延，因为 <code>c_0</code> 里没有计入 prefill 的调度与同步开销。工程判断是：混跑场景下要么把 prefill 与 decode 的批上限分开配置，要么在 TPOT 预算里显式预留排队项，否则按纯解码式解出的 B* 必然偏高。代价侧，prefill 抢占抬高的是尾延迟而非均值——P99 TPOT 会比均值恶化得更快，SLO 若按均值校验就会漏掉违约。</p>\n\n<h3 id=\"th-batch-latency-sec-12\">十二 · 从公式到调度决策：B* 的求解与准入控制的落地</h3>\n<p><code>B* = \\arg\\max\\{B : \\text{TPOT}(B) \\le \\text{SLO}\\}</code> 在实现上不是一个解析解，而是一次单调性搜索：因为 TPOT 在有效区间内先降后升，可以从当前 B 出发做小步试探，找到第一个使 TPOT 越过 SLO 的 B，取其前一点作为批上限。调度器把这个上限作为准入控制的硬约束——队列里待准入的请求只有在 <code>B &lt; B*</code> 时才放行，否则排队等待。这里的工程代价是：B* 是随 KV 长度分布、专家负载、prefill 混入比例动态漂移的量，静态配置一个批上限必然在某些时段过保守（浪费吞吐）或在某些时段过激进（击穿 SLO）。因此正确的做法是周期性用实测的 <code>c_0</code>、<code>c_1</code>、<code>\\eta</code> 重估 B*，而不是一次性标定。</p>\n<p>一个具体机制：在连续批处理的每个调度 tick，采样上一 tick 的 <code>T_step</code> 与 B，用最小二乘拟合出局部 <code>c_0</code> 与 <code>c_1</code>，再代入公式预测下一 tick 在 <code>B+Δ</code> 时的 TPOT；若预测值逼近 SLO 就停止准入。这套闭环把公式从“纸面推导”变成“在线控制器”，其代价是拟合本身需要少量采样开销，且当批内长度分布突变时拟合窗口要缩短。误用形态很明确：把标定一次的 <code>c_1</code> 当常数外推到大批，MoE 倾斜时实际时延非线性上升，SLO 被击穿；或只按吞吐最大化选 B 而不校验 <code>TPOT(B) \\le \\text{SLO}</code>，单请求时延超标导致线上体验劣化。这两类失败都不是公式错，而是把公式的适用边界当成了全域。</p>\n\n<h3 id=\"th-batch-latency-sec-13\">十三 · 线性模型的边界：c₁ 何时不再是常数</h3>\n<p>把 TPOT(B) 写成 (c₀+c₁B)/B + M_KV(B)/(B_HBM·η) 之后，工程上真正危险的动作不是解 B*，而是把解出来的 B* 当成与负载无关的常量写进调度器。这个式子的可解性依赖一个隐含前提：c₁ 是每序列每步的边际成本，与批内序列的构成无关。解码阶段的稠密模型大致满足这一点——每步对每个序列做的都是同一组权重上的 GEMV，权重读取量被所有序列共享，KV 读取量随 B 线性增长，于是总时间近似 c₀+c₁B。但一旦批内序列激活的专家集合发生倾斜，c₁ 就变成了 B 的函数：MoE 每步要按 token 的路由结果聚合专家，被集中命中的少数专家其权重分片被反复搬运，而冷门专家所在的分片仍要占带宽；专家并行下还会出现某些 rank 空转、另一些 rank 排队等 All-to-All 的局面。此时真实时延对 B 是凸的，线性外推会系统性低估，B* 被高估，SLO 在负载上升时被击穿。</p>\n<p>量化这个偏差的办法不是去拟合一个更复杂的闭式解，而是在调度器里维护分段斜率。对每个候选批大小采样若干个观测步，用差分估计局部边际成本 c₁(B)=∂T_step/∂B，再检查它相对基准 c₁ 的漂移是否超过阈值；漂移超限即宣告线性区结束，把可行批上限压回上一个采样点。代价是采样本身要占用调度决策的时间窗：采样步不能与正常解码步重叠，等于在稳态吞吐上开一个周期性空洞，空洞长度与采样频率成正比。对延迟敏感型服务，这个空洞表现为 TPOT 的周期性抖动，抖动幅度取决于采样步被插入的位置；把它放在批切换点而非批中段，可以让抖动落在本就存在的调度间隙里。</p>\n<p>第二类失效来自混跑。chunked prefill 与解码共享同一条流时，prefill 分片会周期性抢占 SM 与 HBM 带宽，纯解码模型里那个干净的 c₀ 实际上被替换成 c₀ 加上一个排队项 W_q，而 W_q 取决于 prefill 分片的长度、到达间隔与解码批的剩余步数。近似写法是 T_step ≈ c₀+c₁B+W_q(λ_p, L_p)，其中 λ_p 为 prefill 分片到达率、L_p 为单片 token 数；W_q 对 B 不单调——批越大，单步解码占用越久，prefill 分片等待越久，反过来又拉长了解码步的尾延迟。这意味着混跑场景下 TPOT(B) 可能在中段出现一个局部极小再回升，只按端点求解会错过可行区间。工程判断是：混跑时不要用单一 B*，而是按 prefill 到达率把一天切成若干区间，每区间单独标定 c₀、c₁ 与 W_q 的经验值，准入控制按区间切换批上限。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>模型假设</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>稠密解码</td><td>c₁ 为常数</td><td>基本成立</td><td>固定开销随 B 摊薄，吞吐近线性</td></tr><tr><td>MoE 专家倾斜</td><td>c₁ 为常数</td><td>低估时延，B* 偏高</td><td>带宽被热点专家分片占满，冷 rank 空转</td></tr><tr><td>chunked prefill 混跑</td><td>无排队项</td><td>忽略 W_q，批上限过高</td><td>prefill 分片等待拉长解码尾延迟</td></tr></tbody></table>\n<p>还有一处近似容易被忽略：第二项 M_KV(B)/(B_HBM·η) 把 KV 读取当成与计算完全重叠的独立分量，但 η 本身随 B 变化——批小时 η 偏低，因为单步搬运量不足以填满 HBM 流水；批大时 η 接近饱和，此时再增大 B 只会让 M_KV 线性上涨而 η 不再改善，TPOT 的斜率被这一项放大。所以即便 c₁ 保持常数，B* 也会因为 η 的饱和点而被压低。实践上应把 η 作为 B 的函数标定，而不是取一个全局常数；标定成本是一次性的离线扫描，但扫描必须在目标精度与目标并行配置下做，换精度或换 TP 规模后 η 曲线会移动，旧标定值不能直接复用。</p>\n<h3 id=\"th-batch-latency-sec-14\">十四 · 线性假设的成立前提：解码稳态与批内同质</h3>\n<p>公式把每步总时间写成 <span class=\"formula\">$$T_{\\text{step}}(B)=c_0+c_1 B$$</span> 再除以 B，这一步隐含了一个非常强的结构假设：批内所有序列在每一步贡献相同的边际成本 c_1，且这个成本与 B 无关。要让该假设成立，需要同时满足三个条件。第一，批内序列处于纯解码阶段，每步每序列只生成一个 token，计算量由注意力读取 KV 与 MLP/专家权重读取主导，形状稳定。第二，批内序列长度分布足够集中，使 attention 的 KV 读取量不因个别长序列而畸变；一旦批内混入超长上下文序列，M_KV(B) 就不再是 B 的线性函数，而近似由最长序列的 KV 长度支配。第三，GPU 处于计算或带宽的同一工作点，kernel 启动开销 c_0 与 B 无关，且 SM 占用率随 B 单调上升而不发生抢占。这三条中任何一条破裂，c_1 就不再是常数，公式从“近似线性”退化为“分段线性”甚至“凸函数”。工程上判断是否越界，最直接的办法是做小步长批扫描：固定输入输出长度分布，测 B=1,2,4,…,B_max 的 TPOT，若相邻倍频点的 TPOT 增量比值明显偏离 1，就说明已进入非线性区，公式的 B* 解不再可信。</p>\n\n<h3 id=\"th-batch-latency-sec-15\">十五 · MoE 专家倾斜：c_1 随 B 非线性上升的第一个失效源</h3>\n<p>稠密模型里 c_1 的物理来源是每序列每步的权重读取与 KV 读取，二者随 B 近似线性。MoE 解码则不同：每个 token 经路由后只激活少数专家，但不同专家被激活的频率由路由分布决定。当 B 增大，批内 token 覆盖的专家集合扩张，被激活专家的权重读取总量不再与 B 成正比，而是由“被命中的专家数”决定。更关键的是，专家并行下每个专家分片位于不同设备，token 需要经 All-to-All 汇聚到专家所在设备再散回，通信量与批内路由的倾斜度直接相关。路由越倾斜，少数热点专家承载的 token 越多，其所在设备的计算与显存带宽成为瓶颈，而其余设备空转，形成木桶效应。此时每步时间可写成 <span class=\"formula\">$$T_{\\text{step}}(B)=c_0+\\max_{e}\\left(\\lambda_e(B)\\cdot c_e\\right)+T_{\\text{comm}}(B)$$</span>，其中 λ_e(B) 是专家 e 在批 B 下承载的 token 数，max 取的是最热专家。λ_e(B) 随 B 的增长不是线性的：小批时路由分布接近均匀，热点专家尚未饱和；大批时热点专家 token 数按比例放大，其设备成为串行瓶颈，T_step 出现超线性抬升。因此用常数 c_1 外推到大批，会系统性低估 TPOT，B* 被高估，SLO 在热点专家饱和点之后被击穿。判断是否落入该失效区，可监控每步各专家 token 计数的基尼系数或最大/均值比：该比值随 B 上升而单调抬升时，线性模型已不可用，应改用按专家负载上界约束的批上限，或引入专家容量因子限制单专家 token 数。</p>\n\n<h3 id=\"th-batch-latency-sec-16\">十六 · chunked prefill 混跑：排队项缺失导致纯解码模型失效</h3>\n<p>连续批处理调度器为了不让解码请求被长预填阻塞，通常把 prefill 切成 chunk 与解码请求混在同一批里执行。这时每步的组成不再是“B 个解码序列各出一个 token”，而是“B_d 个解码序列 + 若干 prefill chunk”。prefill chunk 的计算量由 chunk 长度决定，且其 attention 需要读取已有 KV 并写入新 KV，对 HBM 带宽的占用远高于单 token 解码。于是每步时间多出一项与 prefill 抢占相关的排队延迟：<span class=\"formula\">$$T_{\\text{step}}=c_0+c_1 B_d+c_{\\text{pf}}(L_{\\text{chunk}})+W_{\\text{queue}}(B_d,B_{\\text{pf}})$$</span>，其中 W_queue 是解码请求因 prefill 占用 SM 与带宽而被迫等待的时间。纯解码公式里没有这一项，等价于假设 prefill 从不与解码争抢资源。实际调度中，prefill chunk 越大，单步内解码 token 的完成时刻越被推后，TPOT 的尾部（p99）比均值恶化得更快。用纯解码模型估 TPOT 并据此设批上限，会把 B* 设得过高，因为模型看不见 prefill 带来的额外排队。工程上的修正不是把公式改复杂，而是把 prefill 与解码的资源配比作为独立维度：给定 SLO，先确定可容忍的 prefill 抢占比例（例如每步 prefill token 数上限），再在该约束下解 B*；或者采用分离式部署把 prefill 与解码放到不同资源池，从结构上消除这一项，此时纯解码公式重新成立。</p>\n\n<h3 id=\"th-batch-latency-sec-17\">十七 · 规模上限：固定开销摊薄收益的耗尽点</h3>\n<p>公式的第一项 c_0/B 随 B 增大单调下降，这给人一种“批越大越划算”的错觉。但摊薄收益有上限：当 c_0/B 降到远小于 c_1 时，继续增大 B 对 TPOT 的改善趋近于零，而 c_1 B/B=c_1 保持不变，第二项 M_KV(B)/(B_HBM·η) 却随 B 上升——因为批内 KV 总读取量随 B 增长，而 HBM 带宽 B_HBM 与利用率 η 是固定的。于是 TPOT(B) 在越过某点后由 KV 带宽项主导，随 B 单调上升。这个拐点就是规模上限的物理来源：它不是由 c_0 摊薄决定的，而是由带宽墙决定的。把公式对 B 求导并令其为零可得近似拐点条件 <span class=\"formula\">$$\\frac{c_0}{B^2}\\approx\\frac{\\partial}{\\partial B}\\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\eta}$$</span>，当左侧摊薄收益小于右侧带宽代价增速时，增大 B 已无正收益。工程含义是：B* 的存在不依赖 SLO，即使 SLO 很宽松，也存在一个吞吐饱和点，超过它吞吐不再上升而 TPOT 继续恶化。容量规划时应把该饱和点作为硬上限，而不是把 SLO 当作唯一约束。另一个规模上限来自批内序列数对调度器数据结构与 kernel 网格的约束：当 B 大到单步 kernel 的网格配置需要多波次（wave）执行时，c_0 不再是常数，而是随波次数上升，公式的固定开销项本身失效。</p>\n\n<h3 id=\"th-batch-latency-sec-18\">十八 · 误用模式与边界校验清单</h3>\n<p>三类误用都源于把公式当作外推工具而非局部近似。第一类是把 c_1 当常数外推到大批，忽略 MoE 专家倾斜，结果在热点专家饱和后 SLO 违约；第二类是在 chunked prefill 混跑时仍用纯解码模型，忽略 prefill 抢占排队项，批上限设得过高；第三类是只按吞吐最大化选 B 而不校验 TPOT(B)≤SLO，单请求时延超标。校验清单可以按以下顺序执行：先确认批内是否纯解码、长度分布是否集中，若不满足则公式仅作下界参考；再检查 MoE 路由的最大/均值比是否随 B 抬升，抬升则改用专家负载约束；再确认调度器是否启用 chunked prefill 混跑，启用则必须把 prefill 抢占比例作为独立约束或改用分离式部署；最后在候选 B* 附近做实测 TPOT 扫描，验证模型预测与实测的偏差方向。偏差若表现为实测高于预测且随 B 扩大，说明存在未建模的非线性项，应下调 B*。这套校验的成本是一次批扫描的测量开销，远低于线上 SLO 违约的代价。</p>\n\n<h3 id=\"th-batch-latency-sec-19\">十九 · 线性假设在何处开始失真</h3>\n<p>把每步总时间写成 c_0+c_1·B、再除以 B 得到单请求 TPOT，这一推导的全部效力都押在一个前提上：解码阶段批内序列对每步时间的贡献是可加的、且边际量 c_1 与 B 无关。工程上必须清楚，这不是物理定律，而是一段区间内的近似。当批内序列共享同一组权重、每步只做一次权重流式读取时，增大 B 主要增加的是 KV 读取与 MMA 工作量，边际成本近似恒定，模型成立；一旦批内序列的算子路径开始分叉——不同序列命中不同专家、不同序列处于不同上下文长度、不同序列触发不同的 kernel 变体——每步就不再是“一次固定开销 + B 份同质工作”，c_1 变成 B 的函数，公式从线性退化为凸甚至分段。判断边界的方法不是看 B 的绝对值，而是看每步实际发出的 kernel 种类数与权重读取次数是否随 B 增长：若二者近似不变，线性项可信；若随 B 上升，说明批内已出现路径分裂，此时应改用实测的每步时间曲线拟合，而不是外推常数 c_1。</p>\n<p>最典型的失效来自 MoE。稠密模型里每个 token 走全部权重，批扩大只是把同一份权重摊给更多 token；MoE 里每个 token 只激活部分专家，路由结果决定本步要触碰哪些专家权重。批小的时候路由分布容易集中，权重读取量小；批一大，被激活的专家集合迅速铺开，每步的权重流量随 B 上升，且专家负载倾斜会让少数热门专家成为串行瓶颈——它们的 GEMM 被拉长，而冷门专家的算力闲置。此时真实时延形如</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{MoE}}(B)\\approx \\frac{c_0+\\sum_{e\\in \\mathcal{E}(B)} w_e(B)\\cdot \\tau_e}{B}+\\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot\\eta}$$</div>\n<p>其中 w_e(B) 是专家 e 在本步承担的工作量，τ_e 是其单位工作量耗时，ℰ(B) 是随 B 扩张的激活专家集合。求和项对 B 的导数大于零且递增，线性模型在专家倾斜时系统性低估时延。系统代价直接体现在 TPOT 尾部：热门专家排队使该步被最慢专家钉住，批越大尾延迟越难收敛，而吞吐收益被闲置专家的空转抵消。工程判断是给 MoE 单独标定 c_1(B) 曲线，或在路由层做专家负载均衡与容量因子约束，把 B* 按最慢专家的饱和点而非平均值来取。</p>\n<p>第二个失效条件是 chunked prefill 与解码混跑。纯解码模型假设一步之内只有解码 token 在流动，固定开销 c_0 只含调度与 kernel 启动；一旦调度器把 prefill 块塞进同一批次，prefill 的算力密集段会抢占解码的 SM 与带宽，解码 token 被迫等待，产生一个与 B 无关、却与 prefill 块大小和到达率相关的排队项 Q。此时</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{mix}}(B)\\approx \\frac{c_0+c_1 B}{B}+\\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot\\eta}+Q(\\lambda_p,\\,s_p)$$</div>\n<p>Q 随 prefill 到达率 λ_p 与块尺寸 s_p 上升，且对解码批大小不敏感——这意味着继续调 B 无法压住它，反而可能因批内混入更多解码序列而拉长 prefill 块的等待窗口。代价是双重的：解码 TPOT 的 P99 被 prefill 抖动抬高，prefill 自身也因与解码争抢而 TTFT 变差。可用的工程手段是给 prefill 与解码设独立配额、限制单步内 prefill 块占比，或采用分离式预填/解码把两类流量物理隔离；只要混跑存在，就必须在模型里显式保留 Q 项，不能拿纯解码公式去定批上限。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>模型是否成立</th><th>主导代价</th><th>处置</th></tr></thead><tbody><tr><td>稠密、同构上下文、纯解码</td><td>成立，c_1 近似常数</td><td>固定开销摊薄 vs 边际成本</td><td>按 TPOT(B)≤SLO 解 B*</td></tr><tr><td>MoE、路由分散、专家倾斜</td><td>失效，c_1 随 B 非线性上升</td><td>最慢专家串行、权重流量增长</td><td>标定 c_1(B)、专家均衡、按饱和点取 B*</td></tr><tr><td>chunked prefill 混跑</td><td>失效，缺排队项 Q</td><td>prefill 抢占导致解码尾延迟</td><td>配额隔离或分离式部署，保留 Q 项</td></tr></tbody></table>\n<p>规模上限还有一层常被忽略的来源：第二项 M_KV(B)/(B_HBM·η) 里的 η 并非恒定。批越大，KV 读取越接近随机访问模式，HBM 的有效带宽利用率下降，η 随 B 走低，使该项的实际斜率高于线性外推。同时 KV 容量本身构成硬上限——当 B 逼近显存可容纳的序列数，调度器被迫做抢占与重算，每步时间出现阶跃而非平滑上升。因此 B* 的求解必须带三重校验：TPOT(B)≤SLO 的时延边界、KV 容量与 η 衰减的带宽边界、以及批内路径同质性边界。只按吞吐最大化把 B 推到远超 B*，或把 c_1 当常数外推到大批，都会让线上单请求时延超标；正确做法是把 B* 作为准入控制的动态上限，随路由分布与 prefill 负载实时重估，而不是一次性离线定死。</p>\n<h3 id=\"th-batch-latency-sec-20\">二十 · 从 TPOT 曲线反解批上限：B* 的数值求法与工程取值</h3>\n<p>公式给出的不是一条闭式解，而是一条需要“解边界”的不等式：$$\\text{TPOT}(B) \\approx \\frac{c_0 + c_1 B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta},\\quad B^{*}=\\arg\\max\\{B:\\text{TPOT}(B)\\le \\text{SLO}\\}$$。工程上不要试图解析求根，正确做法是把 B 当作离散整数做单调扫描：从 B=1 起逐点算 TPOT(B)，一旦越过 SLO 就回退一格，取最后一个满足约束的 B。因为第一项 (c_0+c_1B)/B 随 B 单调下降、第二项随 B 单调上升（KV 读取量随批内序列数增长），TPOT(B) 通常是先降后升的 U 形，扫描只需在拐点附近加密采样，前段可以大步跳。这个扫描本身代价极低——它只是算术，不触碰 GPU；真正的代价在于标定 c_0、c_1、η 三个系数，需要一次短程 profiling：固定 B 跑若干 decode step，测每步墙钟时间，做一次线性回归得到截距 c_0 与斜率 c_1，再用实测 HBM 读带宽除以理论峰值得到 η。</p>\n<p>举例：某解码服务 SLO 定为每 token 40 ms（即 TPOT ≤ 40 ms）。profiling 得到 c_0 约为数毫秒量级的固定 kernel 启动与调度开销，c_1 为每序列每步的边际成本。若不考虑 KV 项，令 (c_0+c_1B)/B = SLO 可解出 B 的上界；把 KV 项加上后，这个上界会被进一步压低，因为 M_KV(B) 随 B 增长而分母 B_HBM·η 是常数。工程判断是：<strong>B* 不是“越大越好”的调参目标，而是 SLO 的函数</strong>。SLO 收紧一半，B* 往往不是减半而是掉到远低于一半的位置，因为固定开销摊薄项在 B 较小时下降最快，一旦 SLO 逼近 c_1 的量级，可行域迅速收缩。</p>\n\n<h3 id=\"th-batch-latency-sec-21\">二十一 · 定并行度：把 B* 换算成 TP 与 EP 的切分粒度</h3>\n<p>批上限 B* 一旦确定，并行度就不是自由参数而是被约束的导出量。张量并行（TP）把单层计算切到多卡，直接压低 c_1 中与计算相关的部分，但同时抬高 c_0——每步多了 all-reduce/all-gather 的固定通信开销与更多 kernel 启动。于是 TP 的选取变成一个二维问题：在给定 B* 下，比较 (c_0(TP)+c_1(TP)·B*)/B* 是否仍低于 SLO，同时看吞吐是否随 TP 提升。判据是：<strong>只有当 c_1 的下降幅度足以覆盖 c_0 的上升，且 B* 在更大 TP 下不缩水到摊薄失效的程度，加 TP 才划算</strong>。B* 很小时（SLO 极紧），固定开销占比高，加 TP 往往适得其反。</p>\n<p>专家并行（EP）的情形更微妙：MoE 层每步要跑 all-to-all，这部分通信落在 c_0 里，而专家负载倾斜会让有效 c_1 随 B 非线性上升（这一点在适用边界里已指出，此处不展开机制）。因此在 EP 部署下，用线性模型解出的 B* 是<strong>乐观上界</strong>，必须乘一个保守折减系数再交给调度器。代价侧要盯的是：EP 度越大，单步 all-to-all 的固定延迟越高，B* 被 c_0 项压得越小，最终可能出现“并行度上去了、可行批反而变小、吞吐不升”的局面。工程上应把 B* 与并行度放进同一张表联合扫描，而不是先定并行度再调批大小。</p>\n\n<h3 id=\"th-batch-latency-sec-22\">二十二 · 定 KV 预算：把 M_KV(B) 反解成显存配额</h3>\n<p>第二项 M_KV(B)/(B_HBM·η) 是显存带宽约束的显式化，但它同时是显存容量的约束入口。给定 B*，KV 预算的最小值就是 M_KV(B*)：批内所有序列在 decode 每步要读的 KV 总量。反过来，若显存容量先被模型权重和其他驻留占用吃掉一大块，剩余 HBM 能支撑的 KV 量决定了 B 的物理上限 B_cap，那么真正可用的批上限是 min(B*, B_cap)。这个 min 是容量规划的核心动作：<strong>SLO 给出时延上限，显存给出容量上限，调度器取两者较小者</strong>。当 B_cap < B* 时，瓶颈从时延转到容量，此时提升吞吐的唯一路径是压缩 KV（更低精度、更激进的块管理）或提高 η，而不是继续调批。</p>\n<p>算例延续上节：假设 SLO 解出的 B* 为数十量级，而按每序列 KV 字节数与剩余 HBM 反算出的 B_cap 只有 B* 的一半，则实际批上限被容量钉死。此时若强行把 B 推到 B*，KV 会溢出到换页或触发抢占，TPOT 反而因换页抖动远超模型预测。工程判断：<strong>把 M_KV(B) 当作“每批的显存租金”来报价</strong>——每增加一个序列，就要为它预留 M_KV 的单序列增量，准入控制按剩余 KV 配额放行，而不是按请求数放行。带宽侧则看 η：η 越低（有效带宽利用率差），第二项越大，B* 越小，所以提升 η（更好的访存模式、更少的冗余读）等价于放宽批上限。</p>\n\n<h3 id=\"th-batch-latency-sec-23\">二十三 · 定 SLO 与准入控制：把不等式装进调度器</h3>\n<p>连续批处理调度器每个 step 都要做一次准入决策：新请求能否加入当前批。把 TPOT(B)≤SLO 直接编码成准入条件，就是“加入后预测 TPOT 仍不越界才放行”。实现上不必每步重解 B*，而是维护一个由标定系数算出的<strong>批上限阈值</strong>，并在运行时用滑动窗口的实测 TPOT 做闭环修正：实测持续高于预测，说明 c_1 被低估（MoE 倾斜或 prefill 混跑），阈值自动下调；实测持续低于预测，阈值可缓慢上探。这个闭环的价值在于它同时防住了两类失效：把 c_1 当常数外推到大批，以及在 chunked prefill 与解码混跑时仍用纯解码模型估 TPOT。</p>\n<p>后者的处理必须显式：混跑时 prefill 抢占会引入额外排队项，纯解码模型系统性低估时延，因此调度器在存在 prefill 的 step 上应对阈值打折，或把 prefill 的 token 数折算成等效批增量并入 B 再代入不等式。代价是吞吐：打折意味着少放请求，但换来的是 SLO 违约率下降。工程判断是<strong>把 SLO 违约当作硬约束、把吞吐当作目标函数</strong>，而不是反过来——只按吞吐最大化选 B 而不校验 TPOT(B)≤SLO，是线上体验劣化最常见的来源。准入控制还应区分优先级：高优请求允许占用更紧的 TPOT 预算，低优请求在批接近阈值时被推迟到下一 step，这本质上是给不同请求分配不同的 SLO 值再各自解 B*。</p>\n\n<h3 id=\"th-batch-latency-sec-24\">二十四 · 算例：一次完整的容量决策链路</h3>\n<p>设某解码服务目标 TPOT ≤ 40 ms，profiling 得 c_0 与 c_1 的标定值，η 由实测带宽比给出。第一步，扫描 B 得纯解码模型的 B*（数十量级）。第二步，按每序列 KV 字节数与剩余 HBM 算 B_cap，发现 B_cap 约为 B* 的六成，于是容量先钉死上限。第三步，评估加 TP：加 TP 后 c_1 下降但 c_0 上升，重扫发现 B* 上移而 B_cap 不变，故并行度提升对吞吐无益，维持原并行度。第四步，把 min(B*, B_cap) 作为调度器批上限，并按滑动窗口实测 TPOT 做闭环微调；存在 prefill 混跑的 step 额外打折。第五步，按此上限做容量规划：单副本吞吐 ≈ B_eff / TPOT，据此推算满足目标 QPS 所需副本数，并留出 SLO 违约的余量。</p>\n<p>这个链路里每一步都只用到公式的一个面：B* 用不等式边界，B_cap 用 M_KV 的容量解释，并行度用 c_0/c_1 的此消彼长，准入用闭环修正，容量用吞吐反算。任何一步跳过校验都会把误差传到下游：跳过 B_cap 会溢出，跳过闭环会在 MoE 倾斜时击穿 SLO，跳过 prefill 折算会在混跑时高估可行批。最终落在具体机制上：<strong>调度器持有的不是一个静态批大小，而是一组随实测 TPOT 漂移的阈值，公式提供初值与漂移方向，实测提供修正量</strong>。</p>\n\n<table class=\"mini\">\n<thead><tr><th>决策项</th><th>公式中的面</th><th>主要代价</th><th>校验动作</th></tr></thead>\n<tbody>\n<tr><td>批上限 B*</td><td>TPOT(B)≤SLO 边界</td><td>单请求 TPOT 变差</td><td>扫描取最后可行点</td></tr>\n<tr><td>并行度 TP/EP</td><td>c_0 升、c_1 降</td><td>固定通信开销抬高</td><td>联合扫描 B* 是否缩水</td></tr>\n<tr><td>KV 预算</td><td>M_KV(B*) 容量解释</td><td>显存占用、换页抖动</td><td>取 min(B*, B_cap)</td></tr>\n<tr><td>SLO 准入</td><td>不等式装进调度器</td><td>吞吐让位于违约率</td><td>滑动窗口闭环修正</td></tr>\n</tbody>\n</table>\n\n\n<h3 id=\"th-batch-latency-sec-25\">二十五 · 把 B* 变成调度器里的四个旋钮：批上限、并行度、KV 预算与准入</h3>\n<p>公式的价值不在纸面，而在它能被翻译成调度器里可执行的四个决策量。第一个是批上限：连续批处理调度器每步从等待队列取请求时，必须以 B* 为硬顶，而不是以显存剩余为硬顶。做法是先用 <span class=\"formula\">$$B^{*}=\\arg\\max\\{B:\\text{TPOT}(B)\\le \\text{SLO}\\}$$</span> 离线扫一遍 B，得到 TPOT 关于 B 的单调上升曲线与交点，再把交点向下取整作为 <em>max_num_seqs</em> 类的参数；运行时若实测 TPOT 逼近 SLO 的某个比例（例如 0.9 倍），调度器应主动停止接纳新请求而不是等显存耗尽。第二个是并行度：TPOT 中的 c_0 项随 TP 增大而增大（更多 rank 参与每步集合通信），c_1 项随 TP 增大而减小（每卡承担的权重与 KV 读取变少），因此 TPOT(B)≤SLO 的解集在 TP 维度上不是单调的——存在一个使 B* 最大的 TP 取值，工程上应沿这条曲线选 TP 而不是沿吞吐峰值选 TP。第三个是 KV 预算：第二项 M_KV(B)/(B_HBM·η) 说明 KV 读取时延与批内总 KV 字节成正比，因此 KV 预算应按“B* × 每序列平均上下文长度 × 每 token KV 字节”来预留，而不是按最大上下文长度预留；预留过量会挤掉权重与激活空间，预留不足则 B* 无法兑现。第四个是准入控制：当队列长度超过 B* 时，多出的请求应进入等待而非被塞进当前批，因为塞进去只会让整批 TPOT 一起超标，代价是队列等待时间上升——这是一个明确的吞吐与尾时延交换。</p>\n<p>算例可以定性走一遍。设某解码步的固定开销 c_0 主要来自 kernel 启动与跨 rank 调度，边际成本 c_1 来自每序列的权重读取与 KV 读取；在 SLO 给定的前提下，把 B 从较小值逐步增大，TPOT 先因 c_0/B 摊薄而下降，过拐点后因 c_1 主导而上升，交点即 B*。此时若把 B 推到远大于 B*，吞吐（tokens/s）确实上升，但单请求 TPOT 越过 SLO，线上表现为流式输出变卡、首 token 后的间隔抖动变大。反过来，若为了保险把 B 压到远小于 B*，固定开销无法摊薄，GPU 利用率与吞吐同时下降，容量规划会高估所需卡数。真正需要的是把 B* 当作一个随 SLO 与模型形态漂移的量：SLO 收紧则 B* 左移，KV 变长则第二项抬升、B* 左移，TP 增大则 c_0 抬升、B* 也可能左移。</p>\n<p>边界与失效条件是这套用法最容易被忽略的部分。线性模型成立的前提是解码阶段每序列的边际成本近似恒定，而 MoE 打破了这个前提：专家负载不均时，不同序列路由到不同专家，热门专家的权重读取与激活在批内被反复争用，c_1 随 B 非线性上升，线性外推会系统性低估时延，B* 被高估，SLO 在专家倾斜的批上被击穿。工程上的对策是把 c_1 按专家热度分档实测，或在调度层做专家亲和性分组，把路由到同一热门专家的请求分散到不同步，而不是简单加大 B。第二个失效条件是 chunked prefill 与解码混跑：prefill 分块会抢占解码步的 SM 与带宽，引入一个与 prefill 块大小、到达率相关的排队项，纯解码模型里没有这一项，于是按纯解码 B* 设的批上限在混跑负载下必然偏高。此时应把 prefill 的 token 预算与解码的 B 上限联合求解，或采用分离式预填/解码把两类负载物理隔开。第三个失效条件是只按吞吐最大化选 B 而不校验 TPOT(B)≤SLO——这在离线批推理里可行，在在线服务里等于把单请求时延交给运气。系统代价上，保守取 B 换的是吞吐与卡数，激进取 B 换的是尾时延与 SLO 违约风险，两者都不是免费的。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>由公式导出的取法</th><th>取错的代价</th></tr></thead><tbody><tr><td>批上限</td><td>B* 向下取整，运行时按 TPOT/SLO 比例提前刹车</td><td>过高：TPOT 越线；过低：c_0 摊不薄，吞吐与利用率双降</td></tr><tr><td>并行度 TP</td><td>沿使 B* 最大的 TP 取值，而非吞吐峰值</td><td>TP 过大抬升 c_0 与通信，B* 左移，卡数虚高</td></tr><tr><td>KV 预算</td><td>B* × 平均上下文 × 每 token KV 字节</td><td>按最大上下文预留会挤掉权重空间，B* 无法兑现</td></tr><tr><td>准入</td><td>队列超 B* 即等待，不塞批</td><td>塞批使整批 TPOT 同超，尾时延恶化</td></tr></tbody></table>\n<p>最后落在工程判断上：这套时延模型是容量决策的<em>一阶近似</em>，它的正确用法是给出 B* 的量级与漂移方向，再用线上实测的 TPOT 分位数做闭环校正——把实测的 c_1 随 B 的斜率回填进模型，一旦发现斜率随 B 抬升（MoE 倾斜或 prefill 混跑的征兆），就应把线性项替换为分段或带排队项的修正形式，而不是继续用常数 c_1 外推。调度器的批上限应当是模型给出的 B* 与实测反馈共同约束的结果，任何单靠公式定死的静态上限，都会在负载形态变化时先失效。</p>\n<h3 id=\"th-batch-latency-sec-26\">二十六 · 误用的共同结构：把边际项当常数</h3>\n<p>连续批处理时延模型最容易被误读的地方，不在公式本身，而在 c_1 的身份。c_1 是“每序列每步的计算/访存边际成本”，它的物理来源是注意力与 FFN 在解码步上的增量工作量。这个量在稠密模型、均匀负载、纯解码流下确实近似恒定，于是很多人把它当成一个可标定的常数，用一次小批测量拟合出 c_0 与 c_1，然后线性外推到 B 远超实测区间的位置，据此设定调度器的批上限。误用就发生在这条外推线上：模型给出的是 TPOT(B) 的单调上升曲线，而真实系统在 B 越过某个拐点后是超线性的。识别方法很直接——把 c_1 的标定区间与目标 B* 的比值作为健康指标，若 B* 落在标定区间的数倍之外，这个 B* 只是拟合曲线的产物，不是系统的边界。</p>\n<p>第二类误用更隐蔽：模型被用在它声明失效的场景里。chunked prefill 与解码混跑时，prefill 分块会抢占解码步的 SM 与 HBM 带宽，在每步时延里注入一个与 prefill 队列深度相关的排队项，纯解码模型没有这一项，于是估出的 TPOT 系统性偏低。第三类误用是目标函数写错：直接对吞吐求极大而不施加 TPOT(B)≤SLO 的约束，把 B 推到远超 B* 的位置。三者共享同一个后果——SLO 被击穿，但击穿的方式不同：第一类是斜率错，第二类是缺项，第三类是约束缺失。</p>\n\n<h3 id=\"th-batch-latency-sec-27\">二十七 · 反例：一次把批上限设高的完整推演</h3>\n<p>设某解码服务在标定区间内测得 c_0 与 c_1，拟合出 TPOT(B)≈(c_0+c_1·B)/B + M_KV(B)/(B_HBM·η)，并在小批下验证误差可接受。调度器据此解出 B*，把准入上限设为 B*，认为既满足 SLO 又拿到最大吞吐。上线后观测到的是：平均 TPOT 尚可，但尾部长请求的 TPOT 周期性尖刺，尖刺与 prefill 分块的到达节奏同步；同时 MoE 层在批内路由到同一专家的 token 数随 B 上升而聚集，专家负载倾斜使该层的有效计算时间非线性抬升。真实每步时延变成 (c_0+c_1(B)·B)/B 加上 prefill 排队项，其中 c_1(B) 随 B 上升，模型的两项都没覆盖。结果不是平均时延超标，而是 P99 超标——因为尖刺只在 prefill 与专家倾斜同时发生时出现，平均值把它稀释了。</p>\n<p>这个反例的诊断价值在于：它同时踩中两个失效条件，而两个失效条件的可观测特征不同。专家倾斜表现为“批越大、单步时间对 B 的斜率越陡”，可以在固定输入分布下做 B 扫描，用相邻批大小的单步时间差分估计局部斜率，若斜率随 B 单调上升即判定 c_1 非常数。prefill 抢占表现为“TPOT 与 prefill 队列深度相关”，可以按 prefill 队列深度分层统计 TPOT，若分层后组内方差显著下降、组间均值显著分离，则排队项存在。两项诊断都不需要新硬件，只需要在调度器里记录每步的 B、prefill 队列深度与实测步时。</p>\n\n<h3 id=\"th-batch-latency-sec-28\">二十八 · 后果的量级判断：为什么尾部先坏</h3>\n<p>误用的代价不是均匀分布的。固定开销摊薄项 (c_0)/B 随 B 下降，边际项随 B 上升，两者在 B* 附近交叉，TPOT 曲线在 B* 右侧的斜率由边际项主导。当 c_1 被低估、排队项被漏掉时，模型预测的 TPOT 在 B* 右侧仍平缓，真实曲线却已陡起。于是调度器认为“再加一点批还有余量”，实际每加一个序列，单步时间增量大于模型预期，SLO 余量被快速吃掉。由于 SLO 通常约束的是每 token 时延的上限而非均值，最先违约的是批内最老的请求——它经历了最多的步数，也最可能撞上尖刺。这就是尾部先坏、均值后坏的机制。</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{true}}(B) \\approx \\frac{c_0 + c_1(B)\\cdot B}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot\\eta} + Q_{\\text{prefill}}(d)$$</div>\n<p>其中 Q_prefill(d) 是 prefill 队列深度 d 的函数，模型缺的就是这一项，而 c_1(B) 的非线性是模型把它当常数造成的偏差。工程判断上，容量规划若用被低估的 TPOT 反推可承载并发，会高估系统容量；分离式部署里预填与解码的资源配比若按纯解码模型算，解码侧的批上限会被设得过高，预填侧的突发会直接转化为解码侧的 SLO 违约。</p>\n\n<h3 id=\"th-batch-latency-sec-29\">二十九 · 识别手法：三个可落地的检查</h3>\n<p>第一个检查是斜率扫描。在固定输入长度分布下，令 B 从标定区间上沿逐级增大，记录每级稳定后的单步时间，做相邻差分得到局部边际成本。若差分随 B 上升超过某个比例，说明 c_1 非常数，线性外推失效，此时应改用分段线性或直接以实测表驱动批上限。第二个检查是分层统计。把每步记录按 prefill 队列深度分桶，比较各桶的 TPOT 分布；若桶间均值差异显著，纯解码模型不可用，需在时延模型里显式加入排队项，或改为预填与解码资源隔离的部署形态。第三个检查是约束校验。把调度器的批上限决策与实际 TPOT 的 P99 做闭环对比，若 P99 长期贴近或越过 SLO 而模型预测仍有裕度，说明约束项缺失或斜率错，应立即下调批上限并重标定。</p>\n<ul>\n<li>斜率扫描的代价：需要一段可控的 B 扫描窗口，期间吞吐非最优，属于标定成本而非稳态成本。</li>\n<li>分层统计的代价：需要在调度器里增加每步的队列深度埋点，埋点本身几乎不占时延，但会占用少量调度器 CPU 与日志带宽。</li>\n<li>约束校验的代价：P99 统计需要滑动窗口，窗口过短会被尖刺主导、过长会掩盖拐点，窗口长度本身是一个需要按请求时长分布设定的参数。</li>\n</ul>\n\n<h3 id=\"th-batch-latency-sec-30\">三十 · 正确用法：把模型当边界探测器而非外推器</h3>\n<p>模型的正确位置是“在标定区间内定位 B* 的边界”，而不是“把 B* 外推到未测区间”。给定 SLO，先用小批数据拟合 c_0 与 c_1，解出 TPOT(B)≤SLO 的边界 B*，然后校验 B* 是否落在标定区间内：落在区间内，模型结论可直接用于准入控制；落在区间外，模型只给出方向，实际批上限必须由 B 扫描的实测拐点确定。对 MoE 模型，还应在拟合时按专家负载倾斜程度分层，倾斜越大，c_1 的有效值越高，B* 越保守。对 chunked prefill 混跑，应把解码步的时延预算拆成解码项与排队项两部分，排队项由 prefill 队列深度与分块大小决定，批上限按两项之和满足 SLO 来解。</p>\n<p>工程上更稳的做法是把模型输出当作调度器的初始值而非终值：准入控制以模型给出的 B* 起步，运行期用实测 TPOT 的 P99 做反馈，一旦 P99 越过 SLO 就按固定步长下调批上限，直到 P99 回到裕度内；反之在 P99 长期低于 SLO 且斜率扫描显示边际成本仍平缓时才小幅上调。这样模型提供的是有物理含义的起点，反馈环负责吸收 c_1 非线性与排队项这两类模型外误差。容量规划同理：用模型算出的 B* 乘以单批 token 产出得到名义吞吐上界，再用实测 P99 违约率打折，得到可承诺的 goodput，而不是直接把名义上界写进容量承诺。</p>\n\n<h3 id=\"th-batch-latency-sec-31\">三十一 · 一个必须写进调度器注释的判断</h3>\n<p>把 c_1 当常数外推，本质是把“标定区间的局部斜率”误当成“全局斜率”。解码步的边际成本由注意力读取的 KV 字节数与 FFN 的权重访存共同决定，前者随 B 线性、后者在 MoE 下随路由分布变化，二者叠加使 c_1 在批增大时不再恒定。因此任何以线性模型解出的 B*，都必须附带一个前提：B* 位于 c_1 近似恒定的区间内。这个前提不成立时，B* 只是一个乐观估计，调度器若照此设上限，尾部请求会先违约。识别它的最小成本手段是斜率扫描，最可靠的手段是 P99 闭环。把这条判断写进调度器的批上限配置注释里，比在文档里写十页推导更能防止误用。</p>\n\n<h3 id=\"th-batch-latency-sec-32\">三十二 · 当线性批模型开始说谎：三类误用与一个可复现的反例</h3>\n<p>这套时延模型最危险的地方不在于它算得不准，而在于它在小批区间算得太准，以至于工程师会把 <span class=\"inline-code\">c_1</span> 当成一个可以外推的物理常数。真实系统里 <span class=\"inline-code\">c_1</span> 是当前批内序列的边际成本，它随批组成变化：序列长度分布、KV 命中率、专家路由的集中度都会改写它。第一个典型误用是拿小批实测拟合出 <span class=\"inline-code\">c_0</span> 与 <span class=\"inline-code\">c_1</span>，然后直接解 <span class=\"inline-code\">B*</span> 并把调度器的批上限设成这个值。后果在 MoE 模型上尤其明显：当批内 token 大量路由到同一组专家时，被命中专家的权重读取与激活搬运在 HBM 上形成热点，<span class=\"inline-code\">c_1</span> 随 B 非线性上升，而模型仍按线性斜率预测 TPOT，于是实际时延越过 SLO 边界时调度器毫无察觉。识别方法很直接：在候选批上限附近做批大小扫描，记录每步 TPOT 对 B 的差分，若差分随 B 单调上升且斜率明显大于拟合值，说明已进入专家倾斜区，此时应改用分段拟合或直接以实测包络线做准入控制，而不是继续信任单点线性外推。</p>\n<p>第二个误用发生在预填与解码混跑的连续批处理系统里。纯解码模型把每步时间写成 <span class=\"inline-code\">c_0+c_1·B</span>，隐含假设是这一步只做解码。一旦 chunked prefill 的块被插入同一迭代，prefill 的计算量会抢占 SM 与 HBM 带宽，解码请求被迫等待，等价于在 TPOT 上叠加一个排队项：</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{mix}}(B) \\approx \\frac{c_0 + c_1 B + Q_{\\text{prefill}}(B, L_p)}{B} + \\frac{M_{\\text{KV}}(B)}{B_{\\text{HBM}}\\cdot \\eta}$$</div>\n<p>其中 <span class=\"inline-code\">\\(Q_{\\text{prefill}}\\)</span> 随插入的 prefill token 数 <span class=\"inline-code\">L_p</span> 与批内解码序列数增长，且不是 B 的线性函数。用纯解码模型解出的 <span class=\"inline-code\">B*</span> 在混跑下系统性偏高，表现为 TTFT 尚可但 TPOT 尾部抖动、P99 超标。识别信号是：同一批上限下，开启 chunked prefill 后 TPOT 的方差显著放大，且超标样本集中在 prefill 块较大的迭代。工程对策不是调小 <span class=\"inline-code\">B*</span> 了事，而是给调度器加一个显式的 prefill 预算约束——限制单次迭代插入的 prefill token 上限，使 <span class=\"inline-code\">\\(Q_{\\text{prefill}}\\)</span> 被压到可忽略量级，再回到纯解码模型选批。</p>\n<p>第三个误用最朴素也最常见：把吞吐最大化当作目标函数，直接把 B 推到显存与 KV 容量允许的上限，事后再看监控。这时 <span class=\"inline-code\">B*</span> 的约束 <span class=\"inline-code\">TPOT(B)≤SLO</span> 被完全跳过，单请求时延随批线性劣化，线上表现为首 token 之后出字变慢、流式体验塌陷，而集群吞吐指标却很好看。反例可以这样构造：某解码服务 SLO 设为每 token 时延上限，小批实测得 <span class=\"inline-code\">c_0</span> 较大、<span class=\"inline-code\">c_1</span> 较小，线性模型给出的 <span class=\"inline-code\">B*</span> 落在 KV 容量允许范围之内；运维按吞吐优先把批上限设为容量上限的两倍于 <span class=\"inline-code\">B*</span>，结果固定开销摊薄带来的收益早已饱和，而边际项与 KV 带宽项继续线性增长，TPOT 越过 SLO，P99 长尾被拉长，重试与超时反过来吃掉有效吞吐。这个反例的教训是：<span class=\"inline-code\">B*</span> 是 SLO 边界解而非性能最优点，超过它之后吞吐曲线趋于平坦甚至因排队与重试回落，继续加批是纯亏损。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>c_1 常数外推</td><td>MoE 专家倾斜，边际成本非线性</td><td>TPOT 对 B 的差分斜率超拟合值</td><td>SLO 击穿，尾延迟抬升</td></tr><tr><td>混跑仍用纯解码模型</td><td>prefill 抢占引入排队项</td><td>TPOT 方差放大，超标集中在长 prefill 迭代</td><td>P99 抖动，有效吞吐下降</td></tr><tr><td>吞吐优先不校验 SLO</td><td>越过 B* 后收益饱和、排队反噬</td><td>集群吞吐好看但单请求出字变慢</td><td>重试与超时吞掉吞吐增益</td></tr></tbody></table>\n<p>三类误用共享同一个根因：把模型当成预测器而不是边界条件。正确用法是让 <span class=\"inline-code\">B*</span> 只回答“在给定 SLO 下最大可行批是多少”，并把 <span class=\"inline-code\">c_1</span> 的时变性与 <span class=\"inline-code\">\\(Q_{\\text{prefill}}\\)</span> 的存在当作模型有效性的前置检查——每次调整批上限或开启混跑，先用批扫描验证线性假设仍成立，否则切换到实测包络或分段模型。调度器的准入控制应当以实测 TPOT 包络为硬约束，线性公式只用于初值设定与容量规划，不能作为线上闭环的唯一依据。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>B</td><td>当前批内序列数</td></tr><tr><td>c_0</td><td>每步固定 kernel 启动与调度开销</td></tr><tr><td>c_1</td><td>每序列每步计算/访存边际成本</td></tr><tr><td>\\eta</td><td>带宽利用率</td></tr><tr><td>\\text{SLO}</td><td>目标每 token 时延上限</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-batch-latency · 共 5 个片段</p>\n"},{"id":"th-pd-disagg-goodput","title":"分离式 P/D goodput 模型","direction":"dir-kv-cache-compression","prereq":[],"plain":"预填与解码分离后，系统 goodput 由两阶段各自资源配比与 KV 传输开销共同决定，配比失衡会让一侧成为空闲瓶颈。","definition":"预填与解码分离后，系统 goodput 由两阶段各自资源配比与 KV 传输开销共同决定，配比失衡会让一侧成为空闲瓶颈。","formula":"$$\\text{Goodput}=\\min\\left(\\frac{N_p\\cdot \\text{Th}_p}{1+\\rho},\\ \\frac{N_d\\cdot \\text{Th}_d}{1+\\rho}\\right),\\quad \\rho=\\frac{V_{\\text{KV}}}{B_{\\text{net}}\\cdot \\text{Th}_d}$$","variables":[{"sym":"N_p","meaning":"预填实例数"},{"sym":"N_d","meaning":"解码实例数"},{"sym":"\\text{Th}_p","meaning":"单预填实例吞吐"},{"sym":"\\text{Th}_d","meaning":"单解码实例吞吐"},{"sym":"\\rho","meaning":"KV 传输相对解码时间的占比"}],"derivation":"$\\rho$ 的物理含义：$V_{\\text{KV}}$ 为单请求 KV 缓存字节数，$B_{\\text{net}}$ 为可用网络带宽，$\\text{Th}_d$ 为解码实例吞吐；$\\rho$ 越大，传输在每请求周期中占比越高，两侧有效吞吐被同一因子稀释。","example":"适用边界：$\\rho\\ll1$ 且两侧配比接近时 min 模型有效；失效条件是 KV 传输走 PCIe 或跨机架网络使 $\\rho$ 接近 1，此时传输成为主导项，模型退化为纯网络带宽约束，增加实例数不再提升 goodput。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["当 KV 传输走 PCIe 或跨机架网络、ρ 接近 1 时，传输成为主导项，min 模型退化为纯网络带宽约束","请求长度分布剧烈变化时，静态 N_p/N_d 配比失效，需动态调度（如 DistServe/Splitwise 的弹性配比）"],"system_note":"用途：容量决策中用 $\\rho$ 判断该扩预填还是扩解码，并据 $\\min$ 项定位瓶颈侧；请求长度分布剧变时静态 $N_p/N_d$ 配比失效，需按 DistServe/Splitwise 式弹性配比动态调整。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：预填与解码拆到不同实例后，系统 goodput 由两侧各自「实例数×单实例吞吐」除以同一放大因子 $1+\\rho$ 后的较小值决定，配比失衡时吞吐被空闲的一侧卡住。","公式中 $N_p\\cdot\\text{Th}_p$ 是预填侧总吞吐，$N_d\\cdot\\text{Th}_d$ 是解码侧总吞吐，$\\min$ 表示流水线瓶颈取短板；$\\rho=V_{\\text{KV}}/(B_{\\text{net}}\\cdot\\text{Th}_d)$ 是 KV 传输时间相对解码时间的占比。","$\\rho$ 的物理含义：$V_{\\text{KV}}$ 为单请求 KV 缓存字节数，$B_{\\text{net}}$ 为可用网络带宽，$\\text{Th}_d$ 为解码实例吞吐；$\\rho$ 越大，传输在每请求周期中占比越高，两侧有效吞吐被同一因子稀释。","推导关键一步：把每请求周期拆为「解码计算时间」与「KV 传输时间」，传输与解码串行叠加得到 $1+\\rho$ 的放大因子，再对两侧分别做吞吐归一，取 min 得到端到端 goodput。","适用边界：$\\rho\\ll1$ 且两侧配比接近时 min 模型有效；失效条件是 KV 传输走 PCIe 或跨机架网络使 $\\rho$ 接近 1，此时传输成为主导项，模型退化为纯网络带宽约束，增加实例数不再提升 goodput。","用途：容量决策中用 $\\rho$ 判断该扩预填还是扩解码，并据 $\\min$ 项定位瓶颈侧；请求长度分布剧变时静态 $N_p/N_d$ 配比失效，需按 DistServe/Splitwise 式弹性配比动态调整。","常见误用：忽略 $\\rho$ 中的 $\\text{Th}_d$ 随批大小变化，把 $\\rho$ 当常数做静态配比；长请求突增时 $V_{\\text{KV}}$ 暴涨、$\\rho$ 上升，原配比下解码侧被传输拖死，goodput 断崖下跌。"],"anchors":[],"pitfalls":["按固定 $N_p/N_d$ 配比部署而不监控 $\\rho$，长上下文请求比例上升后 KV 传输占满带宽，解码实例空转，goodput 低于同构部署。","把 KV 传输放在 PCIe 或跨机架链路上却仍按 $\\rho\\ll1$ 估算容量，实际传输时延使 $1+\\rho$ 放大数倍，SLO 无法满足。","只扩预填实例而不检查解码侧 $\\text{Th}_d$ 是否随批膨胀下降，min 项始终落在解码侧，扩容投入无收益。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-1\">一 · 一句话直觉：短板在谁，goodput 就在谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-2\">二 · 严格定义：goodput 是流水线瓶颈速率，不是两侧吞吐之和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-3\">三 · 为什么需要这个模型：容量决策需要一个可定位瓶颈的闭式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-4\">四 · 常见误解之一：把 $\\rho$ 当常数做静态配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-5\">五 · 常见误解之二：只扩预填，不看解码侧 $\\text{Th}_d$ 是否随批膨胀下降</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-6\">六 · 常见误解之三：把 min 当成两侧吞吐之和，或把 $1+\\rho$ 只算在一侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-7\">七 · 边界条件：ρ 何时让 min 模型失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-8\">八 · 逐项拆解：min 的两条腿与共享的放大因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-9\">九 · 推导关键步：把请求周期切成串行两段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-10\">十 · 离散化与近似：三处必须标注的失真点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-11\">十一 · 失效边界的定量刻画：$\\rho\\to1$ 时 min 退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-12\">十二 · 容量决策中的用法：用 $\\rho$ 定位该扩哪一侧</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-13\">十三 · 当 min 失效：ρ 的漂移、配比僵化与扩容幻觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-14\">十四 · 当 min 模型退化：ρ 的边界、配比失效与扩容盲区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-15\">十五 · 边界不是免责声明，而是容量决策的坐标系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-16\">十六 · $\\rho$ 接近 1：min 模型退化为纯带宽约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-17\">十七 · 静态配比失效：长度分布是隐藏的状态变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-18\">十八 · $\\text{Th}_d$ 非常数：把 $\\rho$ 当常数的系统性误判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-19\">十九 · 规模上限：min 模型的线性假设在哪里断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-20\">二十 · 当 ρ 不再是小数：min 模型的三个塌陷面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-21\">二十一 · 边界不在公式里，在链路与分布里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-22\">二十二 · 用 min 项定位瓶颈侧，而不是用平均值估算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-23\">二十三 · 定批大小：批膨胀会同时压低 Th_d 与抬高 ρ</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-24\">二十四 · 定并行度：N_p 与 N_d 的比值由 Th 比值决定，而非由卡数决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-25\">二十五 · 定 KV 预算：ρ 是预算约束，不是事后指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-26\">二十六 · 定 SLO：把延迟目标翻译成 ρ 的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-27\">二十七 · 把 min 公式落到旋钮上：批、并行度、KV 预算与 SLO 的反向求解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-28\">二十八 · 误用的共同形状：把 min 当成加法，把 ρ 当成常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-29\">二十九 · 反例：固定配比 + PCIe 传输的长上下文突增</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-30\">三十 · 只扩预填：min 项始终落在解码侧的扩容陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-31\">三十一 · 请求长度分布剧变时静态配比的失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-32\">三十二 · 误用的代价账：延迟、吞吐、显存、带宽、功耗各落在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-pd-disagg-goodput-sec-33\">三十三 · 把 ρ 当常数：分离式 P/D 最贵的那个误用</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:533px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 532.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：预填与解码分离后，系统 goodput 由两阶段各自资源配比与 K…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\text{Goodput}=\\min\\left(\\frac{…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"450.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：当 KV 传输走 PCIe 或跨机架网络、ρ 接近 1 时，传输成…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-pd-disagg-goodput-sec-1\">一 · 一句话直觉：短板在谁，goodput 就在谁</h3>\n<p>把预填（prefill）和解码（decode）拆到两组不同实例上之后，系统的有效吞吐不再由单卡算力决定，而是由两组实例各自「实例数 × 单实例吞吐」中较小的那一个，再除以同一个放大因子 <span class=\"inline-math\">$1+\\rho$</span> 决定。这句话里有两个独立的工程含义：其一，分离式部署把一条流水线切成两段，端到端速率必然是两段速率的短板，扩哪一侧要看 min 落在哪一侧；其二，两段之间不是免费衔接的，KV cache 必须从预填实例搬到解码实例，这段搬运时间与解码计算时间串行叠加，于是两侧的有效吞吐被同一个因子稀释。直觉上可以把预填侧想成水泵、解码侧想成出水口、KV 传输想成连接管道：泵再强，管子细，出水就慢；出水口再大，泵不够，池子也灌不满。</p>\n<p>这个直觉之所以值得单独拎出来讲，是因为它和「同构部署下扩容就能线性提升吞吐」的默认心智模型直接冲突。在分离式部署里，盲目给某一侧加实例，很可能只是让本来就空闲的那一侧更空闲，goodput 一动不动，而功耗和显存占用照涨。判断扩容收益的第一步，永远是先定位 min 项落在哪一侧。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-2\">二 · 严格定义：goodput 是流水线瓶颈速率，不是两侧吞吐之和</h3>\n<p>本卷采用的 goodput 定义是端到端、单位时间内成功完成并满足 SLO 的请求数，其解析形式为：</p>\n<div class=\"formula\">$$\\text{Goodput}=\\min\\left(\\frac{N_p\\cdot \\text{Th}_p}{1+\\rho},\\ \\frac{N_d\\cdot \\text{Th}_d}{1+\\rho}\\right),\\quad \\rho=\\frac{V_{\\text{KV}}}{B_{\\text{net}}\\cdot \\text{Th}_d}$$</div>\n<p>变量含义需要严格钉死，避免后续讨论漂移：<span class=\"inline-math\">$N_p$</span> 是预填实例数，<span class=\"inline-math\">$N_d$</span> 是解码实例数，<span class=\"inline-math\">$\\text{Th}_p$</span> 是单预填实例吞吐（请求/秒），<span class=\"inline-math\">$\\text{Th}_d$</span> 是单解码实例吞吐，<span class=\"inline-math\">$V_{\\text{KV}}$</span> 是单请求 KV cache 字节数，<span class=\"inline-math\">$B_{\\text{net}}$</span> 是预填到解码之间可用网络带宽，<span class=\"inline-math\">$\\rho$</span> 是 KV 传输时间相对解码时间的占比。注意 <span class=\"inline-math\">$\\rho$</span> 的分母是 <span class=\"inline-math\">$B_{\\text{net}}\\cdot \\text{Th}_d$</span>，即「解码侧每秒推进的请求数 × 带宽」，它把字节量换算成了与解码节奏对齐的时间比例——这一点是定义的关键，也是后面所有误用的根源。</p>\n<p>推导的关键一步是把每请求周期拆成两段串行时间：解码计算时间与 KV 传输时间。设解码侧每完成一个请求需要的时间为 <span class=\"inline-math\">$1/\\text{Th}_d$</span>，传输同一请求 KV 需要 <span class=\"inline-math\">$V_{\\text{KV}}/B_{\\text{net}}$</span>，两者之比恰为 <span class=\"inline-math\">$\\rho$</span>，串行叠加得到放大因子 <span class=\"inline-math\">$1+\\rho$</span>。随后对两侧分别做吞吐归一：预填侧总吞吐 <span class=\"inline-math\">$N_p\\cdot\\text{Th}_p$</span> 除以 <span class=\"inline-math\">$1+\\rho$</span>，解码侧 <span class=\"inline-math\">$N_d\\cdot\\text{Th}_d$</span> 除以 <span class=\"inline-math\">$1+\\rho$</span>，取 min 即端到端 goodput。这里有一个容易被忽略的语义：<span class=\"inline-math\">$\\rho$</span> 是同一个值同时作用在两侧，因为每个请求都必须经过这段传输，无论预填侧多快。</p>\n<p>作为推理系统代价，这个定义直接给出三类可观测量的耦合关系：延迟侧看 <span class=\"inline-math\">$1+\\rho$</span> 对每请求周期的拉长；吞吐侧看 min 项的绝对值；显存与带宽侧看 <span class=\"inline-math\">$V_{\\text{KV}}$</span> 与 <span class=\"inline-math\">$B_{\\text{net}}$</span> 的比值。举例来说，若某部署中解码实例吞吐为每秒数十个请求量级、单请求 KV 为数十 MB 量级，而预填到解码走的是机内 PCIe 链路，则 <span class=\"inline-math\">$\\rho$</span> 很容易被推到接近 1 的量级，此时 <span class=\"inline-math\">$1+\\rho$</span> 把两侧吞吐砍掉近一半，goodput 远低于按算力估算的容量。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-3\">三 · 为什么需要这个模型：容量决策需要一个可定位瓶颈的闭式</h3>\n<p>分离式部署的卖点是把预填的算力密集与解码的访存密集解耦，各自选最合适的并行策略与批大小。但解耦之后，运维面对的是一个二维配比问题：<span class=\"inline-math\">$N_p/N_d$</span> 取多少。没有闭式模型时，团队只能靠压测扫参，代价是大量 GPU 小时，而且扫出来的点随请求长度分布漂移而失效。min 模型的价值在于它把「该扩哪一侧」变成一个可判定的问题：比较 <span class=\"inline-math\">$N_p\\cdot\\text{Th}_p$</span> 与 <span class=\"inline-math\">$N_d\\cdot\\text{Th}_d$</span>，小的一侧就是瓶颈侧，扩容只对瓶颈侧有意义。</p>\n<p><span class=\"inline-math\">$\\rho$</span> 则承担第二个决策职责：判断瓶颈是否根本不在算力侧。当 <span class=\"inline-math\">$\\rho$</span> 接近 1，传输成为主导项，min 模型退化为纯网络带宽约束，此时增加 <span class=\"inline-math\">$N_p$</span> 或 <span class=\"inline-math\">$N_d$</span> 都不提升 goodput——因为放大因子已经把两侧一起压死，而带宽是共享的。这个退化条件是容量规划里最该被前置检查的一条：先算 <span class=\"inline-math\">$\\rho$</span>，再谈配比。若 KV 传输走 PCIe 或跨机架网络，<span class=\"inline-math\">$B_{\\text{net}}$</span> 相对 NVLink 域内大幅下降，<span class=\"inline-math\">$\\rho$</span> 抬升，任何按 <span class=\"inline-math\">$\\rho\\ll1$</span> 估算出的容量都会系统性高估。</p>\n<p>第三个用途是弹性配比。请求长度分布剧变时，静态 <span class=\"inline-math\">$N_p/N_d$</span> 配比失效：长请求突增使 <span class=\"inline-math\">$V_{\\text{KV}}$</span> 暴涨、<span class=\"inline-math\">$\\rho$</span> 上升，原配比下解码侧被传输拖死，goodput 断崖下跌。DistServe/Splitwise 式的弹性配比正是把这个模型当作在线控制器：持续观测 <span class=\"inline-math\">$\\rho$</span> 与 min 项位置，动态迁移实例角色。代价是角色切换本身要重配并行组、清空或迁移 KV，切换期间有效容量下降，因此弹性配比的收益必须与切换开销一起核算，而不是无条件优于静态配比。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-4\">四 · 常见误解之一：把 <span class=\"inline-math\">$\\rho$</span> 当常数做静态配比</h3>\n<p>最常见的误用是忽略 <span class=\"inline-math\">$\\rho$</span> 分母里的 <span class=\"inline-math\">$\\text{Th}_d$</span> 随批大小变化。<span class=\"inline-math\">$\\text{Th}_d$</span> 不是硬件铭牌上的定值：连续批处理下批越大，单实例每秒推进的请求数上升，但每请求的 KV 传输时间并不随批缩小，于是 <span class=\"inline-math\">$\\rho$</span> 随批增大而下降；反过来，批被 SLO 或显存压小时 <span class=\"inline-math\">$\\text{Th}_d$</span> 下降，<span class=\"inline-math\">$\\rho$</span> 上升。把 <span class=\"inline-math\">$\\rho$</span> 当常数写进容量表，等于假设解码侧永远跑在同一个批大小上，一旦调度器因显存压力缩小批，实际 <span class=\"inline-math\">$\\rho$</span> 就偏离估算值，<span class=\"inline-math\">$1+\\rho$</span> 放大数倍，SLO 无法满足。</p>\n<p>这个误解的工程后果有明确的失败模式：按固定 <span class=\"inline-math\">$N_p/N_d$</span> 配比部署而不监控 <span class=\"inline-math\">$\\rho$</span>，长上下文请求比例上升后 KV 传输占满带宽，解码实例空转，goodput 低于同构部署——分离式部署不但没赚到解耦收益，反而多付了传输开销。正确的做法是把 <span class=\"inline-math\">$\\rho$</span> 作为运行时观测量而非部署常量：在容量表里记录 <span class=\"inline-math\">$\\rho$</span> 对应的批大小与请求长度假设，并在监控里对 <span class=\"inline-math\">$\\rho$</span> 设阈值告警。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-5\">五 · 常见误解之二：只扩预填，不看解码侧 <span class=\"inline-math\">$\\text{Th}_d$</span> 是否随批膨胀下降</h3>\n<p>第二个高频误判是默认瓶颈在预填。预填是算力密集段，直觉上「贵、慢、该扩」，于是团队持续加 <span class=\"inline-math\">$N_p$</span>。但如果解码侧 <span class=\"inline-math\">$\\text{Th}_d$</span> 因批膨胀、KV 显存压力或带宽争用而下降，min 项始终落在解码侧，扩容投入零收益。模型给出的判据很直接：只有当 <span class=\"inline-math\">$N_p\\cdot\\text{Th}_p &lt; N_d\\cdot\\text{Th}_d$</span> 时扩预填才有意义；而 <span class=\"inline-math\">$\\text{Th}_d$</span> 本身是批大小的函数，扩预填会推高到达率、推高解码批大小，进而压低 <span class=\"inline-math\">$\\text{Th}_d$</span>——扩容动作本身可能把 min 项从预填侧搬到解码侧，收益在途中被吃掉。</p>\n<p>这条误解还牵连 <span class=\"inline-math\">$\\rho$</span>：扩预填提高到达率后，单位时间需要搬运的 KV 字节数上升，若 <span class=\"inline-math\">$B_{\\text{net}}$</span> 不变，传输链路饱和度上升，等效 <span class=\"inline-math\">$\\rho$</span> 变大。也就是说扩预填同时做了两件对解码侧不利的事：抬高批、抬高传输占比。工程判断应当是先测解码侧在当前批下的 <span class=\"inline-math\">$\\text{Th}_d$</span> 与 <span class=\"inline-math\">$\\rho$</span>，再决定扩容方向；若 <span class=\"inline-math\">$\\rho$</span> 已接近 1，正确动作是换传输链路或压缩 KV，而不是加实例。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-6\">六 · 常见误解之三：把 min 当成两侧吞吐之和，或把 <span class=\"inline-math\">$1+\\rho$</span> 只算在一侧</h3>\n<p>第三类误解在建模层面：有人把分离式部署的 goodput 写成 <span class=\"inline-math\">$N_p\\cdot\\text{Th}_p + N_d\\cdot\\text{Th}_d$</span> 再除以某个系数，仿佛两段可以并行叠加。这在流水线语义下是错的——同一批请求必须顺序经过预填与解码，端到端速率由慢段决定，min 才是正确算子。写成和式会系统性高估容量，且掩盖瓶颈位置，导致配比决策失去依据。另一类同源错误是把 <span class=\"inline-math\">$1+\\rho$</span> 只乘在解码侧，理由是「传输发生在解码之前」。但 <span class=\"inline-math\">$\\rho$</span> 的分母已经用 <span class=\"inline-math\">$\\text{Th}_d$</span> 做了归一，它度量的是每请求周期中传输所占比例，这个周期对两侧的吞吐归一同样适用；只乘一侧会低估放大效应，在 <span class=\"inline-math\">$\\rho$</span> 接近 1 时误差接近一倍。</p>\n<p>还有一个边界误解：认为 min 模型在 <span class=\"inline-math\">$\\rho$</span> 大时仍然可用，只是数值变小。事实是当 <span class=\"inline-math\">$\\rho$</span> 接近 1、传输成为主导项时，模型退化为纯网络带宽约束，此时 min 的形式已不再刻画系统行为——增加实例数不再提升 goodput，因为瓶颈是共享带宽而非实例数。适用边界必须写进模型的使用说明：<span class=\"inline-math\">$\\rho\\ll1$</span> 且两侧配比接近时 min 模型有效；<span class=\"inline-math\">$\\rho$</span> 接近 1 时改用带宽约束式，并把「换链路、压 KV、改拓扑」列为首选动作，而非扩容。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-7\">七 · 边界条件：ρ 何时让 min 模型失效</h3>\n<p>这个模型真正能用的地方，是 ρ 远小于 1 且 N_p/N_d 配比接近最优的那一小块区域。一旦 KV 传输离开 NVLink 域、走 PCIe 或跨机架链路，ρ 会迅速逼近 1，此时 min 括号里的 1+ρ 不再是轻微稀释，而是主导项：预填侧算得再快、解码侧批得再大，每请求周期都被传输时间吃掉一半以上，增加实例数只是把更多请求塞进同一条带宽管道，goodput 不再随 N_p 或 N_d 上升。工程上应把 ρ 当作容量规划的第一观测量，而不是部署完再补的监控项——ρ 越过阈值就意味着该换拓扑（同机架 NVLink 域内放置 P/D 对）或改方案（KV 压缩、分层缓存），而不是继续加卡。</p>\n<p>失效的第二个来源是请求长度分布的时变性。静态 N_p/N_d 配比隐含假设 V_KV 的均值稳定，但长上下文请求比例一旦抬升，V_KV 暴涨直接推高 ρ；更隐蔽的是 Th_d 本身随批大小变化，批越大单请求解码时间被摊薄，ρ 中的分母随之改变，把 ρ 当常数做静态配比就会系统性低估传输占比。DistServe/Splitwise 式弹性配比的意义正在于此：按滑动窗口内的 ρ 与两侧 min 项实时重分实例，而不是按部署时的平均值一次定死。</p>\n<div class=\"formula\">$$\\text{Goodput}=\\min\\left(\\frac{N_p\\cdot \\text{Th}_p}{1+\\rho},\\ \\frac{N_d\\cdot \\text{Th}_d}{1+\\rho}\\right),\\quad \\rho=\\frac{V_{\\text{KV}}}{B_{\\text{net}}\\cdot \\text{Th}_d}$$</div>\n<p>三种典型失败模式值得在容量评审时逐条对照。其一，固定配比部署却不监控 ρ：长上下文请求比例上升后 KV 传输占满带宽，解码实例空转，goodput 反而低于同构部署——分离带来的收益被传输开销全额抵消。其二，KV 传输放在 PCIe 或跨机架链路上却仍按 ρ≪1 估算容量，实际 1+ρ 放大数倍，SLO 直接无法满足，这类错误在跨机架 NVL72 组网时最容易发生。其三，只扩预填实例而不检查解码侧 Th_d 是否随批膨胀下降，min 项始终落在解码侧，扩容投入零收益。判断方法很直接：先算 ρ 定位传输是否主导，再看 min 落在哪一侧决定扩谁，两者都不满足时，问题不在配比而在拓扑。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>模型行为</th><th>工程动作</th></tr></thead><tbody><tr><td>ρ≪1，配比接近</td><td>min 模型有效，瓶颈在算力侧</td><td>按 min 项扩对应侧实例</td></tr><tr><td>ρ→1（PCIe/跨机架）</td><td>退化为纯带宽约束</td><td>改拓扑或压缩 KV，停止加卡</td></tr><tr><td>长度分布剧变</td><td>静态 N_p/N_d 失效</td><td>弹性配比，按 ρ 动态重分</td></tr></tbody></table>\n<h3 id=\"th-pd-disagg-goodput-sec-8\">八 · 逐项拆解：min 的两条腿与共享的放大因子</h3>\n<p>公式的骨架是两条独立吞吐腿被同一个 <span class=\"formula\">$$1+\\rho$$</span> 稀释后取小。先看分子。$N_p\\cdot\\text{Th}_p$ 是预填侧的总吞吐能力，单位是「请求/秒」或「token/秒」，取决于 $\\text{Th}_p$ 的度量口径；工程上必须把两侧口径统一，否则 min 是在比较两个不同量纲的数，配比决策直接失真。$\\text{Th}_p$ 本身不是常数：它随预填批大小、序列长度、是否使用 chunked prefill 而变，长序列预填受注意力二次项支配，短序列预填受 kernel 启动与调度开销支配。$N_d\\cdot\\text{Th}_d$ 同理，$\\text{Th}_d$ 随解码批大小上升而上升，直到 KV cache 容量或带宽触顶。</p>\n<p>分母 $1+\\rho$ 是这套模型最容易被误读的部分。它不是「预填侧除以一个因子、解码侧除以另一个因子」，而是两侧共用一个因子——这一点决定了模型的全部行为。推导上，$\\rho$ 描述的是每个请求在解码阶段额外附加的串行时间占解码计算时间的比例。既然每个请求都要经历这段传输，那么无论它落在哪个解码实例上，单位时间内能完成的请求数都被同一个比例压缩。这就是为什么 min 外面只有一个 $1+\\rho$，而不是两条腿各自带一个分母。</p>\n<p>代价含义直接：$\\rho$ 每增加一倍，端到端 goodput 上限近似腰斩（在 min 项不变的前提下）。举例，某部署 $N_d\\cdot\\text{Th}_d$ 为瓶颈侧、$\\rho=0.1$，则有效 goodput 是解码侧裸吞吐的 $1/1.1$；若 KV 传输改走跨机架链路使 $\\rho$ 升至 $0.8$，同样的解码实例只能交付裸吞吐的 $1/1.8$，接近一半的算力被传输吃掉。这不是延迟问题，是吞吐问题——实例没有变慢，是它们单位时间内能翻台的请求数变少了。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-9\">九 · 推导关键步：把请求周期切成串行两段</h3>\n<p>推导的起点是单请求周期的分解。一个请求在分离式架构里的完整生命周期是：预填实例完成 prompt 计算并产出 KV → KV 经网络搬运到解码实例 → 解码实例逐 token 生成。关键假设是「传输与解码串行叠加」，即解码实例在收到完整 KV 之前不能开始生成（除非做分块传输与流水重叠，那是后续部分的主题，此处按串行处理）。</p>\n<p>设单请求在解码侧的计算时间为 $t_d=1/\\text{Th}_d$（按单实例、单请求归一），KV 传输时间为 $t_{\\text{kv}}=V_{\\text{KV}}/B_{\\text{net}}$。串行叠加得单请求占用解码侧资源的总周期 $t_d+t_{\\text{kv}}=t_d(1+\\rho)$，其中 <span class=\"formula\">$$\\rho=\\frac{t_{\\text{kv}}}{t_d}=\\frac{V_{\\text{KV}}}{B_{\\text{net}}\\cdot\\text{Th}_d}$$</span>。这一步是全部推导的枢纽：$\\rho$ 不是「传输带宽利用率」，而是「传输时间相对解码时间的比值」，量纲为一。</p>\n<p>接着做吞吐归一。解码侧在周期 $t_d(1+\\rho)$ 内交付一个请求，故单实例有效吞吐为 $\\text{Th}_d/(1+\\rho)$，$N_d$ 个实例合计 $N_d\\cdot\\text{Th}_d/(1+\\rho)$。预填侧同理被同一因子稀释——因为预填产出的 KV 也必须走同一条链路、同一段串行时间才能变成可交付的 token，故预填侧有效吞吐为 $N_p\\cdot\\text{Th}_p/(1+\\rho)$。两级串联无缓冲时，稳态吞吐取短板，得最终式。</p>\n<p>这里有一个必须点明的近似：把预填侧也除以 $1+\\rho$ 隐含假设「预填与解码的请求速率匹配、KV 链路对两侧同等计价」。若预填侧可以批量聚合 KV（多个请求的 KV 合并传输摊薄开销），则预填侧的实际稀释因子小于 $1+\\rho$，模型偏保守。工程判断：当 $\\rho$ 较大且预填侧具备聚合能力时，真实 goodput 会高于公式预测，此时不应据公式盲目扩解码实例。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-10\">十 · 离散化与近似：三处必须标注的失真点</h3>\n<p>第一处失真是 $\\text{Th}_d$ 的批依赖被当成常数。公式里 $\\text{Th}_d$ 出现在分子与 $\\rho$ 的分母两处，但它在两处的物理意义并不相同：分子处是「批大小为 $b$ 时的解码吞吐」，分母处是「同一批大小下的单请求解码时间倒数」。若部署时按小批标定的 $\\text{Th}_d$ 代入，而实际运行批被拉大，$\\text{Th}_d$ 上升使 $\\rho$ 下降，公式会低估传输占比；反之按大批标定、实际批被 KV 容量压小，$\\rho$ 被低估。正确做法是把 $\\rho$ 写成批大小的函数 $\\rho(b)=V_{\\text{KV}}/(B_{\\text{net}}\\cdot\\text{Th}_d(b))$，在容量规划中对目标批大小求解，而不是取一个标量。</p>\n<p>第二处是 $V_{\\text{KV}}$ 被当作单请求定值。实际 $V_{\\text{KV}}$ 随上下文长度线性增长（每 token 每层若干字节），请求长度分布是重尾的。把 $V_{\\text{KV}}$ 取均值代入 $\\rho$，等价于假设传输开销按请求数均匀分摊，而真实系统中长请求的 KV 传输会瞬时占满带宽，把同批短请求的解码也拖慢——这是排队效应，min 模型无排队项，无法刻画。离散化上的补救是把请求按长度分桶，对每桶算 $\\rho_i$，再以桶内请求数为权重做加权，得到分段线性的 goodput 曲线；桶划分粒度决定模型精度，通常按 KV 字节数的数量级分 3–5 桶即可捕获断崖。</p>\n<p>第三处是「串行」假设本身。真实流水里 KV 传输可与后续 token 的解码部分重叠（首 token 必须先到，后续层可流式到达），此时有效放大因子介于 $1$ 与 $1+\\rho$ 之间。公式给出的是上界代价，即最坏串行情形。工程上若已实现分块 KV 传输与解码重叠，应把 $\\rho$ 乘一个重叠系数 $\\alpha\\in(0,1]$ 再代入，$\\alpha$ 由实测的首 token 到达延迟与稳态 token 间隔之比标定。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-11\">十一 · 失效边界的定量刻画：$\\rho\\to1$ 时 min 退化</h3>\n<p>公式的适用边界可以用 $\\rho$ 的两个极限读出。当 $\\rho\\ll1$，$1+\\rho\\approx1$，goodput 退化为 $\\min(N_p\\text{Th}_p,N_d\\text{Th}_d)$，配比是唯一矛盾，扩容按短板侧线性收益。当 $\\rho$ 接近甚至超过 $1$，分母主导，两条腿同时被压缩，此时增加 $N_p$ 或 $N_d$ 的边际收益被 $1/(1+\\rho)$ 吃掉——这就是「增加实例数不再提升 goodput」的定量来源。</p>\n<p>更精确地说，goodput 对实例数的偏导为 $\\partial G/\\partial N_d=\\text{Th}_d/(1+\\rho)$（当解码侧为短板时）。只要 $\\rho$ 翻倍，这个偏导就减半。若 KV 传输走 PCIe，$B_{\\text{net}}$ 相比 NVLink 低一个量级以上，$V_{\\text{KV}}$ 不变时 $\\rho$ 被放大同样倍数，偏导趋近于零，扩容投入基本无效。这就是失效条件的物理读数：不是模型错了，是模型告诉你瓶颈已经从算力搬到链路，而 min 结构仍在按算力分配注意力。</p>\n<p>具体例子：一个长上下文服务，单请求 KV 为数十 MB 量级，解码实例 $\\text{Th}_d$ 在目标批下为每秒若干请求，若链路可用带宽只够每秒搬运与解码同量级的 KV 字节，则 $\\rho$ 落在 $1$ 附近，$1+\\rho\\approx2$，goodput 上限是纯算力模型的一半。此时把 $N_d$ 翻倍，goodput 只从 $A/2$ 升到 $A$（$A$ 为原解码总吞吐），而若把 KV 传输迁到 NVLink 域内使 $\\rho$ 降到 $0.1$，同样实例数直接拿到 $A/1.1$——链路改造的收益大于扩容。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-12\">十二 · 容量决策中的用法：用 $\\rho$ 定位该扩哪一侧</h3>\n<p>公式的工程价值不在算出一个数，而在给出决策顺序。第一步算 $\\rho$，判断它是否已接近 $1$：若是，任何扩容都是在给链路交税，应先改拓扑或压缩 KV（量化、分块、复用），把 $\\rho$ 压下来再谈配比。第二步在 $\\rho$ 可控的前提下比较两条腿的裸吞吐 $N_p\\text{Th}_p$ 与 $N_d\\text{Th}_d$，短板侧即扩容侧；由于两侧共享同一分母，比较裸吞吐即可，无需把 $\\rho$ 分别摊到两侧。</p>\n<p>第三步是动态校验。静态 $N_p/N_d$ 配比在请求长度分布剧变时失效：长请求比例上升使 $V_{\\text{KV}}$ 均值暴涨，$\\rho$ 随之上升，原配比下解码侧被传输拖死，goodput 断崖。DistServe/Splitwise 式弹性配比的意义正在于此——把 $N_p/N_d$ 做成随 $\\rho$ 与两侧队列深度反馈调整的量，而不是部署时的常数。监控项应是 $\\rho$ 的实时估计（用实测 KV 字节吞吐除以解码请求速率）与两侧实例的空转率，空转率是 min 项落在哪一侧的直接证据。</p>\n<p>最后一条工程判断：$\\rho$ 的分母含 $\\text{Th}_d$，而 $\\text{Th}_d$ 随批膨胀下降（KV 容量与带宽触顶时），这意味着「扩解码实例」这个动作本身会通过降低单实例 $\\text{Th}_d$ 抬高 $\\rho$，形成负反馈。只扩预填不检查解码侧 $\\text{Th}_d$ 的部署，min 项始终落在解码侧，扩容投入无收益——公式在这里不是预测工具，是诊断工具：它把「哪一侧被卡住」和「为什么扩容没用」压缩成同一个比值。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-13\">十三 · 当 min 失效：ρ 的漂移、配比僵化与扩容幻觉</h3>\n\n<p>公式的脆弱点不在 min 本身，而在 ρ 被当作常数使用。ρ = V_KV / (B_net · Th_d) 中三个量都不是静态的：V_KV 随请求上下文长度线性增长，B_net 在跨机架链路上被其他流量挤占，而 Th_d 随解码批大小上升而下降——批越大，单请求分摊到的算力越少，Th_d 越小，ρ 反而越大。这意味着 ρ 与解码侧负载正相关：解码越忙，传输占比越高，1+ρ 的稀释越重。把 ρ 当成部署时标定一次的常数去反推 N_p/N_d，等于假设系统永远工作在标定点。工程上应把 ρ 作为运行时观测量（KV 传输队列深度、链路有效带宽、解码批大小）持续采样，而不是写进配置文件的常量。</p>\n\n<p>失效边界可以用一个判据刻画：当 ρ 接近 1，1+ρ 约为 2，min 的两项同时被腰斩，但更关键的是传输时间与解码时间同量级，此时 KV 传输不再是“叠加在解码上的开销”，而是与解码并列的主路径。若 KV 走 PCIe 或跨机架网络，B_net 比机内 NVLink 低一个量级，ρ 迅速越过 1，min 模型退化为纯带宽约束：Goodput ≈ B_net / V_KV，与 N_p、N_d 都无关。此时扩容实例数不改变分子，只增加争抢同一链路的传输流，goodput 甚至下降。判断是否落入该区间，只需比较 B_net·Th_d 与 V_KV 的量级——前者小于后者，min 模型已无决策价值。</p>\n\n<table class=\"mini\"><thead><tr><th>工况</th><th>ρ 量级</th><th>瓶颈侧</th><th>扩容动作的有效性</th></tr></thead><tbody><tr><td>机内 NVLink、短上下文</td><td>远小于 1</td><td>由 N_p·Th_p 与 N_d·Th_d 较小者决定</td><td>扩短板侧有效</td></tr><tr><td>跨机架、中等上下文</td><td>接近 1</td><td>传输与解码并列</td><td>扩容收益被 1+ρ 稀释</td></tr><tr><td>PCIe、长上下文突增</td><td>大于 1</td><td>纯网络带宽</td><td>扩容无效，需改拓扑或压缩 KV</td></tr></tbody></table>\n\n<p>第二类失效来自配比僵化。静态 N_p/N_d 只在请求长度分布稳定时成立；长请求比例上升时 V_KV 暴涨、ρ 上升，解码侧每请求周期被传输拖长，等效 Th_d 下降，min 项落向解码侧，而预填实例仍按原配比空转。DistServe/Splitwise 式弹性配比的实质是把 N_p/N_d 变成随 ρ 与两侧队列深度调整的控制变量，代价是实例角色切换带来的冷启动与 KV 迁移开销——切换粒度越细，调度开销越不可忽略。第三类失效是扩容幻觉：只扩预填而不检查 Th_d 是否随批膨胀下降，min 始终落在解码侧，投入无收益。工程判断应固定为：先测 ρ 与两侧有效吞吐，再决定扩哪一侧；ρ 越过阈值时，优先改传输拓扑或做 KV 量化压缩，而不是加实例。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-14\">十四 · 当 min 模型退化：ρ 的边界、配比失效与扩容盲区</h3>\n<p>该模型的有效性建立在一个隐含前提上：<span class=\"formula\">$$1+\\rho$$</span> 是两侧共享的同一稀释因子，且两侧吞吐可独立线性叠加。一旦 KV 传输走 PCIe 或跨机架网络，ρ 逼近 1，传输时间与解码计算时间同量级，min 的瓶颈判定失去意义——此时增加 <span class=\"formula\">$$N_p$$</span> 或 <span class=\"formula\">$$N_d$$</span> 只会在网络带宽上排队，goodput 退化为纯带宽约束 <span class=\"formula\">$$B_{\\text{net}}\\cdot\\text{Th}_d/V_{\\text{KV}}$$</span>，实例数不再是自由变量。工程判据是：ρ 超过某一阈值（传输时延已不可被解码计算掩盖）后，扩容预算应转向链路升级而非实例扩容。</p>\n<p>第二个失效点是静态配比。请求长度分布剧变时 <span class=\"formula\">$$V_{\\text{KV}}$$</span> 随之暴涨，ρ 上升，原 <span class=\"formula\">$$N_p/N_d$$</span> 下解码侧被传输拖死、预填侧空转，goodput 断崖下跌，甚至低于同构部署。这要求按 DistServe/Splitwise 式弹性配比动态调整，而不是把 ρ 当常数做容量规划。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>代价落点</th></tr></thead><tbody><tr><td>忽略 Th_d 随批大小变化，ρ 视为常数</td><td>配比失真，min 项判错侧</td><td>扩容投入无收益</td></tr><tr><td>PCIe/跨机架链路仍按 ρ≪1 估算</td><td>1+ρ 放大数倍，SLO 失守</td><td>尾延迟</td></tr><tr><td>只扩 N_p 不查解码侧 Th_d 膨胀</td><td>瓶颈始终在解码侧</td><td>GPU 时与功耗浪费</td></tr></tbody></table>\n<p>推导中的离散化近似也需交代：把每请求周期拆为“解码计算时间 + KV 传输时间”串行叠加，忽略了传输与下一批解码的重叠机会，因而 <span class=\"formula\">$$1+\\rho$$</span> 是保守上界；连续批处理下 Th_d 随批膨胀而下降，ρ 的分母不是定值，静态代入会系统性低估传输占比。容量决策时应以实测 ρ 与 min 项定位瓶颈侧，而非用公式一次性外推。</p>\n<h3 id=\"th-pd-disagg-goodput-sec-15\">十五 · 边界不是免责声明，而是容量决策的坐标系</h3>\n<p>min 模型的价值不在于给出一个数，而在于给出一个<strong>可判定的适用域</strong>：只有当 $\\rho$ 足够小、且两侧配比落在均衡点附近时，$\\min(N_p\\text{Th}_p, N_d\\text{Th}_d)/(1+\\rho)$ 才与实测 goodput 同阶。工程上真正要问的不是\"公式对不对\"，而是\"我当前这套部署落在公式的哪一侧\"。把 $\\rho$ 当作部署前的一次性估算值，是这套模型最常见的死法：$\\rho$ 是随负载形状漂移的状态量，不是配置常量。它的分母里有 $\\text{Th}_d$，而 $\\text{Th}_d$ 本身随批大小、序列长度、KV 占用而变，于是 $\\rho$ 与配比之间存在隐式耦合——扩解码实例会抬高聚合 $\\text{Th}_d$，从而压低 $\\rho$；扩预填实例则几乎不动 $\\rho$，只抬高 min 的另一侧。这个不对称性决定了扩容方向的选择顺序。</p>\n<p>边界的第一层是<strong>串行叠加假设</strong>。推导把每请求周期拆成\"解码计算时间\"与\"KV 传输时间\"两段相加，得到 $1+\\rho$ 放大因子。这要求传输与解码在同一请求的关键路径上严格串行、且传输不被流水线隐藏。若系统用双缓冲把第 $i$ 个请求的 KV 传输与第 $i-1$ 个请求的解码重叠，则有效放大因子退化为 $\\max(1,\\rho)$ 而非 $1+\\rho$，模型从\"加法惩罚\"变成\"取大惩罚\"，此时按 $1+\\rho$ 做容量规划会系统性高估所需实例数。判断依据很直接：看解码实例的 SM 占用率在传输窗口内是否掉坑；若掉坑，串行假设成立，$1+\\rho$ 可用；若 SM 持续饱和而 NIC 另有峰值，说明重叠已生效，应改用取大形式。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-16\">十六 · $\\rho$ 接近 1：min 模型退化为纯带宽约束</h3>\n<p>失效条件的核心是 $\\rho\\to1$。此时 $1+\\rho\\to2$，两侧有效吞吐同时被砍半，而更严重的是<strong>结构性退化</strong>：goodput 不再由 $\\min(N_p\\text{Th}_p, N_d\\text{Th}_d)$ 决定，而由 $B_{\\text{net}}$ 与 $V_{\\text{KV}}$ 的比值决定。把公式重写为带宽视角：</p>\n<div class=\"formula\">$$\\text{Goodput}_{\\rho\\to1}\\ \\approx\\ \\frac{B_{\\text{net}}}{V_{\\text{KV}}}\\cdot\\frac{1}{1}\\quad\\text{（每请求 KV 字节数决定请求完成速率上限）}$$</div>\n<p>含义是：无论堆多少预填或解码实例，端到端完成率被\"每秒能搬多少 KV 字节 ÷ 每请求多少 KV 字节\"钉死。加实例只会让更多请求排队等同一根链路，goodput 曲线进入平台区。这正是\"增加实例数不再提升 goodput\"的机制来源，不是经验观察。工程判据：当 $\\rho$ 的估算值超过约 0.3 时就应把网络带宽列为一级容量项，超过 1 则 min 模型应整体弃用，改用带宽约束式做规划。</p>\n<p>链路类型直接决定 $\\rho$ 的量级。NVLink 5 域内（GB200/GB300 NVL72 机架内）$B_{\\text{net}}$ 高，$\\rho$ 通常被压在远小于 1 的区间，min 模型可用；一旦 KV 传输跨机架走 InfiniBand 或落到 PCIe，$B_{\\text{net}}$ 下降一到两个数量级，$V_{\\text{KV}}$ 不变而 $\\rho$ 同比放大，模型瞬间失效。具体例子：一个长上下文请求在 FP8 KV 下每 token 每层占数百字节量级，数万 token 的上下文使 $V_{\\text{KV}}$ 进入百 MB 级；若 $B_{\\text{net}}$ 只有数十 GB/s 量级，单请求传输时间就与解码计算时间同阶，$\\rho$ 逼近 1，此时 P/D 分离的收益被传输吃掉，同构部署反而更稳。这是\"分离式部署在跨机架场景下 goodput 低于同构\"的机理，不是调度策略问题。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-17\">十七 · 静态配比失效：长度分布是隐藏的状态变量</h3>\n<p>第二个失效条件是请求长度分布剧变。静态 $N_p/N_d$ 配比隐含假设：$V_{\\text{KV}}$ 的分布稳定、$\\text{Th}_p$ 与 $\\text{Th}_d$ 的比值稳定。预填吞吐随输入长度近似反比下降（计算量随 token 数线性增长），解码吞吐随上下文长度下降（每步要读全部 KV），两者对长度分布的敏感度不同，于是最优配比是长度分布的函数。当长请求比例上升，$V_{\\text{KV}}$ 暴涨、$\\rho$ 上升、$\\text{Th}_d$ 下降，三重效应同向叠加，原配比下解码侧被传输拖死，goodput 断崖式下跌——这不是渐变，是 min 项切换导致的阶跃。</p>\n<p>伪代码式的判据可以写成监控回路：</p>\n<div class=\"formula\">$$\\text{每窗口采样}\\ \\hat\\rho=\\frac{\\bar V_{\\text{KV}}}{B_{\\text{net}}\\cdot \\hat{\\text{Th}}_d},\\quad \\text{若}\\ \\hat\\rho\\ \\text{环比上升超过阈值}\\ \\Rightarrow\\ \\text{触发配比重算}$$</div>\n<p>重算的目标不是让 $N_p\\text{Th}_p=N_d\\text{Th}_d$（那是忽略 $\\rho$ 的均衡），而是在 $\\rho$ 更新后重新解 min 的均衡点，并按 DistServe/Splitwise 式弹性配比迁移实例。代价是重配置期间的容量空窗：实例迁移、KV 路由表更新、连接重建都会带来秒级到十秒级的吞吐凹陷，因此重算阈值不能设得太敏感，否则系统在配比之间来回震荡，goodput 反而低于静态部署。这是弹性配比的真实工程代价，不是免费的自适应。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-18\">十八 · $\\text{Th}_d$ 非常数：把 $\\rho$ 当常数的系统性误判</h3>\n<p>最常见误用是把 $\\rho$ 当配置常量写进容量表。$\\rho$ 的分母含 $\\text{Th}_d$，而 $\\text{Th}_d$ 随批大小变化：批越大，单实例聚合吞吐越高，但每请求的 KV 读取与传输也越密集。批膨胀时 $\\text{Th}_d$ 上升会压低 $\\rho$，看似有利；但同一批内 $V_{\\text{KV}}$ 总量上升，若 $B_{\\text{net}}$ 已被打满，传输排队使有效 $\\rho$ 反弹。两个方向相反的效应意味着 $\\rho$ 对批大小不是单调的，用单点估算做静态配比必然在某个负载区间失准。</p>\n<p>更隐蔽的失败模式是\"只扩预填不查解码\"：运维看到 min 项落在预填侧就加 $N_p$，但若 $\\text{Th}_d$ 因批膨胀或长上下文已下降，min 项会滑到解码侧，扩容投入零收益。判据是每次扩容后复测两侧的实际 $\\text{Th}$，而不是沿用部署初期的标定值。表格给出边界判定与对应动作：</p>\n<table class=\"mini\"><thead><tr><th>状态</th><th>判据</th><th>模型可用性</th><th>工程动作</th></tr></thead><tbody><tr><td>域内 NVLink、短上下文</td><td>$\\rho\\ll1$，配比接近均衡</td><td>min 模型有效</td><td>按 min 项定位瓶颈侧扩容</td></tr><tr><td>跨机架/PCIe</td><td>$\\rho$ 接近或超过 1</td><td>退化为带宽约束</td><td>停用 min 模型，先解带宽或回退同构</td></tr><tr><td>长度分布漂移</td><td>$\\hat\\rho$ 环比阶跃</td><td>静态配比失效</td><td>弹性配比重算，接受重配置凹陷</td></tr><tr><td>批膨胀</td><td>$\\text{Th}_d$ 实测下降</td><td>$\\rho$ 非常数</td><td>复测两侧 $\\text{Th}$，禁止沿用标定值</td></tr></tbody></table>\n\n<h3 id=\"th-pd-disagg-goodput-sec-19\">十九 · 规模上限：min 模型的线性假设在哪里断</h3>\n<p>公式隐含<strong>吞吐线性可加</strong>：$N_p$ 个预填实例的总吞吐是 $N_p\\text{Th}_p$。这在实例数较少、路由均衡时成立；规模上去后三处断裂。其一，KV 路由与元数据管理本身消耗 CPU 与网络，实例数增长使路由表与连接数超线性增长，控制面成为新瓶颈。其二，预填侧的批调度在实例数增多后难以维持满批，$\\text{Th}_p$ 的实际值低于单实例标定值，线性外推高估容量。其三，解码侧的 KV 读取在实例数增多后对同一存储层的带宽竞争加剧，$\\text{Th}_d$ 随 $N_d$ 上升而边际递减。</p>\n<p>规模上限的判据可以写成边际收益检查：</p>\n<div class=\"formula\">$$\\frac{\\partial\\,\\text{Goodput}}{\\partial N_d}\\ \\to\\ 0\\ \\text{时停止扩容，此时瓶颈已从计算侧转移到路由/带宽侧}$$</div>\n<p>工程含义是：min 模型的容量规划只在\"瓶颈侧明确、且扩容边际收益为正\"的区间内有效。一旦两侧吞吐都接近平台，公式给出的扩容建议就是噪声。具体例子：NVL72 机架内 72 个 GPU 全部投入 P/D 分离，若 KV 传输仍走域内 NVLink，$\\rho$ 可控，模型可用；但若把解码实例跨到第二机架，$B_{\\text{net}}$ 骤降、路由跳数增加，$\\rho$ 与路由开销同时上升，此时应把\"机架\"当作配比的基本单元——先在机架内解 min，再决定跨机架复制还是回退同构，而不是把全局 $N_p/N_d$ 当成一个可自由切分的数。</p>\n<p>最后落在工程判断上：这套模型的适用边界由三个量共同划定——$\\rho$ 的量级决定 min 形式是否成立，长度分布的稳定性决定静态配比是否可用，实例规模的边际收益决定线性外推是否可信。三者中任何一个越界，正确的动作不是给公式打补丁，而是切换到对应的退化形式（带宽约束式、弹性配比回路、边际收益检查），并在监控里把 $\\hat\\rho$、两侧实测 $\\text{Th}$、扩容边际收益作为一等指标持续采样。公式是决策的入口，边界是决策的出口。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-20\">二十 · 当 ρ 不再是小数：min 模型的三个塌陷面</h3>\n<p>公式成立的前提是 $1+\\rho$ 只是一个轻微稀释因子，而非主导项。一旦 KV 传输离开 NVLink 域——走 PCIe 直连、或跨机架经过 spine 层——可用带宽 $B_{\\text{net}}$ 骤降，而单请求 KV 字节数 $V_{\\text{KV}}$ 随上下文长度线性增长，$\\rho=V_{\\text{KV}}/(B_{\\text{net}}\\cdot\\text{Th}_d)$ 会迅速逼近甚至超过 1。此时 min 结构失去意义：两侧的有效吞吐被同一个大因子压扁，端到端 goodput 退化为 $\\approx B_{\\text{net}}\\cdot\\text{Th}_d/V_{\\text{KV}}$ 的纯带宽约束，扩预填或扩解码实例都不改变分子，投入全部沉没。工程判断很直接——若部署拓扑无法保证 $\\rho\\ll1$，分离式 P/D 的收益从一开始就不存在，应退回同构部署或改用 KV 压缩、分层放置把 $V_{\\text{KV}}$ 压下来。</p>\n<p>第二个塌陷面藏在 $\\rho$ 的分母里：$\\text{Th}_d$ 不是常数，它随解码批大小膨胀而下降（每 token 的注意力与权重读取被更多序列摊薄，但单步时延上升）。把 $\\rho$ 当静态量做容量规划，等于假设解码侧永远跑在最优批上。真实负载中长请求突增会同时推高 $V_{\\text{KV}}$ 与批大小，$\\rho$ 双向上升，原配比下解码实例被传输串行拖住、预填侧却空转，goodput 出现断崖。正确做法是把 $\\rho$ 当作运行时可测量——按滑动窗口统计实际传输时延占解码周期比例——并据此触发配比调整，这正是 DistServe/Splitwise 弹性配比的立足点：配比是 $\\rho$ 与请求长度分布的函数，不是部署时的一次性常数。</p>\n<p>第三个边界是静态 $N_p/N_d$ 对负载分布的敏感性。min 模型隐含请求长度平稳、预填与解码负载比例稳定的假设；一旦长短请求混合比例剧变，固定配比必然使某一侧成为空闲瓶颈。可用一张判据表快速定位失效类型：</p>\n<table class=\"mini\"><thead><tr><th>观测信号</th><th>模型含义</th><th>处置</th></tr></thead><tbody><tr><td>$\\rho$ 持续上升且解码实例利用率低</td><td>传输主导，min 退化为带宽约束</td><td>缩短链路、压缩 KV、放弃跨架分离</td></tr><tr><td>预填侧排队而解码侧空闲</td><td>min 落在预填项</td><td>增 $N_p$，但先确认 $\\text{Th}_p$ 未被批膨胀侵蚀</td></tr><tr><td>解码侧排队而预填侧空闲</td><td>min 落在解码项</td><td>增 $N_d$ 或降批，勿盲目扩预填</td></tr><tr><td>两侧均未饱和但 goodput 低于同构</td><td>$1+\\rho$ 放大已抵消分离收益</td><td>回退同构或改拓扑</td></tr></tbody></table>\n<p>规模上限由此显形：分离式 P/D 的可行域是「$\\rho$ 小 + 配比可弹性 + 长度分布可预测」的三重交集，任一维度越界，min 模型给出的容量数字就不再可信。最危险的误用是只扩预填实例而不检查解码侧 $\\text{Th}_d$ 是否随批膨胀下降——min 项始终落在解码侧，扩容投入零收益，而监控面板上预填利用率漂亮得很。把 $\\rho$ 与两侧饱和度作为一等指标纳入调度回路，比任何静态配比表都更能守住 SLO。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-21\">二十一 · 边界不在公式里，在链路与分布里</h3>\n<p>min 模型成立的前提是两条：<strong>ρ 足够小</strong>，以及<strong>两侧配比在观测窗口内近似恒定</strong>。前者把 KV 传输当作对解码周期的小幅稀释，后者保证 N_p·Th_p 与 N_d·Th_d 是两个稳定的常数。任一前提破裂，公式给出的容量结论就会系统性偏乐观。最典型的破裂点是链路：一旦 KV 传输走 PCIe 或跨机架网络，B_net 相比 NVLink 域内带宽下降一个量级，ρ 迅速逼近甚至超过 1，此时 <span class=\"formula\">$$1+\\rho$$</span> 不再是修正因子而是主导项，min 退化为纯网络带宽约束——加实例只增加排队，不增加 goodput。工程判据很直接：若 ρ>1，扩容 N_p 或 N_d 的边际收益趋零，唯一有效动作是缩短 KV 路径（同机架放置、改走 NVLink 域）或压缩 V_KV（量化 KV、GQA 头数、前缀复用）。</p>\n<p>第二个破裂点是 ρ 自身的非定常性。ρ=V_KV/(B_net·Th_d) 中 Th_d 随批大小变化：批越大，单实例解码吞吐越高，但每请求分到的带宽份额与 KV 读取压力同步上升，Th_d 并非单调常数。把 ρ 当常数做静态配比，等价于假设请求长度分布平稳。长上下文请求比例一旦突增，V_KV 暴涨、ρ 抬升，解码侧被传输拖住，预填侧却仍在满负荷产出 KV，结果是预填实例排队、解码实例空转，goodput 出现断崖而非缓降。这类失效不会在平均指标上立刻显形，只在尾延迟与 SLO 违约率上暴露。</p>\n<p>规模上限还有一层：min 模型是稳态流模型，不含排队动态。当 N_p 与 N_d 都很大、单侧接近饱和时，请求在预填队列与 KV 传输队列上的等待时间方差放大，端到端延迟分布的尾部远超均值预测，此时按平均吞吐做的容量规划会低估所需冗余。可用一张判据表快速定位：</p>\n<table class=\"mini\"><thead><tr><th>观测信号</th><th>含义</th><th>动作</th></tr></thead><tbody><tr><td>ρ 接近 1 且随负载上升</td><td>传输主导，min 失效</td><td>改链路或压缩 V_KV，停止扩容</td></tr><tr><td>预填队列长、解码实例利用率低</td><td>N_p/N_d 偏大</td><td>下调 N_p 或上调 N_d</td></tr><tr><td>解码侧 Th_d 随批膨胀下降</td><td>min 项锁死在解码侧</td><td>扩解码前先查批内 KV 读取瓶颈</td></tr></tbody></table>\n<p>因此该模型的正确用法是把它当作<strong>配比决策的局部线性化</strong>：在 ρ≪1、长度分布稳定的窗口内，用 min 项定位短板并做增量扩容；一旦 ρ 抬升或分布漂移，就必须切换到 DistServe/Splitwise 式弹性配比，按实时 ρ 与队列深度重算 N_p/N_d，而不是沿用部署时的静态比例。忽略这一点的失败模式很具体：固定配比部署、不监控 ρ，长上下文比例上升后带宽被 KV 传输占满，解码实例空转，goodput 反而低于同构部署。</p>\n<h3 id=\"th-pd-disagg-goodput-sec-22\">二十二 · 用 min 项定位瓶颈侧，而不是用平均值估算</h3>\n<p>容量决策的第一件事不是算总量，而是判断短板落在哪一侧。公式的 min 结构给出一个直接的判据：比较 <span class=\"formula-inline\">N_p·Th_p</span> 与 <span class=\"formula-inline\">N_d·Th_d</span> 两个乘积。若前者小于后者，预填侧是瓶颈，此时增加解码实例只会抬高分母中的闲置容量，goodput 不变；反之亦然。工程上常见的错误是按「总 token/s 需求 ÷ 单实例 token/s」估算实例总数再对半分，这种做法在两侧单实例吞吐不对称时必然失衡——预填是计算密集、解码是访存密集，同一张卡在两种负载下的吞吐量级不同，对半分等于默认二者相等。</p>\n<p>具体机制上，把 min 项写成可观测的量：每侧实例的实时占用率。若预填侧 GPU 的 SM 占用率长期接近饱和而解码侧显存带宽占用率只有一半，说明 min 落在预填侧，扩容方向明确。代价方面，失衡的直接表现是吞吐损失而非延迟损失——goodput 被短板锁死，另一侧的空闲算力变成纯粹的资本浪费。举例：一个 NVL72 机架内切出 4 个预填实例与 8 个解码实例，若实测 <span class=\"formula-inline\">Th_p</span> 约为 <span class=\"formula-inline\">Th_d</span> 的两倍，则 <span class=\"formula-inline\">N_p·Th_p = 8·Th_d</span> 恰与解码侧持平，配比刚好平衡；此时若把预填加到 6 个，goodput 一分不涨，只是把预填侧的空闲率从 0 抬到 33%。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-23\">二十三 · 定批大小：批膨胀会同时压低 Th_d 与抬高 ρ</h3>\n<p>批大小不是独立变量，它通过两条路径进入公式。第一条是 <span class=\"formula-inline\">Th_d</span> 本身随批增大而下降——解码阶段每 token 需读取全部权重与 KV，批越大单请求分摊的权重读取越少、总吞吐上升，但单实例的每请求延迟上升，若 <span class=\"formula-inline\">Th_d</span> 定义为满足 SLO 前提下的吞吐，则批膨胀到一定程度后 <span class=\"formula-inline\">Th_d</span> 反而回落。第二条更隐蔽：<span class=\"formula-inline\">ρ = V_KV/(B_net·Th_d)</span> 的分母含 <span class=\"formula-inline\">Th_d</span>，批增大使 <span class=\"formula-inline\">Th_d</span> 变化时 ρ 随之漂移，把 ρ 当常数做静态配比是典型误用。</p>\n<p>伪代码思路：给定 SLO 的每 token 延迟上限 <span class=\"formula-inline\">L_slo</span>，对候选批大小 <span class=\"formula-inline\">b</span> 扫描，先测该批下解码实例的实际 <span class=\"formula-inline\">Th_d(b)</span> 与每请求 KV 字节 <span class=\"formula-inline\">V_KV(b)</span>（批内并发请求越多，单实例驻留的 KV 总量越大，但单请求 V_KV 由上下文长度决定，与批无关——真正随批变化的是传输事件的聚合方式），再算 <span class=\"formula-inline\">ρ(b)</span>，最后取使 <span class=\"formula-inline\">min(N_p·Th_p, N_d·Th_d(b))/(1+ρ(b))</span> 最大的 b。代价在于这个扫描必须在目标硬件与目标链路上实测，不能从别处搬参数：PCIe 与 NVLink 5 的 <span class=\"formula-inline\">B_net</span> 差一个量级以上，同一 b 在两套链路上算出的 ρ 完全不同。</p>\n<div class=\"formula\">$$\\text{Goodput}=\\min\\left(\\frac{N_p\\cdot \\text{Th}_p}{1+\\rho},\\ \\frac{N_d\\cdot \\text{Th}_d}{1+\\rho}\\right),\\quad \\rho=\\frac{V_{\\text{KV}}}{B_{\\text{net}}\\cdot \\text{Th}_d}$$</div>\n<p>举例：某部署在 NVLink 域内做 KV 传输，<span class=\"formula-inline\">B_net</span> 充裕使 ρ 远小于 1，此时批大小可以放心放大以压低权重读取摊销，因为放大带来的 <span class=\"formula-inline\">Th_d</span> 下降被 1+ρ≈1 的因子稀释得无关紧要；一旦把同一部署改成跨机架传输，<span class=\"formula-inline\">B_net</span> 骤降使 ρ 抬升，原先「大批更优」的结论反转——大批意味着单次传输的 KV 块更大、传输时间在周期中占比更高，goodput 断崖式下跌。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-24\">二十四 · 定并行度：N_p 与 N_d 的比值由 Th 比值决定，而非由卡数决定</h3>\n<p>并行度决策的核心是 <span class=\"formula-inline\">N_p/N_d = Th_d/Th_p</span> 这一平衡条件（由两侧乘积相等解出）。注意这个比值与总卡数无关：总卡数只决定规模，比值决定结构。工程上先定比值、再按预算放大，比先分卡再调比值稳健得多。具体机制上，<span class=\"formula-inline\">Th_p</span> 与 <span class=\"formula-inline\">Th_d</span> 的比值受模型结构影响极大——MoE 模型解码时专家并行带来的 All-to-All 会显著压低 <span class=\"formula-inline\">Th_d</span>，使平衡点偏向更多解码实例；而长上下文预填的 <span class=\"formula-inline\">Th_p</span> 因注意力计算占比高而相对稳定。</p>\n<p>代价维度：并行度失衡的代价在功耗与机架预算上体现得最直接。NVL72 机架的供电与散热是按满配设计的，若配比失衡导致一侧长期低占用，机架的每瓦 goodput 下降，这在容量规划里等价于为闲置容量付电费。举例：某 GB200 NVL72 部署中，实测 <span class=\"formula-inline\">Th_p</span> 约为 <span class=\"formula-inline\">Th_d</span> 的三倍，则平衡比值 <span class=\"formula-inline\">N_p:N_d = 1:3</span>；若按 1:1 部署，解码侧成为瓶颈，预填侧三分之二的算力闲置，goodput 只有平衡配比下的约三分之一水平（按 min 项直接读出）。这个判断不需要任何实验数字，min 结构本身就给出比例关系。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-25\">二十五 · 定 KV 预算：ρ 是预算约束，不是事后指标</h3>\n<p>KV 预算通常被当成显存容量问题单独处理，但在分离式部署里它同时是带宽预算问题。<span class=\"formula-inline\">ρ</span> 的定义把 KV 字节数与网络带宽、解码吞吐绑在一起，意味着「能放下多少 KV」与「能搬动多少 KV」是两个不同的上限，后者往往先到。具体机制：每请求周期内，解码实例必须先收到该请求新增的 KV 块才能继续解码，传输与解码串行叠加成 1+ρ 的放大因子；因此 KV 预算的正确形式是给定 <span class=\"formula-inline\">B_net</span> 与目标 <span class=\"formula-inline\">Th_d</span> 下允许的 <span class=\"formula-inline\">V_KV</span> 上限，即 <span class=\"formula-inline\">V_KV ≤ ρ_target·B_net·Th_d</span>。</p>\n<p>这条约束直接决定上下文长度上限与并发上限的取舍：<span class=\"formula-inline\">V_KV</span> 随上下文长度线性增长，在 <span class=\"formula-inline\">B_net</span> 固定时，支持更长上下文就必须接受更小的 <span class=\"formula-inline\">Th_d</span> 或更低的 ρ 目标，二者不可兼得。代价上，KV 传输走 PCIe 时 <span class=\"formula-inline\">B_net</span> 成为硬天花板，此时无论怎么扩实例数，goodput 都被纯网络带宽锁死——这正是失效条件里「min 模型退化为纯网络带宽约束」的含义。举例：一个跨机架部署的请求平均上下文翻倍，<span class=\"formula-inline\">V_KV</span> 翻倍使 ρ 翻倍，若原 ρ 已接近 1，则 1+ρ 从约 2 抬到约 3，两侧有效吞吐同比例缩水，此时正确的动作不是加实例而是把 KV 传输迁回 NVLink 域或压缩 KV 精度。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-26\">二十六 · 定 SLO：把延迟目标翻译成 ρ 的上界</h3>\n<p>SLO 决策与 goodput 决策在分离式架构下是同一个问题的两面。每请求周期的实际时长约为解码计算时间乘以 1+ρ，若 SLO 给出每 token 延迟上限，则 ρ 有明确上界：<span class=\"formula-inline\">ρ ≤ L_slo/L_decode − 1</span>，其中 <span class=\"formula-inline\">L_decode</span> 是无传输时的解码周期。这个不等式把 SLO 从「结果指标」变成「设计约束」：它告诉你网络链路的选择不是性能优化项而是 SLO 可行性的前提。</p>\n<p>具体机制上，SLO 达标率（goodput 的另一半含义）取决于 ρ 的稳定性而非均值。请求长度分布剧变时 <span class=\"formula-inline\">V_KV</span> 突增，ρ 瞬时抬升，静态配比下解码侧被传输拖死，达标率断崖下跌——这正是失效条件里「静态 N_p/N_d 配比失效」的机制。对策是按 DistServe/Splitwise 式弹性配比动态调整 <span class=\"formula-inline\">N_p/N_d</span>，把实例从预填侧临时划给解码侧以吸收 ρ 的抬升。代价是弹性调整本身有冷启动与状态迁移开销，调整频率过高会引入抖动，因此工程上通常设 ρ 的监控阈值触发而非连续调整。</p>\n<p>算例：设某部署 <span class=\"formula-inline\">N_p=4</span>、<span class=\"formula-inline\">N_d=8</span>，实测 <span class=\"formula-inline\">Th_p</span> 与 <span class=\"formula-inline\">Th_d</span> 使 <span class=\"formula-inline\">N_p·Th_p = N_d·Th_d</span>，配比平衡。此时若长请求比例上升使 ρ 从远小于 1 抬到接近 1，1+ρ 放大约一倍，goodput 减半，SLO 达标率下滑。决策路径：先查 min 项确认瓶颈不在某一侧（两侧相等），再查 ρ 确认瓶颈在传输——此时扩任何一侧实例都无效，唯一有效动作是降 <span class=\"formula-inline\">V_KV</span>（压缩 KV 或截断上下文）或升 <span class=\"formula-inline\">B_net</span>（迁链路）。若 ρ 抬升但尚未接近 1，则按弹性配比把预填实例临时转为解码实例，用 <span class=\"formula-inline\">N_d</span> 的增加抵消 <span class=\"formula-inline\">Th_d</span> 的有效下降。整个决策链条只依赖 min 项与 ρ 两个观测量，不需要重新拟合任何模型。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-27\">二十七 · 把 min 公式落到旋钮上：批、并行度、KV 预算与 SLO 的反向求解</h3>\n<p>这个公式在容量决策里的真正用法不是“算出一个数”，而是把它当作一组约束的联立求解器：给定 SLO 要求的每请求周期上限 $T_{\\text{SLO}}$，先由 $\\rho$ 判断瓶颈侧，再把 $N_p$、$N_d$、批大小、KV 预算四类旋钮按“先修短板、再谈扩容”的顺序定下来。关键是把 $\\rho$ 从“常数”还原成批大小的函数——$\\text{Th}_d$ 随解码批增大而上升，但单请求 KV 传输量 $V_{\\text{KV}}$ 不随批缩小，于是 $\\rho=V_{\\text{KV}}/(B_{\\text{net}}\\cdot\\text{Th}_d)$ 随批增大而下降；这意味着**扩解码批本身就是在降 $\\rho$**，而盲目加解码实例数只是把同样的 $\\rho$ 复制到更多卡上。定批大小的正确顺序是：先按显存约束（权重 + KV 池 + 激活）取解码批的上界 $b_{\\max}$，再在该批下算 $\\rho(b)$，若 $\\rho$ 仍接近 1，说明瓶颈不在算力而在链路，加批无效，必须换链路或改拓扑。并行度则反过来定：预填侧按 $\\text{Th}_p$ 与 $\\rho$ 的相对大小决定是否值得做 TP 扩张，解码侧按 $\\min$ 项定位——若 $\\min$ 恒落在 $N_d\\text{Th}_d$，扩预填是纯浪费。</p>\n<p>KV 预算的定法与前文“按 token 数配池”的角度不同：这里要把 KV 池当作**传输缓冲**来定，而不是当作容量来定。分离式部署中，预填侧产出的 KV 必须先落到可被解码侧拉取的缓冲区，缓冲深度 $D$ 需满足 $D\\ge \\text{Th}_d\\cdot(1+\\rho)\\cdot\\tau_{\\text{jitter}}$，其中 $\\tau_{\\text{jitter}}$ 是两侧调度错拍与链路抖动的合并时延；$D$ 不足时解码侧会因等 KV 而空转，等效于把 $\\rho$ 人为抬高。反过来，$D$ 过大则挤占解码侧 KV 池、压低 $b_{\\max}$，把 $\\text{Th}_d$ 拉低、又把 $\\rho$ 推高——这是一个正反馈式的失效螺旋，也是“KV 预算给多了反而更慢”的机制来源。SLO 的反向求解则直接对 $T_{\\text{SLO}}$ 做不等式：每请求周期为 $\\frac{1}{\\text{Th}_d}(1+\\rho)$（解码侧口径），要求 $\\frac{1}{\\text{Th}_d}(1+\\rho)\\le T_{\\text{SLO}}$，解出 $\\text{Th}_d\\ge \\frac{1+\\rho}{T_{\\text{SLO}}}$，再折算成批与实例数；若该不等式在 $b_{\\max}$ 下无解，结论是 SLO 在当前链路上不可达，而不是“再加机器”。</p>\n<div class=\"formula\">$$\\text{可行域：}\\ \\frac{1+\\rho(b)}{T_{\\text{SLO}}}\\le \\text{Th}_d(b)\\le \\text{Th}_d(b_{\\max}),\\quad b_{\\max}=\\left\\lfloor\\frac{M_{\\text{free}}-D\\cdot s_{\\text{KV}}}{s_{\\text{KV}}\\cdot L}\\right\\rfloor$$</div>\n<p>算例：某分离式部署，预填侧 4 实例、解码侧 6 实例，单预填实例吞吐与单解码实例吞吐取相同量级，链路可用带宽为 $B_{\\text{net}}$，单请求 KV 为 $V_{\\text{KV}}$。当解码批取小值时 $\\text{Th}_d$ 低，$\\rho$ 抬升，$\\min$ 项落在解码侧，此时把预填从 4 扩到 8 完全无收益——预填侧变成空闲瓶颈的反面：预填产能过剩而解码被传输拖住。把解码批提到 $b_{\\max}$ 后 $\\text{Th}_d$ 上升、$\\rho$ 下降，$\\min$ 项切换到预填侧，此时才轮到扩预填；若再扩预填仍不见 goodput 上升，说明 $\\rho$ 已接近 1，模型退化为纯带宽约束，唯一有效动作是换链路（NVLink 域内替代 PCIe 或跨机架路径）或压缩 $V_{\\text{KV}}$（更低比特 KV、按头分组传输），而不是继续堆实例。</p>\n<table class=\"mini\"><thead><tr><th>观测信号</th><th>判定</th><th>动作</th></tr></thead><tbody><tr><td>$\\min$ 恒落解码侧，扩预填无增益</td><td>解码侧 $\\text{Th}_d$ 受限</td><td>提解码批至 $b_{\\max}$，再评估 $\\rho$</td></tr><tr><td>$\\rho\\to1$，加实例 goodput 不涨</td><td>退化为带宽约束</td><td>换链路或压 $V_{\\text{KV}}$，停扩实例</td></tr><tr><td>长请求比例上升后 goodput 断崖</td><td>静态 $N_p/N_d$ 失效</td><td>弹性配比（DistServe/Splitwise 式）动态调度</td></tr><tr><td>解码侧等 KV 空转、缓冲见底</td><td>$D$ 不足，等效 $\\rho$ 抬高</td><td>加缓冲深度，同时复核 $b_{\\max}$ 未被挤占</td></tr></tbody></table>\n<p>边界与代价必须写清：该 min 模型成立的前提是 $\\rho\\ll1$ 且两侧配比接近，此时 $1+\\rho$ 只是一个温和的稀释因子，容量规划可以近似线性外推；一旦 KV 传输走 PCIe 或跨机架网络使 $\\rho$ 接近 1，串行叠加假设本身也开始失真——传输与解码不再是干净的两段，链路争用、重传与调度错拍会把有效 $\\rho$ 推到公式估值之上，此时按 $\\rho\\ll1$ 估算的容量会系统性高估 goodput，SLO 必然失守。系统代价体现在三处：其一，弹性配比需要跨实例的 KV 路由与迁移能力，调度面本身消耗 CPU 与网络控制带宽；其二，为压 $\\rho$ 而做的 KV 压缩会引入数值误差，需与精度策略联动评估；其三，缓冲深度 $D$ 与解码 KV 池共享同一块显存，任何一侧的扩容都在挤压另一侧的 $b_{\\max}$。工程判断因此落在监控上：把 $\\rho$、$\\min$ 项归属、$D$ 水位、长请求占比四个量做成常驻指标，配比调整由指标触发而非由固定模板决定；只扩预填而不检查 $\\text{Th}_d$ 是否随批膨胀下降，是这套方案最常见的无效投入。</p>\n<h3 id=\"th-pd-disagg-goodput-sec-28\">二十八 · 误用的共同形状：把 min 当成加法，把 ρ 当成常数</h3>\n<p>分离式 P/D 的 goodput 模型只有两个自由度——配比 $N_p/N_d$ 与传输占比 $\\rho$——但工程现场绝大多数翻车都来自同一个动作：把这两个量当成部署时一次性确定、之后不再变化的静态参数。$\\min$ 项在数学上取短板，在运维上却意味着“另一侧的资源在空转”，空转不会报警，只会安静地吃掉预算。误用的典型形态是：容量规划时按一段短请求、低并发的基准流量测出 $\\rho\\ll1$，据此选定 $N_p/N_d$ 并写进部署模板；上线后请求长度分布漂移，$\\rho$ 抬升，$1+\\rho$ 放大因子把两侧有效吞吐同时稀释，而 $\\min$ 项落点从预填侧跳到解码侧，原先“够用”的配比瞬间变成一侧排队、一侧闲置。识别这类误用的第一个信号不是吞吐曲线，而是两侧实例的 SM 利用率出现持续分化：一侧接近饱和、另一侧长期低于某个阈值，且分化程度随平均输入长度单调加剧。</p>\n<p>第二个共同形状是把 $\\rho$ 里的 $\\text{Th}_d$ 当作常量。$\\rho=V_{\\text{KV}}/(B_{\\text{net}}\\cdot\\text{Th}_d)$ 中，$\\text{Th}_d$ 是解码实例在<b>当前批大小</b>下的吞吐，而连续批处理会让 $\\text{Th}_d$ 随批膨胀而下降（解码阶段从计算受限滑向带宽受限），于是同一个 $V_{\\text{KV}}$ 与 $B_{\\text{net}}$ 下，$\\rho$ 会随负载自己长大。用基准点的 $\\rho$ 去推高负载点的容量，等于用一个偏小的放大因子估算需求，误差方向永远是乐观的。工程上应把 $\\rho$ 当作负载的函数而非硬件的常数，在容量表里按批大小分档给出 $\\rho$，而不是给一个标量。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-29\">二十九 · 反例：固定配比 + PCIe 传输的长上下文突增</h3>\n<p>构造一个不依赖具体数字的反例。某部署把预填与解码拆到不同实例组，KV 缓存经 PCIe 链路从预填侧搬到解码侧，基准流量为短请求、中等并发，实测 $\\rho$ 远小于 1，两侧配比按 $\\min$ 平衡点选定，SLO 达标。随后业务侧长上下文请求比例上升：单请求 $V_{\\text{KV}}$ 随上下文长度线性增长，而 $B_{\\text{net}}$ 在 PCIe 上是固定的，$\\rho$ 被推高到接近 1 的量级。此时模型退化为纯网络带宽约束——每请求周期里传输时间与解码计算时间同量级，$1+\\rho$ 把两侧有效吞吐放大近一倍来稀释，$\\min$ 项不再由任何一侧的计算能力决定，而由链路带宽决定。后果是双重的：解码实例因为等 KV 而空转，预填实例因为下游搬不动而背压，增加任何一侧的实例数都不提升 goodput，因为瓶颈既不在 $N_p\\cdot\\text{Th}_p$ 也不在 $N_d\\cdot\\text{Th}_d$。这就是“按 $\\rho\\ll1$ 估算容量、却把 KV 放在 PCIe 或跨机架链路上”的典型代价：扩容投入全部打水漂，SLO 无法满足，而监控面板上两侧利用率都不高，极易被误判为“负载不够”。</p>\n<p>识别这个反例有三个可操作判据。其一，看 goodput 对实例数的偏导：分别单独增加 $N_p$ 与 $N_d$，若两者都不带来 goodput 提升，说明瓶颈已不在计算侧，而在 $\\rho$ 项，此时应查链路而非加机器。其二，看解码侧每请求周期的等待时间占比：若 KV 到达间隔与解码计算时间同量级，$\\rho$ 已接近 1。其三，看 $\\rho$ 随平均输入长度的斜率：斜率显著为正且无饱和迹象，说明静态配比正在失效。三者中任意一条成立，就应触发 DistServe/Splitwise 式的弹性配比，而不是继续按固定 $N_p/N_d$ 扩容。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-30\">三十 · 只扩预填：min 项始终落在解码侧的扩容陷阱</h3>\n<p>另一类误用不涉及传输，纯属配比误判：观察到预填侧排队，就扩 $N_p$，却不检查解码侧 $\\text{Th}_d$ 是否随批膨胀而下降。由于 $\\min$ 取短板，若解码侧总吞吐 $N_d\\cdot\\text{Th}_d$ 已经低于预填侧，扩 $N_p$ 只会让预填侧更闲，goodput 纹丝不动。更隐蔽的是，解码侧批增大后 $\\text{Th}_d$ 下降，$N_d\\cdot\\text{Th}_d$ 可能不升反降，于是扩容预填反而让 $\\min$ 项更低。识别方法很直接：在扩容前后各测一次两侧的“实例数×单实例吞吐”，若扩容侧的乘积未成为新的 $\\min$ 项，这次扩容就是无效投入。工程判断应固化为一条规则——每次扩容前先算两侧乘积，只扩当前 $\\min$ 项所在的一侧；若 $\\min$ 项落在解码侧而解码侧 $\\text{Th}_d$ 正在随批下降，正确动作是调批上限或增加 $N_d$，而非加预填。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-31\">三十一 · 请求长度分布剧变时静态配比的失效判据</h3>\n<p>静态 $N_p/N_d$ 配比的有效前提是请求长度分布稳定，因为 $V_{\\text{KV}}$ 与预填计算量都随长度变化，而两者变化速率不同：预填计算量随长度超线性增长，$V_{\\text{KV}}$ 随长度线性增长，于是长请求比例上升会同时抬高预填侧负载与 $\\rho$，但抬高的比例不同，原配比不可能同时平衡两侧。失效判据可以写成一条监控规则：以滑动窗口统计输入长度的分位数，当高分位长度对应的 $\\rho$ 估计值越过设定阈值，且两侧利用率分化持续超过若干调度周期，即判定静态配比失效。此时应切换到按队列深度与 $\\rho$ 实时重算配比的弹性调度，而不是在固定配比下调整批大小来“凑”。弹性配比的代价是调度器需要跨实例组协调，带来额外的控制面延迟与迁移开销，这笔开销必须计入容量表，否则会出现“配比调对了但切换太慢”的新瓶颈。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-32\">三十二 · 误用的代价账：延迟、吞吐、显存、带宽、功耗各落在哪</h3>\n<p>把误用按资源维度拆开，才能在设计评审时逐项对照。延迟侧：$\\rho$ 被低估时，每请求周期的传输等待直接叠加到 TTFT 与 TPOT 上，且等待不随批增大而摊薄，属于硬性串行开销。吞吐侧：$\\min$ 项落错侧时，扩容不产生 goodput，投入产出比为零；$\\rho$ 接近 1 时模型退化为带宽约束，增加实例数不再提升 goodput。显存侧：长请求突增使 $V_{\\text{KV}}$ 暴涨，解码侧为缓冲在途 KV 需要预留更大显存池，若按短请求基准配置，会出现 KV 池打满导致的抢占与重算，重算又反过来加重预填侧负载。带宽侧：PCIe 或跨机架链路上的 KV 传输与模型权重加载、集合通信共享链路，$\\rho$ 上升时这些流量互相挤压，形成非线性劣化。功耗侧：一侧空转并不省电——空转实例仍持有显存与时钟，能效比随利用率分化而恶化，这是固定配比部署在长上下文场景下单位 token 能耗上升的直接原因。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>直接后果</th><th>识别信号</th><th>正确动作</th></tr></thead><tbody><tr><td>$\\rho$ 当常数、固定配比</td><td>$\\min$ 落点漂移，一侧空转</td><td>两侧利用率持续分化且随长度加剧</td><td>按批大小分档估 $\\rho$，弹性配比</td></tr><tr><td>KV 走 PCIe/跨机架仍按 $\\rho\\ll1$ 估容量</td><td>模型退化为带宽约束，扩容无效</td><td>增 $N_p$、$N_d$ 均不提升 goodput</td><td>改链路或重划拓扑，先解 $\\rho$</td></tr><tr><td>只扩预填不查 $\\text{Th}_d$</td><td>$\\min$ 始终在解码侧，投入无收益</td><td>扩容侧乘积未成为新 $\\min$ 项</td><td>扩解码或调批上限</td></tr></tbody></table>\n<p>这张表的使用方式是反向的：先在监控上找信号，再由信号定位误用类型，最后才动容量。反过来做——先扩容再看效果——正是本部分所有反例的共同起点。工程判断应落在一条硬规则上：任何一次扩容决策，必须先给出当前 $\\rho$ 的估计值与两侧“实例数×单实例吞吐”的乘积，两者缺一不可；缺 $\\rho$ 的扩容是在赌传输不是瓶颈，缺乘积的扩容是在赌自己扩对了边。分离式 P/D 的 goodput 从来不是被算错的，而是被“部署时算一次、之后不再算”这件事拖垮的。</p>\n\n<h3 id=\"th-pd-disagg-goodput-sec-33\">三十三 · 把 ρ 当常数：分离式 P/D 最贵的那个误用</h3>\n<p>在容量评审里最常见的一幕，是把 <span class=\"sym\">ρ</span> 当成一个部署时算一次就冻结的常数：拿某个基准负载下的 <span class=\"sym\">V_KV</span> 与 <span class=\"sym\">B_net</span> 估出一个漂亮的小数值，写进配比表，然后按 <span class=\"sym\">N_p/N_d</span> 固定铺机器。问题在于 <span class=\"sym\">ρ</span> 的定义里藏着 <span class=\"sym\">Th_d</span>，而解码实例的单实例吞吐本身随批大小漂移——连续批处理把批堆大时，每 token 的注意力与 KV 读取摊薄，<span class=\"sym\">Th_d</span> 上升，<span class=\"sym\">ρ</span> 反而下降；一旦 SLO 收紧、批被压小，<span class=\"sym\">Th_d</span> 掉下来，<span class=\"sym\">ρ</span> 立刻抬升。于是同一个 <span class=\"sym\">N_p/N_d</span> 在两种运行点上对应两个完全不同的放大因子 <span class=\"sym\">1+ρ</span>，而配比表对此一无所知。识别方法很直接：在监控里把 <span class=\"sym\">ρ</span> 作为一阶指标与批大小、P99 首 token 延迟同屏绘制，若 <span class=\"sym\">ρ</span> 的方差与批大小强相关而配比从未调整，这套部署就是按错误的常数在跑。</p>\n<p>第二个误用是把 KV 传输路径当成“反正带宽够”的透明层。当预填与解码跨 PCIe 或跨机架放置时，<span class=\"sym\">B_net</span> 不再是 NVLink 域内的数字，<span class=\"sym\">ρ</span> 会逼近 1，此时 min 模型退化为纯网络带宽约束：<span class=\"formula\">$$\\text{Goodput}\\approx\\frac{B_{\\text{net}}}{V_{\\text{KV}}}\\ \\text{（当 }\\rho\\gg1\\text{）}$$</span>增加任何一侧的实例数都不再提升 goodput，因为瓶颈已经不在计算侧。代价是双重的：解码实例在等 KV 到位时空转，占着显存与功耗却不产出 token；预填侧则因下游排空而被迫降速。工程判断的落点是先测 <span class=\"sym\">ρ</span> 再谈扩容——若 <span class=\"sym\">ρ</span> 已接近 1，正确动作是把这对 P/D 实例拉回同一 NVLink 域，或改用分层 KV 缓存把热数据留在解码侧，而不是继续加机器。</p>\n<p>第三个误用是只扩预填。团队看到预填排队便加 <span class=\"sym\">N_p</span>，却不去检查 min 项落在哪一侧。若解码侧 <span class=\"sym\">Th_d</span> 因批膨胀或 KV 传输挤占而下降，<span class=\"sym\">N_d·Th_d</span> 始终是短板，新增预填实例只是把更多 KV 更快地推给一个已经饱和的下游，goodput 曲线走平甚至回退。识别信号是：预填侧利用率下降而解码侧队列长度与 KV 等待时间同步上升，同时端到端 goodput 不随 <span class=\"sym\">N_p</span> 增加而变化。下面这张小表把三种误用与其可观测症状对齐，便于在值班面板上直接对照。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>可观测症状</th><th>系统代价</th></tr></thead><tbody><tr><td>ρ 当常数做静态配比</td><td>ρ 方差与批大小强相关，配比长期不变</td><td>长请求突增时解码侧被传输拖死，goodput 断崖</td></tr><tr><td>KV 走 PCIe/跨机架仍按 ρ≪1 估容量</td><td>解码实例空转，KV 等待时间占周期主导</td><td>1+ρ 放大数倍，SLO 无法满足，扩容无收益</td></tr><tr><td>只扩预填不查解码侧 Th_d</td><td>预填利用率降、解码队列涨、goodput 不涨</td><td>资本与功耗投入沉没，min 项始终在解码侧</td></tr></tbody></table>\n<p>给一个反例收束：某部署按固定 <span class=\"sym\">N_p/N_d</span> 铺开且不监控 <span class=\"sym\">ρ</span>，上线初期请求以短上下文为主，<span class=\"sym\">ρ</span> 很小，goodput 表现良好；随后长上下文请求比例上升，<span class=\"sym\">V_KV</span> 暴涨带动 <span class=\"sym\">ρ</span> 抬升，KV 传输占满链路带宽，解码实例大量空转，端到端 goodput 反而低于同构（不分离）部署——分离带来的流水线收益被传输开销吃掉。这个反例的教训不是“分离式不好”，而是分离式的收益严格以 <span class=\"sym\">ρ≪1</span> 且配比跟随负载为边界条件；越过边界，min 模型里的短板从计算侧切换到网络侧，此时唯一有效的动作是弹性配比（DistServe/Splitwise 式动态调整）或改变传输拓扑，而非线性扩容。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>N_p</td><td>预填实例数</td></tr><tr><td>N_d</td><td>解码实例数</td></tr><tr><td>\\text{Th}_p</td><td>单预填实例吞吐</td></tr><tr><td>\\text{Th}_d</td><td>单解码实例吞吐</td></tr><tr><td>\\rho</td><td>KV 传输相对解码时间的占比</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-pd-disagg-goodput · 共 5 个片段</p>\n"},{"id":"th-moe-capacity-drop-bound","title":"MoE 容量因子丢弃率界","direction":"dir-disaggregated-pd","prereq":[],"plain":"容量因子决定每个专家最多接收多少 token；超出容量的 token 会被丢弃并跳过该层计算，其丢弃比例可用二项分布尾概率刻画，容量因子每提高一档，丢弃率下降但专家 GEMM 的 padding 浪费上升，二者在给定路由均值下存在最优折中。","definition":"容量因子决定每个专家最多接收多少 token；超出容量的 token 会被丢弃并跳过该层计算，其丢弃比例可用二项分布尾概率刻画，容量因子每提高一档，丢弃率下降但专家 GEMM 的 padding 浪费上升，二者在给定路由均值下存在最优折中。","formula":"$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr\\Big[X_e > C\\Big],\\quad X_e \\sim \\mathrm{Binomial}\\Big(T,\\ \\tfrac{k}{E}\\Big),\\quad C = \\Big\\lceil \\gamma\\, \\tfrac{kT}{E} \\Big\\rceil$$","variables":[{"sym":"T","meaning":"一个 micro-batch 内进入该 MoE 层的 token 总数"},{"sym":"E","meaning":"该层专家总数"},{"sym":"k","meaning":"每个 token 激活的专家数（top-k）"},{"sym":"γ","meaning":"容量因子，C 相对平均负载 kT/E 的放大倍数"},{"sym":"C","meaning":"每个专家允许接收的最大 token 数（容量）"}],"derivation":"推导的关键一步是把“token 路由到专家 e”近似为概率 k/E 的独立伯努利试验：每个 token 在 E 个专家中选 k 个，均匀路由下任一专家被选中的边际概率恰为 k/E，于是各专家负载服从同一二项分布，丢弃事件即负载超过容量 C。","example":"在推理容量决策中，该界用于把 SLO 的丢弃率预算反解为容量因子：给定 T、E、k 与可容忍丢弃率，选出最小 γ，从而确定每专家 GEMM 的 padding 上界与显存/算力预留，是批大小与专家并行度联合定容的输入参数。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设路由近似均匀且 token 独立同分布；实际路由存在专家坍缩或热点，尾部概率被低估，需用实测路由直方图替换二项分布","容量因子 γ 过大时 padding 到 C 的 GEMM 浪费主导，该界不再反映真实吞吐代价，应改用有效算力利用率模型"],"system_note":"常见误用是只按 γ 调大容量而不核算 padding 代价：γ 过大时每个专家都被 padding 到 C 做分组 GEMM，有效算力利用率被稀释，此时丢弃率界不再反映真实吞吐，应改用有效算力利用率模型评估。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉上，容量因子 γ 是给每个专家预留的“座位数”相对平均负载的放大倍数：γ=1 表示按均值分配，γ>1 才留出应对路由波动的余量；被挤出座位的 token 在该层被直接跳过，只保留残差通路。","公式中 $$X_e \\sim \\mathrm{Binomial}(T, k/E)$$ 把每个专家收到的 token 数建模为 T 次独立试验、单次命中概率 k/E 的二项分布；$$C = \\lceil \\gamma\\, kT/E \\rceil$$ 是硬容量上限，$$\\Pr[X_e > C]$$ 是单个专家溢出的尾概率，对 E 个专家求和得到期望丢弃比例。","推导的关键一步是把“token 路由到专家 e”近似为概率 k/E 的独立伯努利试验：每个 token 在 E 个专家中选 k 个，均匀路由下任一专家被选中的边际概率恰为 k/E，于是各专家负载服从同一二项分布，丢弃事件即负载超过容量 C。","适用边界是路由近似均匀、token 在层内近似独立同分布、micro-batch 规模 T 足够大；失效条件是出现专家坍缩或热点（少数专家承接远超 kT/E 的 token），此时二项尾概率严重低估真实丢弃率，必须用实测路由直方图替换理论分布。","在推理容量决策中，该界用于把 SLO 的丢弃率预算反解为容量因子：给定 T、E、k 与可容忍丢弃率，选出最小 γ，从而确定每专家 GEMM 的 padding 上界与显存/算力预留，是批大小与专家并行度联合定容的输入参数。","常见误用是只按 γ 调大容量而不核算 padding 代价：γ 过大时每个专家都被 padding 到 C 做分组 GEMM，有效算力利用率被稀释，此时丢弃率界不再反映真实吞吐，应改用有效算力利用率模型评估。","另一常见误用是在小 T（如解码阶段单 token 或极小 micro-batch）下套用该二项界：T 小时尾概率对离散性极敏感，γ 的微小变化会引起丢弃率跳变，且路由热点被均值掩盖，界失去预测力。"],"anchors":[],"pitfalls":["把均匀路由假设直接用于线上流量：真实请求的领域分布导致专家热点，实测丢弃率可比二项界高一个数量级，按理论 γ 定容会造成 SLO 违约。","只优化丢弃率而忽略 padding：为压低丢弃把 γ 提到 2 以上，分组 GEMM 的有效算力利用率骤降，吞吐反而低于适度丢弃加小 γ 的配置。","在解码期小 micro-batch 上沿用预填阶段标定的 γ：T 变小后二项尾概率行为改变，同一 γ 的丢弃率与预填阶段差异很大，造成容量规划失真。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-1\">一 · 一句话直觉与它真正回答的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-2\">二 · 严格定义：从路由到容量的三段式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-3\">三 · 为什么需要这个界：定容而不是调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-4\">四 · 常见误解之一：把均匀路由假设直接用于线上流量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-5\">五 · 常见误解之二：只优化丢弃率而忽略 padding</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-6\">六 · 常见误解之三：在小 T 上套用二项界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-7\">七 · 容量因子界的适用半径：均匀假设、padding 代价与小 T 的离散陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-8\">八 · 逐项拆解：T、E、k、γ、C 各自在系统里对应什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-9\">九 · 推导关键步：从「选 k 个专家」到二项分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-10\">十 · 离散化与近似发生在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-11\">十一 · 反解与代价核算：把丢弃率预算换成 γ</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-12\">十二 · 失效条件的数学表述与替换方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-13\">十三 · 二项界的三处失真：均匀性、离散性与 padding 反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-14\">十四 · 均匀路由假设的工程含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-15\">十五 · 独立性假设在批内如何失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-16\">十六 · 专家坍缩与热点：何时必须换分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-17\">十七 · γ 过大时界不再刻画吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-18\">十八 · 小 T 下界的预测力丧失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-19\">十九 · 适用边界的判定清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-20\">二十 · 边界之外：二项界在什么路由分布与批尺度上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-21\">二十一 · 从丢弃率预算反解 γ：容量决策的第一条链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-22\">二十二 · 定批大小：T 是容量决策的自变量而非结果</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-23\">二十三 · 定并行度：专家切分与副本数受 C 约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-24\">二十四 · 定 KV 预算：丢弃率与 KV 争抢同一块显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-25\">二十五 · 定 SLO：把端到端指标拆到层内丢弃预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-26\">二十六 · 算例：一次完整的容量反解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-27\">二十七 · 容量因子在批大小、并行度、KV 预算与 SLO 上的反解用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-28\">二十八 · 误用一：把均匀路由的二项界直接套到线上流量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-29\">二十九 · 误用二：只压丢弃率、不核算 padding 代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-30\">三十 · 误用三：解码期小 micro-batch 沿用预填阶段标定的 γ</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-31\">三十一 · 一个反例：热点领域流量下的定容全过程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-32\">三十二 · 识别清单与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-capacity-drop-bound-sec-33\">三十三 · 误用与反例：当二项尾界脱离路由现实</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：容量因子决定每个专家最多接收多少 token；超出容量的 toke…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\Pr[\\text{drop}] \\approx \\sum_{…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设路由近似均匀且 token 独立同分布；实际路由存在专家坍缩或…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-moe-capacity-drop-bound-sec-1\">一 · 一句话直觉与它真正回答的问题</h3>\n<p>容量因子 γ 是给每个专家预留的“座位数”相对平均负载的放大倍数：γ=1 表示严格按均值分配座位，γ&gt;1 才留出应对路由波动的余量；被挤出座位的 token 在该层被直接跳过，只保留残差通路。这句话的重点不在“丢弃”这个动作，而在“预留多少座位”这个决策——它同时决定了丢弃率和 GEMM 的 padding 浪费，是一枚硬币的两面。</p>\n<p>需要强调的是，这个界回答的不是“这一层会不会丢 token”，而是“给定 T、E、k 与可容忍丢弃率，最小的 γ 是多少”。它把 SLO 的丢弃率预算反解成容量因子，进而确定每专家 GEMM 的 padding 上界与显存/算力预留，是批大小与专家并行度联合定容的输入参数。在 Blackwell 上这一点尤其要紧：tcgen05 的分组 GEMM 按 C 对齐 tile，C 一旦定下，TMEM 占用与 2-SM MMA 的配对方式随之锁定，γ 不是运行时可随手调的旋钮，而是编译期与调度器共同约定的契约。</p>\n<p>代价侧要立刻说清楚：γ 每提高一档，丢弃率下降，但每个专家都被 padding 到 C 做分组 GEMM，有效算力利用率被稀释。在 B200 这类以 tensor core 吞吐为绝对主轴的器件上，padding 浪费直接体现为 SM 占用时间与功耗的上升，而不是“多花一点显存”这么轻的代价。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-2\">二 · 严格定义：从路由到容量的三段式</h3>\n<p>设一个 micro-batch 内进入该 MoE 层的 token 总数为 T，该层专家总数为 E，每个 token 激活的专家数为 k（top-k），容量因子为 γ，则每个专家允许接收的最大 token 数为：</p>\n<div class=\"formula\">$$C = \\Big\\lceil \\gamma\\, \\tfrac{kT}{E} \\Big\\rceil$$</div>\n<p>丢弃比例的期望由各专家溢出尾概率求和给出：</p>\n<div class=\"formula\">$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr\\Big[X_e &gt; C\\Big],\\quad X_e \\sim \\mathrm{Binomial}\\Big(T,\\ \\tfrac{k}{E}\\Big)$$</div>\n<p>推导的关键一步是把“token 路由到专家 e”近似为概率 k/E 的独立伯努利试验：每个 token 在 E 个专家中选 k 个，均匀路由下任一专家被选中的边际概率恰为 k/E，于是各专家负载服从同一二项分布，丢弃事件即负载超过容量 C。注意这里的“独立”是对 token 之间而言，不是对同一 token 的 k 个选择而言——后者在 top-k 内部是互斥的，但因为求和只关心边际，互斥性被吸收进了 k/E 这个概率里。</p>\n<p>定义里有一个容易被忽略的细节：C 是硬上限，不是软目标。分组 GEMM 的 tile 划分以 C 为上界，padding 到 C 是常态而非例外，因此 C 的取值直接决定该层在 Blackwell 上消耗多少个 MMA 周期。工程上把 γ 定义为“放大倍数”而非“绝对座位数”，正是为了让 C 随 T 与 k/E 自动缩放，避免在小 batch 与大 batch 之间反复重编译 kernel。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-3\">三 · 为什么需要这个界：定容而不是调参</h3>\n<p>MoE 推理的容量决策有三个耦合的自由度：批大小（决定 T）、专家并行度（决定 E 在设备间的切分）、以及每专家的容量 C。三者中任意两个固定，第三个就被 SLO 约束反解出来。丢弃率界的作用是把“可容忍丢弃率”这一业务语言翻译成 C 的数值上界，从而让批调度器与专家并行布局有确定的输入。</p>\n<p>具体机制上，推理系统在预填阶段面对的是大 T，二项分布的尾部相对集中，γ 的微小调整对丢弃率影响平缓；而在解码阶段 T 可能小到个位数，尾概率对离散性极敏感，γ 的微小变化会引起丢弃率跳变。这正是为什么容量因子必须在预填与解码两个阶段分别标定，而不能用一套 γ 贯穿始终——用预填阶段标定的 γ 去跑解码，容量规划会系统性失真。</p>\n<p>系统代价的具体例子：假设某层 E 较大、k 较小，kT/E 的均值负载不高，但路由热点使少数专家的实际负载远超均值。若按二项界选一个较小的 γ，实测丢弃率可比理论值高一个数量级，直接造成 SLO 违约；若为保险把 γ 提到 2 以上，分组 GEMM 的有效算力利用率骤降，吞吐反而低于“适度丢弃 + 小 γ”的配置。这个界的价值就在于把这两种失败模式都摆到台面上，让定容成为一次显式的折中，而不是靠调参试出来的经验值。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-4\">四 · 常见误解之一：把均匀路由假设直接用于线上流量</h3>\n<p>二项界成立的前提是路由近似均匀、token 在层内近似独立同分布、micro-batch 规模 T 足够大。真实请求的领域分布会导致专家热点——某些专家承接远超 kT/E 的 token，此时二项尾概率严重低估真实丢弃率。这不是“界不够精确”的小问题，而是假设被违反后的定性失效：尾概率的量级都可能错。</p>\n<p>正确的做法是用实测路由直方图替换理论分布。工程上在 profiler 里挂一个按层、按专家的 token 计数直方图，把每个专家的经验分布代入求和式，得到经验丢弃率界；再与二项界对比，两者的比值就是该层路由不均匀度的度量。这个比值本身可以作为监控指标：一旦某层的比值持续偏离 1，说明流量分布漂移，原先标定的 γ 需要重算。</p>\n<p>代价侧：维护直方图本身有开销，按层按专家计数在 NVL72 这种规模上会引入可观的元数据流量，通常只在标定窗口内开启，稳态运行时用抽样替代。这是“界要跟真实路由对齐”必须付出的工程成本。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-5\">五 · 常见误解之二：只优化丢弃率而忽略 padding</h3>\n<p>第二个误用是只按 γ 调大容量而不核算 padding 代价。γ 过大时每个专家都被 padding 到 C 做分组 GEMM，有效算力利用率被稀释，此时丢弃率界不再反映真实吞吐代价，应改用有效算力利用率模型评估。换句话说，丢弃率界是一个“约束边界”，不是“目标函数”——把丢弃率压到零并不等于系统变快。</p>\n<p>在 Blackwell 上这个代价有具体的物理形态：分组 GEMM 的 tile 以 C 为上界对齐，C 越大，每个专家消耗的 MMA 周期越多，2-SM MMA 的配对利用率越难做满，TMEM 的驻留压力也越大。当 γ 被推到 2 以上时，padding 浪费主导了吞吐，丢弃率界给出的“丢弃率下降”已经不能解释端到端表现。</p>\n<p>工程判断上，正确的做法是把丢弃率界与有效算力利用率模型并列使用：前者给出 γ 的下界（满足 SLO 的最小容量），后者给出 γ 的上界（padding 浪费可接受的最大容量），两者夹出的区间才是可选的 γ 范围。若区间为空，说明该层的 E、k 与 SLO 组合本身不可行，需要调整专家并行度或批大小，而不是继续在 γ 上做文章。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-6\">六 · 常见误解之三：在小 T 上套用二项界</h3>\n<p>第三个误用是在小 T（如解码阶段单 token 或极小 micro-batch）下套用该二项界。T 小时尾概率对离散性极敏感，γ 的微小变化会引起丢弃率跳变，且路由热点被均值掩盖，界失去预测力。此时二项分布的连续性近似不再成立，C 的取整（向上取整到整数座位）本身就会带来可观的相对误差。</p>\n<p>具体机制：当 kT/E 小于 1 时，C 在 γ=1 附近可能取到 1 或 2，两个取值对应的丢弃率差异是阶跃式的，而不是平滑的。解码阶段的批调度器如果按预填阶段的 γ 定容，会遇到“同一 γ 下丢弃率与预填阶段差异很大”的现象，容量规划随之失真。工程上的应对是把解码阶段的容量决策改为按实测直方图逐 micro-batch 校准，或者干脆在解码期采用更宽松的 γ 并接受少量 padding，用确定性换掉尾概率的不可预测性。</p>\n<p>这一条与第一条的区别在于：第一条是路由分布违反均匀假设，第三条是样本量违反大 T 假设。两者都会让界失效，但诊断路径不同——前者看直方图与二项界的比值，后者看 T 与 kT/E 的量级关系。把这两类失效分开识别，才能在定容时选对替换模型：路由不均匀用经验分布，样本量不足用逐批校准或放宽 γ。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-7\">七 · 容量因子界的适用半径：均匀假设、padding 代价与小 T 的离散陷阱</h3>\n\n<p>这个界真正能用的地方，是它把“丢多少 token”从一件只能实测的事，变成一件可以在定容阶段先算出来的事。机制上，它把每个专家收到的 token 数 X_e 建模成 T 次独立伯努利试验的计数，单次命中概率为 k/E——因为每个 token 在 E 个专家中选 k 个，均匀路由下任一专家被选中的边际概率恰为 k/E。于是丢弃事件就是 X_e 越过硬容量 C，期望丢弃比例对 E 个专家求和。这一步推导的代价是三条假设同时成立：路由近似均匀、层内 token 近似独立同分布、micro-batch 规模 T 足够大。任何一条破了，界就从“预测”退化为“下界”，而且是偏乐观的下界。工程上必须清楚：这个界回答的是“均匀流量下最少要留多少座位”，不是“线上流量下会丢多少”。</p>\n\n<p>失效条件里最致命的是专家坍缩与热点。真实请求的领域分布并不均匀，少数专家承接的 token 数远超 kT/E，二项分布的尾部被系统性低估，实测丢弃率可比理论界高一个数量级——按理论 γ 定容直接换来 SLO 违约。此时的正确做法不是调大 γ 硬扛，而是用实测路由直方图替换理论分布：把每个专家的经验命中概率 p_e 代进去，按 Σ_e Pr[Bin(T, p_e) > C] 重算，容量 C 仍取 ⌈γ·kT/E⌉ 但 γ 要按最热专家而非均值来定。这等于把“全局一个 γ”变成“按热点专家定 γ”，代价是冷门专家的座位被过度预留，padding 浪费上升。另一条失效路径是 γ 过大：每个专家都被 padding 到 C 做分组 GEMM，有效算力利用率被稀释，此时丢弃率界已不反映真实吞吐，必须切换到有效算力利用率模型，用 padding 后的实际 MMA 工作量而非名义 token 数来评估。</p>\n\n<p>小 T 是第三个陷阱，且与推理形态强相关。解码阶段单 token 或极小 micro-batch 下，T 很小，尾概率对离散性极敏感——γ 的微小变化会让丢弃率跳变，路由热点又被均值掩盖，界失去预测力。更隐蔽的失败模式是在预填阶段标定 γ、然后沿用到解码期：T 变小后二项尾概率行为改变，同一 γ 的丢弃率与预填阶段差异很大，容量规划整体失真。工程判断是：该界只在预填或大 micro-batch 的连续批处理场景下作为定容输入，解码期应改用实测直方图或直接以固定 C 加溢出回退策略处理。</p>\n\n<table class=\"mini\"><thead><tr><th>场景</th><th>界是否可信</th><th>系统代价落点</th></tr></thead><tbody><tr><td>均匀路由、大 T 预填</td><td>可信，可反解最小 γ</td><td>显存/算力预留按 C 上界</td></tr><tr><td>领域偏斜、专家热点</td><td>低估丢弃率，需实测直方图</td><td>γ 按最热专家定，冷专家 padding 浪费</td></tr><tr><td>γ 过大（>2）</td><td>不再反映吞吐</td><td>分组 GEMM 有效算力利用率骤降</td></tr><tr><td>解码期小 T</td><td>失去预测力</td><td>丢弃率跳变，预填标定的 γ 失真</td></tr></tbody></table>\n\n<div class=\"formula\">$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr\\Big[X_e &gt; C\\Big],\\quad X_e \\sim \\mathrm{Binomial}\\Big(T,\\ \\tfrac{k}{E}\\Big),\\quad C = \\Big\\lceil \\gamma\\, \\tfrac{kT}{E} \\Big\\rceil$$</div>\n\n<p>把这张表读成定容流程：给定 T、E、k 与 SLO 的丢弃率预算，先用二项界反解最小 γ，得到每专家 GEMM 的 padding 上界与显存/算力预留；再用线上路由直方图校验最热专家的 p_e，若其显著高于 k/E 则按热点重算 γ；最后核算 padding 代价，若 γ 抬升带来的有效算力利用率下降超过丢弃率下降带来的收益，就退回“适度丢弃 + 小 γ”的配置。这条折中的判断依据不是丢弃率本身，而是吞吐——丢弃的 token 只保留残差通路、跳过该层计算，代价是精度；padding 的代价是算力。两者在同一 γ 上此消彼长，最优 γ 落在边际精度损失等于边际算力浪费的那一点。</p>\n<h3 id=\"th-moe-capacity-drop-bound-sec-8\">八 · 逐项拆解：T、E、k、γ、C 各自在系统里对应什么</h3>\n<p>公式里的五个符号不是纯数学记号，每一个都直接映射到推理引擎里可观测、可调的量。T 是一个 micro-batch 内进入该 MoE 层的 token 总数——注意它不等于请求数，也不等于序列长度，而是经过前序层、被调度器实际拼进同一个 forward 的 token 数；连续批处理下 T 随每一步的批组成而抖动，这是后面所有离散性问题的根源。E 是该层专家总数，由模型结构固定，但在专家并行下每个 rank 只持有 E/EP 个本地专家，容量 C 的判定发生在本地分组 GEMM 之前。k 是 top-k 激活数，决定路由的稀疏度，也决定每个 token 对专家负载的贡献份额。γ 是唯一由部署方自由选择的旋钮：C 相对平均负载 kT/E 的放大倍数。C 则是硬容量上限，向上取整后成为分组 GEMM 的 padding 目标长度。</p>\n<p>把 C 写成 <span class=\"formula\">$$C = \\Big\\lceil \\gamma\\, \\tfrac{kT}{E} \\Big\\rceil$$</span> 的意义在于：容量不是一个独立的显存预算，而是由当步 T 动态算出来的。这意味着同一个 γ 在预填的大 T 下给出很大的 C，在解码的小 T 下给出很小的 C，而 ceil 带来的相对误差在小 T 时被放大——kT/E 小于 1 时，ceil 直接把 C 抬到 1，γ 的实际放大倍数远偏离名义值。工程上必须把「名义 γ」和「生效 γ = C·E/(kT)」分开记录，否则容量规划会失真。</p>\n<p>代价侧要同时看两条曲线。丢弃率随 γ 上升而下降，但每个专家的 GEMM 被 padding 到 C 后，实际参与计算的 token 数期望是 kT/E，有效算力利用率为 kT/(E·C) ≈ 1/γ。也就是说 γ 从 1 抬到 2，丢弃率改善的同时，专家 GEMM 的算力有一半花在 padding 行上。在 decode 阶段算力本就吃紧、GEMM 偏 memory-bound 的情况下，padding 浪费主要体现在权重带宽的重复读取上；在 prefill 阶段 T 大、GEMM 偏 compute-bound，padding 直接吃掉 tensor core 的 MAC 吞吐。同一个 γ 在两个阶段的代价结构不同，这是不能跨阶段复用标定值的物理原因。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-9\">九 · 推导关键步：从「选 k 个专家」到二项分布</h3>\n<p>推导的起点是一个组合事实：每个 token 在 E 个专家中选 k 个。均匀路由假设下，任一固定专家 e 被某个 token 选中的边际概率是 k/E——这一步不需要任何近似，它是组合计数的直接结果。真正引入近似的是下一步：把 T 个 token 对专家 e 的选择视为 T 次独立伯努利试验。独立性在真实路由里并不严格成立（同一个 token 的 k 个选择互斥，不同 token 之间又受请求领域相关性影响），但因为关注的是单个专家的边际负载，互斥性只影响联合分布、不影响边际，独立性近似在 T 较大时可以接受。于是</p>\n<div class=\"formula\">$$X_e \\sim \\mathrm{Binomial}\\Big(T,\\ \\tfrac{k}{E}\\Big),\\qquad \\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr\\big[X_e &gt; C\\big]$$</div>\n<p>求和号而不是取单个专家，是因为丢弃是逐专家发生的：任何一个专家溢出，被挤出的那部分 token 就在该层被跳过、只保留残差通路。期望丢弃 token 数等于各专家溢出量之和，除以 kT 得到丢弃比例。注意这里隐含了一个「溢出即丢弃」的硬截断语义——容量满后不再接收，而不是排队或改路由，这正是主流实现的行为，也是该界能与实际系统对上号的前提。</p>\n<p>推导中还有一处容易被忽略的近似：各专家负载被当作同分布。均匀路由下确实同分布，但求和号里 E 个相同的尾概率意味着界对「负载在专家间如何分布」完全不敏感。真实系统里专家负载的方差往往大于二项分布方差（路由有相关性），这正是后面失效条件的数学根源——不是均值错了，是方差被低估，尾概率被系统性压低。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-10\">十 · 离散化与近似发生在哪三处</h3>\n<p>第一处是 ceil。C 必须是整数，而 kT/E 一般不是。ceil 使生效容量系统性偏大，偏差上界小于 1 个 token；当 kT/E 远大于 1 时可忽略，当 T 小到 kT/E 接近或小于 1 时，ceil 的相对偏差可以达到 100%。这就是小 T 下 γ 微调引起丢弃率跳变的直接机制：C 在整数格点上跳，尾概率在离散分布上跳，二者叠加使丢弃率对 γ 呈阶梯状响应，而非平滑曲线。</p>\n<p>第二处是二项分布本身的离散性。X_e 取值在整数上，Pr[X_e > C] 是尾部若干整点的概率和。T 大时可由正态近似给出闭式，尾概率约按 Q((C − kT/E)/√(T·k/E·(1−k/E))) 衰减；但 T 小时正态近似失效，必须直接算二项尾和，且尾部只由少数几个整点贡献，任何参数扰动都会让丢弃率成倍变化。工程判断是：预填阶段可用正态近似做容量反解，解码阶段必须用精确二项尾或直接查表。</p>\n<p>第三处是「均匀路由」这一建模假设本身。它把路由器的输出分布压成一个标量概率 k/E，丢掉了专家亲和性、token 内容相关性、层间路由相关等全部结构。这个近似在负载均衡良好时误差可控，在出现专家坍缩或热点时完全失效——少数专家承接远超 kT/E 的 token，其真实尾概率远高于二项界，实测丢弃率可比理论值高一个数量级。此时唯一正确的做法是用实测路由直方图替换理论分布，把每个专家的命中概率 p_e 单独估计，逐专家算二项或泊松尾概率再求和。</p>\n<p>系统代价上，这三处近似共同决定了容量决策的可信区间。用理论界反解 γ 时，若路由实测方差高于二项方差，反解出的 γ 偏小，线上丢弃率超预算，SLO 违约表现为尾延迟抬升和输出质量下降同时出现；若为保守起见把 γ 抬到 2 以上，分组 GEMM 的有效算力利用率降到 1/γ 量级，吞吐反而低于「适度丢弃 + 小 γ」的配置。这就是该界在容量决策中的真实角色：它是一个快速的一阶估计器，不是最终答案。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-11\">十一 · 反解与代价核算：把丢弃率预算换成 γ</h3>\n<p>容量决策的标准用法是反解：给定 T、E、k 与可容忍丢弃率 ε，求最小 γ 使 Σ_e Pr[X_e > ⌈γkT/E⌉] ≤ ε。由于尾概率随 C 单调下降，这是一维单调搜索，用正态近似可直接给出闭式初值再向上取整校正。得到 γ 后立刻要做两件事：一是确定每专家 GEMM 的 padding 上界 C，据此预留分组 GEMM 的 workspace 与输出缓冲；二是核算有效算力利用率 1/γ，判断在当前阶段的 bound 类型下这个利用率是否可接受。</p>\n<p>举例说明代价结构：某层 E 较大、k 较小，decode 阶段单步 T 很小，kT/E 落在 1 附近。此时 γ=1 给出 C=1，几乎必然有专家溢出，丢弃率高；γ=2 给出 C=2，丢弃率明显下降，但每个专家 GEMM 的有效利用率只有约 1/2，且由于 T 小、GEMM 本身已是 memory-bound，padding 到 2 行并不额外增加权重读取次数，代价主要体现在输出缓冲与后续 combine 的无效行处理上。这说明在小 T 场景下抬 γ 的边际代价比大 T 场景低——与「γ 过大总是坏事」的直觉相反，代价要按阶段的 bound 类型分情况核算。</p>\n<p>反过来，prefill 阶段 T 大、GEMM compute-bound，γ 每提高一档，padding 行按比例吃掉 tensor core 吞吐，此时应优先压低 γ、容忍适度丢弃，或用路由均衡损失在模型侧改善负载分布，而不是在推理侧堆容量。这条判断把容量因子从「推理参数」提升为「训练与推理联合设计变量」，但具体怎么联合不在本部分展开。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-12\">十二 · 失效条件的数学表述与替换方案</h3>\n<p>把失效条件写成可检验的形式：设实测每个专家的命中概率为 p_e（由路由直方图估计），则真实丢弃率界为 Σ_e Pr[Bin(T, p_e) > C]，而二项界用的是 p_e ≡ k/E。两者之差由 p_e 的离散程度决定——当 max p_e / (k/E) 显著大于 1 时，热点专家的尾概率被严重低估。工程上应把「路由偏斜度」作为容量决策的前置检查项：偏斜度低时用理论界快速定容，偏斜度高时切换到实测直方图驱动的逐专家尾概率计算，并把 γ 的选取从「按均值放大」改为「按热点专家的分位数放大」。</p>\n<p>第二个失效条件是 γ 过大导致 padding 主导。此时丢弃率界仍在数学上成立，但它描述的已不是真实吞吐代价——真实瓶颈变成分组 GEMM 的有效算力利用率，应改用有效算力利用率模型评估。判据是 1/γ 是否低于当前阶段的算力冗余度：若 1/γ 已逼近该阶段的 bound 利用率上限，继续抬 γ 只会让吞吐单调下降，此时丢弃率再低也没有意义。</p>\n<p>第三个失效条件是小 T 下套用大 T 标定的 γ。T 变小后二项尾概率的行为改变，同一 γ 的丢弃率与预填阶段差异很大，且路由热点被均值掩盖得更彻底。容量规划失真的表现是：预填阶段标定的 γ 在解码阶段要么过度保守（浪费 padding）、要么过度激进（丢弃率飙升），两者都会让端到端 SLO 偏离设计点。正确做法是按阶段分别标定 γ，并把 T 的实际分布（而非均值）作为反解的输入。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-13\">十三 · 二项界的三处失真：均匀性、离散性与 padding 反噬</h3>\n<p>该界最脆弱的一环是 <span class=\"formula-inline\">X_e ~ Binomial(T, k/E)</span> 中的独立同分布假设。它要求每个 token 在 E 个专家上的选择是边际均匀的伯努利试验，而线上流量的领域聚集会直接破坏这一点：代码请求扎堆命中少数“代码专家”，数学请求扎堆命中另一批，实测直方图呈现明显的双峰而非平坦。此时真实尾概率由热点专家的均值 <span class=\"formula-inline\">T·p_e</span>（<span class=\"formula-inline\">p_e ≫ k/E</span>）主导，对 E 求和后的丢弃率可比二项界高一个数量级；按理论 γ 定容，SLO 的丢弃预算在热点专家上被瞬间击穿。工程上的修正是把 <span class=\"formula-inline\">Pr[X_e &gt; C]</span> 换成实测直方图的经验尾概率 <span class=\"formula-inline\">\\(\\hat{F}_e(C)\\)</span> 再求和，γ 由“最热专家”而非“平均专家”反解，代价是容量预留向热点倾斜、冷专家的座位被浪费，专家并行的负载均衡器必须同步介入。</p>\n<p>第二处失真在离散性。推导把 T 次试验近似为连续尾概率，但解码阶段单 token 或极小 micro-batch 下 T 只有个位数，<span class=\"formula-inline\">X_e</span> 取值稀疏，<span class=\"formula-inline\">Pr[X_e &gt; C]</span> 随 γ 呈阶跃式跳变而非平滑下降：γ 从 1 抬到 1.5 可能一步把丢弃率从高位砍到零，也可能毫无变化，取决于 C 落在哪个整数格点上。用预填阶段（T 大、尾概率平滑）标定的 γ 直接搬到解码期，同一 γ 的实际丢弃率与标定值严重脱节，容量规划失真。正确做法是按阶段分别标定：预填用大 T 的二项界，解码用实测小样本直方图，并对 C 做整数取整后的敏感性检查。</p>\n<p>第三处是 padding 反噬，也是该界从“丢弃率模型”退化为“无效模型”的临界点。分组 GEMM 把每个专家都 padding 到 C 参与计算，有效算力利用率为 <span class=\"formula-inline\">\\(\\eta \\approx \\frac{kT}{E\\cdot C} = \\frac{1}{\\gamma}\\)</span>（均匀路由下），γ 每翻一倍，padding 浪费就翻一倍。当 γ 被推到 2 以上以压低丢弃时，丢弃率界仍在下降，但真实吞吐已被 padding 主导而反向下滑——此时该界不再反映吞吐代价，必须切换到以 <span class=\"formula-inline\">\\(\\eta\\)</span> 为核心的有效算力利用率模型，把“丢弃率×剩余算力”作为联合目标而非单看丢弃率。下表给出三种配置的定性对比：</p>\n<table class=\"mini\"><thead><tr><th>配置</th><th>丢弃率界</th><th>有效算力利用率</th><th>系统代价</th></tr></thead><tbody><tr><td>γ=1，均值分配</td><td>高，尾概率显著</td><td>接近 1</td><td>丢弃 token 跳过该层，精度受损</td></tr><tr><td>γ=1.2~1.5，适度余量</td><td>低</td><td>中等稀释</td><td>padding 可控，吞吐与精度折中</td></tr><tr><td>γ&gt;2，强压丢弃</td><td>趋零但界失效</td><td>骤降</td><td>padding 主导，吞吐反低于适度丢弃配置</td></tr></tbody></table>\n<p>由此得到该界的适用判据：路由近似均匀、T 足够大、γ 处于 padding 尚未主导的区间，三者同时成立时二项界才有预测力；任一条件破裂，就应换成实测直方图尾概率或有效算力利用率模型，而不是继续调大 γ 硬扛。</p>\n<h3 id=\"th-moe-capacity-drop-bound-sec-14\">十四 · 均匀路由假设的工程含义</h3>\n<p>二项尾概率界成立的前提不是“路由算法公平”，而是“边际命中概率可写成 k/E 且各 token 相互独立”。在工程上这等价于两件事：其一，路由器对每个 token 的 top-k 选择在专家维度上近似可交换，任一专家被选中的概率不随专家编号漂移；其二，同一 micro-batch 内 token 之间不存在系统性相关，例如同一请求的连续 token 不会集体偏向某类专家。只有这两条同时成立，各专家负载才服从同一 <span>Binomial(T, k/E)</span>，对 E 个专家求和才有意义。</p>\n<p>这条假设在预填阶段较易满足：一个 micro-batch 内 T 通常达到数千 token，来自多个请求、多个领域，路由分布被自然混合，边际概率接近 k/E。到了解码阶段，T 退化为每步每请求一个 token，micro-batch 由并发请求拼成，若并发请求同属一个领域，token 的相关性直接破坏独立性假设。此时公式给出的丢弃率只是“若路由完全均匀”的下界，而非预测值。</p>\n<p>代价层面要看清：均匀假设被违反时，误差不是线性的。尾概率对分布形状高度敏感，热点专家承接的 token 数一旦超过 kT/E 的数倍，<span>Pr[X_e > C]</span> 从万分之一量级跳到百分之一量级，而容量 C 仍按均值放大 γ 倍预留，SLO 的丢弃率预算被瞬间击穿。这就是“按理论 γ 定容会造成违约”的机制根源，不是参数没调好，而是模型族选错了。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-15\">十五 · 独立性假设在批内如何失效</h3>\n<p>独立性假设的失效有一条清晰的工程路径：请求级相关性 → token 级相关性 → 专家负载方差放大。MoE 路由器的输入是隐藏状态，同一请求的 token 共享上下文、同一系统提示、同一领域词汇，其隐藏状态在专家选择上高度同向。若一个 micro-batch 由同一领域的请求组成（连续批处理在低并发时经常如此），则 T 次试验并非独立，实际负载方差远大于二项分布的 <span>T·(k/E)·(1−k/E)</span>。</p>\n<p>方差放大直接改变尾概率。二项界用均值附近的方差估计尾部，而真实负载的方差被请求级聚类抬高，尾部被系统性低估。工程判断是：当 micro-batch 内请求的领域熵低（请求同质），二项界不可用于定容；当领域熵高（请求异质混合），二项界可作为保守近似。判别方法不需要新公式，只需在线上采样路由直方图，比较实测每专家负载的方差与二项方差，比值显著大于 1 即说明独立性已破。</p>\n<p>系统代价体现在两个方向：低估丢弃率导致 SLO 违约与重试放大；高估丢弃率导致 γ 虚高、padding 浪费。前者伤延迟尾部，后者伤吞吐。二者都不能靠“调大 γ”单边解决，因为 γ 增大同时压低丢弃率、抬高 padding，最优点随路由分布漂移。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-16\">十六 · 专家坍缩与热点：何时必须换分布</h3>\n<p>专家坍缩是均匀假设最彻底的失效形式。负载均衡损失在训练期约束专家使用率，但推理期的输入分布与训练分布存在偏移，某些专家在特定领域上被持续激活，形成结构性热点。此时少数专家承接远超 kT/E 的 token，二项尾概率严重低估真实丢弃率，实测丢弃率可比二项界高一个数量级——这不是数值误差，是模型假设与现实的量级差。</p>\n<p>处理方式不是修正 γ，而是替换分布：用实测路由直方图 <span>{p_e}</span> 替代均匀的 k/E，把每个专家的负载建模为 <span>Binomial(T, p_e)</span>（若仍近似独立）或直接使用经验尾分布。容量决策从“反解最小 γ”变为“对每个专家单独定容或按热点专家定容”，后者等价于把 C 抬到热点专家的高分位负载，代价是冷门专家被 padding 到同一 C，分组 GEMM 的有效算力利用率被稀释。</p>\n<p>工程上要区分两种热点：瞬态热点由单个大请求触发，持续时间短，可用请求级限流或路由温度参数缓解；结构性热点由领域分布决定，持续存在，只能靠容量与并行度联合定容吸收。前者适合动态 γ，后者适合静态按热点定容。把两者混为一谈，会导致 γ 在瞬态抖动上反复调整，反而放大 padding 波动。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-17\">十七 · γ 过大时界不再刻画吞吐</h3>\n<p>公式描述的是丢弃率随 γ 单调下降，但它不描述吞吐。γ 增大时每个专家都被 padding 到 <span>C = ⌈γ·kT/E⌉</span> 做分组 GEMM，实际参与计算的 token 数被抬到 E·C，而有效 token 仍是 T·k（扣除丢弃）。有效算力利用率近似为 <span>(T·k·(1−drop)) / (E·C)</span>，γ 越大分母越大，利用率越低。当 padding 浪费主导时，丢弃率界与真实吞吐代价脱钩，继续用它优化等于优化一个不相关的目标。</p>\n<div class=\"formula\">$$\\text{util} \\approx \\frac{T k (1-\\text{drop})}{E \\cdot \\lceil \\gamma kT/E \\rceil} \\approx \\frac{1-\\text{drop}}{\\gamma}$$</div>\n<p>这个近似说明：γ 从 1 提到 2，即使丢弃率降到接近零，利用率也掉到约一半。工程判断是存在一个 γ 拐点，超过它后“降丢弃”的收益被“padding 稀释”抵消，吞吐反而低于适度丢弃加小 γ 的配置。拐点位置取决于 GEMM 的形状效率与丢弃的实际代价（丢弃 token 跳过该层计算但保留残差，对精度的影响需单独评估），不能只由丢弃率界给出。</p>\n<p>因此容量决策的正确做法是双目标：先用丢弃率界反解满足 SLO 的最小 γ，再用有效算力利用率模型核算该 γ 下的吞吐，若吞吐不达标则回到并行度与批大小联合调整，而不是继续抬 γ。把界当唯一目标函数是常见误用。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-18\">十八 · 小 T 下界的预测力丧失</h3>\n<p>T 足够大是二项界可用的规模下限。T 小时，尾概率对离散性极敏感：<span>X_e</span> 取值稀疏，γ 的微小变化会让 C 跨过整数边界，丢弃率随之跳变，公式给出的平滑曲线不再成立。解码阶段单 token 或极小 micro-batch 正是这一区间，此时路由热点被均值掩盖，二项界既低估尾部又高估平滑性。</p>\n<p>规模上限则来自另一端：T 极大时中心极限定理使负载分布趋近正态，二项尾概率可用正态近似快速计算，但请求级相关性随 T 增大而累积，独立性假设反而更脆弱。工程上 T 的上限不是计算能力，而是“批内请求异质性是否足以支撑独立同分布”。连续批处理把不同到达时刻的请求拼进同一 micro-batch，异质性通常足够；固定长度离线批若按领域分组，异质性不足。</p>\n<p>具体例子：预填阶段用 T 数千标定的 γ，直接搬到解码期每步 T 等于并发数的场景，同一 γ 下丢弃率与预填阶段差异很大，容量规划失真。正确做法是按阶段分别标定 γ：预填用大批 T 的二项界，解码用实测路由直方图加经验尾分布，两者不共享同一 γ。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-19\">十九 · 适用边界的判定清单</h3>\n<p>把上述失效条件收敛为可执行的判定顺序，用于判断当前场景能否套用该界：</p>\n<ul>\n<li>路由边际概率是否近似均匀：采样路由直方图，若最大专家占比显著偏离 k/E，换实测分布。</li>\n<li>批内请求领域熵是否足够：低熵（同质请求）时独立性破，二项界只作下界参考。</li>\n<li>T 是否落在二项界有效区间：解码小 T 不套用，预填大 T 可用但需检查相关性。</li>\n<li>γ 是否已越过 padding 拐点：用有效算力利用率核算，越过则改用利用率模型。</li>\n<li>是否存在结构性热点：有则按热点专家定容，不按全局均值反解 γ。</li>\n</ul>\n<p>这张清单的工程价值在于把“公式是否成立”转化为“用哪个模型定容”。二项界是均匀路由、独立 token、中等 T、小 γ 四条件同时满足时的快速反解工具；任一条件破，就必须换分布或换目标函数。容量因子本身不是可独立调优的旋钮，它与批大小、专家并行度、阶段划分绑定，脱离这些上下文单独调 γ 只会把误差从一个代价转移到另一个代价。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-20\">二十 · 边界之外：二项界在什么路由分布与批尺度上失效</h3>\n<p>该界成立的前提可以压缩成三条互相耦合的假设：路由近似均匀、token 在层内近似独立同分布、micro-batch 规模 T 足够大。三者缺一，<span class=\"formula\">$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr[X_e &gt; C]$$</span> 就从“丢弃率预算”退化为“乐观下界”。最脆弱的是均匀性：真实流量里领域分布会把少数专家推成热点，热点专家的实际负载远超 kT/E，而二项尾概率仍按均值算，尾部被系统性低估。工程上的替代做法是放弃解析分布，直接用实测路由直方图做经验尾概率——把每个专家在最近若干 micro-batch 上的命中计数排序，取分位数作为 C 的候选，再反解 γ。这一步的代价是需要在调度器里维护按层的路由计数器，并把定容从离线公式变成在线滚动估计，增加了控制面的状态与抖动风险。</p>\n<p>第二个失效条件是 γ 过大时的 padding 主导。容量 C 一旦抬到远高于均值，分组 GEMM 会把每个专家都 padding 到 C 做矩阵乘，有效算力利用率被稀释，此时丢弃率界仍在下降，但真实吞吐代价已经换了主导项，公式不再反映系统成本。判断切换点的实用判据是比较两条曲线：丢弃造成的有效 token 损失与 padding 造成的算力浪费，前者随 γ 单调降、后者随 γ 近似线性升，交点即折中。<table class=\"mini\"><thead><tr><th>γ 区间</th><th>丢弃率界</th><th>主导代价</th><th>应采用的模型</th></tr></thead><tbody><tr><td>接近 1</td><td>对分布假设极敏感</td><td>丢弃导致残差通路跳过、精度损失</td><td>二项界（需实测校准）</td></tr><tr><td>适度放大</td><td>单调下降</td><td>丢弃与 padding 折中</td><td>二项界 + padding 成本项</td></tr><tr><td>过大</td><td>趋近于零但无意义</td><td>分组 GEMM 有效算力利用率</td><td>有效算力利用率模型</td></tr></tbody></table>显存侧的连带代价同样真实：C 决定每专家 GEMM 的激活缓冲上界，γ 抬高一档，按层预留的临时激活与分组元数据同步放大，在专家并行度受限时直接压缩可用的 KV cache 空间。</p>\n<p>第三个边界是批尺度。解码阶段单 token 或极小 micro-batch 下，T 小到二项分布的离散性主导行为，尾概率对 γ 的微小变化呈跳变而非平滑下降，路由热点又被均值掩盖，界失去预测力。此时正确的做法不是沿用预填阶段标定的 γ，而是按解码期的实际 T 重算容量，或干脆在解码期改用无丢弃的稠密回退路径、以带宽换确定性。这一点与连续批处理下的批组成强相关：批内请求的领域混合比例随调度策略漂移，同一 γ 在不同批组成下的实测丢弃率差异显著，容量规划必须把批组成作为输入而非把 γ 当作常量。规模上限也来自这里——E 越大、k/E 越小，单专家命中概率越低，二项近似越依赖 T 足够大来平滑离散性；当 T 与 E 同量级时，公式的连续性假设瓦解，应退回经验直方图或保守的 γ 下限。</p>\n<h3 id=\"th-moe-capacity-drop-bound-sec-21\">二十一 · 从丢弃率预算反解 γ：容量决策的第一条链路</h3>\n<p>推理侧定容的起点不是“给多少显存”，而是“允许多少 token 被跳过”。给定 SLO 中可容忍的层内丢弃率预算 ε（注意是每层、每 micro-batch 的丢弃比例，不是端到端请求失败率），把 <span class=\"formula-inline\">$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E}\\Pr[X_e&gt;C]$$</span> 当作关于 γ 的单调递减函数，做一次一维反解即可：从 γ=1 起逐档抬升，直到求和尾概率落进 ε 之下，取满足条件的最小 γ。这一步的产物不是一个抽象倍数，而是三个可落地的量：每专家容量 <span class=\"formula-inline\">$$C=\\lceil\\gamma\\,kT/E\\rceil$$</span>、分组 GEMM 的 padding 上界（最坏情形下每个专家都被填到 C，实际算力开销按 E·C 计）、以及为容纳 C 行激活与对应输出所需的暂存显存。反解过程本身很便宜，但必须按 micro-batch 规模 T 逐点做——因为尾概率对 T 高度敏感，同一 ε 在预填的大 T 下可能只需 γ=1.1，在解码的小 T 下却要 γ=1.5 才压得住离散抖动。</p>\n<p>工程上把这条链路写成容量表而非运行时试算：以 (T, E, k, ε) 为索引，离线枚举 γ 网格，记录每个格点的 C 与 padding 浪费比 <span class=\"formula-inline\">$$E\\cdot C/(kT)$$</span>（γ=1 时为 1，γ=1.5 时为 1.5），部署时按实际 micro-batch 查表。代价体现在两个方向：γ 抬高一档，padding 浪费线性上升，分组 GEMM 的有效算力利用率被稀释；γ 压低一档，丢弃率按尾概率上升，被跳过的 token 只保留残差通路，等于该层对这部分 token 白算。所以反解的目标不是“丢弃率最小”，而是“在 ε 约束下取最小 γ”，把余量花在刀刃上。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-22\">二十二 · 定批大小：T 是容量决策的自变量而非结果</h3>\n<p>常规批调度把批大小当优化目标，但在 MoE 容量决策里 T 必须先被固定，否则 γ 无从反解。原因在二项分布的形状：固定均值 kT/E 时，尾概率随 T 增大而收缩（相对标准差按 1/√T 衰减），大 T 下路由波动被平均掉，γ 可以贴近 1；小 T 下单个专家的负载抖动占均值比例大，尾概率对 γ 极敏感。因此批大小与 γ 是一对耦合变量，正确做法是给定 SLO 与 ε，在 (T, γ) 平面上找可行域，再叠加时延约束选点。</p>\n<div class=\"formula\">$$\\text{padding 开销} \\propto E\\cdot\\lceil\\gamma\\,kT/E\\rceil,\\qquad \\text{丢弃率} \\approx \\sum_e \\Pr[\\mathrm{Binomial}(T,k/E)&gt;C]$$</div>\n<p>具体机制上，连续批处理框架每个调度步会重组 micro-batch，T 随在途请求数波动，若 γ 按峰值 T 标定，则在低负载时 padding 浪费被放大（因为 C 是按大 T 算出的绝对值，小 T 时 E·C 相对 kT 的比值飙升）；反之按低谷 T 标定，高峰时丢弃率超标。可行做法是按 T 分档维护多组 γ（例如预填档与解码档分开），调度器在组批时按落入的档位取对应容量。代价是显存预留要按最大档的 C 计，而算力开销按实际档位结算——这是一次用显存换丢弃率确定性的交换。举例：E 较大、k 较小的细粒度专家模型，解码期 T 只有数十量级，此时二项尾概率的离散跳变明显，γ 的微小变化会让丢弃率跨档，必须放弃连续反解、改用查表加安全垫。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-23\">二十三 · 定并行度：专家切分与副本数受 C 约束</h3>\n<p>容量因子直接决定单专家 GEMM 的 M 维上界，而 M 维上界又决定专家并行（EP）切分后每个 rank 上的计算粒度。若把 E 个专家摊到 N 个 rank，每 rank 承接 E/N 个专家，其分组 GEMM 的最大工作量是 (E/N)·C 行；当 C 很小（γ 贴近 1、T 小），单 rank 的 GEMM 退化为大量小矩阵，Tensor Core 利用率被 M 维拖垮，此时应减少 EP 度数、让单 rank 持有更多专家以凑大 M；当 C 很大（预填、大 T），单 rank 工作量饱和，才值得提高 EP 度数换取并行。所以“定并行度”的正确顺序是：先由 ε 反解 γ 与 C，再按 (E/N)·C 是否达到高效 GEMM 的 M 门槛决定 N，最后核对 all-to-all 通信量是否被这一选择推高——dispatch 阶段要搬的 token 数正比于 kT，与 γ 无关，但 combine 阶段回传的布局受容量 padding 影响。</p>\n<p>副本维度同理：数据并行副本数增加会分摊 T，使每副本的 T 变小，进而把 γ 推高、把 C 的相对 padding 推高。这意味着“加副本提吞吐”在 MoE 上不是线性收益，副本数存在一个由容量表决定的拐点。工程判断是：当每副本 T 已小到二项界失去预测力（尾概率跳变、热点被均值掩盖），继续加副本只会让容量预留变成拍脑袋，此时应改为单副本大 T 加 EP 扩展。代价落在显存：每副本都要为 C 预留激活暂存，副本数乘以该预留即总开销，而这份开销在低 T 下几乎不被利用。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-24\">二十四 · 定 KV 预算：丢弃率与 KV 争抢同一块显存</h3>\n<p>KV cache 与 MoE 激活暂存共享 HBM，容量因子抬高 γ 会直接挤压 KV 预算。把每层每 micro-batch 的激活暂存记为与 E·C 成正比（C 行输入、C 行输出、以及分组 GEMM 的中间缓冲），则 γ 每抬高一档，这部分预留线性增长；在给定卡数的显存总账里，KV 可用的块数相应减少，可并发序列长度或上下文长度被压缩。于是容量决策变成一个三元约束：丢弃率 ≤ ε、KV 块数 ≥ 满足 SLO 的并发需求、激活暂存 ≤ 剩余显存。求解顺序是先按 ε 定 γ 与 C，算出激活暂存的下界，再把剩余显存全部分给 KV，最后核对由此得到的并发是否够用；不够则回头放宽 ε（接受更多丢弃）或提高 EP 度数（把 E·C 摊薄到更多卡上）。</p>\n<p>这里有一个容易被忽略的耦合：被丢弃的 token 虽然跳过该层计算，但其 KV 仍需保留（残差通路继续前向），所以丢弃并不省 KV，只省算力。这意味着“用丢弃换显存”是伪命题——γ 压低省下的是激活暂存，不是 KV；而 γ 抬高多花的激活暂存会实打实减少 KV 块数。工程判断因此偏向：在 KV 紧张的部署里，宁可接受适度丢弃率、把 γ 压在低位，也不要为追求零丢弃把激活暂存撑到挤掉 KV 的程度。具体例子：长上下文场景下 KV 是主要显存消费者，此时容量表应按“KV 优先”重排，γ 取满足 ε 的最小值即可，多余显存一律给 KV 块池。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-25\">二十五 · 定 SLO：把端到端指标拆到层内丢弃预算</h3>\n<p>SLO 通常写成端到端时延分位数与吞吐下限，而容量因子作用在层内。两者之间的桥是：丢弃率影响的是输出质量与有效算力，不直接进入时延公式，但通过 padding 间接影响吞吐——γ 抬高使每步 GEMM 变长，调度步时延上升，进而推高 TTFT 与 TPOT 的分位数。因此定 SLO 的正确拆法是三层：第一层把质量约束（可接受的语义退化）翻译成层内丢弃率预算 ε，注意 MoE 层数多，端到端可容忍退化要按层摊薄，单层 ε 必须远小于端到端指标；第二层由 ε 反解 γ，得到每步的 padding 系数；第三层把 padding 系数代入批调度时延模型，核对分位数是否仍达标。三层任一不满足，就回到第一层放宽 ε 或回到并行度一节调整 N。</p>\n<p>常见失效是把均匀路由假设直接用于线上流量：真实请求的领域分布造成专家热点，实测丢弃率可比二项界高一个数量级，按理论 γ 定容必然 SLO 违约。因此 SLO 定容流程里必须插入一步实测校准——用线上路由直方图替换二项分布，重算尾概率，取两者较大者作为 γ 的下界。另一个失效是在解码期小 micro-batch 上沿用预填阶段标定的 γ：T 变小后尾概率行为改变，同一 γ 的丢弃率与预填阶段差异很大，容量规划失真。工程上应把 γ 与 T 档位绑定写入配置，禁止跨阶段复用。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-26\">二十六 · 算例：一次完整的容量反解</h3>\n<p>设某 MoE 层 E 个专家、每 token 激活 k 个、预填 micro-batch 的 T 较大，路由近似均匀。按二项界，单专家负载均值 kT/E、标准差约 √(kT/E·(1−k/E))。取 ε 为单层丢弃预算，从 γ=1 起算尾概率，若超标则抬到 γ=1.1、1.2……直到求和尾概率落入 ε 之下，得到最小 γ*，进而 C*=⌈γ*kT/E⌉。此时 padding 浪费比为 γ*，分组 GEMM 的算力开销按 E·C* 计；激活暂存按 C* 行估算，从显存总账中扣除后剩余给 KV。接着核对：若 EP 度数 N 使 (E/N)·C* 低于高效 GEMM 的 M 门槛，则降 N；若降 N 后单卡显存放不下 E·C* 暂存，则回头抬 ε 换更小 γ*。整个过程不需要任何实验数字，只需要 T、E、k、ε 四个输入与一张 γ 网格表。</p>\n<p>算例的工程含义在于：γ* 不是拍出来的安全系数，而是 ε 的函数；C* 是 γ* 与 T 的乘积，所以同一 ε 在预填档与解码档给出完全不同的 C*，两档必须分开定容。解码档 T 小时，二项尾概率对离散性极敏感，γ 的微小变化引起丢弃率跳变，此时应放弃连续反解，改用实测路由直方图加固定安全垫，并把该档的 γ 锁死在配置里。最后一条判断：当 γ* 被推到 2 以上才能满足 ε 时，说明均匀路由假设已不成立或 ε 定得过紧，此时继续抬 γ 会让 padding 主导、有效算力利用率骤降，吞吐反而低于“适度丢弃加小 γ”的配置——这正是该界失效、应切换到有效算力利用率模型的信号。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-27\">二十七 · 容量因子在批大小、并行度、KV 预算与 SLO 上的反解用法</h3>\n<p>把丢弃率界当作容量决策的“反解器”，而不是事后校验器：给定 SLO 允许的丢弃率预算 δ、层内 token 数 T、专家数 E 与 top-k，求最小 γ 使 <span class=\"formula-inline\">$$\\sum_{e}\\Pr[X_e&gt;C]\\le\\delta$$</span>。由于各专家同分布，等价于单侧尾概率 ≤ δ/E，可在二项分布表上直接查 C，再取 γ = C·E/(kT) 向上取整到硬件友好的档位（如 1.0/1.25/1.5）。这个 γ 同时给出三个下游参数：每专家 GEMM 的 padding 上界 C（决定分组 GEMM 的 tile 数与算力预留）、专家并行度 EP 的切分粒度（C 必须能被每卡专家数整除才不产生二次 padding）、以及 KV 预算的间接约束——γ 越大，单层激活暂存与路由缓冲占用越高，挤占可分配给 KV cache 的显存。</p>\n<p>算例：某层 E=64、k=2、预填 micro-batch T=8192，则平均负载 kT/E=256；若 SLO 容忍该层丢弃率 δ=1e-3，则单专家尾概率预算 1.56e-5，二项分布下需 C≈340，反解得 γ≈1.33，向上取 1.5 得 C=384。此时每专家 padding 浪费约 (384−256)/384≈33%，分组 GEMM 有效算力利用率降至约 2/3；若把 γ 压到 1.0（C=256），丢弃率跳到不可接受量级，残差通路跳过的 token 直接损害输出质量。工程判断是：δ 预算应按层分配而非全局平摊，靠近输出的层丢弃代价更高，应给更大 γ。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>由 γ 反解的输入</th><th>系统代价</th></tr></thead><tbody><tr><td>批大小 T</td><td>固定 δ 下 T 越大尾概率越集中，γ 可下调</td><td>T 增大抬高激活显存与路由缓冲</td></tr><tr><td>专家并行度</td><td>C 需被每卡专家数整除</td><td>不整除产生二次 padding，稀释算力</td></tr><tr><td>KV 预算</td><td>γ 抬高单层暂存占用</td><td>挤占 KV cache，压低并发上限</td></tr></tbody></table>\n<p>边界与失效条件必须写进容量表：该反解只在路由近似均匀、T 足够大时成立；线上领域分布造成专家热点时，实测丢弃率可比二项界高一个数量级，此时必须用实测路由直方图替换 Binomial(T,k/E)，按经验分位数定 C，否则按理论 γ 定容会直接造成 SLO 违约。更隐蔽的失效是 γ 过大：当 γ 超过约 1.5–2 后，padding 到 C 的分组 GEMM 浪费主导吞吐，丢弃率界不再反映真实代价，应切换到有效算力利用率模型，用“适度丢弃 + 小 γ”换吞吐。解码期尤其危险：T 退化为单 token 或极小 micro-batch 时尾概率对离散性极敏感，γ 的微小变化引起丢弃率跳变，且热点被均值掩盖，预填阶段标定的 γ 不能沿用到解码，需按解码的实际 micro-batch 规模单独标定，并把 γ 作为随批调度动态调整的运行时参数而非静态编译常量。</p>\n<h3 id=\"th-moe-capacity-drop-bound-sec-28\">二十八 · 误用一：把均匀路由的二项界直接套到线上流量</h3>\n<p>这是本界最致命的一种误用，也是最难在离线标定阶段被发现的一种。机制上，公式里每个专家的负载被建模为 <span class=\"formula-inline\">X_e ~ Binomial(T, k/E)</span>，其成立的前提是“每个 token 在 E 个专家中选 k 个，且任一专家被选中的边际概率恰为 k/E”。这个前提在合成流量、随机路由、或训练早期尚未分化的路由器上大致成立；但线上流量从来不是均匀的——请求的领域分布（代码、多语、长文档、结构化工具调用）本身高度偏斜，路由器在领域内会自发形成专家坍缩与热点，少数专家承接的 token 数远超 kT/E。</p>\n<p>后果是双向的。一方面，二项尾概率严重低估真实丢弃率：理论算出的 <span class=\"formula-inline\">Pr[X_e > C]</span> 求和后可能落在千分之几，而实测丢弃率可以高出一个数量级，因为热点专家的真实分布尾部比二项分布厚得多。另一方面，按理论 γ 反解出的容量 C 对这些热点专家根本不够用，被挤出的 token 在该层被直接跳过、只保留残差通路，于是模型输出质量在特定领域上出现系统性劣化，而监控面板上的平均丢弃率仍显示“达标”——平均值把热点掩盖了。</p>\n<p>识别方法很直接：不要看聚合丢弃率，要看<strong>逐专家的负载直方图</strong>。把每个 micro-batch 内各专家实际接收的 token 数画成分布，与 <span class=\"formula-inline\">Binomial(T, k/E)</span> 的理论分布叠在一起比对；若实测分布的右尾明显更厚、或出现若干专家长期贴近 C 而另一些专家长期远低于均值，就说明均匀假设已失效，必须用实测路由直方图替换理论分布，逐专家（或按分位数分组）计算溢出概率，而不是对 E 个同分布项求和。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-29\">二十九 · 误用二：只压丢弃率、不核算 padding 代价</h3>\n<p>第二种误用是把 γ 当成“越大越安全”的单调旋钮。机制上，容量 C 一旦确定，分组 GEMM 就要把每个专家的 token 张量 padding 到 C 再做矩阵乘；γ 越大，C 越大，padding 的无效行越多。当 γ 被推到 2 以上时，每个专家都被填充到两倍于平均负载的规模，有效算力利用率被稀释——真正参与计算的 token 占比下降，而 tensor core 的周期数照付。</p>\n<p>这里存在一个明确的折中点：丢弃率随 γ 单调下降，padding 浪费随 γ 单调上升，二者在给定路由均值下交叉。用公式语言说，当 γ 过大时，本界已经不再反映真实吞吐代价，因为主导项从“丢弃导致的 token 重算/质量损失”切换成了“padding 导致的算力空转”，此时应改用有效算力利用率模型评估。工程上的判断是：把 γ 从 1 提到 1.5 带来的丢弃率下降通常值得，但从 1.5 提到 2.5 往往是用吞吐换一个已经很小的丢弃率改善，净收益为负。</p>\n<p>识别方法：在容量决策表里同时记录三个量——理论丢弃率、实测丢弃率、以及分组 GEMM 的有效算力利用率（实际 token 数 / padding 后 token 数）。若发现吞吐随 γ 上升而下降，而丢弃率已进入平台区，就是踩到了 padding 主导区。具体例子：一个 E 较大、k 较小的层，在 γ=1 时丢弃率尚可接受、GEMM 几乎无 padding；运维为“保险”把 γ 提到 2，padding 翻倍，单层延迟上升，整模型吞吐反而低于适度丢弃加小 γ 的配置——这正是失败模式里“吞吐反而更低”的典型形态。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-30\">三十 · 误用三：解码期小 micro-batch 沿用预填阶段标定的 γ</h3>\n<p>第三种误用跨了阶段：在预填（大 T）阶段标定出的 γ，被直接搬到解码阶段使用。机制上，二项分布的尾概率对 T 极其敏感——T 大时分布近似正态、尾部平滑，γ 的微小变化只引起丢弃率的缓慢漂移；T 小到单 token 或极小 micro-batch 时，分布是离散的、偏斜的，尾概率对离散性极敏感，γ 的微小变化会引起丢弃率跳变。更糟的是，小 T 下单个热点 token 就能把某专家推过 C，而均值 kT/E 很小，热点被均值彻底掩盖，界失去预测力。</p>\n<p>后果是容量规划失真：预填阶段标定的 γ 在解码阶段对应的实际丢弃率与标定时差异很大，且方向不定——既可能因为离散性显得“更安全”，也可能因为热点集中而突然违约。由于解码阶段通常是延迟敏感、SLO 最紧的阶段，这种失真直接打在用户体验上。</p>\n<p>识别方法：把 γ 的标定按 T 分档，而不是给整个模型一个全局 γ。对解码期的小 T，不要依赖二项尾概率的解析值，而应直接用实测路由直方图在小 T 下的经验分布来定 C，并接受“γ 在小 T 下不是稳定旋钮”这一事实。工程判断是：预填与解码应当各自持有独立的容量参数，二者的 γ 不可互换。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-31\">三十一 · 一个反例：热点领域流量下的定容全过程</h3>\n<p>设某 MoE 层 E 个专家、每 token 激活 k 个，运维按均匀假设、以可容忍丢弃率为预算反解出 γ=1.2，并据此把每专家容量定为 C，写入容量决策表作为批大小与专家并行度的联合输入。上线后合成流量测试通过，聚合丢弃率落在预算内。</p>\n<p>真实流量到来，某垂直领域请求集中涌入，路由器在该领域内形成两三个热点专家。此时热点专家的真实负载分布不再是 <span class=\"formula-inline\">Binomial(T, k/E)</span>，而是均值远高于 kT/E、尾部更厚的分布；对这些专家，<span class=\"formula-inline\">Pr[X_e > C]</span> 的真实值比理论值高一个数量级，被挤出的 token 在该层跳过计算、只留残差，模型在该领域的输出质量下滑。与此同时，非热点专家长期远低于 C，padding 照付，有效算力利用率被拉低——两头受损。</p>\n<p>正确的处置不是简单调大 γ：调大 γ 会同时抬高所有专家的 C，热点专家仍可能不够（因为热点强度随流量变化），而非热点专家的 padding 浪费进一步加剧。正确做法是先用实测路由直方图替换二项分布、逐专家重算溢出概率，识别出热点专家集合；再对热点专家单独提高容量（或做专家复制/负载均衡），对冷专家维持小 γ。这样丢弃率预算被花在真正需要的地方，padding 代价被限制在热点侧。这个反例说明：本界的价值不在于给出一个可直接写入配置的 γ，而在于它明确了“何时该信、何时该换模型”——一旦实测直方图偏离二项假设，界就从预测工具退化为告警信号。</p>\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-32\">三十二 · 识别清单与工程落点</h3>\n<p>把上述误用收敛成可执行的检查项，落在容量决策的每一步上：</p>\n<ul>\n<li><strong>假设校验</strong>：任何一次用本界定容之前，先比对实测逐专家负载直方图与 <span class=\"formula-inline\">Binomial(T, k/E)</span>；右尾偏厚或专家间负载方差显著大于理论值，即判定均匀假设失效，切换到实测分布。</li>\n<li><strong>代价双记</strong>：容量表必须同时记录丢弃率与 padding 后的有效算力利用率；只记前者就是把 γ 当单调旋钮的根源。</li>\n<li><strong>分阶段标定</strong>：预填与解码各自标定 γ，禁止跨 T 复用；小 T 下以经验分布定 C，不信解析尾概率。</li>\n<li><strong>热点隔离</strong>：把丢弃率预算按专家分位分配，热点专家单独扩容或做复制，冷专家维持小 γ，避免全局调 γ 的两头受损。</li>\n</ul>\n<p>最后落到一个具体机制上：容量因子 γ 在实现里最终体现为分组 GEMM 的 padding 上界与显存/算力预留，它同时被丢弃率界和有效算力利用率模型从两侧夹住。工程判断的落点是——当实测路由直方图与二项假设的偏离超过可接受阈值时，停止用本界反解 γ，改用直方图驱动的逐专家定容；这不是对本界的否定，而是把它放回它成立的那一侧边界内使用。</p>\n\n\n<h3 id=\"th-moe-capacity-drop-bound-sec-33\">三十三 · 误用与反例：当二项尾界脱离路由现实</h3>\n<p>最常见的误用是把均匀路由假设直接搬到线上流量上。二项界成立的前提是每个 token 在 E 个专家中均匀选 k 个，任一专家被命中的边际概率恰为 k/E，于是各专家负载同分布、丢弃事件退化为单参数尾概率。但真实请求的领域分布是偏斜的：代码补全、长文摘要、多语言对话在同一 micro-batch 内混合时，少数专家承接的 token 数远超 kT/E，二项分布把这种热点摊平成了均值。此时 <span class=\"formula\">$$\\Pr[\\text{drop}] \\approx \\sum_{e=1}^{E} \\Pr\\Big[X_e &gt; C\\Big]$$</span> 中的每个尾概率都被系统性低估，实测丢弃率可比理论界高一个数量级，按理论 γ 反解出的容量会在 SLO 上直接违约。识别方法很直接：在服务侧按层采集实测路由直方图，把每个专家的实际负载分布与 Binomial(T, k/E) 做对比，若直方图的方差显著大于二项方差或出现长尾，理论界即失效，必须用实测直方图替换分布再求和。</p>\n<p>第二个反例是只盯丢弃率、不核算 padding 代价。分组 GEMM 会把每个专家的 token 补齐到容量 C 再计算，γ 从 1 提到 2 意味着每个专家的算力槽位翻倍，而真实负载并未翻倍，有效算力利用率被稀释。设专家 e 的实际负载为 n_e，则 padding 浪费可写成 <span class=\"formula\">$$\\text{waste} = \\frac{\\sum_e (C - n_e)}{E \\cdot C}$$</span>，γ 越大该比值越高。工程上常见的错误配置是为把丢弃压到接近零而把 γ 推到 2 以上，结果吞吐反而低于“适度丢弃 + 小 γ”的组合——因为被丢弃的 token 只保留残差通路、代价是一次跳层，而 padding 浪费吃掉的是整层 GEMM 的算力。识别信号是：γ 上调后丢弃率明显下降但端到端吞吐不升反降，说明代价已从丢弃侧转移到算力侧，此时丢弃率界不再反映真实吞吐，应改用有效算力利用率模型评估。</p>\n<p>第三个失效条件在解码期。预填阶段 T 很大，二项尾概率随 T 增大而平滑，γ 的标定相对稳健；但解码阶段单 token 或极小 micro-batch 下 T 很小，尾概率对离散性极敏感，γ 的微小变化会引起丢弃率跳变，且路由热点被小样本均值掩盖，界彻底失去预测力。把预填阶段标定的 γ 沿用到解码期，会造成容量规划失真：同一 γ 在两阶段的丢弃率差异巨大，而显存与算力预留却按预填的 C 来分配。正确做法是按阶段分别定容，解码期改用实测直方图或更保守的容量上界，而不是复用预填的 γ。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>均匀路由假设用于线上流量</td><td>专家热点使二项尾概率低估</td><td>SLO 违约、丢弃率超预算</td><td>实测直方图方差远大于二项方差</td></tr><tr><td>只压丢弃率、γ 过大</td><td>padding 到 C 稀释有效算力</td><td>吞吐下降、算力利用率骤降</td><td>γ 上调后吞吐不升反降</td></tr><tr><td>解码期沿用预填 γ</td><td>小 T 下尾概率离散跳变</td><td>容量规划失真、显存预留错配</td><td>两阶段同 γ 丢弃率差异巨大</td></tr></tbody></table>\n<p>这三类误用共享同一个根：把“给定路由均值下的最优折中”误读成“给定 γ 就能保证丢弃率”。γ 只是容量相对均值的放大倍数，它约束的是座位数，不是路由分布本身；一旦路由偏离均匀或 T 小到离散效应主导，界就从预测工具退化为装饰。工程判断应落在采集实测路由直方图、按阶段分别定容、并用有效算力利用率而非丢弃率单独做吞吐决策上。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>一个 micro-batch 内进入该 MoE 层的 token 总数</td></tr><tr><td>E</td><td>该层专家总数</td></tr><tr><td>k</td><td>每个 token 激活的专家数（top-k）</td></tr><tr><td>γ</td><td>容量因子，C 相对平均负载 kT/E 的放大倍数</td></tr><tr><td>C</td><td>每个专家允许接收的最大 token 数（容量）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-moe-capacity-drop-bound · 共 5 个片段</p>\n"},{"id":"th-moe-alltoall-comm-bound","title":"MoE 专家并行 All-to-All 下界","direction":"dir-moe-routing-capacity","prereq":[],"plain":"在专家并行下，每层必须把 token 从路由所在卡搬到专家所在卡再搬回，通信量由激活字节数与复制因子决定；当互联带宽为 B 时，单层 All-to-All 的耗时下界是字节数除以带宽，与计算重叠也只能逼近而不能突破该下界。","definition":"在专家并行下，每层必须把 token 从路由所在卡搬到专家所在卡再搬回，通信量由激活字节数与复制因子决定；当互联带宽为 B 时，单层 All-to-All 的耗时下界是字节数除以带宽，与计算重叠也只能逼近而不能突破该下界。","formula":"$$T_{\\text{a2a}}^{\\min} \\;=\\; \\max\\Big(\\underbrace{\\tfrac{2\\,T\\,k\\,d\\,b}{B_{\\text{link}}}}_{\\text{dispatch+combine}},\\; \\underbrace{\\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}}_{\\text{ring 单跳}}\\Big)$$","variables":[{"sym":"T","meaning":"本层参与路由的 token 数"},{"sym":"k","meaning":"每 token 激活专家数"},{"sym":"d","meaning":"token 隐藏维宽度"},{"sym":"b","meaning":"每元素字节数（FP8=1，NVFP4≈0.5 加 scale 开销）"},{"sym":"B_{\\text{link}}","meaning":"单卡可用互联带宽（NVLink 或 IB）"},{"sym":"N","meaning":"专家并行组内 GPU 数"}],"derivation":"第二项 $$\\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}$$ 描述 ring 拓扑下单跳的通信量：每个 token 的激活数据需经 N-1 跳转发、每跳由 N 张卡分摊带宽，故有效载荷被放大 (N-1)/N 倍；取两项最大值即得下界。","example":"适用边界：公式假设拓扑全对称、无拥塞、无 kernel 启动与打包/解包开销；NVL72 内 NVLink 域与跨域 InfiniBand 带宽差一个数量级，跨域部署必须按最慢链路重算 B，否则下界会被高估。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设拓扑为全对称且无拥塞；NVL72 内 NVLink 域与跨域 InfiniBand 带宽差一个数量级，跨域时须按最慢链路重算","未计入 kernel 启动与打包/解包开销；小 batch 解码时固定开销可超过带宽项，下界失去指导意义"],"system_note":"用途：在容量决策中，该下界用于判断某层 MoE 的 All-to-All 是否已成为 SLO 瓶颈——若下界已接近层预算，则增加计算资源无益，应改路由策略、降 k、压缩激活字节或缩小 EP 组；小 batch 解码时固定开销可超过带宽项，下界失去指导意义。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：专家并行把每层路由变成一次跨卡搬运，token 先按路由结果被 dispatch 到专家所在 GPU，算完再 combine 回原卡，因此单层通信量由激活字节数与复制因子 k 决定，带宽 B 给定后耗时存在不可突破的下界。","公式第一项 $$\\tfrac{2\\,T\\,k\\,d\\,b}{B_{\\text{link}}}$$ 中，T 为本层参与路由的 token 数，k 为每 token 激活专家数，d 为隐藏维宽度，b 为每元素字节数，因子 2 对应 dispatch 与 combine 两个方向；分母 B 为单卡可用互联带宽，量纲为字节/秒，故该项单位为秒。","第二项 $$\\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}$$ 描述 ring 拓扑下单跳的通信量：每个 token 的激活数据需经 N-1 跳转发、每跳由 N 张卡分摊带宽，故有效载荷被放大 (N-1)/N 倍；取两项最大值即得下界。","推导关键一步：把 dispatch 与 combine 视为两次全互连交换，先按字节数除以链路带宽得到理想传输时间，再与 ring 单跳模型取 max，从而把拓扑差异压缩为一个可比较的解析式；重叠计算只能让实测时间逼近该 max，不能低于它。","适用边界：公式假设拓扑全对称、无拥塞、无 kernel 启动与打包/解包开销；NVL72 内 NVLink 域与跨域 InfiniBand 带宽差一个数量级，跨域部署必须按最慢链路重算 B，否则下界会被高估。","用途：在容量决策中，该下界用于判断某层 MoE 的 All-to-All 是否已成为 SLO 瓶颈——若下界已接近层预算，则增加计算资源无益，应改路由策略、降 k、压缩激活字节或缩小 EP 组；小 batch 解码时固定开销可超过带宽项，下界失去指导意义。","常见误用：直接把 NVLink 带宽代入跨域场景，忽略 IB 慢一个数量级，导致容量规划偏乐观；或忽略 b 的取值差异（FP8 为 1 字节、NVFP4 约 0.5 字节加 scale 开销），把 W4 的通信节省算错。"],"anchors":["FP8=1","NVFP4≈0.5","N-1","NVL72"],"pitfalls":["把 NVLink 域内带宽当作全局带宽代入公式，跨域 InfiniBand 实际慢一个数量级，实测 All-to-All 远超下界，SLO 直接击穿。","小 batch 解码阶段 kernel 启动与打包/解包固定开销超过带宽项，仍按下界做容量规划，导致单卡吞吐预估虚高。","忽略 NVFP4 的 scale 开销，按 0.5 字节/元素计算通信节省，实际字节数偏高，下界被低估。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-1\">一 · 一句话直觉：路由即搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-2\">二 · 严格定义：下界是什么、不是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-3\">三 · 为什么需要这个下界：它决定优化预算投向哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-4\">四 · 常见误解之一：把 NVLink 带宽当成全局带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-5\">五 · 常见误解之二：忽略 b 的取值与 NVFP4 的 scale 开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-6\">六 · 常见误解之三：把下界当成预测值，或以为重叠能突破它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-7\">七 · 下界什么时候不再成立：边界、失效条件与代价归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-8\">八 · 下界成立的前提与它失效的三个现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-9\">九 · 第一项：dispatch 与 combine 的字节账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-10\">十 · 第二项：ring 单跳为什么带 (N-1)/N</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-11\">十一 · 推导关键步：两次交换 + 一次取 max</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-12\">十二 · 离散化与近似：公式在哪里失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-13\">十三 · 代入前的三项修正与一个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-14\">十四 · 下界公式的适用边界：它在哪里成立，又在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-15\">十五 · 下界失效的三种现场：拓扑、粒度与字节口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-16\">十六 · 全对称假设：公式成立的最小拓扑条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-17\">十七 · 无拥塞假设：从「独占带宽」到「共享带宽」</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-18\">十八 · 固定开销：小 batch 解码时下界失去意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-19\">十九 · 字节数 b：NVFP4 的 scale 开销与压缩收益的错算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-20\">二十 · 规模上限：N 增大时两项的相对变化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-21\">二十一 · 失效条件的工程判据与替代模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-22\">二十二 · 边界之外：下界在什么条件下失去指导意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-23\">二十三 · 把下界翻译成批大小上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-24\">二十四 · 定并行度：N 的两种角色</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-25\">二十五 · 定 KV 预算：通信与显存的对偶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-26\">二十六 · 定 SLO：下界作为可行性判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-27\">二十七 · 一个完整算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-28\">二十八 · 把下界换算成容量决策：批大小、并行度、KV 预算与 SLO 的四个旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-29\">二十九 · 把下界当尺子用：批大小、并行度、KV 预算与 SLO 的联合定标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-30\">三十 · 误用一：把 NVLink 域带宽当成全局带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-31\">三十一 · 误用二：忽略 NVFP4 的 scale 开销，把 b 当成 0.5</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-32\">三十二 · 误用三：小 batch 解码仍拿下界做容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-33\">三十三 · 反例：一次跨域扩容的乐观规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-34\">三十四 · 识别清单与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-moe-alltoall-comm-bound-sec-35\">三十五 · 误用与反例：把下界当成可达性能</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：在专家并行下，每层必须把 token 从路由所在卡搬到专家所在卡再…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{a2a}}^{\\min} \\;=\\; \\ma…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设拓扑为全对称且无拥塞；NVL72 内 NVLink 域与跨域 …</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-moe-alltoall-comm-bound-sec-1\">一 · 一句话直觉：路由即搬运</h3>\n<p>专家并行（EP）把 MoE 层的“选专家”从一次本地查表变成一次跨卡搬运：token 在路由卡上算出 top-k 结果，随后被 dispatch 到持有目标专家的 GPU，专家算完再 combine 回原卡。于是每一层都强制插入两次全互连交换，通信量由“激活字节数 × 复制因子 k”决定。带宽 B 一旦给定，这两次交换的耗时就有不可突破的下界——你可以用计算把它盖住、用流水把它藏住，但盖不住、藏不掉的是字节本身。这就是本系列后续所有推导的出发点：MoE 推理在 EP 下的性能天花板，首先是一道带宽除法题，而不是算力题。</p>\n<p>把这句话写成工程语言：单层 All-to-All 的下界是“要搬的字节 ÷ 能用的带宽”，重叠只能让实测值逼近它，不能低于它。任何声称“通信被完全隐藏”的调度方案，其真实含义都是“实测时间已贴近下界”，而不是“通信消失了”。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-2\">二 · 严格定义：下界是什么、不是什么</h3>\n<p>这里说的“下界”是<strong>单层 All-to-All 的理想传输时间下界</strong>，不是端到端延迟下界，也不是吞吐下界。它由两部分取 max 构成：</p>\n<div class=\"formula\">$$T_{\\text{a2a}}^{\\min} \\;=\\; \\max\\Big(\\underbrace{\\tfrac{2\\,T\\,k\\,d\\,b}{B_{\\text{link}}}}_{\\text{dispatch+combine}},\\; \\underbrace{\\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}}_{\\text{ring 单跳}}\\Big)$$</div>\n<p>变量含义必须钉死，否则后面所有容量判断都会漂移：T 为本层参与路由的 token 数（注意是 token 数，不是序列数，也不含 padding 后的填充量）；k 为每 token 激活专家数；d 为隐藏维宽度；b 为每元素字节数（FP8 记 1，NVFP4 约 0.5 并另计 scale 开销）；B_link 为单卡可用互联带宽，量纲字节/秒；N 为 EP 组内 GPU 数。</p>\n<p>第一项 2Tkdb/B 的因子 2 对应 dispatch 与 combine 两个方向，量纲为秒，含义是“两次全互连交换在理想无拥塞链路上的纯传输时间”。第二项 Tkdb(N−1)/(N·B) 是 ring 拓扑的单跳模型：每个 token 的激活数据要经 N−1 跳转发，而每一跳由 N 张卡分摊带宽，于是有效载荷被放大 (N−1)/N 倍。两项取 max，是把“全互连”与“ring”两种拓扑差异压缩成一个可比较的解析式——哪个模型给出的时间更长，就以哪个为准。</p>\n<p>推导的关键一步在于：把 dispatch 与 combine 各自视为一次全互连交换，先做“字节除以带宽”的理想除法，再与 ring 单跳模型取 max。这一步之所以成立，是因为它只依赖字节数与链路带宽两个量，不依赖具体 kernel 实现、不依赖 NCCL 算法选择。代价是它把拓扑、拥塞、启动开销全部折叠进“假设”里，因此它给出的是<strong>可达时间的下限</strong>，而非预测值。</p>\n<p>严格地说，这个下界有三条硬性前提：拓扑全对称、链路无拥塞、不计 kernel 启动与打包/解包开销。任何一条被破坏，公式就从“下界”退化为“乐观估计”。这不是公式的缺陷，而是使用者的责任——下界的价值恰恰在于它标出了“再怎么优化也到不了的地方”，从而把优化预算逼向正确的方向。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-3\">三 · 为什么需要这个下界：它决定优化预算投向哪里</h3>\n<p>没有下界，容量规划就会陷入“加卡就能变快”的直觉陷阱。MoE 层的实际耗时由计算、通信、调度三者叠加，而三者中只有通信是<strong>与硬件拓扑强绑定、且不随算力增加而下降</strong>的项。若某层的 All-to-All 下界已经接近该层的 SLO 预算，那么继续堆计算资源毫无意义：算得再快，也要等字节搬完。此时唯一有效的杠杆是改路由策略、降 k、压缩激活字节（例如 FP8→NVFP4）、或缩小 EP 组规模 N。</p>\n<p>举个具体例子：一个 EP=8 的组，每层 T 个 token、k=2、d 为隐藏维、b=1（FP8），在 NVLink 域内 B 较高，下界项 2Tkdb/B 很小；但若该层被跨域部署，B 换成 InfiniBand，带宽差一个数量级，下界立刻放大十倍，实测 All-to-All 远超原估计，SLO 直接击穿。这正是“把 NVLink 带宽当全局带宽代入”这一误用的典型后果——不是公式错了，是 B 取错了。</p>\n<p>从系统代价看，下界同时约束三件事：延迟（单层预算被通信吃掉多少）、吞吐（每 token 摊到的通信字节决定 batch 上限）、显存与带宽（激活缓冲区与打包缓冲的驻留量）。它还是判断“是否需要分离式预填/解码”和“是否值得上更激进的量化”的前置条件：只有当通信项在下界中占比显著时，压缩 b 才有回报；否则省下的字节会被固定开销吞掉。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-4\">四 · 常见误解之一：把 NVLink 带宽当成全局带宽</h3>\n<p>最普遍也最致命的误用，是在跨域场景里直接代入 NVLink 域内带宽。NVL72 内 NVLink 域与跨域 InfiniBand 的带宽差一个数量级，而公式里的 B_link 是“单卡可用互联带宽”，它必须按<strong>最慢链路</strong>重算。跨域部署时，dispatch 与 combine 的字节要穿过 IB，下界随之放大一个数量级；若仍按 NVLink 代入，容量规划会系统性偏乐观，实测与预估的差距不是几个百分点，而是成倍。</p>\n<p>工程判断很简单：先问“这一层的 EP 组是否跨越 NVLink 域”。若跨越，B 取 IB 的有效带宽，并接受下界被抬高的事实；此时应优先考虑缩小 EP 组、把专家放回域内、或改用层次化 All-to-All（域内 NVLink、域间 IB 两级）。若在域内，才可以用 NVLink 带宽做乐观估计。把这条判断写进容量评审清单，比事后调参便宜得多。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-5\">五 · 常见误解之二：忽略 b 的取值与 NVFP4 的 scale 开销</h3>\n<p>第二个高频错误出在 b 上。FP8 记 1 字节/元素是干净的；NVFP4 名义上约 0.5 字节/元素，但每个 block 还带 scale，实际字节数高于 0.5。若按 0.5 直接算“W4 省一半通信”，下界会被低估，实测 All-to-All 比预估慢，容量规划偏乐观。正确做法是把 scale 开销并入 b 的有效值，再代入公式；定性地说，NVFP4 的通信节省小于“位宽减半”的朴素直觉，因为 scale 是随数据一起搬的。</p>\n<p>这条误解的代价体现在吞吐预估上：b 被低估意味着每 token 的通信字节被低估，进而每卡可承载的 token 数被高估，单卡吞吐预估虚高。它与“小 batch 解码固定开销”叠加时更危险——小 batch 下 kernel 启动与打包/解包开销可超过带宽项，此时下界本身已失去指导意义，再叠加 b 的低估，规划就彻底脱离现实。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-6\">六 · 常见误解之三：把下界当成预测值，或以为重叠能突破它</h3>\n<p>第三种误解是把 T_a2a^min 当作“实际会花的时间”。它不是预测值：公式不含 kernel 启动、不含打包/解包、不含拥塞与协议开销，实测必然大于等于它。把它当预测值，会在小 batch 解码阶段吃大亏——那时固定开销超过带宽项，下界失去指导意义，仍按下界做容量规划会导致单卡吞吐预估虚高。</p>\n<p>与之配套的误解是“计算通信重叠可以突破下界”。重叠的真实作用是让实测时间<strong>逼近</strong> max 项，而不是低于它：字节必须搬完，链路带宽是物理量。因此评估一个重叠方案时，正确的问法是“实测离下界还有多少余量”，而不是“通信是否被隐藏”。余量越小，说明调度越接近理想；余量越大，说明还有 kernel 启动、打包、拥塞等开销可压缩。这个余量本身就是一个可观测的工程指标，比任何“重叠率”百分比都更能指导调优。</p>\n<p>最后一条边界要写进评审清单：公式假设全对称、无拥塞、无启动开销。一旦 EP 组跨越 NVLink 域与 IB 域，或 batch 小到固定开销主导，下界就从“约束”退化为“参考”。此时应改用实测剖面或更细的分层模型，而不是继续对解析式做外推。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-7\">七 · 下界什么时候不再成立：边界、失效条件与代价归属</h3>\n<p>把公式当成“性能预测器”是最容易踩的坑。它本质是一个<b>可行性判据</b>：给定互联带宽 B、激活字节数与复制因子，单层 All-to-All 存在一个不可突破的传输时间，重叠只能逼近。因此它的价值不在于告诉你“会跑多快”，而在于告诉你“再怎么加算力也没用”。一旦输入参数失真，判据就从“下界”退化为“乐观估计”，容量规划随之系统性偏乐观。下面按失效来源拆开讲。</p>\n<p><b>边界一：拓扑对称性假设。</b>公式默认所有链路同构、无拥塞。NVL72 机柜内 NVLink 域与跨域 InfiniBand 的带宽差一个数量级，一旦 EP 组跨越域边界，必须把 B 换成最慢链路重算，否则下界被高估。此时 ring 项 $$\\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}$$ 中的 N 也不再是“组内 GPU 数”这么简单——跨域跳的带宽与域内跳不同，单跳模型失效，实际应按分段链路分别求和时间再取 max。工程判断：先确认 EP 组是否落在单一 NVLink 域内，跨域就把并行度降下来或改成分层 All-to-All，而不是硬套公式。</p>\n<p><b>边界二：固定开销吞掉带宽项。</b>公式未计入 kernel 启动、token 打包/解包、索引重排与同步屏障。小 batch 解码时 T 很小，带宽项随 T 线性缩小，而固定开销基本不变，于是实测时间由启动延迟主导，下界失去指导意义。可用一个粗略判据：当 $$\\tfrac{2\\,T\\,k\\,d\\,b}{B_{\\text{link}}}$$ 与单次 kernel 启动加打包开销同量级时，下界不再约束实际耗时。此时优化方向从“省带宽”转向“合并 kernel、减少同步次数、把 dispatch 与 combine 融进同一个通信核”。</p>\n<p><b>边界三：字节数 b 的取值错误。</b>FP8 取 1 字节，NVFP4 约 0.5 字节但需额外携带 scale，实际字节数高于 0.5，若按 0.5 直接算通信节省，下界被低估、规划偏激进。反过来，忽略 scale 开销会把 W4 的收益算得过大。表里给出各精度下 b 的取值口径与对应代价归属：</p>\n<table class=\"mini\"><thead><tr><th>精度</th><th>b 取值口径</th><th>代价归属</th></tr></thead><tbody><tr><td>FP8</td><td>1 字节/元素</td><td>带宽项线性下降，下界随 b 同比缩小</td></tr><tr><td>NVFP4</td><td>≈0.5 字节/元素 + scale 开销</td><td>scale 使实际字节偏高，节省小于名义值</td></tr></tbody></table>\n<p><b>代价归属与误用后果。</b>三种失效模式对应三类系统代价：跨域误用 NVLink 带宽，实测 All-to-All 远超下界，SLO 直接击穿，表现为尾延迟尖刺而非均值恶化；小 batch 解码按下界规划，单卡吞吐预估虚高，实际受启动开销限制；NVFP4 scale 漏算，下界被低估，容量预留不足。判断准则很直接：若下界已接近层预算，增加计算资源无益，应改路由策略、降 k、压缩激活字节或缩小 EP 组；若下界远小于层预算而实测仍慢，问题在固定开销或拥塞，不在带宽。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-8\">八 · 下界成立的前提与它失效的三个现场</h3>\n<p>公式本身只做了一件事：把 dispatch 与 combine 两次交换折算成字节数除以链路带宽，再与 ring 单跳模型取最大值。它之所以能写成闭式，是因为假设了拓扑全对称、链路无拥塞、且传输期间没有别的流量抢带宽。这三个假设在 NVL72 机柜内基本成立——NVLink 域内任意两卡之间的可用带宽可视为同一量级，交换是结构化的、可预测的。但一旦 EP 组跨越 NVLink 域，假设立刻崩塌：跨域走 InfiniBand，带宽比域内 NVLink 低一个数量级，此时必须把 B_link 换成最慢那条链路的带宽重算，否则算出的下界只是域内理想值，与实测相差一个数量级，容量规划会直接偏乐观。判断方法很朴素：先看 EP 组是否被 NVL72 的 NVLink 域完整包住，包不住就按 IB 重算，不要用域内数字外推。</p>\n<p>第二个失效现场是固定开销。下界只计带宽项，未计 kernel 启动、token 打包/解包、路由排序与同步屏障的代价。解码阶段 batch 很小时，T 很小，带宽项随 T 线性缩小，而这些固定开销不随 T 缩小，于是实测时间被固定开销主导，下界不再有指导意义。工程上的判据是看带宽项与固定开销的量级关系：当 T·k·d·b 小到让 2Tkdb/B_link 落到与一次 kernel launch 同量级时，就该放弃用下界做容量决策，转而按固定开销加带宽项的加性模型估算。这也是为什么小 batch 解码的 MoE 推理，优化重点往往不在通信带宽而在减少 kernel 数量与合并打包步骤。</p>\n<p>第三个失效现场在 b 的取值上。FP8 时 b=1，NVFP4 时 b≈0.5，但 NVFP4 还带 scale 开销，实际每元素字节数高于 0.5。若按 0.5 直接算通信节省，会把下界算低，误以为 W4 能把 All-to-All 压到 FP8 的一半；真实字节数偏高，下界被低估，实测反而更接近 FP8 的量级。正确做法是把 scale 的额外字节摊进 b 再代入，而不是拿量化位宽除以 8 了事。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被破坏的假设</th><th>系统代价表现</th></tr></thead><tbody><tr><td>EP 组跨 NVLink 域</td><td>B_link 全域一致</td><td>实测远超下界，SLO 击穿</td></tr><tr><td>小 batch 解码</td><td>忽略固定开销</td><td>单卡吞吐预估虚高</td></tr><tr><td>NVFP4 未计 scale</td><td>b 取 0.5 即完</td><td>下界被低估，节省算错</td></tr></tbody></table>\n<p>把这三点合起来看，下界的真正用途不是预测实测值，而是做瓶颈判据：若下界已接近层预算，则加计算资源无益，应改路由策略、降 k、压缩激活字节或缩小 EP 组；若下界远低于层预算而实测仍高，则问题在固定开销或拥塞，不在带宽。公式给的是不可突破的地板，不是天花板，误把它当天花板用，才是这类容量规划最常见的翻车方式。</p>\n<h3 id=\"th-moe-alltoall-comm-bound-sec-9\">九 · 第一项：dispatch 与 combine 的字节账</h3>\n<p>公式第一项 <span class=\"formula-inline\">2Tkdb / B_link</span> 的分子不是“每张卡要发多少”，而是“整个 EP 组在单层内必须搬运的激活字节总量”。把 T 个 token 各自的隐状态按路由结果切开：每个 token 选中 k 个专家，每个专家需要看到完整的 d 维向量，于是该 token 向外发出的激活字节为 k·d·b。T 个 token 合计 T·k·d·b，这是 dispatch 方向的单向载荷。combine 方向把专家输出按原路由权重加权求和后送回原卡，载荷结构与 dispatch 对称，因此乘 2。分母 B_link 是单卡可用互联带宽（字节/秒），在“全组同时开火、链路无争用”的理想假设下，总字节除以总带宽即得秒。</p>\n<p>这里有一个容易被读漏的工程含义：分子里的 T 是“本层参与路由的 token 数”，不是序列长度，也不是 batch 内请求数。连续批处理下，一个 decode step 里 T 等于当前在跑的 token 总数（每请求一个），prefill 阶段则等于本 chunk 的 token 数。同一套权重、同一个 EP 组，prefill 的 T 可以是 decode 的几十倍，第一项随之线性放大——这正是分离式部署要把预填与解码拆到不同资源池的算术根源。举例：某层 d=7168、k=8、FP8（b=1），decode 时 T=256，则单向载荷 256×8×7168×1 ≈ 14.7 MB，双向约 29.3 MB；若 B_link 取 NVLink 域内单卡量级（数百 GB/s），该项落在几十微秒量级；同样配置下 prefill chunk 取 T=8192，双向载荷逼近 940 MB，该项直接进入毫秒量级，成为层预算的主项。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-10\">十 · 第二项：ring 单跳为什么带 (N-1)/N</h3>\n<p>第二项 <span class=\"formula-inline\">Tkdb(N-1) / (N·B_link)</span> 描述的是 ring（或等价的多跳转发）拓扑下，同一批载荷走完全组所需的单跳时间。推导的关键在于“每跳谁在出力”：ring 上每个 token 的激活数据要经过 N-1 次转发才能到达全部 N 张卡，而每一跳由 N 张卡同时承担发送，故单跳的有效载荷被放大 (N-1)/N 倍——直观地说，N 张卡分摊 N-1 跳的转发量，单卡每跳只需搬总载荷的 (N-1)/N。注意第二项没有因子 2：ring 的 dispatch 与 combine 在时间上串行，公式取的是“单方向走完全程”的那一跳耗时，两项取 max 后，因子 2 已被第一项吸收，读者不应再把 2 乘到第二项上，否则会把下界算成两倍。</p>\n<p>两项取 max 的物理含义是：全互连（NVLink 域内 all-to-all 直连）受限于“总字节/总带宽”，ring 受限于“最慢那一跳的转发量”，实际硬件走哪条路径，下界就取哪条路径的约束。N 越大，(N-1)/N 越接近 1，ring 项趋近于 Tkdb/B_link，与第一项同量级；N 很小时（如 EP=2、EP=4），(N-1)/N 明显小于 1，ring 项反而宽松，此时第一项主导。这解释了一个常见现象：小 EP 组内 all-to-all 几乎不构成瓶颈，而 EP 扩到几十、上百卡后，通信项迅速吃掉层预算。工程判断上，若某层实测耗时已贴近 max 项，继续加卡只会让 (N-1)/N 更接近 1、第一项不变，收益为零。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-11\">十一 · 推导关键步：两次交换 + 一次取 max</h3>\n<p>完整推导可压缩为三步伪代码思路：</p>\n<ul>\n<li>步一，把单层 MoE 拆成 dispatch 与 combine 两次全互连交换，每次交换的载荷为 T·k·d·b 字节；</li>\n<li>步二，对每次交换按“字节数 ÷ 单卡带宽”得理想传输时间，两次相加得 2Tkdb/B_link；</li>\n<li>步三，对 ring 路径单独算单跳转发时间 Tkdb(N-1)/(N·B_link)，与步二结果取 max，得到与拓扑无关的可比较解析式。</li>\n</ul>\n<p>这一步“取 max”是整条推导的枢纽：它把“拓扑差异”从一个需要逐跳建模的复杂问题，压缩成一个上界可比的闭式表达。代价是丢失了拓扑细节——真实 all-to-all 在拥塞、非对称链路、多轨 IB 下会出现排队，实测时间只会大于等于该 max，绝不会小于。因此该式的定位是“不可突破的下界”，不是“预测值”。系统代价上，它给出的是单层通信的时间地板：若层预算为 L，则必须满足 max 项 ≤ L，否则无论计算多快，该层都过不了 SLO。举例：某解码层预算 200 μs，算得 max 项 180 μs，则计算与通信重叠最多把实测压到 180 μs 附近，剩余 20 μs 是留给 kernel 启动与打包/解包的余量；一旦固定开销超过 20 μs，下界就失去指导意义。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-12\">十二 · 离散化与近似：公式在哪里失真</h3>\n<p>该式是连续流体近似，至少在三处与硬件离散性脱节。其一，字节被当作可无限细分的连续量，而实际传输以 packet/消息为单位，小消息的固定头开销与握手延迟不随字节缩放；当 T·k·d·b 小到单条消息量级（小 batch 解码），带宽项让位于延迟项，公式高估了通信效率。其二，B_link 被当作常数，但 NVLink 域内与跨域 InfiniBand 差一个数量级，且 IB 的多轨、自适应路由会让有效带宽随流数变化；跨域部署必须按最慢链路重算 B，否则下界被系统性高估。其三，b 的取值本身是近似：FP8 取 1 字节干净，NVFP4 标称约 0.5 字节，但每元素还带 scale 开销，实际字节数高于 0.5·元素数，若按 0.5 直接代入会把通信节省算多、下界算低。</p>\n<p>此外，公式假设 dispatch 与 combine 的载荷严格对称，而实际实现中 combine 常需携带路由权重、且部分框架对专家输出做原地累加，字节结构并非完全镜像；公式假设全组同时开火、链路无争用，而真实集群里 all-to-all 与 P2P、KV 传输共享链路，拥塞使实测偏离下界。这些近似不影响公式作为“地板”的合法性——地板只会被突破不了，不会被高估到失效——但影响它作为容量规划输入的可信度：跨域、小 batch、NVFP4 三种场景下，必须对公式做修正再代入。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-13\">十三 · 代入前的三项修正与一个判据</h3>\n<p>工程上把公式用于容量决策前，做三项修正：把 B_link 换成部署路径上最慢链路的实测有效带宽（NVL72 域内与跨域 IB 分别取值，跨域场景取 IB）；把 b 换成含 scale 的实际每元素字节数（NVFP4 按标称 0.5 加 scale 摊销后的值）；对小 batch 解码额外加一项固定开销 T_fixed（kernel 启动 + 打包/解包），判据变为 max 项 + T_fixed ≤ 层预算。三项修正后，公式从“理想地板”变成“可指导扩容的保守地板”。</p>\n<p>一个具体判据：若修正后的 max 项已占层预算七成以上，则增加计算资源无益，应转向降 k、压缩激活字节（换更低位宽）、缩小 EP 组或改路由策略；若 max 项不足三成而实测仍超预算，瓶颈在固定开销或拥塞，应查 kernel 启动次数与链路争用，而非加卡。这个判据把公式从“算一个数”变成“分流决策”：通信项主导时改通信，固定开销主导时改实现。小 batch 解码阶段，T_fixed 常超过带宽项，此时公式退化为“固定开销地板”，仍应按 T_fixed 做容量规划，而不是按带宽项预估单卡吞吐——这正是把 NVLink 带宽直接代入跨域场景、或忽略 NVFP4 scale 开销这两种误用之外，第三种让下界失去意义的失效路径。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-14\">十四 · 下界公式的适用边界：它在哪里成立，又在哪里失效</h3>\n<p>该解析式的价值不在于给出精确预测，而在于给出一个“不可突破”的判据：只要实测 All-to-All 时间显著高于该 max 项，就说明瓶颈不在带宽而在别处（拥塞、打包开销、kernel 启动、路由不均衡）。反过来，一旦实测已经贴近下界，继续堆计算资源或换更快的 kernel 都是无效投入，唯一有效的杠杆是降低公式右侧的某个因子。因此工程上真正要问的不是“下界是多少”，而是“当前部署是否落在公式的假设域内”。公式的假设域有三条：拓扑全对称、链路无拥塞、固定开销可忽略。三条中任意一条被破坏，max 项就不再是下界，而只是一个过于乐观的参考值。</p>\n<p>最典型的破坏来自拓扑非对称。公式中 B_link 被当作单一标量代入，这在单机 NVLink 域内成立，因为 NVL72 内部链路近似对称；但跨域部署时，dispatch 与 combine 的流量必须穿过 InfiniBand，其带宽比域内 NVLink 低一个数量级。此时若仍用 NVLink 带宽代入，max 项会被系统性低估，实测值远超“下界”，容量规划随之偏乐观。正确做法是把 B_link 换成最慢链路的可用带宽重算，并注意跨域场景下 ring 单跳项与全互连项的相对大小会翻转——域内 ring 项可能不是瓶颈，跨域后它成为主导项。工程判断是：先确定 EP 组是否跨越 NVLink 域边界，再决定用哪个 B 代入，这一步错了后面所有推导都无意义。</p>\n<p>第二条破坏来自固定开销。公式只计带宽项，未计 kernel 启动、token 打包/解包、路由元数据交换。小 batch 解码阶段，T 很小，带宽项随之缩小，而固定开销不随 T 缩放，于是固定项可能超过带宽项，此时 max 项不再具有指导意义——实测时间由启动延迟主导，降 k 或压缩字节数收效甚微，真正有效的是合并 kernel、减少 All-to-All 调用次数、或改用更大 batch 摊薄固定成本。第三条破坏来自字节数 b 的取值。FP8 下 b=1，NVFP4 下名义值约 0.5，但 scale 开销必须计入，实际每元素字节数高于 0.5；若按 0.5 直接计算通信节省，会低估真实字节数，从而低估下界，误判“压缩精度已解决带宽瓶颈”。下表把三条失效条件与对应修正动作并列，便于在容量评审时逐条核对。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式中被破坏的假设</th><th>后果</th><th>修正动作</th></tr></thead><tbody><tr><td>EP 组跨 NVLink 域</td><td>B_link 为单一对称带宽</td><td>下界被低估，实测远超</td><td>按 IB 带宽重算，重判主导项</td></tr><tr><td>小 batch 解码</td><td>固定开销可忽略</td><td>带宽项失去主导，下界无意义</td><td>合并调用、增大 batch、摊薄启动</td></tr><tr><td>NVFP4 未计 scale</td><td>b 为纯元素字节</td><td>字节数偏低，下界被低估</td><td>按含 scale 的实际字节重算</td></tr></tbody></table>\n<p>把这三条合起来看，公式的定位应当明确：它是容量决策的第一道筛子，而不是最终预测器。用法是先用它判断某层 MoE 的 All-to-All 是否已逼近层预算——若下界本身已接近 SLO 允许的单层耗时，则增加计算资源无益，应转向降 k、压缩激活字节、缩小 EP 组或改路由策略；若下界远低于预算而实测却贴着预算，则瓶颈在固定开销或拥塞，优化方向是 kernel 融合与拓扑收敛，而非带宽。真正需要警惕的失败模式是把 NVLink 域内带宽当作全局带宽代入跨域场景，此时公式给出的是一个漂亮的、但完全不成立的下界，SLO 会在真实流量下直接击穿。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-15\">十五 · 下界失效的三种现场：拓扑、粒度与字节口径</h3>\n<p>公式取 max 的结构本身已经暴露了它的软肋：第一项是理想全互连的字节传输时间，第二项是 ring 单跳的转发放大，两者都建立在“链路带宽处处相同”的前提上。一旦 EP 组跨越 NVL72 的 NVLink 域边界，这个前提就崩了——域内 NVLink 与跨域 InfiniBand 差一个数量级，此时必须把 B_link 换成最慢链路重算，而不是沿用域内带宽。工程上更稳妥的做法是把下界拆成域内项与跨域项相加：域内按 NVLink 带宽算 dispatch/combine，跨域按 IB 带宽算一次全互连，两项串联而非取 max。否则容量规划会系统性偏乐观，实测 All-to-All 远超下界，SLO 直接击穿。</p>\n<p>第二个失效点是粒度。推导把 T 个 token 的激活视为连续字节流，隐含“打包/解包与 kernel 启动开销可忽略”。小 batch 解码时这一条不成立：每层 dispatch 的固定开销（元数据交换、索引重排、kernel launch）与 token 数无关，当 T 很小时它会超过带宽项，此时下界不再是瓶颈判据，而应改用“固定开销 + 带宽项”的加性模型。判断阈值的方式很直接：令固定开销为 c，则带宽项 2Tkdb/B 与 c 相等时的 T 即为分界点，低于该点谈下界没有意义。</p>\n<div class=\"formula\">$$T_{\\text{a2a}}^{\\min} \\;\\approx\\; c \\;+\\; \\max\\!\\Big(\\tfrac{2Tkdb}{B_{\\text{link}}},\\ \\tfrac{Tkdb\\,(N-1)}{N\\,B_{\\text{link}}}\\Big)$$</div>\n<p>第三个失效点是字节口径 b。FP8 取 1 字节是干净的，NVFP4 却约 0.5 字节再加 scale 开销，scale 的元数据随分组粒度上升而膨胀，实际每元素字节数高于 0.5。若按 0.5 直接算通信节省，下界会被低估，容量决策随之偏激进。表里给出三种口径在同一层上的相对量级，便于在路由策略与精度选择之间做取舍。</p>\n<table class=\"mini\"><thead><tr><th>精度口径</th><th>b 的取值</th><th>对下界的影响</th></tr></thead><tbody><tr><td>FP8</td><td>1</td><td>基准</td></tr><tr><td>NVFP4（忽略 scale）</td><td>≈0.5</td><td>下界被低估</td></tr><tr><td>NVFP4（含 scale）</td><td>&gt;0.5</td><td>需按实际分组重算</td></tr></tbody></table>\n<p>由此得到的工程判断是：下界只在“大 batch、域内、口径正确”三者同时成立时才具备指导力；任一条件破坏，就该改用加性模型或按最慢链路串联重算，而不是继续拿它当 SLO 预算的锚点。</p>\n<h3 id=\"th-moe-alltoall-comm-bound-sec-16\">十六 · 全对称假设：公式成立的最小拓扑条件</h3>\n<p>公式两项都建立在一个未写明的隐含前提上：专家并行组内任意两张卡之间的可用带宽相同，且交换网络不存在热点。第一项把 dispatch 与 combine 压缩成「字节数除以 B_link」，这一步只有在每条链路的有效带宽都等于 B_link 时才成立；第二项 ring 单跳模型进一步假设 N 张卡均匀分摊带宽、N-1 跳转发无额外排队。真实集群里这两个假设同时成立的情形很少：机内 NVLink 域是全对称的，一旦 EP 组跨越 NVLink 域边界进入 InfiniBand，对称性立刻破裂。</p>\n<p>工程上可操作的判据是构造一个加权带宽向量：把 EP 组内每对卡之间的有效带宽排成矩阵，取其中的最小值 B_min 与公式里的 B_link 比较。若 B_min 明显低于组内中位数，则公式给出的下界只是「理想拓扑下界」，实际可达下界应改用 B_min 重算。更严格的做法是把公式改写成按链路分段的求和形式：把 token 流按目的卡分组，每组字节数除以该组链路带宽再求和，取最大值。这一步把「全对称」从假设变成了可检验的量。</p>\n<p>代价体现在容量规划的方向性上：用中位带宽算出的下界偏乐观，会让工程师误判「通信不是瓶颈」，从而把预算投到计算侧；用 B_min 算出的下界偏保守，会过早触发缩组或降 k 的决策。两种误差都不是数值精度问题，而是拓扑认知问题。一个具体例子：EP 组为 16 卡、其中 8 卡同机、8 卡跨机，跨机链路带宽比机内低一个数量级，此时按机内带宽代入公式得到的单层下界与按跨机链路重算的结果相差数倍，前者对应的层预算根本无法达成。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-17\">十七 · 无拥塞假设：从「独占带宽」到「共享带宽」</h3>\n<p>公式默认 All-to-All 独占链路带宽。实际推理系统中，同一时刻可能有多个请求的 MoE 层在跑，连续批处理把不同 batch 的 token 混在同一批 kernel 里，All-to-All 与其他集合通信（如 TP 的 All-Reduce、DP 的梯度同步在推理中通常不存在，但 KV 传输、分离式部署的 P/D 搬运会争用同一张网卡）共享物理链路。此时有效带宽不再是 B_link，而是 B_link 除以并发流数再乘以效率因子。</p>\n<p>可以把拥塞建模为一个乘性惩罚：设同一链路上并发占用该链路的流数为 m，链路利用率上限为 η，则有效带宽 B_eff = η·B_link/m。代入第一项得到 T_a2a ≥ 2Tkdb/(η·B_link/m)。这个式子的意义不在于精确预测，而在于揭示标度关系：并发翻倍，下界翻倍。它解释了为什么在高压吞吐场景下，实测 All-to-All 时间会随并发线性上升而不是停在某个平台——下界本身在随并发移动。</p>\n<p>系统代价是吞吐与延迟的耦合：连续批处理提高吞吐的同时抬高了 m，从而抬高了下界；若调度器不感知这一点，会出现「加大 batch 反而单 token 延迟更差」的非单调现象。一个具体机制是 NCCL 的 ring 算法在检测到链路争用时不会自动降级为 tree，仍按 ring 顺序转发，导致每跳都在排队。工程判断是：在 EP 组跨越共享 IB 交换机的部署中，应把 m 作为调度器的显式状态，而不是让下界公式在事后解释为什么 SLO 被击穿。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-18\">十八 · 固定开销：小 batch 解码时下界失去意义</h3>\n<p>公式只含带宽项，不含 kernel 启动、打包/解包、路由结果排序与同步屏障的固定开销。解码阶段 T 很小（每步每请求通常只有个位数 token），带宽项随之缩小，而固定开销不随 T 缩小。当固定开销超过带宽项时，公式给出的下界低于实际可达时间，甚至低于单次 kernel 启动的延迟，此时下界不再具有指导意义。</p>\n<p>可写出一个带固定开销的修正形式：T_a2a ≥ max(2Tkdb/B_link, (N-1)Tkdb/(N·B_link)) + c_launch + c_pack，其中 c_launch 为 kernel 启动与屏障开销，c_pack 为路由结果的打包/解包开销。判据是看两项的相对大小：当 2Tkdb/B_link 与 c_launch 同量级时，公式进入失效区。由于 c_launch 与硬件和框架实现强相关，工程上应实测单次空 All-to-All 的耗时作为 c_launch 的下限估计，而不是从公式反推。</p>\n<p>代价体现在单卡吞吐预估上：小 batch 解码时若仍按下界做容量规划，会得出「通信开销可忽略」的结论，进而高估单卡可承载的并发请求数。一个具体例子：EP 组为 8 卡、每步每卡仅处理少量 token，带宽项对应的传输时间远小于一次 kernel 启动加两次打包解包的耗时，此时实测 All-to-All 时间由固定开销主导，公式预测的下界与实际相差一个量级。正确的做法是在解码场景改用「固定开销 + 带宽项」的加性模型，并把 c_launch 作为容量表的一等参数。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-19\">十九 · 字节数 b：NVFP4 的 scale 开销与压缩收益的错算</h3>\n<p>b 的取值直接进入两项的分子，是最容易被误用的变量。FP8 时 b=1，NVFP4 时名义上 b≈0.5，但 NVFP4 需要伴随 scale 因子与分组元数据，实际每元素有效字节数高于 0.5。若按 0.5 代入公式计算通信节省，会系统性低估字节数，从而低估下界，得出「量化到 NVFP4 后通信不再是瓶颈」的错误结论。</p>\n<p>可把有效字节数写成 b_eff = b_data + b_meta/g，其中 b_meta 为每组 scale 与元数据的字节数，g 为分组粒度。代入第一项得 T_a2a ≥ 2Tkdb_eff/B_link。这个式子的工程价值在于把「量化收益」拆成数据位宽收益与元数据开销两部分：分组粒度越细，元数据占比越高，压缩收益被侵蚀得越多。判据是看 b_meta/g 相对于 b_data 的比例，比例越高，NVFP4 相对 FP8 的通信节省越有限。</p>\n<p>代价是显存与带宽的双向影响：NVFP4 降低激活字节数的同时，反量化需要在专家计算前插入转换 kernel，这部分开销不在 All-to-All 公式内，但会占用同一张卡的 SM 与寄存器资源，间接拉长层预算。一个具体机制是 tcgen05 路径上 NVFP4 的 MMA 需要 scale 参与，若 scale 在 All-to-All 之后才生成，则 combine 方向仍需搬运 FP8 或更高精度数据，b 在两个方向上不一致，公式的单一 b 假设失效。此时应按 dispatch 与 combine 分别取 b，把第一项改写为 T·k·d·(b_dispatch + b_combine)/B_link。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-20\">二十 · 规模上限：N 增大时两项的相对变化</h3>\n<p>两项随 N 的变化方向不同。第一项与 N 无关，只随 T、k、d、b 线性增长；第二项的 (N-1)/N 因子随 N 增大趋近于 1，因此第二项随 N 增大而趋近于 Tkdb/B_link，即第一项的一半。这意味着在大 N 时 max 由第一项主导，ring 单跳模型不再约束下界；在小 N 时两项接近，拓扑差异才显著。规模上限的第一个含义是：当 N 大到一定程度，公式对拓扑的敏感度下降，下界主要由激活字节数与单卡带宽决定。</p>\n<p>但 N 增大带来另一个失效源：EP 组越大，跨越 NVLink 域边界的概率越高，B_link 的一致性越难保证。NVL72 的域内带宽与跨域 InfiniBand 带宽差一个数量级，当 N 超过单机域容量时，公式必须按最慢链路重算，否则下界被高估。可写出分段形式：设组内 n_fast 张卡走高速链路、n_slow 张卡走慢速链路，则有效下界为 max(2Tkdb/B_fast 作用于快链路部分, 2Tkdb/B_slow 作用于慢链路部分)，取两者最大值。这个分段式说明规模上限不是某个具体 N 值，而是「EP 组是否仍落在单一全对称域内」这一拓扑事实。</p>\n<p>代价是容量决策的拐点：当 EP 组刚好跨域时，下界跳变，原本充裕的层预算突然吃紧，增加计算资源无益，应缩小 EP 组、降 k 或压缩激活字节。一个具体例子：NVL72 整机架内 EP 组全在 NVLink 域内，公式按域内带宽成立；一旦把 EP 组扩到跨机架、经 InfiniBand 互联，按域内带宽算出的下界与按 IB 带宽算出的下界相差一个数量级，此时容量规划必须切换 B 的取值，并把「是否跨域」作为 EP 组规模的第一约束而非事后修正。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-21\">二十一 · 失效条件的工程判据与替代模型</h3>\n<p>把上述边界收敛成一组可执行的判据，比记住公式本身更有用。判据一：检查 EP 组内链路带宽矩阵的最小值与中位数之比，比值偏离 1 则启用 B_min 或分段求和。判据二：检查同一链路上的并发流数 m 与链路利用率 η，把 B_eff 代入而非 B_link。判据三：比较带宽项与实测空 All-to-All 耗时，前者不大于后者时进入固定开销主导区，改用加性模型。判据四：核对 b 的取值是否含 scale 与元数据，dispatch 与 combine 是否同精度。判据五：确认 EP 组是否跨越 NVLink 域边界，跨域即按最慢链路重算。</p>\n<p>每条判据对应一个替代模型：分段求和替代单一 B_link，B_eff 替代 B_link，加性模型替代纯带宽项，b_eff 替代 b，分段 max 替代全局 max。这些替代模型并不推翻原公式，而是把原公式的假设显式化，让下界从「理想拓扑下的理论值」变成「当前部署下的可达值」。工程判断的分界线在于：当下界已接近层预算时，增加计算资源无益，应改路由策略、降 k、压缩激活字节或缩小 EP 组；当下界远低于层预算时，公式的精确度不重要，粗算即可支撑决策。</p>\n<p>最后一个具体机制落在路由策略上：top-k 路由的 k 直接进入两项分子，降 k 是缩小下界最直接的手段，但会改变模型质量，属于算法侧决策而非系统侧；系统侧能做的是把 k 个专家的激活数据按目的卡聚合后再打包，减少打包/解包次数，从而压低 c_pack。这一动作不改变带宽项，但能把固定开销主导区向左推，使公式在更小的 batch 上仍然有效。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-22\">二十二 · 边界之外：下界在什么条件下失去指导意义</h3>\n<p>该下界把拓扑压缩为一个解析式，代价是它默认了全对称、无拥塞的理想交换网络。一旦部署跨越 NVL72 的 NVLink 域边界，这个假设立刻破裂：域内 NVLink 与跨域 InfiniBand 的可用带宽相差一个数量级，而公式中的 <span class=\"sym\">B</span> 是单卡可用互联带宽的单一标量。跨域时必须以最慢链路重算，否则 dispatch 阶段在 IB 上的实际耗时会被系统性低估，容量规划偏乐观。工程判断很简单：先确定 EP 组是否完全落在同一 NVLink 域内，若跨域，把 <span class=\"sym\">B</span> 替换为 IB 侧有效带宽后重算两项，再取 max。此时 ring 单跳项往往不再是约束，瓶颈转移到跨域链路的字节吞吐。</p>\n<p>第二个失效条件是固定开销压过带宽项。下界只计入了传输时间，未计入 kernel 启动、token 打包与解包、路由元数据交换。小 batch 解码阶段，<span class=\"sym\">T</span> 很小，带宽项随之缩小，而每次 All-to-All 的启动与打包开销基本不随 <span class=\"sym\">T</span> 缩放。当固定开销超过带宽项时，实测时间由开销主导，下界不再具备预测力。此时应改用“固定开销 + 带宽项”的复合模型，或直接以实测微基准替代解析式做容量决策。伪代码思路：若 <span class=\"sym\">T</span> 低于某阈值，则判定下界失效，切换到实测标定。</p>\n<div class=\"formula\">$$T_{\\text{real}} \\;\\approx\\; T_{\\text{a2a}}^{\\min} \\;+\\; T_{\\text{fixed}},\\qquad T_{\\text{fixed}} \\gg T_{\\text{a2a}}^{\\min}\\ \\text{when}\\ T\\ \\text{is small}$$</div>\n<p>第三个边界在字节数 <span class=\"sym\">b</span> 的取值。FP8 为 1 字节，NVFP4 约 0.5 字节，但后者附带 scale 开销，实际每元素字节数高于 0.5。若按 0.5 直接代入，下界被低估，通信节省被高估。规模上限方面，公式对 <span class=\"sym\">N</span> 的依赖体现在 ring 项的 <span class=\"sym\">(N-1)/N</span> 因子，随 <span class=\"sym\">N</span> 增大趋近 1，意味着扩大 EP 组并不能通过分摊降低单跳载荷，反而增加跳数与元数据开销。当 <span class=\"sym\">N</span> 增大到跨域、且 <span class=\"sym\">k</span> 与 <span class=\"sym\">d</span> 不变时，通信量随 <span class=\"sym\">N</span> 线性增长而带宽不变，下界随之抬升，此时缩小 EP 组或降低 <span class=\"sym\">k</span> 比增加计算资源更有效。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>后果</th><th>工程对策</th></tr></thead><tbody><tr><td>跨 NVLink 域，仍用域内带宽</td><td>下界被低估，SLO 击穿</td><td>按 IB 最慢链路重算 B</td></tr><tr><td>小 batch 解码，固定开销主导</td><td>单卡吞吐预估虚高</td><td>改用固定开销 + 带宽项复合模型</td></tr><tr><td>NVFP4 忽略 scale 开销</td><td>字节数偏低，节省被高估</td><td>按实际打包字节数代入 b</td></tr></tbody></table>\n<h3 id=\"th-moe-alltoall-comm-bound-sec-23\">二十三 · 把下界翻译成批大小上限</h3>\n<p>容量决策的第一问通常是“这个 EP 组能吃多大的批”。把公式反过来用即可：给定层预算 <span class=\"inline-math\">\\(T_{\\text{budget}}\\)</span>（单层允许的墙钟时间），令下界不超过预算，解出 T 的上限。取 dispatch+combine 项为主时，</p>\n<div class=\"formula\">$$T \\;\\le\\; \\frac{T_{\\text{budget}}\\,B_{\\text{link}}}{2\\,k\\,d\\,b}$$</div>\n<p>这个式子的工程含义是：批大小与 k、d、b 成反比，与带宽成正比，与层预算成正比。它给出的是“带宽允许的最大 token 数”，不是“显存允许的最大 token 数”，两者取小才是真正可用的批。举例：某 MoE 层隐藏维 d=4096、k=8、FP8 即 b=1，EP 组内单卡 NVLink 可用带宽记为 B，层预算设为解码步预算的若干分之一；此时 T 的上限随 B 线性放大，而把 k 从 8 降到 4 直接把上限翻倍——这就是“降 k”在容量侧的定量依据，而不是经验口号。注意 b 的取值必须与量化方案对齐：NVFP4 的 0.5 字节/元素只是载荷，scale 开销要另计，按 0.5 直接代入会把 T 的上限算高，容量规划偏乐观。</p>\n<p>代价侧要同时看：批越大，单层通信时间线性上升，但单 token 摊销的通信成本下降，因此吞吐上升而单步延迟上升。容量决策不是选最大 T，而是选使 SLO 仍被满足的最大 T。若解出的 T 上限小于框架的最小有效批（受 kernel 效率与固定开销限制），说明该层的 EP 配置本身不适配当前 SLO，应改并行度而非硬调批。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-24\">二十四 · 定并行度：N 的两种角色</h3>\n<p>公式里 N 只出现在 ring 单跳项，且以 (N−1)/N 的形式单调趋近 1。这意味着在 ring 模型下，增大 EP 组规模对单跳有效载荷的放大是收敛的：N=2 时为 0.5，N=8 时为 0.875，继续增大收益递减。但增大 N 的真实代价不在这一项，而在跨域：当 EP 组跨越 NVL72 的 NVLink 域时，B 必须换成 InfiniBand 的单卡可用带宽，而两者差一个数量级。于是并行度决策变成一个分段判断：</p>\n<ul>\n<li>若 EP 组完全落在 NVLink 域内，N 的上限由域内 GPU 数决定，公式两项都用 NVLink 带宽，增大 N 主要摊薄每卡载荷、降低单卡通信时间，代价是路由均衡变差与专家利用率下降。</li>\n<li>若 EP 组被迫跨域，B 取 IB 带宽，下界整体抬升一个数量级，此时增大 N 换来的 (N−1)/N 收敛收益远不足以补偿带宽落差，正确动作是缩小 EP 组把流量关回域内，或改成分层并行（域内 EP + 域间复制）。</li>\n</ul>\n<p>算例：某层 T、k、d、b 固定，若把 EP 组从域内 8 卡扩到跨域 16 卡，第一项因 B 降一个数量级而放大十倍，第二项的 (N−1)/N 仅从 0.875 变到 0.9375，净效果是下界显著变差。这就是“跨域时须按最慢链路重算”的操作化表述：并行度不是越大越好，N 的取值必须与 B 的取值同域。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-25\">二十五 · 定 KV 预算：通信与显存的对偶</h3>\n<p>MoE 推理的显存预算里，KV cache 与专家权重是竞争关系。EP 组越大，单卡承载的专家权重越少，留给 KV 的空间越多；但如上节，N 增大受带宽域约束。把两者写成一条约束：单卡显存 = 专家权重分片 + KV 分片 + 激活与临时缓冲。EP 组扩大使专家权重分片按 1/N 缩小，释放出的显存可转为 KV 预算，但前提是通信下界仍在层预算内。于是 KV 预算的可用增量不是自由变量，而是被 <span class=\"inline-math\">\\(T_{\\text{a2a}}^{\\min}\\)</span> 约束的条件收益。</p>\n<p>具体机制：先按第一节解出带宽允许的 T 上限，再按 KV cache 容量式（见该条目）算出该 T 下的 KV 占用，两者取小得到可行批；若可行批受带宽限制而非显存限制，则增加 KV 预算是无效投资——多出来的显存换不来更大批，因为通信已经先饱和。反过来，若可行批受显存限制，则缩小 EP 组、把专家权重集中、腾出 KV 空间是正确方向，代价是通信下界上升，需重新校验层预算。这个对偶判断是容量规划里最容易被忽略的一步：很多部署把显存加满却测不到吞吐提升，原因就是下界已经先到顶。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-26\">二十六 · 定 SLO：下界作为可行性判据</h3>\n<p>SLO 通常以 TPOT 或端到端时延给出。把层预算按解码步拆到每层，得到单层允许时间；若 <span class=\"inline-math\">\\(T_{\\text{a2a}}^{\\min}\\)</span> 已接近或超过该预算，则该 SLO 在给定并行度下不可达，增加计算资源无益。判据写成：</p>\n<div class=\"formula\">$$\\text{可行} \\;\\Longleftrightarrow\\; T_{\\text{a2a}}^{\\min}(T,k,d,b,B,N) \\;\\le\\; \\frac{\\text{TPOT}_{\\text{SLO}}}{L}\\cdot\\alpha$$</div>\n<p>其中 L 为 MoE 层数，α 为该层可分得的预算占比（其余留给 attention、norm、采样等）。这个判据的价值在于它是否定性的：它能在不跑基准的情况下排除一批配置。例如跨域 EP 组在 IB 带宽下算出的下界若已超过层预算，则无论怎么调批、怎么量化，该 SLO 都不可达，必须改拓扑或改并行策略。反之，若下界只占预算的小头，则瓶颈在别处，优化应转向 attention 或调度。</p>\n<p>还要处理小 batch 解码的失效条件：此时 kernel 启动与打包/解包固定开销可超过带宽项，下界失去指导意义。工程判断是设一个交叉点——当 T 小到带宽项低于固定开销量级时，改用固定开销模型估时，而不是继续套下界。容量规划若在此区间仍按下界推算单卡吞吐，会得到虚高的预估。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-27\">二十七 · 一个完整算例</h3>\n<p>设某 MoE 层 d=4096、k=8、FP8 即 b=1，EP 组 N=8 且全部位于 NVL72 的 NVLink 域内。取 B 为单卡可用 NVLink 带宽（定性量级：域内带宽远高于跨域 IB）。层预算由 TPOT 拆得，设为该层可分得的固定份额。按第一节解 T 上限：T ≤ T_budget·B/(2·8·4096·1)。把 k 降为 4，上限翻倍；把 b 换成 NVFP4 并计入 scale 开销，上限提升但不到两倍——这正是“忽略 scale 会把节省算错”的定量体现。</p>\n<p>再校验 ring 项：N=8 时 (N−1)/N=0.875，若第一项为主则取第一项，第二项仅在 ring 拓扑且单跳成为约束时起作用。随后把解出的 T 代入 KV 容量式，若 KV 占用超过单卡余量，则实际批由显存封顶，通信未饱和，此时应缩 EP 组腾显存；若 KV 有余而 T 已到带宽上限，则通信饱和，应降 k 或压缩 b。最后用第四节判据复核：若下界占层预算比例已高，则该 SLO 下该配置接近不可行，需在“缩 EP 回域内”与“降 k”之间做取舍。整个流程不依赖任何实测数字，只依赖公式的单调性与带宽域的定性落差，因此可以在硬件到位前完成容量决策。</p>\n<p>算例的工程结论落在一点：批大小、并行度、KV 预算、SLO 四者不是独立旋钮，而是被同一个下界耦合。先算下界再分配资源，顺序反了就会得到“加显存不加吞吐”或“扩 EP 反而击穿 SLO”的结果。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-28\">二十八 · 把下界换算成容量决策：批大小、并行度、KV 预算与 SLO 的四个旋钮</h3>\n<p>这个下界真正的用处不是解释通信为什么慢，而是把「慢」提前折算成可分配的预算。做法是把单层下界乘以层数得到单 token 的 All-to-All 时间底账，再与目标 SLO 的 TPOT 上限相除，得到「通信可占用的时间份额」。设层数为 L、目标解码间隔为 τ，则每 token 的通信预算占比为 ρ = L·T<sub>a2a</sub><sup>min</sup>(T=1) / τ。ρ 一旦超过约三分之一，就意味着该 MoE 层的通信已经吃掉了解码预算的主体，此时增加计算卡只会让 GPU 空等，正确动作是降 k、压缩激活字节或缩小 EP 组。反过来，若 ρ 远小于该阈值，说明瓶颈在别处（KV 带宽、注意力 kernel），不应在 All-to-All 上做过度优化。注意 T 在解码阶段等于批内 token 数，因此 ρ 随批大小线性上升——这正是批大小不能无限拉高的原因：批越大，单层通信量越大，而 τ 是固定的 SLO 约束。</p>\n<p>由此得到定批大小的直接判据：把 T 当作待求量，令 L·max(2Tkdb/B, Tkdb(N−1)/(NB)) ≤ ρ·τ，解出 T ≤ ρ·τ·B / (L·k·d·b·max(2, (N−1)/N))。分母里的 max 项说明 ring 拓扑在 N 较大时第二项趋近于 1，此时 dispatch+combine 的因子 2 成为主导，批大小上限与 N 基本脱钩——这意味着扩大 EP 组并不自动放宽批大小约束，只是把每卡负载摊薄。定并行度时则相反：N 增大使每卡分摊的激活字节减少，但跨域风险随之上升。NVL72 内 NVLink 域与跨域 InfiniBand 带宽差一个数量级，一旦 EP 组跨越机架边界，公式中的 B 必须换成 IB 带宽重算，下界会整体抬高一个数量级，此时扩大 N 的收益被链路降级完全抵消。工程判断是：EP 组应尽量约束在单个 NVLink 域内，跨域只在模型规模迫使时才用，且必须按最慢链路做容量规划，而不是拿域内带宽代入。</p>\n<p>KV 预算与批大小是同一枚硬币的两面。批大小受通信下界约束，而 KV cache 受显存约束，两者取小者才是可持续的稳态批大小。设每 token 每层 KV 字节为 2·d·b<sub>kv</sub>（K 与 V 各一份），则批大小上限还受 (显存余量)/(L·2·d·b<sub>kv</sub>) 限制。当通信下界给出的 T 大于 KV 给出的 T 时，说明显存是瓶颈，此时压缩激活字节（FP8→NVFP4）对批大小毫无帮助，应转向 KV 量化或分页管理；反之当通信给出的 T 更小时，压缩 b 才有直接收益。这里有一个易错点：NVFP4 约 0.5 字节/元素，但还带 scale 开销，实际字节数高于纯 0.5，若按 0.5 直接算通信节省，会把下界低估，进而把批大小估得偏大，SLO 在真实负载下击穿。同理，FP8 取 1 字节是干净的，W4 的收益必须打折计入。</p>\n<p>算例：设某 MoE 模型 L=32 层，d=7168，k=8，EP 组 N=8 且全部位于单个 NVL72 NVLink 域内，激活用 FP8（b=1）。取单卡可用 NVLink 带宽 B 为域内典型值，按公式第一项估算单 token 单层通信量 2·1·8·7168·1 = 114688 字节，第二项为 114688·7/8 = 100352 字节，取 max 得约 114688 字节。若 B 取每秒数百 GB 量级，单层单 token 下界落在亚微秒到微秒之间，乘 32 层后每 token 通信底账约数十微秒。若 SLO 要求 TPOT 不超过数十毫秒，则 ρ 很小，通信不是瓶颈，批大小可放开到 KV 上限；但若把 EP 组扩到跨机架的 N=64，B 换成慢一个数量级的 IB，单层下界抬高约一个数量级，32 层底账随之进入毫秒级，ρ 迅速逼近阈值，此时应停止扩 N，改为降 k 或把激活压到 NVFP4（并计入 scale 开销）来换回预算。小 batch 解码是这套算法的失效区：当 T 很小时，kernel 启动与打包/解包的固定开销超过带宽项，下界不再有指导意义，此时应按实测固定开销做容量规划，而不是拿公式外推单卡吞吐。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>受下界约束的方式</th><th>失效/降级条件</th></tr></thead><tbody><tr><td>批大小 T</td><td>T ≤ ρ·τ·B / (L·k·d·b·max(2,(N−1)/N))</td><td>小 batch 时固定开销主导</td></tr><tr><td>并行度 N</td><td>N 增大摊薄每卡字节，但跨域须换 IB 带宽</td><td>EP 组跨 NVLink 域</td></tr><tr><td>KV 预算</td><td>与通信给出的 T 取小者</td><td>显存先于通信成为瓶颈</td></tr><tr><td>激活精度 b</td><td>FP8=1，NVFP4≈0.5 加 scale 开销</td><td>忽略 scale 导致下界低估</td></tr></tbody></table>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-29\">二十九 · 把下界当尺子用：批大小、并行度、KV 预算与 SLO 的联合定标</h3>\n<p>这个下界在容量决策里不是拿来预测实测值的，而是拿来当“不可逾越的墙”用：先算出每层 All-to-All 的 $T_{\\text{a2a}}^{\\min}$，再乘以层数得到单 token 的通信地板，与层计算预算相减，剩下的才是留给 GEMM、注意力与 KV 读写的余量。定批大小时，把 $T$ 当作自变量：$T$ 增大时下界线性上升，而 GEMM 吞吐随 $T$ 上升趋于饱和，于是存在一个交叉点 $T^{*}$，超过它通信项主导、时延按 token 线性膨胀。工程做法是解 $\\frac{2Tkdb}{B_{\\text{link}}} = \\alpha T_{\\text{compute}}$（$\\alpha$ 为该层计算时间占比上限），得到单层可容纳的最大 token 数，再除以在飞请求的平均长度即得批大小上限；连续批处理下这个上限还要按 decode 与 prefill 分别算，因为 prefill 的 $T$ 是整段 prompt、decode 的 $T$ 只是批内序列数。</p>\n<p>定并行度时，公式里 $N$ 只出现在 ring 项，且以 $(N-1)/N$ 的形式趋近 1，说明扩大 EP 组对单跳载荷的摊薄很快饱和，真正的代价是跨域。NVL72 内 NVLink 域与跨域 InfiniBand 带宽差一个数量级，一旦 EP 组跨越机柜边界，$B_{\\text{link}}$ 必须换成 IB 值重算，下界随之抬升一个量级。判断规则很直接：若某层在 NVLink 域内的下界已占层预算的可观比例，则把 EP 组扩到域外只会让下界更糟，此时应缩小 EP 组、把专家复制到域内，或降 $k$、压缩 $b$（FP8 的 1 字节与 NVFP4 的约 0.5 字节加 scale 开销要分开算，忽略 scale 会低估字节数、把下界算小）。KV 预算同理：MoE 层的 All-to-All 地板越高，留给 KV cache 的显存带宽与容量窗口越窄，解码期每 token 的通信时间直接吃掉了可承受的 KV 读取延迟，因此 KV 预算应按下界占 SLO 预算的比例反推，而不是先定 KV 再定并行。</p>\n<p>算例：某 MoE 层 $T=4096$、$k=8$、$d=7168$、FP8 即 $b=1$，NVLink 域内单卡可用带宽记为 $B_{\\text{link}}$，则 dispatch+combine 项为 $2\\times4096\\times8\\times7168/B_{\\text{link}}$ 字节除以带宽，量级在数 MB 级；若同一组跨到 IB，$B_{\\text{link}}$ 降一个数量级，该项时间相应放大十倍，SLO 直接被击穿。失效条件必须写进规划文档：小 batch 解码时 $T$ 只有几十，kernel 启动与打包/解包固定开销超过带宽项，下界失去指导意义，此时应按固定开销加带宽项的加性模型估算；拓扑非全对称、存在拥塞、或未计入打包开销时，实测只会高于下界，任何“按下界排容量”的结论都必须留出这部分余量。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>用法</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小</td><td>解 $T$ 使通信项等于计算预算</td><td>decode 下 $T$ 过小，固定开销主导</td></tr><tr><td>EP 并行度</td><td>域内按 NVLink 算，跨域按 IB 重算</td><td>组跨机柜后下界抬升一个量级</td></tr><tr><td>KV 预算</td><td>按下界占 SLO 比例反推</td><td>忽略 NVFP4 scale 开销</td></tr></tbody></table>\n<h3 id=\"th-moe-alltoall-comm-bound-sec-30\">三十 · 误用一：把 NVLink 域带宽当成全局带宽</h3>\n<p>这是本下界在工程上被误用频率最高的一类。公式里只有一个 <span>B<sub>link</sub></span>，看上去像是“这张卡能拿到多少带宽”，于是很多人顺手把 NVLink 的域内带宽填进去，算出单层 All-to-All 的理想耗时，再乘层数得到整网通信预算。问题在于：EP 组一旦跨出 NVLink 域，token 的 dispatch/combine 就要走 InfiniBand，而 NVL72 内 NVLink 域与跨域 IB 的带宽差一个数量级。公式本身没有错，错的是代入的 <span>B<sub>link</sub></span> 与真实拓扑不匹配——下界是对“最慢链路”成立的下界，不是对“最快链路”成立的下界。</p>\n<p>识别方法很直接：先画出 EP 组的物理落位，把组内通信拆成“域内跳”和“跨域跳”两段，分别用各自的带宽代入两项公式，再取整体最大值。若 EP 组规模大于单个 NVLink 域可容纳的 GPU 数，则跨域项必然主导，此时用域内带宽算出的数字不是下界，而是一个物理上不可达的乐观值。后果是容量规划偏乐观：按域内带宽估算，All-to-All 在层预算里只占很小一块，于是调度器敢把 batch 开大、敢把 EP 组开大；实测时跨域 All-to-All 远超预算，SLO 直接击穿，而增加计算资源毫无帮助——因为瓶颈在链路，不在 SM。</p>\n<p>一个具体例子：GB200 NVL72 单机架 72 卡共享 NVLink 域，若把 EP 组设为 72，域内 All-to-All 的 <span>B<sub>link</sub></span> 用 NVLink；一旦把 EP 组扩到跨两个机架，组内一部分 token 对必须经 IB 转发，公式第二项的 ring 单跳模型要用 IB 带宽重算，且 (N−1)/N 的放大因子随 N 增大趋近 1，意味着几乎全部激活字节都要过最慢的那条链路。此时下界数值会比域内估算高出一个数量级，层预算被通信吃满。工程判断：EP 组规模应以“不跨出 NVLink 域”为默认约束，跨域扩展必须显式按 IB 带宽重算下界，并把它当作硬约束写进容量模型，而不是当作一个可调的乐观参数。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-31\">三十一 · 误用二：忽略 NVFP4 的 scale 开销，把 b 当成 0.5</h3>\n<p>第二个高频误用发生在量化收益的估算上。公式里 <span>b</span> 是每元素字节数，事实给定 FP8 为 1 字节、NVFP4 约 0.5 字节“加 scale 开销”。很多工程估算直接把 0.5 代进去，得出“换 NVFP4 通信量减半”的结论，然后据此把 EP 组扩大一倍或把层预算砍半。这是把“元素位宽”当成了“线上字节数”。NVFP4 的每个量化块需要伴随 scale（以及可能的二级 scale），这些元数据同样要过链路，且它们不是按元素线性摊薄的——块越小，scale 占比越高。</p>\n<p>正确的做法是把 <span>b</span> 写成“有效载荷字节 + 元数据字节摊到每元素”的形式，再代入两项公式。识别信号：如果某个容量模型里 NVFP4 相对 FP8 的通信节省被写成精确的 2 倍，那它一定漏了 scale；真实的节省比例严格小于 2，且随量化块尺寸变化。后果有两层：其一，下界被低估，规划者以为通信不再是瓶颈，实际仍是；其二，压缩激活字节本来是缓解 All-to-All 的正当手段之一（与降 k、缩小 EP 组并列），但因为收益被高估，团队会在错误的层上投入量化工程，而真正该做的是先确认瓶颈是否真在链路上。</p>\n<p>具体例子：某层 <span>T</span> 个 token、<span>k</span> 个激活专家、隐藏维 <span>d</span>，FP8 下 dispatch+combine 项为 <span>2Tkdb/B</span>。切到 NVFP4 后若按 0.5 字节算，该项减半；但把 scale 摊回去后有效 <span>b</span> 高于 0.5，实际减幅小于一半。若这一层原本下界已接近层预算，减半的错觉会让人误判“已留出足够余量”，而真实余量不足以吸收跨域链路的劣化。工程判断：任何以 NVFP4 为依据的通信预算，都必须用“含 scale 的有效字节数”重算一遍下界，并把该有效值作为容量模型的输入常量固化下来，而不是每次口头按 0.5 折算。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-32\">三十二 · 误用三：小 batch 解码仍拿下界做容量规划</h3>\n<p>公式的适用边界里明确写了：未计入 kernel 启动与打包/解包开销；小 batch 解码时固定开销可超过带宽项，下界失去指导意义。这条边界最容易被忽略，因为解码阶段恰恰是 MoE 推理最常被容量规划关注的阶段。解码时 <span>T</span> 很小（每步每请求一个 token），带宽项 <span>2Tkdb/B</span> 随之很小，而 All-to-All 的固定成本——kernel 启动、路由结果的打包与解包、跨卡同步——不随 <span>T</span> 缩小。当固定开销超过带宽项时，实测耗时由固定开销主导，公式给出的数字不再是“不可突破的下界”，而是一个与实测无关的小量。</p>\n<p>识别方法：对目标 batch 规模估算固定开销的量级，与带宽项比较；若二者同阶或固定项更大，则下界不能用于容量决策。此时正确的建模对象是“固定开销 + 带宽项”的加性模型，且固定项应通过实测标定，而不是从公式推出。后果是单卡吞吐预估虚高：规划者按带宽项算出每步通信只需极短时间，于是认为解码吞吐由计算或 KV 带宽决定，把资源全押在计算侧；实测却发现每步被 All-to-All 的固定开销拖住，连续批处理也救不回来，因为固定开销与 batch 无关。</p>\n<p>具体例子：小 batch 解码、EP 组较大时，每层 All-to-All 的带宽项随 <span>T</span> 线性缩小，而打包/解包与 kernel 启动的次数随层数线性增长，两者量级在某个 batch 规模附近交叉。交叉点以下，增加 batch 能摊薄固定开销、提升吞吐；交叉点以上，带宽项重新主导，下界恢复指导意义。工程判断：容量规划应显式区分“固定开销主导区”和“带宽主导区”，在固定开销主导区用实测标定的加性模型，只在带宽主导区使用本下界；把两者混用是这一类误用的根源。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-33\">三十三 · 反例：一次跨域扩容的乐观规划</h3>\n<p>给出一个反例，把上述误用叠在一起看后果。场景：一个 MoE 解码服务，原本 EP 组落在单个 NVLink 域内，下界按域内带宽算，All-to-All 在层预算中占比可接受，SLO 达标。为提升吞吐，团队把 EP 组扩到跨域，同时把激活量化从 FP8 切到 NVFP4，理由是“通信量减半，跨域带宽劣势可被抵消”。容量模型里，<span>B<sub>link</sub></span> 仍填域内带宽（误用一），<span>b</span> 填 0.5（误用二），且模型只覆盖大 batch 预填场景，解码侧直接沿用同一下界（误用三）。三项叠加，模型给出的跨域 All-to-All 耗时与扩容前几乎持平，于是扩容被批准。</p>\n<p>实测结果：跨域 token 对走 IB，最慢链路带宽比域内低一个数量级，ring 单跳项按 IB 重算后远大于域内估算；NVFP4 的 scale 开销使有效 <span>b</span> 高于 0.5，减幅不及预期；解码小 batch 下固定开销又叠加在带宽项之上。三者共同作用，单层 All-to-All 实测耗时数倍于模型值，层预算被击穿，SLO 不达标，而 GPU 计算利用率反而下降——因为卡在等链路。此时增加计算资源无效，正确动作是缩回 NVLink 域内 EP 组、按 IB 带宽重算下界、并用含 scale 的有效字节数重估量化收益。</p>\n<p>这个反例的可迁移教训是：本下界的三个输入——<span>B<sub>link</sub></span>、<span>b</span>、适用 batch 区间——每一个都必须与部署拓扑和实际负载对齐，任何一个填错，下界就不再是下界，而是一个伪装成下界的乐观估计。识别这类错误不需要新理论，只需要在模型里对每个输入标注“取自哪条链路、含不含元数据、覆盖哪个 batch 区间”，三者缺一即视为不可信。</p>\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-34\">三十四 · 识别清单与工程落点</h3>\n<p>把识别动作固化成检查项，比事后复盘有效。对任何一份使用本下界的容量模型，逐项核对：其一，<span>B<sub>link</sub></span> 是否取自 EP 组实际经过的最慢链路，跨域时是否已按 IB 重算；其二，<span>b</span> 是否为含 scale 的有效字节数，NVFP4 是否按“小于 2 倍节省”处理；其三，模型覆盖的 batch 区间是否处于带宽主导区，小 batch 解码是否改用加性模型；其四，两项取 max 后是否与层预算比较，而非与整网预算比较；其五，是否把“重叠计算只能逼近不能突破”当作约束写进了调度假设，而不是当作可优化的余量。</p>\n<p>工程落点上，最值得固化的判断是：本下界的价值不在于给出一个精确数字，而在于给出一个“不可能低于”的硬边界，用来否决那些声称能靠加算力解决通信瓶颈的方案。一旦发现某层的下界已接近层预算，增加计算资源无益，应转向改路由策略、降 <span>k</span>、压缩有效激活字节或缩小 EP 组这四条路。反过来，若模型给出的下界远低于层预算，先别高兴——按上面五项核对一遍输入，尤其是跨域与 scale 两项，因为这两项最常把下界悄悄抬高一个数量级而模型作者不自知。</p>\n<p>最后落在具体机制上：把下界计算写成一个带输入校验的函数，输入包括拓扑描述（域内/跨域、链路类型）、量化格式（含 scale 的有效 <span>b</span>）、batch 区间标记；函数在跨域或小 batch 时拒绝返回“可用下界”，而是返回“需实测标定”的标记。这样误用不会以数字的形式悄悄进入容量决策，而是以显式的拒绝暴露出来。这是本下界在工程上唯一可靠的用法：不是算出一个数，而是守住一条不能被乐观输入污染的边界。</p>\n\n\n<h3 id=\"th-moe-alltoall-comm-bound-sec-35\">三十五 · 误用与反例：把下界当成可达性能</h3>\n<p>最常见的误用是把 <span class=\"formula-inline\">B_link</span> 无条件取成 NVLink 域内带宽，然后拿这个数去算跨域部署的 All-to-All 预算。公式里 <span class=\"formula-inline\">B_link</span> 是“单卡可用互联带宽”，一旦 EP 组跨越 NVL72 机柜边界，token 的 dispatch 与 combine 必须走 InfiniBand，而 IB 与 NVLink 差一个数量级，此时下界被系统性高估。反例：一个 EP 组按 NVLink 带宽算出单层 All-to-All 下界只占层预算的一小部分，容量规划据此认为“通信不是瓶颈”，于是把 EP 组开大到跨机柜；上线后实测 All-to-All 远超该下界，SLO 直接击穿——问题不在公式错，而在代入的 B 不是最慢链路。识别方法很简单：先画出 EP 组的物理拓扑，找出 token 实际经过的最慢一段链路，用它重算 B，再看下界是否仍低于层预算。</p>\n<p>第二个误用是忽略 b 的取值差异。FP8 下 b=1 字节，NVFP4 名义上约 0.5 字节，但每个 block 还要带 scale，实际每元素字节数高于 0.5；若直接按 0.5 计算 W4 的通信节省，字节数被低估，下界随之被低估，容量规划会误以为压缩精度已经买到了足够的通信余量。识别方式是回到打包后的真实 payload 字节数，而不是元素位宽除以 8。</p>\n<div class=\"formula\">$$T_{\\text{a2a}}^{\\min} \\;=\\; \\max\\Big(\\tfrac{2\\,T\\,k\\,d\\,b}{B_{\\text{link}}},\\; \\tfrac{T\\,k\\,d\\,b\\,(N-1)}{N\\,B_{\\text{link}}}\\Big)$$</div>\n<p>第三个失效条件出现在小 batch 解码：kernel 启动与打包/解包的固定开销可以超过带宽项，此时下界不再有指导意义。仍按下界做容量规划，会把单卡吞吐预估得虚高，因为真实耗时由固定开销主导，加卡、加带宽都救不回来。工程判断是：解码 batch 小到固定开销与带宽项同量级时，应改用降低 k、缩小 EP 组或换路由策略，而不是继续在带宽上做文章。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>本层参与路由的 token 数</td></tr><tr><td>k</td><td>每 token 激活专家数</td></tr><tr><td>d</td><td>token 隐藏维宽度</td></tr><tr><td>b</td><td>每元素字节数（FP8=1，NVFP4≈0.5 加 scale 开销）</td></tr><tr><td>B_{\\text{link}}</td><td>单卡可用互联带宽（NVLink 或 IB）</td></tr><tr><td>N</td><td>专家并行组内 GPU 数</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-moe-alltoall-comm-bound · 共 5 个片段</p>\n"},{"id":"th-nvfp4-moe-quant-error","title":"NVFP4 分组量化误差界","direction":"dir-expert-parallel-alltoall","prereq":[],"plain":"NVFP4 用 16 元素微块共享 E4M3 scale，量化误差由块内动态范围与 4 bit 尾数共同决定；块越小误差越小但 scale 开销越大，误差上界可写成块内最大值除以 2 的尾数位次方，直接决定 MoE 专家权重能否在 W4A16 下保持精度。","definition":"NVFP4 用 16 元素微块共享 E4M3 scale，量化误差由块内动态范围与 4 bit 尾数共同决定；块越小误差越小但 scale 开销越大，误差上界可写成块内最大值除以 2 的尾数位次方，直接决定 MoE 专家权重能否在 W4A16 下保持精度。","formula":"$$\\big|\\,w - \\hat{w}\\,\\big| \\;\\le\\; \\frac{\\max_{i\\in \\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2},\\qquad \\hat{w}=s\\cdot q,\\ s=\\frac{\\max|w_i|}{2^{m}-1}$$","variables":[{"sym":"w","meaning":"原始 FP16/BF16 权重元素"},{"sym":"\\hat{w}","meaning":"反量化后的权重元素"},{"sym":"s","meaning":"微块共享的 E4M3 scale"},{"sym":"q","meaning":"4 bit 量化整数码"},{"sym":"m","meaning":"尾数位宽（NVFP4 中 m=2，含隐含位共 3 位有效）"}],"derivation":"误差上界 $$|w-\\hat{w}|\\le\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}$$ 的推导关键一步：以块内最大绝对值定 scale 后，相邻量化格点间距为 s，舍入误差不超过半个格点，即 \\tfrac{s}{2}，代入 s 的表达式即得该界。","example":"用途：在推理容量决策中，该界用于判断某专家权重能否在 W4A16 下保持精度——若块内最大值过大导致有效尾数不足，则需缩小微块、改分组方式或对该专家保留 FP8，代价是显存与反量化开销上升。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["上界是逐元素最坏情况，未反映误差在专家输出上的累积；实际精度需用下游任务 perplexity 或路由一致性验证","假设块内分布无极端离群值；MoE 专家权重存在重尾时，单块 scale 被离群点拉高，其余元素有效位下降，界变松"],"system_note":"常见误用：把逐元素最坏界当作端到端精度保证，跳过 perplexity 与路由一致性验证；或忽略重尾分布下 scale 被离群点拉高的效应，误以为 16 元素微块在所有专家上误差一致。","papers":["paper-a-35b-hybrid-attention-mixture-of-ex-2026"],"facts":["直觉：NVFP4 把每 16 个权重元素划为一个微块，块内共享一个 E4M3 scale，元素本身只存 4 bit 整数码；块越小块内动态范围越窄、误差越小，但 scale 存储与反量化开销随之上升。","公式 $$\\hat{w}=s\\cdot q,\\ s=\\frac{\\max|w_i|}{2^{m}-1}$$ 中，w 为原始 FP16/BF16 权重元素，\\hat{w} 为反量化结果，s 为微块共享的 E4M3 scale，q 为 4 bit 量化整数码，m 为尾数位宽；NVFP4 中 m=2，含隐含位共 3 位有效。","误差上界 $$|w-\\hat{w}|\\le\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}$$ 的推导关键一步：以块内最大绝对值定 scale 后，相邻量化格点间距为 s，舍入误差不超过半个格点，即 \\tfrac{s}{2}，代入 s 的表达式即得该界。","适用边界：该界是逐元素最坏情况，未反映误差在专家输出上的累积；实际精度须用下游任务 perplexity 或路由一致性验证；公式假设块内分布无极端离群值，当 MoE 专家权重呈重尾时，单块 scale 被离群点拉高，其余元素有效位下降，界变松。","用途：在推理容量决策中，该界用于判断某专家权重能否在 W4A16 下保持精度——若块内最大值过大导致有效尾数不足，则需缩小微块、改分组方式或对该专家保留 FP8，代价是显存与反量化开销上升。","常见误用：把逐元素最坏界当作端到端精度保证，跳过 perplexity 与路由一致性验证；或忽略重尾分布下 scale 被离群点拉高的效应，误以为 16 元素微块在所有专家上误差一致。"],"anchors":["16 元素","E4M3","4 bit","m=2","3 位有效","W4A16"],"pitfalls":["把逐元素最坏误差界当作端到端精度保证，未做 perplexity 与路由一致性验证，上线后 MoE 专家输出漂移、路由翻转。","专家权重重尾时单块 scale 被离群点拉高，其余元素有效位下降，仍按均匀分布估算误差，量化后精度骤降。","为压低误差盲目缩小微块，scale 存储与反量化开销上升，显存与带宽收益被抵消，W4A16 部署容量反而下降。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-1\">一 · 一句话直觉：把动态范围切成十六份，用共享标尺换掉逐元素指数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-2\">二 · 严格定义：微块、共享 scale 与反量化映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-3\">三 · 误差上界的推导：半个格点就是全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-4\">四 · 为什么需要这个界：容量决策与格式选型的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-5\">五 · 常见误解：逐元素最坏界不是端到端保证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-6\">六 · 界的适用边界与工程判断落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-7\">七 · 误差界的三道裂缝：逐元素界、重尾块与反量化税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-8\">八 · 符号表与公式的逐项读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-9\">九 · 推导关键步：从格点间距到误差界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-10\">十 · 界的松紧从哪来：块内动态范围与重尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-11\">十一 · 失效条件的三种触发路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-12\">十二 · 界与分组粒度的耦合：16 不是常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-13\">十三 · 从界到判据：公式在容量规划里的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-14\">十四 · 误差界在重尾专家权重上的失效与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-15\">十五 · 界的三个隐含前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-16\">十六 · 重尾：界变松的定量机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-17\">十七 · 累积：界为什么不能当端到端保证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-18\">十八 · 规模上限：块大小、专家数与序列长度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-19\">十九 · 失效判据与工程处置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-20\">二十 · 边界之外：逐元素界在专家输出上失效的三种情形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-21\">二十一 · 边界不在公式里，而在块的分布与端到端链路里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-22\">二十二 · 把误差界翻译成“每专家可用位宽”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-23\">二十三 · 用误差界定批大小：精度预算转化为 token 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-24\">二十四 · 用误差界定并行度：专家切分与 TP/EP 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-25\">二十五 · 用误差界定 KV 预算与 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-26\">二十六 · 算例：一个专家集合的容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-27\">二十七 · 误用与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-28\">二十八 · 把误差界换算成容量：微块、离群点与 SLO 的三条约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-29\">二十九 · 误用一：把逐元素最坏界读成端到端精度承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-30\">三十 · 误用二：在重尾专家上沿用均匀分布假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-31\">三十一 · 误用三：盲目缩小微块换精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-32\">三十二 · 一个反例：路由翻转在权重误差报表上完全隐形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-33\">三十三 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-nvfp4-moe-quant-error-sec-34\">三十四 · 误差界的三重误用：把上界当保证、把均匀当普遍、把缩块当解药</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：NVFP4 用 16 元素微块共享 E4M3 scale，量化误差…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\big|\\,w - \\hat{w}\\,\\big| \\;\\le…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：上界是逐元素最坏情况，未反映误差在专家输出上的累积；实际精度需用下…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-nvfp4-moe-quant-error-sec-1\">一 · 一句话直觉：把动态范围切成十六份，用共享标尺换掉逐元素指数</h3>\n<p>NVFP4 的核心直觉可以压缩成一句：<strong>每 16 个权重元素共用一个 E4M3 标尺，元素本身只留 4 bit 整数码</strong>。传统浮点每个元素自带指数，指数位宽决定了它能表达的动态范围；NVFP4 把指数这件事从元素级上提到微块级——一个 16 元素块只存一个 E4M3 scale，块内所有元素共享它，各自只保留 4 bit 的整数码 q。于是显存里每个权重平均只花 4 bit 加一点 scale 开销，而反量化时把 q 乘回 s 就还原出近似权重。这个设计的直接后果是：块内动态范围越窄，共享标尺越贴合每个元素，误差越小；块越大，标尺越被块内极值绑架，误差越大。误差界就是把这个“标尺贴合度”写成可计算的量。</p>\n<p>理解这一点要先放下“4 bit 等于粗暴截断”的印象。4 bit 整数码在给定 scale 下是一组等间距格点，元素被舍入到最近格点，舍入误差天然被半个格点间距封顶。真正决定精度的是格点间距 s 有多大，而 s 由块内最大绝对值除以格点满量程决定。所以 NVFP4 的误差不是由“4 bit 太少”单独决定，而是由“块内最大值有多大”与“尾数位宽 m 有多宽”共同决定。这也是为什么同一个 4 bit 格式在不同专家上表现差异巨大：不是格式变了，是块内最大值变了。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-2\">二 · 严格定义：微块、共享 scale 与反量化映射</h3>\n<p>把符号钉死，后面所有推导才有落脚点。设原始权重元素为 <em>w</em>（FP16 或 BF16），反量化结果为 <em>ŵ</em>，微块共享的 E4M3 scale 为 <em>s</em>，4 bit 量化整数码为 <em>q</em>，尾数位宽为 <em>m</em>。NVFP4 中 m=2，加上隐含位共 3 位有效。反量化映射定义为：</p>\n<div class=\"formula\">$$\\hat{w}=s\\cdot q,\\qquad s=\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}-1}$$</div>\n<p>这里的分母 2^m−1 是 4 bit 整数码在给定符号约定下的满量程格点数，m=2 时满量程为 3。注意 scale 取的是块内最大绝对值，这意味着块内最“响”的那个元素恰好落在满量程格点上，其余元素按比例缩在格点之间。E4M3 作为 scale 的载体，本身是 8 位浮点，指数位给了它跨数量级的表达能力，所以即便块内最大值与最小值相差几个数量级，scale 也不至于溢出或下溢——这是 NVFP4 相对定点分组量化的关键优势，也是它能覆盖 MoE 专家权重这种分布跨度大的场景的原因。</p>\n<p>严格说，这个定义里藏着一个隐含约定：块内元素共享同一个符号约定与同一个格点间距。q 是有符号整数码，s 恒为正，符号由 q 的符号位承载。于是块内每个元素的量化误差只取决于它离最近格点有多远，而格点间距恒为 s。这个“间距恒定”是误差界能写成闭式的前提，一旦块内出现极端离群值把 s 拉高，间距随之变大，块内其余元素的绝对误差上限一起被抬高——这正是后面要反复强调的失效路径。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-3\">三 · 误差上界的推导：半个格点就是全部</h3>\n<p>误差界的推导只有一步关键：以块内最大绝对值定 scale 后，相邻量化格点间距为 s，舍入误差不超过半个格点，即 s/2。把 s 的表达式代入，得到逐元素最坏情况界：</p>\n<div class=\"formula\">$$\\big|\\,w-\\hat{w}\\,\\big|\\;\\le\\;\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}$$</div>\n<p>这个式子值得逐项读。分子是块内最大绝对值，它代表这个块的“动态范围上限”；分母 2^m 是尾数位宽带来的格点细分能力，m=2 时分母为 4，再乘 1/2 得到 1/8。也就是说，NVFP4 下单元素绝对误差不超过块内最大绝对值的八分之一。这个界是逐元素最坏情况，不是统计平均，也不是端到端误差——它只回答“这个元素最多偏多少”，不回答“偏这些会不会让专家输出漂移”。</p>\n<p>从工程代价角度看，这个界直接连着显存与带宽。W4A16 部署下，权重按 4 bit 存储、激活保持 16 bit，显存收益主要来自权重位宽压缩；但每个 16 元素微块还要额外存一个 E4M3 scale，scale 开销摊到每元素约 0.5 bit 量级，实际有效位宽高于纯 4 bit。块越小，块内最大值越贴近元素本身、界越紧，但 scale 数量翻倍，scale 存储与反量化时的乘法开销同步上升。反量化不是免费的：每个元素都要做一次 s·q 的乘加，块越小，单位权重摊到的 scale 读取次数越多，解码阶段这部分开销会挤占本已紧张的访存带宽。所以“缩小微块换精度”从来不是无代价的，它是在用显存与带宽换误差界。</p>\n<p>具体例子：某专家某 16 元素块内最大绝对值为 0.75，m=2，则 s=0.75/3=0.25，格点间距 0.25，单元素误差不超过 0.125。若同一专家另一块因一个离群点使最大绝对值升到 6.0，则 s=2.0，误差上限跳到 1.0——块内那些原本只有 0.05 量级的元素，有效尾数被彻底吃掉，反量化后几乎只剩符号信息。两个块用的是同一个格式、同一个 m，误差界却差一个数量级，差别只在块内最大值。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-4\">四 · 为什么需要这个界：容量决策与格式选型的判据</h3>\n<p>这个界的第一用途是推理容量决策：判断某专家权重能否在 W4A16 下保持精度。做法不是逐元素验算，而是抽样统计每个微块的 max|w_i| 分布，代入界估算有效尾数是否够用。若某专家大量块的界超过下游任务可容忍的权重扰动阈值，就说明该专家不适合直接 NVFP4，需要缩小微块、改分组方式，或对该专家保留 FP8。这是一条可执行的工程判据：它把“能不能量化”从拍脑袋变成按块统计最大值的可计算问题。</p>\n<p>第二用途是格式选型的代价核算。缩小微块能把界压紧，但 scale 存储与反量化开销上升；对某专家保留 FP8 能彻底绕开 4 bit 尾数不足，但该专家的权重显存翻倍、访存带宽需求上升。这两条路径的取舍要用界来量化：界告诉你精度缺口有多大，代价模型告诉你补这个缺口要花多少显存与带宽。没有界，你只知道“精度掉了”，不知道“掉在哪个块、为什么掉、补它值不值”。</p>\n<p>第三用途是解释 MoE 场景下的非均匀性。MoE 专家权重分布差异极大，有的专家权重集中在小幅值区间，有的专家呈重尾。同一个 16 元素微块策略在所有专家上误差并不一致——这不是实现 bug，而是界的分子 max|w_i| 逐块不同导致的必然结果。容量规划若按“平均误差”估算，就会在重尾专家上系统性低估风险。界的作用正是把这种非均匀性显式暴露出来，让容量决策按专家、按块分层做，而不是全局一个系数。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-5\">五 · 常见误解：逐元素最坏界不是端到端保证</h3>\n<p>最常见的误用是把逐元素最坏界当作端到端精度保证，跳过 perplexity 与路由一致性验证。这个界只约束单个权重的偏差上限，不反映误差在专家输出上的累积：一个专家内数百个元素的偏差会同向叠加到矩阵乘结果上，再经过激活函数与路由打分放大或翻转。逐元素界再紧，也不能推出“专家输出不漂移”。实际精度必须用下游任务 perplexity 或路由一致性验证——尤其 MoE 场景，路由翻转意味着 token 被送到错误的专家，这种错误不是权重误差的线性函数，逐元素界根本覆盖不到。</p>\n<p>第二个误解是忽略重尾分布下 scale 被离群点拉高的效应，误以为 16 元素微块在所有专家上误差一致。公式假设块内分布无极端离群值；一旦专家权重重尾，单块 scale 被离群点拉高，其余元素有效位下降，界变松。此时仍按均匀分布估算误差，量化后精度会骤降。工程上的识别方法是看块内 max|w_i| 与块内中位绝对值的比值：比值越大，说明 scale 被少数元素绑架得越狠，界越不可信。</p>\n<p>第三个误解是为压低误差盲目缩小微块。块越小界越紧，但 scale 存储与反量化开销上升，显存与带宽收益被抵消，W4A16 部署容量反而下降。极端情况下，微块缩到每元素一个 scale，NVFP4 退化成带逐元素 scale 的 4 bit 格式，scale 开销吞掉位宽收益，部署密度不如直接 FP8。所以缩小微块必须和容量模型一起算，不能只看误差界变紧就拍板。</p>\n<p>第四个误解是把界的“最坏情况”当成“典型情况”。界给出的是上限，实际误差通常远小于上限，但上限存在的意义正是提醒你：在重尾块上，实际误差可能逼近上限。用典型误差做容量规划、用最坏界做安全边际，才是正确的用法；反过来用最坏界估平均吞吐、用典型误差估最坏风险，都会把决策带偏。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-6\">六 · 界的适用边界与工程判断落点</h3>\n<p>把适用边界写清楚，这个界才不会被误用。它是逐元素最坏情况界，不反映误差在专家输出上的累积；它假设块内分布无极端离群值；它不替代下游任务验证。三条边界对应三种工程动作：第一，容量决策时用界筛掉明显不达标的专家，再用 perplexity 与路由一致性做最终确认；第二，对重尾专家单独统计块内最大值分布，必要时改分组方式或保留 FP8；第三，缩小微块的方案必须同时核算 scale 存储与反量化开销，确认显存与带宽净收益为正。</p>\n<p>落到具体机制上，判断一个 MoE 专家能否走 NVFP4 W4A16，最实用的做法是：按 16 元素微块统计 max|w_i| 的分位数，代入界算出该专家块级误差上限的分布，再与路由打分对权重扰动的敏感度对照。若大量块的界落在敏感度阈值之上，说明该专家在 4 bit 尾数下无法保持路由稳定，应保留 FP8 或缩小微块；若界普遍远低于阈值，则可放心走 NVFP4，把显存与带宽收益落袋。这个判断不依赖任何实验数字，只依赖块内最大值统计与界本身——这正是这个界在容量规划里的价值：它把格式选型从经验判断变成可复算的逐块核算。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-7\">七 · 误差界的三道裂缝：逐元素界、重尾块与反量化税</h3>\n<p>把 $|w-\\hat{w}|\\le \\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}$ 当成“精度合格证”是 NVFP4 部署中最典型的误用。这个界只描述单个元素在舍入后的最坏偏差，而推理系统真正关心的是误差经过整层矩阵乘、激活、残差与路由之后的累积形态。逐元素偏差彼此独立时会在求和中被部分抵消，但 MoE 专家权重若呈重尾，偏差会沿被激活的少数通道集中放大，端到端输出漂移远超单元素界给出的直觉。因此该界的正确用法是“筛选器”而非“保证书”：它回答的是某个专家的某个微块是否还有足够有效尾数，而不是整个模型能否在 W4A16 下交付。</p>\n<p>失效的第一道裂缝在块内分布。NVFP4 以 16 元素共享一个 E4M3 scale，scale 由块内最大绝对值定死，于是块内其余元素的量化格点间距被这个最大值绑架。若某专家权重存在少数幅值远高于同伴的离群通道，$s$ 被抬高，绝大多数元素落在低位格点上，有效尾数从 3 位有效退化到接近 1 位，界本身仍然“成立”，却已松到失去判别力。第二道裂缝在统计假设：公式隐含块内无极端离群值，而 MoE 专家因路由分工天然携带方向性极强的权重分布，不同专家之间误差并不一致，按均匀分布估算容量会系统性低估最差专家。</p>\n<div class=\"formula\">$$\\text{有效尾数损失}\\;\\propto\\;\\log_2\\!\\Big(\\frac{\\max_{i\\in\\text{block}}|w_i|}{\\mathrm{median}_{i\\in\\text{block}}|w_i|}\\Big)$$</div>\n<p>第三道裂缝是代价侧的反馈回路：为压低误差而缩小微块，scale 数量按 $16/n$ 反比上升，E4M3 scale 的存储、加载与反量化乘加随之增加。W4A16 的显存收益被 scale 与反量化开销部分抵消，解码阶段每 token 需多读的 scale 字节直接吃掉带宽红利，容量规划反而收紧。工程判断应落在分层策略上：对块内动态范围温和的专家维持 16 元素微块，对重尾专家改用更细分组或保留 FP8 权重，并以路由一致性与下游 perplexity 作为放行门槛，而不是拿逐元素界替代验证。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>界的可信度</th><th>系统代价</th></tr></thead><tbody><tr><td>块内分布温和、无离群</td><td>紧，可作容量筛选</td><td>16 元素微块，scale 开销最低</td></tr><tr><td>重尾、单块 scale 被拉高</td><td>松，仅存形式上界</td><td>需细分组或 FP8 回退，显存上升</td></tr><tr><td>盲目缩小微块</td><td>界收紧但收益递减</td><td>scale 带宽与反量化算力吃掉 W4A16 红利</td></tr></tbody></table>\n<h3 id=\"th-nvfp4-moe-quant-error-sec-8\">八 · 符号表与公式的逐项读法</h3>\n<p>先把符号钉死，后面所有推导都在这套记号里走。原始权重元素记为 <span class=\"sym\">w</span>，取自 FP16 或 BF16 的专家权重张量；反量化结果是 <span class=\"sym\">ŵ</span>；微块共享的 E4M3 scale 记为 <span class=\"sym\">s</span>；4 bit 整数码记为 <span class=\"sym\">q</span>；尾数位宽记为 <span class=\"sym\">m</span>。NVFP4 中 m=2，加上隐含的前导位共 3 位有效精度，这是整个误差分析的基准刻度。量化关系写成</p>\n<div class=\"formula\">$$\\hat{w}=s\\cdot q,\\qquad s=\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}-1}$$</div>\n<p>逐项拆开看：<span class=\"sym\">s</span> 是块内 16 个元素共用的唯一浮点参数，它以 E4M3 存储，本身也带舍入，但相对 4 bit 码的粗粒度可以忽略到二阶；分母 <span class=\"sym\">2^m−1</span> 是 4 bit 有符号整数码能取到的最大幅值，m=2 时为 3，因此 <span class=\"sym\">q∈[−3,3]</span> 的整数格点被映射到 <span class=\"sym\">[−max|w_i|, max|w_i|]</span>。注意 <span class=\"sym\">s</span> 由块内最大绝对值定义，这一选择直接决定了后面界的松紧：它保证不溢出，却把动态范围的支配权交给了块内最极端的那个元素。反量化在推理时对每个元素做一次乘加，W4A16 路径下权重以 4 bit 存储、以 16 bit 参与 MMA，scale 每 16 元素一份，因此 scale 的存储开销是每元素 8/16=0.5 bit，相对 4 bit 主体不可忽略。</p>\n<p>工程代价落在三处：显存上，4 bit 权重加 0.5 bit scale 使专家权重压缩比接近 7 倍于 FP16，但反量化要在 tensor core 前把码流展开成 16 bit，占的是 SM 的整数/移位吞吐而非 MMA 吞吐；带宽上，权重读取量降到 FP16 的约 1/7，解码阶段权重带宽本就是瓶颈，收益直接体现在 token 间隔上；延迟上，反量化的逐元素乘法与 scale 广播在 16 元素粒度上做，粒度越细，指令条数越多。一个具体例子：某专家线性层权重形状为 4096×4096，按 16 元素微块切分共 1M 个块，每块一个 E4M3 scale，scale 张量本身 1 MB 量级，而 4 bit 主体为 8 MB 量级——这就是“块越小 scale 开销越大”在容量账上的直接体现。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-9\">九 · 推导关键步：从格点间距到误差界</h3>\n<p>推导只有三步，但每一步都藏着一个近似决策。第一步，定 scale：取块内最大绝对值 <span class=\"sym\">M=max|w_i|</span>，令 <span class=\"sym\">s=M/(2^m−1)</span>，使最大幅值恰好落在最大格点上，不溢出。第二步，算格点间距：整数码相邻取值差 1，映射回实数域的间距就是 <span class=\"sym\">s</span>，于是任意元素被舍入到最近格点，误差不超过半个间距，即 <span class=\"sym\">|w−ŵ|≤s/2</span>。第三步，代入 s：</p>\n<div class=\"formula\">$$\\big|\\,w-\\hat{w}\\,\\big|\\le\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}=\\frac{M}{2^{m+1}}$$</div>\n<p>关键步在第二步与第三步之间：<span class=\"sym\">s/2</span> 是“最近格点舍入”的最坏误差，这一步假设了舍入是 round-to-nearest 且码值范围足够覆盖块内所有元素——后者由第一步的 scale 选择保证。m=2 时界化为 <span class=\"sym\">M/8</span>，也就是说块内最大元素的绝对误差上界是它自身的 1/8，而块内较小元素的相对误差会被这个界严重高估。这正是该界“逐元素最坏情况”的来源：它用一个统一的 <span class=\"sym\">M</span> 约束整块，对接近 <span class=\"sym\">M</span> 的元素是紧的，对远小于 <span class=\"sym\">M</span> 的元素则极松。离散化发生在两处：整数码把连续实数压到 7 个非零格点（含零共 8 个码值），这是幅度离散；E4M3 存 scale 又把 scale 本身离散化，这是参数离散。前者是主导误差，后者是二阶修正。近似则发生在“以块内最大值定 scale”这一策略选择上——它不是唯一可行策略，但它是唯一能给出闭式上界的策略。</p>\n<p>把界翻译成系统代价：若某专家块内 <span class=\"sym\">M</span> 偏大而其余元素偏小，则有效尾数被摊薄，等价于该块的实际精度低于 3 位有效；在 W4A16 下这意味着该专家的输出误差随 <span class=\"sym\">M</span> 线性放大，而 MoE 路由对专家输出的微小漂移敏感，误差累积到路由 logits 上可能翻转 top-k 选择。容量决策上，这个界给出的是“单块可接受性”判据：若 <span class=\"sym\">M/8</span> 超过该层可容忍的绝对误差阈值，则该块必须改分组或升精度。举例：某专家权重块内 <span class=\"sym\">M=0.5</span>，界为 0.0625；若同块多数元素幅值在 0.01 量级，它们的相对误差上界被高估到 6 倍以上，真实误差远小于界，但界本身无法区分这两种情形。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-10\">十 · 界的松紧从哪来：块内动态范围与重尾</h3>\n<p>界的松紧完全由块内动态范围 <span class=\"sym\">M/|w|</span> 的分布决定。均匀分布下，块内元素幅值接近，界对每个元素都近似紧；重尾分布下，少数离群点把 <span class=\"sym\">M</span> 拉高，其余元素的量化格点间距被动变大，有效位下降，界对这些元素变得极松。形式化地，若块内第 i 个元素的幅值为 <span class=\"sym\">|w_i|=αM</span>，α∈(0,1]，则其相对误差上界为 <span class=\"sym\">1/(2^{m+1}α)</span>，α 越小界越松。这就是“单块 scale 被离群点拉高”的数学表述：α 的分布决定了界的有效性，而界本身不携带 α 的信息。</p>\n<p>MoE 专家权重恰恰是重尾的高发区：不同专家的权重分布差异大，某些专家在特定通道上存在显著离群值，16 元素微块若恰好横跨这些通道，整块精度被一个点拖垮。系统代价体现在两个方向：一是精度上，重尾块的实际误差远超均匀假设下的估计，perplexity 与路由一致性必须实测而不能靠界推断；二是容量上，为压住重尾而缩小微块，scale 开销从 0.5 bit/元素升到 1 bit/元素甚至更高，显存收益被抵消，W4A16 的部署容量反而下降。一个具体判断：对某专家做块内 α 分布统计，若 90 分位 α 低于 0.1，则该专家不适合 16 元素微块的 NVFP4，应改分组方式或保留 FP8；这一判断用的是界的形式，但输入是实测分布而非假设。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-11\">十一 · 失效条件的三种触发路径</h3>\n<p>第一条路径是把逐元素最坏界当作端到端精度保证。界约束的是单个权重元素的偏差，而专家输出是权重与激活的乘积累加，误差在求和上累积、在非线性上放大、在路由 logits 上竞争。界不反映这种累积，因此跳过 perplexity 与路由一致性验证直接上线，会出现专家输出漂移、路由翻转。第二条路径是忽略重尾下 scale 被离群点拉高的效应，仍按均匀分布估算误差，量化后精度骤降——这在数学上就是上一节 α 分布的误判。第三条路径是为压低误差盲目缩小微块，scale 存储与反量化开销上升，显存与带宽收益被抵消，W4A16 部署容量反而下降。三条路径的共同点是：界是必要条件而非充分条件，它筛掉明显不可行的块，但不能证明可行的块一定可行。</p>\n<p>把失效条件写成可执行的校验清单：对每个专家、每个微块，记录 <span class=\"sym\">M</span>、块内 α 的低分位、以及界 <span class=\"sym\">M/2^{m+1}</span> 与该层误差阈值的比值；三项中任一项越界即触发改分组或升精度。这套清单的计算代价是每块一次归约加一次除法，相对反量化本身可以忽略，但它把“界”从纸面公式变成了容量规划里的判据。举例：某 MoE 层 64 个专家，逐块扫描后发现 3 个专家的重尾块占比超过阈值，对这 3 个专家保留 FP8，其余走 NVFP4，显存账上多出的是这 3 个专家的 FP8 副本，而不是全层升精度——这正是界在容量决策中的正确用法。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-12\">十二 · 界与分组粒度的耦合：16 不是常数</h3>\n<p>16 元素微块是 NVFP4 的硬件粒度，但误差界对粒度是显式依赖的：块越小，<span class=\"sym\">M</span> 越接近块内元素的真实幅值，α 分布越集中，界越紧；代价是 scale 数量线性上升，每元素 scale 开销为 <span class=\"sym\">b_s/n</span>（<span class=\"sym\">b_s</span> 为 scale 位宽，n 为块大小），反量化指令数也随块数上升。写成权衡式：有效位收益随 n 减小而增，开销随 n 减小而增，最优点在两者斜率相等处，而这个点对不同专家不同——这正是“16 元素微块在所有专家上误差一致”这一误用的根源。工程上不能全局调 n，但可以在分组方式上做文章：按通道聚类分组，把幅值相近的元素放进同一块，等价于在不改 n 的前提下压紧 α 分布。</p>\n<p>系统代价的量化：n 从 16 降到 8，scale 开销从 0.5 bit/元素升到 1 bit/元素，权重总位宽从 4.5 升到 5，压缩比相对 FP16 从约 3.6 倍降到约 3.2 倍，解码阶段权重带宽收益同比例缩水；同时反量化指令数翻倍，在权重带宽瓶颈的解码场景里这部分开销可能被掩盖，但在计算密集的预填场景里会显形。一个具体例子：某专家层在 n=16 下界为 <span class=\"sym\">M/8</span>，若块内 α 低分位为 0.05，则该元素相对误差上界达 2.5 倍于其自身幅值，明显不可接受；改按通道聚类后 α 低分位升到 0.4，界收紧到 0.3 倍，无需缩小 n 即达标——这说明分组策略与粒度是同一枚硬币的两面，界只对给定的分组给出结论。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-13\">十三 · 从界到判据：公式在容量规划里的落点</h3>\n<p>把公式整理成一条可执行的判据链：给定层误差阈值 <span class=\"sym\">ε</span>，对每块计算 <span class=\"sym\">M/2^{m+1}</span>，若小于 <span class=\"sym\">ε</span> 则该块在逐元素意义上安全；再对每块计算 α 低分位，若低于设定下限则标记为重尾块；两项都通过的块走 NVFP4，任一不通过的块改分组或升 FP8。这条链的输入全部来自权重统计，输出是每专家、每块的精度决策，直接进入显存预算：NVFP4 块按 4.5 bit/元素计，FP8 块按 8 bit/元素计，两者相加得到该专家的实际占用，再乘专家数得到层容量。W4A16 的可行性由此从“能不能压到 4 bit”变成“多少比例的块能压到 4 bit 而不越界”。</p>\n<p>这条判据链的代价是离线统计加一次扫描，收益是把“界”从最坏情况估计变成分布感知的筛选器。需要强调的是，判据链仍然不替代 perplexity 与路由一致性验证——它筛的是权重侧的可行性，端到端精度还要在激活分布上验证，因为界的推导全程没有出现激活。最后落在具体机制上：NVFP4 的误差界是一个以块内最大值为锚的闭式上界，它的价值不在于给出精度保证，而在于用极低的计算代价把权重分成“明显可行”“明显不可行”“需实测”三类，容量规划的动作就发生在这三类的边界上。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-14\">十四 · 误差界在重尾专家权重上的失效与代价</h3>\n<p>把 <span class=\"inline-formula\">|w−ŵ| ≤ max|wᵢ| / 2^m × 1/2</span> 当作端到端精度保证是这一方案最典型的误用。该界是逐元素最坏情况，只约束单个权重的反量化偏差，完全不反映误差经过专家矩阵乘与激活后的累积、放大或相互抵消。真正决定 W4A16 能否守住精度的是下游 perplexity 与路由一致性：前者衡量输出分布漂移，后者衡量 top-k 专家选择是否翻转。一个专家即使逐元素误差全部落在界内，只要少数关键通道的偏差方向一致，就足以把某条 token 的路由分数推过阈值，造成路由翻转，而路由翻转又会把 token 送入未经校准的专家，误差进一步扩散。工程上必须把误差界当作筛选工具而非验收标准，验收只能落在任务指标上。</p>\n<p>公式隐含的前提是块内分布无极端离群值。MoE 专家权重普遍呈重尾：少数通道幅值远大于其余元素。此时 <span class=\"inline-formula\">s = max|wᵢ| / (2^m − 1)</span> 被离群点单独拉高，块内其余元素被迫落在少数几个量化格点上，有效尾数从 3 位有效急剧退化，实际误差远超按均匀分布估算的值。更麻烦的是这种退化在专家间不均匀——被离群点污染的块误差大，干净的块误差小，于是“16 元素微块在所有专家上误差一致”的假设直接破产。判断某个专家是否安全，应看块内幅值比 max/median 而非只看 max 本身；比值过大即意味着该块的有效位已被离群点吃掉。</p>\n<table class=\"mini\"><thead><tr><th>块内形态</th><th>scale 行为</th><th>有效位</th><th>界与实际误差</th></tr></thead><tbody><tr><td>均匀分布</td><td>贴近中位幅值</td><td>接近 3 位有效</td><td>界紧，实际误差接近界</td></tr><tr><td>含单个离群点</td><td>被离群点拉高</td><td>其余元素有效位下降</td><td>界变松，实际误差显著大于均匀估算</td></tr><tr><td>多离群点</td><td>接近最大幅值</td><td>大量元素退化为少数格点</td><td>界失去筛选意义，须改用 FP8 或改分组</td></tr></tbody></table>\n<p>为压低误差而盲目缩小微块，会直接撞上系统代价：scale 存储随块数线性上升，反量化时每个块都要读取并广播 E4M3 scale，显存占用与反量化带宽同步增加，W4A16 的容量收益被抵消。以 16 元素微块为例，每 16 个 4 bit 权重附带一个 E4M3 scale，scale 开销已不可忽略；缩到 8 元素或更小，scale 占比翻倍，反量化指令密度上升，解码阶段的内存带宽优势被侵蚀。工程判断应落在“按专家分组、按块内幅值比决定精度档位”：幅值比温和的专家维持 NVFP4 的 16 元素微块，重尾专家改分组方式或整专家保留 FP8，用少量显存换路由稳定性，而不是全局缩小微块把收益一次性赔光。</p>\n<h3 id=\"th-nvfp4-moe-quant-error-sec-15\">十五 · 界的三个隐含前提</h3>\n<p>把 <span>|w−ŵ| ≤ max|w<sub>i</sub>| / 2<sup>m</sup> · 1/2</span> 当成一条可搬运的结论之前，必须先看清它站在哪三根柱子上。第一根是<strong>块内最大值可代表块内动态范围</strong>：推导里用 <span>max|w<sub>i</sub>|</span> 定 scale，等于默认块内其余元素与最大值同量级，格点间距 s 对全块“够用”。第二根是<strong>舍入误差在元素间独立且不放大</strong>：界只描述单个元素偏离其格点的距离，不含任何跨元素、跨层、跨 token 的传播项。第三根是<strong>m 是常数</strong>：NVFP4 中 m=2、含隐含位共 3 位有效，这个位宽在块内所有元素上被均匀消耗——而“均匀”恰恰是重尾分布最先破坏的东西。</p>\n<p>三根柱子对应三种不同的失效方式，且失效程度不同。第一根塌陷是<em>结构性</em>的：只要块内存在一个远大于其余元素的离群点，s 就被抬高，界本身仍然“成立”（它依旧是逐元素最坏情况的上界），但它对块内绝大多数元素的描述力急剧下降——界没有变错，是变松。第二根塌陷是<em>语义性</em>的：界从来就不是端到端保证，把它当保证用属于越界使用，而不是公式本身出错。第三根塌陷是<em>规模性</em>的：当微块被迫缩小以挽救第一根柱子时，scale 的存储与反量化开销上升，W4A16 的显存收益被部分抵消，此时“用更小块换更紧界”的工程账要重算。</p>\n<p>工程上区分这三者很重要：第一种要靠分布诊断解决，第二种要靠验证流程解决，第三种要靠容量模型解决。混为一谈的典型后果是把重尾问题误判为“界不够紧”，于是盲目缩块，结果显存收益下降而精度并未回到预期。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-16\">十六 · 重尾：界变松的定量机制</h3>\n<p>设一个 16 元素微块内，15 个元素量级为 σ，1 个离群元素为 Kσ（K 远大于 1）。按公式，s = Kσ/(2<sup>m</sup>−1)，于是那 15 个正常元素分到的格点间距是 Kσ/(2<sup>m</sup>−1)，而它们自身的量级只有 σ。有效尾数被压缩了约 K 倍：原本 3 位有效能分辨 σ/2<sup>m</sup> 级别的差异，现在只能分辨 Kσ/2<sup>m</sup>。用相对误差表述，正常元素的相对误差上界从约 1/2<sup>m+1</sup> 恶化到约 K/2<sup>m+1</sup>。</p>\n<div class=\"formula\">$$\\frac{|w-\\hat{w}|}{|w|}\\;\\le\\;\\frac{K}{2^{m+1}}\\quad(\\text{正常元素}),\\qquad \\frac{|w-\\hat{w}|}{|w|}\\;\\le\\;\\frac{1}{2^{m+1}}\\quad(\\text{离群元素自身})$$</div>\n<p>注意这个式子的方向：离群元素自己的相对误差反而小（它定义了 scale），受害的是它的 15 个邻居。这就是为什么“逐元素最坏界”在重尾块里具有欺骗性——最坏界由离群元素决定，看起来数值不大，但块内多数元素的真实误差被它掩盖。MoE 专家权重天然容易重尾：不同专家的输入分布差异大，冷门专家在训练中更新稀疏，少数通道权重被反复强化，形成通道级离群。16 元素微块若恰好沿这些通道切分，就会反复踩中同一类块。</p>\n<p>系统代价体现在两个方向。精度侧：专家输出漂移经路由 softmax 放大后可能翻转 top-k 选择，一次路由翻转会把 token 送往完全不同的专家，误差不再是“数值略偏”而是“路径改变”。容量侧：若为压住重尾而把微块从 16 缩到 8，scale 数量翻倍，W4A16 下每权重平均位宽从 4 + 8/16 = 4.5 bit 升到 4 + 8/8 = 5 bit，权重显存与反量化带宽同步上升，直接吃掉一部分 W4A16 相对 FP8 的收益。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-17\">十七 · 累积：界为什么不能当端到端保证</h3>\n<p>逐元素界与端到端精度之间隔着一整条计算链。以一个专家内的 GEMM 为例，输出某个通道的误差是输入激活与权重误差的卷积和：</p>\n<div class=\"formula\">$$\\big|\\,\\Delta y_j\\,\\big|\\;\\le\\;\\sum_{i}\\big(|x_i|\\,|\\Delta w_{ij}|+|w_{ij}|\\,|\\Delta x_i|+|\\Delta x_i|\\,|\\Delta w_{ij}|\\big)$$</div>\n<p>右侧第一项就把逐元素界乘上了激活量级并求和：K 维累加使误差按 √K（随机符号）或 K（同号）增长，而逐元素界对此一无所知。更关键的是 MoE 特有的两级放大：专家内部 GEMM 的误差先进入专家输出，再经过路由权重的加权组合，最后进入残差流。路由权重本身对专家输出的微小差异敏感——softmax 在 logit 差距小时梯度大，专家输出的漂移可能改变 top-k 排序。于是“权重误差界”与“路由一致性”之间不存在任何由该公式给出的桥梁。</p>\n<p>因此适用边界的正确表述是：该界是<strong>单元素、单次反量化的最坏情况包络</strong>，可作为筛选工具（判断某专家是否“明显不可量化”），不可作为验收标准。验收必须落到下游指标：perplexity 的偏移量、路由一致性（同一 token 在量化前后是否选中同一组专家）、以及长上下文下误差是否随 token 位置漂移。工程上常见的代价是验证吞吐：perplexity 与路由一致性验证需要在代表性校准集上跑完整前向，其成本远高于量化本身，但跳过它的代价是上线后专家输出漂移与路由翻转，属于不可接受的失败模式。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-18\">十八 · 规模上限：块大小、专家数与序列长度</h3>\n<p>公式里没有任何规模变量，这正是它的规模盲区。三个规模维度各自引入新的失效通道。</p>\n<ul>\n<li><strong>块大小</strong>：16 元素是硬约束（微块定义），不是可调超参。所谓“缩小微块”实际是改变分组方式（例如沿通道而非沿展平顺序切分），使离群元素尽量独占块或少污染邻居。这需要离线分析权重分布并按通道重排，代价是布局变换与推理时索引开销。</li>\n<li><strong>专家数</strong>：专家越多，单专家被采样的 token 越少，校准统计越稀疏，重尾越难被平均掉。逐元素界对每个专家独立成立，但“所有专家都满足界”不等于“路由整体稳定”——冷门专家的少量 token 一旦翻转，长尾影响会被路由放大到整个 batch。</li>\n<li><strong>序列长度</strong>：W4A16 中权重是静态量化的，激活保持 16 位，因此序列变长主要放大激活侧误差累积而非权重侧。但 KV cache 与长上下文使路由决策在更多 token 上发生，路由翻转的期望次数随 token 数线性上升，端到端精度退化因此具有长度依赖性——这是单元素界完全无法表达的量。</li>\n</ul>\n<p>容量决策上的含义是：该界可用于<em>逐专家</em>的准入判断（某专家块内最大值是否大到有效尾数不足），但不能用于<em>整模型</em>的容量承诺。若某专家被判为不可量化，处置选项是保留 FP8 或改分组，代价是显存与反量化开销上升；若整模型层面按“所有专家都过界”来规划 W4A16 容量，就会低估路由翻转风险，属于把逐元素界误用为端到端保证的典型失败模式。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-19\">十九 · 失效判据与工程处置</h3>\n<p>把适用边界转成可执行的判据，需要三个检查点。其一，<strong>块内动态范围比</strong>：统计每个微块的 max|w<sub>i</sub>| 与块内中位量级之比，比值超过阈值即标记为重尾块，该块的有效尾数已被压缩，界对该块多数元素不具描述力。其二，<strong>专家级路由一致性</strong>：在代表性校准集上比较量化前后 top-k 专家选择的重合率，重合率下降即说明误差已越过数值层面进入路径层面，此时逐元素界再紧也无意义。其三，<strong>容量回算</strong>：若为压重尾而改分组或缩块，重算每权重平均位宽与反量化带宽，确认 W4A16 的显存收益仍为正。</p>\n<p>处置顺序应是先诊断后改结构：先按块内动态范围比筛出重尾专家，再对这些专家尝试通道重排分组，仍不达标才降级到 FP8。反过来先缩块再验证，会把 scale 开销推高而未必解决重尾——因为重尾是分布性质，不是块大小能消除的。最终判断落在一条具体机制上：NVFP4 的误差界是<strong>以块内最大值为锚的单元素包络</strong>，它的有效性随块内分布均匀性下降、随计算链累积失效、随专家稀疏与序列增长而失去对端到端精度的解释力；工程上应把它当作逐专家准入筛选器，而把 perplexity 与路由一致性作为唯一验收口径。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-20\">二十 · 边界之外：逐元素界在专家输出上失效的三种情形</h3>\n<p>该上界是逐元素最坏情况，其推导只保证单块内任一权重元素的舍入偏差不超过半个格点，即 <span class=\"inline-formula\">s/2</span>；它不对专家前向输出作任何承诺。MoE 专家的输出是 <span class=\"inline-formula\">y=Wx</span>，误差经 <span class=\"inline-formula\">\\(\\sum_i \\delta w_i x_i\\)</span> 在 token 维度上相干或相消累积，逐元素界既未给出累积后的方差，也未刻画激活分布对误差的放大。因此把该界当作端到端精度保证是典型误用：正确做法是用下游 perplexity 与路由一致性（top-k 专家选择是否翻转）做验证，界只用于判断“某专家权重是否值得保留 W4A16”。</p>\n<p>第二个失效条件是重尾。公式以 <span class=\"inline-formula\">\\(\\max_{i\\in\\text{block}}|w_i|\\)</span> 定 scale，隐含假设块内 16 个元素分布无极端离群值。当 MoE 专家权重呈重尾时，单个离群点把 <span class=\"inline-formula\">s</span> 拉高，其余 15 个元素落在更粗的格点上，有效尾数从 3 位有效（m=2 加隐含位）实际退化，界随之变松，而按均匀分布估算的误差会严重低估真实偏差。此时应缩小微块、改分组方式，或对该专家保留 FP8——代价直接体现在显存与反量化开销上。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>界是否成立</th><th>系统代价</th></tr></thead><tbody><tr><td>块内近似均匀、无离群</td><td>成立，接近紧</td><td>16 元素共享 1 个 E4M3 scale，开销最低</td></tr><tr><td>重尾、单点离群</td><td>形式上成立但极松</td><td>有效位下降，需改分组或升 FP8，显存上升</td></tr><tr><td>盲目缩小微块</td><td>界收紧</td><td>scale 存储与反量化带宽上升，W4A16 容量收益被抵消</td></tr></tbody></table>\n<p>第三个边界是规模上限：微块越小误差越小，但 scale 开销按 <span class=\"inline-formula\">1/16</span> 元素比例反向增长，反量化在解码阶段是带宽敏感的逐元素操作，块数增多意味着更多 scale 读取与更多指令，吞吐与显存收益同时被侵蚀。工程判断应落在“界够用即止”：以 perplexity 与路由一致性为验收门槛，仅在界明显偏松的专家上做非均匀分组或局部升精度，而不是全局缩小微块。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-21\">二十一 · 边界不在公式里，而在块的分布与端到端链路里</h3>\n<p>误差上界 $$\\big|w-\\hat{w}\\big|\\le\\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}$$ 的成立依赖一个未写出的前提：块内 16 个元素的最大绝对值能代表整块的动态范围。一旦专家权重呈重尾，离群点把 E4M3 scale 抬高，其余 15 个元素落在更粗的格点上，有效尾数从 3 位有效实际退化，界本身仍“成立”却变得极松——它给出的是最坏情况，不是典型情况。此时按均匀分布估算误差会系统性低估，量化后精度骤降，而公式不会报警。</p>\n<p>第二个失效点是界的逐元素性。逐元素误差不累积成端到端误差：MoE 中专家输出的误差经路由加权、残差叠加与归一化放大或抵消，逐元素最坏界无法给出 perplexity 保证，也无法保证路由一致性——top-k 专家选择在近邻 logit 上翻转。工程上必须用下游 perplexity 与路由一致性做验证，把公式当作容量筛选的第一道闸门而非上线依据。W4A16 下某专家是否可量化，取决于块内最大值是否让有效尾数不足以支撑该专家的输出敏感度。</p>\n<p>第三个边界是规模与开销的反向耦合。缩小微块能收紧界，但 scale 存储从每 16 元素一个 E4M3 升到更密，反量化指令与 TMEM 读写次数同步上升，显存与带宽收益被抵消，W4A16 部署容量反而下降。判断准则应落在“界是否够用”而非“界是否最小”：</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>界的状态</th><th>系统代价</th></tr></thead><tbody><tr><td>块内近似均匀、无离群</td><td>紧，可作容量依据</td><td>16 元素微块，scale 开销可忽略</td></tr><tr><td>重尾、离群拉高 scale</td><td>成立但极松</td><td>需改分组或该专家保留 FP8，显存上升</td></tr><tr><td>盲目缩小微块</td><td>收紧</td><td>scale 与反量化开销上升，带宽收益抵消</td></tr></tbody></table>\n<p>因此该界的适用规模上限由“块内最大值的代表性”决定，而非由元素数决定；跨专家、跨层的误差不可加，逐元素界不能外推为模型级保证。</p>\n<h3 id=\"th-nvfp4-moe-quant-error-sec-22\">二十二 · 把误差界翻译成“每专家可用位宽”</h3>\n<p>容量决策里真正要回答的问题不是“NVFP4 能不能用”，而是“哪些专家能用、用多大代价换回来”。误差界 <span class=\"formula-inline\">|w−ŵ| ≤ (max|w_i|/2^m)·(1/2)</span> 的工程含义是：一个微块内所有元素共享同一个 E4M3 scale，scale 由块内最大绝对值定死，于是块内每个元素的实际有效精度取决于它自己离 max|w_i| 有多远。把界除以该元素自身的量级，得到相对误差 <span class=\"formula-inline\">|w−ŵ|/|w| ≈ (max|w_i|/|w|)·2^-(m+1)</span>。对 m=2（含隐含位共 3 位有效），当块内某元素只有块最大值的 1/8 时，它的相对误差已经吃掉 3 位有效中的大部分——这就是“有效尾数不足”的定量形态。于是每个专家可以算一个标量：块内动态范围比 <span class=\"formula-inline\">R_e = max|w_i| / median|w_i|</span>，R_e 越大，界越松，该专家越不适合直接 W4A16。这个标量就是容量决策的输入，而不是全局一个“NVFP4 精度如何”的定性判断。</p>\n<div class=\"formula\">$$R_e=\\frac{\\max_{i\\in\\text{block}}|w_i|}{\\operatorname{median}_{i\\in\\text{block}}|w_i|},\\qquad \\varepsilon_e\\approx R_e\\cdot 2^{-(m+1)}$$</div>\n<p>代价侧要同时记账：把某专家从 NVFP4 提到 FP8，权重显存翻倍（4 bit→8 bit），但反量化路径从“scale 乘法 + 4 bit 解包”变成直接读取，SM 上的解包指令与 TMEM 写入的带宽压力下降。反过来，为压低 R_e 把 16 元素微块缩到 8 元素，scale 数量翻倍，E4M3 scale 的存储从每 16 元素 1 字节变成每 8 元素 1 字节，等效位宽从 4.5 bit 升到 5 bit，且反量化时每元素多一次 scale 载入——这是显存与带宽的双向损失。决策规则因此是三选一：R_e 低于阈值则留 NVFP4；R_e 中等则缩块或改分组；R_e 高（重尾）则该专家整块保留 FP8，用显存换路由一致性。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-23\">二十三 · 用误差界定批大小：精度预算转化为 token 预算</h3>\n<p>批大小不是独立变量，它被 KV 预算和权重显存共同挤压。设单卡权重显存 <span class=\"formula-inline\">M_w</span>，其中 NVFP4 专家占 <span class=\"formula-inline\">f</span> 比例、FP8 回退专家占 <span class=\"formula-inline\">1−f</span>，则平均每参数位宽为 <span class=\"formula-inline\">b̄ = 4.5f + 8(1−f)</span>（4.5 含 scale 开销）。批大小 B 的上界由 <span class=\"formula-inline\">B ≤ (M_total − M_w − M_act) / (kv_per_token · L)</span> 给出，其中 kv_per_token 是每 token 每层 KV 字节数。误差界的作用是决定 f：f 越大，b̄ 越小，M_w 越小，B 上界越高；但 f 越大，路由翻转风险越高，SLO 里的“输出一致性”约束越难满足。于是批大小决策变成一个带精度约束的容量最大化问题——不是先定 B 再看精度，而是先由 R_e 分布定 f，再由 f 定 M_w，最后剩下多少显存给 KV 才决定 B。</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor\\frac{M_{\\text{total}}-M_{\\text{act}}-N\\cdot \\bar{b}}{L\\cdot \\text{kv}_{\\text{token}}}\\right\\rfloor,\\qquad \\bar{b}=4.5f+8(1-f)$$</div>\n<p>具体例子：某 MoE 模型单卡可用的权重预算是固定的，若全部专家走 NVFP4，b̄=4.5；把 20% 的重尾专家回退 FP8 后 b̄=5.2，权重显存上升约 15%，在 KV 预算不变的前提下 B_max 相应下降。这个下降必须与“回退后路由一致性提升带来的有效吞吐”对比：如果路由翻转导致的重复计算与重试吃掉了超过 15% 的吞吐，回退就是净亏。误差界在这里的角色是把“20%”这个比例从拍脑袋变成由 R_e 阈值筛出来的确定集合。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-24\">二十四 · 用误差界定并行度：专家切分与 TP/EP 的耦合</h3>\n<p>并行度决策中，误差界影响的是“切分粒度能否保持块内统计”。NVFP4 的 16 元素微块是沿权重矩阵的输入维切的；当专家并行（EP）把不同专家分到不同卡上时，每个专家内部的微块不受影响，误差界不变。但张量并行（TP）沿隐藏维切分同一个专家的权重矩阵时，若切分点落在微块内部，块内 max|w_i| 会因切分而改变——每个分片各自重新定 scale，块内动态范围比 R_e 在分片间不再一致，某些分片的有效位下降。工程上的做法是让 TP 切分对齐 16 元素微块边界，代价是隐藏维必须能被 16×TP 整除，这在小专家上会限制 TP 度。误差界给出的判据是：切分后若某分片的 R_e 超过阈值，则该分片需要单独回退 FP8，此时 TP 组内出现混合精度，集合通信的 all-reduce 要在不同位宽上做转换，NVLink 5 上的传输量按 FP8 计而非按 4 bit 计，带宽开销回升。</p>\n<div class=\"formula\">$$\\text{align}:\\ H \\bmod (16\\cdot P_{\\text{TP}})=0,\\qquad R_e^{(p)}=\\frac{\\max|w_i^{(p)}|}{\\operatorname{median}|w_i^{(p)}|}$$</div>\n<p>代价判断很直接：TP 度提高会缩小每卡上的专家权重分片，分片变小后单分片的微块数量减少，scale 开销占比上升（每 16 元素 1 字节的固定成本摊在更少元素上），等效位宽从 4.5 向 5 靠拢；同时分片内 R_e 的方差变大，混合精度回退的概率上升。因此误差界在这里的实际用途是给 TP 度设一个上限：不是通信带宽不够，而是切分到某个粒度后精度预算已经无法维持均匀，继续切只会让更多分片被迫回退 FP8，抵消并行带来的显存收益。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-25\">二十五 · 用误差界定 KV 预算与 SLO</h3>\n<p>KV 预算是权重显存之外的第二块蛋糕，误差界通过 f 间接决定它的大小。SLO 侧则要把误差界转成可观测指标：路由一致性。MoE 每层 top-k 路由由专家输出决定，权重误差经专家矩阵乘累积后改变 logits 排序，当两个专家的打分接近时发生翻转。误差界给出的是逐元素最坏情况，不能直接当端到端保证，因此 SLO 里必须挂一个验证回路：用固定校准集跑路由一致性（top-k 集合重合率）与 perplexity，把 R_e 阈值校准到“重合率不低于某条线”的位置。这个回路的成本是离线的一次性开销，但它决定了线上 f 的取值，进而决定 KV 预算。</p>\n<div class=\"formula\">$$\\text{SLO}:\\ \\Pr[\\text{top-}k\\ \\text{不变}]\\ge 1-\\delta,\\qquad \\delta=f(\\{R_e\\},\\ \\text{校准集})$$</div>\n<p>具体机制：把每个专家的 R_e 排序，从高到低逐个回退 FP8，每回退一个就重跑校准集的路由一致性，直到重合率越过阈值，得到的回退集合就是 f 的补集。这个过程把误差界从“公式”变成“排序键”——界本身不精确，但它的单调性可用：R_e 越大的专家回退后重合率提升越明显。代价是校准集的推理开销与显存：回退集合确定后，KV 预算按剩余显存分配，B_max 与最大上下文长度共同受挤压；若 SLO 要求长上下文，则 KV 每 token 占用高，B_max 下降，吞吐下降，此时唯一的杠杆是进一步压低 f 或改用更小的微块换精度——而后者又推高 scale 开销，形成闭环。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-26\">二十六 · 算例：一个专家集合的容量决策</h3>\n<p>设某 MoE 模型有 N 个专家，单卡权重预算固定，KV 每 token 每层占用固定字节，层数 L 已知。第一步，对每个专家统计其权重矩阵按 16 元素微块切分后的 R_e 分布，取块级 R_e 的中位数作为该专家的排序键。第二步，按 R_e 从高到低回退 FP8，每次回退后更新 b̄ 与 M_w，并跑校准集路由一致性。第三步，当重合率越过 SLO 阈值时停止，得到回退比例 1−f。第四步，用剩余显存算 B_max 与最大上下文。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>操作</th><th>显存/带宽代价</th><th>精度侧信号</th></tr></thead><tbody><tr><td>统计</td><td>逐专家算块级 R_e 中位数</td><td>离线一次，无线上开销</td><td>得到排序键，界变松的专家排前</td></tr><tr><td>回退</td><td>高 R_e 专家整块改 FP8</td><td>权重显存上升，b̄ 从 4.5 向 8 移动</td><td>路由重合率上升</td></tr><tr><td>定容</td><td>剩余显存分给 KV</td><td>B_max 与上下文长度受挤压</td><td>重合率达标后不再回退</td></tr><tr><td>上线</td><td>混合精度权重加载</td><td>反量化路径分两条，TMEM 写入带宽按 FP8 段计</td><td>持续监控路由翻转率</td></tr></tbody></table>\n<p>这个算例的关键判断是：回退不是免费的精度保险，它直接把 KV 预算换成权重显存。若 SLO 的瓶颈在长上下文而非路由一致性，则回退比例应压到最低，改用缩块或分组重排来局部压低 R_e，把省下的显存留给 KV；反之若瓶颈在输出漂移，则回退是唯一有效杠杆，B_max 的下降是可接受的代价。误差界在这里不提供绝对值，只提供排序与单调性——工程上够用，因为决策本来就是在一组离散选项里选，而不是解连续最优。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-27\">二十七 · 误用与工程判断</h3>\n<p>三种误用都直接打在容量决策上。其一，把逐元素最坏界当端到端保证，跳过 perplexity 与路由一致性验证，f 取满，上线后专家输出漂移、路由翻转，重试与重复计算吃掉吞吐，实际 goodput 低于回退方案。其二，忽略重尾下 scale 被离群点拉高，仍按均匀分布估 R_e，回退集合选错，量化后精度骤降，且因为界看起来“满足”而没有触发验证回路。其三，为压低误差盲目缩小微块，scale 存储与反量化开销上升，等效位宽从 4.5 升到 5 以上，W4A16 的显存收益被抵消，部署容量反而下降——这是把“块越小误差越小”的直觉直接套到容量上，忽略了 scale 是固定成本。</p>\n<p>正确的工程判断是把误差界当作一个带单调性的排序工具，而不是一个可验证的保证：用它筛出候选回退集合，用校准集的路由一致性定阈值，用 b̄ 与 KV 预算算 B_max，三者串成一条决策链。链上每一步都有明确的代价科目——权重显存、反量化带宽、KV 容量、路由翻转率——误差界只负责把“哪些专家值得花这笔钱”排出来。当某专家的 R_e 高到缩块也无法压回阈值时，整块保留 FP8 是唯一不破坏 SLO 的选择，此时容量决策让位于一致性决策，这是本部分给出的最硬的一条判断。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-28\">二十八 · 把误差界换算成容量：微块、离群点与 SLO 的三条约束</h3>\n\n<p>误差界真正进入容量决策时，不是作为一个“精度是否够”的布尔判断，而是作为一条<strong>逐专家的显存—带宽预算约束</strong>。做法是把界改写成对有效尾数的要求：给定该专家块内最大值 max|w|，若要求单元素绝对误差不超过 τ，则必须满足 max|w|/2<sup>m+1</sup> ≤ τ，即 m ≥ log₂(max|w|/τ) − 1。NVFP4 的 m 固定为 2（含隐含位共 3 位有效），于是这条不等式退化为对块内动态范围的约束：只有当 max|w| ≤ 8τ 时，16 元素微块才满足该专家的误差预算。工程上这意味着容量规划的第一步不是数权重，而是<strong>按专家逐个扫描块内最大值分布</strong>，把 max|w| 超过阈值的块标记为“需降级”，再据此决定该专家走 W4A16 还是保留 FP8。这一步的代价是离线校准：一次全专家权重扫描加下游 perplexity 与路由一致性验证，属于上线前的一次性开销，但它决定了后续所有批大小与并行度计算的分母。</p>\n\n<p>失效条件集中在两处，且都直接改变容量结论。其一是<strong>重尾</strong>：MoE 专家权重若存在少量大幅值元素，单块 E4M3 scale 被离群点拉高，块内其余 15 个元素的有效位随之下降，界从“紧”变“松”，此时按均匀分布估出的 τ 会系统性偏乐观，量化后路由翻转、专家输出漂移，表现为端到端吞吐看似达标而任务指标下滑——这正是把逐元素最坏界当作端到端保证的典型翻车路径。其二是<strong>盲目缩小微块</strong>：块从 16 元素降到更小确实收窄动态范围、压低界，但 scale 存储与反量化开销同步上升，W4A16 的显存收益被抵消，单卡可容纳的 KV 预算与批大小反而下降。判断准则很直接：缩小微块带来的显存节省必须大于 scale 元数据增量与反量化指令增量之和，否则容量决策应转向“对该专家保留 FP8”而非“全局缩块”。</p>\n\n<p>算例。设某 MoE 层有 E 个专家，每专家权重 W 字节，W4A16 下每 16 元素附一个 E4M3 scale（1 字节），故每专家权重的显存为 W/2 + W/16 字节，相对 FP16 的压缩比约为 16/9。若扫描发现比例为 p 的专家因块内 max|w| 过大而必须保留 FP8（每元素 1 字节，无微块 scale），则该层显存为 (1−p)·(W/2 + W/16) + p·W。批大小 B 由剩余显存除以每序列 KV 占用决定，而每序列 KV 占用又受 SLO 的 TPOT 约束：反量化在权重加载路径上增加带宽与指令开销，若该层权重流量占比高，则解码步的权重带宽时间上升，直接压缩可支撑的 B。于是容量决策写成一条链：先由误差界筛出 p，再由 p 定权重显存，再由剩余显存与带宽时间定 B 与并行度（TP/EP 切分需保证每卡专家集合内 p 的分布均衡，否则最慢卡决定 SLO），最后由 B 反推 KV 预算上限。任一环节把 p 估小，都会在 SLO 上以 TPOT 超时或路由一致性回退的形式暴露。</p>\n\n<table class=\"mini\"><thead><tr><th>决策变量</th><th>受误差界影响的方式</th><th>系统代价</th></tr></thead><tbody><tr><td>批大小 B</td><td>p 决定权重显存，剩余显存定 B 上限</td><td>显存；B 不足则吞吐下降</td></tr><tr><td>并行度 TP/EP</td><td>每卡专家集合的 p 需均衡</td><td>最慢卡决定 TPOT，SLO 收紧</td></tr><tr><td>KV 预算</td><td>权重显存挤占 KV 空间</td><td>上下文长度与并发数同时受限</td></tr><tr><td>微块粒度</td><td>缩小块降界但增 scale 开销</td><td>带宽与反量化指令上升</td></tr></tbody></table>\n<h3 id=\"th-nvfp4-moe-quant-error-sec-29\">二十九 · 误用一：把逐元素最坏界读成端到端精度承诺</h3>\n<p>最常见也最危险的误用，是把 <span class=\"formula-inline\">|w−ŵ| ≤ max|w_i|/2^m · 1/2</span> 这个逐元素最坏情况界，直接当成“这个专家在 W4A16 下精度没问题”的判据。这个界约束的是单个权重元素反量化后的偏差，它既不对误差在矩阵乘累加中的传播负责，也不对 MoE 路由器的输入分布负责。工程上真正决定输出漂移的是专家输出 <span class=\"formula-inline\">y = Wx</span> 上的累积误差：</p>\n<div class=\"formula\">$$\\big\\|\\,\\Delta y\\,\\big\\| \\;\\le\\; \\sum_{j}\\big|w_j-\\hat{w}_j\\big|\\cdot\\big|x_j\\big| \\;\\le\\; \\frac{1}{2^{m+1}}\\sum_{j}\\max_{i\\in b(j)}|w_i|\\cdot|x_j|$$</div>\n<p>注意右端出现了 <span class=\"formula-inline\">|x_j|</span>——激活的幅度。逐元素界里根本没有这一项，所以它无法回答“这个专家在真实 token 分布下会不会漂”。一个块内每个元素都恰好贴着上界、但激活在该维度上幅值很小的专家，端到端误差可以忽略；反过来，块内误差远小于上界、却恰好落在激活高幅值通道上的专家，输出漂移可能显著。跳过 perplexity 与路由一致性验证，等于用一个与激活无关的量去担保一个与激活强相关的量。</p>\n<p>识别方法很直接：检查量化评估流水线里是否存在“逐层权重误差统计”之外的环节。若只有权重重建误差（weight reconstruction error）报表，没有下游 perplexity、没有 top-k 路由一致性（同一 token 在量化前后选中的专家集合重合率），那这条流水线就是把最坏界当保证在用。代价体现在上线后的形态：专家输出漂移不会以“精度掉了几个点”的温和方式出现，而是以路由翻转的离散事件出现——某个 token 原本进专家 A，量化后改投专家 B，两条专家路径的表示空间不同，输出直接跳变。这类故障在离线权重误差报表上完全看不见。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-30\">三十 · 误用二：在重尾专家上沿用均匀分布假设</h3>\n<p>第二个误用是忽略 scale 被离群点拉高的效应。公式里 <span class=\"formula-inline\">s = max|w_i|/(2^m−1)</span> 用的是块内最大绝对值，这意味着一个 16 元素微块里只要有一个离群点，整块的量化格点间距就被它撑大，其余 15 个元素被迫在更粗的格点上舍入。此时它们的有效尾数不再是名义上的 m=2（含隐含位共 3 位有效），而是被压缩到更低位次。误差界本身没有错，但它对块内每个元素给出的都是同一个宽松上界，而实际分布是“一个元素误差很小、其余十五个误差被放大”。</p>\n<p>把这种情况定量化，可以定义块内有效位损失：设块内次大绝对值为 <span class=\"formula-inline\">|w|_(2)</span>，则非离群元素实际可用的相对精度约为</p>\n<div class=\"formula\">$$\\text{eff-bits}\\;\\approx\\; m-\\log_2\\!\\Big(\\frac{\\max|w_i|}{|w|_{(2)}}\\Big)$$</div>\n<p>当 <span class=\"formula-inline\">max/|w|_(2)</span> 达到 4 倍量级时，非离群元素就损失约 2 位有效精度，3 位有效退化成 1 位量级——这已经接近二值化的粗糙度。MoE 专家权重恰恰容易重尾：不同专家的输入分布差异大，某些专家在少数通道上承载了远高于其他的权重幅值。若仍按均匀分布估算“16 元素微块在所有专家上误差一致”，就会对这批重尾专家系统性低估误差。</p>\n<p>识别手段是分专家统计块内动态范围比值的分布，而不是只看全局平均。具体做法：对每个专家、每个 16 元素块计算 <span class=\"formula-inline\">\\(max|w_i| / \\mathrm{median}|w_i|\\)</span>，画出按专家的分位数。若某些专家的该比值显著高于其他专家，这些专家就是重尾受害者，其误差界名义上满足、实际上已松脱。系统代价是显存与带宽：为救这些专家而缩小微块或改分组，scale 数量按块数线性上升，W4A16 的 4 bit 权重收益被 scale 开销吃掉一部分，容量规划里原本算出的“每卡可多放几个专家”会缩水。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-31\">三十一 · 误用三：盲目缩小微块换精度</h3>\n<p>第三个误用是看到误差界变松就条件反射地缩小微块。块越小，块内动态范围越窄，<span class=\"formula-inline\">max|w_i|</span> 下降，界确实收紧；但 scale 是每块一个 E4M3，块数翻倍则 scale 存储翻倍，反量化时每元素的 scale 加载与乘法次数也翻倍。设权重元素数为 N、块大小为 B，则 scale 开销占比约为</p>\n<div class=\"formula\">$$\\text{scale-overhead}\\;\\approx\\;\\frac{8\\,\\text{bit}}{4\\,\\text{bit}\\cdot B}\\;=\\;\\frac{2}{B}$$</div>\n<p>B=16 时 scale 开销约为权重的 12.5%；B=8 时升到 25%；B=4 时升到 50%。这意味着把微块从 16 缩到 4，权重有效位宽从 4.5 bit 量级膨胀到 6 bit 量级，W4A16 的显存收益被大幅抵消。更关键的是反量化路径：解码阶段每个权重元素都要乘一次 scale，块越小，单位时间内要取的 scale 越多，这部分落在访存与 ALU 上，直接抬高解码延迟。在 MoE 解码本就受权重带宽约束的形态下，缩小微块是在用带宽换精度，而带宽正是瓶颈。</p>\n<p>识别方法：看容量决策表里是否同时记录了“微块大小”和“每卡专家驻留数”两列。若只调小前者、不同步重算后者，说明收益账没算全。正确做法是把缩小微块限定在经分专家统计确认的重尾专家上，其余专家维持 16 元素——分组策略按专家而非全局统一，代价是 kernel 需要支持混合块大小，实现复杂度上升，但避免了全局缩块带来的容量塌陷。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-32\">三十二 · 一个反例：路由翻转在权重误差报表上完全隐形</h3>\n<p>构造一个具体反例。某 MoE 层有 E 个专家，路由器对每个 token 取 top-2。取其中一个专家 A，其权重在 16 元素微块下逐元素误差全部满足上界，权重重建误差报表显示“全部块通过”。但专家 A 的权重在少数通道上重尾，块内 <span class=\"formula-inline\">max/|w|_(2)</span> 达 4 倍，非离群元素有效位退化到 1 位量级。同时，路由器打分对这些通道敏感——因为专家 A 的输出在这些通道上与专家 B 的输出差异构成路由决策的边界。</p>\n<p>量化后，专家 A 在这些通道上的输出漂移 <span class=\"formula-inline\">Δy</span> 使得原本 A 略优于 B 的 token 改为 B 略优，top-2 集合发生翻转。翻转的 token 进入专家 B，而 B 未在该 token 的表示子空间上训练充分，输出分布偏移。端到端表现为 perplexity 上升、生成内容局部失稳。整个链条中，权重误差报表全程绿灯：逐元素界满足、块通过、全局平均误差低。失效点在于报表度量的是权重空间，故障发生在路由空间。</p>\n<p>这个反例的工程含义是：验证必须双轨。权重侧看分专家块内动态范围分布，路由侧看量化前后 top-k 重合率与专家负载分布偏移。若重合率下降集中在少数专家，那正是重尾专家被 scale 拉高的信号，而不是“随机噪声”。代价上，路由翻转不是渐进的吞吐损失，而是离散的质量事故，修复它往往要回退到 FP8 保留这些专家，显存立刻上升——这正是容量规划里必须预留的余量。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-33\">三十三 · 识别清单与工程判断</h3>\n<p>把上述误用收敛成可执行的识别清单，每条对应一个可观测信号与一个系统代价：</p>\n<ul>\n<li>流水线只有权重重建误差、无 perplexity 与路由一致性——信号是评估脚本里缺少下游任务钩子；代价是上线后离散路由翻转，离线报表不可见。</li>\n<li>误差估算按全局平均而非分专家分位数——信号是统计表只有一层聚合；代价是重尾专家被系统性低估，W4A16 容量估算偏乐观。</li>\n<li>微块缩小未同步重算 scale 开销与专家驻留数——信号是容量表两列脱钩；代价是显存收益被 2/B 的 scale 占比抵消，解码带宽压力上升。</li>\n<li>把逐元素界当作单专家精度判据、不做激活幅度加权——信号是判据里没有 <span class=\"formula-inline\">|x_j|</span> 项；代价是高幅值通道上的误差被漏算。</li>\n</ul>\n<p>工程判断落在一条原则上：NVFP4 的误差界是筛选工具，不是担保工具。它的正确用法是在容量决策前做粗筛——块内动态范围比值超过阈值的专家直接标记为“需 FP8 保留或改分组”，其余专家进入 W4A16；粗筛之后必须用路由一致性做终审，因为只有路由空间能暴露激活相关的累积误差。把这两步顺序颠倒，或用权重报表替代终审，就是本部分列出的全部误用的共同根源。真正稳的部署不是误差界最小的部署，而是误差界与路由验证同时过关、且 scale 开销已计入容量账的部署。</p>\n\n<h3 id=\"th-nvfp4-moe-quant-error-sec-34\">三十四 · 误差界的三重误用：把上界当保证、把均匀当普遍、把缩块当解药</h3>\n<p>第一类误用是把逐元素最坏界当成端到端精度保证。界 \\(\\big|w-\\hat{w}\\big|\\le \\frac{\\max_{i\\in\\text{block}}|w_i|}{2^{m}}\\cdot\\frac{1}{2}\\) 描述的是单个权重在反量化后的最大偏差，它既不含误差在专家输出上的累积，也不含激活侧 W4A16 中 FP16/BF16 激活与量化权重相乘后的放大。工程上常见的动作是：离线抽几百个专家权重块，算出界值都小于某个阈值，就判定该 MoE 模型可在 W4A16 下上线，跳过 perplexity 与路由一致性验证。后果是上线后专家输出漂移，top-k 路由在相近 logit 上翻转，同一 token 被送进不同专家，输出分布出现不可复现的抖动。识别方法很直接：在验证集上同时记录路由一致性（同一 token 在量化前后的专家选择重合率）与 perplexity，两者任一出现阶跃式劣化，就说明界没有覆盖累积效应，此时应把该层专家退回 FP8 或缩小微块，而不是继续调界值阈值。</p>\n<p>第二类误用是忽略重尾分布下 scale 被离群点拉高的效应。NVFP4 每 16 个元素共享一个 E4M3 scale，\\(s=\\max|w_i|/(2^{m}-1)\\)，m=2、含隐含位共 3 位有效。只要块内出现一个幅值远高于其余 15 个元素的离群权重，scale 就被它钉死，其余元素落入的量化格点间距随之变大，有效尾数被压缩，界随之变松。误用者往往按均匀分布估算误差，认为 16 元素微块在所有专家上误差一致，实际却是少数重尾专家承担了绝大部分误差。识别方式是逐块统计块内最大值与次大值之比：比值大的块即为重尾块，应单独标记。对这类块，缩小微块、改分组方式或对该专家保留 FP8 都是可选手段，代价是显存占用与反量化开销上升——W4A16 的容量收益部分被抵消。</p>\n<p>第三类误用是把缩块当解药。块越小，块内动态范围越窄，界越紧，但 scale 存储与反量化开销同步上升：每 16 元素一个 E4M3 scale 已占额外位宽，缩到 8 元素或 4 元素时，scale 占比翻倍乃至数倍，反量化时读取 scale 的带宽与指令开销也随之增加。在显存与带宽本就紧张的 decode 阶段，这部分开销直接吃掉 W4A16 带来的容量与带宽收益，部署容量反而下降。判断依据是算一笔账：把 scale 开销折算进每权重平均位宽，若缩块后的平均位宽逼近 FP8，则缩块已无收益，应改用混合精度分组。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>失效机制</th><th>系统代价</th><th>识别信号</th></tr></thead><tbody><tr><td>界当端到端保证</td><td>未计专家输出累积与激活放大</td><td>路由翻转、输出抖动，重跑与回滚成本</td><td>路由一致性阶跃下降</td></tr><tr><td>按均匀分布估误差</td><td>离群点拉高 scale，其余元素有效位下降</td><td>少数重尾专家精度骤降</td><td>块内最大值/次大值比偏高</td></tr><tr><td>盲目缩小微块</td><td>scale 存储与反量化开销上升</td><td>显存与带宽收益被抵消，容量下降</td><td>每权重平均位宽逼近 FP8</td></tr></tbody></table>\n<p>一个具体反例：某 MoE 层中一个专家的权重块含一个幅值约为其余元素数十倍的离群权重，按 16 元素微块量化后，该块 scale 被离群点拉高，其余 15 个元素只剩不足 3 位有效精度，界值看似仍在阈值内，但该专家在长尾 token 上的输出已明显偏移，路由在这些 token 上频繁翻转。工程判断应落在：对重尾块单独保留 FP8 或改用更细分组，同时把路由一致性纳入上线门禁，而不是继续用逐元素界做容量决策。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>w</td><td>原始 FP16/BF16 权重元素</td></tr><tr><td>\\hat{w}</td><td>反量化后的权重元素</td></tr><tr><td>s</td><td>微块共享的 E4M3 scale</td></tr><tr><td>q</td><td>4 bit 量化整数码</td></tr><tr><td>m</td><td>尾数位宽（NVFP4 中 m=2，含隐含位共 3 位有效）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-nvfp4-moe-quant-error · 共 5 个片段</p>\n"}];})();
